// 自动生成：由 scripts/gen_grammar_n5.py 从《蓝宝书文法详解.docx》解析 N5，N4~N1 由旧脚本生成，请勿手改。
// 结构：levels[] -> units[] -> points[] -> blocks[]（furi 为开启振假名时的 ruby 版本）
export const grammarLevels = [{"id":"N5","name":"N5 文法详解（整理版）","units":[{"id":"N5-u1","title":"1单元 名词、指示词、数量词","points":[{"title":"1. 名词1+は+名词2+です/ではありません","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"此句型是名词谓语句的敬体形的现在时，表示对主语作出肯定或者否定的判断，相当于汉语的“～是～”或者“～不是～”。名词2是对名词1作出的解释或说明的具体内容。肯定形句末是「です」，否定形句末为「ではありません」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"これは去年買ったカメラです。【2007年真题】/这是去年买的照相机。","furi":"これは<ruby>去年<rp>(</rp><rt>きょねん</rt><rp>)</rp></ruby><ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ったカメラです。【2007年真题】/这是去年买的照相机。"},{"t":"line","text":"田中さんの来る日は火曜日です。【2007年真题】/田中要来的日子是周二。","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんの<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>は<ruby>火曜日<rp>(</rp><rt>かようび</rt><rp>)</rp></ruby>です。【2007年真题】/田中要来的日子是周二。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"在不造成误解的情况下，名词1可以省略。另外，「では」的口语形式为「じゃ」，因此「ではありません」也可以说成「じゃありません」。"},{"t":"line","text":"如：△妹は学生じゃありません。会社員です。/我妹妹不是学生。是公司职员。"}],"id":"N5-1"},{"title":"2. 名词1+は+名词2+でした/ではありませんでした","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"此句型是句型1的过去时。「です」的过去时是「でした」，「ではありません」的过去时是「ではありませんでした」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"おとといは雨で、昨日は雪でした。【2008年真题】/前天下雨，昨天下雪了。","furi":"おとといは<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>で、<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>は<ruby>雪<rp>(</rp><rt>ゆき</rt><rp>)</rp></ruby>でした。【2008年真题】/前天下雨，昨天下雪了。"},{"t":"line","text":"昔、ここは遊園地ではありませんでした。公園でした。/以前这里不是游乐场，是公园。","furi":"<ruby>昔<rp>(</rp><rt>むかし</rt><rp>)</rp></ruby>、ここは<ruby>遊園<rp>(</rp><rt>ゆうえん</rt><rp>)</rp></ruby><ruby>地<rp>(</rp><rt>ち</rt><rp>)</rp></ruby>ではありませんでした。<ruby>公園<rp>(</rp><rt>こうえん</rt><rp>)</rp></ruby>でした。/以前这里不是游乐场，是公园。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「ではありませんでした」口语中也可以说成「じゃありませんでした」。"}],"id":"N5-2"},{"title":"3. 名词1+は+名词2+だ/ではない","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"此句型是与句型1对应的普通体，「です」普通体为「だ」，「ではありません」普通体为「ではない」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"あれは日本語の教科書だ。/那是日语教科书。","furi":"あれは<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>教科書<rp>(</rp><rt>きょうかしょ</rt><rp>)</rp></ruby>だ。/那是日语教科书。"},{"t":"line","text":"林さんは上海人ではない。/小林不是上海人。","furi":"<ruby>林<rp>(</rp><rt>はやし</rt><rp>)</rp></ruby>さんは<ruby>上海<rp>(</rp><rt>しゃんはい</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>じん</rt><rp>)</rp></ruby>ではない。/小林不是上海人。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"此句型中「ではない」也可以说成「じゃない」。"}],"id":"N5-3"},{"title":"4. 名词1+は+名词2+だった/ではなかった","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"此句型是与句型2对应的普通体，是句型3对应的过去时。「だ」的过去时为「だった」，「ではない」的过去时为「ではなかった」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"3年前、あの人はこの会社の社長だった。/三年前，那个人是这家公司的经理。","furi":"3<ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby><ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>、あの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>はこの<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>の<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>だった。/三年前，那个人是这家公司的经理。"},{"t":"line","text":"それは夢ではなかった。/那不是做梦。","furi":"それは<ruby>夢<rp>(</rp><rt>ゆめ</rt><rp>)</rp></ruby>ではなかった。/那不是做梦。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「ではなかった」在口语中也可以说成「じゃなかった」。"}],"id":"N5-4"},{"title":"5. 名词1+は+名词2+ですか/でしたか","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"此句型是疑问句，相当于汉语的“～是～吗？”。肯定回答用「はい」起句，否定回答用「いいえ」起句。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"A「王さんのお母さんは昔、日本語の教師でしたか。」/“小王的妈妈以前是日语老师吗？”","furi":"A「<ruby>王<rp>(</rp><rt>おう</rt><rp>)</rp></ruby>さんのお<ruby>母<rp>(</rp><rt>かあ</rt><rp>)</rp></ruby>さんは<ruby>昔<rp>(</rp><rt>むかし</rt><rp>)</rp></ruby>、<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>教師<rp>(</rp><rt>きょうし</rt><rp>)</rp></ruby>でしたか。」/“小王的妈妈以前是日语老师吗？”"},{"t":"line","text":"B「はい、そうでした。」/“是，以前是的。”"},{"t":"line","text":"A「あの人は田中さんですか。」/“那个人是田中先生吗？”","furi":"A「あの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>は<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんですか。」/“那个人是田中先生吗？”"},{"t":"line","text":"B「いいえ、違います。田中さんです。」/“不，不是。那是田中。”","furi":"B「いいえ、<ruby>違<rp>(</rp><rt>ちが</rt><rp>)</rp></ruby>います。<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんです。」/“不，不是。那是田中。”"},{"t":"label","label":"注意","text":""},{"t":"line","text":"日语疑问句的特征之一是句末一般不用问号，而用句号。"}],"id":"N5-5"},{"title":"6. 名词1+は+名词2+で、名词3です","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"「で」用来连接两个内容相关的名词句。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"あの人は歌手で、アナウンサーです。/那个人是歌手，也是播音员。","furi":"あの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>は<ruby>歌手<rp>(</rp><rt>かしゅ</rt><rp>)</rp></ruby>で、アナウンサーです。/那个人是歌手，也是播音员。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"前后两个短句的主语是一致的，前句用名词谓语形式结句。"}],"id":"N5-6"},{"title":"7. これ、それ、あれ、どれ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"指示事物的指示词。"},{"t":"line","text":"「これ」，“这个”，近称，指离说话人近的东西或事物。"},{"t":"line","text":"「それ」，“那个”，中称，指离听话人近的东西或事物。"},{"t":"line","text":"「あれ」，“那个”，远称，指离听话人和说话人都比较远的东西或事物。"},{"t":"line","text":"「どれ」，“哪一个”，不定称，指说话人不知道或不明确的东西和事物。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"駅の近くの店でこれを買いました。【2007年真题】/在车站附近的店里买了这个。","furi":"<ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>の<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>くの<ruby>店<rp>(</rp><rt>みせ</rt><rp>)</rp></ruby>でこれを<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いました。【2007年真题】/在车站附近的店里买了这个。"},{"t":"line","text":"これは日本語の辞書で、あれは英語の辞書です。【2001年真题】/这本是日语词典，那本是英语词典。","furi":"これは<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>で、あれは<ruby>英語<rp>(</rp><rt>えいご</rt><rp>)</rp></ruby>の<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>です。【2001年真题】/这本是日语词典，那本是英语词典。"},{"t":"line","text":"A「これは去年買ったカメラです。撮った写真はきれいですよ。」/“这是我去年买的相机，拍出来的相片不错呢。”","furi":"A「これは<ruby>去年<rp>(</rp><rt>きょねん</rt><rp>)</rp></ruby><ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ったカメラです。<ruby>撮<rp>(</rp><rt>と</rt><rp>)</rp></ruby>った<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>はきれいですよ。」/“这是我去年买的相机，拍出来的相片不错呢。”"},{"t":"line","text":"B「そうですか。今度一緒に遊びに行くとき、それを持って行ってね。」/“这样啊，下次一起去玩的时候，要带上它啊。”","furi":"B「そうですか。<ruby>今度<rp>(</rp><rt>こんど</rt><rp>)</rp></ruby><ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>びに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くとき、それを<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>って<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってね。」/“这样啊，下次一起去玩的时候，要带上它啊。”"},{"t":"line","text":"日本で一番有名な山はどれですか。/在日本，最有名的山是哪一座？","furi":"<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>で<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby><ruby>有名<rp>(</rp><rt>ゆうめい</rt><rp>)</rp></ruby>な<ruby>山<rp>(</rp><rt>やま</rt><rp>)</rp></ruby>はどれですか。/在日本，最有名的山是哪一座？"}],"id":"N5-7"},{"title":"8. この、その、あの、どの","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"这四个词均为连体词，后续名词可指定物品或事物。"},{"t":"line","text":"「この+名词」，“这个……”，近称，指离说话人近的物品或事物。"},{"t":"line","text":"「その+名词」，“那个……”，中称，指离听话人近的物品或事物。"},{"t":"line","text":"「あの+名词」，“那个……”，远称，指离听话人和说话人都比较远的物品或事物。"},{"t":"line","text":"「どの+名词」，“哪一个……”，不定称，指说话人不知道或不明确的物品或事物。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"この雑誌を見てもいいですか。【2009年真题】/我可以看这本杂志吗？","furi":"この<ruby>雑誌<rp>(</rp><rt>ざっし</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>てもいいですか。【2009年真题】/我可以看这本杂志吗？"},{"t":"line","text":"あの部屋が日本語の教室です。【2007年真题】/那间房间是日语教室。","furi":"あの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>が<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>教室<rp>(</rp><rt>きょうしつ</rt><rp>)</rp></ruby>です。【2007年真题】/那间房间是日语教室。"},{"t":"line","text":"どの人が山下さんですか。【2006年真题】/哪位是山下先生（小姐）？","furi":"どの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>山下<rp>(</rp><rt>やました</rt><rp>)</rp></ruby>さんですか。【2006年真题】/哪位是山下先生（小姐）？"},{"t":"line","text":"その大きい荷物はわたしのです。【2005年真题】/那件大行李是我的。","furi":"その<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きい<ruby>荷物<rp>(</rp><rt>にもつ</rt><rp>)</rp></ruby>はわたしのです。【2005年真题】/那件大行李是我的。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"连体词必须后续名词才能构成独立的句子成分。"}],"id":"N5-8"},{"title":"9. ここ、そこ、あそこ、どこ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"这一组词用来指示位置、场所。"},{"t":"line","text":"「ここ」，“这儿、这里”，近称，指离说话人近的位置、场所。"},{"t":"line","text":"「そこ」，“那儿、那里”，中称，指离听话人近的位置、场所。"},{"t":"line","text":"「あそこ」，“那儿、那里”，远称，指离听话人、说话人都有距离的位置、场所。"},{"t":"line","text":"「どこ」，“哪里、哪儿”，不定称，指说话人不知道或不明确的位置、场所等。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"遊びに行きましょう。どこがいいですか。【2009年真题】/（我们）出去玩吧，（去）哪里比较好呢？","furi":"<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>びに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きましょう。どこがいいですか。【2009年真题】/（我们）出去玩吧，（去）哪里比较好呢？"},{"t":"line","text":"ここで写真を撮ってもいいですか。【2008年真题】/可以在这儿拍照吗？","furi":"ここで<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>を<ruby>撮<rp>(</rp><rt>と</rt><rp>)</rp></ruby>ってもいいですか。【2008年真题】/可以在这儿拍照吗？"},{"t":"line","text":"あそこに女の人がいますね。【2008年真题】/那边有一个女子吧。","furi":"あそこに<ruby>女<rp>(</rp><rt>おんな</rt><rp>)</rp></ruby>の<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>がいますね。【2008年真题】/那边有一个女子吧。"},{"t":"line","text":"そこの机にボールペンが置いてあります。【2000年真题】/那边书桌上放着一支圆珠笔。","furi":"そこの<ruby>机<rp>(</rp><rt>つくえ</rt><rp>)</rp></ruby>にボールペンが<ruby>置<rp>(</rp><rt>お</rt><rp>)</rp></ruby>いてあります。【2000年真题】/那边书桌上放着一支圆珠笔。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"可以用「～はどこですか」的形式提问，回答时可以用「～はここ/そこ/あそこです」的形式。"}],"id":"N5-9"},{"title":"10. こう、そう、ああ、どう","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"表示方式，方法。"},{"t":"line","text":"「こう+动词」，“这样……、如此……”，用于与说话人相关的事情。"},{"t":"line","text":"「そう+动词」，“那样……”，用于与听话人相关的事情。"},{"t":"line","text":"「ああ+动词」，“那样……”，用于谈论存在于谈话双方认知范围内的事情。"},{"t":"line","text":"「どう+动词」，“怎样……”，用于询问做事的方式。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"このゲームはこうやって遊びますよ。【2007年真题】/这个游戏是这样玩的。","furi":"このゲームはこうやって<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>びますよ。【2007年真题】/这个游戏是这样玩的。"},{"t":"line","text":"これからどうするのかゆっくり考えなさい。【2000年真题】/好好考虑一下今后应该怎么办。","furi":"これからどうするのかゆっくり<ruby>考<rp>(</rp><rt>かんが</rt><rp>)</rp></ruby>えなさい。【2000年真题】/好好考虑一下今后应该怎么办。"},{"t":"line","text":"ああいうタイプの人があまり好きではありません。/我不太喜欢那样的人。","furi":"ああいうタイプの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>があまり<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きではありません。/我不太喜欢那样的人。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「そう」除了上述用法外，后续否定时，可以译为“（不）那么……”，如「この服はそう高くはありません。（这件衣服没那么贵。）」。「こう/ああ」均无此用法。"}],"id":"N5-10"},{"title":"11. こちら、そちら、あちら、どちら","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"可以和「これ、それ、あれ、どれ」一样指示物品；也可以和「ここ、そこ、あそこ、どこ」一样指示场所；还可以用来指示人物、公司、商店等，是较为礼貌的表达方式。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"先生の部屋はこちらです。【2002年真题】/老师的房间在这里。","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>の<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>はこちらです。【2002年真题】/老师的房间在这里。"},{"t":"line","text":"今からあなたのうちへ行きますが、そちらまでどれぐらいかかりますか。【2001年真题】/现在我去您家，到那儿大概要花多长时间？","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>からあなたのうちへ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きますが、そちらまでどれぐらいかかりますか。【2001年真题】/现在我去您家，到那儿大概要花多长时间？"},{"t":"line","text":"あちらはどちらさまですか。/那位是谁啊？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「こちら、そちら、あちら、どちら」在口语可以说成「こっち、そっち、あっち、どっち」，表达较为随意，敬意程度稍轻。"}],"id":"N5-11"},{"title":"12. こんな、そんな、あんな、どんな","blocks":[{"t":"label","label":"接续①","text":""},{"t":"line","text":"こんな、そんな、あんな、どんな+名词","furi":"こんな、そんな、あんな、どんな+<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"表示从某一类事物中选择其中之一，意思是“这种……，那种……，哪种……”。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"そんな人と付き合いたくない。/不想和那种人交往。","furi":"そんな<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>と<ruby>付<rp>(</rp><rt>つ</rt><rp>)</rp></ruby>き<ruby>合<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>いたくない。/不想和那种人交往。"},{"t":"line","text":"どんな音楽を聞きますか。【2003年真题】/你听什么类型的音乐？","furi":"どんな<ruby>音楽<rp>(</rp><rt>おんがく</rt><rp>)</rp></ruby>を<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>きますか。【2003年真题】/你听什么类型的音乐？"},{"t":"label","label":"接续②","text":""},{"t":"line","text":"こんな、そんな、あんな、どんな+形容词/名词","furi":"こんな、そんな、あんな、どんな+<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/名词"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"用来指代某人或者某物的性质和状态，意思是“这样的……，那样的……，怎样的……”。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"こんな馬鹿なことは二度としません。/再也不会做这种蠢事。","furi":"こんな<ruby>馬鹿<rp>(</rp><rt>ばか</rt><rp>)</rp></ruby>なことは<ruby>二度<rp>(</rp><rt>にど</rt><rp>)</rp></ruby>としません。/再也不会做这种蠢事。"},{"t":"line","text":"あんないいこともありますか。/有那样的好事吗？"}],"id":"N5-12"},{"title":"13. 基数词","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"基数词是单纯用以计数的数词，表示事物的具体数量。十一以下的基数词的读法有音读和训读两种，十一以上采取音读。"},{"t":"label","label":"读法","text":""},{"t":"sub","text":"① 十一以下的训读"},{"t":"table","headers":["ひらがな","汉字","数字"],"rows":[["ひとつ","一つ","1"],["ふたつ","二つ","2"],["みっつ","三つ","3"],["よっつ","四つ","4"],["いつつ","五つ","5"],["むっつ","六つ","6"],["ななつ","七つ","7"],["やっつ","八つ","8"],["ここのつ","九つ","9"],["とお","十","10"]]},{"t":"sub","text":"② 一百之内的数字的音读"},{"t":"table","headers":["数字","音读","数字","音读","数字","音读"],"rows":[["1","いち","11","じゅういち","30","さんじゅう"],["2","に","12","じゅうに","40","よんじゅう"],["3","さん","13","じゅうさん","50","ごじゅう"],["4","し/よん","14","じゅうよん","60","ろくじゅう"],["5","ご","15","じゅうご","70","ななじゅう"],["6","ろく","16","じゅうろく","80","はちじゅう"],["7","しち/なな","17","じゅうしち/じゅうなな","90","きゅうじゅう"],["8","はち","18","じゅうはち","100","ひゃく"],["9","く/きゅう","19","じゅうく/じゅうきゅう","0","れい/ぜろ"],["10","じゅう","20","にじゅう","0.1","れいてんいち"],["2/3","さんぶんのに","4%","よんパーセント","100%","ひゃくパーセント"]]},{"t":"sub","text":"③ 一百以上的数字的音读"},{"t":"table","headers":["数字","音读","数字","音读","数字","音读"],"rows":[["101","ひゃくいち","1,000","せん","10,000","いちまん"],["200","にひゃく","2,000","にせん","100,000","じゅうまん"],["300","さんびゃく","3,000","さんぜん","1,000,000","ひゃくまん"],["400","よんひゃく","4,000","よんせん","10,000,000","いっせんまん"],["500","ごひゃく","5,000","ごせん","100,000,000","いちおく"],["600","ろっぴゃく","6,000","ろくせん","1,050","せんごじゅう"],["700","ななひゃく","7,000","ななせん","2,005","にせんご"],["800","はっぴゃく","8,000","はっせん","2,055","にせんごじゅうご"],["900","きゅうひゃく","9,000","きゅうせん","2,500","にせんごひゃく"]]}],"id":"N5-13"},{"title":"14. 序数词","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"序数词是表示事物顺序的数词。序数词一般由基数词前加表示顺序的接头词「第」等，或其后加表示顺序的接尾词「番」、「目」等构成。"},{"t":"label","label":"读法","text":""},{"t":"line","text":"第一（だいいち）","furi":"<ruby>第<rp>(</rp><rt>だい</rt><rp>)</rp></ruby><ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby>（だいいち）"},{"t":"line","text":"第二（だいに）","furi":"<ruby>第<rp>(</rp><rt>だい</rt><rp>)</rp></ruby><ruby>二<rp>(</rp><rt>に</rt><rp>)</rp></ruby>（だいに）"},{"t":"line","text":"第三（だいさん）","furi":"<ruby>第<rp>(</rp><rt>だい</rt><rp>)</rp></ruby><ruby>三<rp>(</rp><rt>さん</rt><rp>)</rp></ruby>（だいさん）"},{"t":"line","text":"第3回（だいさんかい）","furi":"<ruby>第<rp>(</rp><rt>だい</rt><rp>)</rp></ruby>3<ruby>回<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>（だいさんかい）"},{"t":"line","text":"1番（いちばん）","furi":"1<ruby>番<rp>(</rp><rt>ばん</rt><rp>)</rp></ruby>（いちばん）"},{"t":"line","text":"2番（にばん）","furi":"2<ruby>番<rp>(</rp><rt>ばん</rt><rp>)</rp></ruby>（にばん）"},{"t":"line","text":"第5行（だいごぎょう）","furi":"<ruby>第<rp>(</rp><rt>だい</rt><rp>)</rp></ruby>5<ruby>行<rp>(</rp><rt>こう</rt><rp>)</rp></ruby>（だいごぎょう）"}],"id":"N5-14"},{"title":"15. 常用助数词","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"助数词是表示事物计量名称的数词，也就是中文中通常所称的量词。基数词一般借助于助数词，才能准确地表达事物的数量。"},{"t":"label","label":"读法","text":""},{"t":"sub","text":"① 基数词与助数词结合的读法"},{"t":"table","headers":["数字","～個","～枚","～本","～冊","～匹","～円","～歳","～番"],"rows":[["何","なんこ","なんまい","なんほん","なんさつ","なんびき","なんえん/いくら","なんさい","なんばん"],["1","いっこ","いちまい","いっぽん","いっさつ","いっぴき","いちえん","いっさい","いちばん"],["2","にこ","にまい","にほん","にさつ","にひき","にえん","にさい","にばん"],["3","さんこ","さんまい","さんぼん","さんさつ","さんびき","さんえん","さんさい","さんばん"],["4","よんこ","よんまい","よんほん","よんさつ","よんひき","よえん","よんさい","よんばん"],["5","ごこ","ごまい","ごほん","ごさつ","ごひき","ごえん","ごさい","ごばん"],["6","ろっこ","ろくまい","ろっぽん","ろくさつ","ろっぴき","ろくえん","ろくさい","ろくばん"],["7","ななこ","ななまい","ななほん","ななさつ","ななひき","ななえん","ななさい","ななばん"],["8","はっこ","はちまい","はっぽん","はっさつ","はっぴき","はちえん","はっさい","はちばん"],["9","きゅうこ","きゅうまい","きゅうほん","きゅうさつ","きゅうひき","きゅうえん","きゅうさい","きゅうばん"],["10","じゅっこ","じゅうまい","じゅっぽん","じゅっさつ","じゅっぴき","じゅうえん","じゅっさい","じゅうばん"]]},{"t":"sub","text":"② 常用助数词表"},{"t":"table","headers":["助数词","读音","用途"],"rows":[["課（か）","か","课，科；课程，行政科室"],["階（かい）","かい","层；楼房层数"],["回（かい）","かい","回，次；次数，回数，顺序"],["級（きゅう）","きゅう","级；级别，等级"],["個（こ）","こ","个；方的、圆的等成形的物品"],["冊（さつ）","さつ","册，本；书籍或成册纸制品"],["章（しょう）","しょう","章节；文章章节"],["重（じゅう）","じゅう","层，重；重叠数量"],["畳（じょう）","じょう","张，块；日本席子，表示房间面积"],["世代（せだい）","せだい","代；家庭，家族"],["足（そく）","そく","双，对；成双的物品，如手套、鞋袜等"],["台（だい）","だい","台，辆，架；机器、车辆等"],["通（つう）","つう","封，件；信函、文书"],["人（にん）","にん","人；人数"],["杯（はい）","はい","杯、碗；杯碗等器皿"],["箱（はこ）","はこ","箱；成箱的东西"],["番（ばん）","ばん","第……，……号；顺序，序列"],["番地（ばんち）","ばんち","……号；街道编号，地域号码，地址编码"],["番目（ばんめ）","ばんめ","第……个；序数号"],["匹（ひき）","ひき","匹，只；鱼、虫、鸟等小型动物"],["頁（ページ）","ページ","页；页数"],["本（ほん）","ほん","只，根，条，瓶；细长的物品，如笔、树、绳等"],["枚（まい）","まい","张，片，块，件；薄的扁平物体"],["目（め）","め","第……；顺序"],["名（めい）","めい","……名；人数"],["羽（わ）","わ","只；鸟类、家禽等"]]}],"id":"N5-15"},{"title":"16. 常用数量的读法","blocks":[{"t":"label","label":"读法","text":""},{"t":"sub","text":"① 人数的读法"},{"t":"table","headers":["人数","读法"],"rows":[["一人","ひとり"],["二人","ふたり"],["三人","さんにん"],["四人","よにん"],["五人","ごにん"],["六人","ろくにん"],["七人","しちにん/ななにん"],["八人","はちにん"],["九人","きゅうにん"],["十人","じゅうにん"],["十一人","じゅういちにん"],["十二人","じゅうににん"],["十三人","じゅうさんにん"]]},{"t":"sub","text":"② 月份的读法"},{"t":"table","headers":["月份","读法"],"rows":[["一月","いちがつ"],["二月","にがつ"],["三月","さんがつ"],["四月","しがつ"],["五月","ごがつ"],["六月","ろくがつ"],["七月","しちがつ"],["八月","はちがつ"],["九月","くがつ"],["十月","じゅうがつ"],["十一月","じゅういちがつ"],["十二月","じゅうにがつ"]]},{"t":"sub","text":"③ 月数的读法"},{"t":"table","headers":["月数","读法"],"rows":[["一か月","いっかげつ"],["二か月","にかげつ"],["三か月","さんかげつ"],["四か月","よんかげつ"],["五か月","ごかげつ"],["六か月","ろっかげつ"],["七か月","ななかげつ/しちかげつ"],["八か月","はっかげつ"],["九か月","きゅうかげつ"],["十か月","じゅっかげつ"],["十一か月","じゅういっかげつ"],["十二か月","じゅうにかげつ"]]},{"t":"sub","text":"④ 日期的读法"},{"t":"table","headers":["日期","读法"],"rows":[["1日","ついたち"],["2日","ふつか"],["3日","みっか"],["4日","よっか"],["5日","いつか"],["6日","むいか"],["7日","なのか"],["8日","ようか"],["9日","ここのか"],["10日","とおか"],["11日","じゅういちにち"],["12日","じゅうににち"],["13日","じゅうさんにち"],["14日","じゅうよっか"],["15日","じゅうごにち"],["16日","じゅうろくにち"],["17日","じゅうしちにち"],["18日","じゅうはちにち"],["19日","じゅうくにち"],["20日","はつか"],["21日","にじゅういちにち"],["22日","にじゅうににち"],["23日","にじゅうさんにち"],["24日","にじゅうよっか"],["25日","にじゅうごにち"],["26日","にじゅうろくにち"],["27日","にじゅうしちにち"],["28日","にじゅうはちにち"],["29日","にじゅうくにち"],["30日","さんじゅうにち"],["31日","さんじゅういちにち"]]},{"t":"sub","text":"⑤ 天数的读法"},{"t":"table","headers":["天数","读法"],"rows":[["1日間","いちにちかん"],["2日間","ふつかかん"],["3日間","みっかかん"],["4日間","よっかかん"],["5日間","いつかかん"],["6日間","むいかかん"],["7日間","なのかかん"],["8日間","ようかかん"],["9日間","ここのかかん"],["10日間","とおかかん"],["11日間","じゅういちにちかん"],["12日間","じゅうににちかん"],["20日間","はつかかん"],["21日間","にじゅういちにちかん"],["30日間","さんじゅうにちかん"],["31日間","さんじゅういちにちかん"],["何日間","なんにちかん"]]},{"t":"sub","text":"⑥ 时间的读法"},{"t":"table","headers":["时间","读法"],"rows":[["1時","いちじ"],["2時","にじ"],["3時","さんじ"],["4時","よじ"],["5時","ごじ"],["6時","ろくじ"],["7時","しちじ"],["8時","はちじ"],["9時","くじ"],["10時","じゅうじ"],["11時","じゅういちじ"],["12時","じゅうにじ"],["何時","なんじ"]]},{"t":"table","headers":["分钟","读法"],"rows":[["1分","いっぷん"],["2分","にふん"],["3分","さんぷん"],["4分","よんぷん"],["5分","ごふん"],["6分","ろっぷん"],["7分","ななふん"],["8分","はっぷん"],["9分","きゅうふん"],["10分","じゅっぷん"],["11分","じゅういっぷん"],["15分","じゅうごふん"],["何分","なんぷん"]]}],"id":"N5-16"}]},{"id":"N5-u2","title":"2单元 动词","points":[{"title":"17. 三类动词的区分","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"根据动词词尾的活用变形，可以把动词分为 I类动词（五段动词）、II类动词（一段动词）、III类动词（サ变动词/カ变动词）三种类型。"},{"t":"line","text":"I类动词，词尾是「う、く、ぐ、す、つ、ぬ、ぶ、む、る」，且倒数第二个假名一般是「あ、う、お」段假名。"},{"t":"line","text":"II类动词，词尾必须为「る」，且倒数第二个假名要在「い」段或「え」段上。"},{"t":"line","text":"III类动词，包括サ变动词和カ变动词。サ变动词一般指「する」，但「する」可与一些动词性名词一起构成サ变复合词，我们把这些词也称作サ变动词。カ变动词只有一个，即「来る」，其活用变形要特殊记忆。"},{"t":"label","label":"例词","text":""},{"t":"sub","text":"① I类动词"},{"t":"line","text":"買う・行く・急ぐ・押す・立つ・死ぬ・飛ぶ・読む・撮る","furi":"<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>う・<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く・<ruby>急<rp>(</rp><rt>いそ</rt><rp>)</rp></ruby>ぐ・<ruby>押<rp>(</rp><rt>お</rt><rp>)</rp></ruby>す・<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>つ・<ruby>死<rp>(</rp><rt>し</rt><rp>)</rp></ruby>ぬ・<ruby>飛<rp>(</rp><rt>と</rt><rp>)</rp></ruby>ぶ・<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>む・<ruby>撮<rp>(</rp><rt>と</rt><rp>)</rp></ruby>る"},{"t":"sub","text":"② II类动词"},{"t":"line","text":"起きる・食べる・見る・寝る","furi":"<ruby>起<rp>(</rp><rt>お</rt><rp>)</rp></ruby>きる・<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる・<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>る・<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>る"},{"t":"sub","text":"③ III类动词"},{"t":"line","text":"サ变动词：する・運動する・勉強する……","furi":"サ<ruby>变<rp>(</rp><rt>变</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>：する・<ruby>運動<rp>(</rp><rt>うんどう</rt><rp>)</rp></ruby>する・<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>する……"},{"t":"line","text":"カ变动词：来る","furi":"カ<ruby>变<rp>(</rp><rt>变</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>：<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る"},{"t":"label","label":"注意","text":""},{"t":"line","text":"日语中有些动词满足以上II类动词的规则，却是I类动词，这些词语需要我们特别记忆。如「焦る・要る・入る・帰る・返る・限る・切る・蹴る・茂る・知る・喋る・滑る・散る・走る・減る」等。"}],"id":"N5-17"},{"title":"18. 自动词和他动词","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"根据动词是否需要宾语，日语动词又可以分为自动词和他动词。自动词表示自发的不掺杂主观意图的动作、行为，一般情况下格助词要用「が」；他动词需要宾语才能完整地表达主语的动作或作用，格助词要用「を」。有一些动词既可作自动词又可作他动词。"},{"t":"label","label":"例词","text":""},{"t":"sub","text":"① 没有对应他动词的自动词"},{"t":"line","text":"ある・いる・行く・来る","furi":"ある・いる・<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く・<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る"},{"t":"sub","text":"② 没有对应自动词的他动词"},{"t":"line","text":"話す・読む・書く・飲む","furi":"<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>す・<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>む・<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>く・<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>む"},{"t":"sub","text":"③ 既可以作自动词又可以作他动词的单词"},{"t":"line","text":"開く・休む・吹く・笑う・終わる","furi":"<ruby>開<rp>(</rp><rt>ひら</rt><rp>)</rp></ruby>く・<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>む・<ruby>吹<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>く・<ruby>笑<rp>(</rp><rt>わら</rt><rp>)</rp></ruby>う・<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わる"},{"t":"sub","text":"④ 常见的自动词和他动词对应表"},{"t":"table","headers":["自动词","他动词","自动词","他动词"],"rows":[["上がる","上げる","開く","開ける"],["暖まる","暖める","集まる","集める"],["現れる","現す","痛む","痛める"],["動く","動かす","起きる","起こす"],["落ちる","落とす","終わる","終える"],["かかる","かける","消える","消す"],["下がる","下げる","裂ける","裂く"],["建つ","建てる","付く","付ける"],["積もる","積む","届く","届ける"],["直る","直す","鳴る","鳴らす"],["並ぶ","並べる","始まる","始める"],["広まる","広める","減る","減らす"],["見える","見る","見つかる","見つける"]]}],"id":"N5-18"},{"title":"19. 动词「ます形」及敬体形","blocks":[{"t":"label","label":"动词「ます形」变形规则","text":""},{"t":"line","text":"I类动词，把词尾的「う」段假名变为同行「い」段假名之后接「ます」。"},{"t":"line","text":"II类动词，把词尾「る」去掉之后接「ます」。"},{"t":"line","text":"III类动词，「（～）する」变为「（～）し」，之后接「ます」；「来（く）る」变为「来（き）」之后接「ます」。"},{"t":"table","headers":["动词种类","辞书形","变形规则","ます形"],"rows":[["I类动词","言う・行く・注ぐ・押す・立つ・死ぬ・飛ぶ・住む・鳴る・切る・帰る","词尾的「う」段假名变为同行「い」段假名之后接「ます」","言います・行きます・注ぎます・押します・立ちます・死にます・飛びます・住みます・鳴ります・切ります・帰ります"],["II类动词","見る・食べる","词尾「る」去掉之后接「ます」","見ます・食べます"],["III类动词","する・運動する・来る","「（～）する」变为「（～）し」，之后接「ます」；「来る」变为「き」，之后接「ます」","します・運動します・来（き）ます"]]},{"t":"label","label":"说明","text":""},{"t":"line","text":"动词后面加「ます」为礼貌用语。一般和认识不久的人或者长辈、上司等说话时，要用敬体形。「ます」对应的过去时为「ました」，否定形为「ません」，过去否定形为「ませんでした」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"朝シャワーを浴びました。【2009年真题】/今早洗了澡。","furi":"<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>シャワーを<ruby>浴<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>びました。【2009年真题】/今早洗了澡。"},{"t":"line","text":"昨日誰と一緒に帰りましたか。【2008年真题】/昨天和谁一起回去的？","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby><ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>と<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>りましたか。【2008年真题】/昨天和谁一起回去的？"},{"t":"line","text":"わたしはおじいさんとよく散歩をします。【2006年真题】/我经常和爷爷一起散步。","furi":"わたしはおじいさんとよく<ruby>散歩<rp>(</rp><rt>さんぽ</rt><rp>)</rp></ruby>をします。【2006年真题】/我经常和爷爷一起散步。"},{"t":"line","text":"30分ぐらい待ちましたが、バスは来ませんでした。【2003年真题】/等了大概三十分钟，公交车也没来。","furi":"30<ruby>分<rp>(</rp><rt>ふん</rt><rp>)</rp></ruby>ぐらい<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ちましたが、バスは<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ませんでした。【2003年真题】/等了大概三十分钟，公交车也没来。"}],"id":"N5-19"},{"title":"20. 动词「て形」","blocks":[{"t":"label","label":"动词「て形」变形规则","text":""},{"t":"table","headers":["动词种类","辞书形","变形规则","动词「て形」"],"rows":[["I类动词","言う・立つ・鳴る","促音变，词尾「う、つ、る」变为「っ」，再接「て」","言って・立って・鳴って"],["I类动词","住む・死ぬ・飛ぶ","拨音变，词尾「む、ぬ、ぶ」变为「ん」，再接「で」","住んで・死んで・飛んで"],["I类动词","書く・注ぐ・行く","い音变，词尾「く」变为「い」，再接「て」；词尾「ぐ」变成「い」，再接「で」；「行く」特殊为「行って」","書いて・注いで・行って"],["I类动词","押す","词尾「す」变为「し」，再接「て」","押して"],["II类动词","見る・食べる","词尾「る」去掉之后接「て」","見て・食べて"],["III类动词","する・運動する・来る","「（～）する」变为「（～）し」，之后接「て」；「来る」变为「き」，之后接「て」","して・運動して・来（き）て"]]},{"t":"label","label":"注意","text":""},{"t":"line","text":"「行く」这个词的「て形」比较特别，是「行って」，而不是「行いて」。"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"表示动作或状态同时进行。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"辞書を見て漢字を覚えます。【2000年真题】/看着词典背汉字。","furi":"<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>て<ruby>漢字<rp>(</rp><rt>かんじ</rt><rp>)</rp></ruby>を<ruby>覚<rp>(</rp><rt>おぼ</rt><rp>)</rp></ruby>えます。【2000年真题】/看着词典背汉字。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"表示动作或行为相继发生。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"昨日の夜は6時に帰って、ご飯を作りました。【2003年真题】/昨晚六点回家，然后做了饭。","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>の<ruby>夜<rp>(</rp><rt>よる</rt><rp>)</rp></ruby>は6<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>に<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>って、ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>りました。【2003年真题】/昨晚六点回家，然后做了饭。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"表示行为的方法和手段。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"バスに乗って、海へ行きました。【2004年真题】/坐公共汽车去了海边。","furi":"バスに<ruby>乗<rp>(</rp><rt>の</rt><rp>)</rp></ruby>って、<ruby>海<rp>(</rp><rt>うみ</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きました。【2004年真题】/坐公共汽车去了海边。"},{"t":"label","label":"说明④","text":""},{"t":"line","text":"表示原因。"},{"t":"label","label":"例文④","text":""},{"t":"line","text":"財布をなくして困りました。【2006年真题】/钱包没了，很苦恼。","furi":"<ruby>財布<rp>(</rp><rt>さいふ</rt><rp>)</rp></ruby>をなくして<ruby>困<rp>(</rp><rt>こま</rt><rp>)</rp></ruby>りました。【2006年真题】/钱包没了，很苦恼。"}],"id":"N5-20"},{"title":"21. 动词「た形」","blocks":[{"t":"label","label":"动词「た形」变形规则","text":""},{"t":"table","headers":["动词种类","辞书形","变形规则","动词「た形」"],"rows":[["I类动词","言う・立つ・鳴る","促音变，词尾「う、つ、る」变为「っ」，再接「た」","言った・立った・鳴った"],["I类动词","住む・死ぬ・飛ぶ","拨音变，词尾「む、ぬ、ぶ」变为「ん」，再接「だ」","住んだ・死んだ・飛んだ"],["I类动词","書く・注ぐ・行く","い音变，词尾「く」变为「い」，再接「た」；词尾「ぐ」变成「い」，再接「だ」；「行く」特殊为「行った」","書いた・注いだ・行った"],["I类动词","押す","词尾「す」变为「し」，再接「た」","押した"],["II类动词","見る・食べる","词尾「る」去掉之后接「た」","見た・食べた"],["III类动词","する・運動する・来る","「（～）する」变为「（～）し」，之后接「た」；「来る」变为「き」，之后接「た」","した・運動した・来（き）た"]]},{"t":"label","label":"注意","text":""},{"t":"line","text":"和「て形」一样，「行く」这个词的「た形」是「行った」，而不是「行いた」。"},{"t":"label","label":"说明","text":""},{"t":"line","text":"从表格中可以看出，动词「た形」变形规则与「て形」完全相同。动词「た形」为动词的过去时，表示过去的时态或者动作的完了。动词「た形」是与动词「ました形」对应的普通形。另外，动词「た形」也可以在句中修饰名词、代词等。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"これは去年買ったカメラです。【2007年真题】/这是去年买的照相机。","furi":"これは<ruby>去年<rp>(</rp><rt>きょねん</rt><rp>)</rp></ruby><ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ったカメラです。【2007年真题】/这是去年买的照相机。"},{"t":"line","text":"わたしは玄関のドアを開けた。【2000年真题】/我打开了大门。","furi":"わたしは<ruby>玄関<rp>(</rp><rt>げんかん</rt><rp>)</rp></ruby>のドアを<ruby>開<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>けた。【2000年真题】/我打开了大门。"}],"id":"N5-21"},{"title":"22. 动词「ない形」","blocks":[{"t":"label","label":"动词「ない形」变形规则","text":""},{"t":"table","headers":["动词种类","辞书形","变形规则","动词「ない形」"],"rows":[["I类动词","言う・行く・注ぐ・押す・立つ・死ぬ・飛ぶ・住む・鳴る・切る・帰る","词尾的「う」段假名变为同行「あ」段假名之后接「ない」","言わない・行かない・注がない・押さない・立たない・死なない・飛ばない・住まない・鳴らない・切らない・帰らない"],["II类动词","見る・食べる","词尾「る」去掉之后接「ない」","見ない・食べない"],["III类动词","する・運動する・来る","「（～）する」变为「（～）し」，之后接「ない」；「来る」变为「来（こ）」，之后接「ない」","しない・運動しない・来（こ）ない"]]},{"t":"label","label":"注意","text":""},{"t":"line","text":"词尾是「う」的动词是将词尾变成「わ」而不是「あ」；「ある」没有「ない形」，对应的否定表达就是「ない」。"},{"t":"label","label":"说明","text":""},{"t":"line","text":"动词的「ない形」表示动词的现在时否定形，其对应的过去时否定形为「なかった」，分别与敬体形中的「ません」和「ませんでした」对应。参照上述表格可以知道，II类动词以及III类动词中「する」的「ない形」的变形规则和「ます形」一样，「来る」和I类动词的变形规则不一样。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"明日雨が降るか降らないかわかりません。【2005年真题】/不知道明天下不下雨。","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby><ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>るか<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>らないかわかりません。【2005年真题】/不知道明天下不下雨。"},{"t":"line","text":"朝は忙しくて新聞は読まない。【2000年真题】/早上太忙不读报纸。","furi":"<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>は<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しくて<ruby>新聞<rp>(</rp><rt>しんぶん</rt><rp>)</rp></ruby>は<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>まない。【2000年真题】/早上太忙不读报纸。"},{"t":"line","text":"今日、朝ご飯は食べませんでした。朝寝坊をしましたから。/今天没吃早饭。因为睡懒觉了。","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>、<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>は<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べませんでした。<ruby>朝寝坊<rp>(</rp><rt>あさねぼう</rt><rp>)</rp></ruby>をしましたから。/今天没吃早饭。因为睡懒觉了。"}],"id":"N5-22"},{"title":"23. 动词敬体形和普通形","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"上面介绍了动词的敬体形和普通形。敬体形一般用于交流的双方还不太熟悉，或者当对方是应该尊敬的人（如长辈、上司等）的场合，普通形多用于亲人、朋友之间的对话。日文书信中多用敬体形，而一般的书面文章更多使用普通形。"},{"t":"label","label":"对应关系","text":""},{"t":"table","headers":["时态","敬体形","普通形"],"rows":[["现在时肯定形","～ます（書きます）","动词辞书形（書く）"],["现在时否定形","～ません（書きません）","～ない（書かない）"],["过去时肯定形","～ました（書きました）","た形（書いた）"],["过去时否定形","～ませんでした（書きませんでした）","～なかった（書かなかった）"]]}],"id":"N5-23"},{"title":"24. する","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"以「をする」形式接在表示动作或行为的名词之后，意为“做……”。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"運動をしてもいいですか。【2006年真题】/可以做运动了吗？","furi":"<ruby>運動<rp>(</rp><rt>うんどう</rt><rp>)</rp></ruby>をしてもいいですか。【2006年真题】/可以做运动了吗？"},{"t":"line","text":"わたしが子どもの世話をしますから、安心してください。【2006年真题】/有我照顾孩子们，请你放心吧。","furi":"わたしが<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもの<ruby>世話<rp>(</rp><rt>せわ</rt><rp>)</rp></ruby>をしますから、<ruby>安心<rp>(</rp><rt>あんしん</rt><rp>)</rp></ruby>してください。【2006年真题】/有我照顾孩子们，请你放心吧。"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"虽然「する」的意思写为“做”，但是随着前面宾语的变化，「する」的意思也会随之改变，翻译的时候需要考虑上下文。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"「する」前面接带有行为性质的名词，构成III类动词。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"卒業してから何をするつもりですか。【2006年真题】/毕业后打算干什么呢？","furi":"<ruby>卒業<rp>(</rp><rt>そつぎょう</rt><rp>)</rp></ruby>してから<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>をするつもりですか。【2006年真题】/毕业后打算干什么呢？"},{"t":"line","text":"失敗しても、これからも努力し続けるつもりだ。/即使失败，今后也打算继续努力。","furi":"<ruby>失敗<rp>(</rp><rt>しっぱい</rt><rp>)</rp></ruby>しても、これからも<ruby>努力<rp>(</rp><rt>どりょく</rt><rp>)</rp></ruby>し<ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>けるつもりだ。/即使失败，今后也打算继续努力。"},{"t":"label","label":"注意②","text":""},{"t":"line","text":"「旅行/食事/結婚」这样没有动作对象，表示自发性动作的名词搭配「する」构成的三类动词属于自动词；「勉強/運転/紹介」等可以有动作对象的名词搭配「する」构成的三类动词则属于他动词。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"「する」表示身上戴着小饰品，如领带、围巾、皮带等。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"上田さんは左手に指輪をしています。【2004年真题】/上田左手上戴着戒指。","furi":"<ruby>上田<rp>(</rp><rt>うえだ</rt><rp>)</rp></ruby>さんは<ruby>左手<rp>(</rp><rt>ひだりて</rt><rp>)</rp></ruby>に<ruby>指輪<rp>(</rp><rt>ゆびわ</rt><rp>)</rp></ruby>をしています。【2004年真题】/上田左手上戴着戒指。"},{"t":"line","text":"先生は毎日ネクタイをしています。/老师每天都打着领带。","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>は<ruby>毎日<rp>(</rp><rt>まいにち</rt><rp>)</rp></ruby>ネクタイをしています。/老师每天都打着领带。"},{"t":"label","label":"注意③","text":""},{"t":"line","text":"「する」此时表示穿戴着装饰物的状态，因此大多是以「している」的形式出现。"}],"id":"N5-24"},{"title":"25. やる","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"「やる」意为“做”，一般情况下可以与「する」互换，不过相比「する」语气上更为随意。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"ですから、学生はあまりこのアルバイトはやりません。【1999年真题】/因此很少有学生打这个工。","furi":"ですから、<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>はあまりこのアルバイトはやりません。【1999年真题】/因此很少有学生打这个工。"},{"t":"line","text":"今日は、うちでどんなことをやりましたか。/今天在家里干了什么？","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>は、うちでどんなことをやりましたか。/今天在家里干了什么？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「やる」只有他动词的用法，但是「を」前面通常不接「心配/注意」这类与心理状态有关的词汇。"}],"id":"N5-25"},{"title":"26. できる","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"「できる」意为“可以做到”，表示能力。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"辞書を使わずに日本語の新聞を読むことができますか。【2007年真题】/你不用辞典的话，可以看日文报纸吗？","furi":"<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>を<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>わずに<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>新聞<rp>(</rp><rt>しんぶん</rt><rp>)</rp></ruby>を<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>むことができますか。【2007年真题】/你不用辞典的话，可以看日文报纸吗？"},{"t":"line","text":"この仕事は日本語ができなくても大丈夫です。/这份工作就算不会日语也不要紧。","furi":"この<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>は<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>ができなくても<ruby>大丈夫<rp>(</rp><rt>だいじょうぶ</rt><rp>)</rp></ruby>です。/这份工作就算不会日语也不要紧。"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"「できる」前面用「が」。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"「できる」意为“完成了”、“做完了”。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"青木「川田さんはケーキを作ったことがありますか。」/“川田你做过蛋糕吗？”","furi":"<ruby>青木<rp>(</rp><rt>あおき</rt><rp>)</rp></ruby>「<ruby>川田<rp>(</rp><rt>かわた</rt><rp>)</rp></ruby>さんはケーキを<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>ったことがありますか。」/“川田你做过蛋糕吗？”"},{"t":"line","text":"川田「はい、一度だけ。でも、うまくできませんでした。」【2006年真题】/“嗯，只做过一次。但是，没能做好。”","furi":"<ruby>川田<rp>(</rp><rt>かわた</rt><rp>)</rp></ruby>「はい、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>度<rp>(</rp><rt>ど</rt><rp>)</rp></ruby>だけ。でも、うまくできませんでした。」【2006年真题】/“嗯，只做过一次。但是，没能做好。”"},{"t":"line","text":"今日の宿題はできましたか。/今天的作业做完了吗？","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>の<ruby>宿題<rp>(</rp><rt>しゅくだい</rt><rp>)</rp></ruby>はできましたか。/今天的作业做完了吗？"},{"t":"label","label":"注意②","text":""},{"t":"line","text":"「できる」前面加「よく」、「うまく」等，意思是“做得很好”。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"「できる」意为“新建成”、“新成立”、“产生”、“交”。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"駅前に新しいレストランができた。/车站前新建成了一家饭店。","furi":"<ruby>駅前<rp>(</rp><rt>えきまえ</rt><rp>)</rp></ruby>に<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しいレストランができた。/车站前新建成了一家饭店。"},{"t":"line","text":"おばさんに子どもができた。/阿姨怀了孩子。","furi":"おばさんに<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもができた。/阿姨怀了孩子。"},{"t":"line","text":"先週、新しい友だちができた。/上周交了新朋友。","furi":"<ruby>先週<rp>(</rp><rt>せんしゅう</rt><rp>)</rp></ruby>、<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しい<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちができた。/上周交了新朋友。"},{"t":"label","label":"注意③","text":""},{"t":"line","text":"「できる」可以表示具体事物的出现和产生，也可以表示虚拟的关系或概念的建立。"}],"id":"N5-26"},{"title":"27. ある","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"「ある」表示存在。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"その角を右に曲がると郵便局があります。【1999年真题】/那个路口右转有邮局。","furi":"その<ruby>角<rp>(</rp><rt>かく</rt><rp>)</rp></ruby>を<ruby>右<rp>(</rp><rt>みぎ</rt><rp>)</rp></ruby>に<ruby>曲<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>がると<ruby>郵便<rp>(</rp><rt>ゆうびん</rt><rp>)</rp></ruby><ruby>局<rp>(</rp><rt>きょく</rt><rp>)</rp></ruby>があります。【1999年真题】/那个路口右转有邮局。"},{"t":"line","text":"棚の上に本が3冊あります。/架子上有三本书。","furi":"<ruby>棚<rp>(</rp><rt>たな</rt><rp>)</rp></ruby>の<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>に<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>が3<ruby>冊<rp>(</rp><rt>さつ</rt><rp>)</rp></ruby>あります。/架子上有三本书。"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"「ある」通常用于无意识的物体，否定形式为「ない」或「ありません」。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"「ある」表示拥有物品、知识、财产等。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"わたしは留学の経験があります。【2003年真题】/我有留学的经验。","furi":"わたしは<ruby>留学<rp>(</rp><rt>りゅうがく</rt><rp>)</rp></ruby>の<ruby>経験<rp>(</rp><rt>けいけん</rt><rp>)</rp></ruby>があります。【2003年真题】/我有留学的经验。"},{"t":"line","text":"鈴木さんはお金がありません。/铃木没有钱。","furi":"<ruby>鈴木<rp>(</rp><rt>すずき</rt><rp>)</rp></ruby>さんはお<ruby>金<rp>(</rp><rt>かね</rt><rp>)</rp></ruby>がありません。/铃木没有钱。"},{"t":"label","label":"注意②","text":""},{"t":"line","text":"「ある」此处表示的是物品或抽象事物的所有权。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"「ある」表示事情的发生。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"昨日近所で火事があった。【2004年真题】/昨天附近发生了火灾。","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby><ruby>近所<rp>(</rp><rt>きんじょ</rt><rp>)</rp></ruby>で<ruby>火事<rp>(</rp><rt>かじ</rt><rp>)</rp></ruby>があった。【2004年真题】/昨天附近发生了火灾。"},{"t":"line","text":"昨日から少し熱があって頭が痛いです。【2000年真题】/昨天开始有点发热头疼。","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>から<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>熱<rp>(</rp><rt>ねつ</rt><rp>)</rp></ruby>があって<ruby>頭<rp>(</rp><rt>あたま</rt><rp>)</rp></ruby>が<ruby>痛<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>いです。【2000年真题】/昨天开始有点发热头疼。"},{"t":"label","label":"注意③","text":""},{"t":"line","text":"「ある」可以表示会议的召开、考试的举办以及事件、事故等的发生。"}],"id":"N5-27"},{"title":"28. いる","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"「いる」表示存在。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"田中さんがどこにいるかわかりません。【2003年真题】/我不知道田中在哪里。","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんがどこにいるかわかりません。【2003年真题】/我不知道田中在哪里。"},{"t":"line","text":"ずっと外にいたので、体が冷えてしまいました。【2001年真题】/因为一直在外面，所以身体都冻僵了。","furi":"ずっと<ruby>外<rp>(</rp><rt>そと</rt><rp>)</rp></ruby>にいたので、<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby>が<ruby>冷<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>えてしまいました。【2001年真题】/因为一直在外面，所以身体都冻僵了。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「いる」指有意识、有生命的生物的存在。"}],"id":"N5-28"}]},{"id":"N5-u3","title":"3单元 な形容词、い形容词","points":[{"title":"29. な形容词普通形","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"な形容词又叫作形容动词，基本构成为「な形容词词干+だ（词尾）」，可以充当普通形句子的谓语部分，其过去时为「な形容词词干+だった」。其对应的现在时否定形为「な形容词词干+ではない」，过去时否定式为「な形容词词干+ではなかった」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"明日は暇だから、遊びに行きませんか。【2003年真题】/明天有空，一起去玩吧？","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>は<ruby>暇<rp>(</rp><rt>ひま</rt><rp>)</rp></ruby>だから、<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>びに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きませんか。【2003年真题】/明天有空，一起去玩吧？"},{"t":"line","text":"公園の花はとてもきれいだった。【2005年真题】/公园的花很漂亮。","furi":"<ruby>公園<rp>(</rp><rt>こうえん</rt><rp>)</rp></ruby>の<ruby>花<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>はとてもきれいだった。【2005年真题】/公园的花很漂亮。"},{"t":"line","text":"この映画はあまり好きではない（じゃない）。/我不太喜欢这个电影。","furi":"この<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>はあまり<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きではない（じゃない）。/我不太喜欢这个电影。"},{"t":"line","text":"別に嫌いじゃなかったが……/虽说也不讨厌，可是……","furi":"<ruby>別<rp>(</rp><rt>べつ</rt><rp>)</rp></ruby>に<ruby>嫌<rp>(</rp><rt>きら</rt><rp>)</rp></ruby>いじゃなかったが……/虽说也不讨厌，可是……"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「では」的口语形式为「じゃ」，因此否定形也可以说成「な形容词词干+じゃない」。"}],"id":"N5-29"},{"title":"30. な形容词敬体形","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"上面介绍了な形容词的普通形，而与之对应的敬体形的现在时和过去时的肯定形分别为「な形容词词干+です」和「な形容词词干+でした」。现在时否定形有两种，即「な形容词词干+ではありません/ではないです」。过去时否定形也有两种，即「な形容词词干+ではありませんでした/ではなかったです」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"わたしの部屋はきれいじゃないです。【2009年真题】/我的房间不整洁。","furi":"わたしの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>はきれいじゃないです。【2009年真题】/我的房间不整洁。"},{"t":"line","text":"ホテルの部屋は静かではありませんでした。【2008年真题】/酒店的房间不安静。","furi":"ホテルの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>は<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かではありませんでした。【2008年真题】/酒店的房间不安静。"},{"t":"line","text":"兄はサッカーが好きです。【2006年真题】/哥哥喜欢踢足球。","furi":"<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>はサッカーが<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きです。【2006年真题】/哥哥喜欢踢足球。"},{"t":"line","text":"先週は宿題が多くて大変でした。【2006年真题】/上周作业很多，忙死了。","furi":"<ruby>先週<rp>(</rp><rt>せんしゅう</rt><rp>)</rp></ruby>は<ruby>宿題<rp>(</rp><rt>しゅくだい</rt><rp>)</rp></ruby>が<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>くて<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>でした。【2006年真题】/上周作业很多，忙死了。"},{"t":"line","text":"お菓子はあまり好きではありません。【2002年真题】/（我）不太喜欢吃点心。","furi":"お<ruby>菓子<rp>(</rp><rt>かし</rt><rp>)</rp></ruby>はあまり<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きではありません。【2002年真题】/（我）不太喜欢吃点心。"},{"t":"line","text":"ホテルの部屋はきれいではなかったです。/酒店的房间不干净。","furi":"ホテルの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>はきれいではなかったです。/酒店的房间不干净。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"句型中出现的「では」都能换成「じゃ」。"}],"id":"N5-30"},{"title":"31. な形容词+名词","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"な形容词修饰名词的时候，要把词尾的「だ」改为「な」，再接名词。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"一番大変な仕事は何ですか。【2007年真题】/最困难的工作是什么？","furi":"<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby><ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>な<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>ですか。【2007年真题】/最困难的工作是什么？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"な形容词简体形的过去时也可以修饰名词，表示该物体、事物过去的性质、状态等。"},{"t":"line","text":"如：△有名だった彼の作品を一つ言ってください。/请说出曾经很有名的他的一部作品。"}],"id":"N5-31"},{"title":"32. な形容词「で形」","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"な形容词在句中表示并列或者中顿的时候，要把词尾的「だ」变成「で」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"わたしのアパートは静かでいいです。【2007年真题】/我住的公寓安静而舒服。","furi":"わたしのアパートは<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かでいいです。【2007年真题】/我住的公寓安静而舒服。"},{"t":"line","text":"この町は賑やかで便利なところです。【2000年真题】/这条街又热闹又方便。","furi":"この<ruby>町<rp>(</rp><rt>まち</rt><rp>)</rp></ruby>は<ruby>賑<rp>(</rp><rt>にぎ</rt><rp>)</rp></ruby>やかで<ruby>便利<rp>(</rp><rt>べんり</rt><rp>)</rp></ruby>なところです。【2000年真题】/这条街又热闹又方便。"},{"t":"line","text":"この辺はとても静かで、景色も美しいです。/这附近很安静，风景也美丽。","furi":"この<ruby>辺<rp>(</rp><rt>あたり</rt><rp>)</rp></ruby>はとても<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かで、<ruby>景色<rp>(</rp><rt>けしき</rt><rp>)</rp></ruby>も<ruby>美<rp>(</rp><rt>うつく</rt><rp>)</rp></ruby>しいです。/这附近很安静，风景也美丽。"}],"id":"N5-32"},{"title":"33. な形容词+动词","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"な形容词修饰动词的时候，要把词尾的「だ」变成「に」，再接动词。这种用法又可以称作な形容词的副词用法。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"もう少し静かにしてくださいませんか。【2006年真题】/能再安静一点吗？","furi":"もう<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かにしてくださいませんか。【2006年真题】/能再安静一点吗？"},{"t":"line","text":"体が丈夫になりました。【2001年真题】/身体变壮了。","furi":"<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby>が<ruby>丈夫<rp>(</rp><rt>じょうぶ</rt><rp>)</rp></ruby>になりました。【2001年真题】/身体变壮了。"}],"id":"N5-33"},{"title":"34. い形容词普通形","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"形容词基本构成为「形容词词干+い（词尾）」，可以直接充当简体形句子的谓语部分，其过去时要把词尾「い」变成「かった」，即变成「い形容词词干+かった」的形式。其对应的现在时否定形要把词尾「い」变为「く」之后，再接「ない」，即「い形容词词干+く+ない」；过去时否定形为「い形容词词干+く+なかった」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"この小説はつまらない。/这本小说很无趣。","furi":"この<ruby>小説<rp>(</rp><rt>しょうせつ</rt><rp>)</rp></ruby>はつまらない。/这本小说很无趣。"},{"t":"line","text":"英語のテストはあまり難しくない。/英语考试不怎么难。","furi":"<ruby>英語<rp>(</rp><rt>えいご</rt><rp>)</rp></ruby>のテストはあまり<ruby>難<rp>(</rp><rt>むずか</rt><rp>)</rp></ruby>しくない。/英语考试不怎么难。"},{"t":"line","text":"先月はとても忙しかった。/上个月很忙。","furi":"<ruby>先月<rp>(</rp><rt>せんげつ</rt><rp>)</rp></ruby>はとても<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しかった。/上个月很忙。"},{"t":"line","text":"あのケーキはおいしくなかったよ。【2006年真题】/那种蛋糕不好吃。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「いい」的变形比较特别，不仅词尾变化，词干也有所变化，它的几种简体形分别为「いい」、「よかった」、「よくない」、「よくなかった」。"}],"id":"N5-34"},{"title":"35. い形容词敬体形","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"上面介绍了い形容词的普通形，而与之对应的敬体形的现在时和过去时的肯定形分别为「い形容词词干+い+です」和「い形容词词干+かった+です」；现在时否定形有两种，即「い形容词词干+く+ないです/ありません」；过去时否定形也有两种，即「い形容词词干+く+なかったです/ありませんでした」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"ここで写真を撮ってもいいですか。【2008年真题】/可以在这里拍照吗？","furi":"ここで<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>を<ruby>撮<rp>(</rp><rt>と</rt><rp>)</rp></ruby>ってもいいですか。【2008年真题】/可以在这里拍照吗？"},{"t":"line","text":"昨日は天気がよくなかったですね。【2008年真题】/昨天天气不太好啊。","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>は<ruby>天気<rp>(</rp><rt>てんき</rt><rp>)</rp></ruby>がよくなかったですね。【2008年真题】/昨天天气不太好啊。"},{"t":"line","text":"この料理はあまり辛くないですよ。【2005年真题】/这道菜不太辣。","furi":"この<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>はあまり<ruby>辛<rp>(</rp><rt>つら</rt><rp>)</rp></ruby>くないですよ。【2005年真题】/这道菜不太辣。"},{"t":"line","text":"去年の冬は暖かかったです。【2005年真题】/去年冬天很暖和。","furi":"<ruby>去年<rp>(</rp><rt>きょねん</rt><rp>)</rp></ruby>の<ruby>冬<rp>(</rp><rt>ふゆ</rt><rp>)</rp></ruby>は<ruby>暖<rp>(</rp><rt>あたた</rt><rp>)</rp></ruby>かかったです。【2005年真题】/去年冬天很暖和。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"い形容词的活用变形发生在い形容词本身，而不发生在使句子有礼貌的「です」上。"}],"id":"N5-35"},{"title":"36. い形容词+名词","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"い形容词修饰名词的时候，直接接续名词，形式为「い形容词普通形+名词」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"暑いとき、冷たいコーヒーを飲みます。【2003年真题】/热的时候喝冰咖啡。","furi":"<ruby>暑<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>いとき、<ruby>冷<rp>(</rp><rt>つめ</rt><rp>)</rp></ruby>たいコーヒーを<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みます。【2003年真题】/热的时候喝冰咖啡。"},{"t":"line","text":"窓から涼しい風が入ります。【2000年真题】/从窗户吹进凉爽的风。","furi":"<ruby>窓<rp>(</rp><rt>まど</rt><rp>)</rp></ruby>から<ruby>涼<rp>(</rp><rt>すず</rt><rp>)</rp></ruby>しい<ruby>風<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>が<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>ります。【2000年真题】/从窗户吹进凉爽的风。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"い形容词简体形的过去时（い形容词词干+かった）修饰名词时，表示该物体、事物过去的性质、状态等。"}],"id":"N5-36"},{"title":"37. い形容词「て形」","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"い形容词用来表示同一事物的各种性质、特征时，「て」前后的词语属于并列或递进的关系。词尾「い」变成「く」再加「て」，即「い形容词词干+く+て」。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"この辺は夏は涼しくて、冬は暖かいです。【2009年真题】/这里冬暖夏凉。","furi":"この<ruby>辺<rp>(</rp><rt>あたり</rt><rp>)</rp></ruby>は<ruby>夏<rp>(</rp><rt>なつ</rt><rp>)</rp></ruby>は<ruby>涼<rp>(</rp><rt>すず</rt><rp>)</rp></ruby>しくて、<ruby>冬<rp>(</rp><rt>ふゆ</rt><rp>)</rp></ruby>は<ruby>暖<rp>(</rp><rt>あたた</rt><rp>)</rp></ruby>かいです。【2009年真题】/这里冬暖夏凉。"},{"t":"line","text":"兄の新しいカメラは小さくて軽い。【2005年真题】/哥哥的新照相机小而轻巧。","furi":"<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>の<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しいカメラは<ruby>小<rp>(</rp><rt>ちい</rt><rp>)</rp></ruby>さくて<ruby>軽<rp>(</rp><rt>かる</rt><rp>)</rp></ruby>い。【2005年真题】/哥哥的新照相机小而轻巧。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"な形容词和い形容词可以在同一句话中并列使用。"},{"t":"line","text":"如：△田中さんは優しくて静かな人です。/田中是一位温柔、安静的人。"},{"t":"line","text":"另外，多个形容词用于对同一主体（的性质、状态等）进行描述，且属于并列关系时，「て」可以省略。此种表达方式多见于书面语。"}],"id":"N5-37"},{"title":"38. い形容词+动词","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"い形容词修饰动词的时候，要把词尾的「い」变成「く」，再接动词。这种用法可以称作形容词的副词用法。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"パンを薄く切ります。【2007年真题】/把面包切成薄片。","furi":"パンを<ruby>薄<rp>(</rp><rt>うす</rt><rp>)</rp></ruby>く<ruby>切<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ります。【2007年真题】/把面包切成薄片。"},{"t":"line","text":"天気がよくなりました。【2002年真题】/天气变好了。","furi":"<ruby>天気<rp>(</rp><rt>てんき</rt><rp>)</rp></ruby>がよくなりました。【2002年真题】/天气变好了。"}],"id":"N5-38"}]},{"id":"N5-u4","title":"4单元 疑问词","points":[{"title":"39. いくつ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"可以用于询问小东西的个数，意为“几个，多少”；还可以用于询问年龄，此用法和「何歳」类似。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"A「妹さんはいくつですか。」/“你妹妹几岁了？”","furi":"A「<ruby>妹<rp>(</rp><rt>いもうと</rt><rp>)</rp></ruby>さんはいくつですか。」/“你妹妹几岁了？”"},{"t":"line","text":"B「19歳です。」【2008年真题】/“十九岁。”","furi":"B「19<ruby>歳<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>です。」【2008年真题】/“十九岁。”"},{"t":"line","text":"りんごはいくつありますか。【2002年真题】/有几个苹果？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「いくつ」一般用于询问小孩子的年龄或者用于老年人询问年轻人的年龄的场合。当面对面问对方孩子的年龄时，最好在「いくつ」前面加美化语「お」。"}],"id":"N5-39"},{"title":"40. いつ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"用来询问时间，意为“什么时候”。「いつか」可以表示不确定的日子。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"パーティーはいつがいいですか。【2007年真题】/聚会安排在什么时候为好？"},{"t":"line","text":"いつかまた日本へ来たいです。【2008年真题】/以后还想再来日本。","furi":"いつかまた<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>へ<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>たいです。【2008年真题】/以后还想再来日本。"}],"id":"N5-40"},{"title":"41. 誰/どの人/どなた/どの方","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"相当于汉语的“谁”，用于说话人不认识或者不明确第三者是某人的场合。从敬意程度看，「誰」最低。「どの人」、「どなた」带有敬意，为礼貌用语。「どの方」敬意程度最高。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"昨日誰と一緒に帰りましたか。【2008年真题】/昨天和谁一起回家的？","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby><ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>と<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>りましたか。【2008年真题】/昨天和谁一起回家的？"},{"t":"line","text":"どの人が山下さんですか。【2006年真题】/哪位是山下先生？","furi":"どの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>山下<rp>(</rp><rt>やました</rt><rp>)</rp></ruby>さんですか。【2006年真题】/哪位是山下先生？"},{"t":"line","text":"あの方はどなたですか。/那位先生（小姐）是谁？","furi":"あの<ruby>方<rp>(</rp><rt>ほう</rt><rp>)</rp></ruby>はどなたですか。/那位先生（小姐）是谁？"},{"t":"line","text":"次期社長はどの方に決めましたか。/下任社长决定是哪位？","furi":"<ruby>次期<rp>(</rp><rt>じき</rt><rp>)</rp></ruby><ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>はどの<ruby>方<rp>(</rp><rt>ほう</rt><rp>)</rp></ruby>に<ruby>決<rp>(</rp><rt>き</rt><rp>)</rp></ruby>めましたか。/下任社长决定是哪位？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"当对方用「誰、どなた、どの人、どの方+が…か。」询问时，回答时也应该用「…が…。」的形式。"}],"id":"N5-41"},{"title":"42. どう/いかが","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"用来询问对方的想法或事物的性质、状态等，回答中多会出现形容词对其进行说明。意为“……怎么样，……怎样了”。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"そのレストランの料理はどう/いかがですか。/那家西餐厅的料理味道怎么样？","furi":"そのレストランの<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>はどう/いかがですか。/那家西餐厅的料理味道怎么样？"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"表示委婉地向对方提出某项建议，意为“……怎么样，……如何”。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"紅茶をいっぱいいかが/どうですか。/来杯红茶怎么样？","furi":"<ruby>紅茶<rp>(</rp><rt>こうちゃ</rt><rp>)</rp></ruby>をいっぱいいかが/どうですか。/来杯红茶怎么样？"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"用来询问某事应该怎么做，“怎么……，如何……”。此用法不能用「いかが」替换。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"日本語の手紙をどう書きますか。/日语的书信怎么写？","furi":"<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>手紙<rp>(</rp><rt>てがみ</rt><rp>)</rp></ruby>をどう<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>きますか。/日语的书信怎么写？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「いかが」是「どう」的礼貌说法，但是在「どう」的第三种用法里，不能用「いかが」替换。"}],"id":"N5-42"},{"title":"43. どのぐらい/どれぐらい","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"可以用来询问时间、距离、程度、具体数量等，意为“多久……”、“……多远”等。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"A「昨日はどのぐらい走りましたか。」/“昨天你跑了多远？”","furi":"A「<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>はどのぐらい<ruby>走<rp>(</rp><rt>はし</rt><rp>)</rp></ruby>りましたか。」/“昨天你跑了多远？”"},{"t":"line","text":"B「5キロ走りました。」【2008年真题】/“跑了五公里。”","furi":"B「5キロ<ruby>走<rp>(</rp><rt>はし</rt><rp>)</rp></ruby>りました。」【2008年真题】/“跑了五公里。”"},{"t":"line","text":"春休みはどのぐらいありますか。【2001年真题】/春假放多少天？","furi":"<ruby>春休<rp>(</rp><rt>はるやす</rt><rp>)</rp></ruby>みはどのぐらいありますか。【2001年真题】/春假放多少天？"},{"t":"line","text":"今からあなたのうちへ行きますが、そちらまでどれぐらいかかりますか。【2001年真题】/现在我去你家，到你那里大概要花费多长时间？","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>からあなたのうちへ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きますが、そちらまでどれぐらいかかりますか。【2001年真题】/现在我去你家，到你那里大概要花费多长时间？"}],"id":"N5-43"},{"title":"44. 何","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"用来向对方询问自己不了解的内容、情况等，意为“什么”。"},{"t":"sub","text":"① 读「なに」的场合："},{"t":"line","text":"一般「何」后续「が」、「を」、「から」、「まで」、「も」、「は」、「より」时。"},{"t":"sub","text":"② 读「なん」的场合："},{"t":"line","text":"后续「だ」、「の」以及「助数词」时。"},{"t":"sub","text":"③ 两种读法都可以："},{"t":"line","text":"后续「か」、「に」、「と」、「で」时。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"昨日のパーティーで何をしましたか。【2006年真题】/昨天聚会上你做什么了？","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>のパーティーで<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>をしましたか。【2006年真题】/昨天聚会上你做什么了？"},{"t":"line","text":"何か運動をしていますか。【2007年真题】/你做什么运动吗？","furi":"<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>か<ruby>運動<rp>(</rp><rt>うんどう</rt><rp>)</rp></ruby>をしていますか。【2007年真题】/你做什么运动吗？"},{"t":"line","text":"映画は何時に終わりますか。【2007年真题】/电影几点结束？","furi":"<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>に<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わりますか。【2007年真题】/电影几点结束？"},{"t":"line","text":"この耳の大きい動物は何ですか。【2009年真题】/这个大耳朵的动物是什么动物啊？","furi":"この<ruby>耳<rp>(</rp><rt>みみ</rt><rp>)</rp></ruby>の<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きい<ruby>動物<rp>(</rp><rt>どうぶつ</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>ですか。【2009年真题】/这个大耳朵的动物是什么动物啊？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"后续「と」的时候，一般情况下两种读法都可以，但是「何という」这个词语里，只发「なん」的音。后续「で」时，「何で（なにで）」侧重于询问方式，「何で（なんで）」侧重于询问理由。"}],"id":"N5-44"},{"title":"45. なぜ/どうして/なんで","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"用于询问原因、理由的疑问词。意为“为什么……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"昨日はどうして早く帰りましたか。【2004年真题】/昨天为什么回去那么早啊？","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>はどうして<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>く<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>りましたか。【2004年真题】/昨天为什么回去那么早啊？"},{"t":"line","text":"なぜ会社を辞めましたか。/为什么辞职了？","furi":"なぜ<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>を<ruby>辞<rp>(</rp><rt>や</rt><rp>)</rp></ruby>めましたか。/为什么辞职了？"},{"t":"line","text":"なんで来なかったの。約束したのに。/为什么没来啊？明明都约好了。","furi":"なんで<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>なかったの。<ruby>約束<rp>(</rp><rt>やくそく</rt><rp>)</rp></ruby>したのに。/为什么没来啊？明明都约好了。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「なんで」多用于口语表达，意为“怎么会……”。"}],"id":"N5-45"}]},{"id":"N5-u5","title":"5单元 格助词","points":[{"title":"46. が","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"提示主语，表示客观现象、事物的状态、性质等；或者表示话题中首次出现的事物。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"この大学に留学生がいますか。【2009年真题】/这所大学里有留学生吗？","furi":"この<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>に<ruby>留学生<rp>(</rp><rt>りゅうがくせい</rt><rp>)</rp></ruby>がいますか。【2009年真题】/这所大学里有留学生吗？"},{"t":"line","text":"あ、あそこで鳥が鳴いていますよ。【2007年真题】/啊，那边有鸟儿在叫。","furi":"あ、あそこで<ruby>鳥<rp>(</rp><rt>とり</rt><rp>)</rp></ruby>が<ruby>鳴<rp>(</rp><rt>な</rt><rp>)</rp></ruby>いていますよ。【2007年真题】/啊，那边有鸟儿在叫。"},{"t":"line","text":"あの部屋が日本語の教室です。【2007年真题】/那间房间是日语教室。","furi":"あの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>が<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>教室<rp>(</rp><rt>きょうしつ</rt><rp>)</rp></ruby>です。【2007年真题】/那间房间是日语教室。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"表示整体的一部分或者从句中的主语。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"兄は背が高いです。【2008年真题】/哥哥个子高。","furi":"<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>は<ruby>背<rp>(</rp><rt>せ</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いです。【2008年真题】/哥哥个子高。"},{"t":"line","text":"母が作るサンドイッチはおいしいです。【2008年真题】/妈妈做的三明治好吃。","furi":"<ruby>母<rp>(</rp><rt>はは</rt><rp>)</rp></ruby>が<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>るサンドイッチはおいしいです。【2008年真题】/妈妈做的三明治好吃。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"表示疑问句中主语。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"パーティーはいつがいいですか。【2007年真题】/聚会定在什么时候好呢？"},{"t":"line","text":"どの人が山下さんですか。【2006年真题】/哪位是山下先生（小姐）？","furi":"どの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>山下<rp>(</rp><rt>やました</rt><rp>)</rp></ruby>さんですか。【2006年真题】/哪位是山下先生（小姐）？"},{"t":"label","label":"说明④","text":""},{"t":"line","text":"表示好恶、希望、技能好坏等的对象。"},{"t":"label","label":"例文④","text":""},{"t":"line","text":"わたしはカメラがほしいです。【2008年真题】/我想要照相机。"},{"t":"line","text":"田中さんはたぶん歌が上手でしょう。【2008年真题】/田中唱歌大概还不错吧。","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんはたぶん<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>が<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>でしょう。【2008年真题】/田中唱歌大概还不错吧。"},{"t":"line","text":"兄はサッカーが好きです。【2006年真题】/哥哥喜欢踢足球。","furi":"<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>はサッカーが<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きです。【2006年真题】/哥哥喜欢踢足球。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"从初级阶段学习时，就要特别注意「が」与「は」的区别。本书第6单元讲解「は」的时候，将就「が」、「は」的区别给出相应的说明。"}],"id":"N5-46"},{"title":"47. から","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词+から","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+から"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"表示空间、场所的起点。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"あなたの家は学校から遠いですか。【2005年真题】/你家离学校远吗？","furi":"あなたの<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>は<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>から<ruby>遠<rp>(</rp><rt>とお</rt><rp>)</rp></ruby>いですか。【2005年真题】/你家离学校远吗？"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"表示时间的起点。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"次の映画は5時から始まります。【2008年真题】/下场电影从五点开播。","furi":"<ruby>次<rp>(</rp><rt>つぎ</rt><rp>)</rp></ruby>の<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>は5<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>から<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>まります。【2008年真题】/下场电影从五点开播。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"表示动作的经过点。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"窓から涼しい風が入りますよ。【2000年真题】/从窗户吹进凉爽的风。","furi":"<ruby>窓<rp>(</rp><rt>まど</rt><rp>)</rp></ruby>から<ruby>涼<rp>(</rp><rt>すず</rt><rp>)</rp></ruby>しい<ruby>風<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>が<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>りますよ。【2000年真题】/从窗户吹进凉爽的风。"},{"t":"label","label":"说明④","text":""},{"t":"line","text":"表示动作的主体、起点等。"},{"t":"label","label":"例文④","text":""},{"t":"line","text":"わたしは家族から手紙をもらいました。【2003年真题】/我收到家里寄来的信。","furi":"わたしは<ruby>家族<rp>(</rp><rt>かぞく</rt><rp>)</rp></ruby>から<ruby>手紙<rp>(</rp><rt>てがみ</rt><rp>)</rp></ruby>をもらいました。【2003年真题】/我收到家里寄来的信。"}],"id":"N5-47"},{"title":"48. で","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词/数量词+で","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>数量<rp>(</rp><rt>すうりょう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+で"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"表示动作进行的场所。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"ここで写真を撮ってもいいですか。【2008年真题】/可以在这里拍照吗？","furi":"ここで<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>を<ruby>撮<rp>(</rp><rt>と</rt><rp>)</rp></ruby>ってもいいですか。【2008年真题】/可以在这里拍照吗？"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"表示手段、方式方法、工具等。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"大きな声で話さないでください。【2009年真题】/说话声音不要太大。","furi":"<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きな<ruby>声<rp>(</rp><rt>こえ</rt><rp>)</rp></ruby>で<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>さないでください。【2009年真题】/说话声音不要太大。"},{"t":"line","text":"ナイフでパンを切りました。【2006年真题】/用刀把面包切开了。","furi":"ナイフでパンを<ruby>切<rp>(</rp><rt>き</rt><rp>)</rp></ruby>りました。【2006年真题】/用刀把面包切开了。"},{"t":"line","text":"日本語で話しましょう。【2003年真题】/用日语说吧。","furi":"<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>で<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>しましょう。【2003年真题】/用日语说吧。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"表示动作的基准，或者数量的合计等。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"ノートは5冊で300円です。【2008年真题】/笔记本五本共三百日元。","furi":"ノートは5<ruby>冊<rp>(</rp><rt>さつ</rt><rp>)</rp></ruby>で300<ruby>円<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>です。【2008年真题】/笔记本五本共三百日元。"},{"t":"line","text":"病院へ一人で行きました。【2008年真题】/一个人去了医院。","furi":"<ruby>病院<rp>(</rp><rt>びょういん</rt><rp>)</rp></ruby>へ<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>で<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きました。【2008年真题】/一个人去了医院。"},{"t":"line","text":"わたしの家族は、全部で8人です。【2000年真题】/我家一共八个人。","furi":"わたしの<ruby>家族<rp>(</rp><rt>かぞく</rt><rp>)</rp></ruby>は、<ruby>全部<rp>(</rp><rt>ぜんぶ</rt><rp>)</rp></ruby>で8<ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>です。【2000年真题】/我家一共八个人。"},{"t":"label","label":"说明④","text":""},{"t":"line","text":"表示原材料。"},{"t":"label","label":"例文④","text":""},{"t":"line","text":"この料理は肉と野菜で作ります。【2001年真题】/这道菜要用肉和蔬菜做。","furi":"この<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>は<ruby>肉<rp>(</rp><rt>にく</rt><rp>)</rp></ruby>と<ruby>野菜<rp>(</rp><rt>やさい</rt><rp>)</rp></ruby>で<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>ります。【2001年真题】/这道菜要用肉和蔬菜做。"},{"t":"label","label":"说明⑤","text":""},{"t":"line","text":"表示范围。"},{"t":"label","label":"例文⑤","text":""},{"t":"line","text":"この町で一番賑やかなのはこの辺です。【2009年真题】/这一带是这个小镇最热闹的地方。","furi":"この<ruby>町<rp>(</rp><rt>まち</rt><rp>)</rp></ruby>で<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby><ruby>賑<rp>(</rp><rt>にぎ</rt><rp>)</rp></ruby>やかなのはこの<ruby>辺<rp>(</rp><rt>あたり</rt><rp>)</rp></ruby>です。【2009年真题】/这一带是这个小镇最热闹的地方。"},{"t":"label","label":"说明⑥","text":""},{"t":"line","text":"表示原因、理由。"},{"t":"label","label":"例文⑥","text":""},{"t":"line","text":"去年、仕事で外国へ行きました。【2009年真题】/去年，因工作关系去了国外。","furi":"<ruby>去年<rp>(</rp><rt>きょねん</rt><rp>)</rp></ruby>、<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>で<ruby>外国<rp>(</rp><rt>がいこく</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きました。【2009年真题】/去年，因工作关系去了国外。"},{"t":"line","text":"風邪で学校を休みました。【2009年真题】/因感冒没去学校。","furi":"<ruby>風邪<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>で<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>を<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>みました。【2009年真题】/因感冒没去学校。"}],"id":"N5-48"},{"title":"49. と","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"和某人共同做某事，可以用「と一緒に」的形式。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"わたしはおじいさんとよく散歩をします。【2006年真题】/我经常和爷爷一起散步。","furi":"わたしはおじいさんとよく<ruby>散歩<rp>(</rp><rt>さんぽ</rt><rp>)</rp></ruby>をします。【2006年真题】/我经常和爷爷一起散步。"},{"t":"line","text":"昨日誰と一緒に帰りましたか。【2008年真题】/昨天和谁一起回去的？","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby><ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>と<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>りましたか。【2008年真题】/昨天和谁一起回去的？"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"句中的「一緒に」可省略，可参考第1个例句。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"和某人互相进行某事，此事必须有对方参与才能完成。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"わたしは先生と30分話しました。【2007年真题】/我和老师谈了三十分钟。","furi":"わたしは<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>と30<ruby>分<rp>(</rp><rt>ふん</rt><rp>)</rp></ruby><ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>しました。【2007年真题】/我和老师谈了三十分钟。"},{"t":"line","text":"友だちと電話で話しました。【2002年真题】/和朋友通了电话。","furi":"<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちと<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>で<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>しました。【2002年真题】/和朋友通了电话。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"表示说话或引用的内容等。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"この猫は何という名前ですか。【2008年真题】/这只猫叫什么名字？","furi":"この<ruby>猫<rp>(</rp><rt>ねこ</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>という<ruby>名前<rp>(</rp><rt>なまえ</rt><rp>)</rp></ruby>ですか。【2008年真题】/这只猫叫什么名字？"},{"t":"line","text":"漢字のテストは大変だったとみんな言っていました。【2008年真题】/大家都说汉字考试太难了。","furi":"<ruby>漢字<rp>(</rp><rt>かんじ</rt><rp>)</rp></ruby>のテストは<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>だったとみんな<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>っていました。【2008年真题】/大家都说汉字考试太难了。"},{"t":"label","label":"注意③","text":""},{"t":"line","text":"「と」的这种用法，后面经常会出现「言う、思う、考える、書く」等词。"}],"id":"N5-49"},{"title":"50. に","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"表示事物存在或者静态的动作、作用的场所。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"学校のそばに郵便局があります。【2008年真题】/学校附近有家邮局。","furi":"<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>のそばに<ruby>郵便<rp>(</rp><rt>ゆうびん</rt><rp>)</rp></ruby><ruby>局<rp>(</rp><rt>きょく</rt><rp>)</rp></ruby>があります。【2008年真题】/学校附近有家邮局。"},{"t":"line","text":"机の上に本が5冊あります。【2007年真题】/桌上有五本书。","furi":"<ruby>机<rp>(</rp><rt>つくえ</rt><rp>)</rp></ruby>の<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>に<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>が5<ruby>冊<rp>(</rp><rt>さつ</rt><rp>)</rp></ruby>あります。【2007年真题】/桌上有五本书。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"表示动作、作用的到达点、着落点等。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"車の中に鍵を忘れました。【2008年真题】/把钥匙忘在车里了。","furi":"<ruby>車<rp>(</rp><rt>くるま</rt><rp>)</rp></ruby>の<ruby>中<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>に<ruby>鍵<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>を<ruby>忘<rp>(</rp><rt>わす</rt><rp>)</rp></ruby>れました。【2008年真题】/把钥匙忘在车里了。"},{"t":"line","text":"ここにかばんを置かないでください。【2007年真题】/不要把包放在这里。","furi":"ここにかばんを<ruby>置<rp>(</rp><rt>お</rt><rp>)</rp></ruby>かないでください。【2007年真题】/不要把包放在这里。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"表示动作、作用的具体时间。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"映画は何時に終わりますか。【2007年真题】/电影几点结束？","furi":"<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>に<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わりますか。【2007年真题】/电影几点结束？"},{"t":"line","text":"日曜日に掃除や洗濯をします。【2007年真题】/周日打扫房间、洗衣服什么的。","furi":"<ruby>日曜日<rp>(</rp><rt>にちようび</rt><rp>)</rp></ruby>に<ruby>掃除<rp>(</rp><rt>そうじ</rt><rp>)</rp></ruby>や<ruby>洗濯<rp>(</rp><rt>せんたく</rt><rp>)</rp></ruby>をします。【2007年真题】/周日打扫房间、洗衣服什么的。"},{"t":"label","label":"注意③","text":""},{"t":"line","text":"因为「に」前一般为具体时间，所以像「毎年、毎月、毎週、毎日、先週、今週、来週、先月、今月、来月、去年、今年、来年」这样的词语后面都不能用「に」。另外，对时间提问的「いつ」后不能加「に」，「何時」后面应该加「に」。"},{"t":"label","label":"说明④","text":""},{"t":"line","text":"表示动作、作用的目的。"},{"t":"label","label":"例文④","text":""},{"t":"line","text":"明日わたしの部屋へ遊びに来ませんか。【2006年真题】/明天来我房间玩吧？","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>わたしの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>へ<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>びに<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ませんか。【2006年真题】/明天来我房间玩吧？"},{"t":"line","text":"図書館へ本を返しに行きます。【2002年真题】/去图书馆还书。","furi":"<ruby>図書館<rp>(</rp><rt>としょかん</rt><rp>)</rp></ruby>へ<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>を<ruby>返<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>しに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。【2002年真题】/去图书馆还书。"},{"t":"label","label":"说明⑤","text":""},{"t":"line","text":"表示动作、作用涉及的对象。"},{"t":"label","label":"例文⑤","text":""},{"t":"line","text":"わたしは友だちに電話をしました。【2006年真题】/我给朋友打了电话。","furi":"わたしは<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちに<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>をしました。【2006年真题】/我给朋友打了电话。"},{"t":"line","text":"わからないときは、先生に聞きます。【2006年真题】/不明白的时候，问老师。","furi":"わからないときは、<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>に<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>きます。【2006年真题】/不明白的时候，问老师。"},{"t":"label","label":"说明⑥","text":""},{"t":"line","text":"表示某一时间范围内的数量或次数。"},{"t":"label","label":"例文⑥","text":""},{"t":"line","text":"父は一日に3回歯を磨きます。【2009年真题】/爸爸一天刷三次牙。","furi":"<ruby>父<rp>(</rp><rt>ちち</rt><rp>)</rp></ruby>は<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>にち</rt><rp>)</rp></ruby>に3<ruby>回<rp>(</rp><rt>かい</rt><rp>)</rp></ruby><ruby>歯<rp>(</rp><rt>は</rt><rp>)</rp></ruby>を<ruby>磨<rp>(</rp><rt>みが</rt><rp>)</rp></ruby>きます。【2009年真题】/爸爸一天刷三次牙。"},{"t":"label","label":"说明⑦","text":""},{"t":"line","text":"“作为……”，相当于「～として」的用法。"},{"t":"label","label":"例文⑦","text":""},{"t":"line","text":"友だちの結婚祝いにおしゃれな食器を贈った。/作为朋友结婚的贺礼，我赠送了一套漂亮的餐具给她。","furi":"<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちの<ruby>結婚<rp>(</rp><rt>けっこん</rt><rp>)</rp></ruby><ruby>祝<rp>(</rp><rt>いわ</rt><rp>)</rp></ruby>いにおしゃれな<ruby>食器<rp>(</rp><rt>しょっき</rt><rp>)</rp></ruby>を<ruby>贈<rp>(</rp><rt>おく</rt><rp>)</rp></ruby>った。/作为朋友结婚的贺礼，我赠送了一套漂亮的餐具给她。"},{"t":"line","text":"案内してくれたお礼にお土産をあげた。/作为给我们做向导的谢礼，赠送了礼物。","furi":"<ruby>案内<rp>(</rp><rt>あんない</rt><rp>)</rp></ruby>してくれたお<ruby>礼<rp>(</rp><rt>れい</rt><rp>)</rp></ruby>にお<ruby>土産<rp>(</rp><rt>みやげ</rt><rp>)</rp></ruby>をあげた。/作为给我们做向导的谢礼，赠送了礼物。"},{"t":"label","label":"说明⑧","text":""},{"t":"line","text":"“因……而……”、“由于……，感到……”。表示原因、理由。"},{"t":"label","label":"例文⑧","text":""},{"t":"line","text":"東京に来て、電車を使う人がとても多いのにびっくりしました。【2011年7月真题】/来到东京之后，因乘坐电车的人很多而感到吃惊。","furi":"<ruby>東京<rp>(</rp><rt>とうきょう</rt><rp>)</rp></ruby>に<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>て、<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>を<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>う<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>がとても<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>いのにびっくりしました。【2011年7月真题】/来到东京之后，因乘坐电车的人很多而感到吃惊。"},{"t":"line","text":"あまりの恐ろしさに、声も出なかった。/因为太恐惧，连声音也发不出了。","furi":"あまりの<ruby>恐<rp>(</rp><rt>おそ</rt><rp>)</rp></ruby>ろしさに、<ruby>声<rp>(</rp><rt>こえ</rt><rp>)</rp></ruby>も<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>なかった。/因为太恐惧，连声音也发不出了。"},{"t":"label","label":"说明⑨","text":""},{"t":"line","text":"表示比较、评价的基准。"},{"t":"label","label":"例文⑨","text":""},{"t":"line","text":"A社の商品が腰の痛みにどのぐらい効果があるのかについて詳しく知りたい。【2010年7月真题】/我想详细了解一下A公司的商品对于腰痛有怎样的效果。","furi":"A<ruby>社<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>の<ruby>商品<rp>(</rp><rt>しょうひん</rt><rp>)</rp></ruby>が<ruby>腰<rp>(</rp><rt>こし</rt><rp>)</rp></ruby>の<ruby>痛<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>みにどのぐらい<ruby>効果<rp>(</rp><rt>こうか</rt><rp>)</rp></ruby>があるのかについて<ruby>詳<rp>(</rp><rt>くわ</rt><rp>)</rp></ruby>しく<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>りたい。【2010年7月真题】/我想详细了解一下A公司的商品对于腰痛有怎样的效果。"},{"t":"line","text":"このシャツがあなたにすごく似合うと思うよ。/我觉得这件衬衫非常适合你。","furi":"このシャツがあなたにすごく<ruby>似合<rp>(</rp><rt>にあ</rt><rp>)</rp></ruby>うと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>うよ。/我觉得这件衬衫非常适合你。"},{"t":"label","label":"说明⑩","text":""},{"t":"line","text":"“和……”，表示同类事物的叠加。"},{"t":"label","label":"例文⑩","text":""},{"t":"line","text":"A「これから行くおすし屋さんは、おすしにカレーにラーメン、なんでもありますよ。」/“现在要去的寿司店，提供寿司、咖喱饭和拉面，应有尽有呢。”","furi":"A「これから<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くおすし<ruby>屋<rp>(</rp><rt>や</rt><rp>)</rp></ruby>さんは、おすしにカレーにラーメン、なんでもありますよ。」/“现在要去的寿司店，提供寿司、咖喱饭和拉面，应有尽有呢。”"},{"t":"line","text":"B「面白い店ですね。」【2012年7月真题】/“真是一家有趣的店呀。”","furi":"B「<ruby>面白<rp>(</rp><rt>おもしろ</rt><rp>)</rp></ruby>い<ruby>店<rp>(</rp><rt>みせ</rt><rp>)</rp></ruby>ですね。」【2012年7月真题】/“真是一家有趣的店呀。”"},{"t":"line","text":"スーパーでお米に野菜に果物を買ってきた。/从超市里买回了大米、蔬菜和水果。","furi":"スーパーでお<ruby>米<rp>(</rp><rt>こめ</rt><rp>)</rp></ruby>に<ruby>野菜<rp>(</rp><rt>やさい</rt><rp>)</rp></ruby>に<ruby>果物<rp>(</rp><rt>くだもの</rt><rp>)</rp></ruby>を<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ってきた。/从超市里买回了大米、蔬菜和水果。"}],"id":"N5-50"},{"title":"51. の","blocks":[{"t":"label","label":"接续①","text":""},{"t":"line","text":"名词+の+名词","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の+<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"表示所属、性质、限定、同位语等。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"日本の古い映画を見ました。【2009年真题】/看了日本的老电影。","furi":"<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>の<ruby>古<rp>(</rp><rt>ふる</rt><rp>)</rp></ruby>い<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ました。【2009年真题】/看了日本的老电影。"},{"t":"line","text":"今年の夏は海で泳ぎたいです。【2008年真题】/今年夏天想在海里游泳。","furi":"<ruby>今年<rp>(</rp><rt>ことし</rt><rp>)</rp></ruby>の<ruby>夏<rp>(</rp><rt>なつ</rt><rp>)</rp></ruby>は<ruby>海<rp>(</rp><rt>うみ</rt><rp>)</rp></ruby>で<ruby>泳<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>ぎたいです。【2008年真题】/今年夏天想在海里游泳。"},{"t":"line","text":"花の写真を10枚ぐらい撮りました。【2007年真题】/拍了大约十张花儿的照片。","furi":"<ruby>花<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>の<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>を10<ruby>枚<rp>(</rp><rt>まい</rt><rp>)</rp></ruby>ぐらい<ruby>撮<rp>(</rp><rt>と</rt><rp>)</rp></ruby>りました。【2007年真题】/拍了大约十张花儿的照片。"},{"t":"line","text":"息子の太郎は今年、17歳です。/我儿子太郎今年十七岁。","furi":"<ruby>息子<rp>(</rp><rt>むすこ</rt><rp>)</rp></ruby>の<ruby>太郎<rp>(</rp><rt>たろう</rt><rp>)</rp></ruby>は<ruby>今年<rp>(</rp><rt>ことし</rt><rp>)</rp></ruby>、17<ruby>歳<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>です。/我儿子太郎今年十七岁。"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"「の」的此种用法不一定翻译成汉语的“……的”。另外在所属物品相当明确的情况下，「の」可以代替句中省略掉的所属物品。"},{"t":"line","text":"如：△その大きい荷物はわたしのです。【2005年真题】/那件大行李是我的。"},{"t":"label","label":"接续②","text":""},{"t":"line","text":"い形容词辞书形/な形容词词干+な+の","furi":"い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な+の"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"在句中可以明确名词所指何物的情况下，可以用「の」代替该名词。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"この町で一番賑やかなのはこの辺です。【2009年真题】/这一带是这个小镇最热闹的地方。","furi":"この<ruby>町<rp>(</rp><rt>まち</rt><rp>)</rp></ruby>で<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby><ruby>賑<rp>(</rp><rt>にぎ</rt><rp>)</rp></ruby>やかなのはこの<ruby>辺<rp>(</rp><rt>あたり</rt><rp>)</rp></ruby>です。【2009年真题】/这一带是这个小镇最热闹的地方。"},{"t":"line","text":"もうちょっと安いのを、見せてください。【2000年真题】/请让我看看再便宜一些的。","furi":"もうちょっと<ruby>安<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>いのを、<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>せてください。【2000年真题】/请让我看看再便宜一些的。"},{"t":"label","label":"接续③","text":""},{"t":"line","text":"名词+の……","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の……"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"作句子的修饰成分。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"田中さんの来る日は火曜日です。【2007年真题】/田中周二来。","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんの<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>は<ruby>火曜日<rp>(</rp><rt>かようび</rt><rp>)</rp></ruby>です。【2007年真题】/田中周二来。"},{"t":"label","label":"注意③","text":""},{"t":"line","text":"此种用法的「の」是由从句中主格助词「が」变过来的。"},{"t":"label","label":"说明④","text":""},{"t":"line","text":"形式体言，在句中通常不翻译出来。"},{"t":"label","label":"例文④","text":""},{"t":"line","text":"今日の授業は休みだと誰かが言っているのを聞きました。【2010年真题】/我好像听谁说今天停课。","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>の<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby>は<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>みだと<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>かが<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>っているのを<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>きました。【2010年真题】/我好像听谁说今天停课。"},{"t":"line","text":"空を鳥が飛んでいるのが見えます。【2004年真题】/我看到有鸟飞过天空。","furi":"<ruby>空<rp>(</rp><rt>そら</rt><rp>)</rp></ruby>を<ruby>鳥<rp>(</rp><rt>とり</rt><rp>)</rp></ruby>が<ruby>飛<rp>(</rp><rt>と</rt><rp>)</rp></ruby>んでいるのが<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>えます。【2004年真题】/我看到有鸟飞过天空。"},{"t":"label","label":"注意④","text":""},{"t":"line","text":"「の」在第一个例文中是代替宾语部分；第二个例文中是代替主语部分。"}],"id":"N5-51"},{"title":"52. へ","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"动作、作用的方向或目的地。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"会社へ行く前に、銀行へ行きました。【2007年真题】/去公司之前，去了趟银行。","furi":"<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>に、<ruby>銀行<rp>(</rp><rt>ぎんこう</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きました。【2007年真题】/去公司之前，去了趟银行。"},{"t":"line","text":"母は風邪で病院へ行きました。【2006年真题】/妈妈因感冒去医院了。","furi":"<ruby>母<rp>(</rp><rt>はは</rt><rp>)</rp></ruby>は<ruby>風邪<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>で<ruby>病院<rp>(</rp><rt>びょういん</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きました。【2006年真题】/妈妈因感冒去医院了。"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"注意此种用法和「に」的区别。「へ」比「に」更强调动作的方向。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"动作、作用所涉及的对象。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"これは田中さんへのプレゼントです。/这是给田中的礼物。","furi":"これは<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんへのプレゼントです。/这是给田中的礼物。"}],"id":"N5-52"},{"title":"53. まで","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“到……”。表示动作、作用的时间或场所的终点。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"A「先週の授業、どこまで進んだ？」/“上周的课，上到哪里了？”","furi":"A「<ruby>先週<rp>(</rp><rt>せんしゅう</rt><rp>)</rp></ruby>の<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby>、どこまで<ruby>進<rp>(</rp><rt>すす</rt><rp>)</rp></ruby>んだ？」/“上周的课，上到哪里了？”"},{"t":"line","text":"B「3課の文法の練習問題を解いたところまでで終わったよ。」【2010年7月真题】/“第三课的文法练习已经上完了。”","furi":"B「3<ruby>課<rp>(</rp><rt>か</rt><rp>)</rp></ruby>の<ruby>文法<rp>(</rp><rt>ぶんぽう</rt><rp>)</rp></ruby>の<ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby><ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>を<ruby>解<rp>(</rp><rt>と</rt><rp>)</rp></ruby>いたところまでで<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わったよ。」【2010年7月真题】/“第三课的文法练习已经上完了。”"},{"t":"line","text":"大学まで電車で30分かかります。【2001年真题】/坐电车到大学需要花费三十分钟。","furi":"<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>まで<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>で30<ruby>分<rp>(</rp><rt>ふん</rt><rp>)</rp></ruby>かかります。【2001年真题】/坐电车到大学需要花费三十分钟。"},{"t":"line","text":"銀行は9時から3時までです。/银行的营业时间是从早上九点到下午三点。","furi":"<ruby>銀行<rp>(</rp><rt>ぎんこう</rt><rp>)</rp></ruby>は9<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>から3<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>までです。/银行的营业时间是从早上九点到下午三点。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"与「から」连用，构成「～から～まで」的形式，表示空间或时间上的起点和终点。"}],"id":"N5-53"},{"title":"54. を","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"表示动作所涉及的对象，即通常所说的宾语。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"朝シャワーを浴びました。【2009年真题】/早上洗了淋浴。","furi":"<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>シャワーを<ruby>浴<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>びました。【2009年真题】/早上洗了淋浴。"},{"t":"line","text":"忙しいから、ご飯を食べる時間がありません。【2008年真题】/太忙了，没有吃饭的时间。","furi":"<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しいから、ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>がありません。【2008年真题】/太忙了，没有吃饭的时间。"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"此种情况下，「を」后的动词为他动词。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"表示动作经过的场所。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"この橋を渡って向こうに行きましょう。【2009年真题】/走过这座桥去对面吧。","furi":"この<ruby>橋<rp>(</rp><rt>はし</rt><rp>)</rp></ruby>を<ruby>渡<rp>(</rp><rt>わた</rt><rp>)</rp></ruby>って<ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>こうに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きましょう。【2009年真题】/走过这座桥去对面吧。"},{"t":"label","label":"注意②","text":""},{"t":"line","text":"此类动词还有「歩く」、「泳ぐ」、「散歩する」、「飛ぶ」、「登る」、「走る」、「旅行する」等。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"表示动作的起点、出发点。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"わたしは今日6時に会社を出ます。【2005年真题】/我今天六点离开公司。","furi":"わたしは<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>6<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>に<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>ます。【2005年真题】/我今天六点离开公司。"},{"t":"line","text":"7時に家を出ます。【2002年真题】/七点从家里出门。","furi":"7<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>に<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>ます。【2002年真题】/七点从家里出门。"},{"t":"label","label":"注意③","text":""},{"t":"line","text":"此类动词还有「降りる」、「卒業する」、「立つ」等。"}],"id":"N5-54"}]},{"id":"N5-u6","title":"6单元 并列助词、提示助词","points":[{"title":"55. ～と","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词+と+名词","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+と+<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“和……，跟……”。表示物品或者事物的并列。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"この料理は肉と野菜で作ります。【2001年真题】/这道菜是用肉和蔬菜做的。","furi":"この<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>は<ruby>肉<rp>(</rp><rt>にく</rt><rp>)</rp></ruby>と<ruby>野菜<rp>(</rp><rt>やさい</rt><rp>)</rp></ruby>で<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>ります。【2001年真题】/这道菜是用肉和蔬菜做的。"},{"t":"line","text":"机の上に鉛筆とノートと教科書があります。/书桌上有铅笔、笔记本和课本。","furi":"<ruby>机<rp>(</rp><rt>つくえ</rt><rp>)</rp></ruby>の<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>に<ruby>鉛筆<rp>(</rp><rt>えんぴつ</rt><rp>)</rp></ruby>とノートと<ruby>教科書<rp>(</rp><rt>きょうかしょ</rt><rp>)</rp></ruby>があります。/书桌上有铅笔、笔记本和课本。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"用来表示完全列举，一般在列举的事物数目不超过3个时使用。"}],"id":"N5-55"},{"title":"56. ～や","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词+や+名词（+など）","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+や+<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>（+など）"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“和……，或……”。表示对于代表性事物的部分列举，暗示还有其他。构成句型为「～や～（や～）（～など）」，后面的「～や」和「～など」可以省略。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"日曜日に掃除や洗濯をします。【2007年真题】/周日就在家打扫房间或洗衣服什么的。","furi":"<ruby>日曜日<rp>(</rp><rt>にちようび</rt><rp>)</rp></ruby>に<ruby>掃除<rp>(</rp><rt>そうじ</rt><rp>)</rp></ruby>や<ruby>洗濯<rp>(</rp><rt>せんたく</rt><rp>)</rp></ruby>をします。【2007年真题】/周日就在家打扫房间或洗衣服什么的。"},{"t":"line","text":"兄の部屋にはラジオやテレビなどがあります。【2005年真题】/哥哥房间里有收音机和电视机等电器。","furi":"<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>の<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>にはラジオやテレビなどがあります。【2005年真题】/哥哥房间里有收音机和电视机等电器。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"相对于「と」的完全列举，「や」为不完全列举，一般在所列举的事物超过3个时使用。"}],"id":"N5-56"},{"title":"57. ～か","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词+か、名词（+か）+格助词","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+か、<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>（+か）+<ruby>格<rp>(</rp><rt>かく</rt><rp>)</rp></ruby><ruby>助<rp>(</rp><rt>じょ</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":""},{"t":"line","text":"表示从2个或者3个事物中选取一个，表示选择。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"今日か明日、一緒にご飯を食べませんか。【2009年真题】/今天或明天，一起吃个饭吧。","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>か<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>、<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>にご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べませんか。【2009年真题】/今天或明天，一起吃个饭吧。"},{"t":"line","text":"この料理は牛肉か豚肉を使います。【2007年真题】/做这道菜要用牛肉或者猪肉。","furi":"この<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>は<ruby>牛肉<rp>(</rp><rt>ぎゅうにく</rt><rp>)</rp></ruby>か<ruby>豚肉<rp>(</rp><rt>ぶたにく</rt><rp>)</rp></ruby>を<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>います。【2007年真题】/做这道菜要用牛肉或者猪肉。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"并列助词「と、や」都没有表示选择的意思。另外「A+か+Aない/A的反义词+か」的句型意为“是……还是……”。如："},{"t":"line","text":"明日雨が降るか降らないかはわかりません。【2005年真题】/不知道明天下不下雨。"}],"id":"N5-57"},{"title":"58. ～も","blocks":[{"t":"label","label":"接续①","text":""},{"t":"line","text":"名词+も","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+も"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"“也……，都……”，表示同类事物的列举或叠加。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"ご飯もパンもよく食べます。【2008年真题】/饭和面包都经常吃。","furi":"ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>もパンもよく<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べます。【2008年真题】/饭和面包都经常吃。"},{"t":"line","text":"銀行へもデパートへも行きませんでした。【2007年真题】/银行和商场都没去。","furi":"<ruby>銀行<rp>(</rp><rt>ぎんこう</rt><rp>)</rp></ruby>へもデパートへも<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きませんでした。【2007年真题】/银行和商场都没去。"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"此用法的「も」出现在肯定句中表示全盘肯定，出现在否定句中表示全盘否定。"},{"t":"label","label":"接续②","text":""},{"t":"line","text":"数量词+も","furi":"<ruby>数量<rp>(</rp><rt>すうりょう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+も"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"“也……，竟……”，强调数量之多或者数量之少。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"一つのクラスには学生が50人もいました。/一个班级里竟然有五十个学生。","furi":"<ruby>一<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>つのクラスには<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>が50<ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>もいました。/一个班级里竟然有五十个学生。"},{"t":"line","text":"パーティーに日本人は一人も来ていません。【2009年真题】/聚会上一个日本人也没来。","furi":"パーティーに<ruby>日本人<rp>(</rp><rt>にっぽんじん</rt><rp>)</rp></ruby>は<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>も<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ていません。【2009年真题】/聚会上一个日本人也没来。"}],"id":"N5-58"},{"title":"59. は","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词（+助词に、へ、で、と、から、まで）+は","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>（+<ruby>助<rp>(</rp><rt>じょ</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>に、へ、で、と、から、まで）+は"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"「は」用来提示主题，并对主题进行说明和判断。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"わたしの部屋はあまりきれいじゃありません。【2006年真题】/我的房间不太整洁。","furi":"わたしの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>はあまりきれいじゃありません。【2006年真题】/我的房间不太整洁。"},{"t":"line","text":"一番大変な仕事は何ですか。【2007年真题】/最困难的工作是什么？","furi":"<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby><ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>な<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>ですか。【2007年真题】/最困难的工作是什么？"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"「～は～が～」句型可以用来说明主题的某种状态。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"兄は背が高いです。【2007年真题】/哥哥个子高。","furi":"<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>は<ruby>背<rp>(</rp><rt>せ</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いです。【2007年真题】/哥哥个子高。"},{"t":"line","text":"明日は雪が降るでしょう。【2006年真题】/明天会下雪吧。","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>は<ruby>雪<rp>(</rp><rt>ゆき</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>るでしょう。【2006年真题】/明天会下雪吧。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"「～は～（が）、～は～」句型可以用来进行两种事物的比较。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"山田さんはテニスはしますが、ゴルフはしません。【2007年真题】/山田打网球，不过不打高尔夫。","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby>さんはテニスはしますが、ゴルフはしません。【2007年真题】/山田打网球，不过不打高尔夫。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「は」和「が」的区别"},{"t":"sub","text":"① 提示主题用「は」，提示主语用「が」。"},{"t":"line","text":"象は鼻が長いです。/大象鼻子长。"},{"t":"sub","text":"② 对主题进行说明判断时用「は」，陈述眼前看到的、听到的、实际感受到的事情时用「が」。"},{"t":"line","text":"東北地方の雪は多いです。/东北地区雪下得多。"},{"t":"line","text":"今、雪が降っています。/现在正在下雪。"},{"t":"sub","text":"③ 提示已知事物用「は」，未知事物用「が」。"},{"t":"line","text":"机の上に日本語の教科書があります。それは王さんのです。/桌上有本日语教科书，那是小王的。"},{"t":"line","text":"どの人が山下さんですか。【2006年真题】/哪位是山下先生（小姐）？"},{"t":"sub","text":"④ 「は」的指示范围涉及全句，即关联句末的谓语，可以说是句子的大主语；「が」可指示分句中主语，也可以称作是此类句子的小主语。"},{"t":"line","text":"母が作るサンドイッチはおいしいです。【2007年真题】/妈妈做的三明治很好吃。"},{"t":"line","text":"先週は宿題が多くて大変でした。【2006年真题】/上周作业很多，忙死了。"}],"id":"N5-59"},{"title":"60. ～しか～ない","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词普通形/名词（+助词）+しか～ない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>（+<ruby>助<rp>(</rp><rt>じょ</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>）+しか～ない"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“只有……”，表示限定。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"雪がたくさん降ったから、一人しか来ませんでした。【2005年真题】/因为下了大雪，所以只来了一个人。","furi":"<ruby>雪<rp>(</rp><rt>ゆき</rt><rp>)</rp></ruby>がたくさん<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>ったから、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>しか<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ませんでした。【2005年真题】/因为下了大雪，所以只来了一个人。"},{"t":"line","text":"この部屋には椅子が一つしかありません。【2003年真题】/这个房间里只有一把椅子。","furi":"この<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>には<ruby>椅子<rp>(</rp><rt>いす</rt><rp>)</rp></ruby>が<ruby>一<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>つしかありません。【2003年真题】/这个房间里只有一把椅子。"},{"t":"line","text":"このパーティーはチケットを買った人しか入れません。/这个派对只有买了票的人才能入场。","furi":"このパーティーはチケットを<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>った<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>しか<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>れません。/这个派对只有买了票的人才能入场。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"此句型含有说话人感觉不满意的语感，所以一般用于消极场合。"}],"id":"N5-60"},{"title":"61. ～だけ","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词普通形/い形容词普通形/な形容词词干+な/名词+だけ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+だけ"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“只有”，表示限定。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"高いケーキを1つだけ買いました。【2009年真题】/就买了一个昂贵的蛋糕。","furi":"<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いケーキを1つだけ<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いました。【2009年真题】/就买了一个昂贵的蛋糕。"},{"t":"line","text":"小川さんだけお酒を飲みます。【2002年真题】/只有小川喝酒。","furi":"<ruby>小川<rp>(</rp><rt>おがわ</rt><rp>)</rp></ruby>さんだけお<ruby>酒<rp>(</rp><rt>さけ</rt><rp>)</rp></ruby>を<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みます。【2002年真题】/只有小川喝酒。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"此句型包含说话人不满的语气很少，更多的用于描述客观事实。"}],"id":"N5-61"},{"title":"62. ～くらい/ぐらい","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词+くらい/ぐらい","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+くらい/ぐらい"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“大约、大概、左右”等。可用来表示大概的时间、数量、程度等。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"駅で友だちを1時間くらい待ちました。【2009年真题】/在车站等了朋友一个小时左右。","furi":"<ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>で<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちを1<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>くらい<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ちました。【2009年真题】/在车站等了朋友一个小时左右。"},{"t":"line","text":"花の写真を10枚ぐらい撮りました。【2007年真题】/拍了大约十张花儿的照片。","furi":"<ruby>花<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>の<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>を10<ruby>枚<rp>(</rp><rt>まい</rt><rp>)</rp></ruby>ぐらい<ruby>撮<rp>(</rp><rt>と</rt><rp>)</rp></ruby>りました。【2007年真题】/拍了大约十张花儿的照片。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「～くらい/ぐらい」表示程度的用法，详见N3第23条语法条目。"}],"id":"N5-62"},{"title":"63. ～など","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词+など","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+など"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“……等等”。用于列举，暗示除此之外还有其他事物存在。经常和「や」一起使用，构成「～や～など」的句型。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"兄の部屋にはラジオやテレビなどがあります。【2005年真题】/哥哥房间里有收音机和电视机等。","furi":"<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>の<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>にはラジオやテレビなどがあります。【2005年真题】/哥哥房间里有收音机和电视机等。"},{"t":"line","text":"かばんの中に財布や鍵などがあります。【2003年真题】/包里有钱包和钥匙等。","furi":"かばんの<ruby>中<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>に<ruby>財布<rp>(</rp><rt>さいふ</rt><rp>)</rp></ruby>や<ruby>鍵<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>などがあります。【2003年真题】/包里有钱包和钥匙等。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"人物并列时，不能用「など」。另外，一个句子中只能用一个「など」，即没有「～など、～など」的用法。"}],"id":"N5-63"}]},{"id":"N5-u7","title":"7单元 接续助词、终助词","points":[{"title":"64. が","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"表示逆接，即后项事物的出现和一般常理不符。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"30分待ちましたが、バスは来ませんでした。【2003年真题】/等了三十分钟，公交车却没来。","furi":"30<ruby>分<rp>(</rp><rt>ふん</rt><rp>)</rp></ruby><ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ちましたが、バスは<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ませんでした。【2003年真题】/等了三十分钟，公交车却没来。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"前后两个句子互为对照。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"山田さんはテニスはしますが、ゴルフはしません。【2007年真题】/山田打网球，不过不打高尔夫。","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby>さんはテニスはしますが、ゴルフはしません。【2007年真题】/山田打网球，不过不打高尔夫。"},{"t":"line","text":"わたしはよく旅行をしますが、兄はあまりしません。【2008年真题】/我经常旅游，不过哥哥不太去。","furi":"わたしはよく<ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>をしますが、<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>はあまりしません。【2008年真题】/我经常旅游，不过哥哥不太去。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"用于引出话题。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"すみませんが、少し静かにしてください。【2002年真题】/不好意思，请稍微安静点。","furi":"すみませんが、<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かにしてください。【2002年真题】/不好意思，请稍微安静点。"}],"id":"N5-64"},{"title":"65. ても/でも","blocks":[{"t":"label","label":"接续①","text":""},{"t":"line","text":"作为接续词使用"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"“即使……，但是……”。作为接续词使用，表示逆接。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"図書館で3時間勉強しました。でも、うちではしませんでした。【2006年真题】/在图书馆学习了三个小时。不过，在家里没有学习。","furi":"<ruby>図書館<rp>(</rp><rt>としょかん</rt><rp>)</rp></ruby>で3<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby><ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>しました。でも、うちではしませんでした。【2006年真题】/在图书馆学习了三个小时。不过，在家里没有学习。"},{"t":"line","text":"父に電話をしました。でも、友だちにはしませんでした。【2003年真题】/给爸爸打了电话。但是，没有给朋友打。","furi":"<ruby>父<rp>(</rp><rt>ちち</rt><rp>)</rp></ruby>に<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>をしました。でも、<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちにはしませんでした。【2003年真题】/给爸爸打了电话。但是，没有给朋友打。"},{"t":"label","label":"接续②","text":""},{"t":"line","text":"动词「て形」+も","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>」+も"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"“不管都……”、“就算也……”。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"あの美術館はいつ行っても人がたくさんいます。【2007年真题】/无论何时去那座美术馆都有很多人。","furi":"あの<ruby>美術館<rp>(</rp><rt>びじゅつかん</rt><rp>)</rp></ruby>はいつ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>っても<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>がたくさんいます。【2007年真题】/无论何时去那座美术馆都有很多人。"},{"t":"line","text":"学校を卒業しても、日本語の勉強を続けていくつもりだ。【2005年真题】/就算毕业了也打算继续学日语。","furi":"<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>を<ruby>卒業<rp>(</rp><rt>そつぎょう</rt><rp>)</rp></ruby>しても、<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>を<ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>けていくつもりだ。【2005年真题】/就算毕业了也打算继续学日语。"},{"t":"label","label":"注意②","text":""},{"t":"line","text":"「～ても」表示让步，前项的条件不会对后项的事实造成影响。"},{"t":"label","label":"接续③","text":""},{"t":"line","text":"疑问词+ても","furi":"<ruby>疑<rp>(</rp><rt>うたぐ</rt><rp>)</rp></ruby><ruby>问<rp>(</rp><rt>问</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+ても"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"“无论……”、“不管……”。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"私はどこでも寝られます。【2006年真题】/我不管在哪儿都能睡着。","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>はどこでも<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>られます。【2006年真题】/我不管在哪儿都能睡着。"},{"t":"line","text":"私は何でも食べられます。【2003年真题】/我什么都能吃。","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>でも<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べられます。【2003年真题】/我什么都能吃。"},{"t":"label","label":"注意③","text":""},{"t":"line","text":"「～でも」在这种情况下表示在某一类事物中不特指某一个。"}],"id":"N5-65"},{"title":"66. けれども/けど/けれど","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“但是……，可是……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"玄関のベルが鳴ったけれど今頃誰だろう。【2000年真题】/门铃响了，可都到这时候了，会是谁呢？","furi":"<ruby>玄関<rp>(</rp><rt>げんかん</rt><rp>)</rp></ruby>のベルが<ruby>鳴<rp>(</rp><rt>な</rt><rp>)</rp></ruby>ったけれど<ruby>今頃<rp>(</rp><rt>いまごろ</rt><rp>)</rp></ruby><ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>だろう。【2000年真题】/门铃响了，可都到这时候了，会是谁呢？"},{"t":"line","text":"顔色が悪いけどどうしたの。【2000年真题】/你脸色不好呀，怎么了？","furi":"<ruby>顔色<rp>(</rp><rt>かおいろ</rt><rp>)</rp></ruby>が<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>いけどどうしたの。【2000年真题】/你脸色不好呀，怎么了？"},{"t":"line","text":"友だちとの約束を守りたいけれども、突然のことで行けなくなりました。/虽然想要遵守和朋友的约定，但是因为突发的事情而去不了了。","furi":"<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちとの<ruby>約束<rp>(</rp><rt>やくそく</rt><rp>)</rp></ruby>を<ruby>守<rp>(</rp><rt>まも</rt><rp>)</rp></ruby>りたいけれども、<ruby>突然<rp>(</rp><rt>とつぜん</rt><rp>)</rp></ruby>のことで<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>けなくなりました。/虽然想要遵守和朋友的约定，但是因为突发的事情而去不了了。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「けれども/けど/けれど」意思跟表示转折的「が」很相似，多用于口语。"}],"id":"N5-66"},{"title":"67. しかし","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“但是……，不过……”，表示转折。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"飛行機はスピードが速いです。しかし、値段が高いです。/飞机速度很快，但是票价太贵了。","furi":"<ruby>飛行機<rp>(</rp><rt>ひこうき</rt><rp>)</rp></ruby>はスピードが<ruby>速<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>いです。しかし、<ruby>値段<rp>(</rp><rt>ねだん</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いです。/飞机速度很快，但是票价太贵了。"},{"t":"line","text":"この部屋はきれいです。しかし、ちょっと狭いです。/这间房间很漂亮，但是有点小。","furi":"この<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>はきれいです。しかし、ちょっと<ruby>狭<rp>(</rp><rt>せま</rt><rp>)</rp></ruby>いです。/这间房间很漂亮，但是有点小。"},{"t":"line","text":"この仕事は忙しいです。しかし、面白いです。/这份工作很忙碌，但是很有意思。","furi":"この<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>は<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しいです。しかし、<ruby>面白<rp>(</rp><rt>おもしろ</rt><rp>)</rp></ruby>いです。/这份工作很忙碌，但是很有意思。"}],"id":"N5-67"},{"title":"68. ～から","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"句子的简体形/敬体形+から","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>简<rp>(</rp><rt>简</rt><rp>)</rp></ruby><ruby>体形<rp>(</rp><rt>たいけい</rt><rp>)</rp></ruby>/<ruby>敬<rp>(</rp><rt>けい</rt><rp>)</rp></ruby><ruby>体形<rp>(</rp><rt>たいけい</rt><rp>)</rp></ruby>+から"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“因为……，由于……”，表示原因、理由。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"今日はいい天気だから、洗濯しましょう。【2009年真题】/今天是好天气，那就洗衣服吧。","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>はいい<ruby>天気<rp>(</rp><rt>てんき</rt><rp>)</rp></ruby>だから、<ruby>洗濯<rp>(</rp><rt>せんたく</rt><rp>)</rp></ruby>しましょう。【2009年真题】/今天是好天气，那就洗衣服吧。"},{"t":"line","text":"忙しいから、ご飯を食べる時間がありません。【2008年真题】/太忙了，连吃饭的时间都没有。","furi":"<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しいから、ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>がありません。【2008年真题】/太忙了，连吃饭的时间都没有。"},{"t":"line","text":"電車が止まりました。雪がたくさん降ったからです。【2007年真题】/电车停了，因为雪下得太大了。","furi":"<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>が<ruby>止<rp>(</rp><rt>と</rt><rp>)</rp></ruby>まりました。<ruby>雪<rp>(</rp><rt>ゆき</rt><rp>)</rp></ruby>がたくさん<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>ったからです。【2007年真题】/电车停了，因为雪下得太大了。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「から」提示的原因、理由主要是说话人的个人主观行为的理由，因此后面的句子也多数是表示说话人的请求、愿望、推测、主张等的内容。"}],"id":"N5-68"},{"title":"69. ～ので","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词普通形/い形容词普通形/な形容词词干+な/名词/各词类「た形」/句子的简体形・敬体形+ので","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>各<rp>(</rp><rt>かく</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>「た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>」/<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>简<rp>(</rp><rt>简</rt><rp>)</rp></ruby><ruby>体形<rp>(</rp><rt>たいけい</rt><rp>)</rp></ruby>・<ruby>敬<rp>(</rp><rt>けい</rt><rp>)</rp></ruby><ruby>体形<rp>(</rp><rt>たいけい</rt><rp>)</rp></ruby>+ので"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“因为……，由于……”，表示客观的原因、理由。语气比「から」委婉。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"主人が今出張中なので、うちにはいません。/我老公去出差了，所以不在家。","furi":"<ruby>主人<rp>(</rp><rt>しゅじん</rt><rp>)</rp></ruby>が<ruby>今<rp>(</rp><rt>こん</rt><rp>)</rp></ruby><ruby>出張<rp>(</rp><rt>しゅっちょう</rt><rp>)</rp></ruby><ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby>なので、うちにはいません。/我老公去出差了，所以不在家。"},{"t":"line","text":"今度の試験がとても難しかったので、合格しませんでした。/这次考试太难了，所以没有及格。","furi":"<ruby>今度<rp>(</rp><rt>こんど</rt><rp>)</rp></ruby>の<ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>がとても<ruby>難<rp>(</rp><rt>むずか</rt><rp>)</rp></ruby>しかったので、<ruby>合格<rp>(</rp><rt>ごうかく</rt><rp>)</rp></ruby>しませんでした。/这次考试太难了，所以没有及格。"},{"t":"line","text":"風邪を引いたので、病院へ行きました。/感冒了，所以去医院了。","furi":"<ruby>風邪<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>を<ruby>引<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>いたので、<ruby>病院<rp>(</rp><rt>びょういん</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きました。/感冒了，所以去医院了。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「ので」所列举的原因、理由比较客观，因此后项不能用命令、禁止等表达方式。"}],"id":"N5-69"},{"title":"70. て/で","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"い形容词词干+くて","furi":"い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+くて"},{"t":"line","text":"名词/な形容词词干+で","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+で"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"表示中顿。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"この辺は夏は涼しくて、冬は暖かいです。【2009年真题】/这附近冬暖夏凉。","furi":"この<ruby>辺<rp>(</rp><rt>あたり</rt><rp>)</rp></ruby>は<ruby>夏<rp>(</rp><rt>なつ</rt><rp>)</rp></ruby>は<ruby>涼<rp>(</rp><rt>すず</rt><rp>)</rp></ruby>しくて、<ruby>冬<rp>(</rp><rt>ふゆ</rt><rp>)</rp></ruby>は<ruby>暖<rp>(</rp><rt>あたた</rt><rp>)</rp></ruby>かいです。【2009年真题】/这附近冬暖夏凉。"},{"t":"line","text":"妹は17歳で、学生です。【2007年真题】/我妹妹十七岁，是学生。","furi":"<ruby>妹<rp>(</rp><rt>いもうと</rt><rp>)</rp></ruby>は17<ruby>歳<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>で、<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>です。【2007年真题】/我妹妹十七岁，是学生。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"表示并列。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"わたしのアパートは静かでいいです。【2007年真题】/我住的公寓安静又舒适。","furi":"わたしのアパートは<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かでいいです。【2007年真题】/我住的公寓安静又舒适。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"表示轻微的原因。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"この道は暗くて危ないです。【2008年真题】/这条路很黑，有点危险。","furi":"この<ruby>道<rp>(</rp><rt>みち</rt><rp>)</rp></ruby>は<ruby>暗<rp>(</rp><rt>くら</rt><rp>)</rp></ruby>くて<ruby>危<rp>(</rp><rt>あぶ</rt><rp>)</rp></ruby>ないです。【2008年真题】/这条路很黑，有点危险。"},{"t":"line","text":"先週は宿題が多くて大変でした。【2006年真题】/上周作业很多，真够呛。","furi":"<ruby>先週<rp>(</rp><rt>せんしゅう</rt><rp>)</rp></ruby>は<ruby>宿題<rp>(</rp><rt>しゅくだい</rt><rp>)</rp></ruby>が<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>くて<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>でした。【2006年真题】/上周作业很多，真够呛。"}],"id":"N5-70"},{"title":"71. ～ながら","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词「ます形」+ながら","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>」+ながら"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“一边……，一边……”。表示进行某项动作、行为的同时，进行另一项动作、行为。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"何か飲みながら、話をしましょう。【2008年真题】/边喝点东西边谈吧。","furi":"<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>か<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みながら、<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>をしましょう。【2008年真题】/边喝点东西边谈吧。"},{"t":"line","text":"わたしは音楽を聞きながら勉強をします。【2007年真题】/我一边听音乐一边学习。","furi":"わたしは<ruby>音楽<rp>(</rp><rt>おんがく</rt><rp>)</rp></ruby>を<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>きながら<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>をします。【2007年真题】/我一边听音乐一边学习。"}],"id":"N5-71"},{"title":"72. それに","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“而且……”、“还有……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"この道は狭い。それに、車が多くて危ない。【2003年真题】/这条路很窄，而且车很多，很危险。","furi":"この<ruby>道<rp>(</rp><rt>みち</rt><rp>)</rp></ruby>は<ruby>狭<rp>(</rp><rt>せま</rt><rp>)</rp></ruby>い。それに、<ruby>車<rp>(</rp><rt>くるま</rt><rp>)</rp></ruby>が<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>くて<ruby>危<rp>(</rp><rt>あぶ</rt><rp>)</rp></ruby>ない。【2003年真题】/这条路很窄，而且车很多，很危险。"},{"t":"line","text":"東京は人が多いし、それに物価も高いので、住みにくいです。/东京人很多，物价又贵，不适合居住。","furi":"<ruby>東京<rp>(</rp><rt>とうきょう</rt><rp>)</rp></ruby>は<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>いし、それに<ruby>物価<rp>(</rp><rt>ぶっか</rt><rp>)</rp></ruby>も<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いので、<ruby>住<rp>(</rp><rt>す</rt><rp>)</rp></ruby>みにくいです。/东京人很多，物价又贵，不适合居住。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「それに」用于同类事物的列举。"}],"id":"N5-72"},{"title":"73. それとも","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“是……还是……？”，放在两个疑问句中间。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"明日は雨ですか。それとも、晴れですか。/明天是下雨天还是晴天？","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>は<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>ですか。それとも、<ruby>晴<rp>(</rp><rt>は</rt><rp>)</rp></ruby>れですか。/明天是下雨天还是晴天？"},{"t":"line","text":"これは豚肉ですか。それとも、牛肉ですか。/这是猪肉还是牛肉？","furi":"これは<ruby>豚肉<rp>(</rp><rt>ぶたにく</rt><rp>)</rp></ruby>ですか。それとも、<ruby>牛肉<rp>(</rp><rt>ぎゅうにく</rt><rp>)</rp></ruby>ですか。/这是猪肉还是牛肉？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「それとも」只用于选择疑问句。"}],"id":"N5-73"},{"title":"74. それから","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“……然后……”。表示前项动作结束之后，接着做后项的事情。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"朝新聞を読みます。それから、会社へ行きます。/早上读报纸，然后去公司。","furi":"<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby><ruby>新聞<rp>(</rp><rt>しんぶん</rt><rp>)</rp></ruby>を<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>みます。それから、<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。/早上读报纸，然后去公司。"},{"t":"line","text":"田中さんは5時まで会社で働きます。それから、飲み会に行きます。/田中在公司工作到五点，然后去参加聚餐。","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんは5<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>まで<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>で<ruby>働<rp>(</rp><rt>はたら</rt><rp>)</rp></ruby>きます。それから、<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>み<ruby>会<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。/田中在公司工作到五点，然后去参加聚餐。"}],"id":"N5-74"},{"title":"75. ところで","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“对了……”、“话说……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"A「お久しぶりですね。」/“好久不见。”","furi":"A「お<ruby>久<rp>(</rp><rt>ひさ</rt><rp>)</rp></ruby>しぶりですね。」/“好久不见。”"},{"t":"line","text":"B「そうですね。」/“是啊。”"},{"t":"line","text":"A「ところで、もう結婚したと聞きましたよ、おめでとう。」/“对了，听说你已经结婚了，恭喜啊。”","furi":"A「ところで、もう<ruby>結婚<rp>(</rp><rt>けっこん</rt><rp>)</rp></ruby>したと<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>きましたよ、おめでとう。」/“对了，听说你已经结婚了，恭喜啊。”"},{"t":"line","text":"会議はこれで終わります。ところで、取引先のお客さんはまだ来ませんか。/会议到此结束。话说，客户还没来吗？","furi":"<ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby>はこれで<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わります。ところで、<ruby>取引<rp>(</rp><rt>とりひき</rt><rp>)</rp></ruby><ruby>先<rp>(</rp><rt>さき</rt><rp>)</rp></ruby>のお<ruby>客<rp>(</rp><rt>きゃく</rt><rp>)</rp></ruby>さんはまだ<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ませんか。/会议到此结束。话说，客户还没来吗？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「ところで」用于转移话题，常用在段落开头或是对话中途停顿后的开头。"}],"id":"N5-75"},{"title":"76. それで","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“所以……”、“因此……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"医者「川田さん、晩ご飯を食べ過ぎませんでしたか。」/“川田，晚饭是不是吃多了？”","furi":"<ruby>医者<rp>(</rp><rt>いしゃ</rt><rp>)</rp></ruby>「<ruby>川田<rp>(</rp><rt>かわた</rt><rp>)</rp></ruby>さん、<ruby>晩<rp>(</rp><rt>ばん</rt><rp>)</rp></ruby>ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べ<ruby>過<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ぎませんでしたか。」/“川田，晚饭是不是吃多了？”"},{"t":"line","text":"川田「ああ…。おいしかったから、ご飯を5杯食べました。」/“啊……因为太好吃了，就吃了五碗饭。”","furi":"<ruby>川田<rp>(</rp><rt>かわた</rt><rp>)</rp></ruby>「ああ…。おいしかったから、ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を5<ruby>杯<rp>(</rp><rt>はい</rt><rp>)</rp></ruby><ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べました。」/“啊……因为太好吃了，就吃了五碗饭。”"},{"t":"line","text":"ずっと日本に住むつもりです。それで今、日本語を勉強しています。【2004年真题】/我打算一直住在日本，因此现在正在学日语。","furi":"ずっと<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>に<ruby>住<rp>(</rp><rt>す</rt><rp>)</rp></ruby>むつもりです。それで<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>、<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>を<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>しています。【2004年真题】/我打算一直住在日本，因此现在正在学日语。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「それで」表示上下文之间的因果关系。"}],"id":"N5-76"},{"title":"77. か","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"「か」作为终助词，读作升调，可以表示疑问、再次确认等语气。读降调，可以表示惊讶、感叹等语气。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"その本をどこで買ったか覚えていますか。【2009年真题】/还记得那本书是在哪里买的吗？","furi":"その<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>をどこで<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ったか<ruby>覚<rp>(</rp><rt>おぼ</rt><rp>)</rp></ruby>えていますか。【2009年真题】/还记得那本书是在哪里买的吗？"},{"t":"line","text":"また遅刻ですか。/又迟到了！","furi":"また<ruby>遅刻<rp>(</rp><rt>ちこく</rt><rp>)</rp></ruby>ですか。/又迟到了！"},{"t":"label","label":"注意","text":""},{"t":"line","text":"可以用「～ですか、～ですか」或者「～ますか、～ますか」的句型表示选择疑问。如："},{"t":"line","text":"郵便局は、レストランの右ですか、左ですか。【2000年真题】/邮局在餐厅右边还是左边？"}],"id":"N5-77"},{"title":"78. ね","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"可以用来表示轻微的感叹或者征求对方的同意，还可以用来表示叮嘱。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"高いですね。安くしてください。【2009年真题】/真贵，再便宜点吧。","furi":"<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いですね。<ruby>安<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>くしてください。【2009年真题】/真贵，再便宜点吧。"},{"t":"line","text":"昨日は天気がよくなかったですね。【2008年真题】/昨天天气不好啊。","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>は<ruby>天気<rp>(</rp><rt>てんき</rt><rp>)</rp></ruby>がよくなかったですね。【2008年真题】/昨天天气不好啊。"},{"t":"line","text":"子どもが寝ているから、大きい声で歌わないでね。【2000年真题】/孩子在睡觉，不要大声唱歌啊。","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもが<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>ているから、<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きい<ruby>声<rp>(</rp><rt>こえ</rt><rp>)</rp></ruby>で<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>わないでね。【2000年真题】/孩子在睡觉，不要大声唱歌啊。"}],"id":"N5-78"},{"title":"79. よ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"用于提醒对方或向对方提出自己的主张，句末用「よ」来加强语气。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"あ、あそこで鳥が鳴いていますよ。【2007年真题】/啊，那边有鸟儿在叫。","furi":"あ、あそこで<ruby>鳥<rp>(</rp><rt>とり</rt><rp>)</rp></ruby>が<ruby>鳴<rp>(</rp><rt>な</rt><rp>)</rp></ruby>いていますよ。【2007年真题】/啊，那边有鸟儿在叫。"},{"t":"line","text":"もう少し待ったほうがいいですよ。【2008年真题】/再稍微等一下比较好。","furi":"もう<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ったほうがいいですよ。【2008年真题】/再稍微等一下比较好。"},{"t":"line","text":"あのケーキはおいしくなかったよ。【2006年真题】/那种蛋糕不好吃。"}],"id":"N5-79"},{"title":"80. わ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"向对方表示自己的判断、决心。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"それは知りませんわ。/我不知道那件事。","furi":"それは<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>りませんわ。/我不知道那件事。"},{"t":"line","text":"昼ご飯はカレーにしますわ。/午饭我吃咖喱。","furi":"<ruby>昼<rp>(</rp><rt>ひる</rt><rp>)</rp></ruby>ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>はカレーにしますわ。/午饭我吃咖喱。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"女性用语，用在句末可以使语气委婉、柔和。"}],"id":"N5-80"},{"title":"81. かな/かしら","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“……吗？”"},{"t":"label","label":"例文","text":""},{"t":"line","text":"山田選手は今回の試合に出るかな。/山田选手会参加这次比赛吗？","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby><ruby>選手<rp>(</rp><rt>せんしゅ</rt><rp>)</rp></ruby>は<ruby>今回<rp>(</rp><rt>こんかい</rt><rp>)</rp></ruby>の<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>に<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>るかな。/山田选手会参加这次比赛吗？"},{"t":"line","text":"その荷物を持ってくれないかな。/能帮我拿一下那件行李吗？","furi":"その<ruby>荷物<rp>(</rp><rt>にもつ</rt><rp>)</rp></ruby>を<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>ってくれないかな。/能帮我拿一下那件行李吗？"},{"t":"line","text":"今度の休みはどこへ行こうかしら。/这次假期要去哪里呢？","furi":"<ruby>今度<rp>(</rp><rt>こんど</rt><rp>)</rp></ruby>の<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>みはどこへ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>こうかしら。/这次假期要去哪里呢？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「かな」用于句末，表示疑惑和不确定的态度；多用于自言自语，用于对话时则表示间接提出请求或期望。是比较随意的口语形式，前面不接礼貌体。「かしら」属于女性用语。"}],"id":"N5-81"}]},{"id":"N5-u8","title":"8单元 接尾词、副词","points":[{"title":"82. 时间+すぎ/まえ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"「すぎ/まえ」接在表示时间的词后面，表示时间上的偏差。「すぎ」表示比参照时间延后，「まえ」表示比参照时间提前。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"10時すぎに王さんが来ました。/十点多的时候，小王来了。","furi":"10<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>すぎに<ruby>王<rp>(</rp><rt>おう</rt><rp>)</rp></ruby>さんが<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>ました。/十点多的时候，小王来了。"},{"t":"line","text":"今9時10分まえです。/现在是九点差十分。","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>9<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>10<ruby>分<rp>(</rp><rt>ふん</rt><rp>)</rp></ruby>まえです。/现在是九点差十分。"},{"t":"line","text":"今9時10分すぎです。/现在是九点过十分。","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>9<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>10<ruby>分<rp>(</rp><rt>ふん</rt><rp>)</rp></ruby>すぎです。/现在是九点过十分。"}],"id":"N5-82"},{"title":"83. ～たち/がた","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“……们”。「たち/がた」接在人称词后面，表示复数。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"子どもたちが歌を上手に歌っています。【2009年真题】/孩子们娴熟地唱着歌。","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもたちが<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>を<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>に<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>っています。【2009年真题】/孩子们娴熟地唱着歌。"},{"t":"line","text":"ここが、あなた方の部屋です。【2000年真题】/这里是你们的房间。","furi":"ここが、あなた<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>の<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>です。【2000年真题】/这里是你们的房间。"},{"t":"line","text":"先生方、おはようございます。/老师们，早上好。","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby><ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>、おはようございます。/老师们，早上好。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「がた」的尊敬语气更强，因此只能接在表示第二、第三人称的人称词后面。"}],"id":"N5-83"},{"title":"84. ～中","blocks":[{"t":"label","label":"说明","text":""},{"t":"sub","text":"① 读作「ちゅう」的场合："},{"t":"line","text":"接在一定时间内可以持续的动作性名词后，表示动作正在进行中；"},{"t":"line","text":"接在表示时间、空间的词语之后，表示“之内、之中”的意思。"},{"t":"sub","text":"② 读作「じゅう」的场合："},{"t":"line","text":"接在表示时间、空间的词语之后，表示“整个、全部”的意思。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"授業中だから、静かにしてください。【2000年真题】/上课期间，请保持安静。","furi":"<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby><ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby>だから、<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かにしてください。【2000年真题】/上课期间，请保持安静。"},{"t":"line","text":"あの山には一年じゅう雪があります。【2004年真题】/那山上一年四季都有雪。","furi":"あの<ruby>山<rp>(</rp><rt>やま</rt><rp>)</rp></ruby>には<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>じゅう<ruby>雪<rp>(</rp><rt>ゆき</rt><rp>)</rp></ruby>があります。【2004年真题】/那山上一年四季都有雪。"},{"t":"line","text":"1日じゅう仕事をして、疲れました。【2004年真题】/工作了整整一天，累了。","furi":"1<ruby>日<rp>(</rp><rt>にち</rt><rp>)</rp></ruby>じゅう<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>をして、<ruby>疲<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>れました。【2004年真题】/工作了整整一天，累了。"},{"t":"label","label":"补充","text":""},{"t":"sub","text":"① 常见的「～ちゅう」的词汇"},{"t":"line","text":"運転ちゅう・営業ちゅう・お話ちゅう・会議ちゅう・検討ちゅう・工事ちゅう・受験ちゅう・出張ちゅう・食事ちゅう・調査ちゅう・電話ちゅう・病気ちゅう・勉強ちゅう・休みちゅう・～月ちゅう・午前ちゅう・今月ちゅう・水ちゅう"},{"t":"sub","text":"② 常见的「～じゅう」的词汇"},{"t":"line","text":"家じゅう・教室じゅう・学校じゅう・世界じゅう・パートじゅう・町じゅう・店じゅう・村じゅう・一か月じゅう・一年じゅう・今月じゅう・今週じゅう・半年じゅう・部屋じゅう"}],"id":"N5-84"},{"title":"85. ～人にん/じん/ひと","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"「にん」的前面多接数词，而「じん」的前面大多接国名或地名，「ひと」通常单独使用。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"1つの会議室に20人入れます。【2008年真题】/一间会议室可容纳二十人。","furi":"1つの<ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby><ruby>室<rp>(</rp><rt>しつ</rt><rp>)</rp></ruby>に20<ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby><ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>れます。【2008年真题】/一间会议室可容纳二十人。"},{"t":"line","text":"山田さんは日本人です。/山田是日本人。","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby>さんは<ruby>日本人<rp>(</rp><rt>にっぽんじん</rt><rp>)</rp></ruby>です。/山田是日本人。"},{"t":"line","text":"あのレストランは予約した人しか入れません。【2008年真题】/那家饭店只有预约过的人可以进入。","furi":"あのレストランは<ruby>予約<rp>(</rp><rt>よやく</rt><rp>)</rp></ruby>した<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>しか<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>れません。【2008年真题】/那家饭店只有预约过的人可以进入。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"一个人和两个人有特殊说法，即「ひとり」、「ふたり」。"}],"id":"N5-85"},{"title":"86. ～ずつ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“每……”；“一点一点地……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"1人に1つずつ、ケーキを分けましょう。/一人一个把蛋糕分了吧。","furi":"1<ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>に1つずつ、ケーキを<ruby>分<rp>(</rp><rt>わ</rt><rp>)</rp></ruby>けましょう。/一人一个把蛋糕分了吧。"},{"t":"line","text":"日本語が少しずつ上手になりました。/日语一点一点地进步了。","furi":"<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>が<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>しずつ<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>になりました。/日语一点一点地进步了。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「ずつ」表示“等比例地分发”和“以相同的数量或程度反复”。"}],"id":"N5-86"},{"title":"87. とても","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"后面是肯定表达，意为“非常……”。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"公園の花はとてもきれいだった。【2005年真题】/公园里的花很漂亮。","furi":"<ruby>公園<rp>(</rp><rt>こうえん</rt><rp>)</rp></ruby>の<ruby>花<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>はとてもきれいだった。【2005年真题】/公园里的花很漂亮。"},{"t":"line","text":"今日はとても暑いですね。【2002年真题】/今天真热啊。","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>はとても<ruby>暑<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>いですね。【2002年真题】/今天真热啊。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"后面是否定表达，意为“怎么也……，无论如何也……”。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"とても50歳には見えない。/一点看不出是五十岁了。","furi":"とても50<ruby>歳<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>には<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>えない。/一点看不出是五十岁了。"}],"id":"N5-87"},{"title":"88. あまり","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"后面接肯定表达，意为“非常……，太……”。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"あまりおいしかったので、つい食べ過ぎてしまった。/因为太好吃了，所以不小心就吃多了。","furi":"あまりおいしかったので、つい<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べ<ruby>過<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ぎてしまった。/因为太好吃了，所以不小心就吃多了。"},{"t":"line","text":"あまり慌てると失敗するよ。/太慌张的话，会失败的哦。","furi":"あまり<ruby>慌<rp>(</rp><rt>あわ</rt><rp>)</rp></ruby>てると<ruby>失敗<rp>(</rp><rt>しっぱい</rt><rp>)</rp></ruby>するよ。/太慌张的话，会失败的哦。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"后面要接否定表达，意为“（不）怎么……，（不）太……”。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"たくさんコピーしたから、紙があまりありません。【2009年真题】/因为复印了很多，所以纸剩得不多了。","furi":"たくさんコピーしたから、<ruby>紙<rp>(</rp><rt>かみ</rt><rp>)</rp></ruby>があまりありません。【2009年真题】/因为复印了很多，所以纸剩得不多了。"},{"t":"line","text":"わたしの部屋はあまりきれいじゃありません。【2006年真题】/我的房间不太整洁。","furi":"わたしの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>はあまりきれいじゃありません。【2006年真题】/我的房间不太整洁。"},{"t":"line","text":"昨日はあまり寒くありませんでした。【2003年真题】/昨天不怎么冷。","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>はあまり<ruby>寒<rp>(</rp><rt>さむ</rt><rp>)</rp></ruby>くありませんでした。【2003年真题】/昨天不怎么冷。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「あまり」的口语说法为「あんまり」。"}],"id":"N5-88"},{"title":"89. 少し","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“稍微，暂时；不远，一点”，表示程度轻。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"もう少し静かにしてくださいませんか。【2006年真题】/能安静点吗？","furi":"もう<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かにしてくださいませんか。【2006年真题】/能安静点吗？"},{"t":"line","text":"会社から少し行くと、銀行があります。/公司前面不远处有一家银行。","furi":"<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>から<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くと、<ruby>銀行<rp>(</rp><rt>ぎんこう</rt><rp>)</rp></ruby>があります。/公司前面不远处有一家银行。"}],"id":"N5-89"},{"title":"90. ぜんぜん","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"「ぜんぜん」后接否定表达，表示完全否定。意为“完全（不）……，根本（不）……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"そのことはぜんぜん知りません。/我根本不知道那件事。","furi":"そのことはぜんぜん<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>りません。/我根本不知道那件事。"},{"t":"line","text":"政治についてはぜんぜん興味がない。/对政治完全没兴趣。","furi":"<ruby>政治<rp>(</rp><rt>せいじ</rt><rp>)</rp></ruby>についてはぜんぜん<ruby>興味<rp>(</rp><rt>きょうみ</rt><rp>)</rp></ruby>がない。/对政治完全没兴趣。"}],"id":"N5-90"},{"title":"91. ほとんど","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"作为副词使用，可以表达“大体上，差不多”的意思，也可以表示“差一点儿……，几乎……”的意思。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"仕事はほとんど終わりました。/工作差不多完成了。","furi":"<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>はほとんど<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わりました。/工作差不多完成了。"},{"t":"line","text":"昨日は忙しくて、ほとんど眠れなかった。/昨天太忙了，几乎没睡过。","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>は<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しくて、ほとんど<ruby>眠<rp>(</rp><rt>ねむ</rt><rp>)</rp></ruby>れなかった。/昨天太忙了，几乎没睡过。"}],"id":"N5-91"},{"title":"92. いつも","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“经常，总是”，表示一般的状态或习惯等。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"トイレの掃除はいつもわたしがします。【2008年真题】/厕所的打扫一直是我做。","furi":"トイレの<ruby>掃除<rp>(</rp><rt>そうじ</rt><rp>)</rp></ruby>はいつもわたしがします。【2008年真题】/厕所的打扫一直是我做。"},{"t":"line","text":"このレストランはいつもたくさん人が並んでいますね。【2006年真题】/这家餐厅总是排着很多人啊。","furi":"このレストランはいつもたくさん<ruby>人<rp>(</rp><rt>じん</rt><rp>)</rp></ruby>が<ruby>並<rp>(</rp><rt>なら</rt><rp>)</rp></ruby>んでいますね。【2006年真题】/这家餐厅总是排着很多人啊。"}],"id":"N5-92"},{"title":"93. どうぞ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“请……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"どうぞご覧ください。【2002年真题】/请看。","furi":"どうぞご<ruby>覧<rp>(</rp><rt>らん</rt><rp>)</rp></ruby>ください。【2002年真题】/请看。"},{"t":"line","text":"お茶をどうぞ。/请喝茶。","furi":"お<ruby>茶<rp>(</rp><rt>ちゃ</rt><rp>)</rp></ruby>をどうぞ。/请喝茶。"},{"t":"line","text":"A「この自転車を借りてもいいですか。」/“我可以借用一下这辆自行车吗？”","furi":"A「この<ruby>自転車<rp>(</rp><rt>じてんしゃ</rt><rp>)</rp></ruby>を<ruby>借<rp>(</rp><rt>か</rt><rp>)</rp></ruby>りてもいいですか。」/“我可以借用一下这辆自行车吗？”"},{"t":"line","text":"B「ええ、どうぞ。」/“嗯，你用吧。”"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「どうぞ」表示请对方做某事，后面往往接尊敬的表达方式；关系较亲密的人之间可以省略后面的部分，直接用「どうぞ」结句。"}],"id":"N5-93"},{"title":"94. やっと","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“终于……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"難しい問題でしたが、やっと答えがわかりました。【2008年真题】/问题很难，但是终于知道答案了。","furi":"<ruby>難<rp>(</rp><rt>むずか</rt><rp>)</rp></ruby>しい<ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>でしたが、やっと<ruby>答<rp>(</rp><rt>こた</rt><rp>)</rp></ruby>えがわかりました。【2008年真题】/问题很难，但是终于知道答案了。"},{"t":"line","text":"午後5時頃、雨がやっとやんだ。/下午五点的时候，雨终于停了。","furi":"<ruby>午後<rp>(</rp><rt>ごご</rt><rp>)</rp></ruby>5<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>頃<rp>(</rp><rt>ごろ</rt><rp>)</rp></ruby>、<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>がやっとやんだ。/下午五点的时候，雨终于停了。"},{"t":"line","text":"何週間も勉強しつづけて、やっと試験に合格できるようになりました。/连着学了几周，终于能够及格了。","furi":"<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>週間<rp>(</rp><rt>しゅうかん</rt><rp>)</rp></ruby>も<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>しつづけて、やっと<ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>に<ruby>合格<rp>(</rp><rt>ごうかく</rt><rp>)</rp></ruby>できるようになりました。/连着学了几周，终于能够及格了。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「やっと」表示经过艰苦的努力或是漫长的时间，愿望终于实现；后面经常接动词过去时。多用于表达喜悦、解脱、松了口气等情绪。"}],"id":"N5-94"},{"title":"95. ぜひ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“务必……”、“一定……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"今度の試合はぜひ見たいです。【2008年真题】/这次的比赛我非常想看。","furi":"<ruby>今度<rp>(</rp><rt>こんど</rt><rp>)</rp></ruby>の<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>はぜひ<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>たいです。【2008年真题】/这次的比赛我非常想看。"},{"t":"line","text":"こちらにいらっしゃる機会があったら、ぜひお寄りください。【2005年真题】/有机会到这里来的话，请一定要过来啊。","furi":"こちらにいらっしゃる<ruby>機会<rp>(</rp><rt>きかい</rt><rp>)</rp></ruby>があったら、ぜひお<ruby>寄<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>りください。【2005年真题】/有机会到这里来的话，请一定要过来啊。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「ぜひ」用于自身时表示一定要做某事的强烈愿望，用于对方则表示非常希望对方做某事。"}],"id":"N5-95"},{"title":"96. そろそろ","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“差不多该……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"寒くなったのでそろそろ暖房がほしいですね。【2007年真题】/天气转冷了，差不多也该要个电暖气了。","furi":"<ruby>寒<rp>(</rp><rt>さむ</rt><rp>)</rp></ruby>くなったのでそろそろ<ruby>暖房<rp>(</rp><rt>だんぼう</rt><rp>)</rp></ruby>がほしいですね。【2007年真题】/天气转冷了，差不多也该要个电暖气了。"},{"t":"line","text":"そろそろ食事にしましょう。【2008年真题】/差不多是时间去吃饭了。","furi":"そろそろ<ruby>食事<rp>(</rp><rt>しょくじ</rt><rp>)</rp></ruby>にしましょう。【2008年真题】/差不多是时间去吃饭了。"},{"t":"line","text":"そろそろ失礼いたします。/差不多该告辞了。","furi":"そろそろ<ruby>失礼<rp>(</rp><rt>しつれい</rt><rp>)</rp></ruby>いたします。/差不多该告辞了。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「そろそろ」表示时间上的迫近，即到时间该做某事了。"}],"id":"N5-96"}]},{"id":"N5-u9","title":"9单元 常用表达方式","points":[{"title":"97. ～をください","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词+をください","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+をください"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“给我……，我要……”。表示向别人要什么。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"すみません、お水をください。【2006年真题】/不好意思，请给我水。","furi":"すみません、お<ruby>水<rp>(</rp><rt>みず</rt><rp>)</rp></ruby>をください。【2006年真题】/不好意思，请给我水。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"对应的更礼貌的说法是「～をくださいませんか」。如："},{"t":"line","text":"奨学金の申請用紙をくださいませんか。/能给我奖学金的申请表格吗？"}],"id":"N5-97"},{"title":"98. ～てください/ないでください","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词「て形」+ください","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>」+ください"},{"t":"line","text":"动词「ない形」+ないでください","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>」+ないでください"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“请（不要）……”。表示面对面的请求、命令或指示对方做某事或者不做某事。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"高いですね。もっと安くしてください。【2009年真题】/太贵了，请给我便宜些吧。","furi":"<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いですね。もっと<ruby>安<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>くしてください。【2009年真题】/太贵了，请给我便宜些吧。"},{"t":"line","text":"この言葉を覚えてください。【2007年真题】/请记住这句话。","furi":"この<ruby>言葉<rp>(</rp><rt>ことば</rt><rp>)</rp></ruby>を<ruby>覚<rp>(</rp><rt>おぼ</rt><rp>)</rp></ruby>えてください。【2007年真题】/请记住这句话。"},{"t":"line","text":"テストをしていますから静かにしてください。【2004年真题】/正在考试，所以请保持安静。","furi":"テストをしていますから<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かにしてください。【2004年真题】/正在考试，所以请保持安静。"},{"t":"line","text":"大きな声で話さないでください。【2009年真题】/请不要大声说话。","furi":"<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きな<ruby>声<rp>(</rp><rt>こえ</rt><rp>)</rp></ruby>で<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>さないでください。【2009年真题】/请不要大声说话。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"虽然表示礼貌的请求，但因其本身也带有命令的口气，所以一般不能对上司、长辈等要尊敬的人使用。"}],"id":"N5-98"},{"title":"99. ～てくださいませんか/ないでくださいませんか","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词「て形」+くださいませんか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>」+くださいませんか"},{"t":"line","text":"动词「ない形」+ないでくださいませんか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>」+ないでくださいませんか"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“能否请您……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"すみません、砂糖を取ってくださいませんか。【2007年真题】/不好意思，能递给我糖吗？","furi":"すみません、<ruby>砂糖<rp>(</rp><rt>さとう</rt><rp>)</rp></ruby>を<ruby>取<rp>(</rp><rt>と</rt><rp>)</rp></ruby>ってくださいませんか。【2007年真题】/不好意思，能递给我糖吗？"},{"t":"line","text":"もう少し静かにしてくださいませんか。【2006年真题】/能稍微安静一点吗？","furi":"もう<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かにしてくださいませんか。【2006年真题】/能稍微安静一点吗？"},{"t":"line","text":"わたしのものに触らないでくださいませんか。/请不要动我的东西好吗？","furi":"わたしのものに<ruby>触<rp>(</rp><rt>さわ</rt><rp>)</rp></ruby>らないでくださいませんか。/请不要动我的东西好吗？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"此句型是「～てください/ないでください」对应的更礼貌的说法。"}],"id":"N5-99"},{"title":"100. ～ませんか","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词「ます形」+ませんか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>」+ませんか"},{"t":"label","label":"说明","text":""},{"t":"line","text":"可以用于委婉的建议、劝诱，意为“一起做……好吗？”。用来表示疑问，意为“（你）不……吗？”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"今日か明日、一緒にご飯を食べませんか。【2009年真题】/今天或明天，一起吃个饭吧？","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>か<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>、<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>にご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べませんか。【2009年真题】/今天或明天，一起吃个饭吧？"},{"t":"line","text":"昼ご飯の時間をもっと遅くしませんか。【2005年真题】/把午饭时间稍微推后一点吧？","furi":"<ruby>昼<rp>(</rp><rt>ひる</rt><rp>)</rp></ruby>ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>の<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>をもっと<ruby>遅<rp>(</rp><rt>おそ</rt><rp>)</rp></ruby>くしませんか。【2005年真题】/把午饭时间稍微推后一点吧？"}],"id":"N5-100"},{"title":"101. ～ましょうか","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词「ます形」+ましょうか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>」+ましょうか"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"“一起……吧”，用于邀请对方做某事。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"中山「いますぐ出かけましょうか。」/“现在就出发吧。”","furi":"<ruby>中山<rp>(</rp><rt>なかやま</rt><rp>)</rp></ruby>「いますぐ<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>かけましょうか。」/“现在就出发吧。”"},{"t":"line","text":"上田「いいえ、掃除をしてから出かけましょう。」【2006年真题】/“不，打扫完再出发吧。”","furi":"<ruby>上田<rp>(</rp><rt>うえだ</rt><rp>)</rp></ruby>「いいえ、<ruby>掃除<rp>(</rp><rt>そうじ</rt><rp>)</rp></ruby>をしてから<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>かけましょう。」【2006年真题】/“不，打扫完再出发吧。”"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"“……呢；……啊”，表示委婉的疑问。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"結婚式に誰を招待しましょうか。【2007年真题】/结婚典礼要邀请哪些人啊？","furi":"<ruby>結婚式<rp>(</rp><rt>けっこんしき</rt><rp>)</rp></ruby>に<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>を<ruby>招待<rp>(</rp><rt>しょうたい</rt><rp>)</rp></ruby>しましょうか。【2007年真题】/结婚典礼要邀请哪些人啊？"},{"t":"line","text":"明日のパーティーは、どんな飲み物を準備しましょうか。【2001年真题】/明天的派对，该准备什么饮料呢？","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>のパーティーは、どんな<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>み<ruby>物<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>を<ruby>準備<rp>(</rp><rt>じゅんび</rt><rp>)</rp></ruby>しましょうか。【2001年真题】/明天的派对，该准备什么饮料呢？"},{"t":"label","label":"注意②","text":""},{"t":"line","text":"此种用法和「～ますか」的语法意义基本相同。"}],"id":"N5-101"},{"title":"102. ～ましょう","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词「ます形」+ましょう","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>」+ましょう"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"“……吧”，用于邀请、建议对方做某事。语气比「～ましょうか」强烈。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"この橋を渡って向こうに行きましょう。【2009年真题】/过了这座桥去对面吧。","furi":"この<ruby>橋<rp>(</rp><rt>はし</rt><rp>)</rp></ruby>を<ruby>渡<rp>(</rp><rt>わた</rt><rp>)</rp></ruby>って<ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>こうに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きましょう。【2009年真题】/过了这座桥去对面吧。"},{"t":"line","text":"駅まで一緒に帰りましょう。【2007年真题】/一起走到车站吧。","furi":"<ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>まで<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>りましょう。【2007年真题】/一起走到车站吧。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"“（我）……吧”，用于说话人主动提起做某事。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"わたしの傘をお貸ししましょう。【2001年真题】/我把伞借给你吧。","furi":"わたしの<ruby>傘<rp>(</rp><rt>かさ</rt><rp>)</rp></ruby>をお<ruby>貸<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ししましょう。【2001年真题】/我把伞借给你吧。"}],"id":"N5-102"},{"title":"103. ～たい","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词「ます形」+たい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>」+たい"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“（我）想……”。表示第一人称的愿望、想法。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"いつかまた日本へ来たいです。【2008年真题】/以后想再来日本。","furi":"いつかまた<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>へ<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>たいです。【2008年真题】/以后想再来日本。"},{"t":"line","text":"今年の夏は海で泳ぎたいです。【2008年真题】/今年夏天想在海里游泳。","furi":"<ruby>今年<rp>(</rp><rt>ことし</rt><rp>)</rp></ruby>の<ruby>夏<rp>(</rp><rt>なつ</rt><rp>)</rp></ruby>は<ruby>海<rp>(</rp><rt>うみ</rt><rp>)</rp></ruby>で<ruby>泳<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>ぎたいです。【2008年真题】/今年夏天想在海里游泳。"},{"t":"line","text":"果物が食べたいです。【2002年真题】/我想吃水果。","furi":"<ruby>果物<rp>(</rp><rt>くだもの</rt><rp>)</rp></ruby>が<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べたいです。【2002年真题】/我想吃水果。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"疑问句「～たいですか」可以用在第二、第三人称上。另外，「～たいですか」一般不用来面对面询问上司、长辈等理应尊敬的人的愿望、欲望。"}],"id":"N5-103"},{"title":"104. ～がほしい","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词+がほしい","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+がほしい"},{"t":"label","label":"说明","text":""},{"t":"line","text":"表示第一人称想要得到某种东西的愿望。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"わたしは自転車がほしいです。【2007年真题】/我想要自行车。","furi":"わたしは<ruby>自転車<rp>(</rp><rt>じてんしゃ</rt><rp>)</rp></ruby>がほしいです。【2007年真题】/我想要自行车。"},{"t":"line","text":"新しい洋服がほしいです。【2001年真题】/我想要新衣服。","furi":"<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しい<ruby>洋服<rp>(</rp><rt>ようふく</rt><rp>)</rp></ruby>がほしいです。【2001年真题】/我想要新衣服。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"同「～たいですか」一样，也可以用在第二、第三人称上，而且一般不用来面对面询问上司、长辈等理应尊敬的人的愿望、欲望。"}],"id":"N5-104"},{"title":"105. ～だろう/でしょう","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词普通形/い形容词普通形/な形容词词干/名词+だろう/でしょう","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+だろう/でしょう"},{"t":"label","label":"说明","text":""},{"t":"line","text":"常和确信程度不高的「たぶん」、「おそらく」等副词连用，表示说话人的主观推测。和确信程度较高的「きっと」等副词连用，表示说话人较为肯定的判断。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"田中さんはたぶん歌が上手でしょう。【2008年真题】/田中唱歌应该很好听吧。","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんはたぶん<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>が<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>でしょう。【2008年真题】/田中唱歌应该很好听吧。"},{"t":"line","text":"部屋の電気が消えているということは、たぶんもう寝たのでしょう。【2000年真题】/房间的灯关了，或许是已经睡了吧。","furi":"<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>の<ruby>電気<rp>(</rp><rt>でんき</rt><rp>)</rp></ruby>が<ruby>消<rp>(</rp><rt>き</rt><rp>)</rp></ruby>えているということは、たぶんもう<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>たのでしょう。【2000年真题】/房间的灯关了，或许是已经睡了吧。"},{"t":"line","text":"たぶん明日も風が強いだろう。【2004年真题】/或许明天也会刮大风吧。","furi":"たぶん<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>も<ruby>風<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>が<ruby>強<rp>(</rp><rt>つよ</rt><rp>)</rp></ruby>いだろう。【2004年真题】/或许明天也会刮大风吧。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「でしょう」是「だろう」的礼貌用法。"}],"id":"N5-105"},{"title":"106. ～にする/くする","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"な形容词词干/名词+にする","furi":"な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+にする"},{"t":"line","text":"い形容词词干+くする","furi":"い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+くする"},{"t":"label","label":"说明","text":""},{"t":"line","text":"表示人为的改变、改造，使其达到期望的结果。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"すみませんが、少し静かにしてください。【2002年真题】/不好意思，请保持安静。","furi":"すみませんが、<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かにしてください。【2002年真题】/不好意思，请保持安静。"},{"t":"line","text":"バナナを半分にして一緒に食べましょう。【2004年真题】/把香蕉分成两半一起吃吧。","furi":"バナナを<ruby>半分<rp>(</rp><rt>はんぶん</rt><rp>)</rp></ruby>にして<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べましょう。【2004年真题】/把香蕉分成两半一起吃吧。"},{"t":"line","text":"高いですね。もっと安くしてください。【2009年真题】/太贵了，请再便宜点。","furi":"<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いですね。もっと<ruby>安<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>くしてください。【2009年真题】/太贵了，请再便宜点。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「～にする」还可以表示选择。如："},{"t":"line","text":"母の誕生日のプレゼントはセーターにしました。【2009年真题】/就选毛衣当妈妈的生日礼物了。"}],"id":"N5-106"},{"title":"107. ～になる/くなる","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"な形容词词干/名词+になる","furi":"な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+になる"},{"t":"line","text":"い形容词词干+くなる","furi":"い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+くなる"},{"t":"label","label":"说明","text":""},{"t":"line","text":"表示事物自然而然的变化结果。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"寿司が好きになりました。【2009年真题】/变得喜欢吃寿司了。","furi":"<ruby>寿司<rp>(</rp><rt>すし</rt><rp>)</rp></ruby>が<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きになりました。【2009年真题】/变得喜欢吃寿司了。"},{"t":"line","text":"大学の友だちは、英語の先生になりました。【2005年真题】/大学朋友成为了一名英语老师。","furi":"<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>の<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちは、<ruby>英語<rp>(</rp><rt>えいご</rt><rp>)</rp></ruby>の<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>になりました。【2005年真题】/大学朋友成为了一名英语老师。"},{"t":"line","text":"たくさん歩いたから、足が痛くなりました。【2005年真题】/走了很多路，脚痛。","furi":"たくさん<ruby>歩<rp>(</rp><rt>ある</rt><rp>)</rp></ruby>いたから、<ruby>足<rp>(</rp><rt>あし</rt><rp>)</rp></ruby>が<ruby>痛<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>くなりました。【2005年真题】/走了很多路，脚痛。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"与「～にする/くする」强调人为的作用相比，「～になる/くなる」更强调事物变化产生的结果。另外，「～になる」还有表示客观决定的用法。如："},{"t":"line","text":"今度国に帰ることになりました。【2006年真题】/这次决定回国。"}],"id":"N5-107"},{"title":"108. ～ている","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词「て形」+いる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>」+いる"},{"t":"label","label":"说明①","text":""},{"t":"line","text":"“（正）在……”。表示动作正在进行，或者表示平时反复进行的某种习惯性行为。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"子どもたちが歌を上手に歌っています。【2009年真题】/孩子们娴熟地唱着歌。","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもたちが<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>を<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>に<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>っています。【2009年真题】/孩子们娴熟地唱着歌。"},{"t":"line","text":"何か運動をしていますか。【2007年真题】/你平时在做什么运动吗？","furi":"<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>か<ruby>運動<rp>(</rp><rt>うんどう</rt><rp>)</rp></ruby>をしていますか。【2007年真题】/你平时在做什么运动吗？"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"此种用法前接持续性动词。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"“……了”，“……着”。表示动作、作用完成之后所呈现的状态，或者其作用后的结果还保留着的状态。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"先生は眼鏡をかけています。/老师戴着眼镜。","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>は<ruby>眼鏡<rp>(</rp><rt>めがね</rt><rp>)</rp></ruby>をかけています。/老师戴着眼镜。"},{"t":"line","text":"図書館の本はまだ返していません。【2004年真题】/图书馆的书还没还。","furi":"<ruby>図書館<rp>(</rp><rt>としょかん</rt><rp>)</rp></ruby>の<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>はまだ<ruby>返<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>していません。【2004年真题】/图书馆的书还没还。"},{"t":"line","text":"ドアが閉まっています。【2003年真题】/门关着呢。","furi":"ドアが<ruby>閉<rp>(</rp><rt>し</rt><rp>)</rp></ruby>まっています。【2003年真题】/门关着呢。"},{"t":"label","label":"注意②","text":""},{"t":"line","text":"此用法前接瞬间性动词。"}],"id":"N5-108"},{"title":"109. ～てある","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"～が/は+他动词「て形」+ある","furi":"～が/は+<ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>」+ある"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“……着”。表示有目的性地完成某项动作、行为后，其结果或状态依旧保留。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"教室に試験の時間割が貼ってあります。【2010年真题】/教室里贴着考试时间表。","furi":"<ruby>教室<rp>(</rp><rt>きょうしつ</rt><rp>)</rp></ruby>に<ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>の<ruby>時間割<rp>(</rp><rt>じかんわり</rt><rp>)</rp></ruby>が<ruby>貼<rp>(</rp><rt>は</rt><rp>)</rp></ruby>ってあります。【2010年真题】/教室里贴着考试时间表。"},{"t":"line","text":"冷蔵庫にはビールが2本入れてあります。/冰箱里放着两罐啤酒。","furi":"<ruby>冷蔵庫<rp>(</rp><rt>れいぞうこ</rt><rp>)</rp></ruby>にはビールが2<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby><ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>れてあります。/冰箱里放着两罐啤酒。"},{"t":"line","text":"部屋に花が飾ってあります。/房间里装饰着花。","furi":"<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>に<ruby>花<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>が<ruby>飾<rp>(</rp><rt>かざ</rt><rp>)</rp></ruby>ってあります。/房间里装饰着花。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「～てある」表示动作完成后形成的某种状态。原本出现在他动词前面的宾格助词「を」，在此句型中需改为「が/は」。"}],"id":"N5-109"},{"title":"110. もう～","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"“已经……了”。后面接动词「た形」，表示动作的完了。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"子どもたちはもう公園に行ったから、うちにはいません。【2000年真题】/孩子们已经去公园了，所以不在家。","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもたちはもう<ruby>公園<rp>(</rp><rt>こうえん</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったから、うちにはいません。【2000年真题】/孩子们已经去公园了，所以不在家。"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"这种情况下「もう」读降调。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"“已经（不）……，再也（不）……”，之后接否定表达。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"みんながたくさん飲みましたから、もうお酒はありません。【2004年真题】/大家都喝了很多，所以酒已经没了。","furi":"みんながたくさん<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みましたから、もうお<ruby>酒<rp>(</rp><rt>さけ</rt><rp>)</rp></ruby>はありません。【2004年真题】/大家都喝了很多，所以酒已经没了。"},{"t":"line","text":"牛乳は全部飲みました。もうありません。【2006年真题】/牛奶全喝完了，已经没了。","furi":"<ruby>牛乳<rp>(</rp><rt>ぎゅうにゅう</rt><rp>)</rp></ruby>は<ruby>全部<rp>(</rp><rt>ぜんぶ</rt><rp>)</rp></ruby><ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みました。もうありません。【2006年真题】/牛奶全喝完了，已经没了。"},{"t":"line","text":"これからもうたばこを吸いません。/从今以后再也不吸烟了。","furi":"これからもうたばこを<ruby>吸<rp>(</rp><rt>す</rt><rp>)</rp></ruby>いません。/从今以后再也不吸烟了。"},{"t":"label","label":"注意②","text":""},{"t":"line","text":"这种情况下「もう」也读降调。"},{"t":"label","label":"说明③","text":""},{"t":"line","text":"「もう+数量词，副词」，意为“再、另外”，表示在原来基础上再累加一些数量或程度。"},{"t":"label","label":"例文③","text":""},{"t":"line","text":"もう少し待ったほうがいいですよ。【2008年真题】/再稍微等一下比较好。","furi":"もう<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ったほうがいいですよ。【2008年真题】/再稍微等一下比较好。"},{"t":"line","text":"もう少し静かにしてくださいませんか。【2006年真题】/能稍微再安静点吗？","furi":"もう<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>静<rp>(</rp><rt>しず</rt><rp>)</rp></ruby>かにしてくださいませんか。【2006年真题】/能稍微再安静点吗？"},{"t":"label","label":"注意③","text":""},{"t":"line","text":"这种情况下「もう」读升调。"}],"id":"N5-110"},{"title":"111. まだ～","blocks":[{"t":"label","label":"说明①","text":""},{"t":"line","text":"“还……”。之后接肯定表达，表示某状态到目前为止还存在着或某动作到现在还在继续。"},{"t":"label","label":"例文①","text":""},{"t":"line","text":"まだ郵便局は開いています。早く行きましょう。【2007年真题】/邮局还开着呢。快点去吧。","furi":"まだ<ruby>郵便<rp>(</rp><rt>ゆうびん</rt><rp>)</rp></ruby><ruby>局<rp>(</rp><rt>きょく</rt><rp>)</rp></ruby>は<ruby>開<rp>(</rp><rt>ひら</rt><rp>)</rp></ruby>いています。<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>く<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きましょう。【2007年真题】/邮局还开着呢。快点去吧。"},{"t":"line","text":"次のバスまでまだ1時間あるから、喫茶店に行きましょう。【2005年真题】/到下一班公交车来还有一个小时呢，去咖啡店坐坐吧。","furi":"<ruby>次<rp>(</rp><rt>つぎ</rt><rp>)</rp></ruby>のバスまでまだ1<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>あるから、<ruby>喫茶店<rp>(</rp><rt>きっさてん</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きましょう。【2005年真题】/到下一班公交车来还有一个小时呢，去咖啡店坐坐吧。"},{"t":"line","text":"ジュースはもうありませんが、コーヒーはまだあります。【2001年真题】/橙汁已经没了，咖啡还有。"},{"t":"label","label":"注意①","text":""},{"t":"line","text":"除了名词句和表示存在的动词「ある/いる」之外，动词一般要用「まだ～ている/ています」的形式。"},{"t":"label","label":"说明②","text":""},{"t":"line","text":"“还（未）……，还（没有）……”。之后接否定表达，表示动作尚未发生或者尚未结束，暗示接下来将做该动作或者该动作即将结束。"},{"t":"label","label":"例文②","text":""},{"t":"line","text":"パーティーはまだ始まりません。【2007年真题】/派对还没开始。","furi":"パーティーはまだ<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>まりません。【2007年真题】/派对还没开始。"},{"t":"line","text":"図書館の本はまだ返していません。【2004年真题】/图书馆的书还没还呢。","furi":"<ruby>図書館<rp>(</rp><rt>としょかん</rt><rp>)</rp></ruby>の<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>はまだ<ruby>返<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>していません。【2004年真题】/图书馆的书还没还呢。"},{"t":"label","label":"注意②","text":""},{"t":"line","text":"此种情况下，若动词是持续性动词，一般要用「まだ～ていない/ていません」的形式。"}],"id":"N5-111"},{"title":"112. ～ほうが～","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词普通形/い形容词普通形/な形容词词干+な/名词+の+ほうが～","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の+ほうが～"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“还是……比较……”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"もう少し待ったほうがいいですよ。【2008年真题】/还是再等会儿比较好。","furi":"もう<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ったほうがいいですよ。【2008年真题】/还是再等会儿比较好。"},{"t":"line","text":"熱が高いときは、無理をしないほうがいい。【2007年真题】/发烧的时候还是不要硬撑了。","furi":"<ruby>熱<rp>(</rp><rt>ねつ</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いときは、<ruby>無理<rp>(</rp><rt>むり</rt><rp>)</rp></ruby>をしないほうがいい。【2007年真题】/发烧的时候还是不要硬撑了。"},{"t":"line","text":"風がとても強いので、外に出ないほうが安全だ。【2008年真题】/风很大，还是不出去比较安全。","furi":"<ruby>風<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>がとても<ruby>強<rp>(</rp><rt>つよ</rt><rp>)</rp></ruby>いので、<ruby>外<rp>(</rp><rt>そと</rt><rp>)</rp></ruby>に<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>ないほうが<ruby>安全<rp>(</rp><rt>あんぜん</rt><rp>)</rp></ruby>だ。【2008年真题】/风很大，还是不出去比较安全。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「～ほうが」表示做出选择。后面常接「いい」等，表示委婉的劝告或建议。"}],"id":"N5-112"},{"title":"113. ～前に","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词+の/动词辞书形+前に","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の/<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>に"},{"t":"label","label":"说明","text":""},{"t":"line","text":"表示做前项动作之前，先把后项的动作做完。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"面接の前にいろいろ準備をしました。/面试之前，做了各种各样的准备。","furi":"<ruby>面接<rp>(</rp><rt>めんせつ</rt><rp>)</rp></ruby>の<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>にいろいろ<ruby>準備<rp>(</rp><rt>じゅんび</rt><rp>)</rp></ruby>をしました。/面试之前，做了各种各样的准备。"},{"t":"line","text":"寝る前に歯を磨いてください。【2008年真题】/睡觉之前请刷牙。","furi":"<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>る<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>に<ruby>歯<rp>(</rp><rt>は</rt><rp>)</rp></ruby>を<ruby>磨<rp>(</rp><rt>みが</rt><rp>)</rp></ruby>いてください。【2008年真题】/睡觉之前请刷牙。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"后项动词即使是过去时，「前に」前面的动词也要用动词的辞书形。"}],"id":"N5-113"},{"title":"114. ～とき","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词普通形/い形容词普通形/な形容词词干+な/名词+の+とき","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の+とき"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“在……的时候”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"わからないときは、先生に聞きます。【2006年真题】/不明白的时候，问老师。","furi":"わからないときは、<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>に<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>きます。【2006年真题】/不明白的时候，问老师。"},{"t":"line","text":"妹が生まれたとき、父は外国にいました。【2004年真题】/妹妹出生的时候，爸爸在国外。","furi":"<ruby>妹<rp>(</rp><rt>いもうと</rt><rp>)</rp></ruby>が<ruby>生<rp>(</rp><rt>う</rt><rp>)</rp></ruby>まれたとき、<ruby>父<rp>(</rp><rt>ちち</rt><rp>)</rp></ruby>は<ruby>外国<rp>(</rp><rt>がいこく</rt><rp>)</rp></ruby>にいました。【2004年真题】/妹妹出生的时候，爸爸在国外。"},{"t":"line","text":"暑いとき、冷たいコーヒーを飲みます。【2003年真题】/热的时候喝冰咖啡。","furi":"<ruby>暑<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>いとき、<ruby>冷<rp>(</rp><rt>つめ</rt><rp>)</rp></ruby>たいコーヒーを<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みます。【2003年真题】/热的时候喝冰咖啡。"},{"t":"line","text":"子どものとき野菜が好きではありませんでした。【2004年真题】/小时候不喜欢吃蔬菜。","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どものとき<ruby>野菜<rp>(</rp><rt>やさい</rt><rp>)</rp></ruby>が<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きではありませんでした。【2004年真题】/小时候不喜欢吃蔬菜。"}],"id":"N5-114"},{"title":"115. 場合","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词普通形/い形容词普通形/な形容词词干+な/名词+の+場合","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の+<ruby>場合<rp>(</rp><rt>ばあい</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“在……情况下”，后项大多为采取相应措施或对策的指示性句子。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"財布が盗まれた場合、すぐ警察を呼んでください。/钱包被偷的情况，请立刻喊警察。","furi":"<ruby>財布<rp>(</rp><rt>さいふ</rt><rp>)</rp></ruby>が<ruby>盗<rp>(</rp><rt>ぬす</rt><rp>)</rp></ruby>まれた<ruby>場合<rp>(</rp><rt>ばあい</rt><rp>)</rp></ruby>、すぐ<ruby>警察<rp>(</rp><rt>けいさつ</rt><rp>)</rp></ruby>を<ruby>呼<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>んでください。/钱包被偷的情况，请立刻喊警察。"},{"t":"line","text":"体の調子が悪い場合は、少し休んだほうがいいです。/身体不舒服的话，稍微休息一下比较好。","furi":"<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby>の<ruby>調子<rp>(</rp><rt>ちょうし</rt><rp>)</rp></ruby>が<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>い<ruby>場合<rp>(</rp><rt>ばあい</rt><rp>)</rp></ruby>は、<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>んだほうがいいです。/身体不舒服的话，稍微休息一下比较好。"},{"t":"line","text":"雨の場合は、試合を中止します。/下雨的话，就停止比赛。","furi":"<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>の<ruby>場合<rp>(</rp><rt>ばあい</rt><rp>)</rp></ruby>は、<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>を<ruby>中止<rp>(</rp><rt>ちゅうし</rt><rp>)</rp></ruby>します。/下雨的话，就停止比赛。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「場合」前项大多是负面情况或不希望出现的事情，不太用于积极或有利的情况。"}],"id":"N5-115"},{"title":"116. ～てから","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词「て形」+から","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>」+から"},{"t":"label","label":"说明","text":""},{"t":"line","text":"表示前后两个动作发生时间的既定性，即一定是先发生前项，接着出现后项。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"テープを入れてから、一番右のボタンを押します。/磁带放进去之后，再按一下最右边的按钮。","furi":"テープを<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>れてから、<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby><ruby>右<rp>(</rp><rt>みぎ</rt><rp>)</rp></ruby>のボタンを<ruby>押<rp>(</rp><rt>お</rt><rp>)</rp></ruby>します。/磁带放进去之后，再按一下最右边的按钮。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「～てから」前后两个动作之间的间隔时间不能太长。"}],"id":"N5-116"},{"title":"117. ～あとで","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"动词「た形」+あとで","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>」+あとで"},{"t":"line","text":"名词+の+あとで","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の+あとで"},{"t":"label","label":"说明","text":""},{"t":"line","text":"表示做完一件事情后做另外一件事，用于客观地叙述事情发生的顺序。强调在前项发生之后进行后项的动作，行为。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"家族が出かけたあとで、部屋の掃除をします。【2009年真题】/家人都出门后，再打扫房间。","furi":"<ruby>家族<rp>(</rp><rt>かぞく</rt><rp>)</rp></ruby>が<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>かけたあとで、<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>の<ruby>掃除<rp>(</rp><rt>そうじ</rt><rp>)</rp></ruby>をします。【2009年真题】/家人都出门后，再打扫房间。"},{"t":"line","text":"食事のあとで、映画を見に行きませんか。/吃完饭后，去看电影吧？","furi":"<ruby>食事<rp>(</rp><rt>しょくじ</rt><rp>)</rp></ruby>のあとで、<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きませんか。/吃完饭后，去看电影吧？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「～あとで」前后两个动作之间的间隔时间可长可短。要重点掌握它和「～てから」前面接续的区别。"}],"id":"N5-117"},{"title":"118. ～ほかに（は）","blocks":[{"t":"label","label":"接续","text":""},{"t":"line","text":"名词+の+ほかに（は）","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の+ほかに（は）"},{"t":"label","label":"说明","text":""},{"t":"line","text":"“除了……以外”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"ペンのほかに、何か必要なものがありますか。/除了钢笔还有什么需要的东西吗？","furi":"ペンのほかに、<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>か<ruby>必要<rp>(</rp><rt>ひつよう</rt><rp>)</rp></ruby>なものがありますか。/除了钢笔还有什么需要的东西吗？"},{"t":"line","text":"ピアノのほかには、ギターを弾けますよ。/除了钢琴我还会弹吉他哟。","furi":"ピアノのほかには、ギターを<ruby>弾<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>けますよ。/除了钢琴我还会弹吉他哟。"}],"id":"N5-118"},{"title":"119. ～と～とどちらが～か","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“……和……哪个……？”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"スポーツをするのと、見るのとどちらが好きですか。【2008年真题】/对于体育活动，你是更喜欢参与其中呢还是观看呢？","furi":"スポーツをするのと、<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>るのとどちらが<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きですか。【2008年真题】/对于体育活动，你是更喜欢参与其中呢还是观看呢？"},{"t":"line","text":"この大学とあの大学とどちらが近いですか。【2003年真题】/这所大学和那所大学，哪一所更近？","furi":"この<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>とあの<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>とどちらが<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>いですか。【2003年真题】/这所大学和那所大学，哪一所更近？"},{"t":"line","text":"バスと電車とどちらがいいですか。【1999年真题】/公交车和电车哪个比较好？","furi":"バスと<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>とどちらがいいですか。【1999年真题】/公交车和电车哪个比较好？"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「～と～とどちらが～か」属于选择疑问句，只提供两个选项。"}],"id":"N5-119"},{"title":"120. ～で～がいちばん～","blocks":[{"t":"label","label":"说明","text":""},{"t":"line","text":"“在……内，……是最……的”。"},{"t":"label","label":"例文","text":""},{"t":"line","text":"クラスで王さんがいちばん背が高い人です。/小王是班里个子最高的人。","furi":"クラスで<ruby>王<rp>(</rp><rt>おう</rt><rp>)</rp></ruby>さんがいちばん<ruby>背<rp>(</rp><rt>せ</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>い<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>です。/小王是班里个子最高的人。"},{"t":"line","text":"日本で富士山がいちばん有名な山です。/富士山是日本最有名的山。","furi":"<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>で<ruby>富士山<rp>(</rp><rt>ふじさん</rt><rp>)</rp></ruby>がいちばん<ruby>有名<rp>(</rp><rt>ゆうめい</rt><rp>)</rp></ruby>な<ruby>山<rp>(</rp><rt>やま</rt><rp>)</rp></ruby>です。/富士山是日本最有名的山。"},{"t":"line","text":"学校で上田先生がいちばん優しいです。/学校里上田老师最温柔。","furi":"<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>で<ruby>上田<rp>(</rp><rt>うえだ</rt><rp>)</rp></ruby><ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>がいちばん<ruby>優<rp>(</rp><rt>やさ</rt><rp>)</rp></ruby>しいです。/学校里上田老师最温柔。"},{"t":"label","label":"注意","text":""},{"t":"line","text":"「～で～がいちばん～」表示限定的范围内的最高级。"}],"id":"N5-120"}]},{"id":"N5-u10","title":"10单元 常用寒暄用语","points":[{"id":"N5-121","title":"ありがとうございます。谢谢。","blocks":[{"t":"line","text":"ありがとうございます。谢谢。"}]},{"id":"N5-122","title":"いいえ、かまいません。没关系。","blocks":[{"t":"line","text":"いいえ、かまいません。没关系。"}]},{"id":"N5-123","title":"いただきます。我开始吃饭了；我收下了。","blocks":[{"t":"line","text":"いただきます。我开始吃饭了；我收下了。"}]},{"id":"N5-124","title":"いってきます。我出去了。","blocks":[{"t":"line","text":"いってきます。我出去了。"}]},{"id":"N5-125","title":"いってらっしゃい。您走好。","blocks":[{"t":"line","text":"いってらっしゃい。您走好。"}]},{"id":"N5-126","title":"いらっしゃいませ。欢迎光临。","blocks":[{"t":"line","text":"いらっしゃいませ。欢迎光临。"}]},{"id":"N5-127","title":"お帰りなさい。您回来了。","blocks":[{"t":"line","text":"お帰りなさい。您回来了。","furi":"お<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>りなさい。您回来了。"}]},{"id":"N5-128","title":"おかげさまで、元気です。托您的福，我很好。","blocks":[{"t":"line","text":"おかげさまで、元気です。托您的福，我很好。","furi":"おかげさまで、<ruby>元気<rp>(</rp><rt>げんき</rt><rp>)</rp></ruby>です。托您的福，我很好。"}]},{"id":"N5-129","title":"お元気で。多保重。","blocks":[{"t":"line","text":"お元気で。多保重。","furi":"お<ruby>元気<rp>(</rp><rt>げんき</rt><rp>)</rp></ruby>で。多保重。"}]},{"id":"N5-130","title":"お大事に。多保重。","blocks":[{"t":"line","text":"お大事に。多保重。","furi":"お<ruby>大事<rp>(</rp><rt>だいじ</rt><rp>)</rp></ruby>に。多保重。"}]},{"id":"N5-131","title":"お願いします。拜托了。","blocks":[{"t":"line","text":"お願いします。拜托了。","furi":"お<ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>いします。拜托了。"}]},{"id":"N5-132","title":"おはようございます。早上好。","blocks":[{"t":"line","text":"おはようございます。早上好。"}]},{"id":"N5-133","title":"お休みなさい。晚安。","blocks":[{"t":"line","text":"お休みなさい。晚安。","furi":"お<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>みなさい。晚安。"}]},{"id":"N5-134","title":"かしこまりました。我知道了。","blocks":[{"t":"line","text":"かしこまりました。我知道了。"}]},{"id":"N5-135","title":"ごちそうさまでした。多谢款待。","blocks":[{"t":"line","text":"ごちそうさまでした。多谢款待。"}]},{"id":"N5-136","title":"こちらこそ。哪里哪里。","blocks":[{"t":"line","text":"こちらこそ。哪里哪里。"}]},{"id":"N5-137","title":"ごめんなさい。对不起。","blocks":[{"t":"line","text":"ごめんなさい。对不起。"}]},{"id":"N5-138","title":"こんにちは。你好。","blocks":[{"t":"line","text":"こんにちは。你好。"}]},{"id":"N5-139","title":"こんばんは。晚上好。","blocks":[{"t":"line","text":"こんばんは。晚上好。"}]},{"id":"N5-140","title":"さようなら。再见。","blocks":[{"t":"line","text":"さようなら。再见。"}]},{"id":"N5-141","title":"失礼します。再见。","blocks":[{"t":"line","text":"失礼します。再见。","furi":"<ruby>失礼<rp>(</rp><rt>しつれい</rt><rp>)</rp></ruby>します。再见。"}]},{"id":"N5-142","title":"すみません。对不起；请问……","blocks":[{"t":"line","text":"すみません。对不起；请问……"}]},{"id":"N5-143","title":"ただいま。我回来了。","blocks":[{"t":"line","text":"ただいま。我回来了。"}]},{"id":"N5-144","title":"では、また（あした）。回头见（明天见）。","blocks":[{"t":"line","text":"では、また（あした）。回头见（明天见）。"}]},{"id":"N5-145","title":"どういたしまして。不用谢。","blocks":[{"t":"line","text":"どういたしまして。不用谢。"}]},{"id":"N5-146","title":"どうぞよろしく。请多关照。","blocks":[{"t":"line","text":"どうぞよろしく。请多关照。"}]},{"id":"N5-147","title":"はじめまして。初次见面。","blocks":[{"t":"line","text":"はじめまして。初次见面。"}]},{"id":"N5-148","title":"久しぶりです。好久不见。","blocks":[{"t":"line","text":"久しぶりです。好久不见。","furi":"<ruby>久<rp>(</rp><rt>ひさ</rt><rp>)</rp></ruby>しぶりです。好久不见。"}]},{"id":"N5-149","title":"わかりました。明白了。","blocks":[{"t":"line","text":"わかりました。明白了。"}]}]}]},{"id":"N4","name":"N4 文法详解（整理版）","units":[{"id":"N4-u1","title":"第1单元 助动词","points":[{"title":"1. ～ず（に）","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ず（に）（する→せずに）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ず（に）（する→せずに）"},{"t":"label","label":"说明","text":"意为“不……、没……”或“因为没有……而……”，表示动作状态的否定或原因，主要用于书面语。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"昨日は忙しくて、夜10時まで何も食べずに働いた。（昨天太忙了，什么都没吃一直工作到晚上10点。）","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>は<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しくて、<ruby>夜<rp>(</rp><rt>よる</rt><rp>)</rp></ruby>10<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>まで<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>も<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べずに<ruby>働<rp>(</rp><rt>はたら</rt><rp>)</rp></ruby>いた。（昨天太忙了，什么都没吃一直工作到晚上10点。）"},{"t":"line","text":"辞書を使わずに日本語の新聞を読むことができますか。（不用词典能读日文报纸吗？）","furi":"<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>を<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>わずに<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>新聞<rp>(</rp><rt>しんぶん</rt><rp>)</rp></ruby>を<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>むことができますか。（不用词典能读日文报纸吗？）"}],"id":"N4-1"},{"title":"2. ～たがる","blocks":[{"t":"label","label":"接续","text":"动词ます形 + たがる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + たがる"},{"t":"label","label":"说明","text":"表示第三人称的愿望、要求（想要……）。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"うちの子どもは怖い話を聞きたがる。（我家孩子想听恐怖故事。）","furi":"うちの<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもは<ruby>怖<rp>(</rp><rt>こわ</rt><rp>)</rp></ruby>い<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>を<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>きたがる。（我家孩子想听恐怖故事。）"},{"t":"line","text":"このアパートに住みたがっている学生が多い。（想住这间公寓的学生很多。）","furi":"このアパートに<ruby>住<rp>(</rp><rt>す</rt><rp>)</rp></ruby>みたがっている<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>が<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>い。（想住这间公寓的学生很多。）"}],"id":"N4-2"},{"title":"3. ～がる","blocks":[{"t":"label","label":"接续","text":"い形容词词干/な形容词词干 + がる","furi":"い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + がる"},{"t":"label","label":"说明","text":"表示第三人称的感情、感受（感到……、觉得……）。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"急に大きな音がしたので、その子どもは怖がって泣いてしまった。（突然发出巨响，那个孩子害怕地哭了。）","furi":"<ruby>急<rp>(</rp><rt>きゅう</rt><rp>)</rp></ruby>に<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きな<ruby>音<rp>(</rp><rt>おと</rt><rp>)</rp></ruby>がしたので、その<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもは<ruby>怖<rp>(</rp><rt>こわ</rt><rp>)</rp></ruby>がって<ruby>泣<rp>(</rp><rt>な</rt><rp>)</rp></ruby>いてしまった。（突然发出巨响，那个孩子害怕地哭了。）"},{"t":"line","text":"猫を可愛がる女の子が多いです。（喜欢猫的女孩子很多。）","furi":"<ruby>猫<rp>(</rp><rt>ねこ</rt><rp>)</rp></ruby>を<ruby>可愛<rp>(</rp><rt>かわい</rt><rp>)</rp></ruby>がる<ruby>女<rp>(</rp><rt>おんな</rt><rp>)</rp></ruby>の<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>が<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>いです。（喜欢猫的女孩子很多。）"}],"id":"N4-3"},{"title":"4. ～そうだ（传闻）","blocks":[{"t":"label","label":"接续","text":"动词/形容词普通形、名词 + だ + そうだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>、<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + だ + そうだ"},{"t":"label","label":"说明","text":"表示传闻，“听说……、据说……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"来週うちの近くでお祭りがあるそうです。（听说下周我家附近有庙会。）","furi":"<ruby>来週<rp>(</rp><rt>らいしゅう</rt><rp>)</rp></ruby>うちの<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>くでお<ruby>祭<rp>(</rp><rt>まつ</rt><rp>)</rp></ruby>りがあるそうです。（听说下周我家附近有庙会。）"},{"t":"line","text":"友だちによると、去年の試験は簡単だったそうです。（据朋友说，去年的考试很简单。）","furi":"<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちによると、<ruby>去年<rp>(</rp><rt>きょねん</rt><rp>)</rp></ruby>の<ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>は<ruby>簡単<rp>(</rp><rt>かんたん</rt><rp>)</rp></ruby>だったそうです。（据朋友说，去年的考试很简单。）"}],"id":"N4-4"},{"title":"5. ～そうだ（样态）","blocks":[{"t":"label","label":"接续","text":"动词ます形、い形容词词干、な形容词词干 + そうだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>、い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>、な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + そうだ"},{"t":"label","label":"说明","text":"表示根据所见所闻做出的判断，“看起来好像……、眼看就要……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"山田先生はいつも難しそうな本を読んでいます。（山田老师总在看看起来很难的书。）","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby><ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>はいつも<ruby>難<rp>(</rp><rt>むずか</rt><rp>)</rp></ruby>しそうな<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>を<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>んでいます。（山田老师总在看看起来很难的书。）"},{"t":"line","text":"石田さんは忙しそうだ。手伝いましょう。（石田看起来很忙，帮帮他吧。）","furi":"<ruby>石田<rp>(</rp><rt>いしだ</rt><rp>)</rp></ruby>さんは<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しそうだ。<ruby>手伝<rp>(</rp><rt>てつだ</rt><rp>)</rp></ruby>いましょう。（石田看起来很忙，帮帮他吧。）"},{"t":"line","text":"ポケットから財布が落ちそうだよ。（钱包快从口袋里掉出来了。）","furi":"ポケットから<ruby>財布<rp>(</rp><rt>さいふ</rt><rp>)</rp></ruby>が<ruby>落<rp>(</rp><rt>お</rt><rp>)</rp></ruby>ちそうだよ。（钱包快从口袋里掉出来了。）"}],"id":"N4-5"},{"title":"6. ～ようだ","blocks":[{"t":"label","label":"接续①","text":"动词普通形/い形容词普通形/な形容词词干+な/名词+の","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の"},{"t":"label","label":"说明①","text":"比喻，“像……一样”。","furi":""},{"t":"label","label":"例句①","text":"母ははじめて飛行機に乗って、子供のように喜んでいた。（妈妈第一次坐飞机，高兴得像个孩子。）","furi":"<ruby>母<rp>(</rp><rt>はは</rt><rp>)</rp></ruby>ははじめて<ruby>飛行機<rp>(</rp><rt>ひこうき</rt><rp>)</rp></ruby>に<ruby>乗<rp>(</rp><rt>の</rt><rp>)</rp></ruby>って、<ruby>子供<rp>(</rp><rt>こども</rt><rp>)</rp></ruby>のように<ruby>喜<rp>(</rp><rt>よろこ</rt><rp>)</rp></ruby>んでいた。（妈妈第一次坐飞机，高兴得像个孩子。）"},{"t":"label","label":"说明②","text":"举例，“像……那样”。","furi":""},{"t":"label","label":"例句②","text":"田中さんのような優しい人が好きです。（我喜欢像田中那样温柔的人。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんのような<ruby>優<rp>(</rp><rt>やさ</rt><rp>)</rp></ruby>しい<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きです。（我喜欢像田中那样温柔的人。）"},{"t":"label","label":"说明③","text":"主观推测，“好像……、似乎……”。","furi":""},{"t":"label","label":"例句③","text":"外は寒いようですね。（外面好像很冷。）","furi":"<ruby>外<rp>(</rp><rt>そと</rt><rp>)</rp></ruby>は<ruby>寒<rp>(</rp><rt>さむ</rt><rp>)</rp></ruby>いようですね。（外面好像很冷。）"}],"id":"N4-6"},{"title":"7. ～らしい","blocks":[{"t":"label","label":"接续①","text":"动词/形容词普通形、名词 + らしい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>、<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + らしい"},{"t":"label","label":"说明①","text":"根据客观情况或传闻进行推测，“好像……”。","furi":""},{"t":"label","label":"例句①","text":"二人は来年結婚するらしいです。（两个人好像明年结婚。）","furi":"<ruby>二<rp>(</rp><rt>に</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>は<ruby>来年<rp>(</rp><rt>らいねん</rt><rp>)</rp></ruby><ruby>結婚<rp>(</rp><rt>けっこん</rt><rp>)</rp></ruby>するらしいです。（两个人好像明年结婚。）"},{"t":"label","label":"说明②","text":"名词+らしい，表示充分具备该名词应有的特点，“像……似的、地道的……”。","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+らしい，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>充分<rp>(</rp><rt>じゅうぶん</rt><rp>)</rp></ruby><ruby>具<rp>(</rp><rt>ぐ</rt><rp>)</rp></ruby><ruby>备<rp>(</rp><rt>备</rt><rp>)</rp></ruby><ruby>该<rp>(</rp><rt>该</rt><rp>)</rp></ruby><ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>应<rp>(</rp><rt>应</rt><rp>)</rp></ruby><ruby>有<rp>(</rp><rt>ゆう</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>特<rp>(</rp><rt>とく</rt><rp>)</rp></ruby><ruby>点<rp>(</rp><rt>てん</rt><rp>)</rp></ruby>，“<ruby>像<rp>(</rp><rt>ぞう</rt><rp>)</rp></ruby>……<ruby>似<rp>(</rp><rt>に</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>、<ruby>地道<rp>(</rp><rt>じみち</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>……”。"},{"t":"label","label":"例句②","text":"学生らしくもっと勉強しなさい。（要更加努力学习，像个学生的样子。）","furi":"<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>らしくもっと<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>しなさい。（要更加努力学习，像个学生的样子。）"}],"id":"N4-7"},{"title":"8. ～みたいだ","blocks":[{"t":"label","label":"接续","text":"动词普通形/い形容词普通形/な形容词词干/名词 + みたいだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + みたいだ"},{"t":"label","label":"说明①","text":"主观推测，“好像……、似乎……”，多用于口语。","furi":""},{"t":"label","label":"例句①","text":"教室に誰かいるみたいだ。電気が付いている。（教室里好像有人，灯开着。）","furi":"<ruby>教室<rp>(</rp><rt>きょうしつ</rt><rp>)</rp></ruby>に<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>かいるみたいだ。<ruby>電気<rp>(</rp><rt>でんき</rt><rp>)</rp></ruby>が<ruby>付<rp>(</rp><rt>つ</rt><rp>)</rp></ruby>いている。（教室里好像有人，灯开着。）"},{"t":"label","label":"说明②","text":"比喻，“像……一样”。","furi":""},{"t":"label","label":"例句②","text":"あの雲の形は馬みたいだ。（那片云的形状像马一样。）","furi":"あの<ruby>雲<rp>(</rp><rt>くも</rt><rp>)</rp></ruby>の<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>は<ruby>馬<rp>(</rp><rt>うま</rt><rp>)</rp></ruby>みたいだ。（那片云的形状像马一样。）"},{"t":"label","label":"说明③","text":"举例，“像……那样”。","furi":""},{"t":"label","label":"例句③","text":"大きくなったら、イチローさんみたいな野球選手になりたいです。（长大后，我想成为像一郎那样的棒球运动员。）","furi":"<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きくなったら、イチローさんみたいな<ruby>野球<rp>(</rp><rt>やきゅう</rt><rp>)</rp></ruby><ruby>選手<rp>(</rp><rt>せんしゅ</rt><rp>)</rp></ruby>になりたいです。（长大后，我想成为像一郎那样的棒球运动员。）"}],"id":"N4-8"},{"title":"9. 可能助动词「れる/られる」","blocks":[{"t":"label","label":"接续","text":"","furi":""},{"t":"line","text":"I类：词尾「う段」→「え段」+る（書く→書ける）","furi":"I<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：<ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>尾<rp>(</rp><rt>お</rt><rp>)</rp></ruby>「う<ruby>段<rp>(</rp><rt>だん</rt><rp>)</rp></ruby>」→「え<ruby>段<rp>(</rp><rt>だん</rt><rp>)</rp></ruby>」+る（<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>く→<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ける）"},{"t":"line","text":"II类：ない形 + られる（食べる→食べられる）","furi":"II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + られる（<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる→<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べられる）"},{"t":"line","text":"III类：する→できる、来る→来られる","furi":"III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：する→できる、<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る→<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>られる"},{"t":"label","label":"说明","text":"表示能力或可能性，“能……、会……、可以……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"この店で日本のお金が使えますか。（这家店可以用日元吗？）","furi":"この<ruby>店<rp>(</rp><rt>みせ</rt><rp>)</rp></ruby>で<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>のお<ruby>金<rp>(</rp><rt>かね</rt><rp>)</rp></ruby>が<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>えますか。（这家店可以用日元吗？）"},{"t":"line","text":"この辞書で漢字の読み方が調べられます。（这本词典可以查汉字的读音。）","furi":"この<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>で<ruby>漢字<rp>(</rp><rt>かんじ</rt><rp>)</rp></ruby>の<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>み<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>が<ruby>調<rp>(</rp><rt>しら</rt><rp>)</rp></ruby>べられます。（这本词典可以查汉字的读音。）"}],"id":"N4-9"},{"title":"10. 使役助动词「せる/させる」","blocks":[{"t":"label","label":"接续","text":"","furi":""},{"t":"line","text":"I类：ない形 + せる（書く→書かせる）","furi":"I<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + せる（<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>く→<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>かせる）"},{"t":"line","text":"II类：ない形 + させる（食べる→食べさせる）","furi":"II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + させる（<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる→<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べさせる）"},{"t":"line","text":"III类：する→させる、来る→来させる","furi":"III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：する→させる、<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る→<ruby>来<rp>(</rp><rt>きた</rt><rp>)</rp></ruby>させる"},{"t":"label","label":"说明","text":"“让……、使……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"父は面白いことを言ってよくみんなを笑わせる。（爸爸总是说有趣的事情逗大家笑。）","furi":"<ruby>父<rp>(</rp><rt>ちち</rt><rp>)</rp></ruby>は<ruby>面白<rp>(</rp><rt>おもしろ</rt><rp>)</rp></ruby>いことを<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってよくみんなを<ruby>笑<rp>(</rp><rt>わら</rt><rp>)</rp></ruby>わせる。（爸爸总是说有趣的事情逗大家笑。）"},{"t":"line","text":"すぐ返事ができないので、少し考えさせてください。（我无法立刻回答，请让我考虑一下。）","furi":"すぐ<ruby>返事<rp>(</rp><rt>へんじ</rt><rp>)</rp></ruby>ができないので、<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>考<rp>(</rp><rt>かんが</rt><rp>)</rp></ruby>えさせてください。（我无法立刻回答，请让我考虑一下。）"}],"id":"N4-10"},{"title":"11. 被动助动词「れる/られる」","blocks":[{"t":"label","label":"接续","text":"","furi":""},{"t":"line","text":"I类：ない形 + れる（書く→書かれる）","furi":"I<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + れる（<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>く→<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>かれる）"},{"t":"line","text":"II类：ない形 + られる（食べる→食べられる）","furi":"II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + られる（<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる→<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べられる）"},{"t":"line","text":"III类：する→される、来る→来られる","furi":"III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：する→される、<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る→<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>られる"},{"t":"label","label":"说明①","text":"直接被动（人作主语）。","furi":""},{"t":"label","label":"例句①","text":"私は先生に褒められました。（我被老师表扬了。）","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>は<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>に<ruby>褒<rp>(</rp><rt>ほ</rt><rp>)</rp></ruby>められました。（我被老师表扬了。）"},{"t":"label","label":"说明②","text":"带宾语的间接被动。","furi":""},{"t":"label","label":"例句②","text":"わたしはルームメートに日記を見られた。（我的日记被室友看了。）","furi":"わたしはルームメートに<ruby>日記<rp>(</rp><rt>にっき</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>られた。（我的日记被室友看了。）"},{"t":"label","label":"说明③","text":"自动词构成的间接被动（带来不良影响）。","furi":""},{"t":"label","label":"例句③","text":"帰りは雨に降られてしまった。（回来时被雨淋了。）","furi":"<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>りは<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>に<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>られてしまった。（回来时被雨淋了。）"},{"t":"label","label":"说明④","text":"事物作主语的被动（客观事实、新闻报道）。","furi":""},{"t":"label","label":"例句④","text":"最近は日本の漫画がいろいろな国で読まれています。（最近日本的漫画在很多国家被阅读。）","furi":"<ruby>最近<rp>(</rp><rt>さいきん</rt><rp>)</rp></ruby>は<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>の<ruby>漫画<rp>(</rp><rt>まんが</rt><rp>)</rp></ruby>がいろいろな<ruby>国<rp>(</rp><rt>くに</rt><rp>)</rp></ruby>で<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>まれています。（最近日本的漫画在很多国家被阅读。）"}],"id":"N4-11"},{"title":"12. 使役被动助动词「される/させられる」","blocks":[{"t":"label","label":"接续","text":"","furi":""},{"t":"line","text":"I类：ない形 + される/せられる（書く→書かされる）","furi":"I<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + される/せられる（<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>く→<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>かされる）"},{"t":"line","text":"II类：ない形 + させられる（食べる→食べさせられる）","furi":"II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + させられる（<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる→<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べさせられる）"},{"t":"line","text":"III类：する→させられる、来る→来させられる","furi":"III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：する→させられる、<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る→<ruby>来<rp>(</rp><rt>きた</rt><rp>)</rp></ruby>させられる"},{"t":"label","label":"说明","text":"“被迫……”，强调并非出于自身意愿。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"お腹が痛くて病院へ行ったら、1時間も待たされた。（肚子疼去医院，结果被让等了一个小时。）","furi":"お<ruby>腹<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>が<ruby>痛<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>くて<ruby>病院<rp>(</rp><rt>びょういん</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったら、1<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>も<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>たされた。（肚子疼去医院，结果被让等了一个小时。）"},{"t":"line","text":"わたしは、母に買い物に行かせられました。（我被妈妈派去买东西。）","furi":"わたしは、<ruby>母<rp>(</rp><rt>はは</rt><rp>)</rp></ruby>に<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>い<ruby>物<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>かせられました。（我被妈妈派去买东西。）"}],"id":"N4-12"},{"title":"13. 命令助动词「れ/ろ」","blocks":[{"t":"label","label":"接续","text":"","furi":""},{"t":"line","text":"I类：词尾改为「え段」假名（書く→書け）","furi":"I<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：<ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>尾<rp>(</rp><rt>お</rt><rp>)</rp></ruby><ruby>改<rp>(</rp><rt>あらため</rt><rp>)</rp></ruby><ruby>为<rp>(</rp><rt>为</rt><rp>)</rp></ruby>「え<ruby>段<rp>(</rp><rt>だん</rt><rp>)</rp></ruby>」<ruby>假<rp>(</rp><rt>假</rt><rp>)</rp></ruby><ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>（<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>く→<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>け）"},{"t":"line","text":"II类：词干 + ろ（食べる→食べろ）","furi":"II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：<ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + ろ（<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる→<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べろ）"},{"t":"line","text":"III类：する→しろ、来る→来い","furi":"III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：する→しろ、<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る→<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>い"},{"t":"label","label":"说明","text":"表示命令，“去做……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"早く起きろ。学校に遅れるよ。（快起床，上学要迟到了。）","furi":"<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>く<ruby>起<rp>(</rp><rt>お</rt><rp>)</rp></ruby>きろ。<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>に<ruby>遅<rp>(</rp><rt>おく</rt><rp>)</rp></ruby>れるよ。（快起床，上学要迟到了。）"},{"t":"line","text":"テレビを見ないで、勉強しろ。（别看电视了，快去学习。）","furi":"テレビを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ないで、<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>しろ。（别看电视了，快去学习。）"}],"id":"N4-13"},{"title":"14. 禁止助动词「な」","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + な","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + な"},{"t":"label","label":"说明","text":"表示禁止，“不准……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"「ここにごみを捨てるな！」と書いてある。（写着“此处严禁扔垃圾！”。）","furi":"「ここにごみを<ruby>捨<rp>(</rp><rt>す</rt><rp>)</rp></ruby>てるな！」と<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いてある。（写着“此处严禁扔垃圾！”。）"},{"t":"line","text":"ここに車を止めるな。邪魔だ。（别在这里停车，很碍事。）","furi":"ここに<ruby>車<rp>(</rp><rt>くるま</rt><rp>)</rp></ruby>を<ruby>止<rp>(</rp><rt>と</rt><rp>)</rp></ruby>めるな。<ruby>邪魔<rp>(</rp><rt>じゃま</rt><rp>)</rp></ruby>だ。（别在这里停车，很碍事。）"}],"id":"N4-14"}]},{"id":"N4-u2","title":"第2单元 补助动词、形式体言和接续助词等","points":[{"title":"15. ～ておく/とく","blocks":[{"t":"label","label":"接续","text":"动词て形 + おく（口语中常变为とく）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + おく（<ruby>口<rp>(</rp><rt>くち</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby><ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby><ruby>常<rp>(</rp><rt>つね</rt><rp>)</rp></ruby><ruby>变<rp>(</rp><rt>变</rt><rp>)</rp></ruby><ruby>为<rp>(</rp><rt>为</rt><rp>)</rp></ruby>とく）"},{"t":"label","label":"说明","text":"事先做好某事。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"あとで捨てるから、ごみを集めておいてください。（待会儿要扔，请先把垃圾收在一起。）","furi":"あとで<ruby>捨<rp>(</rp><rt>す</rt><rp>)</rp></ruby>てるから、ごみを<ruby>集<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>めておいてください。（待会儿要扔，请先把垃圾收在一起。）"},{"t":"line","text":"お客さんが来るからテーブルの上にお皿を並べておきます。（客人要来，先在桌上摆好盘子。）","furi":"お<ruby>客<rp>(</rp><rt>きゃく</rt><rp>)</rp></ruby>さんが<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>るからテーブルの<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>にお<ruby>皿<rp>(</rp><rt>さら</rt><rp>)</rp></ruby>を<ruby>並<rp>(</rp><rt>なら</rt><rp>)</rp></ruby>べておきます。（客人要来，先在桌上摆好盘子。）"}],"id":"N4-15"},{"title":"16. ～ていく","blocks":[{"t":"label","label":"接续","text":"动词て形 + いく","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + いく"},{"t":"label","label":"说明①","text":"空间上远去，“……而去”。","furi":""},{"t":"label","label":"例句①","text":"鳥が飛んでいきました。（鸟儿飞走了。）","furi":"<ruby>鳥<rp>(</rp><rt>とり</rt><rp>)</rp></ruby>が<ruby>飛<rp>(</rp><rt>と</rt><rp>)</rp></ruby>んでいきました。（鸟儿飞走了。）"},{"t":"label","label":"说明②","text":"时间上持续到将来，“……下去”。","furi":""},{"t":"label","label":"例句②","text":"学校を卒業しても、日本語の勉強を続けていくつもりだ。（即使毕业了，也打算继续学日语。）","furi":"<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>を<ruby>卒業<rp>(</rp><rt>そつぎょう</rt><rp>)</rp></ruby>しても、<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>の<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>を<ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>けていくつもりだ。（即使毕业了，也打算继续学日语。）"}],"id":"N4-16"},{"title":"17. ～てくる","blocks":[{"t":"label","label":"接续","text":"动词て形 + くる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + くる"},{"t":"label","label":"说明①","text":"去去就来（做完动作回来）。","furi":""},{"t":"label","label":"例句①","text":"ちょっと手紙を出してきます。（我去寄封信就回来。）","furi":"ちょっと<ruby>手紙<rp>(</rp><rt>てがみ</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>してきます。（我去寄封信就回来。）"},{"t":"label","label":"说明②","text":"空间上靠近，“朝着这里来”。","furi":""},{"t":"label","label":"例句②","text":"台風が近づいてきます。（台风正在逼近。）","furi":"<ruby>台風<rp>(</rp><rt>たいふう</rt><rp>)</rp></ruby>が<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>づいてきます。（台风正在逼近。）"},{"t":"label","label":"说明③","text":"时间上持续到现在，“一直……到现在”。","furi":""},{"t":"label","label":"例句③","text":"この伝統は百年も続いてきた。（这个传统已经持续了一百年。）","furi":"この<ruby>伝統<rp>(</rp><rt>でんとう</rt><rp>)</rp></ruby>は<ruby>百<rp>(</rp><rt>ひゃく</rt><rp>)</rp></ruby><ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>も<ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>いてきた。（这个传统已经持续了一百年。）"}],"id":"N4-17"},{"title":"18. ～てしまう/ちゃう","blocks":[{"t":"label","label":"接续","text":"动词て形 + しまう（口语中常变为ちゃう）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + しまう（<ruby>口<rp>(</rp><rt>くち</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby><ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby><ruby>常<rp>(</rp><rt>つね</rt><rp>)</rp></ruby><ruby>变<rp>(</rp><rt>变</rt><rp>)</rp></ruby><ruby>为<rp>(</rp><rt>为</rt><rp>)</rp></ruby>ちゃう）"},{"t":"label","label":"说明","text":"表示动作完成，常带有遗憾、懊悔的语气。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"あ、大変、急いできたから、財布を忘れちゃった。（啊，糟了，因为太着急过来，钱包忘带了。）","furi":"あ、<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>、<ruby>急<rp>(</rp><rt>いそ</rt><rp>)</rp></ruby>いできたから、<ruby>財布<rp>(</rp><rt>さいふ</rt><rp>)</rp></ruby>を<ruby>忘<rp>(</rp><rt>わす</rt><rp>)</rp></ruby>れちゃった。（啊，糟了，因为太着急过来，钱包忘带了。）"},{"t":"line","text":"わたしは、昨日夜の11時に友だちに来られて、困ってしまった。（昨晚11点朋友来了，我真够呛。）","furi":"わたしは、<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby><ruby>夜<rp>(</rp><rt>よる</rt><rp>)</rp></ruby>の11<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>に<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちに<ruby>来<rp>(</rp><rt>きた</rt><rp>)</rp></ruby>られて、<ruby>困<rp>(</rp><rt>こま</rt><rp>)</rp></ruby>ってしまった。（昨晚11点朋友来了，我真够呛。）"}],"id":"N4-18"},{"title":"19. ～てみる","blocks":[{"t":"label","label":"接续","text":"动词て形 + みる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + みる"},{"t":"label","label":"说明","text":"试着做某事。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"客：すみません、この帽子、被ってみてもいいですか。（不好意思，这顶帽子我可以试戴吗？）","furi":"<ruby>客<rp>(</rp><rt>きゃく</rt><rp>)</rp></ruby>：すみません、この<ruby>帽子<rp>(</rp><rt>ぼうし</rt><rp>)</rp></ruby>、<ruby>被<rp>(</rp><rt>こうむ</rt><rp>)</rp></ruby>ってみてもいいですか。（不好意思，这顶帽子我可以试戴吗？）"},{"t":"line","text":"店員：はい、どうぞ。（可以，请。）","furi":"<ruby>店員<rp>(</rp><rt>てんいん</rt><rp>)</rp></ruby>：はい、どうぞ。（可以，请。）"},{"t":"line","text":"わたしはできませんが息子にやらせてみましょう。（我做不了，让我儿子试试看吧。）","furi":"わたしはできませんが<ruby>息子<rp>(</rp><rt>むすこ</rt><rp>)</rp></ruby>にやらせてみましょう。（我做不了，让我儿子试试看吧。）"}],"id":"N4-19"},{"title":"20. ～もの","blocks":[{"t":"label","label":"接续","text":"动词/形容词的连体形","furi":""},{"t":"label","label":"说明","text":"形式体言，指代具体事物（不用于指代事情）。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"メニューの中から好きなものを選んでください。（请从菜单中选择您喜欢的。）","furi":"メニューの<ruby>中<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>から<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きなものを<ruby>選<rp>(</rp><rt>えら</rt><rp>)</rp></ruby>んでください。（请从菜单中选择您喜欢的。）"},{"t":"line","text":"A：あ、これおいしそうだね。食べてもいい？（啊，这个看起来很好吃，我能吃吗？）","furi":"A：あ、これおいしそうだね。<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べてもいい？（啊，这个看起来很好吃，我能吃吗？）"},{"t":"line","text":"B：だめよ。お客様にさしあげるものだから。（不行，这是要送给客人的。）","furi":"B：だめよ。お<ruby>客様<rp>(</rp><rt>きゃくさま</rt><rp>)</rp></ruby>にさしあげるものだから。（不行，这是要送给客人的。）"}],"id":"N4-20"},{"title":"21. ～こと","blocks":[{"t":"label","label":"接续","text":"动词/形容词的连体形","furi":""},{"t":"label","label":"说明","text":"形式体言，用于指代事情、事件。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"銀行の名前が変わったことを知りませんでした。（我不知道银行的名字变了。）","furi":"<ruby>銀行<rp>(</rp><rt>ぎんこう</rt><rp>)</rp></ruby>の<ruby>名前<rp>(</rp><rt>なまえ</rt><rp>)</rp></ruby>が<ruby>変<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わったことを<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>りませんでした。（我不知道银行的名字变了。）"},{"t":"line","text":"日本に行ったことがありますか。（你去过日本吗？）","furi":"<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったことがありますか。（你去过日本吗？）"},{"t":"line","text":"わたしの趣味は切手を集めることです。（我的爱好是集邮。）","furi":"わたしの<ruby>趣味<rp>(</rp><rt>しゅみ</rt><rp>)</rp></ruby>は<ruby>切手<rp>(</rp><rt>きって</rt><rp>)</rp></ruby>を<ruby>集<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>めることです。（我的爱好是集邮。）"}],"id":"N4-21"},{"title":"22. ～ということ","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + ということ","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ということ"},{"t":"label","label":"说明","text":"表示内容，用于归纳较长的句子。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"彼は来月結婚するということを、まだ誰にも知らせていない。（他下个月要结婚的事，还没告诉任何人。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>来月<rp>(</rp><rt>らいげつ</rt><rp>)</rp></ruby><ruby>結婚<rp>(</rp><rt>けっこん</rt><rp>)</rp></ruby>するということを、まだ<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>にも<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>らせていない。（他下个月要结婚的事，还没告诉任何人。）"},{"t":"line","text":"いろいろ調べて、その駅が一番便利だということがわかった。（经过各种调查，得知那个车站最方便。）","furi":"いろいろ<ruby>調<rp>(</rp><rt>しら</rt><rp>)</rp></ruby>べて、その<ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>が<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby><ruby>便利<rp>(</rp><rt>べんり</rt><rp>)</rp></ruby>だということがわかった。（经过各种调查，得知那个车站最方便。）"}],"id":"N4-22"},{"title":"23. ～の/んです","blocks":[{"t":"label","label":"接续","text":"动词/形容词普通形 + の/ん + です","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + の/ん + です"},{"t":"label","label":"说明","text":"表示说明、强调原因或要求对方说明。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"A：明日、一緒に出かけませんか。（明天一起出去吧？）","furi":"A：<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>、<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>かけませんか。（明天一起出去吧？）"},{"t":"line","text":"B：明日は友だちと約束があるんです。（明天我和朋友有约。）","furi":"B：<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>は<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちと<ruby>約束<rp>(</rp><rt>やくそく</rt><rp>)</rp></ruby>があるんです。（明天我和朋友有约。）"},{"t":"line","text":"その写真はどこで撮ったんですか。（那张照片是在哪儿拍的呀？）","furi":"その<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>はどこで<ruby>撮<rp>(</rp><rt>と</rt><rp>)</rp></ruby>ったんですか。（那张照片是在哪儿拍的呀？）"}],"id":"N4-23"},{"title":"24. ～のに（转折）","blocks":[{"t":"label","label":"接续","text":"动词/形容词普通形、名词+な + のに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>、<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+な + のに"},{"t":"label","label":"说明","text":"表示结果与预想不同，“却……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"田中さんは遅刻をしないと言ったのに、また遅刻をした。（田中说了不会迟到，却还是迟到了。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんは<ruby>遅刻<rp>(</rp><rt>ちこく</rt><rp>)</rp></ruby>をしないと<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったのに、また<ruby>遅刻<rp>(</rp><rt>ちこく</rt><rp>)</rp></ruby>をした。（田中说了不会迟到，却还是迟到了。）"},{"t":"line","text":"A：何回も電話したのに、どうして出てくれなかったんですか。（打了好几通电话，你为什么不接？）","furi":"A：<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>回<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>も<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>したのに、どうして<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>てくれなかったんですか。（打了好几通电话，你为什么不接？）"},{"t":"line","text":"B：すみません。（对不起。）","furi":""}],"id":"N4-24"}]},{"id":"N4-u3","title":"第3单元 许可、禁止和接尾词等","points":[{"title":"25. ～てもいい","blocks":[{"t":"label","label":"接续","text":"动词て形 + もいい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + もいい"},{"t":"label","label":"说明","text":"表示许可，“可以……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"明日はテキストを持ってこなくてもいいです。（明天不带教材来也可以。）","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>はテキストを<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>ってこなくてもいいです。（明天不带教材来也可以。）"},{"t":"line","text":"この帽子、被ってみてもいいですか。（这顶帽子我可以试戴吗？）","furi":"この<ruby>帽子<rp>(</rp><rt>ぼうし</rt><rp>)</rp></ruby>、<ruby>被<rp>(</rp><rt>こうむ</rt><rp>)</rp></ruby>ってみてもいいですか。（这顶帽子我可以试戴吗？）"}],"id":"N4-25"},{"title":"26. ～てもかまわない","blocks":[{"t":"label","label":"接续","text":"动词て形/い形容词て形 + もかまわない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + もかまわない"},{"t":"label","label":"说明","text":"表示容许，“……也行、……也可以”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"遅くてもかまわないので電話してください。（再晚也不要紧，请打电话来。）","furi":"<ruby>遅<rp>(</rp><rt>おそ</rt><rp>)</rp></ruby>くてもかまわないので<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>してください。（再晚也不要紧，请打电话来。）"},{"t":"line","text":"カメラは持って来なくてもかまいません。（不带相机来也不要紧。）","furi":"カメラは<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>って<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>なくてもかまいません。（不带相机来也不要紧。）"}],"id":"N4-26"},{"title":"27. ～てはいけない","blocks":[{"t":"label","label":"接续","text":"动词て形 + はいけない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + はいけない"},{"t":"label","label":"说明","text":"表示禁止，“不可以……、不能……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"この部屋に入ってはいけません。（不准进入这个房间。）","furi":"この<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>に<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>ってはいけません。（不准进入这个房间。）"},{"t":"line","text":"授業中、電話をかけてはいけません。（上课时间不准打电话。）","furi":"<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby><ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby>、<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>をかけてはいけません。（上课时间不准打电话。）"}],"id":"N4-27"},{"title":"28. ～なければならない/いけない","blocks":[{"t":"label","label":"接续","text":"动词ない形 + なければならない/いけない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + なければならない/いけない"},{"t":"label","label":"说明","text":"表示必须，“必须……、不……是不行的”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"食事の前には必ず手を洗わなければなりません。（吃饭前必须洗手。）","furi":"<ruby>食事<rp>(</rp><rt>しょくじ</rt><rp>)</rp></ruby>の<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>には<ruby>必<rp>(</rp><rt>かなら</rt><rp>)</rp></ruby>ず<ruby>手<rp>(</rp><rt>て</rt><rp>)</rp></ruby>を<ruby>洗<rp>(</rp><rt>あら</rt><rp>)</rp></ruby>わなければなりません。（吃饭前必须洗手。）"},{"t":"line","text":"部屋は明るくなければいけない。（房间必须采光好。）","furi":"<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>は<ruby>明<rp>(</rp><rt>あか</rt><rp>)</rp></ruby>るくなければいけない。（房间必须采光好。）"}],"id":"N4-28"},{"title":"29. ～なくてもいい","blocks":[{"t":"label","label":"接续","text":"动词ない形 + なくてもいい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + なくてもいい"},{"t":"label","label":"说明","text":"表示不必，“不……也行”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"電話をかけなくてもいいです。（不打电话也行。）","furi":"<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>をかけなくてもいいです。（不打电话也行。）"},{"t":"line","text":"病気が治ったから、薬を飲まなくてもいいです。（病已经好了，不吃药也行。）","furi":"<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>が<ruby>治<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>ったから、<ruby>薬<rp>(</rp><rt>くすり</rt><rp>)</rp></ruby>を<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>まなくてもいいです。（病已经好了，不吃药也行。）"}],"id":"N4-29"},{"title":"30. ～なくてはならない/いけない","blocks":[{"t":"label","label":"接续","text":"动词ない形 + なくてはならない/いけない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + なくてはならない/いけない"},{"t":"label","label":"说明","text":"表示必须，“必须……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"寝る前に必ず歯を磨かなくてはいけません。（睡前必须刷牙。）","furi":"<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>る<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>に<ruby>必<rp>(</rp><rt>かなら</rt><rp>)</rp></ruby>ず<ruby>歯<rp>(</rp><rt>は</rt><rp>)</rp></ruby>を<ruby>磨<rp>(</rp><rt>みが</rt><rp>)</rp></ruby>かなくてはいけません。（睡前必须刷牙。）"},{"t":"line","text":"嫌でもテストは受けてはいけません。（再讨厌也要参加考试。）","furi":"<ruby>嫌<rp>(</rp><rt>いや</rt><rp>)</rp></ruby>でもテストは<ruby>受<rp>(</rp><rt>う</rt><rp>)</rp></ruby>けてはいけません。（再讨厌也要参加考试。）"}],"id":"N4-30"},{"title":"31. ～すぎる","blocks":[{"t":"label","label":"接续","text":"动词ます形/い形容词词干/な形容词词干 + すぎる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + すぎる"},{"t":"label","label":"说明","text":"表示过度，“过于……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"タバコを吸いすぎるのはよくないですよ。（抽烟太多不好。）","furi":"タバコを<ruby>吸<rp>(</rp><rt>す</rt><rp>)</rp></ruby>いすぎるのはよくないですよ。（抽烟太多不好。）"},{"t":"line","text":"山田さんは買い物をしすぎて、お金がなくなった。（山田买东西没节制，把钱花光了。）","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby>さんは<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>い<ruby>物<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>をしすぎて、お<ruby>金<rp>(</rp><rt>かね</rt><rp>)</rp></ruby>がなくなった。（山田买东西没节制，把钱花光了。）"}],"id":"N4-31"},{"title":"32. ～だす","blocks":[{"t":"label","label":"接续","text":"动词ます形 + だす","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + だす"},{"t":"label","label":"说明","text":"表示开始，“开始……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"今まで寝ていた赤ちゃんが急に泣きだした。（一直睡着的婴儿突然哭了起来。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>まで<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>ていた<ruby>赤<rp>(</rp><rt>あか</rt><rp>)</rp></ruby>ちゃんが<ruby>急<rp>(</rp><rt>きゅう</rt><rp>)</rp></ruby>に<ruby>泣<rp>(</rp><rt>な</rt><rp>)</rp></ruby>きだした。（一直睡着的婴儿突然哭了起来。）"},{"t":"line","text":"先生がなかなか来ないので、学生が騒ぎだした。（老师总是不来，学生开始嚷嚷了。）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>がなかなか<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>ないので、<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>が<ruby>騒<rp>(</rp><rt>さわ</rt><rp>)</rp></ruby>ぎだした。（老师总是不来，学生开始嚷嚷了。）"}],"id":"N4-32"},{"title":"33. ～つづける","blocks":[{"t":"label","label":"接续","text":"动词ます形 + つづける","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + つづける"},{"t":"label","label":"说明","text":"表示持续，“持续……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"1時間ぐらい話しつづけたので、のどが渇いた。（因为连续说了大概一个小时，嗓子干了。）","furi":"1<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>ぐらい<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>しつづけたので、のどが<ruby>渇<rp>(</rp><rt>かわ</rt><rp>)</rp></ruby>いた。（因为连续说了大概一个小时，嗓子干了。）"},{"t":"line","text":"長い時間テレビを見つづけると、目が痛くなる。（长时间看电视的话，眼睛会疼。）","furi":"<ruby>長<rp>(</rp><rt>なが</rt><rp>)</rp></ruby>い<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>テレビを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>つづけると、<ruby>目<rp>(</rp><rt>め</rt><rp>)</rp></ruby>が<ruby>痛<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>くなる。（长时间看电视的话，眼睛会疼。）"}],"id":"N4-33"},{"title":"34. ～やすい","blocks":[{"t":"label","label":"接续","text":"动词ます形 + やすい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + やすい"},{"t":"label","label":"说明","text":"表示容易，“容易……、易于……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"この季節はたくさんの人が病気になりやすい。（这个季节很多人容易生病。）","furi":"この<ruby>季節<rp>(</rp><rt>きせつ</rt><rp>)</rp></ruby>はたくさんの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>になりやすい。（这个季节很多人容易生病。）"},{"t":"line","text":"このペンは書きやすいですね。（这支笔很好写。）","furi":"このペンは<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>きやすいですね。（这支笔很好写。）"}],"id":"N4-34"},{"title":"35. ～にくい","blocks":[{"t":"label","label":"接续","text":"动词ます形 + にくい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + にくい"},{"t":"label","label":"说明","text":"表示困难，“难以……、不容易……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"夜は暗くて歩いている人が見えにくいので、注意して運転します。（晚上很黑，很难看到行人，所以要小心驾驶。）","furi":"<ruby>夜<rp>(</rp><rt>よる</rt><rp>)</rp></ruby>は<ruby>暗<rp>(</rp><rt>くら</rt><rp>)</rp></ruby>くて<ruby>歩<rp>(</rp><rt>ある</rt><rp>)</rp></ruby>いている<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>えにくいので、<ruby>注意<rp>(</rp><rt>ちゅうい</rt><rp>)</rp></ruby>して<ruby>運転<rp>(</rp><rt>うんてん</rt><rp>)</rp></ruby>します。（晚上很黑，很难看到行人，所以要小心驾驶。）"},{"t":"line","text":"彼の名前は長くて覚えにくい。（他的名字很长，很难记。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>名前<rp>(</rp><rt>なまえ</rt><rp>)</rp></ruby>は<ruby>長<rp>(</rp><rt>なが</rt><rp>)</rp></ruby>くて<ruby>覚<rp>(</rp><rt>おぼ</rt><rp>)</rp></ruby>えにくい。（他的名字很长，很难记。）"}],"id":"N4-35"},{"title":"36. ～方（かた）","blocks":[{"t":"label","label":"接续","text":"动词ます形 + 方","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示方法，“……的方法”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"この漢字は読み方が難しいです。（这个汉字的读法很难。）","furi":"この<ruby>漢字<rp>(</rp><rt>かんじ</rt><rp>)</rp></ruby>は<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>み<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>が<ruby>難<rp>(</rp><rt>むずか</rt><rp>)</rp></ruby>しいです。（这个汉字的读法很难。）"},{"t":"line","text":"授業で手紙の書き方を習いました。（在课堂上学习了写信的方法。）","furi":"<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby>で<ruby>手紙<rp>(</rp><rt>てがみ</rt><rp>)</rp></ruby>の<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>き<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>を<ruby>習<rp>(</rp><rt>なら</rt><rp>)</rp></ruby>いました。（在课堂上学习了写信的方法。）"}],"id":"N4-36"},{"title":"37. ～さ","blocks":[{"t":"label","label":"接续","text":"い形容词词干/な形容词词干 + さ","furi":"い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + さ"},{"t":"label","label":"说明","text":"构成表示程度的名词，“……度、……之大”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"わたしの部屋の広さはこの部屋と大体同じです。（我房间的大小和这间房间差不多。）","furi":"わたしの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>の<ruby>広<rp>(</rp><rt>ひろ</rt><rp>)</rp></ruby>さはこの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>と<ruby>大体<rp>(</rp><rt>だいたい</rt><rp>)</rp></ruby><ruby>同<rp>(</rp><rt>おな</rt><rp>)</rp></ruby>じです。（我房间的大小和这间房间差不多。）"},{"t":"line","text":"そのかばんの軽さに驚いた。（我对那个包之轻感到惊讶。）","furi":"そのかばんの<ruby>軽<rp>(</rp><rt>かる</rt><rp>)</rp></ruby>さに<ruby>驚<rp>(</rp><rt>おどろ</rt><rp>)</rp></ruby>いた。（我对那个包之轻感到惊讶。）"}],"id":"N4-37"}]},{"id":"N4-u4","title":"第4单元 时间和举例等","points":[{"title":"38. ～うちに","blocks":[{"t":"label","label":"接续","text":"动词普通形/い形容词普通形/な形容词词干+な/名词+の + うちに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + うちに"},{"t":"label","label":"说明","text":"表示“在……之内、趁着……的时候”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"どうぞ、温かいうちにお召し上がりください。（请趁热吃吧。）","furi":"どうぞ、<ruby>温<rp>(</rp><rt>あたた</rt><rp>)</rp></ruby>かいうちにお<ruby>召<rp>(</rp><rt>め</rt><rp>)</rp></ruby>し<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>がりください。（请趁热吃吧。）"},{"t":"line","text":"若いうちに、いろいろな国へ旅行したいです。（想趁年轻去很多国家旅游。）","furi":"<ruby>若<rp>(</rp><rt>わか</rt><rp>)</rp></ruby>いうちに、いろいろな<ruby>国<rp>(</rp><rt>くに</rt><rp>)</rp></ruby>へ<ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>したいです。（想趁年轻去很多国家旅游。）"},{"t":"line","text":"彼女の話を聞いているうちに、涙が出てきた。（听她讲着讲着，眼泪流了出来。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>の<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>を<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>いているうちに、<ruby>涙<rp>(</rp><rt>なみだ</rt><rp>)</rp></ruby>が<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>てきた。（听她讲着讲着，眼泪流了出来。）"}],"id":"N4-38"},{"title":"39. ～ところ（正要）","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + ところ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ところ"},{"t":"label","label":"说明","text":"表示动作即将开始，“正要……、正打算……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"これから食事に行くところなんですが、一緒にいかがですか。（我正打算去吃饭，你也一起吗？）","furi":"これから<ruby>食事<rp>(</rp><rt>しょくじ</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くところなんですが、<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>にいかがですか。（我正打算去吃饭，你也一起吗？）"},{"t":"line","text":"これからパンを焼くところです。（正打算要烤面包。）","furi":"これからパンを<ruby>焼<rp>(</rp><rt>や</rt><rp>)</rp></ruby>くところです。（正打算要烤面包。）"}],"id":"N4-39"},{"title":"40. ～ているところだ","blocks":[{"t":"label","label":"接续","text":"动词ている形 + ところだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところだ"},{"t":"label","label":"说明","text":"表示动作正在进行，“正在……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"わたしは今、家で日本語を勉強しているところです。（我现在正在家里学日语。）","furi":"わたしは<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>、<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>で<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>を<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>しているところです。（我现在正在家里学日语。）"},{"t":"line","text":"山田社長は電話をかけているところです。（山田社长正在打电话。）","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby><ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>は<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>をかけているところです。（山田社长正在打电话。）"}],"id":"N4-40"},{"title":"41. ～たところだ","blocks":[{"t":"label","label":"接续","text":"动词た形 + ところだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところだ"},{"t":"label","label":"说明","text":"表示动作刚刚结束，“刚刚……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"A：明日の会議の資料、もう部長に届けた？（明天会议的资料，已经给部长送去了吗？）","furi":"A：<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>の<ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby>の<ruby>資料<rp>(</rp><rt>しりょう</rt><rp>)</rp></ruby>、もう<ruby>部長<rp>(</rp><rt>ぶちょう</rt><rp>)</rp></ruby>に<ruby>届<rp>(</rp><rt>とど</rt><rp>)</rp></ruby>けた？（明天会议的资料，已经给部长送去了吗？）"},{"t":"line","text":"B：はい、届けました。ついさっき、持って行ったところです。（是的，送去了。刚刚拿过去的。）","furi":"B：はい、<ruby>届<rp>(</rp><rt>とど</rt><rp>)</rp></ruby>けました。ついさっき、<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>って<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったところです。（是的，送去了。刚刚拿过去的。）"},{"t":"line","text":"今、お茶を入れたところなんです。（我刚泡好茶。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>、お<ruby>茶<rp>(</rp><rt>ちゃ</rt><rp>)</rp></ruby>を<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>れたところなんです。（我刚泡好茶。）"}],"id":"N4-41"},{"title":"42. ～ばかり（限定）","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词 + ばかり","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + ばかり"},{"t":"label","label":"说明","text":"表示限定，“只……、光是……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"田中さんはいつも人のやることに文句を言うばかりで自分では何もしない。（田中总是对别人做的事说长道短，自己却什么都不做。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんはいつも<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>のやることに<ruby>文句<rp>(</rp><rt>もんく</rt><rp>)</rp></ruby>を<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>うばかりで<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>では<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>もしない。（田中总是对别人做的事说长道短，自己却什么都不做。）"},{"t":"line","text":"あの子は肉ばかり食べて、野菜を全然食べません。（那孩子只吃肉，完全不吃蔬菜。）","furi":"あの<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>は<ruby>肉<rp>(</rp><rt>にく</rt><rp>)</rp></ruby>ばかり<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べて、<ruby>野菜<rp>(</rp><rt>やさい</rt><rp>)</rp></ruby>を<ruby>全然<rp>(</rp><rt>ぜんぜん</rt><rp>)</rp></ruby><ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べません。（那孩子只吃肉，完全不吃蔬菜。）"}],"id":"N4-42"},{"title":"43. ～てばかり","blocks":[{"t":"label","label":"接续","text":"动词て形 + ばかり","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ばかり"},{"t":"label","label":"说明","text":"表示总是重复相同行为，“总是……、只……、一个劲地……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"息子は毎日遊んでばかりで勉強をしない。（儿子每天只顾着玩不学习。）","furi":"<ruby>息子<rp>(</rp><rt>むすこ</rt><rp>)</rp></ruby>は<ruby>毎日<rp>(</rp><rt>まいにち</rt><rp>)</rp></ruby><ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>んでばかりで<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>をしない。（儿子每天只顾着玩不学习。）"},{"t":"line","text":"テレビを見てばかりいると、目が悪くなりますよ。（光顾着看电视的话，视力会下降的。）","furi":"テレビを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>てばかりいると、<ruby>目<rp>(</rp><rt>め</rt><rp>)</rp></ruby>が<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>くなりますよ。（光顾着看电视的话，视力会下降的。）"}],"id":"N4-43"},{"title":"44. ～たばかり","blocks":[{"t":"label","label":"接续","text":"动词た形 + ばかり","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ばかり"},{"t":"label","label":"说明","text":"表示刚做完某事，“刚刚……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"さっき起きたばかりで、まだ眠いです。（刚起床，还很困。）","furi":"さっき<ruby>起<rp>(</rp><rt>お</rt><rp>)</rp></ruby>きたばかりで、まだ<ruby>眠<rp>(</rp><rt>ねむ</rt><rp>)</rp></ruby>いです。（刚起床，还很困。）"},{"t":"line","text":"昼ごはんを食べたばかりなので、今は何も食べられない。（刚吃过午饭，现在什么都吃不下。）","furi":"<ruby>昼<rp>(</rp><rt>ひる</rt><rp>)</rp></ruby>ごはんを<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べたばかりなので、<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>も<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べられない。（刚吃过午饭，现在什么都吃不下。）"}],"id":"N4-44"},{"title":"45. ～までに","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词 + までに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + までに"},{"t":"label","label":"说明","text":"表示截止时间或期限，“到……为止、在……之前”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"明日の朝9時までにここへ来てください。（请在明天早上9点前到这里。）","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>の<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>9<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>までにここへ<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>てください。（请在明天早上9点前到这里。）"},{"t":"line","text":"この紙に名前を書いて、来週までに事務所に出してください。（请在这张纸上填好名字，下周前交到事务所。）","furi":"この<ruby>紙<rp>(</rp><rt>かみ</rt><rp>)</rp></ruby>に<ruby>名前<rp>(</rp><rt>なまえ</rt><rp>)</rp></ruby>を<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いて、<ruby>来週<rp>(</rp><rt>らいしゅう</rt><rp>)</rp></ruby>までに<ruby>事務所<rp>(</rp><rt>じむしょ</rt><rp>)</rp></ruby>に<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>してください。（请在这张纸上填好名字，下周前交到事务所。）"}],"id":"N4-45"},{"title":"46. ～でも","blocks":[{"t":"label","label":"接续","text":"名词 + でも","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + でも"},{"t":"label","label":"说明","text":"表示举例，“……之类的”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"暇だからゲームでもしましょう。（正好有时间，玩玩游戏之类的吧。）","furi":"<ruby>暇<rp>(</rp><rt>ひま</rt><rp>)</rp></ruby>だからゲームでもしましょう。（正好有时间，玩玩游戏之类的吧。）"},{"t":"line","text":"一緒にコーヒーでもいかがですか。（要不一起喝杯咖啡怎么样？）","furi":"<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>にコーヒーでもいかがですか。（要不一起喝杯咖啡怎么样？）"}],"id":"N4-46"},{"title":"47. ～とか","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词 + とか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + とか"},{"t":"label","label":"说明","text":"表示列举，“……之类的”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"引き出しにはスプーンとかナイフとかが入っています。（抽屉里放着勺子、餐刀等之类的东西。）","furi":"<ruby>引<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>き<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>しにはスプーンとかナイフとかが<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>っています。（抽屉里放着勺子、餐刀等之类的东西。）"},{"t":"line","text":"時には散歩するとか運動するとかしたほうが体にいいですよ。（偶尔散散步、做做运动什么的，对身体有好处。）","furi":"<ruby>時<rp>(</rp><rt>とき</rt><rp>)</rp></ruby>には<ruby>散歩<rp>(</rp><rt>さんぽ</rt><rp>)</rp></ruby>するとか<ruby>運動<rp>(</rp><rt>うんどう</rt><rp>)</rp></ruby>するとかしたほうが<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby>にいいですよ。（偶尔散散步、做做运动什么的，对身体有好处。）"}],"id":"N4-47"},{"title":"48. 疑问词+か","blocks":[{"t":"label","label":"接续","text":"疑问词 + か","furi":"<ruby>疑<rp>(</rp><rt>うたぐ</rt><rp>)</rp></ruby><ruby>问<rp>(</rp><rt>问</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + か"},{"t":"label","label":"说明","text":"表示不确定，“某个……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"何か飲みながら、話をしましょう。（边喝点什么边聊吧。）","furi":"<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>か<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みながら、<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>をしましょう。（边喝点什么边聊吧。）"},{"t":"line","text":"いつかまた日本へ来たいです。（以后还想再来日本。）","furi":"いつかまた<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>へ<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>たいです。（以后还想再来日本。）"},{"t":"line","text":"誰か手伝ってください。（谁能来帮帮我。）","furi":"<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>か<ruby>手伝<rp>(</rp><rt>てつだ</rt><rp>)</rp></ruby>ってください。（谁能来帮帮我。）"}],"id":"N4-48"},{"title":"49. 疑问词+も","blocks":[{"t":"label","label":"接续","text":"疑问词 + も（+否定）","furi":"<ruby>疑<rp>(</rp><rt>うたぐ</rt><rp>)</rp></ruby><ruby>问<rp>(</rp><rt>问</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + も（+否定）"},{"t":"label","label":"说明","text":"表示全盘否定，“都（不）……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"かばんを買いに行ったが、どれも高くて買えなかった。（去买包，可是哪个都贵得买不起。）","furi":"かばんを<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったが、どれも<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>くて<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>えなかった。（去买包，可是哪个都贵得买不起。）"},{"t":"line","text":"教室には誰もいない。（教室里一个人都没有。）","furi":"<ruby>教室<rp>(</rp><rt>きょうしつ</rt><rp>)</rp></ruby>には<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>もいない。（教室里一个人都没有。）"}],"id":"N4-49"},{"title":"50. ～または","blocks":[{"t":"label","label":"说明","text":"表示选择，“或者”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"1番の部屋、または2番の部屋に行ってください。（请去1号房或2号房。）","furi":"1<ruby>番<rp>(</rp><rt>ばん</rt><rp>)</rp></ruby>の<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>、または2<ruby>番<rp>(</rp><rt>ばん</rt><rp>)</rp></ruby>の<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってください。（请去1号房或2号房。）"},{"t":"line","text":"自己紹介は中国語で、または日本語でお願いします。（请用中文或者日语进行自我介绍。）","furi":"<ruby>自己<rp>(</rp><rt>じこ</rt><rp>)</rp></ruby><ruby>紹介<rp>(</rp><rt>しょうかい</rt><rp>)</rp></ruby>は<ruby>中国語<rp>(</rp><rt>ちゅうごくご</rt><rp>)</rp></ruby>で、または<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>でお<ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>いします。（请用中文或者日语进行自我介绍。）"}],"id":"N4-50"},{"title":"51. ～たり / ～たり～たり","blocks":[{"t":"label","label":"接续","text":"动词た形 + り / い形容词词干+かったり / な形容词词干+だったり / 名词+だったり","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + り / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+かったり / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+だったり / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+だったり"},{"t":"label","label":"说明","text":"列举动作或状态，“有时……有时……”或动作反复。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"昨日は散歩をしたり、料理を作ったりしました。（昨天散了会儿步，又做了饭什么的。）","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>は<ruby>散歩<rp>(</rp><rt>さんぽ</rt><rp>)</rp></ruby>をしたり、<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>を<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>ったりしました。（昨天散了会儿步，又做了饭什么的。）"},{"t":"line","text":"図書館で本を読んだり勉強したりします。（在图书馆看看书、学学习什么的。）","furi":"<ruby>図書館<rp>(</rp><rt>としょかん</rt><rp>)</rp></ruby>で<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>を<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>んだり<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>したりします。（在图书馆看看书、学学习什么的。）"},{"t":"line","text":"学生たちは、教室を出たり入ったりしています。（学生们从教室进进出出。）","furi":"<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>たちは、<ruby>教室<rp>(</rp><rt>きょうしつ</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>たり<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>ったりしています。（学生们从教室进进出出。）"}],"id":"N4-51"},{"title":"52. ～し / ～し～し","blocks":[{"t":"label","label":"接续","text":"动词/形容词普通形 + し + 同","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + し + <ruby>同<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"列举原因或事项，暗示还有其他。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"お金もないし、時間もないから、遊びに行けない。（既没钱又没时间，所以没法去玩。）","furi":"お<ruby>金<rp>(</rp><rt>かね</rt><rp>)</rp></ruby>もないし、<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>もないから、<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>びに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>けない。（既没钱又没时间，所以没法去玩。）"},{"t":"line","text":"はじめは言葉もわからないし、友だちもいないし、本当に大変でした。（一开始语言也不通，又没有朋友，真的很辛苦。）","furi":"はじめは<ruby>言葉<rp>(</rp><rt>ことば</rt><rp>)</rp></ruby>もわからないし、<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちもいないし、<ruby>本当<rp>(</rp><rt>ほんとう</rt><rp>)</rp></ruby>に<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>でした。（一开始语言也不通，又没有朋友，真的很辛苦。）"},{"t":"line","text":"山田さんのアパートはきれいだし、広いし、駅からも近い。（山田的公寓又漂亮又宽敞，离车站还近。）","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby>さんのアパートはきれいだし、<ruby>広<rp>(</rp><rt>ひろ</rt><rp>)</rp></ruby>いし、<ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>からも<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>い。（山田的公寓又漂亮又宽敞，离车站还近。）"}],"id":"N4-52"}]},{"id":"N4-u5","title":"第5单元 比较、程度、推测和打算等","points":[{"title":"53. ～ほど～ない","blocks":[{"t":"label","label":"接续","text":"名词 + ほど + 否定","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + ほど + <ruby>否定<rp>(</rp><rt>ひてい</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"“不如……、没有……那么……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"今日は昨日ほど風が強くない。（今天的风没有昨天大。）","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>は<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>ほど<ruby>風<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>が<ruby>強<rp>(</rp><rt>つよ</rt><rp>)</rp></ruby>くない。（今天的风没有昨天大。）"},{"t":"line","text":"わたしの部屋は姉の部屋ほど大きくない。（我的房间没有姐姐的大。）","furi":"わたしの<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>は<ruby>姉<rp>(</rp><rt>あね</rt><rp>)</rp></ruby>の<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>ほど<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きくない。（我的房间没有姐姐的大。）"}],"id":"N4-53"},{"title":"54. ～より","blocks":[{"t":"label","label":"接续","text":"名词/动词普通形 + より","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + より"},{"t":"label","label":"说明","text":"表示比较，“比……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"兄より弟のほうが背が高い。（弟弟比哥哥个儿高。）","furi":"<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>より<ruby>弟<rp>(</rp><rt>おとうと</rt><rp>)</rp></ruby>のほうが<ruby>背<rp>(</rp><rt>せ</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>い。（弟弟比哥哥个儿高。）"},{"t":"line","text":"息子が思ったより立派になった。（儿子比我想象的还要优秀。）","furi":"<ruby>息子<rp>(</rp><rt>むすこ</rt><rp>)</rp></ruby>が<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>ったより<ruby>立派<rp>(</rp><rt>りっぱ</rt><rp>)</rp></ruby>になった。（儿子比我想象的还要优秀。）"}],"id":"N4-54"},{"title":"55. ～まま","blocks":[{"t":"label","label":"接续","text":"动词た形/ない形+ない + まま","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>+ない + まま"},{"t":"label","label":"说明","text":"表示维持原状，“就那样……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"テレビをつけたまま寝てしまいました。（开着电视睡着了。）","furi":"テレビをつけたまま<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>てしまいました。（开着电视睡着了。）"},{"t":"line","text":"靴を履いたまま部屋に入ってしまった。（就那样穿着鞋子进了房间。）","furi":"<ruby>靴<rp>(</rp><rt>くつ</rt><rp>)</rp></ruby>を<ruby>履<rp>(</rp><rt>は</rt><rp>)</rp></ruby>いたまま<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>に<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>ってしまった。（就那样穿着鞋子进了房间。）"}],"id":"N4-55"},{"title":"56. ～のうち","blocks":[{"t":"label","label":"接续","text":"名词 + のうち","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + のうち"},{"t":"label","label":"说明","text":"表示范围，“在……之中、……当中”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"天ぷらと寿司とすき焼きのうちでどれが一番食べたいですか。（天妇罗、寿司和寿喜锅中，你最想吃哪个？）","furi":"<ruby>天<rp>(</rp><rt>てん</rt><rp>)</rp></ruby>ぷらと<ruby>寿司<rp>(</rp><rt>すし</rt><rp>)</rp></ruby>とすき<ruby>焼<rp>(</rp><rt>や</rt><rp>)</rp></ruby>きのうちでどれが<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby><ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べたいですか。（天妇罗、寿司和寿喜锅中，你最想吃哪个？）"},{"t":"line","text":"昨日もらったプレゼントのうち、ピンクのワンピースが一番好きだ。（昨天收到的礼物中，最喜欢粉色的连衣裙。）","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>もらったプレゼントのうち、ピンクのワンピースが<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby><ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きだ。（昨天收到的礼物中，最喜欢粉色的连衣裙。）"}],"id":"N4-56"},{"title":"57. 必ず","blocks":[{"t":"label","label":"说明","text":"表示没有例外，“一定、必须、务必”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"食事の前に必ず手を洗わなければなりません。（吃饭前必须洗手。）","furi":"<ruby>食事<rp>(</rp><rt>しょくじ</rt><rp>)</rp></ruby>の<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>に<ruby>必<rp>(</rp><rt>かなら</rt><rp>)</rp></ruby>ず<ruby>手<rp>(</rp><rt>て</rt><rp>)</rp></ruby>を<ruby>洗<rp>(</rp><rt>あら</rt><rp>)</rp></ruby>わなければなりません。（吃饭前必须洗手。）"},{"t":"line","text":"鈴木さんは必ず来ると思います。（我觉得铃木一定会来的。）","furi":"<ruby>鈴木<rp>(</rp><rt>すずき</rt><rp>)</rp></ruby>さんは<ruby>必<rp>(</rp><rt>かなら</rt><rp>)</rp></ruby>ず<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>ると<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>います。（我觉得铃木一定会来的。）"}],"id":"N4-57"},{"title":"58. ～かもしれない","blocks":[{"t":"label","label":"接续","text":"动词/形容词普通形、名词+かもしれない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>、<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+かもしれない"},{"t":"label","label":"说明","text":"表示可能性较低的推测，“也许……、可能……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"途中で雨が降るかもしれないから、傘を持って行きます。（半路可能会下雨，所以带着伞去吧。）","furi":"<ruby>途中<rp>(</rp><rt>とちゅう</rt><rp>)</rp></ruby>で<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>るかもしれないから、<ruby>傘<rp>(</rp><rt>かさ</rt><rp>)</rp></ruby>を<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>って<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。（半路可能会下雨，所以带着伞去吧。）"},{"t":"line","text":"大木さんは今日も大学に来なかった。病気かもしれない。（大木今天也没来学校，可能是生病了。）","furi":"<ruby>大木<rp>(</rp><rt>おおき</rt><rp>)</rp></ruby>さんは<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>も<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>に<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>なかった。<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>かもしれない。（大木今天也没来学校，可能是生病了。）"}],"id":"N4-58"},{"title":"59. ～つもりだ","blocks":[{"t":"label","label":"接续","text":"动词辞书形/ない形 + つもりだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + つもりだ"},{"t":"label","label":"说明","text":"表示打算，“打算……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"会社をやめてどうするつもりですか。（你辞职是打算怎样呢？）","furi":"<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>をやめてどうするつもりですか。（你辞职是打算怎样呢？）"},{"t":"line","text":"明日からたばこをやめるつもりです。（我打算明天开始戒烟。）","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>からたばこをやめるつもりです。（我打算明天开始戒烟。）"}],"id":"N4-59"},{"title":"60. ～たつもりで","blocks":[{"t":"label","label":"接续","text":"动词た形 + つもりで","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + つもりで"},{"t":"label","label":"说明","text":"表示当作、权当，“就算是……、当作……一样”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"歌手になったつもりで、みんなの前で歌を歌う。（就当自己是歌手，在大家面前唱歌。）","furi":"<ruby>歌手<rp>(</rp><rt>かしゅ</rt><rp>)</rp></ruby>になったつもりで、みんなの<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>で<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>を<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>う。（就当自己是歌手，在大家面前唱歌。）"},{"t":"line","text":"旅行に行ってきたつもりで、そのお金を貯めておいた。（就当作去旅游了，把那笔钱存了起来。）","furi":"<ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってきたつもりで、そのお<ruby>金<rp>(</rp><rt>かね</rt><rp>)</rp></ruby>を<ruby>貯<rp>(</rp><rt>た</rt><rp>)</rp></ruby>めておいた。（就当作去旅游了，把那笔钱存了起来。）"}],"id":"N4-60"},{"title":"61. ～はずだ/はずがない","blocks":[{"t":"label","label":"接续①","text":"动词/形容词普通形、名词+の + はずだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>、<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + はずだ"},{"t":"label","label":"说明①","text":"根据情理推测，“理应……、应该……”。","furi":""},{"t":"label","label":"例句①","text":"この薬を飲めば病気は治るはずです。（吃这种药的话，病应该会好。）","furi":"この<ruby>薬<rp>(</rp><rt>くすり</rt><rp>)</rp></ruby>を<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>めば<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>は<ruby>治<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>るはずです。（吃这种药的话，病应该会好。）"},{"t":"label","label":"接续②","text":"动词/形容词普通形、名词+の + はずがない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>、<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + はずがない"},{"t":"label","label":"说明②","text":"表示完全没有可能性，“不可能……、不会……”。","furi":""},{"t":"label","label":"例句②","text":"あの人は入院しているので、明日の旅行に来るはずがない。（那个人住院了，不可能来参加明天的旅行。）","furi":"あの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>は<ruby>入院<rp>(</rp><rt>にゅういん</rt><rp>)</rp></ruby>しているので、<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>の<ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>に<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>るはずがない。（那个人住院了，不可能来参加明天的旅行。）"}],"id":"N4-61"}]},{"id":"N4-u6","title":"第6单元 条件、目的和限定等","points":[{"title":"62. ～たら","blocks":[{"t":"label","label":"接续","text":"动词た形 + ら","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ら"},{"t":"label","label":"说明①","text":"表示假定条件，“如果……的话”。","furi":""},{"t":"label","label":"例句①","text":"道で近所の人に会ったら、挨拶しましょう。（如果在路上碰到邻居，打个招呼吧。）","furi":"<ruby>道<rp>(</rp><rt>みち</rt><rp>)</rp></ruby>で<ruby>近所<rp>(</rp><rt>きんじょ</rt><rp>)</rp></ruby>の<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>に<ruby>会<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>ったら、<ruby>挨拶<rp>(</rp><rt>あいさつ</rt><rp>)</rp></ruby>しましょう。（如果在路上碰到邻居，打个招呼吧。）"},{"t":"label","label":"说明②","text":"表示先后顺序，“……之后”。","furi":""},{"t":"label","label":"例句②","text":"出席するかどうかを決めたら、すぐ連絡してください。（决定是否出席之后，请立刻联系我。）","furi":"<ruby>出席<rp>(</rp><rt>しゅっせき</rt><rp>)</rp></ruby>するかどうかを<ruby>決<rp>(</rp><rt>き</rt><rp>)</rp></ruby>めたら、すぐ<ruby>連絡<rp>(</rp><rt>れんらく</rt><rp>)</rp></ruby>してください。（决定是否出席之后，请立刻联系我。）"},{"t":"label","label":"说明③","text":"表示意外发现，“……一看”。","furi":""},{"t":"label","label":"例句③","text":"壁の時計が斜めになっていたので掛け直したら、かえって曲がってしまった。（墙上的钟歪了，调整了一下，没想到更歪了。）","furi":"<ruby>壁<rp>(</rp><rt>かべ</rt><rp>)</rp></ruby>の<ruby>時計<rp>(</rp><rt>とけい</rt><rp>)</rp></ruby>が<ruby>斜<rp>(</rp><rt>なな</rt><rp>)</rp></ruby>めになっていたので<ruby>掛<rp>(</rp><rt>か</rt><rp>)</rp></ruby>け<ruby>直<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>したら、かえって<ruby>曲<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>がってしまった。（墙上的钟歪了，调整了一下，没想到更歪了。）"}],"id":"N4-62"},{"title":"63. ～なら","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词 + なら","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + なら"},{"t":"label","label":"说明①","text":"表示假定条件，“如果……的话”。","furi":""},{"t":"label","label":"例句①","text":"明日雨なら、洗濯をしません。（如果明天下雨，就不洗衣服。）","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby><ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>なら、<ruby>洗濯<rp>(</rp><rt>せんたく</rt><rp>)</rp></ruby>をしません。（如果明天下雨，就不洗衣服。）"},{"t":"label","label":"说明②","text":"提起话题，针对对方的话题给出回答或建议。","furi":""},{"t":"label","label":"例句②","text":"おなかがすいているなら、ドーナツがあるよ。（肚子饿了的话，有甜甜圈哟。）","furi":""},{"t":"label","label":"例句③","text":"美智子さんですか。美智子ならもう出かけましたけど。（是美智子吗？美智子已经出去了。）","furi":"<ruby>美智子<rp>(</rp><rt>みちこ</rt><rp>)</rp></ruby>さんですか。<ruby>美智子<rp>(</rp><rt>みちこ</rt><rp>)</rp></ruby>ならもう<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>かけましたけど。（是美智子吗？美智子已经出去了。）"}],"id":"N4-63"},{"title":"64. ～ば","blocks":[{"t":"label","label":"接续","text":"动词ば形 / い形容词词干+ければ / な形容词词干+なら","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ば<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+ければ / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+なら"},{"t":"label","label":"说明①","text":"表示假定条件，“如果……的话”。","furi":""},{"t":"label","label":"例句①","text":"毎日練習をすれば上手になります。（每天都练习的话，肯定会变熟练的。）","furi":"<ruby>毎日<rp>(</rp><rt>まいにち</rt><rp>)</rp></ruby><ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby>をすれば<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>になります。（每天都练习的话，肯定会变熟练的。）"},{"t":"label","label":"说明②","text":"表示恒常条件（真理、习惯），“一……就……”。","furi":""},{"t":"label","label":"例句②","text":"温度を0度以上にすれば、氷が水となる。（温度升至零度以上，冰就会化为水。）","furi":"<ruby>温度<rp>(</rp><rt>おんど</rt><rp>)</rp></ruby>を0<ruby>度<rp>(</rp><rt>ど</rt><rp>)</rp></ruby><ruby>以上<rp>(</rp><rt>いじょう</rt><rp>)</rp></ruby>にすれば、<ruby>氷<rp>(</rp><rt>こおり</rt><rp>)</rp></ruby>が<ruby>水<rp>(</rp><rt>みず</rt><rp>)</rp></ruby>となる。（温度升至零度以上，冰就会化为水。）"}],"id":"N4-64"},{"title":"65. ～と","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + と","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + と"},{"t":"label","label":"说明①","text":"表示恒常条件，“一……就……”。","furi":""},{"t":"label","label":"例句①","text":"わたしはこの音楽を聞くと必ず眠くなります。（我只要一听这个音乐就会犯困。）","furi":"わたしはこの<ruby>音楽<rp>(</rp><rt>おんがく</rt><rp>)</rp></ruby>を<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>くと<ruby>必<rp>(</rp><rt>かなら</rt><rp>)</rp></ruby>ず<ruby>眠<rp>(</rp><rt>ねむ</rt><rp>)</rp></ruby>くなります。（我只要一听这个音乐就会犯困。）"},{"t":"label","label":"说明②","text":"表示假定条件，“如果……的话”。","furi":""},{"t":"label","label":"例句②","text":"高速道路は今のところ渋滞していないから、この調子だと、あと30分で目的地に着くだろう。（目前高速不堵，照这样看，再过30分钟应该能到目的地。）","furi":"<ruby>高速<rp>(</rp><rt>こうそく</rt><rp>)</rp></ruby><ruby>道路<rp>(</rp><rt>どうろ</rt><rp>)</rp></ruby>は<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>のところ<ruby>渋滞<rp>(</rp><rt>じゅうたい</rt><rp>)</rp></ruby>していないから、この<ruby>調子<rp>(</rp><rt>ちょうし</rt><rp>)</rp></ruby>だと、あと30<ruby>分<rp>(</rp><rt>ふん</rt><rp>)</rp></ruby>で<ruby>目的<rp>(</rp><rt>もくてき</rt><rp>)</rp></ruby><ruby>地<rp>(</rp><rt>ち</rt><rp>)</rp></ruby>に<ruby>着<rp>(</rp><rt>つ</rt><rp>)</rp></ruby>くだろう。（目前高速不堵，照这样看，再过30分钟应该能到目的地。）"},{"t":"label","label":"说明③","text":"表示意外发现或同时发生，“刚一……就……”。","furi":""},{"t":"label","label":"例句③","text":"朝、カーテンを開けると、外は一面の銀世界だった。（早上打开窗帘，外面是一片银装素裹的世界。）","furi":"<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>、カーテンを<ruby>開<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>けると、<ruby>外<rp>(</rp><rt>そと</rt><rp>)</rp></ruby>は<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>面<rp>(</rp><rt>めん</rt><rp>)</rp></ruby>の<ruby>銀世界<rp>(</rp><rt>ぎんせかい</rt><rp>)</rp></ruby>だった。（早上打开窗帘，外面是一片银装素裹的世界。）"},{"t":"label","label":"说明④","text":"表示相继发生的动作，“一……立即……”。","furi":""},{"t":"label","label":"例句④","text":"田中さんはご飯を食べ終わると、すぐに勉強を始めました。（田中一吃完饭，马上就开始学习了。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんはご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>を<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べ<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わると、すぐに<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>を<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>めました。（田中一吃完饭，马上就开始学习了。）"}],"id":"N4-65"},{"title":"66. もし","blocks":[{"t":"label","label":"接续","text":"もし + 假设句","furi":"もし + <ruby>假<rp>(</rp><rt>假</rt><rp>)</rp></ruby><ruby>设<rp>(</rp><rt>设</rt><rp>)</rp></ruby><ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"“如果……”，多与「たら」「なら」「ば」连用。","furi":"“<ruby>如<rp>(</rp><rt>如</rt><rp>)</rp></ruby><ruby>果<rp>(</rp><rt>はて</rt><rp>)</rp></ruby>……”，<ruby>多<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>与<rp>(</rp><rt>あずか</rt><rp>)</rp></ruby>「たら」「なら」「ば」<ruby>连<rp>(</rp><rt>连</rt><rp>)</rp></ruby><ruby>用<rp>(</rp><rt>よう</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"もし彼が来たら、知らせてください。（如果他来了，请告诉我。）","furi":"もし<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>が<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>たら、<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>らせてください。（如果他来了，请告诉我。）"}],"id":"N4-66"},{"title":"67. もし～ても","blocks":[{"t":"label","label":"说明","text":"“就算……也……”。","furi":""},{"t":"label","label":"例句","text":"もし雨が降っても、試合をします。頑張ってください。（就算下雨也会比赛，请加油。）","furi":"もし<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>っても、<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>をします。<ruby>頑張<rp>(</rp><rt>がんば</rt><rp>)</rp></ruby>ってください。（就算下雨也会比赛，请加油。）"}],"id":"N4-67"},{"title":"68. ～といい","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + といい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + といい"},{"t":"label","label":"说明","text":"表示愿望，“……的话就好了”。","furi":""},{"t":"label","label":"例句","text":"病気が早くよくなるといいですね。（要是能快点痊愈就好了。）","furi":"<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>が<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>くよくなるといいですね。（要是能快点痊愈就好了。）"}],"id":"N4-68"},{"title":"69. ～ため（に）（原因）","blocks":[{"t":"label","label":"接续","text":"动词/形容词普通形、名词+の + ため（に）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>、<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + ため（に）"},{"t":"label","label":"说明","text":"表示客观原因，“由于……、因为……”。","furi":""},{"t":"label","label":"例句","text":"携帯電話を忘れたために、連絡できませんでした。（因为忘带手机，所以没法联系。）","furi":"<ruby>携帯<rp>(</rp><rt>けいたい</rt><rp>)</rp></ruby><ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>を<ruby>忘<rp>(</rp><rt>わす</rt><rp>)</rp></ruby>れたために、<ruby>連絡<rp>(</rp><rt>れんらく</rt><rp>)</rp></ruby>できませんでした。（因为忘带手机，所以没法联系。）"}],"id":"N4-69"},{"title":"70. ～ため（に）（目的）","blocks":[{"t":"label","label":"接续","text":"名词+の/动词辞书形 + ために","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の/<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ために"},{"t":"label","label":"说明","text":"表示目的，“为了……”。","furi":""},{"t":"label","label":"例句","text":"日本で働くために日本語を勉強している。（为了在日本工作而学习日语。）","furi":"<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>で<ruby>働<rp>(</rp><rt>はたら</rt><rp>)</rp></ruby>くために<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>を<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>している。（为了在日本工作而学习日语。）"}],"id":"N4-70"},{"title":"71. ～よう（に）（目的）","blocks":[{"t":"label","label":"接续","text":"动词辞书形/ない形/可能形 + よう（に）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/<ruby>可能<rp>(</rp><rt>かのう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + よう（に）"},{"t":"label","label":"说明","text":"表示目标，“为了……”。","furi":""},{"t":"label","label":"例句","text":"上手に話せるように何度も練習します。（为了能说得熟练，练习很多次。）","furi":"<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>に<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>せるように<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>度<rp>(</rp><rt>ど</rt><rp>)</rp></ruby>も<ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby>します。（为了能说得熟练，练习很多次。）"}],"id":"N4-71"},{"title":"72. ～ようになる","blocks":[{"t":"label","label":"接续","text":"动词辞书形/可能形 + ようになる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>可能<rp>(</rp><rt>かのう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ようになる"},{"t":"label","label":"说明","text":"表示从不具备到具备，“变得……、逐渐会……”。","furi":""},{"t":"label","label":"例句","text":"毎日練習したので、泳げるようになりました。（因为每天都在练习，所以逐渐会游了。）","furi":"<ruby>毎日<rp>(</rp><rt>まいにち</rt><rp>)</rp></ruby><ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby>したので、<ruby>泳<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>げるようになりました。（因为每天都在练习，所以逐渐会游了。）"}],"id":"N4-72"},{"title":"73. ～ようにする","blocks":[{"t":"label","label":"接续","text":"动词辞书形/ない形 + ようにする","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ようにする"},{"t":"label","label":"说明","text":"表示努力做到或不做某事，“要做到……”。","furi":""},{"t":"label","label":"例句","text":"夜は甘いものを食べないようにしています。（晚上努力做到不吃甜食。）","furi":"<ruby>夜<rp>(</rp><rt>よる</rt><rp>)</rp></ruby>は<ruby>甘<rp>(</rp><rt>あま</rt><rp>)</rp></ruby>いものを<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べないようにしています。（晚上努力做到不吃甜食。）"}],"id":"N4-73"},{"title":"74. ～（よ）うとする","blocks":[{"t":"label","label":"接续","text":"动词意志形 + とする","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>意志<rp>(</rp><rt>いし</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + とする"},{"t":"label","label":"说明","text":"表示打算、想要做某事。","furi":""},{"t":"label","label":"例句","text":"一番になろうとして、みんな一生懸命走る。（因为想成为第一名，大家拼命跑。）","furi":"<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby>になろうとして、みんな<ruby>一生懸命<rp>(</rp><rt>いっしょうけんめい</rt><rp>)</rp></ruby><ruby>走<rp>(</rp><rt>はし</rt><rp>)</rp></ruby>る。（因为想成为第一名，大家拼命跑。）"},{"t":"label","label":"例句②","text":"家を出ようとした時、電話がかかってきました。（正要出门的时候，电话响了。）","furi":"<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>ようとした<ruby>時<rp>(</rp><rt>とき</rt><rp>)</rp></ruby>、<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>がかかってきました。（正要出门的时候，电话响了。）"}],"id":"N4-74"},{"title":"75. ～ではなく","blocks":[{"t":"label","label":"说明","text":"“不是……而是……”。","furi":""},{"t":"label","label":"例句","text":"わたしは雨ではなく、風が強いほうが天気が悪いと思う。（我觉得不是雨天，而是刮大风的天气才是坏天气。）","furi":"わたしは<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>ではなく、<ruby>風<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>が<ruby>強<rp>(</rp><rt>つよ</rt><rp>)</rp></ruby>いほうが<ruby>天気<rp>(</rp><rt>てんき</rt><rp>)</rp></ruby>が<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>いと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>う。（我觉得不是雨天，而是刮大风的天气才是坏天气。）"}],"id":"N4-75"},{"title":"76. ～かわりに（代替、交换、转折）","blocks":[{"t":"label","label":"接续","text":"名词+の/动词辞书形 + かわりに","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の/<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + かわりに"},{"t":"label","label":"说明①","text":"表示代替。","furi":""},{"t":"label","label":"例句①","text":"社長のかわりに、副社長が挨拶をした。（副社长代替社长致辞。）","furi":"<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>のかわりに、<ruby>副<rp>(</rp><rt>ふく</rt><rp>)</rp></ruby><ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>が<ruby>挨拶<rp>(</rp><rt>あいさつ</rt><rp>)</rp></ruby>をした。（副社长代替社长致辞。）"},{"t":"label","label":"说明②","text":"表示取代。","furi":""},{"t":"label","label":"例句②","text":"お酒のかわりに、お茶を飲みましょう。（让我们以茶代酒吧。）","furi":"お<ruby>酒<rp>(</rp><rt>さけ</rt><rp>)</rp></ruby>のかわりに、お<ruby>茶<rp>(</rp><rt>ちゃ</rt><rp>)</rp></ruby>を<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みましょう。（让我们以茶代酒吧。）"},{"t":"label","label":"说明③","text":"表示不……而……。","furi":""},{"t":"label","label":"例句③","text":"大学に行くかわりに、専門学校に行く。（没上大学，而去读了专科学校。）","furi":"<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くかわりに、<ruby>専門<rp>(</rp><rt>せんもん</rt><rp>)</rp></ruby><ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く。（没上大学，而去读了专科学校。）"},{"t":"label","label":"说明④","text":"表示交换条件。","furi":""},{"t":"label","label":"例句④","text":"ノートを貸してもらったかわりに、昼ごはんをごちそうしよう。（你借我笔记，我请你吃午饭吧。）","furi":"ノートを<ruby>貸<rp>(</rp><rt>か</rt><rp>)</rp></ruby>してもらったかわりに、<ruby>昼<rp>(</rp><rt>ひる</rt><rp>)</rp></ruby>ごはんをごちそうしよう。（你借我笔记，我请你吃午饭吧。）"},{"t":"label","label":"说明⑤","text":"表示转折（两面性）。","furi":""},{"t":"label","label":"例句⑤","text":"この料理はおいしいかわりに、値段が高い。（这道菜很好吃，但价格贵。）","furi":"この<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>はおいしいかわりに、<ruby>値段<rp>(</rp><rt>ねだん</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>い。（这道菜很好吃，但价格贵。）"}],"id":"N4-76"},{"title":"77. ちっとも～ない","blocks":[{"t":"label","label":"说明","text":"“一点也不……”。","furi":""},{"t":"label","label":"例句","text":"彼が作った料理はちっともおいしくない。（他做的菜一点也不好吃。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>が<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>った<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>はちっともおいしくない。（他做的菜一点也不好吃。）"}],"id":"N4-77"},{"title":"78. おもに","blocks":[{"t":"label","label":"说明","text":"“主要”。","furi":""},{"t":"label","label":"例句","text":"この村ではおもに米を生産しています。（这个村子主要生产大米。）","furi":"この<ruby>村<rp>(</rp><rt>むら</rt><rp>)</rp></ruby>ではおもに<ruby>米<rp>(</rp><rt>こめ</rt><rp>)</rp></ruby>を<ruby>生産<rp>(</rp><rt>せいさん</rt><rp>)</rp></ruby>しています。（这个村子主要生产大米。）"}],"id":"N4-78"}]},{"id":"N4-u7","title":"第7单元 决定、依据和感受等","points":[{"title":"79. ～ないで","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ないで","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ないで"},{"t":"label","label":"说明","text":"“不……而……”或“没……就……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"昨日は歯を磨かないで寝ました。（昨天没刷牙就睡了。）","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>は<ruby>歯<rp>(</rp><rt>は</rt><rp>)</rp></ruby>を<ruby>磨<rp>(</rp><rt>みが</rt><rp>)</rp></ruby>かないで<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>ました。（昨天没刷牙就睡了。）"},{"t":"line","text":"わたしはコーヒーに砂糖を入れないで飲みます。（我喝咖啡不加糖。）","furi":"わたしはコーヒーに<ruby>砂糖<rp>(</rp><rt>さとう</rt><rp>)</rp></ruby>を<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>れないで<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>みます。（我喝咖啡不加糖。）"}],"id":"N4-79"},{"title":"80. ～なくて","blocks":[{"t":"label","label":"接续","text":"动词ない形 + なくて / い形容词词干+くなくて / な形容词词干+でなくて","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + なくて / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+くなくて / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+でなくて"},{"t":"label","label":"说明","text":"表示并列或轻微原因。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"あの店はあまり高くなくて、店員も親切です。（那家店不贵，店员还很热情。）","furi":"あの<ruby>店<rp>(</rp><rt>みせ</rt><rp>)</rp></ruby>はあまり<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>くなくて、<ruby>店員<rp>(</rp><rt>てんいん</rt><rp>)</rp></ruby>も<ruby>親切<rp>(</rp><rt>しんせつ</rt><rp>)</rp></ruby>です。（那家店不贵，店员还很热情。）"},{"t":"line","text":"子どもが勉強しなくて、親が心配している。（孩子不学习，父母很担心。）","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもが<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>しなくて、<ruby>親<rp>(</rp><rt>おや</rt><rp>)</rp></ruby>が<ruby>心配<rp>(</rp><rt>しんぱい</rt><rp>)</rp></ruby>している。（孩子不学习，父母很担心。）"}],"id":"N4-80"},{"title":"81. ～によると/によれば","blocks":[{"t":"label","label":"接续","text":"名词 + によると/によれば","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + によると/によれば"},{"t":"label","label":"说明","text":"表示传闻出处或推测依据。","furi":""},{"t":"label","label":"例句","text":"天気予報によると今夜は雪が降るそうです。（据天气预报说，今晚可能要下雪。）","furi":"<ruby>天気<rp>(</rp><rt>てんき</rt><rp>)</rp></ruby><ruby>予報<rp>(</rp><rt>よほう</rt><rp>)</rp></ruby>によると<ruby>今夜<rp>(</rp><rt>こんや</rt><rp>)</rp></ruby>は<ruby>雪<rp>(</rp><rt>ゆき</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>るそうです。（据天气预报说，今晚可能要下雪。）"}],"id":"N4-81"},{"title":"82. ～がする","blocks":[{"t":"label","label":"接续","text":"名词 + がする","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + がする"},{"t":"label","label":"说明","text":"表示感觉（听觉、嗅觉、味觉等），“感觉到……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"台所からいいにおいがします。（从厨房飘来香味。）","furi":"<ruby>台所<rp>(</rp><rt>だいどころ</rt><rp>)</rp></ruby>からいいにおいがします。（从厨房飘来香味。）"},{"t":"line","text":"隣の家でピアノの音がしている。（从邻居家传来钢琴声。）","furi":"<ruby>隣<rp>(</rp><rt>となり</rt><rp>)</rp></ruby>の<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>でピアノの<ruby>音<rp>(</rp><rt>おと</rt><rp>)</rp></ruby>がしている。（从邻居家传来钢琴声。）"}],"id":"N4-82"},{"title":"83. ～か～ないか","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + か + 动词ない形 + ないか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + か + <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ないか"},{"t":"label","label":"说明","text":"“是……还是不……”。","furi":""},{"t":"label","label":"例句","text":"留学に行くか行かないかを迷っています。（在为去不去留学而烦恼。）","furi":"<ruby>留学<rp>(</rp><rt>りゅうがく</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くか<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>かないかを<ruby>迷<rp>(</rp><rt>まよ</rt><rp>)</rp></ruby>っています。（在为去不去留学而烦恼。）"}],"id":"N4-83"},{"title":"84. ～かどうか","blocks":[{"t":"label","label":"接续","text":"动词/形容词普通形、名词 + かどうか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>、<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + かどうか"},{"t":"label","label":"说明","text":"“是否……”。","furi":""},{"t":"label","label":"例句","text":"中田さんが大学を卒業できたかどうか知っていますか。（你知道中田有没有毕业吗？）","furi":"<ruby>中田<rp>(</rp><rt>なかた</rt><rp>)</rp></ruby>さんが<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>を<ruby>卒業<rp>(</rp><rt>そつぎょう</rt><rp>)</rp></ruby>できたかどうか<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>っていますか。（你知道中田有没有毕业吗？）"}],"id":"N4-84"},{"title":"85. ～だい/かい","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + だい/かい","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + だい/かい"},{"t":"label","label":"说明","text":"表示疑问，男性口语。","furi":""},{"t":"label","label":"例句","text":"今何時だい。（现在几点啊？）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby><ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>だい。（现在几点啊？）"},{"t":"label","label":"例句②","text":"行くかい。（去吗？）","furi":"<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くかい。（去吗？）"}],"id":"N4-85"},{"title":"86. ～ことがある","blocks":[{"t":"label","label":"接续①","text":"动词た形 + ことがある","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ことがある"},{"t":"label","label":"说明①","text":"表示有过某种经历。","furi":""},{"t":"label","label":"例句①","text":"まだこのマンガを読んだことがありません。（我还没看过这本漫画。）","furi":"まだこのマンガを<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>んだことがありません。（我还没看过这本漫画。）"},{"t":"label","label":"接续②","text":"动词辞书形 + ことがある","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ことがある"},{"t":"label","label":"说明②","text":"表示有时、偶尔做某事。","furi":""},{"t":"label","label":"例句②","text":"時々日本の歌を歌うことがあります。（我有时会唱日语歌。）","furi":"<ruby>時々<rp>(</rp><rt>ときどき</rt><rp>)</rp></ruby><ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>の<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>を<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>うことがあります。（我有时会唱日语歌。）"}],"id":"N4-86"},{"title":"87. ～ことができる","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + ことができる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ことができる"},{"t":"label","label":"说明","text":"表示能力或可能性，“可以……、能……”。","furi":""},{"t":"label","label":"例句","text":"図書館でこの町の歴史を調べることができます。（可以在图书馆查阅这个城市的历史。）","furi":"<ruby>図書館<rp>(</rp><rt>としょかん</rt><rp>)</rp></ruby>でこの<ruby>町<rp>(</rp><rt>まち</rt><rp>)</rp></ruby>の<ruby>歴史<rp>(</rp><rt>れきし</rt><rp>)</rp></ruby>を<ruby>調<rp>(</rp><rt>しら</rt><rp>)</rp></ruby>べることができます。（可以在图书馆查阅这个城市的历史。）"}],"id":"N4-87"},{"title":"88. ～という","blocks":[{"t":"label","label":"接续①","text":"名词 + という","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + という"},{"t":"label","label":"说明①","text":"表示名称，“叫作……”。","furi":""},{"t":"label","label":"例句①","text":"カトレアという店を知っていますか。（你知道一家叫“卡特米兰”的店吗？）","furi":"カトレアという<ruby>店<rp>(</rp><rt>みせ</rt><rp>)</rp></ruby>を<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>っていますか。（你知道一家叫“卡特米兰”的店吗？）"},{"t":"label","label":"接续②","text":"句子的普通形 + という","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + という"},{"t":"label","label":"说明②","text":"表示引用内容，“说……”。","furi":""},{"t":"label","label":"例句②","text":"佐藤さんは日本料理がおいしいと言いました。（佐藤说日本菜好吃。）","furi":"<ruby>佐藤<rp>(</rp><rt>さとう</rt><rp>)</rp></ruby>さんは<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby><ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>がおいしいと<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>いました。（佐藤说日本菜好吃。）"}],"id":"N4-88"},{"title":"89. ～（よ）うと思う","blocks":[{"t":"label","label":"接续","text":"动词意志形 + と思う","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>意志<rp>(</rp><rt>いし</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + と<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>う"},{"t":"label","label":"说明","text":"表示说话人的打算或计划，“我想……、我打算……”。","furi":""},{"t":"label","label":"例句","text":"これから買い物に行って、カレーを作ろうと思います。（我现在去买东西，准备做咖喱。）","furi":"これから<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>い<ruby>物<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>って、カレーを<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>ろうと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>います。（我现在去买东西，准备做咖喱。）"},{"t":"label","label":"例句②","text":"来月富士山に登ろうと思っています。（我打算下个月爬富士山。）","furi":"<ruby>来月<rp>(</rp><rt>らいげつ</rt><rp>)</rp></ruby><ruby>富士山<rp>(</rp><rt>ふじさん</rt><rp>)</rp></ruby>に<ruby>登<rp>(</rp><rt>のぼ</rt><rp>)</rp></ruby>ろうと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>っています。（我打算下个月爬富士山。）"}],"id":"N4-89"}]},{"id":"N4-u8","title":"第8单元 授受关系","points":[{"title":"90. あげる/さしあげる","blocks":[{"t":"label","label":"说明","text":"“给……、送上……”。主语是自己或己方的人。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"山川さんの誕生日にこの財布をあげるつもりです。（山川生日时，我打算送他这个钱包。）","furi":"<ruby>山川<rp>(</rp><rt>やまかわ</rt><rp>)</rp></ruby>さんの<ruby>誕生<rp>(</rp><rt>たんじょう</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>び</rt><rp>)</rp></ruby>にこの<ruby>財布<rp>(</rp><rt>さいふ</rt><rp>)</rp></ruby>をあげるつもりです。（山川生日时，我打算送他这个钱包。）"},{"t":"line","text":"先生にケーキをさしあげました。（送老师蛋糕。）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>にケーキをさしあげました。（送老师蛋糕。）"}],"id":"N4-90"},{"title":"91. ～てあげる/てさしあげる","blocks":[{"t":"label","label":"接续","text":"动词て形 + あげる/さしあげる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + あげる/さしあげる"},{"t":"label","label":"说明","text":"为别人做某事。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"うん、持ってるよ。貸してあげるよ。（嗯，我有。我借给你。）","furi":"うん、<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>ってるよ。<ruby>貸<rp>(</rp><rt>か</rt><rp>)</rp></ruby>してあげるよ。（嗯，我有。我借给你。）"},{"t":"line","text":"吉田先生を駅まで車で送ってさしあげた。（我开车把吉田老师送到了车站。）","furi":"<ruby>吉田<rp>(</rp><rt>よしだ</rt><rp>)</rp></ruby><ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>を<ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>まで<ruby>車<rp>(</rp><rt>くるま</rt><rp>)</rp></ruby>で<ruby>送<rp>(</rp><rt>おく</rt><rp>)</rp></ruby>ってさしあげた。（我开车把吉田老师送到了车站。）"}],"id":"N4-91"},{"title":"92. もらう/いただく","blocks":[{"t":"label","label":"说明","text":"从别人那里得到某物。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"これは姉にもらった本です。（这是姐姐给我的书。）","furi":"これは<ruby>姉<rp>(</rp><rt>あね</rt><rp>)</rp></ruby>にもらった<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>です。（这是姐姐给我的书。）"},{"t":"line","text":"誕生日に友だちからプレゼントをたくさんもらった。（生日时从朋友那里收到很多礼物。）","furi":"<ruby>誕生<rp>(</rp><rt>たんじょう</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>び</rt><rp>)</rp></ruby>に<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちからプレゼントをたくさんもらった。（生日时从朋友那里收到很多礼物。）"}],"id":"N4-92"},{"title":"93. ～てもらう/ていただく","blocks":[{"t":"label","label":"接续","text":"动词て形 + もらう/いただく","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + もらう/いただく"},{"t":"label","label":"说明","text":"请别人为自己做某事。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"わたしは先生に作文を直していただきました。（我请老师帮我修改了作文。）","furi":"わたしは<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>に<ruby>作文<rp>(</rp><rt>さくぶん</rt><rp>)</rp></ruby>を<ruby>直<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>していただきました。（我请老师帮我修改了作文。）"},{"t":"line","text":"辞書を忘れたので、友だちに貸してもらった。（忘记带词典了，朋友借给了我。）","furi":"<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>を<ruby>忘<rp>(</rp><rt>わす</rt><rp>)</rp></ruby>れたので、<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちに<ruby>貸<rp>(</rp><rt>か</rt><rp>)</rp></ruby>してもらった。（忘记带词典了，朋友借给了我。）"}],"id":"N4-93"},{"title":"94. くれる/くださる","blocks":[{"t":"label","label":"说明","text":"别人给我（或己方的人）某物。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"木田さんは、わたしに本をくれました。（木田给了我一本书。）","furi":"<ruby>木田<rp>(</rp><rt>きだ</rt><rp>)</rp></ruby>さんは、わたしに<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>をくれました。（木田给了我一本书。）"},{"t":"line","text":"おじは万年筆をくださいました。（叔叔给了我一支钢笔。）","furi":"おじは<ruby>万年筆<rp>(</rp><rt>まんねんひつ</rt><rp>)</rp></ruby>をくださいました。（叔叔给了我一支钢笔。）"}],"id":"N4-94"},{"title":"95. ～てくれる/てくださる","blocks":[{"t":"label","label":"接续","text":"动词て形 + くれる/くださる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + くれる/くださる"},{"t":"label","label":"说明","text":"别人为我（或己方的人）做某事。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"そちらの方がわたしの荷物を持ってくださいました。（是那位把我的行李拿过来的。）","furi":"そちらの<ruby>方<rp>(</rp><rt>ほう</rt><rp>)</rp></ruby>がわたしの<ruby>荷物<rp>(</rp><rt>にもつ</rt><rp>)</rp></ruby>を<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>ってくださいました。（是那位把我的行李拿过来的。）"},{"t":"line","text":"友だちが掃除を手伝ってくれた。（朋友帮我一起打扫了。）","furi":"<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちが<ruby>掃除<rp>(</rp><rt>そうじ</rt><rp>)</rp></ruby>を<ruby>手伝<rp>(</rp><rt>てつだ</rt><rp>)</rp></ruby>ってくれた。（朋友帮我一起打扫了。）"}],"id":"N4-95"},{"title":"96. やる","blocks":[{"t":"label","label":"说明","text":"自己给地位低的人或动植物某物。","furi":""},{"t":"label","label":"例句","text":"金魚に餌をやる。（给金鱼喂食。）","furi":"<ruby>金魚<rp>(</rp><rt>きんぎょ</rt><rp>)</rp></ruby>に<ruby>餌<rp>(</rp><rt>えさ</rt><rp>)</rp></ruby>をやる。（给金鱼喂食。）"}],"id":"N4-96"},{"title":"97. ～てやる","blocks":[{"t":"label","label":"接续","text":"动词て形 + やる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + やる"},{"t":"label","label":"说明","text":"自己为身份低的人或动物做某事。","furi":""},{"t":"label","label":"例句","text":"わたしが弟のシャツを洗ってやった。（我帮弟弟洗了衬衫。）","furi":"わたしが<ruby>弟<rp>(</rp><rt>おとうと</rt><rp>)</rp></ruby>のシャツを<ruby>洗<rp>(</rp><rt>あら</rt><rp>)</rp></ruby>ってやった。（我帮弟弟洗了衬衫。）"}],"id":"N4-97"},{"title":"98. ～てちょうだい","blocks":[{"t":"label","label":"接续","text":"动词て形 + ちょうだい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ちょうだい"},{"t":"label","label":"说明","text":"表示请求，女性或儿童用语。","furi":""},{"t":"label","label":"例句","text":"その単語の読み方を教えてちょうだい。（告诉我那个单词怎么念嘛。）","furi":"その<ruby>単語<rp>(</rp><rt>たんご</rt><rp>)</rp></ruby>の<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>み<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>を<ruby>教<rp>(</rp><rt>おし</rt><rp>)</rp></ruby>えてちょうだい。（告诉我那个单词怎么念嘛。）"}],"id":"N4-98"},{"title":"99. ～（さ）せてください/（さ）せないでください","blocks":[{"t":"label","label":"接续","text":"动词使役形て形 + ください","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>使役<rp>(</rp><rt>しえき</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ください"},{"t":"label","label":"说明","text":"“请让我……、请不要让我……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"その仕事はぜひわたしにやらせてください。（那份工作请一定交给我来做。）","furi":"その<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>はぜひわたしにやらせてください。（那份工作请一定交给我来做。）"},{"t":"line","text":"危ないですから、子どもを一人で遊ばせないでください。（很危险的，请不要让孩子一个人玩耍。）","furi":"<ruby>危<rp>(</rp><rt>あぶ</rt><rp>)</rp></ruby>ないですから、<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもを<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>で<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>ばせないでください。（很危险的，请不要让孩子一个人玩耍。）"}],"id":"N4-99"}]},{"id":"N4-u9","title":"第9单元 敬语1（尊他语）","points":[{"title":"100. いらっしゃる","blocks":[{"t":"label","label":"说明","text":"是「いる」「行く」「来る」的尊他语。","furi":"<ruby>是<rp>(</rp><rt>ぜ</rt><rp>)</rp></ruby>「いる」「<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く」「<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"どなたか質問のある方はいらっしゃいませんか。（哪位有问题吗？）","furi":"どなたか<ruby>質問<rp>(</rp><rt>しつもん</rt><rp>)</rp></ruby>のある<ruby>方<rp>(</rp><rt>ほう</rt><rp>)</rp></ruby>はいらっしゃいませんか。（哪位有问题吗？）"},{"t":"line","text":"先生は今度の土曜日はずっと研究室にいらっしゃるそうです。（老师这周六好像一直会在研究室。）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>は<ruby>今度<rp>(</rp><rt>こんど</rt><rp>)</rp></ruby>の<ruby>土曜日<rp>(</rp><rt>どようび</rt><rp>)</rp></ruby>はずっと<ruby>研究<rp>(</rp><rt>けんきゅう</rt><rp>)</rp></ruby><ruby>室<rp>(</rp><rt>しつ</rt><rp>)</rp></ruby>にいらっしゃるそうです。（老师这周六好像一直会在研究室。）"}],"id":"N4-100"},{"title":"101. 見える/お見えになる","blocks":[{"t":"label","label":"说明","text":"「来る」的尊他语。","furi":"「<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"お客さまがお見えになりました。（客人来了。）","furi":"お<ruby>客<rp>(</rp><rt>きゃく</rt><rp>)</rp></ruby>さまがお<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>えになりました。（客人来了。）"}],"id":"N4-101"},{"title":"102. おいでになる","blocks":[{"t":"label","label":"说明","text":"「来る」「行く」「いる」的尊他语。","furi":"「<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る」「<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く」「いる」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"まだおいでになるまで少し時間がありますから、そこで待っていてください。（离老师来还有一点时间，请在那里等一下。）","furi":"まだおいでになるまで<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>がありますから、そこで<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>っていてください。（离老师来还有一点时间，请在那里等一下。）"}],"id":"N4-102"},{"title":"103. お越しになる","blocks":[{"t":"label","label":"说明","text":"「来る」的尊他语。","furi":"「<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"鈴木さんは日本からお越しになりました。（铃木来自日本。）","furi":"<ruby>鈴木<rp>(</rp><rt>すずき</rt><rp>)</rp></ruby>さんは<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>からお<ruby>越<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>しになりました。（铃木来自日本。）"}],"id":"N4-103"},{"title":"104. おっしゃる","blocks":[{"t":"label","label":"说明","text":"「言う」的尊他语。","furi":"「<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>う」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"意見のある方は、おっしゃってください。（有意见的请讲。）","furi":"<ruby>意見<rp>(</rp><rt>いけん</rt><rp>)</rp></ruby>のある<ruby>方<rp>(</rp><rt>ほう</rt><rp>)</rp></ruby>は、おっしゃってください。（有意见的请讲。）"},{"t":"label","label":"例句②","text":"お名前は何とおっしゃいますか。（您怎么称呼？）","furi":"お<ruby>名前<rp>(</rp><rt>なまえ</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby>とおっしゃいますか。（您怎么称呼？）"}],"id":"N4-104"},{"title":"105. ご存知です","blocks":[{"t":"label","label":"说明","text":"「知っている」的尊他语。","furi":"「<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>っている」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"先生は山下さんの住所をご存知ですか。（老师知道山下住哪儿吗？）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>は<ruby>山下<rp>(</rp><rt>やました</rt><rp>)</rp></ruby>さんの<ruby>住所<rp>(</rp><rt>じゅうしょ</rt><rp>)</rp></ruby>をご<ruby>存知<rp>(</rp><rt>ぞんじ</rt><rp>)</rp></ruby>ですか。（老师知道山下住哪儿吗？）"}],"id":"N4-105"},{"title":"106. ご覧になる","blocks":[{"t":"label","label":"说明","text":"「見る」的尊他语。","furi":"「<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>る」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"中川さんが描いた絵をご覧になりましたか。（您看了中川画的画了吗？）","furi":"<ruby>中川<rp>(</rp><rt>なかがわ</rt><rp>)</rp></ruby>さんが<ruby>描<rp>(</rp><rt>えが</rt><rp>)</rp></ruby>いた<ruby>絵<rp>(</rp><rt>え</rt><rp>)</rp></ruby>をご<ruby>覧<rp>(</rp><rt>らん</rt><rp>)</rp></ruby>になりましたか。（您看了中川画的画了吗？）"}],"id":"N4-106"},{"title":"107. ご覧ください","blocks":[{"t":"label","label":"说明","text":"「見る」的尊他语请求形。","furi":"「<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>る」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby><ruby>请<rp>(</rp><rt>请</rt><rp>)</rp></ruby><ruby>求<rp>(</rp><rt>もとめ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"添付ファイルをご覧ください。（请看附件。）","furi":"<ruby>添付<rp>(</rp><rt>てんぷ</rt><rp>)</rp></ruby>ファイルをご<ruby>覧<rp>(</rp><rt>らん</rt><rp>)</rp></ruby>ください。（请看附件。）"}],"id":"N4-107"},{"title":"108. 召す","blocks":[{"t":"label","label":"说明","text":"「食べる」「飲む」「着る」的尊他语。","furi":"「<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる」「<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>む」「<ruby>着<rp>(</rp><rt>き</rt><rp>)</rp></ruby>る」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"朝ご飯をお召しになりましたか。（您吃过早饭了吗？）","furi":"<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>ご<ruby>飯<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>をお<ruby>召<rp>(</rp><rt>めし</rt><rp>)</rp></ruby>しになりましたか。（您吃过早饭了吗？）"}],"id":"N4-108"},{"title":"109. 召し上がる","blocks":[{"t":"label","label":"说明","text":"「食べる」「飲む」的尊他语。","furi":"「<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる」「<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>む」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"どうぞ、温かいうちに召し上がってください。（请趁热吃吧。）","furi":"どうぞ、<ruby>温<rp>(</rp><rt>あたた</rt><rp>)</rp></ruby>かいうちに<ruby>召<rp>(</rp><rt>め</rt><rp>)</rp></ruby>し<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>がってください。（请趁热吃吧。）"}],"id":"N4-109"},{"title":"110. お/ご～なさる","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + なさる / ご + III类动词词干 + なさる","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + なさる / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + なさる"},{"t":"label","label":"说明","text":"对动作主体的尊敬。","furi":""},{"t":"label","label":"例句","text":"部長は新企画についてお話しなさいました。（部长谈了新的企划。）","furi":"<ruby>部長<rp>(</rp><rt>ぶちょう</rt><rp>)</rp></ruby>は<ruby>新<rp>(</rp><rt>しん</rt><rp>)</rp></ruby><ruby>企画<rp>(</rp><rt>きかく</rt><rp>)</rp></ruby>についてお<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>しなさいました。（部长谈了新的企划。）"},{"t":"label","label":"例句②","text":"事前にご予約なさったほうがいいと思います。（我认为最好事先预约好。）","furi":"<ruby>事前<rp>(</rp><rt>じぜん</rt><rp>)</rp></ruby>にご<ruby>予約<rp>(</rp><rt>よやく</rt><rp>)</rp></ruby>なさったほうがいいと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>います。（我认为最好事先预约好。）"}],"id":"N4-110"},{"title":"111. お/ご～になる","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + になる / ご + III类动词词干 + になる","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + になる / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + になる"},{"t":"label","label":"说明","text":"对动作主体的尊敬。","furi":""},{"t":"label","label":"例句","text":"先生はもうお帰りになりました。（老师已经回去了。）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>はもうお<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>りになりました。（老师已经回去了。）"},{"t":"label","label":"例句②","text":"ここでお待ちになってください。（请在此稍等。）","furi":"ここでお<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ちになってください。（请在此稍等。）"}],"id":"N4-111"},{"title":"112. お/ご～ください","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + ください / ご + III类动词词干 + ください","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ください / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + ください"},{"t":"label","label":"说明","text":"请求别人做某事的尊敬说法。","furi":""},{"t":"label","label":"例句","text":"では、お元気で。ご両親にもどうぞよろしくお伝えください。（那么祝您身体健康，请代我向您父母问好。）","furi":"では、お<ruby>元気<rp>(</rp><rt>げんき</rt><rp>)</rp></ruby>で。ご<ruby>両親<rp>(</rp><rt>りょうしん</rt><rp>)</rp></ruby>にもどうぞよろしくお<ruby>伝<rp>(</rp><rt>つた</rt><rp>)</rp></ruby>えください。（那么祝您身体健康，请代我向您父母问好。）"}],"id":"N4-112"},{"title":"113. 敬语助动词「れる/られる」","blocks":[{"t":"label","label":"接续","text":"I类ない形 + れる / II类ない形 + られる / III类：する→される、来る→来られる","furi":"I<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + れる / II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + られる / III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：する→される、<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る→<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>られる"},{"t":"label","label":"说明","text":"尊敬程度较低的尊他语。","furi":""},{"t":"label","label":"例句","text":"佐藤さんは何時に帰られましたか。（佐藤几点回来的？）","furi":"<ruby>佐藤<rp>(</rp><rt>さとう</rt><rp>)</rp></ruby>さんは<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>に<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>られましたか。（佐藤几点回来的？）"}],"id":"N4-113"}]},{"id":"N4-u10","title":"第10单元 敬语2（自谦语）","points":[{"title":"114. いたす","blocks":[{"t":"label","label":"说明","text":"「する」的自谦语。","furi":"「する」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"ご指示どおりにいたします。（按照您的指示去办。）","furi":"ご<ruby>指示<rp>(</rp><rt>しじ</rt><rp>)</rp></ruby>どおりにいたします。（按照您的指示去办。）"}],"id":"N4-114"},{"title":"115. おる","blocks":[{"t":"label","label":"说明","text":"「いる」的自谦语。","furi":"「いる」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"5時までに会社におります。（我会一直在公司待到五点。）","furi":"5<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>までに<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>におります。（我会一直在公司待到五点。）"}],"id":"N4-115"},{"title":"116. 参る","blocks":[{"t":"label","label":"说明","text":"「行く」「来る」的自谦语。","furi":"「<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く」「<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"明日、先生のお宅に参ります。（明天去老师家拜访。）","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>、<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>のお<ruby>宅<rp>(</rp><rt>たく</rt><rp>)</rp></ruby>に<ruby>参<rp>(</rp><rt>まい</rt><rp>)</rp></ruby>ります。（明天去老师家拜访。）"}],"id":"N4-116"},{"title":"117. 申す","blocks":[{"t":"label","label":"说明","text":"「言う」的自谦语。","furi":"「<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>う」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"私は、中川と申します。（我叫中川。）","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>は、<ruby>中川<rp>(</rp><rt>なかがわ</rt><rp>)</rp></ruby>と<ruby>申<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>します。（我叫中川。）"}],"id":"N4-117"},{"title":"118. 申し上げる","blocks":[{"t":"label","label":"说明","text":"「言う」的自谦语，敬意程度比「申す」高。","furi":"「<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>う」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>，<ruby>敬意<rp>(</rp><rt>けいい</rt><rp>)</rp></ruby><ruby>程度<rp>(</rp><rt>ていど</rt><rp>)</rp></ruby><ruby>比<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>「<ruby>申<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>す」<ruby>高<rp>(</rp><rt>だか</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"心よりお詫び申し上げます。（诚心诚意向您致以歉意。）","furi":"<ruby>心<rp>(</rp><rt>こころ</rt><rp>)</rp></ruby>よりお<ruby>詫<rp>(</rp><rt>わ</rt><rp>)</rp></ruby>び<ruby>申<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>し<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>げます。（诚心诚意向您致以歉意。）"}],"id":"N4-118"},{"title":"119. 存じている","blocks":[{"t":"label","label":"说明","text":"「知っている」的自谦语。","furi":"「<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>っている」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"社長の電話番号は存じています。（我知道社长的电话号码。）","furi":"<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>の<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby><ruby>番号<rp>(</rp><rt>ばんごう</rt><rp>)</rp></ruby>は<ruby>存<rp>(</rp><rt>ぞん</rt><rp>)</rp></ruby>じています。（我知道社长的电话号码。）"}],"id":"N4-119"},{"title":"120. 存じ上げる","blocks":[{"t":"label","label":"说明","text":"「知っている」的自谦语。","furi":"「<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>っている」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"お名前はよく存じ上げております。（久仰大名。）","furi":"お<ruby>名前<rp>(</rp><rt>なまえ</rt><rp>)</rp></ruby>はよく<ruby>存<rp>(</rp><rt>ぞん</rt><rp>)</rp></ruby>じ<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>げております。（久仰大名。）"}],"id":"N4-120"},{"title":"121. お目にかかる","blocks":[{"t":"label","label":"说明","text":"「会う」的自谦语。","furi":"「<ruby>会<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>う」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"山口：中川先生。（中川老师。）","furi":""},{"t":"line","text":"中川：あ、山口さん。偶然ですね。（啊，是山口啊。真是太巧了。）","furi":"<ruby>中川<rp>(</rp><rt>なかがわ</rt><rp>)</rp></ruby>：あ、<ruby>山口<rp>(</rp><rt>やまぐち</rt><rp>)</rp></ruby>さん。<ruby>偶然<rp>(</rp><rt>ぐうぜん</rt><rp>)</rp></ruby>ですね。（啊，是山口啊。真是太巧了。）"},{"t":"line","text":"山口：はい。わたしもこのパーティーで先生にお目にかかれるとは思いませんでした。（是啊，我也没想到在这个派对上能碰到老师。）","furi":"<ruby>山口<rp>(</rp><rt>やまぐち</rt><rp>)</rp></ruby>：はい。わたしもこのパーティーで<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>にお<ruby>目<rp>(</rp><rt>め</rt><rp>)</rp></ruby>にかかれるとは<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>いませんでした。（是啊，我也没想到在这个派对上能碰到老师。）"}],"id":"N4-121"},{"title":"122. ご覧いただく","blocks":[{"t":"label","label":"说明","text":"「見てもらう」的自谦语。","furi":"「<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>てもらう」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"この絵をご覧いただき、ありがとうございます。（非常感谢您看了这幅画。）","furi":"この<ruby>絵<rp>(</rp><rt>え</rt><rp>)</rp></ruby>をご<ruby>覧<rp>(</rp><rt>らん</rt><rp>)</rp></ruby>いただき、ありがとうございます。（非常感谢您看了这幅画。）"}],"id":"N4-122"},{"title":"123. 拝見する","blocks":[{"t":"label","label":"说明","text":"「見る」的自谦语。","furi":"「<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>る」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"A：どうぞご覧ください。（请过目。）","furi":"A：どうぞご<ruby>覧<rp>(</rp><rt>らん</rt><rp>)</rp></ruby>ください。（请过目。）"},{"t":"line","text":"B：では、拝見します。（好的，那我就看了。）","furi":"B：では、<ruby>拝見<rp>(</rp><rt>はいけん</rt><rp>)</rp></ruby>します。（好的，那我就看了。）"}],"id":"N4-123"},{"title":"124. 拝借する","blocks":[{"t":"label","label":"说明","text":"「借りる」的自谦语。","furi":"「<ruby>借<rp>(</rp><rt>か</rt><rp>)</rp></ruby>りる」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"先生の辞書を拝借してもよろしいですか。（老师可以把词典借给我吗？）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>の<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>を<ruby>拝借<rp>(</rp><rt>はいしゃく</rt><rp>)</rp></ruby>してもよろしいですか。（老师可以把词典借给我吗？）"}],"id":"N4-124"},{"title":"125. うかがう","blocks":[{"t":"label","label":"说明","text":"「行く」「来る」「聞く」「尋ねる」「訪問する」的自谦语。","furi":"「<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く」「<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る」「<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>く」「<ruby>尋<rp>(</rp><rt>たず</rt><rp>)</rp></ruby>ねる」「<ruby>訪問<rp>(</rp><rt>ほうもん</rt><rp>)</rp></ruby>する」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"学生：先生、ご相談したいことがあるのですが、授業の後、先生の研究室にうかがってもよろしいでしょうか。（老师，我有事要和您商量，下课后去您的研究室可以吗？）","furi":"<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>：<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>、ご<ruby>相談<rp>(</rp><rt>そうだん</rt><rp>)</rp></ruby>したいことがあるのですが、<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby>の<ruby>後<rp>(</rp><rt>のち</rt><rp>)</rp></ruby>、<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>の<ruby>研究<rp>(</rp><rt>けんきゅう</rt><rp>)</rp></ruby><ruby>室<rp>(</rp><rt>しつ</rt><rp>)</rp></ruby>にうかがってもよろしいでしょうか。（老师，我有事要和您商量，下课后去您的研究室可以吗？）"},{"t":"line","text":"先生：はい。いいですよ。（好的，没问题。）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>：はい。いいですよ。（好的，没问题。）"}],"id":"N4-125"},{"title":"126. 承る（うけたまわる）","blocks":[{"t":"label","label":"说明","text":"「受ける」「聞く」的自谦语。","furi":"「<ruby>受<rp>(</rp><rt>う</rt><rp>)</rp></ruby>ける」「<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>く」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"先生のご意見を承りました。（听取了老师的意见。）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>のご<ruby>意見<rp>(</rp><rt>いけん</rt><rp>)</rp></ruby>を<ruby>承<rp>(</rp><rt>うけたまわ</rt><rp>)</rp></ruby>りました。（听取了老师的意见。）"}],"id":"N4-126"},{"title":"127. あがる","blocks":[{"t":"label","label":"说明","text":"「食べる」「飲む」的尊他语（注意不是自谦）。","furi":"「<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる」「<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>む」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>（注意不是自谦）。"},{"t":"label","label":"例句","text":"先生は毎日お魚をあがりますか。（老师每天都吃鱼吗？）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>は<ruby>毎日<rp>(</rp><rt>まいにち</rt><rp>)</rp></ruby>お<ruby>魚<rp>(</rp><rt>さかな</rt><rp>)</rp></ruby>をあがりますか。（老师每天都吃鱼吗？）"}],"id":"N4-127"},{"title":"128. お/ご～する","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + する / ご + III类动词词干 + する","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + する / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + する"},{"t":"label","label":"说明","text":"自谦表达。","furi":""},{"t":"label","label":"例句","text":"先生、わたしがその荷物をお持ちします。（老师，我来拿那件行李吧。）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>、わたしがその<ruby>荷物<rp>(</rp><rt>にもつ</rt><rp>)</rp></ruby>をお<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>ちします。（老师，我来拿那件行李吧。）"}],"id":"N4-128"},{"title":"129. お/ご～いたす","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + いたす / ご + III类动词词干 + いたす","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + いたす / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + いたす"},{"t":"label","label":"说明","text":"自谦程度比「お/ご～する」更高。","furi":"<ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>程度<rp>(</rp><rt>ていど</rt><rp>)</rp></ruby><ruby>比<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>「お/ご～する」<ruby>更<rp>(</rp><rt>さら</rt><rp>)</rp></ruby><ruby>高<rp>(</rp><rt>だか</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"その仕事についてはわたしからご説明いたします。（有关那份工作，由我来进行说明。）","furi":"その<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>についてはわたしからご<ruby>説明<rp>(</rp><rt>せつめい</rt><rp>)</rp></ruby>いたします。（有关那份工作，由我来进行说明。）"}],"id":"N4-129"},{"title":"130. ～ておる","blocks":[{"t":"label","label":"接续","text":"动词て形 + おる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + おる"},{"t":"label","label":"说明","text":"「～ている」的自谦语。","furi":"「～ている」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>自<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"ただいま、外出しております。（现在外出中。）","furi":"ただいま、<ruby>外出<rp>(</rp><rt>がいしゅつ</rt><rp>)</rp></ruby>しております。（现在外出中。）"}],"id":"N4-130"}]},{"id":"N4-u11","title":"第11单元 敬语3（礼貌语）","points":[{"title":"131. ございます","blocks":[{"t":"label","label":"说明","text":"「ある」的礼貌语。","furi":"「ある」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>礼<rp>(</rp><rt>れい</rt><rp>)</rp></ruby><ruby>貌<rp>(</rp><rt>貌</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"ネクタイ売り場は2階にございます。（领带的柜台在二楼。）","furi":"ネクタイ<ruby>売<rp>(</rp><rt>う</rt><rp>)</rp></ruby>り<ruby>場<rp>(</rp><rt>ば</rt><rp>)</rp></ruby>は2<ruby>階<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>にございます。（领带的柜台在二楼。）"}],"id":"N4-131"},{"title":"132. ～でございます","blocks":[{"t":"label","label":"说明","text":"「だ/です/である」的礼貌语。","furi":"「だ/です/である」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>礼<rp>(</rp><rt>れい</rt><rp>)</rp></ruby><ruby>貌<rp>(</rp><rt>貌</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"こちらのカメラは新製品でございます。（这个相机是新产品。）","furi":"こちらのカメラは<ruby>新<rp>(</rp><rt>しん</rt><rp>)</rp></ruby><ruby>製品<rp>(</rp><rt>せいひん</rt><rp>)</rp></ruby>でございます。（这个相机是新产品。）"}],"id":"N4-132"}]}]},{"id":"N3","name":"N3 文法详解（整理版）","units":[{"id":"N3-u1","title":"第1单元 ～間、～間に等","points":[{"title":"1. ～間（あいだ）","blocks":[{"t":"label","label":"接续","text":"名词+の / 动词辞书形/ている形 + 間","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の / <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>間<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示在某一段时间里某种动作或状态一直持续，谓语用持续动词。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"山田先生の講演の間、皆熱心に話を聞いていた。（山田老师演讲的时候，大家都很认真地听着。）","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby><ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>の<ruby>講演<rp>(</rp><rt>こうえん</rt><rp>)</rp></ruby>の<ruby>間<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>、<ruby>皆<rp>(</rp><rt>みな</rt><rp>)</rp></ruby><ruby>熱心<rp>(</rp><rt>ねっしん</rt><rp>)</rp></ruby>に<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>を<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>いていた。（山田老师演讲的时候，大家都很认真地听着。）"},{"t":"line","text":"わたしは夏休みの間、ずっと実家にいました。（暑假期间，我一直待在老家。）","furi":"わたしは<ruby>夏休<rp>(</rp><rt>なつやす</rt><rp>)</rp></ruby>みの<ruby>間<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>、ずっと<ruby>実家<rp>(</rp><rt>じっか</rt><rp>)</rp></ruby>にいました。（暑假期间，我一直待在老家。）"}],"id":"N3-1"},{"title":"2. ～間に（あいだに）","blocks":[{"t":"label","label":"接续","text":"名词+の / 动词辞书形/ている形 + 間に","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の / <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>間<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>に"},{"t":"label","label":"说明","text":"表示在持续的某一点或一段时间里发生了某个动作，谓语用瞬间性动词。","furi":""},{"t":"label","label":"例句","text":"日本に留学している間に富士山に登りたい。（想在留学日本期间登一次富士山。）","furi":"<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>に<ruby>留学<rp>(</rp><rt>りゅうがく</rt><rp>)</rp></ruby>している<ruby>間<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>に<ruby>富士山<rp>(</rp><rt>ふじさん</rt><rp>)</rp></ruby>に<ruby>登<rp>(</rp><rt>のぼ</rt><rp>)</rp></ruby>りたい。（想在留学日本期间登一次富士山。）"}],"id":"N3-2"},{"title":"3. ～あがる（接尾词）","blocks":[{"t":"label","label":"接续","text":"动词ます形 + あがる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + あがる"},{"t":"label","label":"说明①","text":"表示动作完成，“……完成了、……好了”。","furi":""},{"t":"label","label":"例句①","text":"企画書ができあがったので、どうぞご覧ください。（最新的企划书完成了，请过目。）","furi":"<ruby>企画<rp>(</rp><rt>きかく</rt><rp>)</rp></ruby><ruby>書<rp>(</rp><rt>しょ</rt><rp>)</rp></ruby>ができあがったので、どうぞご<ruby>覧<rp>(</rp><rt>らん</rt><rp>)</rp></ruby>ください。（最新的企划书完成了，请过目。）"},{"t":"label","label":"说明②","text":"表示动作向上，“向上、……起来”。","furi":""},{"t":"label","label":"例句②","text":"意中の大学に合格したとの知らせに、彼女はすっかり舞い上がった。（得知考上了心仪的大学，她高兴得跳了起来。）","furi":"<ruby>意中<rp>(</rp><rt>いちゅう</rt><rp>)</rp></ruby>の<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>に<ruby>合格<rp>(</rp><rt>ごうかく</rt><rp>)</rp></ruby>したとの<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>らせに、<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>はすっかり<ruby>舞<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>い<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>がった。（得知考上了心仪的大学，她高兴得跳了起来。）"}],"id":"N3-3"},{"title":"4. ～いい/よい","blocks":[{"t":"label","label":"接续","text":"动词ます形 + いい/よい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + いい/よい"},{"t":"label","label":"说明","text":"表示容易做，“容易……、易于……”，只能用于积极评价。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"この町は住みよいです。（这座城市很宜居。）","furi":"この<ruby>町<rp>(</rp><rt>まち</rt><rp>)</rp></ruby>は<ruby>住<rp>(</rp><rt>す</rt><rp>)</rp></ruby>みよいです。（这座城市很宜居。）"},{"t":"line","text":"この本はわかりいいです。（这本书通俗易懂。）","furi":"この<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>はわかりいいです。（这本书通俗易懂。）"}],"id":"N3-4"},{"title":"5. ～一方（で）（いっぽう）","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词+の + 一方（で）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + <ruby>一方<rp>(</rp><rt>いっぽう</rt><rp>)</rp></ruby>（で）"},{"t":"label","label":"说明①","text":"同一主语的不同方面，“一方面……另一方面……”。","furi":""},{"t":"label","label":"例句①","text":"彼は自分は何もしていない一方で、他人のすることによく文句を言う。（他自己什么都不干，却经常对别人做的事发牢骚。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>もしていない<ruby>一方<rp>(</rp><rt>いっぽう</rt><rp>)</rp></ruby>で、<ruby>他人<rp>(</rp><rt>たにん</rt><rp>)</rp></ruby>のすることによく<ruby>文句<rp>(</rp><rt>もんく</rt><rp>)</rp></ruby>を<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>う。（他自己什么都不干，却经常对别人做的事发牢骚。）"},{"t":"label","label":"说明②","text":"不同主语的对比，“一方面……另一方面……”。","furi":""},{"t":"label","label":"例句②","text":"収入が減る一方で、教育費などの支出は増えていくのだから、節約するしかない。（一方面收入不断减少，另一方面教育费等开支不断增加，所以只好节约。）","furi":"<ruby>収入<rp>(</rp><rt>しゅうにゅう</rt><rp>)</rp></ruby>が<ruby>減<rp>(</rp><rt>へ</rt><rp>)</rp></ruby>る<ruby>一方<rp>(</rp><rt>いっぽう</rt><rp>)</rp></ruby>で、<ruby>教育<rp>(</rp><rt>きょういく</rt><rp>)</rp></ruby><ruby>費<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>などの<ruby>支出<rp>(</rp><rt>ししゅつ</rt><rp>)</rp></ruby>は<ruby>増<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>えていくのだから、<ruby>節約<rp>(</rp><rt>せつやく</rt><rp>)</rp></ruby>するしかない。（一方面收入不断减少，另一方面教育费等开支不断增加，所以只好节约。）"}],"id":"N3-5"},{"title":"6. ～一方だ","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + 一方だ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>一方<rp>(</rp><rt>いっぽう</rt><rp>)</rp></ruby>だ"},{"t":"label","label":"说明","text":"表示事态不断向某个方向发展，“越来越……、不断……”，可用于好或不好的事态。","furi":""},{"t":"label","label":"例句","text":"ここ数年、この町の人口は減る一方だ。（最近几年来，这个城市的人口在不断地减少。）","furi":"ここ<ruby>数<rp>(</rp><rt>すう</rt><rp>)</rp></ruby><ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>、この<ruby>町<rp>(</rp><rt>まち</rt><rp>)</rp></ruby>の<ruby>人口<rp>(</rp><rt>じんこう</rt><rp>)</rp></ruby>は<ruby>減<rp>(</rp><rt>へ</rt><rp>)</rp></ruby>る<ruby>一方<rp>(</rp><rt>いっぽう</rt><rp>)</rp></ruby>だ。（最近几年来，这个城市的人口在不断地减少。）"}],"id":"N3-6"},{"title":"7. ～上で（の）（うえ）","blocks":[{"t":"label","label":"接续","text":"名词+の / 动词た形 + 上で（の）","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の / <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>で（の）"},{"t":"label","label":"说明","text":"表示做完前项之后做后项，“在……之后”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"それぞれの説明をよく聞いた上で、旅行のコースを選びたいと思います。（我想仔细听各自说明之后，选择旅行的路线。）","furi":"それぞれの<ruby>説明<rp>(</rp><rt>せつめい</rt><rp>)</rp></ruby>をよく<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>いた<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>で、<ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>のコースを<ruby>選<rp>(</rp><rt>えら</rt><rp>)</rp></ruby>びたいと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>います。（我想仔细听各自说明之后，选择旅行的路线。）"},{"t":"line","text":"皆様のご意見を伺った上で、来週ご報告いたします。（听取各位意见之后，下周我将作报告。）","furi":"<ruby>皆様<rp>(</rp><rt>みなさま</rt><rp>)</rp></ruby>のご<ruby>意見<rp>(</rp><rt>いけん</rt><rp>)</rp></ruby>を<ruby>伺<rp>(</rp><rt>うかが</rt><rp>)</rp></ruby>った<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>で、<ruby>来週<rp>(</rp><rt>らいしゅう</rt><rp>)</rp></ruby>ご<ruby>報告<rp>(</rp><rt>ほうこく</rt><rp>)</rp></ruby>いたします。（听取各位意见之后，下周我将作报告。）"}],"id":"N3-7"},{"title":"8. ～上で（は）/上での（范围）","blocks":[{"t":"label","label":"接续","text":"名词+の / 动词辞书形 + 上で（は）/上での","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の / <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>で（は）/<ruby>上<rp>(</rp><rt>じょう</rt><rp>)</rp></ruby>での"},{"t":"label","label":"说明","text":"表示范围、方面，“在……方面、在……上”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"仕事の上では別に問題はない。（在工作上没有问题。）","furi":"<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>の<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>では<ruby>別<rp>(</rp><rt>べつ</rt><rp>)</rp></ruby>に<ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>はない。（在工作上没有问题。）"},{"t":"line","text":"外国語を勉強する上で、単語を覚えるのはとても大事なことだ。（在学习外语时，背单词是很重要的。）","furi":"<ruby>外国<rp>(</rp><rt>がいこく</rt><rp>)</rp></ruby><ruby>語<rp>(</rp><rt>ご</rt><rp>)</rp></ruby>を<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>する<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>で、<ruby>単語<rp>(</rp><rt>たんご</rt><rp>)</rp></ruby>を<ruby>覚<rp>(</rp><rt>おぼ</rt><rp>)</rp></ruby>えるのはとても<ruby>大事<rp>(</rp><rt>だいじ</rt><rp>)</rp></ruby>なことだ。（在学习外语时，背单词是很重要的。）"}],"id":"N3-8"},{"title":"9. ～上に","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+である + 上に","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+である + <ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>に"},{"t":"label","label":"说明","text":"表示添加，“不仅……而且……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"そのスポーツクラブは入会金が要らない上に、わが家から近い。（那家体育俱乐部不仅不需要入会费，而且离我家很近。）","furi":"そのスポーツクラブは<ruby>入会<rp>(</rp><rt>にゅうかい</rt><rp>)</rp></ruby><ruby>金<rp>(</rp><rt>きん</rt><rp>)</rp></ruby>が<ruby>要<rp>(</rp><rt>い</rt><rp>)</rp></ruby>らない<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>に、わが<ruby>家<rp>(</rp><rt>や</rt><rp>)</rp></ruby>から<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>い。（那家体育俱乐部不仅不需要入会费，而且离我家很近。）"},{"t":"line","text":"台風が近づいてきて、風が強い上、雨も激しく降っている。（台风逼近，不仅刮起了大风，雨势也很猛。）","furi":"<ruby>台風<rp>(</rp><rt>たいふう</rt><rp>)</rp></ruby>が<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>づいてきて、<ruby>風<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>が<ruby>強<rp>(</rp><rt>つよ</rt><rp>)</rp></ruby>い<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>、<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>も<ruby>激<rp>(</rp><rt>はげ</rt><rp>)</rp></ruby>しく<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>っている。（台风逼近，不仅刮起了大风，雨势也很猛。）"}],"id":"N3-9"},{"title":"10. ～うちは / ないうちに","blocks":[{"t":"label","label":"接续①","text":"动词辞书形/ている形 / い形容词普通形 / な形容词词干+な / 名词+の + うちは","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + うちは"},{"t":"label","label":"说明①","text":"表示在某个时期内一直做某事或处于某状态。","furi":""},{"t":"label","label":"例句①","text":"膝に痛みがあるうちは、運動しないでください。（膝盖还在痛的时候，请不要运动。）","furi":"<ruby>膝<rp>(</rp><rt>ひざ</rt><rp>)</rp></ruby>に<ruby>痛<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>みがあるうちは、<ruby>運動<rp>(</rp><rt>うんどう</rt><rp>)</rp></ruby>しないでください。（膝盖还在痛的时候，请不要运动。）"},{"t":"label","label":"接续②","text":"动词ない形 + ないうちに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ないうちに"},{"t":"label","label":"说明②","text":"表示趁着前项还没有发生，赶快做后项。","furi":""},{"t":"label","label":"例句②","text":"昨日のパーティーは、友だちと話していたら、ほとんど何も食べないうちに終わってしまった。（昨天的派对上，一直和朋友聊天，基本上什么都没吃派对就结束了。）","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>のパーティーは、<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちと<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>していたら、ほとんど<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>も<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べないうちに<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わってしまった。（昨天的派对上，一直和朋友聊天，基本上什么都没吃派对就结束了。）"}],"id":"N3-10"},{"title":"11. ～おかげで/おかげだ","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+の + おかげで/おかげだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + おかげで/おかげだ"},{"t":"label","label":"说明","text":"表示因某种原因产生了好的结果，“多亏……才……、托……的福”。","furi":""},{"t":"label","label":"例句","text":"母は「風邪を引かないのは、毎朝しているジョギングのおかげだ。」とよく言っている。（妈妈总是说：“没感冒，多亏了每天早上慢跑。”）","furi":"<ruby>母<rp>(</rp><rt>はは</rt><rp>)</rp></ruby>は「<ruby>風邪<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>を<ruby>引<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>かないのは、<ruby>毎朝<rp>(</rp><rt>まいあさ</rt><rp>)</rp></ruby>しているジョギングのおかげだ。」とよく<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>っている。（妈妈总是说：“没感冒，多亏了每天早上慢跑。”）"}],"id":"N3-11"},{"title":"12. ～おきに","blocks":[{"t":"label","label":"接续","text":"数量词 + おきに","furi":"<ruby>数量<rp>(</rp><rt>すうりょう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + おきに"},{"t":"label","label":"说明","text":"表示时间或距离的间隔，“每隔……”。","furi":""},{"t":"label","label":"例句","text":"この道には5メートルおきに木が植えてある。（这条路上每隔五米种一棵树。）","furi":"この<ruby>道<rp>(</rp><rt>みち</rt><rp>)</rp></ruby>には5メートルおきに<ruby>木<rp>(</rp><rt>き</rt><rp>)</rp></ruby>が<ruby>植<rp>(</rp><rt>う</rt><rp>)</rp></ruby>えてある。（这条路上每隔五米种一棵树。）"}],"id":"N3-12"},{"title":"13. ～恐れがある","blocks":[{"t":"label","label":"接续","text":"动词辞书形 / 名词+の + 恐れがある","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + <ruby>恐<rp>(</rp><rt>おそ</rt><rp>)</rp></ruby>れがある"},{"t":"label","label":"说明","text":"表示有可能产生不良后果，“恐怕要……、有可能……”。","furi":""},{"t":"label","label":"例句","text":"この欠陥を直さないと、重大な事故が起こる恐れがある。（如果不修好这个缺陷，就有可能要发生重大事故。）","furi":"この<ruby>欠陥<rp>(</rp><rt>けっかん</rt><rp>)</rp></ruby>を<ruby>直<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>さないと、<ruby>重大<rp>(</rp><rt>じゅうだい</rt><rp>)</rp></ruby>な<ruby>事故<rp>(</rp><rt>じこ</rt><rp>)</rp></ruby>が<ruby>起<rp>(</rp><rt>お</rt><rp>)</rp></ruby>こる<ruby>恐<rp>(</rp><rt>おそ</rt><rp>)</rp></ruby>れがある。（如果不修好这个缺陷，就有可能要发生重大事故。）"}],"id":"N3-13"},{"title":"14. ～がかり","blocks":[{"t":"label","label":"接续","text":"名词 + がかり","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + がかり"},{"t":"label","label":"说明","text":"表示花费多少人时或时间，“花……、用……”。","furi":""},{"t":"label","label":"例句","text":"3年がかりの調査の結果、工場廃水に含まれている金属物質が住民に危害を及ぼしたことがわかった。（花了三年时间调查后发现，工业废水中包含的金属物质对人们的健康造成了影响。）","furi":"3<ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>がかりの<ruby>調査<rp>(</rp><rt>ちょうさ</rt><rp>)</rp></ruby>の<ruby>結果<rp>(</rp><rt>けっか</rt><rp>)</rp></ruby>、<ruby>工場<rp>(</rp><rt>こうじょう</rt><rp>)</rp></ruby><ruby>廃水<rp>(</rp><rt>はいすい</rt><rp>)</rp></ruby>に<ruby>含<rp>(</rp><rt>ふく</rt><rp>)</rp></ruby>まれている<ruby>金属<rp>(</rp><rt>きんぞく</rt><rp>)</rp></ruby><ruby>物質<rp>(</rp><rt>ぶっしつ</rt><rp>)</rp></ruby>が<ruby>住民<rp>(</rp><rt>じゅうみん</rt><rp>)</rp></ruby>に<ruby>危害<rp>(</rp><rt>きがい</rt><rp>)</rp></ruby>を<ruby>及<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>ぼしたことがわかった。（花了三年时间调查后发现，工业废水中包含的金属物质对人们的健康造成了影响。）"}],"id":"N3-14"},{"title":"15. ～がたい","blocks":[{"t":"label","label":"接续","text":"动词ます形 + がたい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + がたい"},{"t":"label","label":"说明","text":"表示主观上难以做某事，“难以……、很难……”。","furi":""},{"t":"label","label":"例句","text":"これだけ景気が悪いのに、税金を上げようとするのは、わたしたち国民には理解しがたい。（如此不景气还要提高税金，对我们国民来说难以理解。）","furi":"これだけ<ruby>景気<rp>(</rp><rt>けいき</rt><rp>)</rp></ruby>が<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>いのに、<ruby>税金<rp>(</rp><rt>ぜいきん</rt><rp>)</rp></ruby>を<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>げようとするのは、わたしたち<ruby>国民<rp>(</rp><rt>こくみん</rt><rp>)</rp></ruby>には<ruby>理解<rp>(</rp><rt>りかい</rt><rp>)</rp></ruby>しがたい。（如此不景气还要提高税金，对我们国民来说难以理解。）"}],"id":"N3-15"},{"title":"16. ～か何か","blocks":[{"t":"label","label":"接续","text":"动词普通形/名词 + か何か","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + か<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>か"},{"t":"label","label":"说明","text":"表示不明确的指示，“……什么的、……之类的”。","furi":""},{"t":"label","label":"例句","text":"風で紙が飛んでしまうので、本か何か重いものを載せておこう。（纸会被风刮走，用书什么的重的东西压上面吧。）","furi":"<ruby>風<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>で<ruby>紙<rp>(</rp><rt>かみ</rt><rp>)</rp></ruby>が<ruby>飛<rp>(</rp><rt>と</rt><rp>)</rp></ruby>んでしまうので、<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>か<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>か<ruby>重<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>いものを<ruby>載<rp>(</rp><rt>の</rt><rp>)</rp></ruby>せておこう。（纸会被风刮走，用书什么的重的东西压上面吧。）"}],"id":"N3-16"},{"title":"17. ～から言うと/から言えば/から言って","blocks":[{"t":"label","label":"接续","text":"名词 + から言うと/から言えば/から言って","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + から<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>うと/から<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>えば/から<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>って"},{"t":"label","label":"说明","text":"表示从某立场得出的看法、结论，“从……来说、从……来讲”。","furi":""},{"t":"label","label":"例句","text":"社長：そうですね。経営者の立場から言うと、何でも率直に言ってほしいです。（嗯，从经营者的立场来说，我希望员工能坦率地说出自己的意见。）","furi":"<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>：そうですね。<ruby>経営<rp>(</rp><rt>けいえい</rt><rp>)</rp></ruby><ruby>者<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>の<ruby>立場<rp>(</rp><rt>たちば</rt><rp>)</rp></ruby>から<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>うと、<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>でも<ruby>率直<rp>(</rp><rt>そっちょく</rt><rp>)</rp></ruby>に<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってほしいです。（嗯，从经营者的立场来说，我希望员工能坦率地说出自己的意见。）"}],"id":"N3-17"},{"title":"18. ～からすると/からすれば","blocks":[{"t":"label","label":"接续","text":"名词 + からすると/からすれば","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + からすると/からすれば"},{"t":"label","label":"说明","text":"表示从某角度衡量，“从……来看”。","furi":""},{"t":"label","label":"例句","text":"プロからすると、わたしの技術はまだ未熟です。（从专家的角度来看，我的技术还不纯熟。）","furi":"プロからすると、わたしの<ruby>技術<rp>(</rp><rt>ぎじゅつ</rt><rp>)</rp></ruby>はまだ<ruby>未熟<rp>(</rp><rt>みじゅく</rt><rp>)</rp></ruby>です。（从专家的角度来看，我的技术还不纯熟。）"}],"id":"N3-18"},{"title":"19. ～から～にかけて","blocks":[{"t":"label","label":"接续","text":"名词 + から + 名词 + にかけて","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + から + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にかけて"},{"t":"label","label":"说明","text":"表示时间、空间的大致范围，“从……到……”。","furi":""},{"t":"label","label":"例句","text":"東北地方から北海道にかけて今夜は大雪になるでしょう。（从东北地区到北海道，今晚会下大雪。）","furi":"<ruby>東北<rp>(</rp><rt>とうほく</rt><rp>)</rp></ruby><ruby>地方<rp>(</rp><rt>ちほう</rt><rp>)</rp></ruby>から<ruby>北海道<rp>(</rp><rt>ほっかいどう</rt><rp>)</rp></ruby>にかけて<ruby>今夜<rp>(</rp><rt>こんや</rt><rp>)</rp></ruby>は<ruby>大雪<rp>(</rp><rt>おおゆき</rt><rp>)</rp></ruby>になるでしょう。（从东北地区到北海道，今晚会下大雪。）"}],"id":"N3-19"},{"title":"20. ～から見ると/から見れば/から見て","blocks":[{"t":"label","label":"接续","text":"名词 + から見ると/から見れば/から見て","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + から<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ると/から<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>れば/から<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>て"},{"t":"label","label":"说明","text":"表示立场，“从……来看”。","furi":""},{"t":"label","label":"例句","text":"平凡なわたしから見ると、彼女はあらゆる才能に恵まれているように思える。（在平凡的我看来，她似乎拥有所有的才能。）","furi":"<ruby>平凡<rp>(</rp><rt>へいぼん</rt><rp>)</rp></ruby>なわたしから<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ると、<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>はあらゆる<ruby>才能<rp>(</rp><rt>さいのう</rt><rp>)</rp></ruby>に<ruby>恵<rp>(</rp><rt>めぐ</rt><rp>)</rp></ruby>まれているように<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>える。（在平凡的我看来，她似乎拥有所有的才能。）"}],"id":"N3-20"},{"title":"21. ～きる/きれる/きれない","blocks":[{"t":"label","label":"接续","text":"动词ます形 + きる/きれる/きれない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + きる/きれる/きれない"},{"t":"label","label":"说明①","text":"表示做完某事，“……完”。","furi":""},{"t":"label","label":"例句①","text":"こんなに長い小説は、1日では読みきれない。（这么长的小说，一天之内是看不完的。）","furi":"こんなに<ruby>長<rp>(</rp><rt>なが</rt><rp>)</rp></ruby>い<ruby>小説<rp>(</rp><rt>しょうせつ</rt><rp>)</rp></ruby>は、1<ruby>日<rp>(</rp><rt>にち</rt><rp>)</rp></ruby>では<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>みきれない。（这么长的小说，一天之内是看不完的。）"},{"t":"label","label":"说明②","text":"表示状态达到极限，“十分……、非常……”。","furi":""},{"t":"label","label":"例句②","text":"今日は忙しくて、もう疲れきってしました。（今天非常忙，已经筋疲力尽了。）","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>は<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しくて、もう<ruby>疲<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>れきってしました。（今天非常忙，已经筋疲力尽了。）"}],"id":"N3-21"},{"title":"22. ～くせに","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+の + くせに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + くせに"},{"t":"label","label":"说明","text":"表示指责、不满，“明明……却……”。","furi":""},{"t":"label","label":"例句","text":"子どものくせに、生意気だね。（一个小孩儿竟这么狂妄。）","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どものくせに、<ruby>生意気<rp>(</rp><rt>なまいき</rt><rp>)</rp></ruby>だね。（一个小孩儿竟这么狂妄。）"}],"id":"N3-22"},{"title":"23. ～くらい/ぐらい（程度）","blocks":[{"t":"label","label":"说明①","text":"表示程度，“……得……、简直……”。","furi":""},{"t":"label","label":"例句①","text":"怖くて怖くて、大声で叫びたいくらいだった。（当时害怕得想大声叫出来。）","furi":"<ruby>怖<rp>(</rp><rt>こわ</rt><rp>)</rp></ruby>くて<ruby>怖<rp>(</rp><rt>こわ</rt><rp>)</rp></ruby>くて、<ruby>大声<rp>(</rp><rt>おおごえ</rt><rp>)</rp></ruby>で<ruby>叫<rp>(</rp><rt>さけ</rt><rp>)</rp></ruby>びたいくらいだった。（当时害怕得想大声叫出来。）"},{"t":"label","label":"说明②","text":"表示最低程度，“至少……、最起码……”。","furi":""},{"t":"label","label":"例句②","text":"これは新品だから、安くても5千円ぐらいはするだろう。（这是最新产品，即使便宜，至少也要五千日元吧。）","furi":"これは<ruby>新品<rp>(</rp><rt>しんぴん</rt><rp>)</rp></ruby>だから、<ruby>安<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>くても5<ruby>千<rp>(</rp><rt>せん</rt><rp>)</rp></ruby><ruby>円<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>ぐらいはするだろう。（这是最新产品，即使便宜，至少也要五千日元吧。）"},{"t":"label","label":"说明③","text":"用「～ぐらい～はない」表示最高程度，“没有比……更……”。","furi":"<ruby>用<rp>(</rp><rt>よう</rt><rp>)</rp></ruby>「～ぐらい～はない」<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>最高<rp>(</rp><rt>さいこう</rt><rp>)</rp></ruby><ruby>程度<rp>(</rp><rt>ていど</rt><rp>)</rp></ruby>，“<ruby>没<rp>(</rp><rt>ぼつ</rt><rp>)</rp></ruby><ruby>有<rp>(</rp><rt>ゆう</rt><rp>)</rp></ruby><ruby>比<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>……<ruby>更<rp>(</rp><rt>さら</rt><rp>)</rp></ruby>……”。"},{"t":"label","label":"例句③","text":"彼ぐらい努力する人はいない。（没有比他更努力的人了。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>ぐらい<ruby>努力<rp>(</rp><rt>どりょく</rt><rp>)</rp></ruby>する<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>はいない。（没有比他更努力的人了。）"}],"id":"N3-23"},{"title":"24. ～こそ","blocks":[{"t":"label","label":"接续","text":"名词 + こそ","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + こそ"},{"t":"label","label":"说明","text":"表示强调，“正是……、才是……”。","furi":""},{"t":"label","label":"例句","text":"これこそ本場の日本料理です。（这才是地道的日本料理。）","furi":"これこそ<ruby>本場<rp>(</rp><rt>ほんば</rt><rp>)</rp></ruby>の<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby><ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>です。（这才是地道的日本料理。）"}],"id":"N3-24"},{"title":"25. ～こと（命令、感叹）","blocks":[{"t":"label","label":"接续①","text":"动词辞书形/ない形 + こと","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + こと"},{"t":"label","label":"说明①","text":"表示命令或禁止，“要……、不要……”，用于书面语。","furi":""},{"t":"label","label":"例句①","text":"指定の場所以外に自転車を止めないこと。（不要在指定区域以外停放自行车。）","furi":"<ruby>指定<rp>(</rp><rt>してい</rt><rp>)</rp></ruby>の<ruby>場所<rp>(</rp><rt>ばしょ</rt><rp>)</rp></ruby><ruby>以外<rp>(</rp><rt>いがい</rt><rp>)</rp></ruby>に<ruby>自転車<rp>(</rp><rt>じてんしゃ</rt><rp>)</rp></ruby>を<ruby>止<rp>(</rp><rt>と</rt><rp>)</rp></ruby>めないこと。（不要在指定区域以外停放自行车。）"},{"t":"label","label":"接续②","text":"句子的普通形/礼貌形 + こと","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>礼<rp>(</rp><rt>れい</rt><rp>)</rp></ruby><ruby>貌<rp>(</rp><rt>貌</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + こと"},{"t":"label","label":"说明②","text":"表示感叹、惊讶，女性用语。","furi":""},{"t":"label","label":"例句②","text":"まあ、なんてきれいな夕焼けだこと。（啊，多美的晚霞啊！）","furi":"まあ、なんてきれいな<ruby>夕焼<rp>(</rp><rt>ゆうや</rt><rp>)</rp></ruby>けだこと。（啊，多美的晚霞啊！）"}],"id":"N3-25"},{"title":"26. ～ことか","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+の + ことか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + ことか"},{"t":"label","label":"说明","text":"表示感叹，“多么……啊”，常与「どんなに、どれほど」等呼应。","furi":"<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>感<rp>(</rp><rt>かん</rt><rp>)</rp></ruby><ruby>叹<rp>(</rp><rt>叹</rt><rp>)</rp></ruby>，“<ruby>多<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>么<rp>(</rp><rt>么</rt><rp>)</rp></ruby>……<ruby>啊<rp>(</rp><rt>啊</rt><rp>)</rp></ruby>”，<ruby>常<rp>(</rp><rt>つね</rt><rp>)</rp></ruby><ruby>与<rp>(</rp><rt>あずか</rt><rp>)</rp></ruby>「どんなに、どれほど」<ruby>等<rp>(</rp><rt>とう</rt><rp>)</rp></ruby><ruby>呼<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>应<rp>(</rp><rt>应</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"自分で野菜を作ってみて、おいしい野菜を育てることがどんなに大変なことかわかりました。（自己试着种了蔬菜之后才明白，要种出好吃的蔬菜是多么困难的事情。）","furi":"<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>で<ruby>野菜<rp>(</rp><rt>やさい</rt><rp>)</rp></ruby>を<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>ってみて、おいしい<ruby>野菜<rp>(</rp><rt>やさい</rt><rp>)</rp></ruby>を<ruby>育<rp>(</rp><rt>そだ</rt><rp>)</rp></ruby>てることがどんなに<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>なことかわかりました。（自己试着种了蔬菜之后才明白，要种出好吃的蔬菜是多么困难的事情。）"}],"id":"N3-26"},{"title":"27. ～ことだ（忠告）","blocks":[{"t":"label","label":"接续","text":"动词辞书形/ない形 + ことだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ことだ"},{"t":"label","label":"说明","text":"表示忠告或建议，“应该……、不应该……”。","furi":""},{"t":"label","label":"例句","text":"上手になりたければ、毎日短い時間でもいいから練習を続けることだ。（如果想要变得擅长，就要坚持每天练习，哪怕只是很短的时间。）","furi":"<ruby>上手<rp>(</rp><rt>じょうず</rt><rp>)</rp></ruby>になりたければ、<ruby>毎日<rp>(</rp><rt>まいにち</rt><rp>)</rp></ruby><ruby>短<rp>(</rp><rt>みじか</rt><rp>)</rp></ruby>い<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>でもいいから<ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby>を<ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>けることだ。（如果想要变得擅长，就要坚持每天练习，哪怕只是很短的时间。）"}],"id":"N3-27"},{"title":"28. ～ことに","blocks":[{"t":"label","label":"接续","text":"动词た形 / い形容词普通形 / な形容词词干+な + ことに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な + ことに"},{"t":"label","label":"说明","text":"表示说话人对后项事物的评价，“令人……的是”。","furi":""},{"t":"label","label":"例句","text":"興味深いことに、昔のおもちゃが再び流行しているそうだ。（令人觉得有趣的是，据说以前的玩具再度流行起来了。）","furi":"<ruby>興味深<rp>(</rp><rt>きょうみぶか</rt><rp>)</rp></ruby>いことに、<ruby>昔<rp>(</rp><rt>むかし</rt><rp>)</rp></ruby>のおもちゃが<ruby>再<rp>(</rp><rt>ふたた</rt><rp>)</rp></ruby>び<ruby>流行<rp>(</rp><rt>りゅうこう</rt><rp>)</rp></ruby>しているそうだ。（令人觉得有趣的是，据说以前的玩具再度流行起来了。）"}],"id":"N3-28"},{"title":"29. ～ことにする","blocks":[{"t":"label","label":"接续","text":"动词辞书形/ない形 + ことにする","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ことにする"},{"t":"label","label":"说明","text":"表示说话人的主观决定，“决定……”。","furi":""},{"t":"label","label":"例句","text":"アルコールはもう飲まないことにする。（我决定不再喝酒了。）","furi":"アルコールはもう<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>まないことにする。（我决定不再喝酒了。）"},{"t":"label","label":"注意","text":"「～ことにしている」表示个人习惯，“坚持……”。","furi":"「～ことにしている」<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>个<rp>(</rp><rt>个</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>じん</rt><rp>)</rp></ruby><ruby>习<rp>(</rp><rt>习</rt><rp>)</rp></ruby><ruby>惯<rp>(</rp><rt>惯</rt><rp>)</rp></ruby>，“<ruby>坚<rp>(</rp><rt>坚</rt><rp>)</rp></ruby><ruby>持<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>……”。"}],"id":"N3-29"},{"title":"30. ～ことになっている/こととなっている","blocks":[{"t":"label","label":"接续","text":"动词辞书形/ない形 + ことになっている/こととなっている","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ことになっている/こととなっている"},{"t":"label","label":"说明","text":"表示计划、惯例、规章制度，“预定……、规定……”。","furi":""},{"t":"label","label":"例句","text":"今日は7時東京駅で友だちと会うことになっているので、6時半に会社を出ます。（今天约好七点在东京站见面，所以打算六点半下班。）","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>は7<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>東京<rp>(</rp><rt>とうきょう</rt><rp>)</rp></ruby><ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>で<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちと<ruby>会<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>うことになっているので、6<ruby>時半<rp>(</rp><rt>じはん</rt><rp>)</rp></ruby>に<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>ます。（今天约好七点在东京站见面，所以打算六点半下班。）"}],"id":"N3-30"},{"title":"31. ～ことになる","blocks":[{"t":"label","label":"接续①","text":"动词辞书形/ない形 + ことになる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ことになる"},{"t":"label","label":"说明①","text":"表示客观的决定，“决定……”。","furi":""},{"t":"label","label":"例句①","text":"来月から授業は8時から始まることになりました。（从下个月起，八点开始上课。）","furi":"<ruby>来月<rp>(</rp><rt>らいげつ</rt><rp>)</rp></ruby>から<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby>は8<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>から<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>まることになりました。（从下个月起，八点开始上课。）"},{"t":"label","label":"接续②","text":"动词普通形 + ということになる / 名词+ということになる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ということになる / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+ということになる"},{"t":"label","label":"说明②","text":"换一种说法指出事情的本质，“也就是说……”。","furi":""},{"t":"label","label":"例句②","text":"家賃は一か月5万円だから、1年で60万円も払うことになる。（房租一个月五万日元，也就是说一年要支付六十万日元。）","furi":"<ruby>家賃<rp>(</rp><rt>やちん</rt><rp>)</rp></ruby>は<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby>か<ruby>月<rp>(</rp><rt>げつ</rt><rp>)</rp></ruby>5<ruby>万<rp>(</rp><rt>まん</rt><rp>)</rp></ruby><ruby>円<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>だから、1<ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>で60<ruby>万<rp>(</rp><rt>まん</rt><rp>)</rp></ruby><ruby>円<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>も<ruby>払<rp>(</rp><rt>はら</rt><rp>)</rp></ruby>うことになる。（房租一个月五万日元，也就是说一年要支付六十万日元。）"}],"id":"N3-31"},{"title":"32. ～ことはない/こともない","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + ことはない/こともない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ことはない/こともない"},{"t":"label","label":"说明","text":"表示没必要做某事，“不必……、用不着……”。","furi":""},{"t":"label","label":"例句","text":"その器具は確かに便利そうだが、なくても困らないのだから、わざわざ買うことはない。（那个器械似乎的确很方便，但是即使没有也没事，因此没必要特意去买。）","furi":"その<ruby>器具<rp>(</rp><rt>きぐ</rt><rp>)</rp></ruby>は<ruby>確<rp>(</rp><rt>たし</rt><rp>)</rp></ruby>かに<ruby>便利<rp>(</rp><rt>べんり</rt><rp>)</rp></ruby>そうだが、なくても<ruby>困<rp>(</rp><rt>こま</rt><rp>)</rp></ruby>らないのだから、わざわざ<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>うことはない。（那个器械似乎的确很方便，但是即使没有也没事，因此没必要特意去买。）"}],"id":"N3-32"},{"title":"33. ～最中に","blocks":[{"t":"label","label":"接续","text":"名词+の / 动词ている形 + 最中に","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の / <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>最中<rp>(</rp><rt>さいちゅう</rt><rp>)</rp></ruby>に"},{"t":"label","label":"说明","text":"表示正在做某事时发生了意外的事，“正在……的时候”。","furi":""},{"t":"label","label":"例句","text":"電話している最中に、誰かが玄関に来た。（正在打电话的时候，有人进屋了。）","furi":"<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>している<ruby>最中<rp>(</rp><rt>さいちゅう</rt><rp>)</rp></ruby>に、<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>かが<ruby>玄関<rp>(</rp><rt>げんかん</rt><rp>)</rp></ruby>に<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>た。（正在打电话的时候，有人进屋了。）"}],"id":"N3-33"},{"title":"34. ～さえ","blocks":[{"t":"label","label":"接续","text":"名词/助词 + さえ（人物名词+で+さえ）","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>助<rp>(</rp><rt>じょ</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + さえ（<ruby>人物<rp>(</rp><rt>じんぶつ</rt><rp>)</rp></ruby><ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+で+さえ）"},{"t":"label","label":"说明","text":"举出极端例子类推其他，“甚至……、连……都……”。","furi":""},{"t":"label","label":"例句","text":"日本人でさえ、敬語を間違える場合がある。（就连日本人也会把敬语用错。）","furi":"<ruby>日本人<rp>(</rp><rt>にっぽんじん</rt><rp>)</rp></ruby>でさえ、<ruby>敬語<rp>(</rp><rt>けいご</rt><rp>)</rp></ruby>を<ruby>間違<rp>(</rp><rt>まちが</rt><rp>)</rp></ruby>える<ruby>場合<rp>(</rp><rt>ばあい</rt><rp>)</rp></ruby>がある。（就连日本人也会把敬语用错。）"}],"id":"N3-34"},{"title":"35. ～さえ～ば","blocks":[{"t":"label","label":"接续","text":"名词 + さえ + 各词类的「ば形」","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + さえ + <ruby>各<rp>(</rp><rt>かく</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>「ば<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>」"},{"t":"label","label":"说明","text":"表示只要具备该条件就能成立，“只要……就……”。","furi":""},{"t":"label","label":"例句","text":"最近、自分さえよければいいという考えの人が増えている。（最近，认为只要自己好就行的人多起来了。）","furi":"<ruby>最近<rp>(</rp><rt>さいきん</rt><rp>)</rp></ruby>、<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>さえよければいいという<ruby>考<rp>(</rp><rt>かんが</rt><rp>)</rp></ruby>えの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>増<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>えている。（最近，认为只要自己好就行的人多起来了。）"}],"id":"N3-35"},{"title":"36. ～じゃん/じゃない/じゃないの/じゃないか","blocks":[{"t":"label","label":"说明①","text":"表示反问，“不（是）……吗？”，口语化。","furi":""},{"t":"label","label":"例句①","text":"ねえ、ほら、できたじゃん。（你瞧，不是好了吗？）","furi":""},{"t":"label","label":"说明②","text":"表示新的发现或惊讶。","furi":""},{"t":"label","label":"例句②","text":"あれ、田中君じゃないか。（咦，这不是田中吗？）","furi":"あれ、<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby><ruby>君<rp>(</rp><rt>くん</rt><rp>)</rp></ruby>じゃないか。（咦，这不是田中吗？）"},{"t":"label","label":"说明③","text":"动词意志形+じゃないか，表示建议，“让我们一起……吧”。","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>意志<rp>(</rp><rt>いし</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+じゃないか，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>建<rp>(</rp><rt>けん</rt><rp>)</rp></ruby><ruby>议<rp>(</rp><rt>议</rt><rp>)</rp></ruby>，“<ruby>让<rp>(</rp><rt>让</rt><rp>)</rp></ruby><ruby>我<rp>(</rp><rt>わが</rt><rp>)</rp></ruby><ruby>们<rp>(</rp><rt>们</rt><rp>)</rp></ruby><ruby>一起<rp>(</rp><rt>かずき</rt><rp>)</rp></ruby>……<ruby>吧<rp>(</rp><rt>吧</rt><rp>)</rp></ruby>”。"},{"t":"label","label":"例句③","text":"皆で一緒に頑張ろうじゃないか。（我们大家一起努力吧。）","furi":"<ruby>皆<rp>(</rp><rt>みな</rt><rp>)</rp></ruby>で<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>頑張<rp>(</rp><rt>がんば</rt><rp>)</rp></ruby>ろうじゃないか。（我们大家一起努力吧。）"}],"id":"N3-36"},{"title":"37. ～上（じょう）","blocks":[{"t":"label","label":"接续","text":"名词 + 上","furi":""},{"t":"label","label":"说明","text":"表示范围、方面，“在……上、……方面”。","furi":""},{"t":"label","label":"例句","text":"それは法律上では許されない行為だ。（在法律上那是不被允许的行为。）","furi":"それは<ruby>法律<rp>(</rp><rt>ほうりつ</rt><rp>)</rp></ruby><ruby>上<rp>(</rp><rt>じょう</rt><rp>)</rp></ruby>では<ruby>許<rp>(</rp><rt>ゆる</rt><rp>)</rp></ruby>されない<ruby>行為<rp>(</rp><rt>こうい</rt><rp>)</rp></ruby>だ。（在法律上那是不被允许的行为。）"}],"id":"N3-37"},{"title":"38. ～ずとも","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ずとも（する→せずとも）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ずとも（する→せずとも）"},{"t":"label","label":"说明","text":"表示即使不做前项也可以，“即使不……也……”。","furi":""},{"t":"label","label":"例句","text":"嫌なら行かずともよい。（如果不愿意的话，不去也行。）","furi":"<ruby>嫌<rp>(</rp><rt>いや</rt><rp>)</rp></ruby>なら<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>かずともよい。（如果不愿意的话，不去也行。）"}],"id":"N3-38"},{"title":"39. ～（は）する/（も）する","blocks":[{"t":"label","label":"接续","text":"名词 +（は）する/（も）する","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> +（は）する/（も）する"},{"t":"label","label":"说明","text":"表示花费的时间或费用，带有感叹超出预想。","furi":""},{"t":"label","label":"例句","text":"そのホテルは一泊10万円もするそうだ。（听说那家宾馆一晚要花十万日元。）","furi":"そのホテルは<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>泊<rp>(</rp><rt>はく</rt><rp>)</rp></ruby>10<ruby>万<rp>(</rp><rt>まん</rt><rp>)</rp></ruby><ruby>円<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>もするそうだ。（听说那家宾馆一晚要花十万日元。）"}],"id":"N3-39"},{"title":"40. ～せいで/せいだ/せいか","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+の + せいで/せいだ/せいか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + せいで/せいだ/せいか"},{"t":"label","label":"说明","text":"表示因前项造成了不好的结果，“都怪……、因为……”，带有责怪语气。","furi":""},{"t":"label","label":"例句","text":"今年の冬は気温が高すぎるせいか、まだ一度も雪が降っていない。（大概是今年冬天温度过高的缘故吧，还没下过雪。）","furi":"<ruby>今年<rp>(</rp><rt>ことし</rt><rp>)</rp></ruby>の<ruby>冬<rp>(</rp><rt>ふゆ</rt><rp>)</rp></ruby>は<ruby>気温<rp>(</rp><rt>きおん</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>すぎるせいか、まだ<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>度<rp>(</rp><rt>ど</rt><rp>)</rp></ruby>も<ruby>雪<rp>(</rp><rt>ゆき</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>っていない。（大概是今年冬天温度过高的缘故吧，还没下过雪。）"}],"id":"N3-40"},{"title":"41. ～そうにない/そうもない","blocks":[{"t":"label","label":"接续","text":"动词ます形 + そうにない/そうもない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + そうにない/そうもない"},{"t":"label","label":"说明","text":"样态助动词「そうだ」的否定形式，表示看起来不会发生。","furi":"<ruby>样<rp>(</rp><rt>样</rt><rp>)</rp></ruby><ruby>态<rp>(</rp><rt>态</rt><rp>)</rp></ruby><ruby>助<rp>(</rp><rt>じょ</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「そうだ」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>否定<rp>(</rp><rt>ひてい</rt><rp>)</rp></ruby><ruby>形式<rp>(</rp><rt>けいしき</rt><rp>)</rp></ruby>，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>看<rp>(</rp><rt>み</rt><rp>)</rp></ruby><ruby>起<rp>(</rp><rt>おこ</rt><rp>)</rp></ruby><ruby>来<rp>(</rp><rt>らい</rt><rp>)</rp></ruby><ruby>不<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby><ruby>会<rp>(</rp><rt>かい</rt><rp>)</rp></ruby><ruby>发<rp>(</rp><rt>发</rt><rp>)</rp></ruby><ruby>生<rp>(</rp><rt>せい</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"今のわたしの給料では、何年働いても自分の家は買えそうもない。（就我现在的收入而言，无论工作多少年也买不起自己的房子。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>のわたしの<ruby>給料<rp>(</rp><rt>きゅうりょう</rt><rp>)</rp></ruby>では、<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby><ruby>働<rp>(</rp><rt>はたら</rt><rp>)</rp></ruby>いても<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>の<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>は<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>えそうもない。（就我现在的收入而言，无论工作多少年也买不起自己的房子。）"}],"id":"N3-41"},{"title":"42. ～たきり～ない","blocks":[{"t":"label","label":"接续","text":"动词た形 + きり + 否定","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + きり + <ruby>否定<rp>(</rp><rt>ひてい</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示自从前项发生之后，再也没有发生后项。","furi":""},{"t":"label","label":"例句","text":"彼は出かけたきり、帰ってこない。（他出去之后就没有回来。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>かけたきり、<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>ってこない。（他出去之后就没有回来。）"}],"id":"N3-42"},{"title":"43. ～だけでなく","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词 + だけでなく","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + だけでなく"},{"t":"label","label":"说明","text":"表示累加，“不但……而且……”。","furi":""},{"t":"label","label":"例句","text":"新しい携帯電話は、写真が撮れるだけじゃなくて、テレビだって見られるんだよ。（新手机不仅能拍照，还可以看电视。）","furi":"<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しい<ruby>携帯<rp>(</rp><rt>けいたい</rt><rp>)</rp></ruby><ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>は、<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>が<ruby>撮<rp>(</rp><rt>と</rt><rp>)</rp></ruby>れるだけじゃなくて、テレビだって<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>られるんだよ。（新手机不仅能拍照，还可以看电视。）"}],"id":"N3-43"},{"title":"44. ～だけでは","blocks":[{"t":"label","label":"接续","text":"动词普通形/名词 + だけでは","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + だけでは"},{"t":"label","label":"说明","text":"表示光是前项的话难以出现期待的结果，“光是……的话”。","furi":""},{"t":"label","label":"例句","text":"スポーツはただ見るだけではつまらない。（体育运动光看是没有意思的。）","furi":"スポーツはただ<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>るだけではつまらない。（体育运动光看是没有意思的。）"}],"id":"N3-44"},{"title":"45. ～たことにする","blocks":[{"t":"label","label":"接续","text":"动词た形 + ことにする","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ことにする"},{"t":"label","label":"说明","text":"表示将某事按与事实相反的情况处理，“就当作……”。","furi":""},{"t":"label","label":"例句","text":"その話は聞かなかったことにします。（那件事情就当我没听过。）","furi":"その<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>は<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>かなかったことにします。（那件事情就当我没听过。）"}],"id":"N3-45"},{"title":"46. ～たって/だって（即使）","blocks":[{"t":"label","label":"接续①","text":"い形容词词干+く / 动词ます形 + たって / な形容词词干/名词 + だって","furi":"い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+く / <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + たって / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + だって"},{"t":"label","label":"说明①","text":"表示逆接条件，“即使……也……”。","furi":""},{"t":"label","label":"例句①","text":"今さら謝りたって許してもらえないかもしれない。（事已至此，即使道歉，也不会得到原谅了吧。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>さら<ruby>謝<rp>(</rp><rt>あやま</rt><rp>)</rp></ruby>りたって<ruby>許<rp>(</rp><rt>ゆる</rt><rp>)</rp></ruby>してもらえないかもしれない。（事已至此，即使道歉，也不会得到原谅了吧。）"},{"t":"label","label":"接续②","text":"疑问词 + だって","furi":"<ruby>疑<rp>(</rp><rt>うたぐ</rt><rp>)</rp></ruby><ruby>问<rp>(</rp><rt>问</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + だって"},{"t":"label","label":"说明②","text":"表示无论……都……。","furi":""},{"t":"label","label":"例句②","text":"あの二人が結婚したと聞けば、誰だってびっくりするよ。（要是听说那两个人结婚了的话，无论是谁都会吃惊的。）","furi":"あの<ruby>二<rp>(</rp><rt>に</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>が<ruby>結婚<rp>(</rp><rt>けっこん</rt><rp>)</rp></ruby>したと<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>けば、<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>だってびっくりするよ。（要是听说那两个人结婚了的话，无论是谁都会吃惊的。）"}],"id":"N3-46"},{"title":"47. たとえ/たとい～ても","blocks":[{"t":"label","label":"接续","text":"たとえ/たとい + 动词て形 + も / い形容词词干+くても / な形容词词干+でも / 名词+でも","furi":"たとえ/たとい + <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + も / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+くても / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+でも / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+でも"},{"t":"label","label":"说明","text":"“即使……也……”。","furi":""},{"t":"label","label":"例句","text":"たとえみんなに反対されても、わたしは絶対にこの計画を実行したい。（即使大家都反对，我也一定要实行这个计划。）","furi":"たとえみんなに<ruby>反対<rp>(</rp><rt>はんたい</rt><rp>)</rp></ruby>されても、わたしは<ruby>絶対<rp>(</rp><rt>ぜったい</rt><rp>)</rp></ruby>にこの<ruby>計画<rp>(</rp><rt>けいかく</rt><rp>)</rp></ruby>を<ruby>実行<rp>(</rp><rt>じっこう</rt><rp>)</rp></ruby>したい。（即使大家都反对，我也一定要实行这个计划。）"}],"id":"N3-47"},{"title":"48. ～たばかりだ","blocks":[{"t":"label","label":"接续","text":"动词た形 + ばかりだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ばかりだ"},{"t":"label","label":"说明","text":"表示刚刚做完某个动作，“刚刚……”。","furi":""},{"t":"label","label":"例句","text":"昨日、動物園に行ったら、先月生まれたばかりのライオンの赤ちゃんを見ることができました。（昨天去了动物园，看到了上个月刚刚出生的小狮子。）","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>、<ruby>動物<rp>(</rp><rt>どうぶつ</rt><rp>)</rp></ruby><ruby>園<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったら、<ruby>先月<rp>(</rp><rt>せんげつ</rt><rp>)</rp></ruby><ruby>生<rp>(</rp><rt>う</rt><rp>)</rp></ruby>まれたばかりのライオンの<ruby>赤<rp>(</rp><rt>あか</rt><rp>)</rp></ruby>ちゃんを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ることができました。（昨天去了动物园，看到了上个月刚刚出生的小狮子。）"}],"id":"N3-48"},{"title":"49. ～たび（に）","blocks":[{"t":"label","label":"接续","text":"名词+の / 动词辞书形 + たび（に）","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の / <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + たび（に）"},{"t":"label","label":"说明","text":"表示每当进行前项动作时，总是伴随后项事态，“每当……就……”。","furi":""},{"t":"label","label":"例句","text":"わたしは山田さんに会うたびに素敵な人だといつも思う。（我每次见到山田，都觉得他很出色。）","furi":"わたしは<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby>さんに<ruby>会<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>うたびに<ruby>素敵<rp>(</rp><rt>すてき</rt><rp>)</rp></ruby>な<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>だといつも<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>う。（我每次见到山田，都觉得他很出色。）"}],"id":"N3-49"},{"title":"50. ～たまえ","blocks":[{"t":"label","label":"接续","text":"动词ます形 + たまえ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + たまえ"},{"t":"label","label":"说明","text":"表示轻微的命令，男性用语。","furi":""},{"t":"label","label":"例句","text":"上田君、この方案を説明したまえ。（上田，你来说明下这个方案吧。）","furi":"<ruby>上田<rp>(</rp><rt>うえだ</rt><rp>)</rp></ruby><ruby>君<rp>(</rp><rt>くん</rt><rp>)</rp></ruby>、この<ruby>方案<rp>(</rp><rt>ほうあん</rt><rp>)</rp></ruby>を<ruby>説明<rp>(</rp><rt>せつめい</rt><rp>)</rp></ruby>したまえ。（上田，你来说明下这个方案吧。）"}],"id":"N3-50"},{"title":"51. ～たら/ったら（话题）","blocks":[{"t":"label","label":"接续","text":"名词 + たら/ったら","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + たら/ったら"},{"t":"label","label":"说明","text":"表示提起话题，带有亲昵或责难语气。","furi":""},{"t":"label","label":"例句","text":"李さんったら、また遅刻した。（说到小李，他又迟到了。）","furi":"<ruby>李<rp>(</rp><rt>り</rt><rp>)</rp></ruby>さんったら、また<ruby>遅刻<rp>(</rp><rt>ちこく</rt><rp>)</rp></ruby>した。（说到小李，他又迟到了。）"}],"id":"N3-51"},{"title":"52. ～だらけ","blocks":[{"t":"label","label":"接续","text":"名词 + だらけ","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + だらけ"},{"t":"label","label":"说明","text":"表示净是不愉快的东西，“满是……、净是……”。","furi":""},{"t":"label","label":"例句","text":"この部屋は何年も住んでいないので、埃だらけだ。（这间屋子好多年没有住人了，都是灰尘。）","furi":"この<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>も<ruby>住<rp>(</rp><rt>す</rt><rp>)</rp></ruby>んでいないので、<ruby>埃<rp>(</rp><rt>ほこり</rt><rp>)</rp></ruby>だらけだ。（这间屋子好多年没有住人了，都是灰尘。）"}],"id":"N3-52"},{"title":"53. ～たらどうですか","blocks":[{"t":"label","label":"接续","text":"动词た形 + らどうですか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + らどうですか"},{"t":"label","label":"说明","text":"表示提议、劝诱，“……那样做怎么样”。","furi":""},{"t":"label","label":"例句","text":"ネクタイでも買ってあげたらどう？上田さんからのプレゼント、お兄さん、喜ぶと思うよ。（买领带怎么样？上田送的礼物，哥哥收到肯定会高兴的。）","furi":"ネクタイでも<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ってあげたらどう？<ruby>上田<rp>(</rp><rt>うえだ</rt><rp>)</rp></ruby>さんからのプレゼント、お<ruby>兄<rp>(</rp><rt>にい</rt><rp>)</rp></ruby>さん、<ruby>喜<rp>(</rp><rt>よろこ</rt><rp>)</rp></ruby>ぶと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>うよ。（买领带怎么样？上田送的礼物，哥哥收到肯定会高兴的。）"}],"id":"N3-53"},{"title":"54. ～だろうか","blocks":[{"t":"label","label":"接续","text":"动词/形容词普通形、名词 + だろうか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>、<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + だろうか"},{"t":"label","label":"说明","text":"表示询问、推测、怀疑，“能……吗、会是……吗”。","furi":""},{"t":"label","label":"例句","text":"明日の実験は成功するだろうか。（明天的实验能成功吗？）","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>の<ruby>実験<rp>(</rp><rt>じっけん</rt><rp>)</rp></ruby>は<ruby>成功<rp>(</rp><rt>せいこう</rt><rp>)</rp></ruby>するだろうか。（明天的实验能成功吗？）"}],"id":"N3-54"},{"title":"55. ～っけ","blocks":[{"t":"label","label":"接续","text":"句子的普通形/礼貌形 + っけ","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>礼<rp>(</rp><rt>れい</rt><rp>)</rp></ruby><ruby>貌<rp>(</rp><rt>貌</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + っけ"},{"t":"label","label":"说明","text":"表示向对方确认或表示回忆，“（是不是）……来着”。","furi":""},{"t":"label","label":"例句","text":"レポートの締め切りはあさってだったっけ。（小报告的截止日期是不是后天来着？）","furi":"レポートの<ruby>締<rp>(</rp><rt>し</rt><rp>)</rp></ruby>め<ruby>切<rp>(</rp><rt>き</rt><rp>)</rp></ruby>りはあさってだったっけ。（小报告的截止日期是不是后天来着？）"}],"id":"N3-55"},{"title":"56. ～って","blocks":[{"t":"label","label":"说明①","text":"名词+って+名词，表示称谓，“叫……的……”。","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+って+<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>称<rp>(</rp><rt>しょう</rt><rp>)</rp></ruby><ruby>谓<rp>(</rp><rt>谓</rt><rp>)</rp></ruby>，“<ruby>叫<rp>(</rp><rt>叫</rt><rp>)</rp></ruby>……<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>……”。"},{"t":"label","label":"例句①","text":"さっき、高橋さんって人から電話がありました。（刚刚，有个叫高桥的人打来电话了。）","furi":"さっき、<ruby>高橋<rp>(</rp><rt>たかはし</rt><rp>)</rp></ruby>さんって<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>から<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>がありました。（刚刚，有个叫高桥的人打来电话了。）"},{"t":"label","label":"说明②","text":"名词/句子普通形+って，表示说明主题，“……的是……”。","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+って，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>说<rp>(</rp><rt>说</rt><rp>)</rp></ruby><ruby>明主<rp>(</rp><rt>めいしゅ</rt><rp>)</rp></ruby><ruby>题<rp>(</rp><rt>题</rt><rp>)</rp></ruby>，“……<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>是<rp>(</rp><rt>ぜ</rt><rp>)</rp></ruby>……”。"},{"t":"label","label":"例句②","text":"来年、関西地区に支店を出すって、本当ですか。（明年要在关西地区开分店，这是真的吗？）","furi":"<ruby>来年<rp>(</rp><rt>らいねん</rt><rp>)</rp></ruby>、<ruby>関西<rp>(</rp><rt>かんさい</rt><rp>)</rp></ruby><ruby>地区<rp>(</rp><rt>ちく</rt><rp>)</rp></ruby>に<ruby>支店<rp>(</rp><rt>してん</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>すって、<ruby>本当<rp>(</rp><rt>ほんとう</rt><rp>)</rp></ruby>ですか。（明年要在关西地区开分店，这是真的吗？）"},{"t":"label","label":"说明③","text":"句子普通形+って，表示传闻，“听说……”。","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+って，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>传<rp>(</rp><rt>传</rt><rp>)</rp></ruby><ruby>闻<rp>(</rp><rt>闻</rt><rp>)</rp></ruby>，“<ruby>听<rp>(</rp><rt>听</rt><rp>)</rp></ruby><ruby>说<rp>(</rp><rt>说</rt><rp>)</rp></ruby>……”。"},{"t":"label","label":"例句③","text":"明日は雨だって。（听说明天会下雨。）","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>は<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>だって。（听说明天会下雨。）"},{"t":"label","label":"说明④","text":"句子普通形+って+「言う/思う」等，表示引用。","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+って+「<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>う/<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>う」<ruby>等<rp>(</rp><rt>とう</rt><rp>)</rp></ruby>，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>引用<rp>(</rp><rt>いんよう</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句④","text":"今日はないって言ってましたよ。（他说今天休息。）","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>はないって<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってましたよ。（他说今天休息。）"}],"id":"N3-56"},{"title":"57. ～つもり（自以为）","blocks":[{"t":"label","label":"接续","text":"动词た形/ている形 + つもり","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + つもり"},{"t":"label","label":"说明","text":"表示主语自己的看法，“自以为……”。","furi":""},{"t":"label","label":"例句","text":"わたしは彼女にいろいろ親切にしたつもりなんですが、感謝されるどころか、恨まれている。（我自认为对她已经很好了，可别说感谢了，反倒遭她怨恨。）","furi":"わたしは<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>にいろいろ<ruby>親切<rp>(</rp><rt>しんせつ</rt><rp>)</rp></ruby>にしたつもりなんですが、<ruby>感謝<rp>(</rp><rt>かんしゃ</rt><rp>)</rp></ruby>されるどころか、<ruby>恨<rp>(</rp><rt>うら</rt><rp>)</rp></ruby>まれている。（我自认为对她已经很好了，可别说感谢了，反倒遭她怨恨。）"}],"id":"N3-57"},{"title":"58. ～で（原因、依据）","blocks":[{"t":"label","label":"接续","text":"动词普通形+こと / 名词 + で","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+こと / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + で"},{"t":"label","label":"说明","text":"表示原因或依据。","furi":""},{"t":"label","label":"例句","text":"将来のことで悩んでるらしいよ。（好像在为将来的事情烦恼着呢。）","furi":"<ruby>将来<rp>(</rp><rt>しょうらい</rt><rp>)</rp></ruby>のことで<ruby>悩<rp>(</rp><rt>なや</rt><rp>)</rp></ruby>んでるらしいよ。（好像在为将来的事情烦恼着呢。）"}],"id":"N3-58"},{"title":"59. ～て以来","blocks":[{"t":"label","label":"接续","text":"动词て形 + 以来","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>以来<rp>(</rp><rt>いらい</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示自从过去某事件之后直到现在，“自从……以来”。","furi":""},{"t":"label","label":"例句","text":"兄は会社に入って以来、一度も休んだことはありません。（哥哥自从进了公司之后，从未请过假。）","furi":"<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>は<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>に<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>って<ruby>以来<rp>(</rp><rt>いらい</rt><rp>)</rp></ruby>、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>度<rp>(</rp><rt>ど</rt><rp>)</rp></ruby>も<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>んだことはありません。（哥哥自从进了公司之后，从未请过假。）"}],"id":"N3-59"},{"title":"60. ～てごらん","blocks":[{"t":"label","label":"接续","text":"动词て形 + ごらん","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ごらん"},{"t":"label","label":"说明","text":"表示让对方尝试做某事，“请……试试”。","furi":""},{"t":"label","label":"例句","text":"これ、食べてごらん。おいしいよ。（吃吃看这个，很好吃哦。）","furi":"これ、<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べてごらん。おいしいよ。（吃吃看这个，很好吃哦。）"}],"id":"N3-60"},{"title":"61. ～てしかた（が）ない/てしょうがない","blocks":[{"t":"label","label":"接续","text":"动词て形 / い形容词词干+くて / な形容词词干+で + しかたがない/しょうがない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+くて / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+で + しかたがない/しょうがない"},{"t":"label","label":"说明","text":"表示感情强烈，“……得不得了、非常……”。","furi":""},{"t":"label","label":"例句","text":"残念でしかたがない。（太遗憾了。）","furi":"<ruby>残念<rp>(</rp><rt>ざんねん</rt><rp>)</rp></ruby>でしかたがない。（太遗憾了。）"}],"id":"N3-61"},{"title":"62. ～て済む/で済む","blocks":[{"t":"label","label":"接续","text":"动词て形 + 済む","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>済<rp>(</rp><rt>す</rt><rp>)</rp></ruby>む"},{"t":"label","label":"说明","text":"表示“……就解决了、……就好了”。","furi":""},{"t":"label","label":"例句","text":"薬で済む病気だから、入院する必要はない。（这病吃药就能治好，用不着住院。）","furi":"<ruby>薬<rp>(</rp><rt>くすり</rt><rp>)</rp></ruby>で<ruby>済<rp>(</rp><rt>す</rt><rp>)</rp></ruby>む<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>だから、<ruby>入院<rp>(</rp><rt>にゅういん</rt><rp>)</rp></ruby>する<ruby>必要<rp>(</rp><rt>ひつよう</rt><rp>)</rp></ruby>はない。（这病吃药就能治好，用不着住院。）"}],"id":"N3-62"},{"title":"63. ～て（は）たまらない","blocks":[{"t":"label","label":"接续","text":"动词て形 / い形容词词干+くて / な形容词词干+で + たまらない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+くて / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+で + たまらない"},{"t":"label","label":"说明","text":"表示强烈的感情、感觉、欲望，“……得不得了、非常……”。","furi":""},{"t":"label","label":"例句","text":"昨日の歌の練習では何度も間違えてみんなに笑われ、恥ずかしくてたまらなかった。（昨天在练习唱歌的时候，我好几次都唱错，因此被大家取笑，别提有多难为情了。）","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>の<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>の<ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby>では<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby><ruby>度<rp>(</rp><rt>ど</rt><rp>)</rp></ruby>も<ruby>間違<rp>(</rp><rt>まちが</rt><rp>)</rp></ruby>えてみんなに<ruby>笑<rp>(</rp><rt>わら</rt><rp>)</rp></ruby>われ、<ruby>恥<rp>(</rp><rt>は</rt><rp>)</rp></ruby>ずかしくてたまらなかった。（昨天在练习唱歌的时候，我好几次都唱错，因此被大家取笑，别提有多难为情了。）"}],"id":"N3-63"},{"title":"64. ～てならない","blocks":[{"t":"label","label":"接续","text":"动词て形 / い形容词词干+くて / な形容词词干+で + ならない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+くて / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+で + ならない"},{"t":"label","label":"说明","text":"表示情不自禁地产生某种感情，“……得不得了、不由得……”。","furi":""},{"t":"label","label":"例句","text":"世界中を旅行して回れるなんて、羡ましくてならない。（能够周游全世界，真是让我羡慕得不得了。）","furi":"<ruby>世界中<rp>(</rp><rt>せかいじゅう</rt><rp>)</rp></ruby>を<ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>して<ruby>回<rp>(</rp><rt>まわ</rt><rp>)</rp></ruby>れるなんて、<ruby>羡<rp>(</rp><rt>羡</rt><rp>)</rp></ruby>ましくてならない。（能够周游全世界，真是让我羡慕得不得了。）"}],"id":"N3-64"},{"title":"65. ～ては/では（条件）","blocks":[{"t":"label","label":"接续","text":"动词て形 + は","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + は"},{"t":"label","label":"说明①","text":"表示动作反复，“一……就……”。","furi":""},{"t":"label","label":"例句①","text":"息子は小学生の頃、よくお腹が痛いと言っては学校を休んでいた。（儿子上小学的时候，经常说肚子疼，然后请假不去学校。）","furi":"<ruby>息子<rp>(</rp><rt>むすこ</rt><rp>)</rp></ruby>は<ruby>小学生<rp>(</rp><rt>しょうがくせい</rt><rp>)</rp></ruby>の<ruby>頃<rp>(</rp><rt>ころ</rt><rp>)</rp></ruby>、よくお<ruby>腹<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>が<ruby>痛<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>いと<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>っては<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>を<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>んでいた。（儿子上小学的时候，经常说肚子疼，然后请假不去学校。）"},{"t":"label","label":"说明②","text":"表示假设条件，后项多是不好的结果。","furi":""},{"t":"label","label":"例句②","text":"そんな暗い部屋で本を読んでは目が悪くなるから、電気をつけなさい。（在那么暗的屋子里看书的话，对眼睛不好。把灯打开吧。）","furi":"そんな<ruby>暗<rp>(</rp><rt>くら</rt><rp>)</rp></ruby>い<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>で<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>を<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>んでは<ruby>目<rp>(</rp><rt>め</rt><rp>)</rp></ruby>が<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>くなるから、<ruby>電気<rp>(</rp><rt>でんき</rt><rp>)</rp></ruby>をつけなさい。（在那么暗的屋子里看书的话，对眼睛不好。把灯打开吧。）"}],"id":"N3-65"},{"title":"66. ～ではないか","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干/名词 + ではないか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + ではないか"},{"t":"label","label":"说明","text":"表示征求同意、反问或惊讶，“不是……吗？”","furi":""},{"t":"label","label":"例句","text":"ほら、できるじゃないか。（瞧，你不是行的吗？）","furi":""},{"t":"label","label":"例句②","text":"やあ、田中君ではないか。（哎呀，这不是田中吗？）","furi":"やあ、<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby><ruby>君<rp>(</rp><rt>くん</rt><rp>)</rp></ruby>ではないか。（哎呀，这不是田中吗？）"}],"id":"N3-66"},{"title":"67. ～（の）ではないか","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干/名词 + （の）ではないか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + （の）ではないか"},{"t":"label","label":"说明","text":"表示推测、判断、主张，“是不是……、恐怕……吧”。","furi":""},{"t":"label","label":"例句","text":"このままでは、病気はひどくなるのではないか。（这样下去，病恐怕会变重的吧。）","furi":"このままでは、<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>はひどくなるのではないか。（这样下去，病恐怕会变重的吧。）"}],"id":"N3-67"},{"title":"68. ～てはならない","blocks":[{"t":"label","label":"接续","text":"动词て形 + はならない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + はならない"},{"t":"label","label":"说明","text":"表示禁止，“不能……、不可以……”。","furi":""},{"t":"label","label":"例句","text":"既に決まったことを勝手に変えてはならない。（已经定好的事情不能随意更改。）","furi":"<ruby>既<rp>(</rp><rt>すで</rt><rp>)</rp></ruby>に<ruby>決<rp>(</rp><rt>き</rt><rp>)</rp></ruby>まったことを<ruby>勝手<rp>(</rp><rt>かって</rt><rp>)</rp></ruby>に<ruby>変<rp>(</rp><rt>か</rt><rp>)</rp></ruby>えてはならない。（已经定好的事情不能随意更改。）"}],"id":"N3-68"},{"title":"69. ～てほしい","blocks":[{"t":"label","label":"接续①","text":"人物+に + 动词て形/ないで + ほしい","furi":"<ruby>人物<rp>(</rp><rt>じんぶつ</rt><rp>)</rp></ruby>+に + <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/ないで + ほしい"},{"t":"label","label":"说明①","text":"表示希望对方做某事。","furi":""},{"t":"label","label":"例句①","text":"この歌は好きなんですが、少し難しいですからほかにしてほしいです。（这首歌我虽然喜欢，不过有些难，希望可以换成其他的。）","furi":"この<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>は<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きなんですが、<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>難<rp>(</rp><rt>むずか</rt><rp>)</rp></ruby>しいですからほかにしてほしいです。（这首歌我虽然喜欢，不过有些难，希望可以换成其他的。）"},{"t":"label","label":"接续②","text":"～が + 动词て形 + ほしい","furi":"～が + <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ほしい"},{"t":"label","label":"说明②","text":"表示希望出现某种事态。","furi":""},{"t":"label","label":"例句②","text":"イベントが無事に終わってほしい。（希望活动顺利结束。）","furi":"イベントが<ruby>無事<rp>(</rp><rt>ぶじ</rt><rp>)</rp></ruby>に<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わってほしい。（希望活动顺利结束。）"}],"id":"N3-69"},{"title":"70. ～てみせる","blocks":[{"t":"label","label":"接续","text":"动词て形 + みせる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + みせる"},{"t":"label","label":"说明","text":"表示做给某人看或表示决心，“做给……看、一定要……”。","furi":""},{"t":"label","label":"例句","text":"今度こそ、絶対試験に合格してみせる。（这次，我绝对会考上的。）","furi":"<ruby>今度<rp>(</rp><rt>こんど</rt><rp>)</rp></ruby>こそ、<ruby>絶対<rp>(</rp><rt>ぜったい</rt><rp>)</rp></ruby><ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>に<ruby>合格<rp>(</rp><rt>ごうかく</rt><rp>)</rp></ruby>してみせる。（这次，我绝对会考上的。）"}],"id":"N3-70"},{"title":"71. ～てもしかた（が）ない/てもしょうがない","blocks":[{"t":"label","label":"接续","text":"动词て形 + もしかたがない/もしょうがない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + もしかたがない/もしょうがない"},{"t":"label","label":"说明","text":"表示即使前项也没用，“即使……也没用、即使……也无可奈何”。","furi":""},{"t":"label","label":"例句","text":"今さら文句を言ってもしかたがない。（事到如今，发牢骚也无济于事。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>さら<ruby>文句<rp>(</rp><rt>もんく</rt><rp>)</rp></ruby>を<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってもしかたがない。（事到如今，发牢骚也无济于事。）"}],"id":"N3-71"},{"title":"72. ～ても始まらない","blocks":[{"t":"label","label":"接续","text":"动词て形 + も始まらない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + も<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>まらない"},{"t":"label","label":"说明","text":"表示即使做某事也没用，“即使……也没用”。","furi":""},{"t":"label","label":"例句","text":"焦っても始まらない。落ち着いて片付けよう。（着急也没用，静下心来收拾吧。）","furi":"<ruby>焦<rp>(</rp><rt>あせ</rt><rp>)</rp></ruby>っても<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>まらない。<ruby>落<rp>(</rp><rt>お</rt><rp>)</rp></ruby>ち<ruby>着<rp>(</rp><rt>つ</rt><rp>)</rp></ruby>いて<ruby>片付<rp>(</rp><rt>かたづ</rt><rp>)</rp></ruby>けよう。（着急也没用，静下心来收拾吧。）"}],"id":"N3-72"},{"title":"73. ～てやってくれないか","blocks":[{"t":"label","label":"接续","text":"动词て形 + やってくれないか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + やってくれないか"},{"t":"label","label":"说明","text":"请求对方为第三者做某事，“可否给……做……”。","furi":""},{"t":"label","label":"例句","text":"娘に英語を教えてやってくれないか。（可否请你教我女儿学英语？）","furi":"<ruby>娘<rp>(</rp><rt>むすめ</rt><rp>)</rp></ruby>に<ruby>英語<rp>(</rp><rt>えいご</rt><rp>)</rp></ruby>を<ruby>教<rp>(</rp><rt>おし</rt><rp>)</rp></ruby>えてやってくれないか。（可否请你教我女儿学英语？）"}],"id":"N3-73"},{"title":"74. ～てよかった/なくてよかった","blocks":[{"t":"label","label":"接续","text":"动词て形 + よかった / ない形 + なくてよかった","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + よかった / ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + なくてよかった"},{"t":"label","label":"说明","text":"表示事情结束后的评价，“太好了……、没有做……太好了”。","furi":""},{"t":"label","label":"例句","text":"午後になって雨が降り出した。傘を持ってきてよかった。（下午下起雨来了，幸亏我带了伞。）","furi":"<ruby>午後<rp>(</rp><rt>ごご</rt><rp>)</rp></ruby>になって<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>り<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>した。<ruby>傘<rp>(</rp><rt>かさ</rt><rp>)</rp></ruby>を<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>ってきてよかった。（下午下起雨来了，幸亏我带了伞。）"}],"id":"N3-74"},{"title":"75. ～ということだ（传闻/结论）","blocks":[{"t":"label","label":"接续①","text":"句子的普通形 + ということだ","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ということだ"},{"t":"label","label":"说明①","text":"表示传闻，“听说……、据说……”。","furi":""},{"t":"label","label":"例句①","text":"コーチの話では、彼が試合に出れば、優勝は間違いないということだ。（据教练说，如果他参加比赛的话，一定能拿冠军。）","furi":"コーチの<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>では、<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>が<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>に<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>れば、<ruby>優勝<rp>(</rp><rt>ゆうしょう</rt><rp>)</rp></ruby>は<ruby>間違<rp>(</rp><rt>まちが</rt><rp>)</rp></ruby>いないということだ。（据教练说，如果他参加比赛的话，一定能拿冠军。）"},{"t":"label","label":"接续②","text":"名词/动词普通形 + ということだ","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ということだ"},{"t":"label","label":"说明②","text":"表示换而言之或结论，“也就是说……”。","furi":""},{"t":"label","label":"例句②","text":"手紙が戻ってきたということは、彼女はもうこの住所にないということだ。（信退回来了，也就是说她已经不住那里了。）","furi":"<ruby>手紙<rp>(</rp><rt>てがみ</rt><rp>)</rp></ruby>が<ruby>戻<rp>(</rp><rt>もど</rt><rp>)</rp></ruby>ってきたということは、<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>はもうこの<ruby>住所<rp>(</rp><rt>じゅうしょ</rt><rp>)</rp></ruby>にないということだ。（信退回来了，也就是说她已经不住那里了。）"}],"id":"N3-75"},{"title":"76. ～というと/といえば/といったら","blocks":[{"t":"label","label":"说明①","text":"表示提起话题，“说起……”。","furi":""},{"t":"label","label":"例句①","text":"田中さんといえば、卒業以来、会っていないなあ。（说起田中，毕业之后就再也没有见过他。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんといえば、<ruby>卒業<rp>(</rp><rt>そつぎょう</rt><rp>)</rp></ruby><ruby>以来<rp>(</rp><rt>いらい</rt><rp>)</rp></ruby>、<ruby>会<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>っていないなあ。（说起田中，毕业之后就再也没有见过他。）"},{"t":"label","label":"说明②","text":"名词+というと，表示确认对方的话题。","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+というと，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>确<rp>(</rp><rt>确</rt><rp>)</rp></ruby><ruby>认<rp>(</rp><rt>认</rt><rp>)</rp></ruby><ruby>对<rp>(</rp><rt>对</rt><rp>)</rp></ruby><ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>话<rp>(</rp><rt>话</rt><rp>)</rp></ruby><ruby>题<rp>(</rp><rt>题</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句②","text":"小林さんというと、アメリカに行ったあの人ですか。（你说的小林，就是去了美国的那个人吧。）","furi":"<ruby>小林<rp>(</rp><rt>こばやし</rt><rp>)</rp></ruby>さんというと、アメリカに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったあの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>ですか。（你说的小林，就是去了美国的那个人吧。）"},{"t":"label","label":"说明③","text":"名词+といったら，表示提起话题并带有感叹。","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+といったら，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>提起<rp>(</rp><rt>ていき</rt><rp>)</rp></ruby><ruby>话<rp>(</rp><rt>话</rt><rp>)</rp></ruby><ruby>题<rp>(</rp><rt>题</rt><rp>)</rp></ruby><ruby>并<rp>(</rp><rt>并</rt><rp>)</rp></ruby><ruby>带<rp>(</rp><rt>带</rt><rp>)</rp></ruby><ruby>有<rp>(</rp><rt>ゆう</rt><rp>)</rp></ruby><ruby>感<rp>(</rp><rt>かん</rt><rp>)</rp></ruby><ruby>叹<rp>(</rp><rt>叹</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句③","text":"桜の美しさといったら、とても言葉では表現できないほどです。（说起樱花的美丽，是无法用言语形容的。）","furi":"<ruby>桜<rp>(</rp><rt>さくら</rt><rp>)</rp></ruby>の<ruby>美<rp>(</rp><rt>うつく</rt><rp>)</rp></ruby>しさといったら、とても<ruby>言葉<rp>(</rp><rt>ことば</rt><rp>)</rp></ruby>では<ruby>表現<rp>(</rp><rt>ひょうげん</rt><rp>)</rp></ruby>できないほどです。（说起樱花的美丽，是无法用言语形容的。）"}],"id":"N3-76"},{"title":"77. ～というのは/とは","blocks":[{"t":"label","label":"说明①","text":"名词+というのは/とは，表示定义，“所谓的……”。","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+というのは/とは，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>定<rp>(</rp><rt>てい</rt><rp>)</rp></ruby><ruby>义<rp>(</rp><rt>义</rt><rp>)</rp></ruby>，“<ruby>所<rp>(</rp><rt>ところ</rt><rp>)</rp></ruby><ruby>谓<rp>(</rp><rt>谓</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>……”。"},{"t":"label","label":"例句①","text":"「下水」というのは、台所などで使った汚れた水のことである。（所谓的污水就是指厨房等排出的脏水。）","furi":"「<ruby>下水<rp>(</rp><rt>げすい</rt><rp>)</rp></ruby>」というのは、<ruby>台所<rp>(</rp><rt>だいどころ</rt><rp>)</rp></ruby>などで<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>った<ruby>汚<rp>(</rp><rt>よご</rt><rp>)</rp></ruby>れた<ruby>水<rp>(</rp><rt>みず</rt><rp>)</rp></ruby>のことである。（所谓的污水就是指厨房等排出的脏水。）"},{"t":"label","label":"说明②","text":"というのは～からだ/のだ，表示原因，“……是因为……”。","furi":"というのは～からだ/のだ，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>原因<rp>(</rp><rt>げんいん</rt><rp>)</rp></ruby>，“……<ruby>是<rp>(</rp><rt>ぜ</rt><rp>)</rp></ruby><ruby>因<rp>(</rp><rt>いん</rt><rp>)</rp></ruby><ruby>为<rp>(</rp><rt>为</rt><rp>)</rp></ruby>……”。"},{"t":"label","label":"例句②","text":"残念ですが、明日のパーティーは参加できません。というのは、急に出張することになったんです。（很遗憾，我不能参加明天的宴会了，因为公司突然派我去出差。）","furi":"<ruby>残念<rp>(</rp><rt>ざんねん</rt><rp>)</rp></ruby>ですが、<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>のパーティーは<ruby>参加<rp>(</rp><rt>さんか</rt><rp>)</rp></ruby>できません。というのは、<ruby>急<rp>(</rp><rt>きゅう</rt><rp>)</rp></ruby>に<ruby>出張<rp>(</rp><rt>しゅっちょう</rt><rp>)</rp></ruby>することになったんです。（很遗憾，我不能参加明天的宴会了，因为公司突然派我去出差。）"}],"id":"N3-77"},{"title":"78. ～というほどではない/というほどでもない","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + というほどではない/でもない","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + というほどではない/でもない"},{"t":"label","label":"说明","text":"表示没有达到那个程度，“并没有达到……程度”。","furi":""},{"t":"label","label":"例句","text":"ちょっと辛いが、食べられないというほどでもない。（虽然有些辣，不过没有到不能吃的地步。）","furi":"ちょっと<ruby>辛<rp>(</rp><rt>つら</rt><rp>)</rp></ruby>いが、<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べられないというほどでもない。（虽然有些辣，不过没有到不能吃的地步。）"}],"id":"N3-78"},{"title":"79. ～というものは","blocks":[{"t":"label","label":"接续","text":"名词 + というものは","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + というものは"},{"t":"label","label":"说明","text":"表示一般性叙述，“……这种东西”。","furi":""},{"t":"label","label":"例句","text":"戦争というものは、残酷なものです。（战争是非常残酷的。）","furi":"<ruby>戦争<rp>(</rp><rt>せんそう</rt><rp>)</rp></ruby>というものは、<ruby>残酷<rp>(</rp><rt>ざんこく</rt><rp>)</rp></ruby>なものです。（战争是非常残酷的。）"}],"id":"N3-79"},{"title":"80. ～（や）～といった","blocks":[{"t":"label","label":"接续","text":"（名词+や+）名词 + といった","furi":"（<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+や+）<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + といった"},{"t":"label","label":"说明","text":"表示举例，“……这样的……”。","furi":""},{"t":"label","label":"例句","text":"この会社はタオルや洗剤といった様々な日用品を扱っている。（这家公司经营毛巾、洗涤剂等各种各样的日用品。）","furi":"この<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>はタオルや<ruby>洗剤<rp>(</rp><rt>せんざい</rt><rp>)</rp></ruby>といった<ruby>様々<rp>(</rp><rt>さまざま</rt><rp>)</rp></ruby>な<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby><ruby>用品<rp>(</rp><rt>ようひん</rt><rp>)</rp></ruby>を<ruby>扱<rp>(</rp><rt>あつか</rt><rp>)</rp></ruby>っている。（这家公司经营毛巾、洗涤剂等各种各样的日用品。）"}],"id":"N3-80"},{"title":"81. ～といっても","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + といっても","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + といっても"},{"t":"label","label":"说明","text":"表示转折，“虽说……但是……”。","furi":""},{"t":"label","label":"例句","text":"A：4月から外国語の学校に通ってる。（我从四月份开始在外语学校上学。）","furi":"A：4<ruby>月<rp>(</rp><rt>つき</rt><rp>)</rp></ruby>から<ruby>外国<rp>(</rp><rt>がいこく</rt><rp>)</rp></ruby><ruby>語<rp>(</rp><rt>ご</rt><rp>)</rp></ruby>の<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>に<ruby>通<rp>(</rp><rt>かよ</rt><rp>)</rp></ruby>ってる。（我从四月份开始在外语学校上学。）"},{"t":"line","text":"B：へえ、頑張ってるね。（啊，你真用功啊。）","furi":"B：へえ、<ruby>頑張<rp>(</rp><rt>がんば</rt><rp>)</rp></ruby>ってるね。（啊，你真用功啊。）"},{"t":"line","text":"A：といっても、週に1回だけだけど。（虽说如此，也只不过是一周上一次课而已。）","furi":"A：といっても、<ruby>週<rp>(</rp><rt>しゅう</rt><rp>)</rp></ruby>に1<ruby>回<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>だけだけど。（虽说如此，也只不过是一周上一次课而已。）"}],"id":"N3-81"},{"title":"82. ～とおり（に）/とおりの/どおり（に）/どおりの","blocks":[{"t":"label","label":"接续","text":"动词辞书形/た形 + とおり（に）/とおりの / 名词+の+とおり / 名词+どおり","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + とおり（に）/とおりの / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の+とおり / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+どおり"},{"t":"label","label":"说明","text":"表示按照前项所述那样做，“如……那样、按照……”。","furi":""},{"t":"label","label":"例句","text":"説明書どおりに組み立ててみたのですが、動かないんです。（我按照说明书去组装的，但是机器不能启动。）","furi":"<ruby>説明<rp>(</rp><rt>せつめい</rt><rp>)</rp></ruby><ruby>書<rp>(</rp><rt>しょ</rt><rp>)</rp></ruby>どおりに<ruby>組<rp>(</rp><rt>く</rt><rp>)</rp></ruby>み<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>ててみたのですが、<ruby>動<rp>(</rp><rt>うご</rt><rp>)</rp></ruby>かないんです。（我按照说明书去组装的，但是机器不能启动。）"}],"id":"N3-82"},{"title":"83. ～とされている","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + とされている","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + とされている"},{"t":"label","label":"说明","text":"表示人们认为、被视为，“人们认为……、被视为……”。","furi":""},{"t":"label","label":"例句","text":"今の時代では定期的な知識の更新が必要とされている。（在如今这个时代，人们认为定期进行知识的更新是有必要的。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>の<ruby>時代<rp>(</rp><rt>じだい</rt><rp>)</rp></ruby>では<ruby>定期<rp>(</rp><rt>ていき</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>な<ruby>知識<rp>(</rp><rt>ちしき</rt><rp>)</rp></ruby>の<ruby>更新<rp>(</rp><rt>こうしん</rt><rp>)</rp></ruby>が<ruby>必要<rp>(</rp><rt>ひつよう</rt><rp>)</rp></ruby>とされている。（在如今这个时代，人们认为定期进行知识的更新是有必要的。）"}],"id":"N3-83"},{"title":"84. ～として/としての/としても","blocks":[{"t":"label","label":"接续①","text":"名词 + として/としての/としても","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + として/としての/としても"},{"t":"label","label":"说明①","text":"表示身份、资格、立场，“作为……”。","furi":""},{"t":"label","label":"例句①","text":"来週、社長が日本へ出張するので、わたしも通訳として一緒に行きます。（下周社长去日本出差，我也作为翻译同行。）","furi":"<ruby>来週<rp>(</rp><rt>らいしゅう</rt><rp>)</rp></ruby>、<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>が<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>へ<ruby>出張<rp>(</rp><rt>しゅっちょう</rt><rp>)</rp></ruby>するので、わたしも<ruby>通訳<rp>(</rp><rt>つうやく</rt><rp>)</rp></ruby>として<ruby>一緒<rp>(</rp><rt>いっしょ</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きます。（下周社长去日本出差，我也作为翻译同行。）"},{"t":"label","label":"接续②","text":"句子的普通形 + としても","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + としても"},{"t":"label","label":"说明②","text":"表示假定或确定的逆接条件，“即使……也……”。","furi":""},{"t":"label","label":"例句②","text":"たとえ不合格だとしても、君の今までの努力は無駄ではないよ。（即使不合格，你之前的努力也不是白费的。）","furi":"たとえ<ruby>不<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby><ruby>合格<rp>(</rp><rt>ごうかく</rt><rp>)</rp></ruby>だとしても、<ruby>君<rp>(</rp><rt>きみ</rt><rp>)</rp></ruby>の<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>までの<ruby>努力<rp>(</rp><rt>どりょく</rt><rp>)</rp></ruby>は<ruby>無駄<rp>(</rp><rt>むだ</rt><rp>)</rp></ruby>ではないよ。（即使不合格，你之前的努力也不是白费的。）"}],"id":"N3-84"},{"title":"85. ～と（は）反対に","blocks":[{"t":"label","label":"接续","text":"名词 + と（は）反対に","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + と（は）<ruby>反対<rp>(</rp><rt>はんたい</rt><rp>)</rp></ruby>に"},{"t":"label","label":"说明","text":"“与……相反”。","furi":""},{"t":"label","label":"例句","text":"投資家の予想とは反対に、株価は下がっている。（与投资家们的预料相反，股票价格正在下跌。）","furi":"<ruby>投資<rp>(</rp><rt>とうし</rt><rp>)</rp></ruby><ruby>家<rp>(</rp><rt>か</rt><rp>)</rp></ruby>の<ruby>予想<rp>(</rp><rt>よそう</rt><rp>)</rp></ruby>とは<ruby>反対<rp>(</rp><rt>はんたい</rt><rp>)</rp></ruby>に、<ruby>株価<rp>(</rp><rt>かぶか</rt><rp>)</rp></ruby>は<ruby>下<rp>(</rp><rt>さ</rt><rp>)</rp></ruby>がっている。（与投资家们的预料相反，股票价格正在下跌。）"}],"id":"N3-85"},{"title":"86. ～ないかな","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ないかな","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ないかな"},{"t":"label","label":"说明","text":"表示希望、愿望，“多希望……啊”。","furi":""},{"t":"label","label":"例句","text":"社長のスピーチ、早く終わらないかな、いつも長くて困るよ。（社长的演讲能不能早点结束啊。总是说个不停，真让人头疼。）","furi":"<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>のスピーチ、<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>く<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わらないかな、いつも<ruby>長<rp>(</rp><rt>なが</rt><rp>)</rp></ruby>くて<ruby>困<rp>(</rp><rt>こま</rt><rp>)</rp></ruby>るよ。（社长的演讲能不能早点结束啊。总是说个不停，真让人头疼。）"}],"id":"N3-86"},{"title":"87. ～直す","blocks":[{"t":"label","label":"接续","text":"动词ます形 + 直す","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>直<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>す"},{"t":"label","label":"说明","text":"表示重新做，“重新……”。","furi":""},{"t":"label","label":"例句","text":"字が汚いので、書き直しました。（因为字迹潦草，所以重写。）","furi":"<ruby>字<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>が<ruby>汚<rp>(</rp><rt>きたな</rt><rp>)</rp></ruby>いので、<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>き<ruby>直<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>しました。（因为字迹潦草，所以重写。）"}],"id":"N3-87"},{"title":"88. なにしろ～から","blocks":[{"t":"label","label":"接续","text":"なにしろ + 句子的普通形/礼貌形 + から","furi":"なにしろ + <ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>礼<rp>(</rp><rt>れい</rt><rp>)</rp></ruby><ruby>貌<rp>(</rp><rt>貌</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + から"},{"t":"label","label":"说明","text":"“因为……”，用于陈述理由。","furi":""},{"t":"label","label":"例句","text":"なにしろここは田舎だから、買い物には不便だ。（因为这里是农村，买东西不方便。）","furi":"なにしろここは<ruby>田舎<rp>(</rp><rt>いなか</rt><rp>)</rp></ruby>だから、<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>い<ruby>物<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>には<ruby>不便<rp>(</rp><rt>ふべん</rt><rp>)</rp></ruby>だ。（因为这里是农村，买东西不方便。）"}],"id":"N3-88"},{"title":"89. ～なんか/なんて","blocks":[{"t":"label","label":"说明①","text":"表示列举，“……之类的”。","furi":""},{"t":"label","label":"例句①","text":"これなんか似合うと思うよ。（我觉得这个挺适合你的。）","furi":"これなんか<ruby>似合<rp>(</rp><rt>にあ</rt><rp>)</rp></ruby>うと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>うよ。（我觉得这个挺适合你的。）"},{"t":"label","label":"说明②","text":"用于自己时谦逊，用于他人时轻蔑。","furi":""},{"t":"label","label":"例句②","text":"いいえ、わたしなんかまだまだです。（不，我的日语还不行。）","furi":""},{"t":"label","label":"说明③","text":"表示惊讶，“竟然……”。","furi":""},{"t":"label","label":"例句③","text":"ここで先生に会うなんて、思ってもみなかった。（真没想到竟然在这里遇见老师。）","furi":"ここで<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>に<ruby>会<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>うなんて、<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>ってもみなかった。（真没想到竟然在这里遇见老师。）"},{"t":"label","label":"说明④","text":"名词+なんて+名词，表示例示。","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+なんて+<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>例示<rp>(</rp><rt>れいじ</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句④","text":"田中なんてやつは知らない。（我不认识田中这个人。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>なんてやつは<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>らない。（我不认识田中这个人。）"}],"id":"N3-89"},{"title":"90. ～において/における","blocks":[{"t":"label","label":"接续","text":"名词 + において/における","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + において/における"},{"t":"label","label":"说明","text":"表示场合、时间、范围，“在……”。","furi":""},{"t":"label","label":"例句","text":"ロンドンにおける国際会議が終わりました。（在伦敦举行的国际会议结束了。）","furi":"ロンドンにおける<ruby>国際<rp>(</rp><rt>こくさい</rt><rp>)</rp></ruby><ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby>が<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わりました。（在伦敦举行的国际会议结束了。）"}],"id":"N3-90"},{"title":"91. ～にかわって/にかわり","blocks":[{"t":"label","label":"接续","text":"名词 + にかわって/にかわり","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にかわって/にかわり"},{"t":"label","label":"说明","text":"表示代替，“代替……”。","furi":""},{"t":"label","label":"例句","text":"入院した先生にかわって、今は新しい先生が授業をしている。（老师住院了，所以现在由新老师代课。）","furi":"<ruby>入院<rp>(</rp><rt>にゅういん</rt><rp>)</rp></ruby>した<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>にかわって、<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>は<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しい<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>が<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby>をしている。（老师住院了，所以现在由新老师代课。）"}],"id":"N3-91"},{"title":"92. ～に関して/に関しても/に関する","blocks":[{"t":"label","label":"接续","text":"名词 + に関して/に関しても/に関する","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>関<rp>(</rp><rt>かん</rt><rp>)</rp></ruby>して/に<ruby>関<rp>(</rp><rt>かん</rt><rp>)</rp></ruby>しても/に<ruby>関<rp>(</rp><rt>かん</rt><rp>)</rp></ruby>する"},{"t":"label","label":"说明","text":"“关于……、有关……”。","furi":""},{"t":"label","label":"例句","text":"環境に関する諸問題を検討します。（讨论有关环境方面的问题。）","furi":"<ruby>環境<rp>(</rp><rt>かんきょう</rt><rp>)</rp></ruby>に<ruby>関<rp>(</rp><rt>かん</rt><rp>)</rp></ruby>する<ruby>諸<rp>(</rp><rt>しょ</rt><rp>)</rp></ruby><ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>を<ruby>検討<rp>(</rp><rt>けんとう</rt><rp>)</rp></ruby>します。（讨论有关环境方面的问题。）"}],"id":"N3-92"},{"title":"93. ～に比べて/と比べて","blocks":[{"t":"label","label":"接续","text":"名词 + に比べて/と比べて","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>比<rp>(</rp><rt>くら</rt><rp>)</rp></ruby>べて/と<ruby>比<rp>(</rp><rt>くら</rt><rp>)</rp></ruby>べて"},{"t":"label","label":"说明","text":"“和……相比”。","furi":""},{"t":"label","label":"例句","text":"今回発売されたパソコンは、今までのものに比べてかなり軽くなったので、持ち運びが楽だ。（这次发售的电脑，比之前所有机型都轻得多，便于携带。）","furi":"<ruby>今回<rp>(</rp><rt>こんかい</rt><rp>)</rp></ruby><ruby>発売<rp>(</rp><rt>はつばい</rt><rp>)</rp></ruby>されたパソコンは、<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>までのものに<ruby>比<rp>(</rp><rt>くら</rt><rp>)</rp></ruby>べてかなり<ruby>軽<rp>(</rp><rt>かる</rt><rp>)</rp></ruby>くなったので、<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>ち<ruby>運<rp>(</rp><rt>はこ</rt><rp>)</rp></ruby>びが<ruby>楽<rp>(</rp><rt>らく</rt><rp>)</rp></ruby>だ。（这次发售的电脑，比之前所有机型都轻得多，便于携带。）"}],"id":"N3-93"},{"title":"94. ～にしろ～にしろ/～にせよ～にせよ/～にしても～にしても","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 + にしろ/にせよ/にしても + 同","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + にしろ/にせよ/にしても + <ruby>同<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"无论前项是哪种情况，“无论是……还是……都……”。","furi":""},{"t":"label","label":"例句","text":"出席するにしろ、欠席するにしろ、招待状の返事は早く出したほうがいい。（无论是参加还是缺席，最好尽快回信。）","furi":"<ruby>出席<rp>(</rp><rt>しゅっせき</rt><rp>)</rp></ruby>するにしろ、<ruby>欠席<rp>(</rp><rt>けっせき</rt><rp>)</rp></ruby>するにしろ、<ruby>招待<rp>(</rp><rt>しょうたい</rt><rp>)</rp></ruby><ruby>状<rp>(</rp><rt>じょう</rt><rp>)</rp></ruby>の<ruby>返事<rp>(</rp><rt>へんじ</rt><rp>)</rp></ruby>は<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>く<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>したほうがいい。（无论是参加还是缺席，最好尽快回信。）"}],"id":"N3-94"},{"title":"95. ～に対して/に対する","blocks":[{"t":"label","label":"说明①","text":"表示动作对象，“对……”。","furi":""},{"t":"label","label":"例句①","text":"先日の会議では彼の説明に対して質問が集中した。（在上次的会议上，提问集中在他所做的说明上。）","furi":"<ruby>先日<rp>(</rp><rt>せんじつ</rt><rp>)</rp></ruby>の<ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby>では<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>説明<rp>(</rp><rt>せつめい</rt><rp>)</rp></ruby>に<ruby>対<rp>(</rp><rt>たい</rt><rp>)</rp></ruby>して<ruby>質問<rp>(</rp><rt>しつもん</rt><rp>)</rp></ruby>が<ruby>集中<rp>(</rp><rt>しゅうちゅう</rt><rp>)</rp></ruby>した。（在上次的会议上，提问集中在他所做的说明上。）"},{"t":"label","label":"说明②","text":"表示数量比例。","furi":""},{"t":"label","label":"例句②","text":"醤油3に対して酢1の割合で混ぜる。（把酱油和醋以三比一的比例混合。）","furi":"<ruby>醤油<rp>(</rp><rt>しょうゆ</rt><rp>)</rp></ruby>3に<ruby>対<rp>(</rp><rt>たい</rt><rp>)</rp></ruby>して<ruby>酢<rp>(</rp><rt>す</rt><rp>)</rp></ruby>1の<ruby>割合<rp>(</rp><rt>わりあい</rt><rp>)</rp></ruby>で<ruby>混<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ぜる。（把酱油和醋以三比一的比例混合。）"},{"t":"label","label":"说明③","text":"表示对比，“与……相反、而……”。","furi":""},{"t":"label","label":"例句③","text":"地方では人口が減っているのに対して、都市部では人口が急激に増えている。（地方的人口在减少，与之相对，城市的人口在急剧增加。）","furi":"<ruby>地方<rp>(</rp><rt>ちほう</rt><rp>)</rp></ruby>では<ruby>人口<rp>(</rp><rt>じんこう</rt><rp>)</rp></ruby>が<ruby>減<rp>(</rp><rt>へ</rt><rp>)</rp></ruby>っているのに<ruby>対<rp>(</rp><rt>たい</rt><rp>)</rp></ruby>して、<ruby>都市<rp>(</rp><rt>とし</rt><rp>)</rp></ruby><ruby>部<rp>(</rp><rt>ぶ</rt><rp>)</rp></ruby>では<ruby>人口<rp>(</rp><rt>じんこう</rt><rp>)</rp></ruby>が<ruby>急激<rp>(</rp><rt>きゅうげき</rt><rp>)</rp></ruby>に<ruby>増<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>えている。（地方的人口在减少，与之相对，城市的人口在急剧增加。）"}],"id":"N3-95"},{"title":"96. ～について/についての","blocks":[{"t":"label","label":"接续","text":"名词 + について/についての","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + について/についての"},{"t":"label","label":"说明","text":"“关于……”。","furi":""},{"t":"label","label":"例句","text":"『プレゼント』という映画を見て、この映画ほど人生について考えさせられる映画はないと思った。（看了叫做《礼物》的电影，我觉得没有什么电影比这部更能引起我对人生的思考。）","furi":"『プレゼント』という<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>て、この<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>ほど<ruby>人生<rp>(</rp><rt>じんせい</rt><rp>)</rp></ruby>について<ruby>考<rp>(</rp><rt>かんが</rt><rp>)</rp></ruby>えさせられる<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>はないと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>った。（看了叫做《礼物》的电影，我觉得没有什么电影比这部更能引起我对人生的思考。）"}],"id":"N3-96"},{"title":"97. ～につれて/につれ","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词 + につれて/につれ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + につれて/につれ"},{"t":"label","label":"说明","text":"“随着……”。","furi":""},{"t":"label","label":"例句","text":"辺りが暗くなるにつれて、だんだん眠くなってきた。（随着夜幕降临，渐渐有了睡意。）","furi":"<ruby>辺<rp>(</rp><rt>あた</rt><rp>)</rp></ruby>りが<ruby>暗<rp>(</rp><rt>くら</rt><rp>)</rp></ruby>くなるにつれて、だんだん<ruby>眠<rp>(</rp><rt>ねむ</rt><rp>)</rp></ruby>くなってきた。（随着夜幕降临，渐渐有了睡意。）"}],"id":"N3-97"},{"title":"98. ～にて","blocks":[{"t":"label","label":"接续","text":"名词 + にて","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にて"},{"t":"label","label":"说明①","text":"表示场所，“在……”，书面语。","furi":""},{"t":"label","label":"例句①","text":"新人教育は本社にて行います。（新员工培训在总部进行。）","furi":"<ruby>新人<rp>(</rp><rt>しんじん</rt><rp>)</rp></ruby><ruby>教育<rp>(</rp><rt>きょういく</rt><rp>)</rp></ruby>は<ruby>本社<rp>(</rp><rt>ほんしゃ</rt><rp>)</rp></ruby>にて<ruby>行<rp>(</rp><rt>おこな</rt><rp>)</rp></ruby>います。（新员工培训在总部进行。）"},{"t":"label","label":"说明②","text":"表示工具、手段，“用……、以……”，书面语。","furi":""},{"t":"label","label":"例句②","text":"面接の結果は書面にてお知らせいたします。（用书面形式通知面试的结果。）","furi":"<ruby>面接<rp>(</rp><rt>めんせつ</rt><rp>)</rp></ruby>の<ruby>結果<rp>(</rp><rt>けっか</rt><rp>)</rp></ruby>は<ruby>書面<rp>(</rp><rt>しょめん</rt><rp>)</rp></ruby>にてお<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>らせいたします。（用书面形式通知面试的结果。）"},{"t":"label","label":"说明③","text":"表示结束时间，“于……”。","furi":""},{"t":"label","label":"例句③","text":"本日は夜8時にて閉館します。（今晚八点闭馆。）","furi":"<ruby>本日<rp>(</rp><rt>ほんじつ</rt><rp>)</rp></ruby>は<ruby>夜<rp>(</rp><rt>よる</rt><rp>)</rp></ruby>8<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>にて<ruby>閉館<rp>(</rp><rt>へいかん</rt><rp>)</rp></ruby>します。（今晚八点闭馆。）"}],"id":"N3-98"},{"title":"99. ～にとって","blocks":[{"t":"label","label":"接续","text":"名词 + にとって","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にとって"},{"t":"label","label":"说明","text":"“对……来说”。","furi":""},{"t":"label","label":"例句","text":"わたしにとって、今一番大切なものは、飼っている犬です。（对于我来说，现在最重要的东西就是我养的狗。）","furi":"わたしにとって、<ruby>今<rp>(</rp><rt>こん</rt><rp>)</rp></ruby><ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby><ruby>大切<rp>(</rp><rt>たいせつ</rt><rp>)</rp></ruby>なものは、<ruby>飼<rp>(</rp><rt>か</rt><rp>)</rp></ruby>っている<ruby>犬<rp>(</rp><rt>いぬ</rt><rp>)</rp></ruby>です。（对于我来说，现在最重要的东西就是我养的狗。）"}],"id":"N3-99"},{"title":"100. ～には（目的）","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + には","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + には"},{"t":"label","label":"说明","text":"表示目的，后项为达到该目的所需做的事情，“要……（就得……）”。","furi":""},{"t":"label","label":"例句","text":"日本へ行くには、ビザを取らなければならない。（要去日本，必须要获得签证。）","furi":"<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>へ<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くには、ビザを<ruby>取<rp>(</rp><rt>と</rt><rp>)</rp></ruby>らなければならない。（要去日本，必须要获得签证。）"}],"id":"N3-100"},{"title":"101. ～によって/により/による","blocks":[{"t":"label","label":"说明①","text":"表示因前项不同而导致不同结果，“因……（而）、根据……（而）”。","furi":""},{"t":"label","label":"例句①","text":"あの美術館は曜日によって閉まる時間が違うから窓口で確認したほうがいいよ。（那家美术馆因日期不同闭馆时间也有所不同，最好在窗口确认一下。）","furi":"あの<ruby>美術館<rp>(</rp><rt>びじゅつかん</rt><rp>)</rp></ruby>は<ruby>曜日<rp>(</rp><rt>ようび</rt><rp>)</rp></ruby>によって<ruby>閉<rp>(</rp><rt>し</rt><rp>)</rp></ruby>まる<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>が<ruby>違<rp>(</rp><rt>ちが</rt><rp>)</rp></ruby>うから<ruby>窓口<rp>(</rp><rt>まどぐち</rt><rp>)</rp></ruby>で<ruby>確認<rp>(</rp><rt>かくにん</rt><rp>)</rp></ruby>したほうがいいよ。（那家美术馆因日期不同闭馆时间也有所不同，最好在窗口确认一下。）"},{"t":"label","label":"说明②","text":"表示依据，“根据……、由……”。","furi":""},{"t":"label","label":"例句②","text":"社会の安定は法律によって守られている。（社会安定由法律守护。）","furi":"<ruby>社会<rp>(</rp><rt>しゃかい</rt><rp>)</rp></ruby>の<ruby>安定<rp>(</rp><rt>あんてい</rt><rp>)</rp></ruby>は<ruby>法律<rp>(</rp><rt>ほうりつ</rt><rp>)</rp></ruby>によって<ruby>守<rp>(</rp><rt>まも</rt><rp>)</rp></ruby>られている。（社会安定由法律守护。）"},{"t":"label","label":"说明③","text":"表示手段，“通过……、凭借……”。","furi":""},{"t":"label","label":"例句③","text":"関係者の皆様のご協力によって、無事この会を終了することができました。（通过大家的齐心协力，大会圆满地落幕了。）","furi":"<ruby>関係<rp>(</rp><rt>かんけい</rt><rp>)</rp></ruby><ruby>者<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>の<ruby>皆様<rp>(</rp><rt>みなさま</rt><rp>)</rp></ruby>のご<ruby>協力<rp>(</rp><rt>きょうりょく</rt><rp>)</rp></ruby>によって、<ruby>無事<rp>(</rp><rt>ぶじ</rt><rp>)</rp></ruby>この<ruby>会<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>を<ruby>終了<rp>(</rp><rt>しゅうりょう</rt><rp>)</rp></ruby>することができました。（通过大家的齐心协力，大会圆满地落幕了。）"},{"t":"label","label":"说明④","text":"表示客观原因，“因为……、由于……”。","furi":""},{"t":"label","label":"例句④","text":"大雨によって、運動会は中止になった。（由于大雨，运动会取消了。）","furi":"<ruby>大雨<rp>(</rp><rt>おおあめ</rt><rp>)</rp></ruby>によって、<ruby>運動会<rp>(</rp><rt>うんどうかい</rt><rp>)</rp></ruby>は<ruby>中止<rp>(</rp><rt>ちゅうし</rt><rp>)</rp></ruby>になった。（由于大雨，运动会取消了。）"},{"t":"label","label":"说明⑤","text":"表示被动句的动作主体，“被……、由……”。","furi":""},{"t":"label","label":"例句⑤","text":"この美術館には、19世紀の画家たちによって描かれた絵がたくさんあります。（这个美术馆中，有很多幅由十九世纪的画家们所作的画。）","furi":"この<ruby>美術館<rp>(</rp><rt>びじゅつかん</rt><rp>)</rp></ruby>には、19<ruby>世紀<rp>(</rp><rt>せいき</rt><rp>)</rp></ruby>の<ruby>画家<rp>(</rp><rt>がか</rt><rp>)</rp></ruby>たちによって<ruby>描<rp>(</rp><rt>えが</rt><rp>)</rp></ruby>かれた<ruby>絵<rp>(</rp><rt>え</rt><rp>)</rp></ruby>がたくさんあります。（这个美术馆中，有很多幅由十九世纪的画家们所作的画。）"}],"id":"N3-101"},{"title":"102. ～ぬ/ん","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ぬ/ん（する→せぬ/せん）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ぬ/ん（する→せぬ/せん）"},{"t":"label","label":"说明","text":"表示否定，相当于「ない」，ぬ为书面语，ん为口语。","furi":"<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>否定<rp>(</rp><rt>ひてい</rt><rp>)</rp></ruby>，<ruby>相当<rp>(</rp><rt>そうとう</rt><rp>)</rp></ruby><ruby>于<rp>(</rp><rt>于</rt><rp>)</rp></ruby>「ない」，ぬ<ruby>为<rp>(</rp><rt>为</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>面<rp>(</rp><rt>めん</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>，ん<ruby>为<rp>(</rp><rt>为</rt><rp>)</rp></ruby><ruby>口<rp>(</rp><rt>ぐち</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"そのことについては、僕はさっぱりわからん。（关于那件事情，我什么都不知道。）","furi":"そのことについては、<ruby>僕<rp>(</rp><rt>ぼく</rt><rp>)</rp></ruby>はさっぱりわからん。（关于那件事情，我什么都不知道。）"}],"id":"N3-102"},{"title":"103. ～ねばならない/ねばならぬ","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ねばならない/ねばならぬ（する→せねばならない）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ねばならない/ねばならぬ（する→せねばならない）"},{"t":"label","label":"说明","text":"表示必须，“必须……”，书面语。","furi":""},{"t":"label","label":"例句","text":"金曜日までに書類を用意せねばならない。（在星期五之前必须要准备好资料。）","furi":"<ruby>金曜日<rp>(</rp><rt>きんようび</rt><rp>)</rp></ruby>までに<ruby>書類<rp>(</rp><rt>しょるい</rt><rp>)</rp></ruby>を<ruby>用意<rp>(</rp><rt>ようい</rt><rp>)</rp></ruby>せねばならない。（在星期五之前必须要准备好资料。）"}],"id":"N3-103"},{"title":"104. ～の（疑问、断定）","blocks":[{"t":"label","label":"说明①","text":"表示疑问，读升调，女性用语。","furi":""},{"t":"label","label":"例句①","text":"ヤンさんはいつ国に帰るの？（小杨什么时候回国？）","furi":"ヤンさんはいつ<ruby>国<rp>(</rp><rt>こく</rt><rp>)</rp></ruby>に<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>るの？（小杨什么时候回国？）"},{"t":"label","label":"说明②","text":"表示轻微的断定，“是……的”，读降调。","furi":""},{"t":"label","label":"例句②","text":"今日は休みなの。（今天休息。）","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>は<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>みなの。（今天休息。）"},{"t":"label","label":"说明③","text":"表示轻微的命令。","furi":""},{"t":"label","label":"例句③","text":"さっさと着替えるの。（快点换衣服。）","furi":"さっさと<ruby>着替<rp>(</rp><rt>きが</rt><rp>)</rp></ruby>えるの。（快点换衣服。）"}],"id":"N3-104"},{"title":"105. ～のに（用途、目的）","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + のに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + のに"},{"t":"label","label":"说明","text":"表示用途、目的，“用于……、为了……”。","furi":""},{"t":"label","label":"例句","text":"パスポートを申請するのにいろいろな書類や写真を用意する必要がある。（申请护照，需要准备各种各样的资料和照片。）","furi":"パスポートを<ruby>申請<rp>(</rp><rt>しんせい</rt><rp>)</rp></ruby>するのにいろいろな<ruby>書類<rp>(</rp><rt>しょるい</rt><rp>)</rp></ruby>や<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>を<ruby>用意<rp>(</rp><rt>ようい</rt><rp>)</rp></ruby>する<ruby>必要<rp>(</rp><rt>ひつよう</rt><rp>)</rp></ruby>がある。（申请护照，需要准备各种各样的资料和照片。）"}],"id":"N3-105"},{"title":"106. ～の話では","blocks":[{"t":"label","label":"接续","text":"名词 + の話では","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + の<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>では"},{"t":"label","label":"说明","text":"表示传闻的根据，“据说……”。","furi":""},{"t":"label","label":"例句","text":"友だちの話では、新しい辞書はとてもいいそうです。（听朋友说，新出的字典很好。）","furi":"<ruby>友<rp>(</rp><rt>とも</rt><rp>)</rp></ruby>だちの<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>では、<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しい<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>はとてもいいそうです。（听朋友说，新出的字典很好。）"}],"id":"N3-106"},{"title":"107. ～ばかりだ","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + ばかりだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ばかりだ"},{"t":"label","label":"说明","text":"表示事态不断向不好的方向发展，“越来越……、不断地……”。","furi":""},{"t":"label","label":"例句","text":"物価は上がるばかりで生活は少しも楽にならない。（物价不断地上涨，生活没法轻松。）","furi":"<ruby>物価<rp>(</rp><rt>ぶっか</rt><rp>)</rp></ruby>は<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>がるばかりで<ruby>生活<rp>(</rp><rt>せいかつ</rt><rp>)</rp></ruby>は<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>しも<ruby>楽<rp>(</rp><rt>らく</rt><rp>)</rp></ruby>にならない。（物价不断地上涨，生活没法轻松。）"}],"id":"N3-107"},{"title":"108. ～ば～ほど","blocks":[{"t":"label","label":"接续","text":"动词ば形 + 同一动词辞书形 + ほど / い形容词词干+ければ + 同一い形容词辞书形+ほど","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ば<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>同<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ほど / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+ければ + <ruby>同一<rp>(</rp><rt>どういつ</rt><rp>)</rp></ruby>い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+ほど"},{"t":"label","label":"说明","text":"表示随着前项变化，后项也相应变化，“越……越……”。","furi":""},{"t":"label","label":"例句","text":"駅に近ければ近いほど、高くなりますので。（离车站越近，房租就越高。）","furi":"<ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>に<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>ければ<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>いほど、<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>くなりますので。（离车站越近，房租就越高。）"}],"id":"N3-108"},{"title":"109. ～ばよかった/なければよかった","blocks":[{"t":"label","label":"接续","text":"动词ば形 + よかった / ない形 + なければよかった","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ば<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + よかった / ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + なければよかった"},{"t":"label","label":"说明","text":"表示遗憾或责备，“要是……就好了、要是不……就好了”。","furi":""},{"t":"label","label":"例句","text":"彼女はわたしの話に傷ついたみたい。あんなことを言わなきゃよかった。（她好像因为我的话受伤了。早知道不那样说就好了。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>はわたしの<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>に<ruby>傷<rp>(</rp><rt>きず</rt><rp>)</rp></ruby>ついたみたい。あんなことを<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>わなきゃよかった。（她好像因为我的话受伤了。早知道不那样说就好了。）"}],"id":"N3-109"},{"title":"110. ～ぶり","blocks":[{"t":"label","label":"接续①","text":"名词 + ぶり（に）","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + ぶり（に）"},{"t":"label","label":"说明①","text":"表示时隔一段时间，“经过……之后又……”。","furi":""},{"t":"label","label":"例句①","text":"台風で電車が不通になっていたが、10時間ぶりに運転を始めたそうだ。（听说因为台风造成电车全线瘫痪，不过十个小时之后又恢复运营了。）","furi":"<ruby>台風<rp>(</rp><rt>たいふう</rt><rp>)</rp></ruby>で<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>が<ruby>不通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby>になっていたが、10<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>ぶりに<ruby>運転<rp>(</rp><rt>うんてん</rt><rp>)</rp></ruby>を<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>めたそうだ。（听说因为台风造成电车全线瘫痪，不过十个小时之后又恢复运营了。）"},{"t":"label","label":"接续②","text":"动词ます形/名词 + ぶり","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + ぶり"},{"t":"label","label":"说明②","text":"表示样子、状态，“……的样子、……的状态”。","furi":""},{"t":"label","label":"例句②","text":"彼の話しぶりに気に入らない。（不喜欢他说话的口气。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>しぶりに<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>に<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>らない。（不喜欢他说话的口气。）"}],"id":"N3-110"},{"title":"111. ～べき/べきだ/べきではない","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + べき/べきだ/べきではない（する→すべき/するべき）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + べき/べきだ/べきではない（する→すべき/するべき）"},{"t":"label","label":"说明","text":"表示应该或不应该，“应该……、不应该……”。","furi":""},{"t":"label","label":"例句","text":"約束は守るべきです。そうしないと、信用を失いますよ。（我们应该遵守约定，否则会失去信用。）","furi":"<ruby>約束<rp>(</rp><rt>やくそく</rt><rp>)</rp></ruby>は<ruby>守<rp>(</rp><rt>まも</rt><rp>)</rp></ruby>るべきです。そうしないと、<ruby>信用<rp>(</rp><rt>しんよう</rt><rp>)</rp></ruby>を<ruby>失<rp>(</rp><rt>うしな</rt><rp>)</rp></ruby>いますよ。（我们应该遵守约定，否则会失去信用。）"}],"id":"N3-111"},{"title":"112. ～ほど","blocks":[{"t":"label","label":"说明①","text":"表示程度，“几乎……、简直……”。","furi":""},{"t":"label","label":"例句①","text":"この料理はとても辛くて、体中から汗が出るほどだ。（这道菜辣得浑身冒汗。）","furi":"この<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>はとても<ruby>辛<rp>(</rp><rt>つら</rt><rp>)</rp></ruby>くて、<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby><ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby>から<ruby>汗<rp>(</rp><rt>あせ</rt><rp>)</rp></ruby>が<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>るほどだ。（这道菜辣得浑身冒汗。）"},{"t":"label","label":"说明②","text":"表示没有达到某种程度。","furi":""},{"t":"label","label":"例句②","text":"病状は手術が必要なほどではない。（病情还没有发展到非要动手术的程度。）","furi":"<ruby>病状<rp>(</rp><rt>びょうじょう</rt><rp>)</rp></ruby>は<ruby>手術<rp>(</rp><rt>しゅじゅつ</rt><rp>)</rp></ruby>が<ruby>必要<rp>(</rp><rt>ひつよう</rt><rp>)</rp></ruby>なほどではない。（病情还没有发展到非要动手术的程度。）"},{"t":"label","label":"说明③","text":"名词+ほど～はない，表示最高程度，“没有比……更……”。","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+ほど～はない，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>最高<rp>(</rp><rt>さいこう</rt><rp>)</rp></ruby><ruby>程度<rp>(</rp><rt>ていど</rt><rp>)</rp></ruby>，“<ruby>没<rp>(</rp><rt>ぼつ</rt><rp>)</rp></ruby><ruby>有<rp>(</rp><rt>ゆう</rt><rp>)</rp></ruby><ruby>比<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>……<ruby>更<rp>(</rp><rt>さら</rt><rp>)</rp></ruby>……”。"},{"t":"label","label":"例句③","text":"彼女ほど頭のいい人はいない。（没有比她更聪明的人了。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>ほど<ruby>頭<rp>(</rp><rt>あたま</rt><rp>)</rp></ruby>のいい<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>はいない。（没有比她更聪明的人了。）"}],"id":"N3-112"},{"title":"113. ～向きだ/向きに/向きの","blocks":[{"t":"label","label":"接续","text":"名词 + 向きだ/向きに/向きの","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + <ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>きだ/<ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>きに/<ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>きの"},{"t":"label","label":"说明","text":"表示适合某对象，“适合于……”。","furi":""},{"t":"label","label":"例句","text":"この服はキャンプ向きだ。（这件衣服适合野营。）","furi":"この<ruby>服<rp>(</rp><rt>ふく</rt><rp>)</rp></ruby>はキャンプ<ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>きだ。（这件衣服适合野营。）"}],"id":"N3-113"},{"title":"114. ～向けだ/向けに/向けの","blocks":[{"t":"label","label":"接续","text":"名词 + 向けだ/向けに/向けの","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + <ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>けだ/<ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>けに/<ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>けの"},{"t":"label","label":"说明","text":"表示面向某对象，“面向……、以……为对象”。","furi":""},{"t":"label","label":"例句","text":"この映画は大人向けなので、子どもは見てもつまらない。（这部电影是以大人为对象的，小孩子即使看了也觉得无趣。）","furi":"この<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>は<ruby>大人<rp>(</rp><rt>おとな</rt><rp>)</rp></ruby><ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>けなので、<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもは<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>てもつまらない。（这部电影是以大人为对象的，小孩子即使看了也觉得无趣。）"}],"id":"N3-114"},{"title":"115. ～もの/もん（理由）","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + もの/もん","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + もの/もん"},{"t":"label","label":"说明","text":"用于说明理由，带有辩解、撒娇语气，口语。","furi":""},{"t":"label","label":"例句","text":"A：どうして食べないの？（你为什么不吃？）","furi":"A：どうして<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べないの？（你为什么不吃？）"},{"t":"line","text":"B：だって嫌いなんだもん。（因为人家不喜欢吃呀。）","furi":"B：だって<ruby>嫌<rp>(</rp><rt>きら</rt><rp>)</rp></ruby>いなんだもん。（因为人家不喜欢吃呀。）"}],"id":"N3-115"},{"title":"116. ～ものだ","blocks":[{"t":"label","label":"说明①","text":"表示一般常识，“理应……、本来就是……”。","furi":""},{"t":"label","label":"例句①","text":"暑い夏ほどクーラーは売れるものだ。（越是炎热的夏天，空调越畅销。）","furi":"<ruby>暑<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>い<ruby>夏<rp>(</rp><rt>なつ</rt><rp>)</rp></ruby>ほどクーラーは<ruby>売<rp>(</rp><rt>う</rt><rp>)</rp></ruby>れるものだ。（越是炎热的夏天，空调越畅销。）"},{"t":"label","label":"说明②","text":"动词た形+ものだ，表示回忆。","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>+ものだ，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>回<rp>(</rp><rt>かい</rt><rp>)</rp></ruby><ruby>忆<rp>(</rp><rt>忆</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句②","text":"子どもの頃はよくこの川で遊んだものだ。（小时候经常在这条河边玩。）","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもの<ruby>頃<rp>(</rp><rt>ころ</rt><rp>)</rp></ruby>はよくこの<ruby>川<rp>(</rp><rt>かわ</rt><rp>)</rp></ruby>で<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>んだものだ。（小时候经常在这条河边玩。）"},{"t":"label","label":"说明③","text":"表示感叹。","furi":""},{"t":"label","label":"例句③","text":"時間の経つのは早いものですね。（时间过得真快啊。）","furi":"<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>の<ruby>経<rp>(</rp><rt>た</rt><rp>)</rp></ruby>つのは<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>いものですね。（时间过得真快啊。）"},{"t":"label","label":"说明④","text":"たい+ものだ/ほしい+ものだ，表示强烈愿望。","furi":"たい+ものだ/ほしい+ものだ，<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>强<rp>(</rp><rt>强</rt><rp>)</rp></ruby><ruby>烈<rp>(</rp><rt>れつ</rt><rp>)</rp></ruby><ruby>愿<rp>(</rp><rt>すなお</rt><rp>)</rp></ruby><ruby>望<rp>(</rp><rt>もち</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句④","text":"ぜひハワイへ旅行に行きたいものだ。（真想去夏威夷旅行。）","furi":"ぜひハワイへ<ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きたいものだ。（真想去夏威夷旅行。）"}],"id":"N3-116"},{"title":"117. ～やら～やら","blocks":[{"t":"label","label":"接续","text":"动词辞书形/い形容词辞书形/名词 + やら～やら","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + やら～やら"},{"t":"label","label":"说明","text":"表示列举消极的事例，“……啦……啦、又是……又是……”。","furi":""},{"t":"label","label":"例句","text":"今月はレポートやら試験やらでひどく忙しかった。（这个月又是写报告，又是考试，忙得团团转。）","furi":"<ruby>今月<rp>(</rp><rt>こんげつ</rt><rp>)</rp></ruby>はレポートやら<ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>やらでひどく<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しかった。（这个月又是写报告，又是考试，忙得团团转。）"}],"id":"N3-117"},{"title":"118. ～ようがない/ようもない","blocks":[{"t":"label","label":"接续","text":"动词ます形 + ようがない/ようもない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ようがない/ようもない"},{"t":"label","label":"说明","text":"“无法……、没有办法……”。","furi":""},{"t":"label","label":"例句","text":"故障した機械を直してくれと頼まれたが、部品がなくては修理しようがない。（别人请我修机器，但是没有零部件的话没法修。）","furi":"<ruby>故障<rp>(</rp><rt>こしょう</rt><rp>)</rp></ruby>した<ruby>機械<rp>(</rp><rt>きかい</rt><rp>)</rp></ruby>を<ruby>直<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>してくれと<ruby>頼<rp>(</rp><rt>たの</rt><rp>)</rp></ruby>まれたが、<ruby>部品<rp>(</rp><rt>ぶひん</rt><rp>)</rp></ruby>がなくては<ruby>修理<rp>(</rp><rt>しゅうり</rt><rp>)</rp></ruby>しようがない。（别人请我修机器，但是没有零部件的话没法修。）"}],"id":"N3-118"},{"title":"119. ～ように（希望、间接引用）","blocks":[{"t":"label","label":"说明①","text":"表示希望、要求。","furi":""},{"t":"label","label":"例句①","text":"どうか彼の病気が治るように。（希望他能早日康复。）","furi":"どうか<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>が<ruby>治<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>るように。（希望他能早日康复。）"},{"t":"label","label":"说明②","text":"表示间接引用，后接「言う、伝える」等。","furi":"<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>间<rp>(</rp><rt>间</rt><rp>)</rp></ruby><ruby>接<rp>(</rp><rt>せっ</rt><rp>)</rp></ruby><ruby>引用<rp>(</rp><rt>いんよう</rt><rp>)</rp></ruby>，<ruby>后<rp>(</rp><rt>きさき</rt><rp>)</rp></ruby><ruby>接<rp>(</rp><rt>せっ</rt><rp>)</rp></ruby>「<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>う、<ruby>伝<rp>(</rp><rt>つた</rt><rp>)</rp></ruby>える」<ruby>等<rp>(</rp><rt>とう</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句②","text":"戻りましたら、家に電話するようにお伝えください。（他回来之后，请转告他给家里打个电话。）","furi":"<ruby>戻<rp>(</rp><rt>もど</rt><rp>)</rp></ruby>りましたら、<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>に<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>するようにお<ruby>伝<rp>(</rp><rt>つた</rt><rp>)</rp></ruby>えください。（他回来之后，请转告他给家里打个电话。）"}],"id":"N3-119"},{"title":"120. ～ようになっている","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + ようになっている","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ようになっている"},{"t":"label","label":"说明","text":"表示正在发生某种变化或状态持续，“变得……、处于……状态”。","furi":""},{"t":"label","label":"例句","text":"火事が起こった場合は、このベルは自動的に鳴るようになっています。（发生火灾时，这个电铃会自动响。）","furi":"<ruby>火事<rp>(</rp><rt>かじ</rt><rp>)</rp></ruby>が<ruby>起<rp>(</rp><rt>お</rt><rp>)</rp></ruby>こった<ruby>場合<rp>(</rp><rt>ばあい</rt><rp>)</rp></ruby>は、このベルは<ruby>自動的<rp>(</rp><rt>じどうてき</rt><rp>)</rp></ruby>に<ruby>鳴<rp>(</rp><rt>な</rt><rp>)</rp></ruby>るようになっています。（发生火灾时，这个电铃会自动响。）"}],"id":"N3-120"},{"title":"121. ～ように見える","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+の + ように見える","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + ように<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>える"},{"t":"label","label":"说明","text":"表示看上去像那样，“看上去像是……”。","furi":""},{"t":"label","label":"例句","text":"着物を着て化粧をした彼女は別人のように見える。（穿上和服、化了妆的她，看上去像别人一样。）","furi":"<ruby>着物<rp>(</rp><rt>きもの</rt><rp>)</rp></ruby>を<ruby>着<rp>(</rp><rt>き</rt><rp>)</rp></ruby>て<ruby>化粧<rp>(</rp><rt>けしょう</rt><rp>)</rp></ruby>をした<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>は<ruby>別人<rp>(</rp><rt>べつじん</rt><rp>)</rp></ruby>のように<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>える。（穿上和服、化了妆的她，看上去像别人一样。）"}],"id":"N3-121"},{"title":"122. ～（ら）れる（自发态）","blocks":[{"t":"label","label":"接续","text":"I类ない形 + れる / II类ない形 + られる / III类：する→される、来る→来られる","furi":"I<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + れる / II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + られる / III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：する→される、<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る→<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>られる"},{"t":"label","label":"说明","text":"表示不由自主地产生某种心理活动，“不由得……”。","furi":""},{"t":"label","label":"例句","text":"この写真を見るたびに、子どもの頃のことが思い出される。（每当看到这张照片，就不由得想起小时候的事情。）","furi":"この<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>るたびに、<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもの<ruby>頃<rp>(</rp><rt>ころ</rt><rp>)</rp></ruby>のことが<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>い<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>される。（每当看到这张照片，就不由得想起小时候的事情。）"}],"id":"N3-122"},{"title":"123. ～わけがない/わけはない","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+の + わけがない/わけはない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + わけがない/わけはない"},{"t":"label","label":"说明","text":"表示强烈否定，“不可能……、不会……”。","furi":""},{"t":"label","label":"例句","text":"この漫画は若い人に大人気なので、高校生が知らないわけがない。（这本漫画在年轻人当中非常流行，所以高中生不可能不知道。）","furi":"この<ruby>漫画<rp>(</rp><rt>まんが</rt><rp>)</rp></ruby>は<ruby>若<rp>(</rp><rt>わか</rt><rp>)</rp></ruby>い<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>に<ruby>大人気<rp>(</rp><rt>だいにんき</rt><rp>)</rp></ruby>なので、<ruby>高校生<rp>(</rp><rt>こうこうせい</rt><rp>)</rp></ruby>が<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>らないわけがない。（这本漫画在年轻人当中非常流行，所以高中生不可能不知道。）"}],"id":"N3-123"},{"title":"124. ～わけだ","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+の + わけだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + わけだ"},{"t":"label","label":"说明①","text":"表示基于事实的理所当然的结论，“当然……、难怪……”。","furi":""},{"t":"label","label":"例句①","text":"暑いわけだ。38度もある。（难怪那么热，气温高达三十八度。）","furi":"<ruby>暑<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>いわけだ。38<ruby>度<rp>(</rp><rt>ど</rt><rp>)</rp></ruby>もある。（难怪那么热，气温高达三十八度。）"},{"t":"label","label":"说明②","text":"表示换而言之，“也就是说……”。","furi":""},{"t":"label","label":"例句②","text":"つまり、もう昼ごはんを食べたわけですね。（也就是说你已经吃过午饭了。）","furi":"つまり、もう<ruby>昼<rp>(</rp><rt>ひる</rt><rp>)</rp></ruby>ごはんを<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べたわけですね。（也就是说你已经吃过午饭了。）"}],"id":"N3-124"},{"title":"125. ～わけではない/わけでもない","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+の + わけではない/でもない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + わけではない/でもない"},{"t":"label","label":"说明","text":"表示部分否定，“并不是……”。","furi":""},{"t":"label","label":"例句","text":"スポーツが苦手だと言っても、スポーツ番組を見るのが嫌いだというわけではない。（虽说我不擅长运动，但并不是说我不喜欢看体育节目。）","furi":"スポーツが<ruby>苦手<rp>(</rp><rt>にがて</rt><rp>)</rp></ruby>だと<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>っても、スポーツ<ruby>番組<rp>(</rp><rt>ばんぐみ</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>るのが<ruby>嫌<rp>(</rp><rt>きら</rt><rp>)</rp></ruby>いだというわけではない。（虽说我不擅长运动，但并不是说我不喜欢看体育节目。）"}],"id":"N3-125"},{"title":"126. ～わけにはいかない","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + わけにはいかない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + わけにはいかない"},{"t":"label","label":"说明","text":"表示从常识、责任等考虑不能做某事，“不能……、不可以……”。","furi":""},{"t":"label","label":"例句","text":"重要な会議だから、責任者のわたしが遅れていくわけにはいかない。（因为是重要会议，所以我身为负责人不能迟到。）","furi":"<ruby>重要<rp>(</rp><rt>じゅうよう</rt><rp>)</rp></ruby>な<ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby>だから、<ruby>責任<rp>(</rp><rt>せきにん</rt><rp>)</rp></ruby><ruby>者<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>のわたしが<ruby>遅<rp>(</rp><rt>おく</rt><rp>)</rp></ruby>れていくわけにはいかない。（因为是重要会议，所以我身为负责人不能迟到。）"}],"id":"N3-126"},{"title":"127. ～を込めて","blocks":[{"t":"label","label":"接续","text":"名词 + を込めて","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + を<ruby>込<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>めて"},{"t":"label","label":"说明","text":"表示将某种感情倾注其中，“充满……、怀着……”。","furi":""},{"t":"label","label":"例句","text":"感謝の気持ちを込めて、このカードを作りました。（满怀着感激的心情，制作了这张卡片。）","furi":"<ruby>感謝<rp>(</rp><rt>かんしゃ</rt><rp>)</rp></ruby>の<ruby>気持<rp>(</rp><rt>きも</rt><rp>)</rp></ruby>ちを<ruby>込<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>めて、このカードを<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>りました。（满怀着感激的心情，制作了这张卡片。）"}],"id":"N3-127"},{"title":"128. ～を～とする","blocks":[{"t":"label","label":"接续","text":"名词 + を + 名词 + とする","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + を + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + とする"},{"t":"label","label":"说明","text":"“把……当作……”。","furi":""},{"t":"label","label":"例句","text":"投票の結果、山田氏を会長とすることに決定しました。（根据投票结果，大家一致决定让山田担任会长。）","furi":"<ruby>投票<rp>(</rp><rt>とうひょう</rt><rp>)</rp></ruby>の<ruby>結果<rp>(</rp><rt>けっか</rt><rp>)</rp></ruby>、<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby><ruby>氏<rp>(</rp><rt>し</rt><rp>)</rp></ruby>を<ruby>会長<rp>(</rp><rt>かいちょう</rt><rp>)</rp></ruby>とすることに<ruby>決定<rp>(</rp><rt>けってい</rt><rp>)</rp></ruby>しました。（根据投票结果，大家一致决定让山田担任会长。）"}],"id":"N3-128"},{"title":"129. ～をはじめ（として）/をはじめとする","blocks":[{"t":"label","label":"接续","text":"名词 + をはじめ（として）/をはじめとする","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + をはじめ（として）/をはじめとする"},{"t":"label","label":"说明","text":"“以……为首、以……为代表”。","furi":""},{"t":"label","label":"例句","text":"わたしたちの町にはこのお寺をはじめ、いろいろな古い建物がある。（在我们的城镇里，以这座寺庙为代表，有很多古老的建筑。）","furi":"わたしたちの<ruby>町<rp>(</rp><rt>まち</rt><rp>)</rp></ruby>にはこのお<ruby>寺<rp>(</rp><rt>てら</rt><rp>)</rp></ruby>をはじめ、いろいろな<ruby>古<rp>(</rp><rt>ふる</rt><rp>)</rp></ruby>い<ruby>建物<rp>(</rp><rt>たてもの</rt><rp>)</rp></ruby>がある。（在我们的城镇里，以这座寺庙为代表，有很多古老的建筑。）"}],"id":"N3-129"},{"title":"130. ～んじゃない（口语）","blocks":[{"t":"label","label":"说明①","text":"读升调，表示征求同意或反问，“不是吗？”","furi":""},{"t":"label","label":"例句①","text":"その座っている人、鈴木さんじゃない？（坐在那儿的人，不是铃木吗？）","furi":"その<ruby>座<rp>(</rp><rt>すわ</rt><rp>)</rp></ruby>っている<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>、<ruby>鈴木<rp>(</rp><rt>すずき</rt><rp>)</rp></ruby>さんじゃない？（坐在那儿的人，不是铃木吗？）"},{"t":"label","label":"说明②","text":"读降调，表示禁止，“不要……、不许……”。","furi":""},{"t":"label","label":"例句②","text":"勝手に人の日記を読むんじゃない。（不要擅自读别人的日记。）","furi":"<ruby>勝手<rp>(</rp><rt>かって</rt><rp>)</rp></ruby>に<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>の<ruby>日記<rp>(</rp><rt>にっき</rt><rp>)</rp></ruby>を<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>むんじゃない。（不要擅自读别人的日记。）"}],"id":"N3-130"}]},{"id":"N3-u2","title":"敬语（N3补充部分）","points":[{"title":"131. お/ご～です","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + です / お/ご + III类动词词干/名词 + です","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + です / お/ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + です"},{"t":"label","label":"说明","text":"尊他语的固定表达。","furi":""},{"t":"label","label":"例句","text":"社長がお呼びです。（社长叫您。）","furi":"<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>がお<ruby>呼<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>びです。（社长叫您。）"}],"id":"N3-131"},{"title":"132. お/ご～になれる","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + になれる / ご + III类动词词干 + になれる","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + になれる / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + になれる"},{"t":"label","label":"说明","text":"尊他语「お/ご～になる」的可能形，“您能够……”。","furi":"<ruby>尊<rp>(</rp><rt>とうと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>「お/ご～になる」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>可能<rp>(</rp><rt>かのう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>，“<ruby>您<rp>(</rp><rt>您</rt><rp>)</rp></ruby><ruby>能<rp>(</rp><rt>のう</rt><rp>)</rp></ruby><ruby>够<rp>(</rp><rt>够</rt><rp>)</rp></ruby>……”。"},{"t":"label","label":"例句","text":"グリーン車だとゆっくりお座りになれます。（坐指定席的话能够更宽敞一些。）","furi":"グリーン<ruby>車<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>だとゆっくりお<ruby>座<rp>(</rp><rt>すわ</rt><rp>)</rp></ruby>りになれます。（坐指定席的话能够更宽敞一些。）"}],"id":"N3-132"},{"title":"133. ～ていらっしゃる/ておいでになる","blocks":[{"t":"label","label":"接续","text":"动词て形 + いらっしゃる/おいでになる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + いらっしゃる/おいでになる"},{"t":"label","label":"说明","text":"「～です/～ている/～ていく/～てくる」的尊他语。","furi":"「～です/～ている/～ていく/～てくる」<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>尊<rp>(</rp><rt>みこと</rt><rp>)</rp></ruby><ruby>他<rp>(</rp><rt>た</rt><rp>)</rp></ruby><ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"今、ほかの学生と話していらっしゃいますから、少々待ってください。（现在正在和其他学生谈话，请稍等。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>、ほかの<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>と<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>していらっしゃいますから、<ruby>少々<rp>(</rp><rt>しょうしょう</rt><rp>)</rp></ruby><ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>ってください。（现在正在和其他学生谈话，请稍等。）"}],"id":"N3-133"},{"title":"134. お/ご～できる","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + できる / ご + III类动词词干 + できる","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + できる / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + できる"},{"t":"label","label":"说明","text":"自谦语的可能形，“可以……、能够……”。","furi":""},{"t":"label","label":"例句","text":"ゆっくりとお話できる場所がいいですね。（能够慢慢聊天的地方比较好。）","furi":"ゆっくりとお<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>できる<ruby>場所<rp>(</rp><rt>ばしょ</rt><rp>)</rp></ruby>がいいですね。（能够慢慢聊天的地方比较好。）"}],"id":"N3-134"},{"title":"135. お/ご～いただく","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + いただく / ご + III类动词词干 + いただく","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + いただく / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + いただく"},{"t":"label","label":"说明","text":"自谦语，表示承蒙对方做某事。","furi":""},{"t":"label","label":"例句","text":"この書類を佐藤さんにお渡しいただきたいんですが。（想拜托您把这份文件交给佐藤。）","furi":"この<ruby>書類<rp>(</rp><rt>しょるい</rt><rp>)</rp></ruby>を<ruby>佐藤<rp>(</rp><rt>さとう</rt><rp>)</rp></ruby>さんにお<ruby>渡<rp>(</rp><rt>わた</rt><rp>)</rp></ruby>しいただきたいんですが。（想拜托您把这份文件交给佐藤。）"}],"id":"N3-135"},{"title":"136. お/ご～願う","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + 願う / ご + III类动词词干 + 願う","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>う / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + <ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>う"},{"t":"label","label":"说明","text":"表示委婉请求，“能否请您……”。","furi":""},{"t":"label","label":"例句","text":"この件を山田さんにお伝え願えませんか。（这件事可否麻烦您向山田传达一下？）","furi":"この<ruby>件<rp>(</rp><rt>けん</rt><rp>)</rp></ruby>を<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby>さんにお<ruby>伝<rp>(</rp><rt>つた</rt><rp>)</rp></ruby>え<ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>えませんか。（这件事可否麻烦您向山田传达一下？）"}],"id":"N3-136"},{"title":"137. ～ていただけませんか","blocks":[{"t":"label","label":"接续","text":"动词て形 + いただけませんか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + いただけませんか"},{"t":"label","label":"说明","text":"请求对方为自己做某事，“请您……”。","furi":""},{"t":"label","label":"例句","text":"学生：先生、日本語で文章を書いたんですが、わたしの作文を見ていただけませんか。（老师，我用日文写了一篇作文，请您帮我看一下可以吗？）","furi":"<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>：<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>、<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>で<ruby>文章<rp>(</rp><rt>ぶんしょう</rt><rp>)</rp></ruby>を<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いたんですが、わたしの<ruby>作文<rp>(</rp><rt>さくぶん</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ていただけませんか。（老师，我用日文写了一篇作文，请您帮我看一下可以吗？）"},{"t":"line","text":"先生：ええ、いいですよ。（好的。）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>：ええ、いいですよ。（好的。）"}],"id":"N3-137"},{"title":"138. ～てもよろしいでしょうか","blocks":[{"t":"label","label":"接续","text":"动词て形 + もよろしいでしょうか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + もよろしいでしょうか"},{"t":"label","label":"说明","text":"委婉的询问、请求，“……可以吗？”","furi":""},{"t":"label","label":"例句","text":"お客様、このお皿をさげてもよろしいでしょうか。（客人您好，这个盘子可以撤下去吗？）","furi":"お<ruby>客様<rp>(</rp><rt>きゃくさま</rt><rp>)</rp></ruby>、このお<ruby>皿<rp>(</rp><rt>さら</rt><rp>)</rp></ruby>をさげてもよろしいでしょうか。（客人您好，这个盘子可以撤下去吗？）"}],"id":"N3-138"},{"title":"139. ～（さ）せていただく","blocks":[{"t":"label","label":"接续","text":"I类ない形 + せていただく / II类ない形 + させていただく / III类：する→させていただく、来る→来させていただく","furi":"I<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + せていただく / II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + させていただく / III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby>：する→させていただく、<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る→<ruby>来<rp>(</rp><rt>きた</rt><rp>)</rp></ruby>させていただく"},{"t":"label","label":"说明","text":"自谦语，请求对方允许自己做某事，“请让我……、请允许我……”。","furi":""},{"t":"label","label":"例句","text":"自己紹介させていただきます。（请允许我自我介绍一下。）","furi":"<ruby>自己<rp>(</rp><rt>じこ</rt><rp>)</rp></ruby><ruby>紹介<rp>(</rp><rt>しょうかい</rt><rp>)</rp></ruby>させていただきます。（请允许我自我介绍一下。）"}],"id":"N3-139"},{"title":"140. 敬语的特殊形式（表格）","blocks":[{"t":"line","text":"尊他语特殊形式：","furi":""},{"t":"line","text":"行く/来る/いる → いらっしゃる/おいでになる","furi":"<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く/<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る/いる → いらっしゃる/おいでになる"},{"t":"line","text":"する → なさる","furi":""},{"t":"line","text":"食べる/飲む → 召し上がる","furi":"<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる/<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>む → <ruby>召<rp>(</rp><rt>め</rt><rp>)</rp></ruby>し<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>がる"},{"t":"line","text":"言う → おっしゃる","furi":"<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>う → おっしゃる"},{"t":"line","text":"見る → ご覧になる","furi":"<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>る → ご<ruby>覧<rp>(</rp><rt>らん</rt><rp>)</rp></ruby>になる"},{"t":"line","text":"くれる → くださる","furi":""},{"t":"line","text":"自谦语特殊形式：","furi":""},{"t":"line","text":"行く/来る → 参る/伺う","furi":"<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く/<ruby>来<rp>(</rp><rt>く</rt><rp>)</rp></ruby>る → <ruby>参<rp>(</rp><rt>まい</rt><rp>)</rp></ruby>る/<ruby>伺<rp>(</rp><rt>うかが</rt><rp>)</rp></ruby>う"},{"t":"line","text":"いる → おる","furi":""},{"t":"line","text":"する → いたす","furi":""},{"t":"line","text":"見る → 拝見する","furi":"<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>る → <ruby>拝見<rp>(</rp><rt>はいけん</rt><rp>)</rp></ruby>する"},{"t":"line","text":"言う → 申す/申し上げる","furi":"<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>う → <ruby>申<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>す/<ruby>申<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>し<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>げる"},{"t":"line","text":"食べる/飲む → いただく","furi":"<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べる/<ruby>飲<rp>(</rp><rt>の</rt><rp>)</rp></ruby>む → いただく"},{"t":"line","text":"もらう → いただく/頂戴する","furi":"もらう → いただく/<ruby>頂戴<rp>(</rp><rt>ちょうだい</rt><rp>)</rp></ruby>する"}],"id":"N3-140"}]}]},{"id":"N2","name":"N2 文法详解（整理版）","units":[{"id":"N2-u1","title":"第1单元 ～あげく（に）～に至って等","points":[{"title":"1. ～あげく（に）","blocks":[{"t":"label","label":"接续","text":"动词た形 / 名词 + の + あげく（に）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + の + あげく（に）"},{"t":"label","label":"说明","text":"表示结果，“最后……”。后项多为消极意义。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"彼女はいろいろと悩んだあげく、結婚をやめてしまった。（她烦恼了许久，最后没有结婚。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>はいろいろと<ruby>悩<rp>(</rp><rt>なや</rt><rp>)</rp></ruby>んだあげく、<ruby>結婚<rp>(</rp><rt>けっこん</rt><rp>)</rp></ruby>をやめてしまった。（她烦恼了许久，最后没有结婚。）"},{"t":"line","text":"プリンターの調子が悪くなり、製造会社に電話で問い合わせたら、向こうの担当者に、あれこれ質問に答えさせられたあげく、対応できないと言われた。（打印机出了点问题，打电话咨询了生产商，对方负责人问来问去，让我回答了半天，最后却说他们没法处理。）","furi":"プリンターの<ruby>調子<rp>(</rp><rt>ちょうし</rt><rp>)</rp></ruby>が<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>くなり、<ruby>製造<rp>(</rp><rt>せいぞう</rt><rp>)</rp></ruby><ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>に<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>で<ruby>問<rp>(</rp><rt>と</rt><rp>)</rp></ruby>い<ruby>合<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>わせたら、<ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>こうの<ruby>担当<rp>(</rp><rt>たんとう</rt><rp>)</rp></ruby><ruby>者<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>に、あれこれ<ruby>質問<rp>(</rp><rt>しつもん</rt><rp>)</rp></ruby>に<ruby>答<rp>(</rp><rt>こた</rt><rp>)</rp></ruby>えさせられたあげく、<ruby>対応<rp>(</rp><rt>たいおう</rt><rp>)</rp></ruby>できないと<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>われた。（打印机出了点问题，打电话咨询了生产商，对方负责人问来问去，让我回答了半天，最后却说他们没法处理。）"}],"id":"N2-1"},{"title":"2. ～あまり（に）","blocks":[{"t":"label","label":"接续","text":"动词辞书形/た形 / い形容词普通形 / な形容词词干+な / 名词+の + あまり（に）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + あまり（に）"},{"t":"label","label":"说明","text":"表示由于过度……而导致某种结果，“由于过度……因而……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"試験の結果を気にするあまり、夜眠れなくなってしまった。（由于太在意考试结果，晚上失眠了。）","furi":"<ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>の<ruby>結果<rp>(</rp><rt>けっか</rt><rp>)</rp></ruby>を<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>にするあまり、<ruby>夜<rp>(</rp><rt>よる</rt><rp>)</rp></ruby><ruby>眠<rp>(</rp><rt>ねむ</rt><rp>)</rp></ruby>れなくなってしまった。（由于太在意考试结果，晚上失眠了。）"},{"t":"line","text":"何でも完全にやろうと思うあまりに、体を壊す人がいる。（有些人因为做任何事情都过于追求完美，而弄坏了身体。）","furi":"<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>でも<ruby>完全<rp>(</rp><rt>かんぜん</rt><rp>)</rp></ruby>にやろうと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>うあまりに、<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby>を<ruby>壊<rp>(</rp><rt>こわ</rt><rp>)</rp></ruby>す<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>がいる。（有些人因为做任何事情都过于追求完美，而弄坏了身体。）"}],"id":"N2-2"},{"title":"3. ～以上（は）","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+である / 名词+である + 以上（は）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+である / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+である + <ruby>以上<rp>(</rp><rt>いじょう</rt><rp>)</rp></ruby>（は）"},{"t":"label","label":"说明","text":"表示确定的事实，“既然……就……”。后项常接决心、义务、建议等。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"エネルギーの問題がこれほど深刻になった以上、世界各国が協力して、ただちに対策を立てるべきだ。（既然能源问题已经如此严峻，世界各国就应该联合起来，立即采取对策。）","furi":"エネルギーの<ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>がこれほど<ruby>深刻<rp>(</rp><rt>しんこく</rt><rp>)</rp></ruby>になった<ruby>以上<rp>(</rp><rt>いじょう</rt><rp>)</rp></ruby>、<ruby>世界<rp>(</rp><rt>せかい</rt><rp>)</rp></ruby><ruby>各国<rp>(</rp><rt>かっこく</rt><rp>)</rp></ruby>が<ruby>協力<rp>(</rp><rt>きょうりょく</rt><rp>)</rp></ruby>して、ただちに<ruby>対策<rp>(</rp><rt>たいさく</rt><rp>)</rp></ruby>を<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>てるべきだ。（既然能源问题已经如此严峻，世界各国就应该联合起来，立即采取对策。）"},{"t":"line","text":"留学する以上は、勉強だけでなく、その国の文化を学んだり交流をしたりしたいと思う。（既然去留学了，就不仅是学习，我还想了解该国的文化，并与该国的人们进行交流。）","furi":"<ruby>留学<rp>(</rp><rt>りゅうがく</rt><rp>)</rp></ruby>する<ruby>以上<rp>(</rp><rt>いじょう</rt><rp>)</rp></ruby>は、<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>だけでなく、その<ruby>国<rp>(</rp><rt>くに</rt><rp>)</rp></ruby>の<ruby>文化<rp>(</rp><rt>ぶんか</rt><rp>)</rp></ruby>を<ruby>学<rp>(</rp><rt>まな</rt><rp>)</rp></ruby>んだり<ruby>交流<rp>(</rp><rt>こうりゅう</rt><rp>)</rp></ruby>をしたりしたいと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>う。（既然去留学了，就不仅是学习，我还想了解该国的文化，并与该国的人们进行交流。）"}],"id":"N2-3"},{"title":"4. ～上は","blocks":[{"t":"label","label":"接续","text":"动词辞书形/た形 + 上は","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>は"},{"t":"label","label":"说明","text":"表示既定事实，“既然……就……”。语气比「～以上（は）」更强烈。","furi":"<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>既定<rp>(</rp><rt>きてい</rt><rp>)</rp></ruby><ruby>事<rp>(</rp><rt>ごと</rt><rp>)</rp></ruby><ruby>实<rp>(</rp><rt>实</rt><rp>)</rp></ruby>，“<ruby>既<rp>(</rp><rt>すんで</rt><rp>)</rp></ruby><ruby>然<rp>(</rp><rt>しか</rt><rp>)</rp></ruby>……<ruby>就<rp>(</rp><rt>就</rt><rp>)</rp></ruby>……”。<ruby>语<rp>(</rp><rt>语</rt><rp>)</rp></ruby><ruby>气<rp>(</rp><rt>气</rt><rp>)</rp></ruby><ruby>比<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>「～<ruby>以上<rp>(</rp><rt>いじょう</rt><rp>)</rp></ruby>（は）」<ruby>更<rp>(</rp><rt>さら</rt><rp>)</rp></ruby><ruby>强<rp>(</rp><rt>强</rt><rp>)</rp></ruby><ruby>烈<rp>(</rp><rt>れつ</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"事態がこうなった上は、もう彼一人に任せてはおけない。（既然事态发展到这一步，就不能再交给他一个人去做了。）","furi":"<ruby>事態<rp>(</rp><rt>じたい</rt><rp>)</rp></ruby>がこうなった<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>は、もう<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby><ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>に<ruby>任<rp>(</rp><rt>まか</rt><rp>)</rp></ruby>せてはおけない。（既然事态发展到这一步，就不能再交给他一个人去做了。）"}],"id":"N2-4"},{"title":"5. ～（よ）うではないか/（よ）うじゃないか","blocks":[{"t":"label","label":"接续","text":"动词意向形 + ではないか/じゃないか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>意向<rp>(</rp><rt>いこう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ではないか/じゃないか"},{"t":"label","label":"说明","text":"表示建议或劝诱，“让我们……吧”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"食糧不足で困っている人たちに、できる限りの援助をしようではないか。（让我们尽最大努力去援助那些因粮食不足而处于困境的人吧。）","furi":"<ruby>食糧<rp>(</rp><rt>しょくりょう</rt><rp>)</rp></ruby><ruby>不足<rp>(</rp><rt>ふそく</rt><rp>)</rp></ruby>で<ruby>困<rp>(</rp><rt>こま</rt><rp>)</rp></ruby>っている<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>たちに、できる<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りの<ruby>援助<rp>(</rp><rt>えんじょ</rt><rp>)</rp></ruby>をしようではないか。（让我们尽最大努力去援助那些因粮食不足而处于困境的人吧。）"},{"t":"line","text":"この本に載っているレストランはとてもおいしそうだ。みんなで行ってみようじゃないか。（这本书上刊登的餐厅看起来很好吃。大家一起去看看吧。）","furi":"この<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>に<ruby>載<rp>(</rp><rt>の</rt><rp>)</rp></ruby>っているレストランはとてもおいしそうだ。みんなで<ruby>行<rp>(</rp><rt>おこな</rt><rp>)</rp></ruby>ってみようじゃないか。（这本书上刊登的餐厅看起来很好吃。大家一起去看看吧。）"}],"id":"N2-5"},{"title":"6. ～得る/得ない","blocks":[{"t":"label","label":"接续①","text":"动词ます形 + 得る","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>得<rp>(</rp><rt>え</rt><rp>)</rp></ruby>る"},{"t":"label","label":"说明①","text":"表示可能性，“能……、有可能……”。用于书面语。","furi":""},{"t":"label","label":"例句①","text":"今度のサッカーの決勝戦では、どんなことでも起こりうる。（这次的足球决赛，什么情况都有可能发生。）","furi":"<ruby>今度<rp>(</rp><rt>こんど</rt><rp>)</rp></ruby>のサッカーの<ruby>決勝<rp>(</rp><rt>けっしょう</rt><rp>)</rp></ruby><ruby>戦<rp>(</rp><rt>せん</rt><rp>)</rp></ruby>では、どんなことでも<ruby>起<rp>(</rp><rt>お</rt><rp>)</rp></ruby>こりうる。（这次的足球决赛，什么情况都有可能发生。）"},{"t":"label","label":"接续②","text":"动词ます形 + 得ない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>得<rp>(</rp><rt>え</rt><rp>)</rp></ruby>ない"},{"t":"label","label":"说明②","text":"表示没有可能性，“不可能……”。","furi":""},{"t":"label","label":"例句②","text":"他人の夢の中に潜入して、アイディアを盗むなんてあり得ない話だ。（潜入到别人的梦里窃取点子，简直是天方夜谭。）","furi":"<ruby>他人<rp>(</rp><rt>たにん</rt><rp>)</rp></ruby>の<ruby>夢<rp>(</rp><rt>ゆめ</rt><rp>)</rp></ruby>の<ruby>中<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>に<ruby>潜入<rp>(</rp><rt>せんにゅう</rt><rp>)</rp></ruby>して、アイディアを<ruby>盗<rp>(</rp><rt>ぬす</rt><rp>)</rp></ruby>むなんてあり<ruby>得<rp>(</rp><rt>え</rt><rp>)</rp></ruby>ない<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>だ。（潜入到别人的梦里窃取点子，简直是天方夜谭。）"}],"id":"N2-6"},{"title":"7. ～甲斐がある/甲斐がない/甲斐もなく","blocks":[{"t":"label","label":"接续","text":"动词た形 / 名词+の + 甲斐がある/甲斐がない/甲斐もなく","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + <ruby>甲斐<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>がある/<ruby>甲斐<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>がない/<ruby>甲斐<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>もなく"},{"t":"label","label":"说明","text":"“有（没有）……的价值、回报”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"3時間待った甲斐があって、雨がやみ、美しい景色を見ることができた。（三个小时没有白等，雨停了，欣赏到了美丽的风景。）","furi":"3<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby><ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>った<ruby>甲斐<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>があって、<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>がやみ、<ruby>美<rp>(</rp><rt>うつく</rt><rp>)</rp></ruby>しい<ruby>景色<rp>(</rp><rt>けしき</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ることができた。（三个小时没有白等，雨停了，欣赏到了美丽的风景。）"},{"t":"line","text":"必死の練習の甲斐もなく、オリンピックの代表選手には選ばれなかった。（拼命练习都白费了，没有被选为奥运会参赛选手。）","furi":"<ruby>必死<rp>(</rp><rt>ひっし</rt><rp>)</rp></ruby>の<ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby>の<ruby>甲斐<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>もなく、オリンピックの<ruby>代表<rp>(</rp><rt>だいひょう</rt><rp>)</rp></ruby><ruby>選手<rp>(</rp><rt>せんしゅ</rt><rp>)</rp></ruby>には<ruby>選<rp>(</rp><rt>えら</rt><rp>)</rp></ruby>ばれなかった。（拼命练习都白费了，没有被选为奥运会参赛选手。）"}],"id":"N2-7"},{"title":"8. ～がきっかけで/がきっかけになって/をきっかけに（して）/をきっかけとして","blocks":[{"t":"label","label":"接续","text":"动词普通形+の / 名词 + がきっかけで/がきっかけになって/をきっかけに（して）/をきっかけとして","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+の / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + がきっかけで/がきっかけになって/をきっかけに（して）/をきっかけとして"},{"t":"label","label":"说明","text":"“以……为契机、机会”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"恵まれない子どもたちの姿を見たのがきっかけで、この支援活動を始めたのです。（自从看到这些穷苦的孩子们的样子，我就开始了这项援助活动。）","furi":"<ruby>恵<rp>(</rp><rt>めぐ</rt><rp>)</rp></ruby>まれない<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもたちの<ruby>姿<rp>(</rp><rt>すがた</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>たのがきっかけで、この<ruby>支援<rp>(</rp><rt>しえん</rt><rp>)</rp></ruby><ruby>活動<rp>(</rp><rt>かつどう</rt><rp>)</rp></ruby>を<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>めたのです。（自从看到这些穷苦的孩子们的样子，我就开始了这项援助活动。）"},{"t":"line","text":"田中さんは、あるパーティーで友達から一人の女性を紹介された。それをきっかけに、田中さんはその女性と交際を始めたそうだ。（在一次聚会上，朋友给田中介绍了一位女士。据说以此为契机，田中开始和那位女士交往了。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんは、あるパーティーで<ruby>友達<rp>(</rp><rt>ともだち</rt><rp>)</rp></ruby>から<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>の<ruby>女性<rp>(</rp><rt>じょせい</rt><rp>)</rp></ruby>を<ruby>紹介<rp>(</rp><rt>しょうかい</rt><rp>)</rp></ruby>された。それをきっかけに、<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんはその<ruby>女性<rp>(</rp><rt>じょせい</rt><rp>)</rp></ruby>と<ruby>交際<rp>(</rp><rt>こうさい</rt><rp>)</rp></ruby>を<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>めたそうだ。（在一次聚会上，朋友给田中介绍了一位女士。据说以此为契机，田中开始和那位女士交往了。）"}],"id":"N2-8"},{"title":"9. ～限り（は）/限りでは","blocks":[{"t":"label","label":"接续①","text":"动词辞书形/可能形 / 名词+の + 限り","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>可能<rp>(</rp><rt>かのう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + <ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>り"},{"t":"label","label":"说明①","text":"表示最大限度，“尽量……、竭尽……”。","furi":""},{"t":"label","label":"例句①","text":"できる限りの努力はした。あとは結果を待つのみだ。（自己尽了最大的努力，之后就是等待结果了。）","furi":"できる<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りの<ruby>努力<rp>(</rp><rt>どりょく</rt><rp>)</rp></ruby>はした。あとは<ruby>結果<rp>(</rp><rt>けっか</rt><rp>)</rp></ruby>を<ruby>待<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>つのみだ。（自己尽了最大的努力，之后就是等待结果了。）"},{"t":"label","label":"接续②","text":"动词辞书形/た形/ている形 + 限りでは","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りでは"},{"t":"label","label":"说明②","text":"表示在某个限定范围内，“据……所知、据……调查”。","furi":""},{"t":"label","label":"例句②","text":"私の見る限りでは、彼は信頼できる人物だ。（在我看来，他是一个值得信赖的人。）","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>の<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>る<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りでは、<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>信頼<rp>(</rp><rt>しんらい</rt><rp>)</rp></ruby>できる<ruby>人物<rp>(</rp><rt>じんぶつ</rt><rp>)</rp></ruby>だ。（在我看来，他是一个值得信赖的人。）"},{"t":"label","label":"接续③","text":"动词辞书形/ている形 + 限り","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>り"},{"t":"label","label":"说明③","text":"表示条件，“只要……就……”。","furi":""},{"t":"label","label":"例句③","text":"生きている限り、うれしいことも悲しいことも必ずある。（只要活着，就一定会有开心的事情和悲伤的事情。）","furi":"<ruby>生<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きている<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>り、うれしいことも<ruby>悲<rp>(</rp><rt>かな</rt><rp>)</rp></ruby>しいことも<ruby>必<rp>(</rp><rt>かなら</rt><rp>)</rp></ruby>ずある。（只要活着，就一定会有开心的事情和悲伤的事情。）"}],"id":"N2-9"},{"title":"10. ～が契機で/が契機になって/を契機に（して）/を契機として","blocks":[{"t":"label","label":"接续","text":"动词普通形+の / 名词 + が契機で/が契機になって/を契機に（して）/を契機として","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+の / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + が<ruby>契機<rp>(</rp><rt>けいき</rt><rp>)</rp></ruby>で/が<ruby>契機<rp>(</rp><rt>けいき</rt><rp>)</rp></ruby>になって/を<ruby>契機<rp>(</rp><rt>けいき</rt><rp>)</rp></ruby>に（して）/を<ruby>契機<rp>(</rp><rt>けいき</rt><rp>)</rp></ruby>として"},{"t":"label","label":"说明","text":"“以……为契机”，书面语。","furi":""},{"t":"label","label":"例句","text":"数週間の入院生活で、健康の大切さを実感した。これを契機に、もっと健康に気をつけて生活しようと決心した。（通过几个星期的住院生活，我切身体会到了健康的重要性，决定以此为契机，在生活中更加注意健康。）","furi":"<ruby>数<rp>(</rp><rt>すう</rt><rp>)</rp></ruby><ruby>週間<rp>(</rp><rt>しゅうかん</rt><rp>)</rp></ruby>の<ruby>入院<rp>(</rp><rt>にゅういん</rt><rp>)</rp></ruby><ruby>生活<rp>(</rp><rt>せいかつ</rt><rp>)</rp></ruby>で、<ruby>健康<rp>(</rp><rt>けんこう</rt><rp>)</rp></ruby>の<ruby>大切<rp>(</rp><rt>たいせつ</rt><rp>)</rp></ruby>さを<ruby>実感<rp>(</rp><rt>じっかん</rt><rp>)</rp></ruby>した。これを<ruby>契機<rp>(</rp><rt>けいき</rt><rp>)</rp></ruby>に、もっと<ruby>健康<rp>(</rp><rt>けんこう</rt><rp>)</rp></ruby>に<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>をつけて<ruby>生活<rp>(</rp><rt>せいかつ</rt><rp>)</rp></ruby>しようと<ruby>決心<rp>(</rp><rt>けっしん</rt><rp>)</rp></ruby>した。（通过几个星期的住院生活，我切身体会到了健康的重要性，决定以此为契机，在生活中更加注意健康。）"}],"id":"N2-10"},{"title":"11. ～かけだ/かける","blocks":[{"t":"label","label":"接续","text":"动词ます形 + かけだ/かける","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + かけだ/かける"},{"t":"label","label":"说明","text":"表示动作开始后还没有结束，“没……完、……做到一半”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"テーブルの上に食べかけのケーキがおいてある。（桌上放着没吃完的蛋糕。）","furi":"テーブルの<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>に<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べかけのケーキがおいてある。（桌上放着没吃完的蛋糕。）"},{"t":"line","text":"テーブルの上においた読みかけの本を母がかたづけてしまった。（母亲把放在桌上看到一半的书给收起来了。）","furi":"テーブルの<ruby>上<rp>(</rp><rt>うえ</rt><rp>)</rp></ruby>においた<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>みかけの<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>を<ruby>母<rp>(</rp><rt>はは</rt><rp>)</rp></ruby>がかたづけてしまった。（母亲把放在桌上看到一半的书给收起来了。）"},{"t":"line","text":"家の前で死にかけていた野良猫を拾って動物病院に連れていった。（在家门前捡到一只快死的野猫，带它去了动物医院。）","furi":"<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>の<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>で<ruby>死<rp>(</rp><rt>し</rt><rp>)</rp></ruby>にかけていた<ruby>野良猫<rp>(</rp><rt>のらねこ</rt><rp>)</rp></ruby>を<ruby>拾<rp>(</rp><rt>ひろ</rt><rp>)</rp></ruby>って<ruby>動物<rp>(</rp><rt>どうぶつ</rt><rp>)</rp></ruby><ruby>病院<rp>(</rp><rt>びょういん</rt><rp>)</rp></ruby>に<ruby>連<rp>(</rp><rt>つ</rt><rp>)</rp></ruby>れていった。（在家门前捡到一只快死的野猫，带它去了动物医院。）"}],"id":"N2-11"},{"title":"12. ～がちだ","blocks":[{"t":"label","label":"接续","text":"动词ます形/名词 + がちだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + がちだ"},{"t":"label","label":"说明","text":"表示容易发生某种负面事情，“容易……、往往会……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"あの学生は体が弱くて、授業を休みがちだ。（那个学生身体虚弱，经常请假不来上课。）","furi":"あの<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>は<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby>が<ruby>弱<rp>(</rp><rt>よわ</rt><rp>)</rp></ruby>くて、<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby>を<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>みがちだ。（那个学生身体虚弱，经常请假不来上课。）"},{"t":"line","text":"通勤に車を使っているので、運動不足になりがちだ。（开车上下班，很容易导致运动不足。）","furi":"<ruby>通勤<rp>(</rp><rt>つうきん</rt><rp>)</rp></ruby>に<ruby>車<rp>(</rp><rt>くるま</rt><rp>)</rp></ruby>を<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>っているので、<ruby>運動<rp>(</rp><rt>うんどう</rt><rp>)</rp></ruby><ruby>不足<rp>(</rp><rt>ふそく</rt><rp>)</rp></ruby>になりがちだ。（开车上下班，很容易导致运动不足。）"}],"id":"N2-12"},{"title":"13. ～かと思えば","blocks":[{"t":"label","label":"接续①","text":"动词辞书形/た形/名词 + かと思えば","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + かと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>えば"},{"t":"label","label":"说明①","text":"表示后项与预想相反，“原以为……却……”。","furi":""},{"t":"label","label":"例句①","text":"息子は学校から帰ってきたかと思えば、またすぐ遊びに出かけていた。（原以为儿子从学校回来了，却又马上出去玩了。）","furi":"<ruby>息子<rp>(</rp><rt>むすこ</rt><rp>)</rp></ruby>は<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>から<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>ってきたかと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>えば、またすぐ<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>びに<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>かけていた。（原以为儿子从学校回来了，却又马上出去玩了。）"},{"t":"label","label":"接续②","text":"动词辞书形 + かと思えば","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + かと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>えば"},{"t":"label","label":"说明②","text":"表示并列，“既……又……”。","furi":""},{"t":"label","label":"例句②","text":"百歳を越えて生きる人がいるかと思えば、一歳になることもなく、この世を去る赤ん坊もいる。（既有活过百岁的寿星，也有还不到一岁就离开人世的婴儿。）","furi":"<ruby>百<rp>(</rp><rt>ひゃく</rt><rp>)</rp></ruby><ruby>歳<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>を<ruby>越<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>えて<ruby>生<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きる<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>がいるかと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>えば、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>歳<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>になることもなく、この<ruby>世<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>を<ruby>去<rp>(</rp><rt>さ</rt><rp>)</rp></ruby>る<ruby>赤<rp>(</rp><rt>あか</rt><rp>)</rp></ruby>ん<ruby>坊<rp>(</rp><rt>ぼう</rt><rp>)</rp></ruby>もいる。（既有活过百岁的寿星，也有还不到一岁就离开人世的婴儿。）"}],"id":"N2-13"},{"title":"14. ～か～ないかのうちに","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + か + 动词ない形 + ないかのうちに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + か + <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ないかのうちに"},{"t":"label","label":"说明","text":"表示两件事几乎同时发生，“刚……就……、还没……就……”。","furi":""},{"t":"label","label":"例句","text":"ピクニックの日の朝、娘はとてもうれしそうにしていた。「いってきます」と言い終わるか終わらないかのうちに、玄関を飛び出していった。（要去野餐的那天早上，女儿显得非常高兴。刚说完“我走了”，就跑出了大门。）","furi":"ピクニックの<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>の<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>、<ruby>娘<rp>(</rp><rt>むすめ</rt><rp>)</rp></ruby>はとてもうれしそうにしていた。「いってきます」と<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>い<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わるか<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わらないかのうちに、<ruby>玄関<rp>(</rp><rt>げんかん</rt><rp>)</rp></ruby>を<ruby>飛<rp>(</rp><rt>と</rt><rp>)</rp></ruby>び<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>していった。（要去野餐的那天早上，女儿显得非常高兴。刚说完“我走了”，就跑出了大门。）"}],"id":"N2-14"},{"title":"15. ～かねる/かねない","blocks":[{"t":"label","label":"接续①","text":"动词ます形 + かねる","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + かねる"},{"t":"label","label":"说明①","text":"表示难以做某事，“很难……、难以……”。用于礼貌地拒绝。","furi":""},{"t":"label","label":"例句①","text":"労働条件の変更について会社から説明を受けたが、私はどうも納得しかねる。（有关劳动条件的变更虽然已经听取了公司方的说明，但我还是难以接受。）","furi":"<ruby>労働<rp>(</rp><rt>ろうどう</rt><rp>)</rp></ruby><ruby>条件<rp>(</rp><rt>じょうけん</rt><rp>)</rp></ruby>の<ruby>変更<rp>(</rp><rt>へんこう</rt><rp>)</rp></ruby>について<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>から<ruby>説明<rp>(</rp><rt>せつめい</rt><rp>)</rp></ruby>を<ruby>受<rp>(</rp><rt>う</rt><rp>)</rp></ruby>けたが、<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>はどうも<ruby>納得<rp>(</rp><rt>なっとく</rt><rp>)</rp></ruby>しかねる。（有关劳动条件的变更虽然已经听取了公司方的说明，但我还是难以接受。）"},{"t":"label","label":"接续②","text":"动词ます形 + かねない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + かねない"},{"t":"label","label":"说明②","text":"表示有可能（带来负面结果），“有可能……”。","furi":""},{"t":"label","label":"例句②","text":"適度なスポーツは健康にいいといわれるが、やりすぎると体をこわしかねない。（适当的运动有益健康，但是运动过度也可能会损坏身体。）","furi":"<ruby>適度<rp>(</rp><rt>てきど</rt><rp>)</rp></ruby>なスポーツは<ruby>健康<rp>(</rp><rt>けんこう</rt><rp>)</rp></ruby>にいいといわれるが、やりすぎると<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby>をこわしかねない。（适当的运动有益健康，但是运动过度也可能会损坏身体。）"}],"id":"N2-15"},{"title":"16. ～かのようだ","blocks":[{"t":"label","label":"接续","text":"动词普通形 + かのようだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + かのようだ"},{"t":"label","label":"说明","text":"表示比喻，“就像……一样”。","furi":""},{"t":"label","label":"例句","text":"賞をもらったのは弟だというのに、彼女の喜ぶようすは自分が賞をもらったかのようだ。（虽然得奖的是弟弟，但她就像是自己得了奖一样高兴。）","furi":"<ruby>賞<rp>(</rp><rt>しょう</rt><rp>)</rp></ruby>をもらったのは<ruby>弟<rp>(</rp><rt>おとうと</rt><rp>)</rp></ruby>だというのに、<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>の<ruby>喜<rp>(</rp><rt>よろこ</rt><rp>)</rp></ruby>ぶようすは<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>が<ruby>賞<rp>(</rp><rt>しょう</rt><rp>)</rp></ruby>をもらったかのようだ。（虽然得奖的是弟弟，但她就像是自己得了奖一样高兴。）"}],"id":"N2-16"},{"title":"17. ～からいいようなものの","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + からいいようなものの","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + からいいようなものの"},{"t":"label","label":"说明","text":"表示幸好避免了不好的事态，“（因为……）幸好（这次）……”。","furi":""},{"t":"label","label":"例句","text":"この大事な資料が見つかったからいいようなもの、万が一、紛失したらどうするんだ。（幸好找到了这份重要的资料，万一找不到该怎么办。）","furi":"この<ruby>大事<rp>(</rp><rt>だいじ</rt><rp>)</rp></ruby>な<ruby>資料<rp>(</rp><rt>しりょう</rt><rp>)</rp></ruby>が<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>つかったからいいようなもの、<ruby>万<rp>(</rp><rt>まん</rt><rp>)</rp></ruby>が<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby>、<ruby>紛失<rp>(</rp><rt>ふんしつ</rt><rp>)</rp></ruby>したらどうするんだ。（幸好找到了这份重要的资料，万一找不到该怎么办。）"}],"id":"N2-17"},{"title":"18. ～からこそ","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + からこそ","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + からこそ"},{"t":"label","label":"说明","text":"强调原因，“正因为……”。","furi":""},{"t":"label","label":"例句","text":"田中監督が選手たちに厳しくするのは、一度は優勝を経験させたいと願うからこそだ。（田中教练对运动员们很严厉，正是因为想让他们体验一下夺冠的滋味。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby><ruby>監督<rp>(</rp><rt>かんとく</rt><rp>)</rp></ruby>が<ruby>選手<rp>(</rp><rt>せんしゅ</rt><rp>)</rp></ruby>たちに<ruby>厳<rp>(</rp><rt>きび</rt><rp>)</rp></ruby>しくするのは、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>度<rp>(</rp><rt>ど</rt><rp>)</rp></ruby>は<ruby>優勝<rp>(</rp><rt>ゆうしょう</rt><rp>)</rp></ruby>を<ruby>経験<rp>(</rp><rt>けいけん</rt><rp>)</rp></ruby>させたいと<ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>うからこそだ。（田中教练对运动员们很严厉，正是因为想让他们体验一下夺冠的滋味。）"}],"id":"N2-18"},{"title":"19. ～からして","blocks":[{"t":"label","label":"接续","text":"名词 + からして","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + からして"},{"t":"label","label":"说明","text":"表示判断的依据，“单从……来看”。","furi":""},{"t":"label","label":"例句","text":"私は彼のことが大嫌いだ。彼の話し方や服装からして我慢ならない。（我很讨厌他。光是他说话的方式和着装就很受不了。）","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>は<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>のことが<ruby>大嫌<rp>(</rp><rt>だいきら</rt><rp>)</rp></ruby>いだ。<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>し<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>や<ruby>服装<rp>(</rp><rt>ふくそう</rt><rp>)</rp></ruby>からして<ruby>我慢<rp>(</rp><rt>がまん</rt><rp>)</rp></ruby>ならない。（我很讨厌他。光是他说话的方式和着装就很受不了。）"}],"id":"N2-19"},{"title":"20. ～からといって","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + からといって","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + からといって"},{"t":"label","label":"说明","text":"表示转折，认为前项原因不充分，“不能因为……就……、虽说……但是……”。","furi":""},{"t":"label","label":"例句","text":"しばらく連絡がないからといって、そんなに心配することないよ。（虽说有一段时间没有联系了，但是也没必要那么担心。）","furi":"しばらく<ruby>連絡<rp>(</rp><rt>れんらく</rt><rp>)</rp></ruby>がないからといって、そんなに<ruby>心配<rp>(</rp><rt>しんぱい</rt><rp>)</rp></ruby>することないよ。（虽说有一段时间没有联系了，但是也没必要那么担心。）"}],"id":"N2-20"},{"title":"21. ～からには/からは","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+である / 名词+である + からには/からは","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+である / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+である + からには/からは"},{"t":"label","label":"说明","text":"“既然……就……”。","furi":""},{"t":"label","label":"例句","text":"約束したからには、どんなことがあっても守らなければならない。（既然已经约好了，无论发生什么事情都必须要遵守。）","furi":"<ruby>約束<rp>(</rp><rt>やくそく</rt><rp>)</rp></ruby>したからには、どんなことがあっても<ruby>守<rp>(</rp><rt>まも</rt><rp>)</rp></ruby>らなければならない。（既然已经约好了，无论发生什么事情都必须要遵守。）"}],"id":"N2-21"},{"title":"22. ～代わりに","blocks":[{"t":"label","label":"接续①","text":"动词/い形容词/な形容词/名词的修饰形 + 代わりに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>修<rp>(</rp><rt>おさむ</rt><rp>)</rp></ruby><ruby>饰<rp>(</rp><rt>饰</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>代<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わりに"},{"t":"label","label":"说明①","text":"表示代替或交换条件。","furi":""},{"t":"label","label":"例句①","text":"スーツケースを貸す代わりに、食事をごちそうしてもらった。（我借行李箱给他，他请我吃了饭。）","furi":"スーツケースを<ruby>貸<rp>(</rp><rt>か</rt><rp>)</rp></ruby>す<ruby>代<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わりに、<ruby>食事<rp>(</rp><rt>しょくじ</rt><rp>)</rp></ruby>をごちそうしてもらった。（我借行李箱给他，他请我吃了饭。）"},{"t":"label","label":"说明②","text":"表示事物的正反两面，“虽然……但是……”。","furi":""},{"t":"label","label":"例句②","text":"インターネットの普及でさまざまな情報が手に入る代わりに、人とのコミュニケーションが少なくなった。（由于互联网的普及人们可以得到各种各样的信息，但与人的交流却越来越少了。）","furi":"インターネットの<ruby>普及<rp>(</rp><rt>ふきゅう</rt><rp>)</rp></ruby>でさまざまな<ruby>情報<rp>(</rp><rt>じょうほう</rt><rp>)</rp></ruby>が<ruby>手<rp>(</rp><rt>て</rt><rp>)</rp></ruby>に<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>る<ruby>代<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わりに、<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>とのコミュニケーションが<ruby>少<rp>(</rp><rt>すく</rt><rp>)</rp></ruby>なくなった。（由于互联网的普及人们可以得到各种各样的信息，但与人的交流却越来越少了。）"}],"id":"N2-22"},{"title":"23. ～気味","blocks":[{"t":"label","label":"接续","text":"动词ます形/名词 + 気味","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + <ruby>気味<rp>(</rp><rt>きみ</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示倾向，程度较轻，“稍微……、有点儿……”，多用于不好的事情。","furi":""},{"t":"label","label":"例句","text":"このところ忙しくて少し疲れ気味だから、今日は早く帰ることにした。（最近很忙，感觉有点儿累，所以今天早点回去。）","furi":"このところ<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しくて<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>疲<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>れ<ruby>気味<rp>(</rp><rt>ぎみ</rt><rp>)</rp></ruby>だから、<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>は<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>く<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>ることにした。（最近很忙，感觉有点儿累，所以今天早点回去。）"}],"id":"N2-23"},{"title":"24. ～きり/きりだ","blocks":[{"t":"label","label":"接续①","text":"动词辞书形/た形/名词 + きり","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + きり"},{"t":"label","label":"说明①","text":"表示限定，“只有……”。","furi":""},{"t":"label","label":"例句①","text":"一回きりの人生だから、楽しく過ごしたい。（人生只有一次，所以想开心地度过。）","furi":"<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>回<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>きりの<ruby>人生<rp>(</rp><rt>じんせい</rt><rp>)</rp></ruby>だから、<ruby>楽<rp>(</rp><rt>たの</rt><rp>)</rp></ruby>しく<ruby>過<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ごしたい。（人生只有一次，所以想开心地度过。）"},{"t":"label","label":"接续②","text":"动词た形 + きり/きりだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + きり/きりだ"},{"t":"label","label":"说明②","text":"表示前项发生后再无后项，“一……就再没……”。","furi":""},{"t":"label","label":"例句②","text":"本田さんとは20年前に一度会ったきりだ。（与本田自二十年前见过一面之后就再也没有见过。）","furi":"<ruby>本田<rp>(</rp><rt>ほんだ</rt><rp>)</rp></ruby>さんとは20<ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby><ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>に<ruby>一度<rp>(</rp><rt>いちど</rt><rp>)</rp></ruby><ruby>会<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>ったきりだ。（与本田自二十年前见过一面之后就再也没有见过。）"}],"id":"N2-24"},{"title":"25. ～げ","blocks":[{"t":"label","label":"接续","text":"动词ます形 / い形容词词干 / な形容词词干 + げ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + げ"},{"t":"label","label":"说明","text":"表示样态，“像……似的、看上去……”。","furi":""},{"t":"label","label":"例句","text":"彼女は彼の告白に恥ずかしげに「いいよ」と答えた。（对他的告白，她有点害羞地回答“好的”。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>は<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>告白<rp>(</rp><rt>こくはく</rt><rp>)</rp></ruby>に<ruby>恥<rp>(</rp><rt>は</rt><rp>)</rp></ruby>ずかしげに「いいよ」と<ruby>答<rp>(</rp><rt>こた</rt><rp>)</rp></ruby>えた。（对他的告白，她有点害羞地回答“好的”。）"}],"id":"N2-25"},{"title":"26. ～ことから","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+である + ことから","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+である + ことから"},{"t":"label","label":"说明","text":"表示原因或依据，“因为……、从……来看”。","furi":""},{"t":"label","label":"例句","text":"都心では、子どもが少なくなっていることから、学校の数も減りつつある。（在城市，由于儿童的数量在逐渐减少，所以学校的数量也不断减少。）","furi":"<ruby>都心<rp>(</rp><rt>としん</rt><rp>)</rp></ruby>では、<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもが<ruby>少<rp>(</rp><rt>すく</rt><rp>)</rp></ruby>なくなっていることから、<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>の<ruby>数<rp>(</rp><rt>かず</rt><rp>)</rp></ruby>も<ruby>減<rp>(</rp><rt>へ</rt><rp>)</rp></ruby>りつつある。（在城市，由于儿童的数量在逐渐减少，所以学校的数量也不断减少。）"}],"id":"N2-26"},{"title":"27. ～ことだから","blocks":[{"t":"label","label":"接续","text":"名词+の + ことだから","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + ことだから"},{"t":"label","label":"说明","text":"表示判断的依据，“因为是……（这样的人）”。","furi":""},{"t":"label","label":"例句","text":"山田さんはもともと世話好きで、誰に対しても親切だ。そんな彼女のことだから、困っている友達をほうっておけなかったのだろう。（山田本来就是个热心肠的人，对谁都很热情。这样的她，是不会对处于困境的朋友视而不见的吧。）","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby>さんはもともと<ruby>世話好<rp>(</rp><rt>せわず</rt><rp>)</rp></ruby>きで、<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>に<ruby>対<rp>(</rp><rt>たい</rt><rp>)</rp></ruby>しても<ruby>親切<rp>(</rp><rt>しんせつ</rt><rp>)</rp></ruby>だ。そんな<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>のことだから、<ruby>困<rp>(</rp><rt>こま</rt><rp>)</rp></ruby>っている<ruby>友達<rp>(</rp><rt>ともだち</rt><rp>)</rp></ruby>をほうっておけなかったのだろう。（山田本来就是个热心肠的人，对谁都很热情。这样的她，是不会对处于困境的朋友视而不见的吧。）"}],"id":"N2-27"},{"title":"28. ～ことなく/こともなく","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + ことなく/こともなく","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ことなく/こともなく"},{"t":"label","label":"说明","text":"表示否定，“不……”，书面语。","furi":""},{"t":"label","label":"例句","text":"失敗を恐れることなく、行動してほしい。（希望你做事情不要害怕失败。）","furi":"<ruby>失敗<rp>(</rp><rt>しっぱい</rt><rp>)</rp></ruby>を<ruby>恐<rp>(</rp><rt>おそ</rt><rp>)</rp></ruby>れることなく、<ruby>行動<rp>(</rp><rt>こうどう</rt><rp>)</rp></ruby>してほしい。（希望你做事情不要害怕失败。）"}],"id":"N2-28"},{"title":"29. ～ごとに","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词 + ごとに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + ごとに"},{"t":"label","label":"说明","text":"“每……、每当……”。","furi":""},{"t":"label","label":"例句","text":"この目覚まし時計は5分ごとに鳴るように設定されている。（这个闹钟被设定为每隔五分钟响一次。）","furi":"この<ruby>目覚<rp>(</rp><rt>めざ</rt><rp>)</rp></ruby>まし<ruby>時計<rp>(</rp><rt>とけい</rt><rp>)</rp></ruby>は5<ruby>分<rp>(</rp><rt>ふん</rt><rp>)</rp></ruby>ごとに<ruby>鳴<rp>(</rp><rt>な</rt><rp>)</rp></ruby>るように<ruby>設定<rp>(</rp><rt>せってい</rt><rp>)</rp></ruby>されている。（这个闹钟被设定为每隔五分钟响一次。）"}],"id":"N2-29"},{"title":"30. ～ことにはならない","blocks":[{"t":"label","label":"接续","text":"动词た形 + ことにはならない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ことにはならない"},{"t":"label","label":"说明","text":"“不能当作……、不能算作……”。","furi":""},{"t":"label","label":"例句","text":"本やインターネットの資料を写しただけではレポートを書いたことにはならない。（如果只是照抄书本或者网上的资料的话，不能算是写了小论文。）","furi":"<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>やインターネットの<ruby>資料<rp>(</rp><rt>しりょう</rt><rp>)</rp></ruby>を<ruby>写<rp>(</rp><rt>うつ</rt><rp>)</rp></ruby>しただけではレポートを<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いたことにはならない。（如果只是照抄书本或者网上的资料的话，不能算是写了小论文。）"}],"id":"N2-30"},{"title":"31. ～ことは～が","blocks":[{"t":"label","label":"接续","text":"动词/い形容词的修饰形 + ことは + 同一动词/い形容词普通形 + が","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>修<rp>(</rp><rt>おさむ</rt><rp>)</rp></ruby><ruby>饰<rp>(</rp><rt>饰</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ことは + <ruby>同<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + が"},{"t":"label","label":"说明","text":"表示让步，“……是……，但……”。","furi":""},{"t":"label","label":"例句","text":"レポートは最後まで書いたことは書いたんですが、まだ足りない部分もあります。（报告写是写完了，但是还有不足的地方。）","furi":"レポートは<ruby>最後<rp>(</rp><rt>さいご</rt><rp>)</rp></ruby>まで<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いたことは<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>いたんですが、まだ<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>りない<ruby>部分<rp>(</rp><rt>ぶぶん</rt><rp>)</rp></ruby>もあります。（报告写是写完了，但是还有不足的地方。）"}],"id":"N2-31"},{"title":"32. ～際（は）/際に（は）","blocks":[{"t":"label","label":"接续","text":"动词辞书形/た形 / 名词+の + 際（は）/際に（は）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + <ruby>際<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>（は）/<ruby>際<rp>(</rp><rt>ぎわ</rt><rp>)</rp></ruby>に（は）"},{"t":"label","label":"说明","text":"“在……时候、借……时机”。","furi":""},{"t":"label","label":"例句","text":"外出する際は、必ず鍵をかけるようにしてください。（外出的时候请一定把门锁好。）","furi":"<ruby>外出<rp>(</rp><rt>がいしゅつ</rt><rp>)</rp></ruby>する<ruby>際<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>は、<ruby>必<rp>(</rp><rt>かなら</rt><rp>)</rp></ruby>ず<ruby>鍵<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>をかけるようにしてください。（外出的时候请一定把门锁好。）"}],"id":"N2-32"},{"title":"33. ～ざるを得ない","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ざるを得ない（する→せざるを得ない）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ざるを<ruby>得<rp>(</rp><rt>え</rt><rp>)</rp></ruby>ない（する→せざるを<ruby>得<rp>(</rp><rt>え</rt><rp>)</rp></ruby>ない）"},{"t":"label","label":"说明","text":"表示无奈，“不得不……”。书面语。","furi":""},{"t":"label","label":"例句","text":"2回も同じ間違いをするとは、注意が足りなかったと言わざるを得ない。（两次都犯了同样的错误，不得不说是不够注意。）","furi":"2<ruby>回<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>も<ruby>同<rp>(</rp><rt>おな</rt><rp>)</rp></ruby>じ<ruby>間違<rp>(</rp><rt>まちが</rt><rp>)</rp></ruby>いをするとは、<ruby>注意<rp>(</rp><rt>ちゅうい</rt><rp>)</rp></ruby>が<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>りなかったと<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>わざるを<ruby>得<rp>(</rp><rt>え</rt><rp>)</rp></ruby>ない。（两次都犯了同样的错误，不得不说是不够注意。）"}],"id":"N2-33"},{"title":"34. ～次第/次第だ/次第で（は）","blocks":[{"t":"label","label":"接续①","text":"动词ます形 + 次第","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>次第<rp>(</rp><rt>しだい</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明①","text":"表示前项一发生就做后项，“……之后立刻……”。","furi":""},{"t":"label","label":"例句①","text":"田中は出かけておりますので、戻り次第ご連絡をさしあげます。（田中外出了，他一回来我就让他联系您。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>は<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>かけておりますので、<ruby>戻<rp>(</rp><rt>もど</rt><rp>)</rp></ruby>り<ruby>次第<rp>(</rp><rt>しだい</rt><rp>)</rp></ruby>ご<ruby>連絡<rp>(</rp><rt>れんらく</rt><rp>)</rp></ruby>をさしあげます。（田中外出了，他一回来我就让他联系您。）"},{"t":"label","label":"接续②","text":"动词/い形容词/な形容词的修饰形 + 次第だ/次第で","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>修<rp>(</rp><rt>おさむ</rt><rp>)</rp></ruby><ruby>饰<rp>(</rp><rt>饰</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>次第<rp>(</rp><rt>しだい</rt><rp>)</rp></ruby>だ/<ruby>次第<rp>(</rp><rt>しだい</rt><rp>)</rp></ruby>で"},{"t":"label","label":"说明②","text":"表示原委、情况，“……就是……”。","furi":""},{"t":"label","label":"例句②","text":"先日お伝えした日程に誤りがありましたので、今回、改めてご連絡を差し上げた次第です。（由于前几天与您说的日期有误，所以现在再次和您联系。）","furi":"<ruby>先日<rp>(</rp><rt>せんじつ</rt><rp>)</rp></ruby>お<ruby>伝<rp>(</rp><rt>つた</rt><rp>)</rp></ruby>えした<ruby>日程<rp>(</rp><rt>にってい</rt><rp>)</rp></ruby>に<ruby>誤<rp>(</rp><rt>あやま</rt><rp>)</rp></ruby>りがありましたので、<ruby>今回<rp>(</rp><rt>こんかい</rt><rp>)</rp></ruby>、<ruby>改<rp>(</rp><rt>あらた</rt><rp>)</rp></ruby>めてご<ruby>連絡<rp>(</rp><rt>れんらく</rt><rp>)</rp></ruby>を<ruby>差<rp>(</rp><rt>さ</rt><rp>)</rp></ruby>し<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>げた<ruby>次第<rp>(</rp><rt>しだい</rt><rp>)</rp></ruby>です。（由于前几天与您说的日期有误，所以现在再次和您联系。）"},{"t":"label","label":"接续③","text":"名词 + 次第だ/次第で（は）","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + <ruby>次第<rp>(</rp><rt>しだい</rt><rp>)</rp></ruby>だ/<ruby>次第<rp>(</rp><rt>しだい</rt><rp>)</rp></ruby>で（は）"},{"t":"label","label":"说明③","text":"表示取决于，“……取决于……”。","furi":""},{"t":"label","label":"例句③","text":"あしたハイキングに行くかどうかは、お天気次第だ。（明天去不去郊游取决于天气。）","furi":"あしたハイキングに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くかどうかは、お<ruby>天気<rp>(</rp><rt>てんき</rt><rp>)</rp></ruby><ruby>次第<rp>(</rp><rt>しだい</rt><rp>)</rp></ruby>だ。（明天去不去郊游取决于天气。）"}],"id":"N2-34"},{"title":"35. ～末（に）","blocks":[{"t":"label","label":"接续","text":"动词た形 / 名词+の + 末（に）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + <ruby>末<rp>(</rp><rt>すえ</rt><rp>)</rp></ruby>（に）"},{"t":"label","label":"说明","text":"表示经过一个过程后得到的结果，“经过……最后……”。","furi":""},{"t":"label","label":"例句","text":"あれこれ悩んだ末に、ABC大学を志望校に決めた。（烦恼了许久，最终决定将ABC大学作为志愿填报的学校。）","furi":"あれこれ<ruby>悩<rp>(</rp><rt>なや</rt><rp>)</rp></ruby>んだ<ruby>末<rp>(</rp><rt>すえ</rt><rp>)</rp></ruby>に、ABC<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>を<ruby>志望校<rp>(</rp><rt>しぼうこう</rt><rp>)</rp></ruby>に<ruby>決<rp>(</rp><rt>き</rt><rp>)</rp></ruby>めた。（烦恼了许久，最终决定将ABC大学作为志愿填报的学校。）"}],"id":"N2-35"},{"title":"36. ～ずにすむ/ないですむ/なくてすむ","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ずにすむ/ないですむ/なくてすむ（する→せずにすむ）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ずにすむ/ないですむ/なくてすむ（する→せずにすむ）"},{"t":"label","label":"说明","text":"“不……（也可以解决）、不用……就可以了”。","furi":""},{"t":"label","label":"例句","text":"今朝乗っていた電車が一時運転見合わせになったけど、早めに家を出たので遅刻せずにすんだ。（今天早上乘的电车停止运行了一段时间，但因为提早出了门，所以没有迟到。）","furi":"<ruby>今朝<rp>(</rp><rt>けさ</rt><rp>)</rp></ruby><ruby>乗<rp>(</rp><rt>の</rt><rp>)</rp></ruby>っていた<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>が<ruby>一時<rp>(</rp><rt>いちじ</rt><rp>)</rp></ruby><ruby>運転<rp>(</rp><rt>うんてん</rt><rp>)</rp></ruby><ruby>見合<rp>(</rp><rt>みあ</rt><rp>)</rp></ruby>わせになったけど、<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>めに<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>たので<ruby>遅刻<rp>(</rp><rt>ちこく</rt><rp>)</rp></ruby>せずにすんだ。（今天早上乘的电车停止运行了一段时间，但因为提早出了门，所以没有迟到。）"}],"id":"N2-36"},{"title":"37. ～ずにはいられない/ないではいられない","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ずにはいられない/ないではいられない（する→せずにはいられない）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ずにはいられない/ないではいられない（する→せずにはいられない）"},{"t":"label","label":"说明","text":"表示忍不住做某事，“不得不……、不能不……”。","furi":""},{"t":"label","label":"例句","text":"お世話になった先生が突然入院されたと聞いて、私は心配で病院に行かずにはいられなかった。（听到关照过我的老师突然住院的消息，很是担心，忍不住要去看他。）","furi":"お<ruby>世話<rp>(</rp><rt>せわ</rt><rp>)</rp></ruby>になった<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>が<ruby>突然<rp>(</rp><rt>とつぜん</rt><rp>)</rp></ruby><ruby>入院<rp>(</rp><rt>にゅういん</rt><rp>)</rp></ruby>されたと<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>いて、<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>は<ruby>心配<rp>(</rp><rt>しんぱい</rt><rp>)</rp></ruby>で<ruby>病院<rp>(</rp><rt>びょういん</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>かずにはいられなかった。（听到关照过我的老师突然住院的消息，很是担心，忍不住要去看他。）"}],"id":"N2-37"},{"title":"38. ～たいばかりに/ほしいばかりに","blocks":[{"t":"label","label":"接续","text":"动词ます形 + たいばかりに / 名词+が + ほしいばかりに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + たいばかりに / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+が + ほしいばかりに"},{"t":"label","label":"说明","text":"表示原因，“就是因为想……”。","furi":""},{"t":"label","label":"例句","text":"ブランドバッグを手に入れたいばかりに、夏休みは一生懸命アルバイトをした。（就是因为想买名牌包，暑假才拼命打工的。）","furi":"ブランドバッグを<ruby>手<rp>(</rp><rt>て</rt><rp>)</rp></ruby>に<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>れたいばかりに、<ruby>夏休<rp>(</rp><rt>なつやす</rt><rp>)</rp></ruby>みは<ruby>一生懸命<rp>(</rp><rt>いっしょうけんめい</rt><rp>)</rp></ruby>アルバイトをした。（就是因为想买名牌包，暑假才拼命打工的。）"}],"id":"N2-38"},{"title":"39. ～だけ/だけあって/だけに/だけのことはある","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词 + だけ/だけあって/だけに/だけのことはある","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + だけ/だけあって/だけに/だけのことはある"},{"t":"label","label":"说明①","text":"表示与身份、地位相称，“不愧是……、到底没白……”。","furi":""},{"t":"label","label":"例句①","text":"多くの観光客が訪れるだけあって、確かに山からの眺めはすばらしかった。（这里不愧是游客云集的地方，从山上眺望的景色的确很美。）","furi":"<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>くの<ruby>観光<rp>(</rp><rt>かんこう</rt><rp>)</rp></ruby><ruby>客<rp>(</rp><rt>きゃく</rt><rp>)</rp></ruby>が<ruby>訪<rp>(</rp><rt>おとず</rt><rp>)</rp></ruby>れるだけあって、<ruby>確<rp>(</rp><rt>たし</rt><rp>)</rp></ruby>かに<ruby>山<rp>(</rp><rt>やま</rt><rp>)</rp></ruby>からの<ruby>眺<rp>(</rp><rt>なが</rt><rp>)</rp></ruby>めはすばらしかった。（这里不愧是游客云集的地方，从山上眺望的景色的确很美。）"},{"t":"label","label":"说明②","text":"表示正因为前项而更加，“正因为……更加……”。","furi":""},{"t":"label","label":"例句②","text":"妹はもともと体が弱いだけに、風邪を引いても心配だ。（正因为妹妹身体本来就很虚弱，所以就算是感冒也让人担心。）","furi":"<ruby>妹<rp>(</rp><rt>いもうと</rt><rp>)</rp></ruby>はもともと<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby>が<ruby>弱<rp>(</rp><rt>よわ</rt><rp>)</rp></ruby>いだけに、<ruby>風邪<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>を<ruby>引<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>いても<ruby>心配<rp>(</rp><rt>しんぱい</rt><rp>)</rp></ruby>だ。（正因为妹妹身体本来就很虚弱，所以就算是感冒也让人担心。）"},{"t":"label","label":"说明③","text":"表示正因为前项反而更加，“正因为……反倒……”。","furi":""},{"t":"label","label":"例句③","text":"優勝することを期待していただけに、負けたときの失望は大きかった。（正因为一直很期待取得胜利，所以失败时非常失望。）","furi":"<ruby>優勝<rp>(</rp><rt>ゆうしょう</rt><rp>)</rp></ruby>することを<ruby>期待<rp>(</rp><rt>きたい</rt><rp>)</rp></ruby>していただけに、<ruby>負<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>けたときの<ruby>失望<rp>(</rp><rt>しつぼう</rt><rp>)</rp></ruby>は<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きかった。（正因为一直很期待取得胜利，所以失败时非常失望。）"}],"id":"N2-39"},{"title":"40. ～たところ","blocks":[{"t":"label","label":"接续","text":"动词た形 + ところ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところ"},{"t":"label","label":"说明","text":"表示做了前项后发生或发现了后项。","furi":""},{"t":"label","label":"例句","text":"仕事の合間にときどき遠くを見るようにしたところ、目が疲れにくくなった。（工作的间隙有时会望望远处，这样眼睛就不容易疲劳了。）","furi":"<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>の<ruby>合間<rp>(</rp><rt>あいま</rt><rp>)</rp></ruby>にときどき<ruby>遠<rp>(</rp><rt>とお</rt><rp>)</rp></ruby>くを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>るようにしたところ、<ruby>目<rp>(</rp><rt>め</rt><rp>)</rp></ruby>が<ruby>疲<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>れにくくなった。（工作的间隙有时会望望远处，这样眼睛就不容易疲劳了。）"}],"id":"N2-40"},{"title":"41. ～たところが","blocks":[{"t":"label","label":"接续","text":"动词た形 + ところが","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところが"},{"t":"label","label":"说明","text":"表示逆接，“然而……、虽然……可是……”。","furi":""},{"t":"label","label":"例句","text":"田中さんならわかるだろうと思って聞いてみたところが、彼にもわからないという。（我想田中大概会知道的，就问了问，可他说他也不知道。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんならわかるだろうと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>って<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>いてみたところが、<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>にもわからないという。（我想田中大概会知道的，就问了问，可他说他也不知道。）"}],"id":"N2-41"},{"title":"42. ～たところで","blocks":[{"t":"label","label":"接续","text":"动词た形 + ところで","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところで"},{"t":"label","label":"说明","text":"表示逆接，“即使……也……”。","furi":""},{"t":"label","label":"例句","text":"どんなに一生懸命働いたところで、生活は楽にならないだろう。（再怎么拼命工作，生活也不会变得轻松的吧。）","furi":"どんなに<ruby>一生懸命<rp>(</rp><rt>いっしょうけんめい</rt><rp>)</rp></ruby><ruby>働<rp>(</rp><rt>はたら</rt><rp>)</rp></ruby>いたところで、<ruby>生活<rp>(</rp><rt>せいかつ</rt><rp>)</rp></ruby>は<ruby>楽<rp>(</rp><rt>らく</rt><rp>)</rp></ruby>にならないだろう。（再怎么拼命工作，生活也不会变得轻松的吧。）"}],"id":"N2-42"},{"title":"43. ～たとたん（に）","blocks":[{"t":"label","label":"接续","text":"动词た形 + とたん（に）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + とたん（に）"},{"t":"label","label":"说明","text":"“一……就……、刚……就……”。后项多为意料之外。","furi":""},{"t":"label","label":"例句","text":"国から来た手紙を見たとたん、彼女は泣き出してしまった。（她一看到从老家寄来的信，就哭起来了。）","furi":"<ruby>国<rp>(</rp><rt>くに</rt><rp>)</rp></ruby>から<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>た<ruby>手紙<rp>(</rp><rt>てがみ</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>たとたん、<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>は<ruby>泣<rp>(</rp><rt>な</rt><rp>)</rp></ruby>き<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>してしまった。（她一看到从老家寄来的信，就哭起来了。）"}],"id":"N2-43"},{"title":"44. ～ついでに","blocks":[{"t":"label","label":"接续","text":"动词辞书形/た形 / 名词+の + ついでに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + ついでに"},{"t":"label","label":"说明","text":"“顺便……”。","furi":""},{"t":"label","label":"例句","text":"展覧会に行ったついでに近くの公園をぶらぶら散歩してきた。（去展览会时顺便去附近的公园悠闲地散了会儿步。）","furi":"<ruby>展覧<rp>(</rp><rt>てんらん</rt><rp>)</rp></ruby><ruby>会<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったついでに<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>くの<ruby>公園<rp>(</rp><rt>こうえん</rt><rp>)</rp></ruby>をぶらぶら<ruby>散歩<rp>(</rp><rt>さんぽ</rt><rp>)</rp></ruby>してきた。（去展览会时顺便去附近的公园悠闲地散了会儿步。）"}],"id":"N2-44"},{"title":"45. ～っこない","blocks":[{"t":"label","label":"接续","text":"动词ます形 + っこない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + っこない"},{"t":"label","label":"说明","text":"表示强烈否定，“不可能……”。口语。","furi":""},{"t":"label","label":"例句","text":"こんな弱い選手ばかりでは、次の試合に勝てっこない。（尽是这些实力很弱的选手的话，下次比赛不可能赢。）","furi":"こんな<ruby>弱<rp>(</rp><rt>よわ</rt><rp>)</rp></ruby>い<ruby>選手<rp>(</rp><rt>せんしゅ</rt><rp>)</rp></ruby>ばかりでは、<ruby>次<rp>(</rp><rt>つぎ</rt><rp>)</rp></ruby>の<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>に<ruby>勝<rp>(</rp><rt>かち</rt><rp>)</rp></ruby>てっこない。（尽是这些实力很弱的选手的话，下次比赛不可能赢。）"}],"id":"N2-45"},{"title":"46. ～つつ（も）","blocks":[{"t":"label","label":"接续①","text":"动词ます形 + つつ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + つつ"},{"t":"label","label":"说明①","text":"表示两个动作同时进行，“一边……一边……”。书面语。","furi":""},{"t":"label","label":"例句①","text":"辞書を引きつつ英字新聞を読んでいる。（一边查字典一边看英文报纸。）","furi":"<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>を<ruby>引<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>きつつ<ruby>英字<rp>(</rp><rt>えいじ</rt><rp>)</rp></ruby><ruby>新聞<rp>(</rp><rt>しんぶん</rt><rp>)</rp></ruby>を<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>んでいる。（一边查字典一边看英文报纸。）"},{"t":"label","label":"接续②","text":"动词ます形 + つつ（も）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + つつ（も）"},{"t":"label","label":"说明②","text":"表示逆接，“虽然……但是……”。","furi":""},{"t":"label","label":"例句②","text":"タバコは体に悪いと知りつつも、つい吸ってしまう。（虽然知道抽烟对身体不好，但还是忍不住去抽。）","furi":"タバコは<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby>に<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>いと<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>りつつも、つい<ruby>吸<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ってしまう。（虽然知道抽烟对身体不好，但还是忍不住去抽。）"}],"id":"N2-46"},{"title":"47. ～つつある","blocks":[{"t":"label","label":"接续","text":"动词ます形 + つつある","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + つつある"},{"t":"label","label":"说明","text":"“正在……、逐渐……”。","furi":""},{"t":"label","label":"例句","text":"環境問題への関心が高くなり、車ではなく電車を利用する人が増えつつある。（对环境越来越关心，不开车而去乘电车的人在不断增加。）","furi":"<ruby>環境<rp>(</rp><rt>かんきょう</rt><rp>)</rp></ruby><ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>への<ruby>関心<rp>(</rp><rt>かんしん</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>くなり、<ruby>車<rp>(</rp><rt>くるま</rt><rp>)</rp></ruby>ではなく<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>を<ruby>利用<rp>(</rp><rt>りよう</rt><rp>)</rp></ruby>する<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>増<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>えつつある。（对环境越来越关心，不开车而去乘电车的人在不断增加。）"}],"id":"N2-47"},{"title":"48. ～っぱなし","blocks":[{"t":"label","label":"接续","text":"动词ます形 + っぱなし","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + っぱなし"},{"t":"label","label":"说明①","text":"接他动词，表示做了某事不去做后续，“放任不管……”。","furi":""},{"t":"label","label":"例句①","text":"水を出しっぱなしにして、歯を磨くのはもったいないですよ。（刷牙的时候一直开着水龙头的话很浪费水。）","furi":"<ruby>水<rp>(</rp><rt>みず</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>しっぱなしにして、<ruby>歯<rp>(</rp><rt>は</rt><rp>)</rp></ruby>を<ruby>磨<rp>(</rp><rt>みが</rt><rp>)</rp></ruby>くのはもったいないですよ。（刷牙的时候一直开着水龙头的话很浪费水。）"},{"t":"label","label":"说明②","text":"接自动词，表示状态持续，“一直……”。","furi":""},{"t":"label","label":"例句②","text":"電車の中はあいにく空席がなくて、ずっと立ちっぱなしだった。（刚好没有空位置，所以在电车中一直站着。）","furi":"<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>の<ruby>中<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>はあいにく<ruby>空席<rp>(</rp><rt>くうせき</rt><rp>)</rp></ruby>がなくて、ずっと<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>ちっぱなしだった。（刚好没有空位置，所以在电车中一直站着。）"}],"id":"N2-48"},{"title":"49. ～っぽい","blocks":[{"t":"label","label":"接续","text":"动词ます形 / い形容词词干 / 名词 + っぽい","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + っぽい"},{"t":"label","label":"说明","text":"表示有某种感觉或倾向，“看上去……、容易……”。","furi":""},{"t":"label","label":"例句","text":"大人のくせに、そんなつまらないことでけんかするのは子どもっぽい。（明明是大人了，却为了那么无聊的事情大发脾气，真是很孩子气。）","furi":"<ruby>大人<rp>(</rp><rt>おとな</rt><rp>)</rp></ruby>のくせに、そんなつまらないことでけんかするのは<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもっぽい。（明明是大人了，却为了那么无聊的事情大发脾气，真是很孩子气。）"}],"id":"N2-49"},{"title":"50. ～てからでないと/てからでなければ","blocks":[{"t":"label","label":"接续","text":"动词て形 + からでないと/からでなければ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + からでないと/からでなければ"},{"t":"label","label":"说明","text":"表示前项是后项的前提条件，“如果不先……就……”。","furi":""},{"t":"label","label":"例句","text":"今日の宿題が終わってからでないと、遊びにいけない。（如果不先把今天的作业做完的话，就不能去玩。）","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>の<ruby>宿題<rp>(</rp><rt>しゅくだい</rt><rp>)</rp></ruby>が<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わってからでないと、<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>びにいけない。（如果不先把今天的作业做完的话，就不能去玩。）"}],"id":"N2-50"},{"title":"51. ～てでも","blocks":[{"t":"label","label":"接续","text":"动词て形 + でも","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + でも"},{"t":"label","label":"说明","text":"表示采取强硬手段，“就是……也要……”。","furi":""},{"t":"label","label":"例句","text":"大企業の社長という地位を捨ててでも、私にはやりたいことがある。（就算是舍弃大公司社长的地位，我也有我想做的事情。）","furi":"<ruby>大<rp>(</rp><rt>だい</rt><rp>)</rp></ruby><ruby>企業<rp>(</rp><rt>きぎょう</rt><rp>)</rp></ruby>の<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>という<ruby>地位<rp>(</rp><rt>ちい</rt><rp>)</rp></ruby>を<ruby>捨<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ててでも、<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>にはやりたいことがある。（就算是舍弃大公司社长的地位，我也有我想做的事情。）"}],"id":"N2-51"},{"title":"52. ～（の）ではあるまいか","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形+の / な形容词词干/名词+なの + ではあるまいか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+の / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+なの + ではあるまいか"},{"t":"label","label":"说明","text":"表示委婉的主张，“不是……吗、难道不是……吗”。","furi":""},{"t":"label","label":"例句","text":"彼は最初から何もかも全部わかっていたのではあるまいか。（他是不是一开始就知道所有的事情啊？）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>最初<rp>(</rp><rt>さいしょ</rt><rp>)</rp></ruby>から<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>もかも<ruby>全部<rp>(</rp><rt>ぜんぶ</rt><rp>)</rp></ruby>わかっていたのではあるまいか。（他是不是一开始就知道所有的事情啊？）"}],"id":"N2-52"},{"title":"53. ～てはいられない","blocks":[{"t":"label","label":"接续","text":"动词て形 + はいられない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + はいられない"},{"t":"label","label":"说明","text":"表示不能再维持现状，“不能……”。","furi":""},{"t":"label","label":"例句","text":"事の真相を知った以上、もう黙ってはいられない。（既然知道了真相，就不能再沉默下去了。）","furi":"<ruby>事<rp>(</rp><rt>こと</rt><rp>)</rp></ruby>の<ruby>真相<rp>(</rp><rt>しんそう</rt><rp>)</rp></ruby>を<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>った<ruby>以上<rp>(</rp><rt>いじょう</rt><rp>)</rp></ruby>、もう<ruby>黙<rp>(</rp><rt>だま</rt><rp>)</rp></ruby>ってはいられない。（既然知道了真相，就不能再沉默下去了。）"}],"id":"N2-53"},{"title":"54. ～てばかりはいられない/てばかりもいられない","blocks":[{"t":"label","label":"接续","text":"动词て形 + ばかりはいられない/ばかりもいられない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ばかりはいられない/ばかりもいられない"},{"t":"label","label":"说明","text":"表示不能总是那样，“（也）不能总是……”。","furi":""},{"t":"label","label":"例句","text":"どんなに辛くても、泣いてばかりもいられない。もっと強く生きていかなければならない。（无论多痛苦，也不能总是哭，必须要更坚强地活下去。）","furi":"どんなに<ruby>辛<rp>(</rp><rt>つら</rt><rp>)</rp></ruby>くても、<ruby>泣<rp>(</rp><rt>な</rt><rp>)</rp></ruby>いてばかりもいられない。もっと<ruby>強<rp>(</rp><rt>つよ</rt><rp>)</rp></ruby>く<ruby>生<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きていかなければならない。（无论多痛苦，也不能总是哭，必须要更坚强地活下去。）"}],"id":"N2-54"},{"title":"55. ～てはじめて","blocks":[{"t":"label","label":"接续","text":"动词て形 + はじめて","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + はじめて"},{"t":"label","label":"说明","text":"“在……之后才……”。","furi":""},{"t":"label","label":"例句","text":"外国で生活をしてはじめて自分の国の良さがわかった。（在国外生活之后才明白自己国家的好处。）","furi":"<ruby>外国<rp>(</rp><rt>がいこく</rt><rp>)</rp></ruby>で<ruby>生活<rp>(</rp><rt>せいかつ</rt><rp>)</rp></ruby>をしてはじめて<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>の<ruby>国<rp>(</rp><rt>くに</rt><rp>)</rp></ruby>の<ruby>良<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>さがわかった。（在国外生活之后才明白自己国家的好处。）"}],"id":"N2-55"},{"title":"56. ～ではすまされない","blocks":[{"t":"label","label":"接续","text":"名词 / 动词普通形+の + ではすまされない","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> / <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+の + ではすまされない"},{"t":"label","label":"说明","text":"表示某事是不能被允许的，“如果……的话是不行的”。","furi":""},{"t":"label","label":"例句","text":"課長である以上、そんな大事なことを知らなかったではすまされないだろう。（作为课长，出了这么大的事情却不知道怎么行呢？）","furi":"<ruby>課長<rp>(</rp><rt>かちょう</rt><rp>)</rp></ruby>である<ruby>以上<rp>(</rp><rt>いじょう</rt><rp>)</rp></ruby>、そんな<ruby>大事<rp>(</rp><rt>だいじ</rt><rp>)</rp></ruby>なことを<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>らなかったではすまされないだろう。（作为课长，出了这么大的事情却不知道怎么行呢？）"}],"id":"N2-56"},{"title":"57. ～てまで","blocks":[{"t":"label","label":"接续","text":"动词て形 + まで","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + まで"},{"t":"label","label":"说明","text":"表示程度，“甚至不惜……”。","furi":""},{"t":"label","label":"例句","text":"借金してまで遊びに行ったと聞いて、あきれてしまった。（听说甚至不惜借钱出去玩，我真的是无语了。）","furi":"<ruby>借金<rp>(</rp><rt>しゃっきん</rt><rp>)</rp></ruby>してまで<ruby>遊<rp>(</rp><rt>あそ</rt><rp>)</rp></ruby>びに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったと<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>いて、あきれてしまった。（听说甚至不惜借钱出去玩，我真的是无语了。）"}],"id":"N2-57"},{"title":"58. ～ということだ（结论/传闻）","blocks":[{"t":"label","label":"接续①","text":"句子的普通形 + ということだ","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ということだ"},{"t":"label","label":"说明①","text":"表示根据事实得出的结论，“就是说……、也就是说……”。","furi":""},{"t":"label","label":"例句①","text":"父はまだ海外出張から帰ってきていない。つまり今日の私の卒業式には参加できないということだ。（爸爸去国外出差还没有回来，也就是说不能参加我今天的毕业典礼了。）","furi":"<ruby>父<rp>(</rp><rt>ちち</rt><rp>)</rp></ruby>はまだ<ruby>海外<rp>(</rp><rt>かいがい</rt><rp>)</rp></ruby><ruby>出張<rp>(</rp><rt>しゅっちょう</rt><rp>)</rp></ruby>から<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>ってきていない。つまり<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>の<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>の<ruby>卒業<rp>(</rp><rt>そつぎょう</rt><rp>)</rp></ruby><ruby>式<rp>(</rp><rt>しき</rt><rp>)</rp></ruby>には<ruby>参加<rp>(</rp><rt>さんか</rt><rp>)</rp></ruby>できないということだ。（爸爸去国外出差还没有回来，也就是说不能参加我今天的毕业典礼了。）"},{"t":"label","label":"接续②","text":"句子的普通形 + ということだ","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ということだ"},{"t":"label","label":"说明②","text":"表示传闻，“听说……”。","furi":""},{"t":"label","label":"例句②","text":"コーチの話では、彼が試合に出れば、優勝は間違いないということだ。（听教练说，如果他参加比赛的话，肯定会赢。）","furi":"コーチの<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>では、<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>が<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>に<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>れば、<ruby>優勝<rp>(</rp><rt>ゆうしょう</rt><rp>)</rp></ruby>は<ruby>間違<rp>(</rp><rt>まちが</rt><rp>)</rp></ruby>いないということだ。（听教练说，如果他参加比赛的话，肯定会赢。）"}],"id":"N2-58"},{"title":"59. ～というものだ","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干/名词 + というものだ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + というものだ"},{"t":"label","label":"说明","text":"表示对事物的本质特征进行评价，“也就是……、这就是所谓的……”。","furi":""},{"t":"label","label":"例句","text":"相手の話も聞かずに自分の主張だけ通そうとするなんて、それはわがままというものだ。（不听对方说的话只想一味坚持自己的主张，这正是任性。）","furi":"<ruby>相手<rp>(</rp><rt>あいて</rt><rp>)</rp></ruby>の<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>も<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>かずに<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>の<ruby>主張<rp>(</rp><rt>しゅちょう</rt><rp>)</rp></ruby>だけ<ruby>通<rp>(</rp><rt>とお</rt><rp>)</rp></ruby>そうとするなんて、それはわがままというものだ。（不听对方说的话只想一味坚持自己的主张，这正是任性。）"}],"id":"N2-59"},{"title":"60. ～というものではない/というものでもない","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + というものではない/というものでもない","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + というものではない/というものでもない"},{"t":"label","label":"说明","text":"表示否定，“并非……”。","furi":""},{"t":"label","label":"例句","text":"勝負は勝てばよいというものではない。どんな勝ち方をしたのかが重要である。（说到胜负，并不是取得胜利了就好。以什么方法取得胜利是很重要的。）","furi":"<ruby>勝負<rp>(</rp><rt>しょうぶ</rt><rp>)</rp></ruby>は<ruby>勝<rp>(</rp><rt>か</rt><rp>)</rp></ruby>てばよいというものではない。どんな<ruby>勝<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ち<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>をしたのかが<ruby>重要<rp>(</rp><rt>じゅうよう</rt><rp>)</rp></ruby>である。（说到胜负，并不是取得胜利了就好。以什么方法取得胜利是很重要的。）"}],"id":"N2-60"},{"title":"61. ～というより","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干/名词 + というより","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + というより"},{"t":"label","label":"说明","text":"“与其说……，还不如说……”。","furi":""},{"t":"label","label":"例句","text":"駅から家までバスに乗らずに歩くのは、節約というより健康のためだ。（从车站到家里这段路，不乘巴士而是步行，与其说是为了省钱，不如说是为了健康。）","furi":"<ruby>駅<rp>(</rp><rt>えき</rt><rp>)</rp></ruby>から<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>までバスに<ruby>乗<rp>(</rp><rt>の</rt><rp>)</rp></ruby>らずに<ruby>歩<rp>(</rp><rt>ある</rt><rp>)</rp></ruby>くのは、<ruby>節約<rp>(</rp><rt>せつやく</rt><rp>)</rp></ruby>というより<ruby>健康<rp>(</rp><rt>けんこう</rt><rp>)</rp></ruby>のためだ。（从车站到家里这段路，不乘巴士而是步行，与其说是为了省钱，不如说是为了健康。）"}],"id":"N2-61"},{"title":"62. ～といっても過言ではない/といっても言い過ぎではない","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + といっても過言ではない/といっても言い過ぎではない","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + といっても<ruby>過言<rp>(</rp><rt>かごん</rt><rp>)</rp></ruby>ではない/といっても<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>い<ruby>過<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ぎではない"},{"t":"label","label":"说明","text":"表示评价，“即便……说也不为过”。","furi":""},{"t":"label","label":"例句","text":"山田監督は私の恩人です。今の私があるのも山田監督あってのことだといっても過言ではありません。（山田导演是我的恩人，可以说多亏有山田导演才有今天的我。）","furi":"<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby><ruby>監督<rp>(</rp><rt>かんとく</rt><rp>)</rp></ruby>は<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>の<ruby>恩人<rp>(</rp><rt>おんじん</rt><rp>)</rp></ruby>です。<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>の<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>があるのも<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby><ruby>監督<rp>(</rp><rt>かんとく</rt><rp>)</rp></ruby>あってのことだといっても<ruby>過言<rp>(</rp><rt>かごん</rt><rp>)</rp></ruby>ではありません。（山田导演是我的恩人，可以说多亏有山田导演才有今天的我。）"}],"id":"N2-62"},{"title":"63. ～（か）と思うと/（か）と思ったら","blocks":[{"t":"label","label":"接续①","text":"动词た形 + （か）と思うと/（か）と思ったら","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + （か）と<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>うと/（か）と<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>ったら"},{"t":"label","label":"说明①","text":"表示几乎同时发生，“刚……就……”。","furi":""},{"t":"label","label":"例句①","text":"息子は、朝学校に行く際に、必ずと言っていいほど忘れ物をしている。出かけたかと思うとすぐ忘れ物を取りに帰ってくる。（儿子早上去学校的时候，总是丢三落四。刚一出门就又返回来拿落下的东西。）","furi":"<ruby>息子<rp>(</rp><rt>むすこ</rt><rp>)</rp></ruby>は、<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby><ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>く<ruby>際<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>に、<ruby>必<rp>(</rp><rt>かなら</rt><rp>)</rp></ruby>ずと<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>っていいほど<ruby>忘<rp>(</rp><rt>わす</rt><rp>)</rp></ruby>れ<ruby>物<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>をしている。<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>かけたかと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>うとすぐ<ruby>忘<rp>(</rp><rt>わす</rt><rp>)</rp></ruby>れ<ruby>物<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>を<ruby>取<rp>(</rp><rt>と</rt><rp>)</rp></ruby>りに<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>ってくる。（儿子早上去学校的时候，总是丢三落四。刚一出门就又返回来拿落下的东西。）"},{"t":"label","label":"接续②","text":"动词辞书形/た形 + （か）と思うと/（か）と思ったら","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + （か）と<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>うと/（か）と<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>ったら"},{"t":"label","label":"说明②","text":"表示与预想相反，“原以为……却……”。","furi":""},{"t":"label","label":"例句②","text":"やっと仕事が終わったと思ったら、また新しい仕事を頼まれた。（原以为工作终于结束了，可又被安排了新的工作。）","furi":"やっと<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>が<ruby>終<rp>(</rp><rt>お</rt><rp>)</rp></ruby>わったと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>ったら、また<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しい<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>を<ruby>頼<rp>(</rp><rt>たの</rt><rp>)</rp></ruby>まれた。（原以为工作终于结束了，可又被安排了新的工作。）"}],"id":"N2-63"},{"title":"64. ～とか（不确定、传闻）","blocks":[{"t":"label","label":"接续①","text":"句子的普通形/名词 + とか/とかいう","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + とか/とかいう"},{"t":"label","label":"说明①","text":"表示不确定，“说是……什么的”。","furi":""},{"t":"label","label":"例句①","text":"中村さんとかいう人から電話が入ってきた。（一个叫中村的什么人打过电话来。）","furi":"<ruby>中村<rp>(</rp><rt>なかむら</rt><rp>)</rp></ruby>さんとかいう<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>から<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>が<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>ってきた。（一个叫中村的什么人打过电话来。）"},{"t":"label","label":"接续②","text":"句子的普通形 + とかいうことだ/とかいう話だ","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + とかいうことだ/とかいう<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>だ"},{"t":"label","label":"说明②","text":"表示不确定的传闻，“好像听说……”。","furi":""},{"t":"label","label":"例句②","text":"田中さんは結婚したら仕事をやめるという話だ。（据说田中结婚后会辞掉工作。）","furi":"<ruby>田中<rp>(</rp><rt>たなか</rt><rp>)</rp></ruby>さんは<ruby>結婚<rp>(</rp><rt>けっこん</rt><rp>)</rp></ruby>したら<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>をやめるという<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>だ。（据说田中结婚后会辞掉工作。）"},{"t":"label","label":"接续③","text":"句子的普通形 + とかで","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + とかで"},{"t":"label","label":"说明③","text":"表示听到的理由，“说是因为……什么的”。","furi":""},{"t":"label","label":"例句③","text":"台風が近づいているとかで、飛行機が欠航になった。（说是因为有台风逼近，飞机停飞了。）","furi":"<ruby>台風<rp>(</rp><rt>たいふう</rt><rp>)</rp></ruby>が<ruby>近<rp>(</rp><rt>ちか</rt><rp>)</rp></ruby>づいているとかで、<ruby>飛行機<rp>(</rp><rt>ひこうき</rt><rp>)</rp></ruby>が<ruby>欠航<rp>(</rp><rt>けっこう</rt><rp>)</rp></ruby>になった。（说是因为有台风逼近，飞机停飞了。）"}],"id":"N2-64"},{"title":"65. ～どころか","blocks":[{"t":"label","label":"接续","text":"动词/い形容词/な形容词的修饰形 / 名词 + どころか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>修<rp>(</rp><rt>おさむ</rt><rp>)</rp></ruby><ruby>饰<rp>(</rp><rt>饰</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + どころか"},{"t":"label","label":"说明","text":"表示从根本上否定前项，“哪里……、别说……”。","furi":""},{"t":"label","label":"例句","text":"医者には二、三日で治ると言われたが、よくなるどころかますます悪くなってきた。（医生说两三天能好，哪里好了，反而越来越严重了。）","furi":"<ruby>医者<rp>(</rp><rt>いしゃ</rt><rp>)</rp></ruby>には<ruby>二<rp>(</rp><rt>に</rt><rp>)</rp></ruby>、<ruby>三<rp>(</rp><rt>さん</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>にち</rt><rp>)</rp></ruby>で<ruby>治<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>ると<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>われたが、よくなるどころかますます<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>くなってきた。（医生说两三天能好，哪里好了，反而越来越严重了。）"}],"id":"N2-65"},{"title":"66. ～ところだった","blocks":[{"t":"label","label":"接续","text":"动词辞书形/た形/ていた形 + ところだった","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/ていた<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところだった"},{"t":"label","label":"说明","text":"“差一点就……、险些……”。","furi":""},{"t":"label","label":"例句","text":"床が濡れていることに気づかず、もう少しで倒れるところだった。（没注意到地板湿了，差点儿就摔倒了。）","furi":"<ruby>床<rp>(</rp><rt>ゆか</rt><rp>)</rp></ruby>が<ruby>濡<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>れていることに<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>づかず、もう<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>しで<ruby>倒<rp>(</rp><rt>たお</rt><rp>)</rp></ruby>れるところだった。（没注意到地板湿了，差点儿就摔倒了。）"}],"id":"N2-66"},{"title":"67. ～どころではない","blocks":[{"t":"label","label":"接续","text":"动词辞书形/ている形/名词 + どころではない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + どころではない"},{"t":"label","label":"说明","text":"表示不是做某事的场合，“不是……的时候、哪能……”。","furi":""},{"t":"label","label":"例句","text":"わたしは仕事でしばしば出張するので、あちこち旅行できていいとみんなに言われるが、いつも忙しくて見物どころではない。（因为工作关系我会经常出差，大家都说我能四处旅游真好，但总是很忙根本没办法观光。）","furi":"わたしは<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>でしばしば<ruby>出張<rp>(</rp><rt>しゅっちょう</rt><rp>)</rp></ruby>するので、あちこち<ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>できていいとみんなに<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>われるが、いつも<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しくて<ruby>見物<rp>(</rp><rt>けんぶつ</rt><rp>)</rp></ruby>どころではない。（因为工作关系我会经常出差，大家都说我能四处旅游真好，但总是很忙根本没办法观光。）"}],"id":"N2-67"},{"title":"68. ～ところに/ところへ","blocks":[{"t":"label","label":"接续","text":"动词辞书形/た形/ている形 + ところに/ところへ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところに/ところへ"},{"t":"label","label":"说明","text":"“正当……的时候”。","furi":""},{"t":"label","label":"例句","text":"外国の町で、道に迷って困っていたところに、警察が通りかかった。（在国外的城市，正当迷路不知所措时，警察刚好经过。）","furi":"<ruby>外国<rp>(</rp><rt>がいこく</rt><rp>)</rp></ruby>の<ruby>町<rp>(</rp><rt>まち</rt><rp>)</rp></ruby>で、<ruby>道<rp>(</rp><rt>みち</rt><rp>)</rp></ruby>に<ruby>迷<rp>(</rp><rt>まよ</rt><rp>)</rp></ruby>って<ruby>困<rp>(</rp><rt>こま</rt><rp>)</rp></ruby>っていたところに、<ruby>警察<rp>(</rp><rt>けいさつ</rt><rp>)</rp></ruby>が<ruby>通<rp>(</rp><rt>とお</rt><rp>)</rp></ruby>りかかった。（在国外的城市，正当迷路不知所措时，警察刚好经过。）"}],"id":"N2-68"},{"title":"69. ～ところを","blocks":[{"t":"label","label":"接续①","text":"动词辞书形/た形/ている形 + ところを","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところを"},{"t":"label","label":"说明①","text":"“正当……的时候”。","furi":""},{"t":"label","label":"例句①","text":"犯人は駅前で買い物をしているところを、警察に捕まった。（罪犯正在车站前面买东西的时候，被警察逮捕了。）","furi":"<ruby>犯人<rp>(</rp><rt>はんにん</rt><rp>)</rp></ruby>は<ruby>駅前<rp>(</rp><rt>えきまえ</rt><rp>)</rp></ruby>で<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>い<ruby>物<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>をしているところを、<ruby>警察<rp>(</rp><rt>けいさつ</rt><rp>)</rp></ruby>に<ruby>捕<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>まった。（罪犯正在车站前面买东西的时候，被警察逮捕了。）"},{"t":"label","label":"接续②","text":"动词た形/ている形 + ところを見ると","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところを<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ると"},{"t":"label","label":"说明②","text":"表示判断的依据，“从……来看”。","furi":""},{"t":"label","label":"例句②","text":"朝からニコニコしているところをみると、何かいいことがあったに違いない。（从早上开始就笑眯眯的，看样子一定有什么好事情。）","furi":"<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>からニコニコしているところをみると、<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>かいいことがあったに<ruby>違<rp>(</rp><rt>ちが</rt><rp>)</rp></ruby>いない。（从早上开始就笑眯眯的，看样子一定有什么好事情。）"}],"id":"N2-69"},{"title":"70. ～としか言いようがない","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + としか言いようがない","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + としか<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>いようがない"},{"t":"label","label":"说明","text":"表示强调，“只能说是……”。","furi":""},{"t":"label","label":"例句","text":"あんなに巨大な建物を大昔の人が造ったとは、不思議としか言いようがない。（古代的人建造出这么庞大的建筑，只能说是不可思议。）","furi":"あんなに<ruby>巨大<rp>(</rp><rt>きょだい</rt><rp>)</rp></ruby>な<ruby>建物<rp>(</rp><rt>たてもの</rt><rp>)</rp></ruby>を<ruby>大昔<rp>(</rp><rt>おおむかし</rt><rp>)</rp></ruby>の<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>造<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>ったとは、<ruby>不思議<rp>(</rp><rt>ふしぎ</rt><rp>)</rp></ruby>としか<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>いようがない。（古代的人建造出这么庞大的建筑，只能说是不可思议。）"}],"id":"N2-70"},{"title":"71. ～としたら/とすれば","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + としたら/とすれば","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + としたら/とすれば"},{"t":"label","label":"说明","text":"表示假设，“如果……”。","furi":""},{"t":"label","label":"例句","text":"1年間の休暇がとれたとしたら、どんなことがしたいですか。（如果可以休一年的假，你想做什么？）","furi":"1<ruby>年間<rp>(</rp><rt>ねんかん</rt><rp>)</rp></ruby>の<ruby>休暇<rp>(</rp><rt>きゅうか</rt><rp>)</rp></ruby>がとれたとしたら、どんなことがしたいですか。（如果可以休一年的假，你想做什么？）"}],"id":"N2-71"},{"title":"72. ～とともに","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词 + とともに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + とともに"},{"t":"label","label":"说明","text":"表示伴随，“随着……、与……的同时”。","furi":""},{"t":"label","label":"例句","text":"都市では、人口の増加とともに、住宅問題が深刻になってきた。（城市里，在人口不断增加的同时，住房问题也越来越严峻。）","furi":"<ruby>都市<rp>(</rp><rt>とし</rt><rp>)</rp></ruby>では、<ruby>人口<rp>(</rp><rt>じんこう</rt><rp>)</rp></ruby>の<ruby>増加<rp>(</rp><rt>ぞうか</rt><rp>)</rp></ruby>とともに、<ruby>住宅<rp>(</rp><rt>じゅうたく</rt><rp>)</rp></ruby><ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>が<ruby>深刻<rp>(</rp><rt>しんこく</rt><rp>)</rp></ruby>になってきた。（城市里，在人口不断增加的同时，住房问题也越来越严峻。）"}],"id":"N2-72"},{"title":"73. ～とは限らない","blocks":[{"t":"label","label":"接续","text":"句子的普通形 + とは限らない","furi":"<ruby>句<rp>(</rp><rt>く</rt><rp>)</rp></ruby><ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + とは<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>らない"},{"t":"label","label":"说明","text":"“不见得……、未必……”。","furi":""},{"t":"label","label":"例句","text":"実力のあるチームがいつも勝つとは限らない。試合はやってみなければわからないのだ。（有实力的队伍未必会赢。不比赛看看，就不知道谁会赢。）","furi":"<ruby>実力<rp>(</rp><rt>じつりょく</rt><rp>)</rp></ruby>のあるチームがいつも<ruby>勝<rp>(</rp><rt>か</rt><rp>)</rp></ruby>つとは<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>らない。<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>はやってみなければわからないのだ。（有实力的队伍未必会赢。不比赛看看，就不知道谁会赢。）"}],"id":"N2-73"},{"title":"74. ～ない限り","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ない限り","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ない<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>り"},{"t":"label","label":"说明","text":"“只要不……就……、除非……否则就……”。","furi":""},{"t":"label","label":"例句","text":"この地方は人口がだんだん減っていて、何か対策を立てない限り、今後も増えることはないだろう。（这个地区的人口在逐渐减少，如果不采取对策的话，今后也不会增加吧。）","furi":"この<ruby>地方<rp>(</rp><rt>ちほう</rt><rp>)</rp></ruby>は<ruby>人口<rp>(</rp><rt>じんこう</rt><rp>)</rp></ruby>がだんだん<ruby>減<rp>(</rp><rt>へ</rt><rp>)</rp></ruby>っていて、<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>か<ruby>対策<rp>(</rp><rt>たいさく</rt><rp>)</rp></ruby>を<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>てない<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>り、<ruby>今後<rp>(</rp><rt>こんご</rt><rp>)</rp></ruby>も<ruby>増<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>えることはないだろう。（这个地区的人口在逐渐减少，如果不采取对策的话，今后也不会增加吧。）"}],"id":"N2-74"},{"title":"75. ～ないことには","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ないことには","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ないことには"},{"t":"label","label":"说明","text":"“如果不……（就不……）”。","furi":""},{"t":"label","label":"例句","text":"一度行ってみないことには、どんな所かわからないだろう。（如果不去一次看看的话，就无法知道那是一个什么样的地方吧。）","furi":"<ruby>一度<rp>(</rp><rt>いちど</rt><rp>)</rp></ruby><ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってみないことには、どんな<ruby>所<rp>(</rp><rt>ところ</rt><rp>)</rp></ruby>かわからないだろう。（如果不去一次看看的话，就无法知道那是一个什么样的地方吧。）"}],"id":"N2-75"},{"title":"76. ～ないことはない/ないこともない","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ないことはない/ないこともない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ないことはない/ないこともない"},{"t":"label","label":"说明","text":"表示有某种可能性，“不是不……、有可能……”。","furi":""},{"t":"label","label":"例句","text":"私も留学していたことがありますから、あなたの苦労がわからないこともありません。（我也曾经留过学，所以我不是不了解你的辛苦。）","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>も<ruby>留学<rp>(</rp><rt>りゅうがく</rt><rp>)</rp></ruby>していたことがありますから、あなたの<ruby>苦労<rp>(</rp><rt>くろう</rt><rp>)</rp></ruby>がわからないこともありません。（我也曾经留过学，所以我不是不了解你的辛苦。）"}],"id":"N2-76"},{"title":"77. ～ないではない/ないでもない","blocks":[{"t":"label","label":"接续","text":"动词ない形 + ないではない/ないでもない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ないではない/ないでもない"},{"t":"label","label":"说明","text":"表示并非完全没有，“并非不……、也不是不……”。","furi":""},{"t":"label","label":"例句","text":"彼女の今までの苦労を知っているので、留学が決まった時あれほど喜んだ気持ちがわからないでもない。（我深知她迄今为止所吃的苦，所以也不是不理解留学确定下来时她那么高兴的心情。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>の<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>までの<ruby>苦労<rp>(</rp><rt>くろう</rt><rp>)</rp></ruby>を<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>っているので、<ruby>留学<rp>(</rp><rt>りゅうがく</rt><rp>)</rp></ruby>が<ruby>決<rp>(</rp><rt>き</rt><rp>)</rp></ruby>まった<ruby>時<rp>(</rp><rt>とき</rt><rp>)</rp></ruby>あれほど<ruby>喜<rp>(</rp><rt>よろこ</rt><rp>)</rp></ruby>んだ<ruby>気持<rp>(</rp><rt>きも</rt><rp>)</rp></ruby>ちがわからないでもない。（我深知她迄今为止所吃的苦，所以也不是不理解留学确定下来时她那么高兴的心情。）"}],"id":"N2-77"},{"title":"78. ～ながら（も）","blocks":[{"t":"label","label":"接续","text":"动词ます形 / い形容词词干 / な形容词词干/名词 + ながら（も）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + ながら（も）"},{"t":"label","label":"说明","text":"表示逆接，“虽然……但是……”。","furi":""},{"t":"label","label":"例句","text":"あの経営者は、不良品と知りながら製品を販売していた。（那个经营者明知道是次品，却还在销售。）","furi":"あの<ruby>経営<rp>(</rp><rt>けいえい</rt><rp>)</rp></ruby><ruby>者<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>は、<ruby>不<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby><ruby>良品<rp>(</rp><rt>りょうひん</rt><rp>)</rp></ruby>と<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>りながら<ruby>製品<rp>(</rp><rt>せいひん</rt><rp>)</rp></ruby>を<ruby>販売<rp>(</rp><rt>はんばい</rt><rp>)</rp></ruby>していた。（那个经营者明知道是次品，却还在销售。）"}],"id":"N2-78"},{"title":"79. ～なくはない/なくもない","blocks":[{"t":"label","label":"接续","text":"动词ない形 / い形容词词干+く / な形容词词干 / 名词 + なくはない/なくもない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+く / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + なくはない/なくもない"},{"t":"label","label":"说明","text":"表示并非完全没有，“不是不……”。","furi":""},{"t":"label","label":"例句","text":"山本さんは、ある日突然会社をやめて周りを驚かせたが、あの人の性格を考えると、理解できなくはない。（山本有一天突然辞职了，让大家吃了一惊。不过从他的性格来看，也并非不能理解。）","furi":"<ruby>山本<rp>(</rp><rt>やまもと</rt><rp>)</rp></ruby>さんは、ある<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby><ruby>突然<rp>(</rp><rt>とつぜん</rt><rp>)</rp></ruby><ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>をやめて<ruby>周<rp>(</rp><rt>まわ</rt><rp>)</rp></ruby>りを<ruby>驚<rp>(</rp><rt>おどろ</rt><rp>)</rp></ruby>かせたが、あの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>の<ruby>性格<rp>(</rp><rt>せいかく</rt><rp>)</rp></ruby>を<ruby>考<rp>(</rp><rt>かんが</rt><rp>)</rp></ruby>えると、<ruby>理解<rp>(</rp><rt>りかい</rt><rp>)</rp></ruby>できなくはない。（山本有一天突然辞职了，让大家吃了一惊。不过从他的性格来看，也并非不能理解。）"}],"id":"N2-79"},{"title":"80. ～ならともかく","blocks":[{"t":"label","label":"接续","text":"动词辞书形/い形容词普通形 / な形容词词干/名词 + ならともかく","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + ならともかく"},{"t":"label","label":"说明","text":"“如果是……则另当别论”。","furi":""},{"t":"label","label":"例句","text":"遅刻ならともかく、無断欠勤などもってのほかだ。（如果是迟到也就罢了，招呼都不打就不来上班真是岂有此理。）","furi":"<ruby>遅刻<rp>(</rp><rt>ちこく</rt><rp>)</rp></ruby>ならともかく、<ruby>無断<rp>(</rp><rt>むだん</rt><rp>)</rp></ruby><ruby>欠勤<rp>(</rp><rt>けっきん</rt><rp>)</rp></ruby>などもってのほかだ。（如果是迟到也就罢了，招呼都不打就不来上班真是岂有此理。）"}],"id":"N2-80"},{"title":"81. ～にあたって/にあたり","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词 + にあたって/にあたり","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にあたって/にあたり"},{"t":"label","label":"说明","text":"表示重要的时刻，“值此……之际、在……的时候”。","furi":""},{"t":"label","label":"例句","text":"新年を迎えるにあたって、一年の計画を立てた。（在迎接新年之际，制订了一年的计划。）","furi":"<ruby>新年<rp>(</rp><rt>しんねん</rt><rp>)</rp></ruby>を<ruby>迎<rp>(</rp><rt>むか</rt><rp>)</rp></ruby>えるにあたって、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>の<ruby>計画<rp>(</rp><rt>けいかく</rt><rp>)</rp></ruby>を<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>てた。（在迎接新年之际，制订了一年的计划。）"}],"id":"N2-81"},{"title":"82. ～に応じて（は）/に応じ","blocks":[{"t":"label","label":"接续","text":"名词 + に応じて（は）/に応じ","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>応<rp>(</rp><rt>おう</rt><rp>)</rp></ruby>じて（は）/に<ruby>応<rp>(</rp><rt>おう</rt><rp>)</rp></ruby>じ"},{"t":"label","label":"说明","text":"“根据……、按照……”。","furi":""},{"t":"label","label":"例句","text":"このレストランは、客の予算に応じていくつかのコースを用意してくれる。（这家餐厅根据客人的预算准备了几个套系的菜。）","furi":"このレストランは、<ruby>客<rp>(</rp><rt>きゃく</rt><rp>)</rp></ruby>の<ruby>予算<rp>(</rp><rt>よさん</rt><rp>)</rp></ruby>に<ruby>応<rp>(</rp><rt>おう</rt><rp>)</rp></ruby>じていくつかのコースを<ruby>用意<rp>(</rp><rt>ようい</rt><rp>)</rp></ruby>してくれる。（这家餐厅根据客人的预算准备了几个套系的菜。）"}],"id":"N2-82"},{"title":"83. ～に（は）かかわらず/に（は）かかわりなく","blocks":[{"t":"label","label":"接续","text":"名词 / 动词/い形容词普通形 + に（は）かかわらず/に（は）かかわりなく","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> / <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + に（は）かかわらず/に（は）かかわりなく"},{"t":"label","label":"说明","text":"“不管……、无论……”。","furi":""},{"t":"label","label":"例句","text":"好きか嫌いかにかかわらず、この仕事は必ずしなければならない。（不管喜不喜欢，都必须做这个工作。）","furi":"<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きか<ruby>嫌<rp>(</rp><rt>きら</rt><rp>)</rp></ruby>いかにかかわらず、この<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>は<ruby>必<rp>(</rp><rt>かなら</rt><rp>)</rp></ruby>ずしなければならない。（不管喜不喜欢，都必须做这个工作。）"}],"id":"N2-83"},{"title":"84. ～にかかわる","blocks":[{"t":"label","label":"接续","text":"名词 + にかかわる","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にかかわる"},{"t":"label","label":"说明","text":"“与……有关、涉及到……”，表示影响到重要的事情。","furi":""},{"t":"label","label":"例句","text":"進学は自分の未来にかかわることだから、真剣に考えなさい。（升学与自己的未来息息相关，一定要慎重考虑。）","furi":"<ruby>進学<rp>(</rp><rt>しんがく</rt><rp>)</rp></ruby>は<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>の<ruby>未来<rp>(</rp><rt>みらい</rt><rp>)</rp></ruby>にかかわることだから、<ruby>真剣<rp>(</rp><rt>しんけん</rt><rp>)</rp></ruby>に<ruby>考<rp>(</rp><rt>かんが</rt><rp>)</rp></ruby>えなさい。（升学与自己的未来息息相关，一定要慎重考虑。）"}],"id":"N2-84"},{"title":"85. ～に限って/に限り","blocks":[{"t":"label","label":"接续①","text":"名词 + に限って/に限り","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>って/に<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>り"},{"t":"label","label":"说明①","text":"表示限度，“只限于……、只有……”。","furi":""},{"t":"label","label":"例句①","text":"毎週火曜日に限って、映画は半額になります。（只有每周周二，电影半价。）","furi":"<ruby>毎週<rp>(</rp><rt>まいしゅう</rt><rp>)</rp></ruby><ruby>火曜日<rp>(</rp><rt>かようび</rt><rp>)</rp></ruby>に<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>って、<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>は<ruby>半額<rp>(</rp><rt>はんがく</rt><rp>)</rp></ruby>になります。（只有每周周二，电影半价。）"},{"t":"label","label":"接续②","text":"名词 + に限って","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>って"},{"t":"label","label":"说明②","text":"表示偏偏在关键时刻，“唯独……、偏偏……”。","furi":""},{"t":"label","label":"例句②","text":"大切な用事があって遅刻してはいけない時に限って、寝坊してしまう。（偏偏在有重要的事情不能迟到的时候会睡过头。）","furi":"<ruby>大切<rp>(</rp><rt>たいせつ</rt><rp>)</rp></ruby>な<ruby>用事<rp>(</rp><rt>ようじ</rt><rp>)</rp></ruby>があって<ruby>遅刻<rp>(</rp><rt>ちこく</rt><rp>)</rp></ruby>してはいけない<ruby>時<rp>(</rp><rt>とき</rt><rp>)</rp></ruby>に<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>って、<ruby>寝坊<rp>(</rp><rt>ねぼう</rt><rp>)</rp></ruby>してしまう。（偏偏在有重要的事情不能迟到的时候会睡过头。）"}],"id":"N2-85"},{"title":"86. ～に限らず","blocks":[{"t":"label","label":"接续","text":"名词 + に限らず","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>らず"},{"t":"label","label":"说明","text":"“不仅……而且……”。","furi":""},{"t":"label","label":"例句","text":"あの選手は子供のころ、サッカーに限らず、スポーツならなんでも得意だったそうだ。（听说那位选手小时候，不仅擅长足球，只要是体育项目都很拿手。）","furi":"あの<ruby>選手<rp>(</rp><rt>せんしゅ</rt><rp>)</rp></ruby>は<ruby>子供<rp>(</rp><rt>こども</rt><rp>)</rp></ruby>のころ、サッカーに<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>らず、スポーツならなんでも<ruby>得意<rp>(</rp><rt>とくい</rt><rp>)</rp></ruby>だったそうだ。（听说那位选手小时候，不仅擅长足球，只要是体育项目都很拿手。）"}],"id":"N2-86"},{"title":"87. ～に限る","blocks":[{"t":"label","label":"接续","text":"动词辞书形/ない形 / 名词 + に限る","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>る"},{"t":"label","label":"说明","text":"“最好是……”。","furi":""},{"t":"label","label":"例句","text":"疲れたときは、寝るに限ります。（累的时候，最好是睡一觉。）","furi":"<ruby>疲<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>れたときは、<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>るに<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>ります。（累的时候，最好是睡一觉。）"}],"id":"N2-87"},{"title":"88. ～にかけては/にかけても","blocks":[{"t":"label","label":"接续","text":"名词 + にかけては/にかけても","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にかけては/にかけても"},{"t":"label","label":"说明","text":"“在……方面”。后项多是对某人某物的正面评价。","furi":""},{"t":"label","label":"例句","text":"値段は別として、味の良さにかけては、このレストランが一番だ。（价格暂且不说，在味道方面，这家餐厅是最好的。）","furi":"<ruby>値段<rp>(</rp><rt>ねだん</rt><rp>)</rp></ruby>は<ruby>別<rp>(</rp><rt>べつ</rt><rp>)</rp></ruby>として、<ruby>味<rp>(</rp><rt>あじ</rt><rp>)</rp></ruby>の<ruby>良<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>さにかけては、このレストランが<ruby>一番<rp>(</rp><rt>いちばん</rt><rp>)</rp></ruby>だ。（价格暂且不说，在味道方面，这家餐厅是最好的。）"}],"id":"N2-88"},{"title":"89. ～に決まっている","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干/名词 + に決まっている","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>決<rp>(</rp><rt>き</rt><rp>)</rp></ruby>まっている"},{"t":"label","label":"说明","text":"表示确切的推测，“一定……、肯定……”。","furi":""},{"t":"label","label":"例句","text":"今度の選挙では、実力も人気もあるあの若い候補が勝つに決まっている。（这次选举，一定是那个既有实力又有人气的年轻的候选人获胜。）","furi":"<ruby>今度<rp>(</rp><rt>こんど</rt><rp>)</rp></ruby>の<ruby>選挙<rp>(</rp><rt>せんきょ</rt><rp>)</rp></ruby>では、<ruby>実力<rp>(</rp><rt>じつりょく</rt><rp>)</rp></ruby>も<ruby>人気<rp>(</rp><rt>にんき</rt><rp>)</rp></ruby>もあるあの<ruby>若<rp>(</rp><rt>わか</rt><rp>)</rp></ruby>い<ruby>候補<rp>(</rp><rt>こうほ</rt><rp>)</rp></ruby>が<ruby>勝<rp>(</rp><rt>か</rt><rp>)</rp></ruby>つに<ruby>決<rp>(</rp><rt>き</rt><rp>)</rp></ruby>まっている。（这次选举，一定是那个既有实力又有人气的年轻的候选人获胜。）"}],"id":"N2-89"},{"title":"90. ～に加えて/に加え","blocks":[{"t":"label","label":"接续","text":"名词 + に加えて/に加え","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>加<rp>(</rp><rt>くわ</rt><rp>)</rp></ruby>えて/に<ruby>加<rp>(</rp><rt>くわ</rt><rp>)</rp></ruby>え"},{"t":"label","label":"说明","text":"表示添加，“加上……、而且……”。","furi":""},{"t":"label","label":"例句","text":"今年は作物の生育がよくないそうだ。夏の低温に加えて、雨が少なかったのが原因だと考えられている。（据说今年农作物的生长不好。原因是夏季气温过低，加上雨水不足。）","furi":"<ruby>今年<rp>(</rp><rt>ことし</rt><rp>)</rp></ruby>は<ruby>作物<rp>(</rp><rt>さくもつ</rt><rp>)</rp></ruby>の<ruby>生育<rp>(</rp><rt>せいいく</rt><rp>)</rp></ruby>がよくないそうだ。<ruby>夏<rp>(</rp><rt>なつ</rt><rp>)</rp></ruby>の<ruby>低温<rp>(</rp><rt>ていおん</rt><rp>)</rp></ruby>に<ruby>加<rp>(</rp><rt>くわ</rt><rp>)</rp></ruby>えて、<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>が<ruby>少<rp>(</rp><rt>すく</rt><rp>)</rp></ruby>なかったのが<ruby>原因<rp>(</rp><rt>げんいん</rt><rp>)</rp></ruby>だと<ruby>考<rp>(</rp><rt>かんが</rt><rp>)</rp></ruby>えられている。（据说今年农作物的生长不好。原因是夏季气温过低，加上雨水不足。）"}],"id":"N2-90"},{"title":"91. ～に応えて/に応え","blocks":[{"t":"label","label":"接续","text":"名词 + に応えて/に応え","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>応<rp>(</rp><rt>こた</rt><rp>)</rp></ruby>えて/に<ruby>応<rp>(</rp><rt>こた</rt><rp>)</rp></ruby>え"},{"t":"label","label":"说明","text":"“响应……、应……、回报……”。","furi":""},{"t":"label","label":"例句","text":"この美術館では、利用者の声に応えて、夏期の開館時間を1時間延長することにします。（这个美术馆响应使用者的要求，决定将夏季开馆时间延长一小时。）","furi":"この<ruby>美術館<rp>(</rp><rt>びじゅつかん</rt><rp>)</rp></ruby>では、<ruby>利用<rp>(</rp><rt>りよう</rt><rp>)</rp></ruby><ruby>者<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>の<ruby>声<rp>(</rp><rt>こえ</rt><rp>)</rp></ruby>に<ruby>応<rp>(</rp><rt>こた</rt><rp>)</rp></ruby>えて、<ruby>夏期<rp>(</rp><rt>かき</rt><rp>)</rp></ruby>の<ruby>開館<rp>(</rp><rt>かいかん</rt><rp>)</rp></ruby><ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>を1<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby><ruby>延長<rp>(</rp><rt>えんちょう</rt><rp>)</rp></ruby>することにします。（这个美术馆响应使用者的要求，决定将夏季开馆时间延长一小时。）"}],"id":"N2-91"},{"title":"92. ～に際して/に際し","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词 + に際して/に際し","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>際<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>して/に<ruby>際<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>し"},{"t":"label","label":"说明","text":"“当……之际、在……的时候”。书面语。","furi":""},{"t":"label","label":"例句","text":"図書館のご利用に際しては、以下の点にご注意ください。（在使用图书馆的时候，请注意以下几点。）","furi":"<ruby>図書館<rp>(</rp><rt>としょかん</rt><rp>)</rp></ruby>のご<ruby>利用<rp>(</rp><rt>りよう</rt><rp>)</rp></ruby>に<ruby>際<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>しては、<ruby>以下<rp>(</rp><rt>いか</rt><rp>)</rp></ruby>の<ruby>点<rp>(</rp><rt>てん</rt><rp>)</rp></ruby>にご<ruby>注意<rp>(</rp><rt>ちゅうい</rt><rp>)</rp></ruby>ください。（在使用图书馆的时候，请注意以下几点。）"}],"id":"N2-92"},{"title":"93. ～に先立って/に先立ち","blocks":[{"t":"label","label":"接续","text":"名词 + に先立って/に先立ち","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>先立<rp>(</rp><rt>さきだ</rt><rp>)</rp></ruby>って/に<ruby>先立<rp>(</rp><rt>さきだ</rt><rp>)</rp></ruby>ち"},{"t":"label","label":"说明","text":"“在……之前、先于……”。书面语。","furi":""},{"t":"label","label":"例句","text":"会議の開始に先立って、新しいメンバーが紹介された。（在会议开始前，先介绍了新的成员。）","furi":"<ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby>の<ruby>開始<rp>(</rp><rt>かいし</rt><rp>)</rp></ruby>に<ruby>先立<rp>(</rp><rt>さきだ</rt><rp>)</rp></ruby>って、<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しいメンバーが<ruby>紹介<rp>(</rp><rt>しょうかい</rt><rp>)</rp></ruby>された。（在会议开始前，先介绍了新的成员。）"}],"id":"N2-93"},{"title":"94. ～に従って/に従い","blocks":[{"t":"label","label":"接续①","text":"动词辞书形/名词 + に従って/に従い","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>従<rp>(</rp><rt>したが</rt><rp>)</rp></ruby>って/に<ruby>従<rp>(</rp><rt>したが</rt><rp>)</rp></ruby>い"},{"t":"label","label":"说明①","text":"“按照……”。","furi":""},{"t":"label","label":"例句①","text":"会議での決定に従って、来月から新製品の生産を開始することになった。（根据会议做出的决定，下个月开始生产新产品。）","furi":"<ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby>での<ruby>決定<rp>(</rp><rt>けってい</rt><rp>)</rp></ruby>に<ruby>従<rp>(</rp><rt>したが</rt><rp>)</rp></ruby>って、<ruby>来月<rp>(</rp><rt>らいげつ</rt><rp>)</rp></ruby>から<ruby>新<rp>(</rp><rt>しん</rt><rp>)</rp></ruby><ruby>製品<rp>(</rp><rt>せいひん</rt><rp>)</rp></ruby>の<ruby>生産<rp>(</rp><rt>せいさん</rt><rp>)</rp></ruby>を<ruby>開始<rp>(</rp><rt>かいし</rt><rp>)</rp></ruby>することになった。（根据会议做出的决定，下个月开始生产新产品。）"},{"t":"label","label":"说明②","text":"“随着……”。","furi":""},{"t":"label","label":"例句②","text":"国の経済が発展するに従って、人々の暮らしもよくなってきた。（随着国家经济的发展，人们的生活也越来越好了。）","furi":"<ruby>国<rp>(</rp><rt>くに</rt><rp>)</rp></ruby>の<ruby>経済<rp>(</rp><rt>けいざい</rt><rp>)</rp></ruby>が<ruby>発展<rp>(</rp><rt>はってん</rt><rp>)</rp></ruby>するに<ruby>従<rp>(</rp><rt>したが</rt><rp>)</rp></ruby>って、<ruby>人々<rp>(</rp><rt>ひとびと</rt><rp>)</rp></ruby>の<ruby>暮<rp>(</rp><rt>く</rt><rp>)</rp></ruby>らしもよくなってきた。（随着国家经济的发展，人们的生活也越来越好了。）"}],"id":"N2-94"},{"title":"95. ～にしたら/にすれば/にしても","blocks":[{"t":"label","label":"接续","text":"名词 + にしたら/にすれば/にしても","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にしたら/にすれば/にしても"},{"t":"label","label":"说明","text":"表示立场，“从……立场来看”。","furi":""},{"t":"label","label":"例句","text":"留学は今すぐではなく、大学を卒業してからにします。両親にしても、そのほうが安心でしょう。（留学打算等到大学毕业以后再去，而不是现在马上就去。即便是父母，也认为这样更安心吧。）","furi":"<ruby>留学<rp>(</rp><rt>りゅうがく</rt><rp>)</rp></ruby>は<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>すぐではなく、<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>を<ruby>卒業<rp>(</rp><rt>そつぎょう</rt><rp>)</rp></ruby>してからにします。<ruby>両親<rp>(</rp><rt>りょうしん</rt><rp>)</rp></ruby>にしても、そのほうが<ruby>安心<rp>(</rp><rt>あんしん</rt><rp>)</rp></ruby>でしょう。（留学打算等到大学毕业以后再去，而不是现在马上就去。即便是父母，也认为这样更安心吧。）"}],"id":"N2-95"},{"title":"96. ～にしては","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干/名词 + にしては","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にしては"},{"t":"label","label":"说明","text":"表示评价的标准，前项与后项不成比例，“就……而言”。","furi":""},{"t":"label","label":"例句","text":"この子は小学生にしてはずいぶんしっかりしている。（这个孩子还是个小学生，却很是沉稳。）","furi":"この<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>は<ruby>小学生<rp>(</rp><rt>しょうがくせい</rt><rp>)</rp></ruby>にしてはずいぶんしっかりしている。（这个孩子还是个小学生，却很是沉稳。）"}],"id":"N2-96"},{"title":"97. ～にしろ/にせよ/にしても（转折、并列）","blocks":[{"t":"label","label":"接续①","text":"动词/い形容词普通形 / な形容词词干/名词 + にしろ/にせよ/にしても","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にしろ/にせよ/にしても"},{"t":"label","label":"说明①","text":"表示让步，“即使……、无论……”。","furi":""},{"t":"label","label":"例句①","text":"どんなに強そうに見える人にしても、心に弱いところがあるはずだ。（无论是外表看起来多坚强的人，内心也应该有脆弱的地方。）","furi":"どんなに<ruby>強<rp>(</rp><rt>つよ</rt><rp>)</rp></ruby>そうに<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>える<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>にしても、<ruby>心<rp>(</rp><rt>こころ</rt><rp>)</rp></ruby>に<ruby>弱<rp>(</rp><rt>よわ</rt><rp>)</rp></ruby>いところがあるはずだ。（无论是外表看起来多坚强的人，内心也应该有脆弱的地方。）"},{"t":"label","label":"接续②","text":"动词/い形容词普通形 + にしろ/にせよ/にしても + 同","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + にしろ/にせよ/にしても + <ruby>同<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明②","text":"表示无论哪种情况，“无论是……还是……都……”。","furi":""},{"t":"label","label":"例句②","text":"卒業後就職するにせよ、進学するにせよ、早く決めないといけない。（毕业后，无论是工作还是继续深造，都必须要尽早决定。）","furi":"<ruby>卒業<rp>(</rp><rt>そつぎょう</rt><rp>)</rp></ruby><ruby>後<rp>(</rp><rt>ご</rt><rp>)</rp></ruby><ruby>就職<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby>するにせよ、<ruby>進学<rp>(</rp><rt>しんがく</rt><rp>)</rp></ruby>するにせよ、<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>く<ruby>決<rp>(</rp><rt>き</rt><rp>)</rp></ruby>めないといけない。（毕业后，无论是工作还是继续深造，都必须要尽早决定。）"}],"id":"N2-97"},{"title":"98. ～に過ぎない","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干/名词 + に過ぎない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>過<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ぎない"},{"t":"label","label":"说明","text":"“只不过……而已”。","furi":""},{"t":"label","label":"例句","text":"これは、多くの不正の一つに過ぎない。まだたくさんの不正が隠されているはずだ。（这只是许多不正当行为中的一个而已，应该还有很多不正当行为没有暴露出来。）","furi":"これは、<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>くの<ruby>不正<rp>(</rp><rt>ふせい</rt><rp>)</rp></ruby>の<ruby>一<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>つに<ruby>過<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ぎない。まだたくさんの<ruby>不正<rp>(</rp><rt>ふせい</rt><rp>)</rp></ruby>が<ruby>隠<rp>(</rp><rt>かく</rt><rp>)</rp></ruby>されているはずだ。（这只是许多不正当行为中的一个而已，应该还有很多不正当行为没有暴露出来。）"}],"id":"N2-98"},{"title":"99. ～に相違ない","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干/名词 + に相違ない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>相違<rp>(</rp><rt>そうい</rt><rp>)</rp></ruby>ない"},{"t":"label","label":"说明","text":"表示断定，“一定……、肯定……”。书面语。","furi":""},{"t":"label","label":"例句","text":"この地域の水汚染の問題を根本から解決するのは難しいに相違ない。（从根本上解决这个地区的水污染问题肯定是很难的。）","furi":"この<ruby>地域<rp>(</rp><rt>ちいき</rt><rp>)</rp></ruby>の<ruby>水<rp>(</rp><rt>みず</rt><rp>)</rp></ruby><ruby>汚染<rp>(</rp><rt>おせん</rt><rp>)</rp></ruby>の<ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>を<ruby>根本<rp>(</rp><rt>こんぽん</rt><rp>)</rp></ruby>から<ruby>解決<rp>(</rp><rt>かいけつ</rt><rp>)</rp></ruby>するのは<ruby>難<rp>(</rp><rt>むずか</rt><rp>)</rp></ruby>しいに<ruby>相違<rp>(</rp><rt>そうい</rt><rp>)</rp></ruby>ない。（从根本上解决这个地区的水污染问题肯定是很难的。）"}],"id":"N2-99"},{"title":"100. ～に沿って/に沿い","blocks":[{"t":"label","label":"接续","text":"名词 + に沿って/に沿い","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>沿<rp>(</rp><rt>そ</rt><rp>)</rp></ruby>って/に<ruby>沿<rp>(</rp><rt>そ</rt><rp>)</rp></ruby>い"},{"t":"label","label":"说明","text":"“沿着……、按照……”。","furi":""},{"t":"label","label":"例句","text":"会社の経営方針に沿って、来年度の計画を立てる。（根据公司的经营方针，制订下个年度的计划。）","furi":"<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>の<ruby>経営<rp>(</rp><rt>けいえい</rt><rp>)</rp></ruby><ruby>方針<rp>(</rp><rt>ほうしん</rt><rp>)</rp></ruby>に<ruby>沿<rp>(</rp><rt>そ</rt><rp>)</rp></ruby>って、<ruby>来年度<rp>(</rp><rt>らいねんど</rt><rp>)</rp></ruby>の<ruby>計画<rp>(</rp><rt>けいかく</rt><rp>)</rp></ruby>を<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>てる。（根据公司的经营方针，制订下个年度的计划。）"}],"id":"N2-100"},{"title":"101. ～に違いない","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干/名词 + に違いない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>違<rp>(</rp><rt>ちが</rt><rp>)</rp></ruby>いない"},{"t":"label","label":"说明","text":"表示根据事实做非常肯定的判断，“一定……、肯定……”。","furi":""},{"t":"label","label":"例句","text":"彼は日本に10年以上住んでいたので、日本語のレベルが高いに違いない。（他在日本生活了十多年，日语水平一定很高。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>に10<ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby><ruby>以上<rp>(</rp><rt>いじょう</rt><rp>)</rp></ruby><ruby>住<rp>(</rp><rt>す</rt><rp>)</rp></ruby>んでいたので、<ruby>日本語<rp>(</rp><rt>にほんご</rt><rp>)</rp></ruby>のレベルが<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いに<ruby>違<rp>(</rp><rt>ちが</rt><rp>)</rp></ruby>いない。（他在日本生活了十多年，日语水平一定很高。）"}],"id":"N2-101"},{"title":"102. ～につき","blocks":[{"t":"label","label":"接续①","text":"名词 + につき","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + につき"},{"t":"label","label":"说明①","text":"表示平均分配，“每……”。","furi":""},{"t":"label","label":"例句①","text":"水道代は1か月につき3000円かかります。（每个月水费要花费三千日元。）","furi":"<ruby>水道<rp>(</rp><rt>すいどう</rt><rp>)</rp></ruby><ruby>代<rp>(</rp><rt>だい</rt><rp>)</rp></ruby>は1か<ruby>月<rp>(</rp><rt>げつ</rt><rp>)</rp></ruby>につき3000<ruby>円<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>かかります。（每个月水费要花费三千日元。）"},{"t":"label","label":"接续②","text":"名词 + につき","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + につき"},{"t":"label","label":"说明②","text":"表示原因，“因为……”。用于通知、告示等。","furi":""},{"t":"label","label":"例句②","text":"ただいま水道工事中につき、1週間休ませていただけます。（由于正在维修下水道，暂停营业一个星期。）","furi":"ただいま<ruby>水道<rp>(</rp><rt>すいどう</rt><rp>)</rp></ruby><ruby>工事<rp>(</rp><rt>こうじ</rt><rp>)</rp></ruby><ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby>につき、1<ruby>週間<rp>(</rp><rt>しゅうかん</rt><rp>)</rp></ruby><ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>ませていただけます。（由于正在维修下水道，暂停营业一个星期。）"}],"id":"N2-102"},{"title":"103. ～につけ/につけては/につけても","blocks":[{"t":"label","label":"接续①","text":"动词辞书形/名词 + につけ/につけては/につけても","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + につけ/につけては/につけても"},{"t":"label","label":"说明①","text":"“每当……就……”。","furi":""},{"t":"label","label":"例句①","text":"この写真を見るにつけ、子どもの頃を思い出す。（每当看到这张照片，我就会想起小时候的事情。）","furi":"この<ruby>写真<rp>(</rp><rt>しゃしん</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>るにつけ、<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもの<ruby>頃<rp>(</rp><rt>ころ</rt><rp>)</rp></ruby>を<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>い<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>す。（每当看到这张照片，我就会想起小时候的事情。）"},{"t":"label","label":"接续②","text":"动词辞书形/い形容词/名词 + につけ + 同","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + につけ + <ruby>同<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明②","text":"“不论……还是……都……”。","furi":""},{"t":"label","label":"例句②","text":"社長は常に会社の状況をつかんでおかなければならない。いいにつけ、悪いにつけ、状況を報告させる必要がある。（社长必须时常掌握公司的状况。无论是好事还是坏事，都需要让下属汇报实情。）","furi":"<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>は<ruby>常<rp>(</rp><rt>つね</rt><rp>)</rp></ruby>に<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>の<ruby>状況<rp>(</rp><rt>じょうきょう</rt><rp>)</rp></ruby>をつかんでおかなければならない。いいにつけ、<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>いにつけ、<ruby>状況<rp>(</rp><rt>じょうきょう</rt><rp>)</rp></ruby>を<ruby>報告<rp>(</rp><rt>ほうこく</rt><rp>)</rp></ruby>させる<ruby>必要<rp>(</rp><rt>ひつよう</rt><rp>)</rp></ruby>がある。（社长必须时常掌握公司的状况。无论是好事还是坏事，都需要让下属汇报实情。）"}],"id":"N2-103"},{"title":"104. ～に伴って/に伴い","blocks":[{"t":"label","label":"接续","text":"动词辞书形/名词 + に伴って/に伴い","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>伴<rp>(</rp><rt>ともな</rt><rp>)</rp></ruby>って/に<ruby>伴<rp>(</rp><rt>ともな</rt><rp>)</rp></ruby>い"},{"t":"label","label":"说明","text":"“随着……”。书面语。","furi":""},{"t":"label","label":"例句","text":"その島は、森林の減少に伴って、鳥や動物の数が減ってきている。（随着森林的减少，那个岛上的鸟类和动物的数量也在减少。）","furi":"その<ruby>島<rp>(</rp><rt>しま</rt><rp>)</rp></ruby>は、<ruby>森林<rp>(</rp><rt>しんりん</rt><rp>)</rp></ruby>の<ruby>減少<rp>(</rp><rt>げんしょう</rt><rp>)</rp></ruby>に<ruby>伴<rp>(</rp><rt>ともな</rt><rp>)</rp></ruby>って、<ruby>鳥<rp>(</rp><rt>とり</rt><rp>)</rp></ruby>や<ruby>動物<rp>(</rp><rt>どうぶつ</rt><rp>)</rp></ruby>の<ruby>数<rp>(</rp><rt>かず</rt><rp>)</rp></ruby>が<ruby>減<rp>(</rp><rt>へ</rt><rp>)</rp></ruby>ってきている。（随着森林的减少，那个岛上的鸟类和动物的数量也在减少。）"}],"id":"N2-104"},{"title":"105. ～に反して/に反し","blocks":[{"t":"label","label":"接续","text":"名词 + に反して/に反し","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>反<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>して/に<ruby>反<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>し"},{"t":"label","label":"说明","text":"“与……相反”。","furi":""},{"t":"label","label":"例句","text":"けさの天気予報では午後から晴れると言っていた。ところが、予報に反して、雨が降り続いている。（今天的天气预报说下午开始转晴。可与预报相反，还是在不停地下雨。）","furi":"けさの<ruby>天気<rp>(</rp><rt>てんき</rt><rp>)</rp></ruby><ruby>予報<rp>(</rp><rt>よほう</rt><rp>)</rp></ruby>では<ruby>午後<rp>(</rp><rt>ごご</rt><rp>)</rp></ruby>から<ruby>晴<rp>(</rp><rt>は</rt><rp>)</rp></ruby>れると<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>っていた。ところが、<ruby>予報<rp>(</rp><rt>よほう</rt><rp>)</rp></ruby>に<ruby>反<rp>(</rp><rt>はん</rt><rp>)</rp></ruby>して、<ruby>雨<rp>(</rp><rt>あめ</rt><rp>)</rp></ruby>が<ruby>降<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>り<ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>いている。（今天的天气预报说下午开始转晴。可与预报相反，还是在不停地下雨。）"}],"id":"N2-105"},{"title":"106. ～にほかならない","blocks":[{"t":"label","label":"接续①","text":"名词 + にほかならない","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にほかならない"},{"t":"label","label":"说明①","text":"表示断定，“正是……、不外乎……”。","furi":""},{"t":"label","label":"例句①","text":"今回の失敗の原因は、準備不足にほかならない。（这次失败的原因无外乎是准备不充分。）","furi":"<ruby>今回<rp>(</rp><rt>こんかい</rt><rp>)</rp></ruby>の<ruby>失敗<rp>(</rp><rt>しっぱい</rt><rp>)</rp></ruby>の<ruby>原因<rp>(</rp><rt>げんいん</rt><rp>)</rp></ruby>は、<ruby>準備<rp>(</rp><rt>じゅんび</rt><rp>)</rp></ruby><ruby>不足<rp>(</rp><rt>ふそく</rt><rp>)</rp></ruby>にほかならない。（这次失败的原因无外乎是准备不充分。）"},{"t":"label","label":"接续②","text":"动词/い形容词普通形 + からにほかならない / な形容词词干/名词 + だ/である + からにほかならない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + からにほかならない / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + だ/である + からにほかならない"},{"t":"label","label":"说明②","text":"强调原因，“正是因为……”。","furi":""},{"t":"label","label":"例句②","text":"その問題についていろいろな意見が出ているが、それは、みんなが関心を持っているからにほかならない。（关于这个问题，大家提出了很多意见，这正是因为大家对这个问题的关注。）","furi":"その<ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>についていろいろな<ruby>意見<rp>(</rp><rt>いけん</rt><rp>)</rp></ruby>が<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>ているが、それは、みんなが<ruby>関心<rp>(</rp><rt>かんしん</rt><rp>)</rp></ruby>を<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>っているからにほかならない。（关于这个问题，大家提出了很多意见，这正是因为大家对这个问题的关注。）"}],"id":"N2-106"},{"title":"107. ～にもかかわらず","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+である / 名词+である + にもかかわらず","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+である / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+である + にもかかわらず"},{"t":"label","label":"说明","text":"表示转折，“虽然……但是……、尽管……却……”。","furi":""},{"t":"label","label":"例句","text":"彼は、夏休み中にもかかわらず、毎日図書館で勉強している。（虽然是暑假，但他却每天在图书馆学习。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は、<ruby>夏休<rp>(</rp><rt>なつやす</rt><rp>)</rp></ruby>み<ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby>にもかかわらず、<ruby>毎日<rp>(</rp><rt>まいにち</rt><rp>)</rp></ruby><ruby>図書館<rp>(</rp><rt>としょかん</rt><rp>)</rp></ruby>で<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>している。（虽然是暑假，但他却每天在图书馆学习。）"}],"id":"N2-107"},{"title":"108. ～に基づいて/に基づき","blocks":[{"t":"label","label":"接续","text":"名词 + に基づいて/に基づき","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + に<ruby>基<rp>(</rp><rt>もと</rt><rp>)</rp></ruby>づいて/に<ruby>基<rp>(</rp><rt>もと</rt><rp>)</rp></ruby>づき"},{"t":"label","label":"说明","text":"“根据……、按照……”。","furi":""},{"t":"label","label":"例句","text":"調査結果に基づいて、論文を書く。（根据调查结果来写论文。）","furi":"<ruby>調査<rp>(</rp><rt>ちょうさ</rt><rp>)</rp></ruby><ruby>結果<rp>(</rp><rt>けっか</rt><rp>)</rp></ruby>に<ruby>基<rp>(</rp><rt>もと</rt><rp>)</rp></ruby>づいて、<ruby>論文<rp>(</rp><rt>ろんぶん</rt><rp>)</rp></ruby>を<ruby>書<rp>(</rp><rt>か</rt><rp>)</rp></ruby>く。（根据调查结果来写论文。）"}],"id":"N2-108"},{"title":"109. ～にわたって/にわたり","blocks":[{"t":"label","label":"接续","text":"名词 + にわたって/にわたり","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + にわたって/にわたり"},{"t":"label","label":"说明","text":"表示时间或空间范围，“涉及……、一直……”。","furi":""},{"t":"label","label":"例句","text":"踏切事故のために、2時間にわたり、電車がストップしました。（因为岔道口的事故，电车足足停了两个小时。）","furi":"<ruby>踏切<rp>(</rp><rt>ふみきり</rt><rp>)</rp></ruby><ruby>事故<rp>(</rp><rt>じこ</rt><rp>)</rp></ruby>のために、2<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>にわたり、<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>がストップしました。（因为岔道口的事故，电车足足停了两个小时。）"}],"id":"N2-109"},{"title":"110. ～抜きで/抜きに/を抜きにして/は抜きにして","blocks":[{"t":"label","label":"接续","text":"名词 + 抜きで/抜きに/を抜きにして/は抜きにして","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + <ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>きで/<ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>きに/を<ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>きにして/は<ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>きにして"},{"t":"label","label":"说明","text":"“省去……、去掉……”。","furi":""},{"t":"label","label":"例句","text":"かたいあいさつは抜きにして、さっそく乾杯しましょう。（免去繁琐的致辞，赶快干杯吧。）","furi":"かたいあいさつは<ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>きにして、さっそく<ruby>乾杯<rp>(</rp><rt>かんぱい</rt><rp>)</rp></ruby>しましょう。（免去繁琐的致辞，赶快干杯吧。）"}],"id":"N2-110"},{"title":"111. ～抜きでは/抜きには/を抜きにしては","blocks":[{"t":"label","label":"接续","text":"名词 + 抜きでは/抜きには/を抜きにしては（+否定）","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + <ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>きでは/<ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>きには/を<ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>きにしては（+否定）"},{"t":"label","label":"说明","text":"“省去……的话、（如果）没有……就不……”。","furi":""},{"t":"label","label":"例句","text":"この町の発展は観光事業を抜きにしては語れない。（抛开旅游事业的话，这个城市的发展就无从谈起。）","furi":"この<ruby>町<rp>(</rp><rt>まち</rt><rp>)</rp></ruby>の<ruby>発展<rp>(</rp><rt>はってん</rt><rp>)</rp></ruby>は<ruby>観光<rp>(</rp><rt>かんこう</rt><rp>)</rp></ruby><ruby>事業<rp>(</rp><rt>じぎょう</rt><rp>)</rp></ruby>を<ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>きにしては<ruby>語<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>れない。（抛开旅游事业的话，这个城市的发展就无从谈起。）"}],"id":"N2-111"},{"title":"112. ～抜く","blocks":[{"t":"label","label":"接续","text":"动词ます形 + 抜く","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>く"},{"t":"label","label":"说明","text":"表示克服困难坚持做完，“……到底、一直……”。","furi":""},{"t":"label","label":"例句","text":"マラソン大会に出場するからには、よく練習をして42.195kmを走り抜きたい。（既然要参加马拉松比赛，就想好好练习，跑完42.195公里。）","furi":"マラソン<ruby>大会<rp>(</rp><rt>たいかい</rt><rp>)</rp></ruby>に<ruby>出場<rp>(</rp><rt>しゅつじょう</rt><rp>)</rp></ruby>するからには、よく<ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby>をして42.195kmを<ruby>走<rp>(</rp><rt>はし</rt><rp>)</rp></ruby>り<ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>きたい。（既然要参加马拉松比赛，就想好好练习，跑完42.195公里。）"}],"id":"N2-112"},{"title":"113. ～のみならず","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+である / 名词 + のみならず","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+である / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + のみならず"},{"t":"label","label":"说明","text":"“不仅……，（而且）……”。","furi":""},{"t":"label","label":"例句","text":"このカメラは高性能であるのみならず、メモリーカードの容量も大きい。（这个相机不仅摄影性能好，存储卡的容量也很大。）","furi":"このカメラは<ruby>高性能<rp>(</rp><rt>こうせいのう</rt><rp>)</rp></ruby>であるのみならず、メモリーカードの<ruby>容量<rp>(</rp><rt>ようりょう</rt><rp>)</rp></ruby>も<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きい。（这个相机不仅摄影性能好，存储卡的容量也很大。）"}],"id":"N2-113"},{"title":"114. ～のもとで/のもとに","blocks":[{"t":"label","label":"接续①","text":"名词 + のもとで/のもとに","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + のもとで/のもとに"},{"t":"label","label":"说明①","text":"表示范围，“在……下”。","furi":""},{"t":"label","label":"例句①","text":"坂本さんの論文は大変すばらしい。山田教授の指導のもとに修正を重ねた結果だということだ。（坂本的论文很优秀。这是在山田教授的指导下不断修改的结果。）","furi":"<ruby>坂本<rp>(</rp><rt>さかもと</rt><rp>)</rp></ruby>さんの<ruby>論文<rp>(</rp><rt>ろんぶん</rt><rp>)</rp></ruby>は<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>すばらしい。<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby><ruby>教授<rp>(</rp><rt>きょうじゅ</rt><rp>)</rp></ruby>の<ruby>指導<rp>(</rp><rt>しどう</rt><rp>)</rp></ruby>のもとに<ruby>修正<rp>(</rp><rt>しゅうせい</rt><rp>)</rp></ruby>を<ruby>重<rp>(</rp><rt>かさ</rt><rp>)</rp></ruby>ねた<ruby>結果<rp>(</rp><rt>けっか</rt><rp>)</rp></ruby>だということだ。（坂本的论文很优秀。这是在山田教授的指导下不断修改的结果。）"},{"t":"label","label":"接续②","text":"名词+の + 名のもとに","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + <ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>のもとに"},{"t":"label","label":"说明②","text":"“以……为名、在……的名义之下”。","furi":""},{"t":"label","label":"例句②","text":"「開発」の名のもとに大規模な森林破壊が進んでいる。（以“开发”为名，大量的森林不断被破坏。）","furi":"「<ruby>開発<rp>(</rp><rt>かいはつ</rt><rp>)</rp></ruby>」の<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>のもとに<ruby>大<rp>(</rp><rt>だい</rt><rp>)</rp></ruby><ruby>規模<rp>(</rp><rt>きぼ</rt><rp>)</rp></ruby>な<ruby>森林<rp>(</rp><rt>しんりん</rt><rp>)</rp></ruby><ruby>破壊<rp>(</rp><rt>はかい</rt><rp>)</rp></ruby>が<ruby>進<rp>(</rp><rt>すす</rt><rp>)</rp></ruby>んでいる。（以“开发”为名，大量的森林不断被破坏。）"}],"id":"N2-114"},{"title":"115. ～ばかりか","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干/名词 + ばかりか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + ばかりか"},{"t":"label","label":"说明","text":"表示递进，“不但……、不只是……”。","furi":""},{"t":"label","label":"例句","text":"彼は、銀行からの借金が数百万円もあって、返せずにいるという。そればかりか友人たちからも相当のお金を借りているらしい。（听说他从银行借了几百万，还没还。不仅如此，好像还从朋友那儿借了不少钱。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は、<ruby>銀行<rp>(</rp><rt>ぎんこう</rt><rp>)</rp></ruby>からの<ruby>借金<rp>(</rp><rt>しゃっきん</rt><rp>)</rp></ruby>が<ruby>数<rp>(</rp><rt>すう</rt><rp>)</rp></ruby><ruby>百<rp>(</rp><rt>ひゃく</rt><rp>)</rp></ruby><ruby>万<rp>(</rp><rt>まん</rt><rp>)</rp></ruby><ruby>円<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>もあって、<ruby>返<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>せずにいるという。そればかりか<ruby>友人<rp>(</rp><rt>ゆうじん</rt><rp>)</rp></ruby>たちからも<ruby>相当<rp>(</rp><rt>そうとう</rt><rp>)</rp></ruby>のお<ruby>金<rp>(</rp><rt>かね</rt><rp>)</rp></ruby>を<ruby>借<rp>(</rp><rt>か</rt><rp>)</rp></ruby>りているらしい。（听说他从银行借了几百万，还没还。不仅如此，好像还从朋友那儿借了不少钱。）"}],"id":"N2-115"},{"title":"116. ～ばかりに","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+である + ばかりに","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+である + ばかりに"},{"t":"label","label":"说明","text":"表示不好的原因，“就是因为……、正因为……”。","furi":""},{"t":"label","label":"例句","text":"みんなの前でパソコンが得意だなんて話すんじゃなかった。よけいなことを言ったばかりにクラス会の案内状作りを頼まれてしまった。（真不该在大家面前说自己电脑很擅长。就因为多嘴，结果被安排去制作班会的邀请函。）","furi":"みんなの<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>でパソコンが<ruby>得意<rp>(</rp><rt>とくい</rt><rp>)</rp></ruby>だなんて<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>すんじゃなかった。よけいなことを<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったばかりにクラス<ruby>会<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>の<ruby>案内<rp>(</rp><rt>あんない</rt><rp>)</rp></ruby><ruby>状<rp>(</rp><rt>じょう</rt><rp>)</rp></ruby><ruby>作<rp>(</rp><rt>づく</rt><rp>)</rp></ruby>りを<ruby>頼<rp>(</rp><rt>たの</rt><rp>)</rp></ruby>まれてしまった。（真不该在大家面前说自己电脑很擅长。就因为多嘴，结果被安排去制作班会的邀请函。）"}],"id":"N2-116"},{"title":"117. ～はともかく（として）","blocks":[{"t":"label","label":"接续","text":"名词 + はともかく（として）","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + はともかく（として）"},{"t":"label","label":"说明","text":"“……暂且不谈、先不说……”。","furi":""},{"t":"label","label":"例句","text":"この店の料理は、味はともかく量は多い。（这家店的菜，味道怎么样暂且不说，分量是挺足的。）","furi":"この<ruby>店<rp>(</rp><rt>みせ</rt><rp>)</rp></ruby>の<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>は、<ruby>味<rp>(</rp><rt>あじ</rt><rp>)</rp></ruby>はともかく<ruby>量<rp>(</rp><rt>りょう</rt><rp>)</rp></ruby>は<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>い。（这家店的菜，味道怎么样暂且不说，分量是挺足的。）"}],"id":"N2-117"},{"title":"118. ～は別として","blocks":[{"t":"label","label":"接续","text":"名词 + は別として","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + は<ruby>別<rp>(</rp><rt>べつ</rt><rp>)</rp></ruby>として"},{"t":"label","label":"说明","text":"“……另当别论、……暂且不论”。","furi":""},{"t":"label","label":"例句","text":"おいしいかどうかは別として、一度食べてみたいと思う。（好不好吃暂且不说，我想去尝尝看。）","furi":"おいしいかどうかは<ruby>別<rp>(</rp><rt>べつ</rt><rp>)</rp></ruby>として、<ruby>一度<rp>(</rp><rt>いちど</rt><rp>)</rp></ruby><ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べてみたいと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>う。（好不好吃暂且不说，我想去尝尝看。）"}],"id":"N2-118"},{"title":"119. ～はもちろん/はもとより","blocks":[{"t":"label","label":"接续","text":"名词 + はもちろん/はもとより","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + はもちろん/はもとより"},{"t":"label","label":"说明","text":"“……自不必说、不用说……”。","furi":""},{"t":"label","label":"例句","text":"面接試験では、話し方はもちろん、服装などにも気をつける必要がある。（面试时，说话的方式就不用说了，着装也需要注意。）","furi":"<ruby>面接<rp>(</rp><rt>めんせつ</rt><rp>)</rp></ruby><ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>では、<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>し<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>はもちろん、<ruby>服装<rp>(</rp><rt>ふくそう</rt><rp>)</rp></ruby>などにも<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>をつける<ruby>必要<rp>(</rp><rt>ひつよう</rt><rp>)</rp></ruby>がある。（面试时，说话的方式就不用说了，着装也需要注意。）"}],"id":"N2-119"},{"title":"120. ～反面/半面","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+である / 名词+である + 反面/半面","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+である / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+である + <ruby>反面<rp>(</rp><rt>はんめん</rt><rp>)</rp></ruby>/<ruby>半面<rp>(</rp><rt>はんめん</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示同一事物的正反两面，“另一方面……”。","furi":""},{"t":"label","label":"例句","text":"この車は、空気を汚さない反面、価格が高いという欠点がある。（这个车不污染空气，但也有价格昂贵的缺点。）","furi":"この<ruby>車<rp>(</rp><rt>くるま</rt><rp>)</rp></ruby>は、<ruby>空気<rp>(</rp><rt>くうき</rt><rp>)</rp></ruby>を<ruby>汚<rp>(</rp><rt>よご</rt><rp>)</rp></ruby>さない<ruby>反面<rp>(</rp><rt>はんめん</rt><rp>)</rp></ruby>、<ruby>価格<rp>(</rp><rt>かかく</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いという<ruby>欠点<rp>(</rp><rt>けってん</rt><rp>)</rp></ruby>がある。（这个车不污染空气，但也有价格昂贵的缺点。）"}],"id":"N2-120"},{"title":"121. ～ほか（は）ない/よりほか（は）ない/ほかしかたがない","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + ほか（は）ない/よりほか（は）ない/ほかしかたがない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ほか（は）ない/よりほか（は）ない/ほかしかたがない"},{"t":"label","label":"说明","text":"表示别无选择，“只有……、只好……”。","furi":""},{"t":"label","label":"例句","text":"夫も子どもも亡くなってしまって、たった一人の弟に頼るほかない。（丈夫和孩子都去世了，只能依靠唯一的一个弟弟。）","furi":"<ruby>夫<rp>(</rp><rt>おっと</rt><rp>)</rp></ruby>も<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもも<ruby>亡<rp>(</rp><rt>な</rt><rp>)</rp></ruby>くなってしまって、たった<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>の<ruby>弟<rp>(</rp><rt>おとうと</rt><rp>)</rp></ruby>に<ruby>頼<rp>(</rp><rt>たよ</rt><rp>)</rp></ruby>るほかない。（丈夫和孩子都去世了，只能依靠唯一的一个弟弟。）"}],"id":"N2-121"},{"title":"122. ～まい/まいか","blocks":[{"t":"label","label":"接续","text":"动词辞书形/ない形 + まい/まいか（する→するまい/すまい、くる→くるまい/こまい）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + まい/まいか（する→するまい/すまい、くる→くるまい/こまい）"},{"t":"label","label":"说明①","text":"表示否定的意志，“不想……、不会……”。","furi":""},{"t":"label","label":"例句①","text":"日本へ来てしばらくは、国へ電話はかけるまいと思っていたが、今日はさびしくてたまらず、ついかけてしまった。（原本想刚来日本的这段时间不要打电话回国的，但今天实在是太寂寞了，忍不住打了电话。）","furi":"<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby>へ<ruby>来<rp>(</rp><rt>き</rt><rp>)</rp></ruby>てしばらくは、<ruby>国<rp>(</rp><rt>くに</rt><rp>)</rp></ruby>へ<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>はかけるまいと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>っていたが、<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>はさびしくてたまらず、ついかけてしまった。（原本想刚来日本的这段时间不要打电话回国的，但今天实在是太寂寞了，忍不住打了电话。）"},{"t":"label","label":"说明②","text":"表示否定的推测，“不会吧、也许不……”。","furi":""},{"t":"label","label":"例句②","text":"自分の目で確かめない限り、そんな恐ろしいことはだれも信じまい。（如果不是自己亲眼看到，那么恐怖的事情恐怕谁也不会相信的吧。）","furi":"<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>の<ruby>目<rp>(</rp><rt>め</rt><rp>)</rp></ruby>で<ruby>確<rp>(</rp><rt>たし</rt><rp>)</rp></ruby>かめない<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>り、そんな<ruby>恐<rp>(</rp><rt>おそ</rt><rp>)</rp></ruby>ろしいことはだれも<ruby>信<rp>(</rp><rt>しん</rt><rp>)</rp></ruby>じまい。（如果不是自己亲眼看到，那么恐怖的事情恐怕谁也不会相信的吧。）"}],"id":"N2-122"},{"title":"123. ～もかまわず","blocks":[{"t":"label","label":"接续","text":"动词普通形+の / 名词 + もかまわず","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>+の / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + もかまわず"},{"t":"label","label":"说明","text":"“不顾……”。","furi":""},{"t":"label","label":"例句","text":"彼は、けがをした足が痛むのもかまわず、工事現場を見てまわった。（他不顾脚伤的疼痛，视察了施工现场。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は、けがをした<ruby>足<rp>(</rp><rt>あし</rt><rp>)</rp></ruby>が<ruby>痛<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>むのもかまわず、<ruby>工事<rp>(</rp><rt>こうじ</rt><rp>)</rp></ruby><ruby>現場<rp>(</rp><rt>げんば</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>てまわった。（他不顾脚伤的疼痛，视察了施工现场。）"}],"id":"N2-123"},{"title":"124. ～も当然だ","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词 + も当然だ","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + も<ruby>当然<rp>(</rp><rt>とうぜん</rt><rp>)</rp></ruby>だ"},{"t":"label","label":"说明","text":"“……也是理所当然的”。","furi":""},{"t":"label","label":"例句","text":"3週間も水をやらなかったのだから、花が枯れてしまうのも当然だ。（因为三个星期没浇水，花枯掉了也是理所当然的。）","furi":"3<ruby>週間<rp>(</rp><rt>しゅうかん</rt><rp>)</rp></ruby>も<ruby>水<rp>(</rp><rt>みず</rt><rp>)</rp></ruby>をやらなかったのだから、<ruby>花<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>が<ruby>枯<rp>(</rp><rt>か</rt><rp>)</rp></ruby>れてしまうのも<ruby>当然<rp>(</rp><rt>とうぜん</rt><rp>)</rp></ruby>だ。（因为三个星期没浇水，花枯掉了也是理所当然的。）"}],"id":"N2-124"},{"title":"125. ～も～なら～も～だ","blocks":[{"t":"label","label":"接续","text":"名词 + も + な形容词词干/名词 + なら + 名词 + も + 名词 + だ","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + も + な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + なら + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + も + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + だ"},{"t":"label","label":"说明","text":"表示双方都不好，“……也不像样、……也不像样”。","furi":""},{"t":"label","label":"例句","text":"夜中に夫婦喧嘩をして近所に迷惑をかけるなんて、夫も夫なら妻も妻だ。（夫妻俩大半夜吵架打扰到邻居，丈夫也不好妻子也有问题。）","furi":"<ruby>夜中<rp>(</rp><rt>やちゅう</rt><rp>)</rp></ruby>に<ruby>夫婦<rp>(</rp><rt>ふうふ</rt><rp>)</rp></ruby><ruby>喧嘩<rp>(</rp><rt>けんか</rt><rp>)</rp></ruby>をして<ruby>近所<rp>(</rp><rt>きんじょ</rt><rp>)</rp></ruby>に<ruby>迷惑<rp>(</rp><rt>めいわく</rt><rp>)</rp></ruby>をかけるなんて、<ruby>夫<rp>(</rp><rt>おっと</rt><rp>)</rp></ruby>も<ruby>夫<rp>(</rp><rt>おっと</rt><rp>)</rp></ruby>なら<ruby>妻<rp>(</rp><rt>つま</rt><rp>)</rp></ruby>も<ruby>妻<rp>(</rp><rt>つま</rt><rp>)</rp></ruby>だ。（夫妻俩大半夜吵架打扰到邻居，丈夫也不好妻子也有问题。）"}],"id":"N2-125"},{"title":"126. ～ものか/もんか","blocks":[{"t":"label","label":"接续","text":"动词/い形容词/な形容词的修饰形 + ものか/もんか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>修<rp>(</rp><rt>おさむ</rt><rp>)</rp></ruby><ruby>饰<rp>(</rp><rt>饰</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ものか/もんか"},{"t":"label","label":"说明","text":"表示强烈的否定，“怎么会……呢、不会……”。","furi":""},{"t":"label","label":"例句","text":"注文も計算も間違えるような、あんなレストランには、もう二度と行くものか。（那种把点的菜弄错，结账也出错的餐厅我再也不会去了。）","furi":"<ruby>注文<rp>(</rp><rt>ちゅうもん</rt><rp>)</rp></ruby>も<ruby>計算<rp>(</rp><rt>けいさん</rt><rp>)</rp></ruby>も<ruby>間違<rp>(</rp><rt>まちが</rt><rp>)</rp></ruby>えるような、あんなレストランには、もう<ruby>二度<rp>(</rp><rt>にど</rt><rp>)</rp></ruby>と<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>くものか。（那种把点的菜弄错，结账也出错的餐厅我再也不会去了。）"}],"id":"N2-126"},{"title":"127. ～ものがある","blocks":[{"t":"label","label":"接续","text":"动词/い形容词/な形容词的修饰形 + ものがある","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>修<rp>(</rp><rt>おさむ</rt><rp>)</rp></ruby><ruby>饰<rp>(</rp><rt>饰</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ものがある"},{"t":"label","label":"说明","text":"表示评价和感受，“有……的一面、的确很……”。","furi":""},{"t":"label","label":"例句","text":"彼女の演奏には、人の心を動かすものがある。（她的演奏很打动人心。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>の<ruby>演奏<rp>(</rp><rt>えんそう</rt><rp>)</rp></ruby>には、<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>の<ruby>心<rp>(</rp><rt>こころ</rt><rp>)</rp></ruby>を<ruby>動<rp>(</rp><rt>うご</rt><rp>)</rp></ruby>かすものがある。（她的演奏很打动人心。）"}],"id":"N2-127"},{"title":"128. ～ものだから","blocks":[{"t":"label","label":"接续","text":"动词/い形容词/な形容词的修饰形 + ものだから","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>修<rp>(</rp><rt>おさむ</rt><rp>)</rp></ruby><ruby>饰<rp>(</rp><rt>饰</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ものだから"},{"t":"label","label":"说明","text":"表示原因，用于解释、辩解，“因为……”。","furi":""},{"t":"label","label":"例句","text":"娘があまりに楽しみにしていたものだから、遊園地に行けなくなったことをすぐには言い出せなかった。（因为女儿一直很期待，所以去不了游乐园这件事没能马上说出口。）","furi":"<ruby>娘<rp>(</rp><rt>むすめ</rt><rp>)</rp></ruby>があまりに<ruby>楽<rp>(</rp><rt>たの</rt><rp>)</rp></ruby>しみにしていたものだから、<ruby>遊園<rp>(</rp><rt>ゆうえん</rt><rp>)</rp></ruby><ruby>地<rp>(</rp><rt>ち</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>けなくなったことをすぐには<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>い<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>せなかった。（因为女儿一直很期待，所以去不了游乐园这件事没能马上说出口。）"}],"id":"N2-128"},{"title":"129. ～ものではない","blocks":[{"t":"label","label":"接续","text":"动词辞书形 + ものではない","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ものではない"},{"t":"label","label":"说明","text":"表示从道德、社会常识出发给予忠告，“不应该……、不要……”。","furi":""},{"t":"label","label":"例句","text":"常識のある大人なら、目上の人に対して失礼なことを言うものではない。（如果是有常识的大人的话，就不应该对长辈说出无礼的话。）","furi":"<ruby>常識<rp>(</rp><rt>じょうしき</rt><rp>)</rp></ruby>のある<ruby>大人<rp>(</rp><rt>おとな</rt><rp>)</rp></ruby>なら、<ruby>目上<rp>(</rp><rt>めうえ</rt><rp>)</rp></ruby>の<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>に<ruby>対<rp>(</rp><rt>たい</rt><rp>)</rp></ruby>して<ruby>失礼<rp>(</rp><rt>しつれい</rt><rp>)</rp></ruby>なことを<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>うものではない。（如果是有常识的大人的话，就不应该对长辈说出无礼的话。）"}],"id":"N2-129"},{"title":"130. ～ものなら","blocks":[{"t":"label","label":"接续①","text":"动词可能形 + ものなら","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>可能<rp>(</rp><rt>かのう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ものなら"},{"t":"label","label":"说明①","text":"表示几乎不可能的假设，“如果能……的话”。","furi":""},{"t":"label","label":"例句①","text":"あの日の記憶を消せるものなら消してしまいたい。（如果可以的话，真想把那天的记忆给消除了。）","furi":"あの<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>の<ruby>記憶<rp>(</rp><rt>きおく</rt><rp>)</rp></ruby>を<ruby>消<rp>(</rp><rt>け</rt><rp>)</rp></ruby>せるものなら<ruby>消<rp>(</rp><rt>け</rt><rp>)</rp></ruby>してしまいたい。（如果可以的话，真想把那天的记忆给消除了。）"},{"t":"label","label":"接续②","text":"动词意向形 + ものなら","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>意向<rp>(</rp><rt>いこう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ものなら"},{"t":"label","label":"说明②","text":"表示假设，后项多为严重结果，“如果要……的话”。","furi":""},{"t":"label","label":"例句②","text":"母の作った料理に文句をつけようものなら、次の日から食事を作ってもらえない。（要是对妈妈做的菜挑三拣四的话，她第二天就不会做给我吃了。）","furi":"<ruby>母<rp>(</rp><rt>はは</rt><rp>)</rp></ruby>の<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>った<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>に<ruby>文句<rp>(</rp><rt>もんく</rt><rp>)</rp></ruby>をつけようものなら、<ruby>次<rp>(</rp><rt>つぎ</rt><rp>)</rp></ruby>の<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>から<ruby>食事<rp>(</rp><rt>しょくじ</rt><rp>)</rp></ruby>を<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>ってもらえない。（要是对妈妈做的菜挑三拣四的话，她第二天就不会做给我吃了。）"}],"id":"N2-130"},{"title":"131. ～ものの","blocks":[{"t":"label","label":"接续","text":"动词/い形容词/な形容词的修饰形 + ものの","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>修<rp>(</rp><rt>おさむ</rt><rp>)</rp></ruby><ruby>饰<rp>(</rp><rt>饰</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ものの"},{"t":"label","label":"说明","text":"表示转折，“虽然……但是……”。","furi":""},{"t":"label","label":"例句","text":"あの映画は一度見たものの、話の筋がまったくわからなかった。（那部电影虽然看过一次，但完全没明白它在说什么。）","furi":"あの<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>は<ruby>一度<rp>(</rp><rt>いちど</rt><rp>)</rp></ruby><ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>たものの、<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>の<ruby>筋<rp>(</rp><rt>すじ</rt><rp>)</rp></ruby>がまったくわからなかった。（那部电影虽然看过一次，但完全没明白它在说什么。）"}],"id":"N2-131"},{"title":"132. ～も～ば～も","blocks":[{"t":"label","label":"接续","text":"名词+も + 动词ば形/い形容词ば形 + 名词+も / 名词+も + な形容词词干/名词+なら + 名词+も","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+も + <ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ば<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ば<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+も / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+も + な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+なら + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+も"},{"t":"label","label":"说明","text":"“既……又……”。","furi":""},{"t":"label","label":"例句","text":"うちの子はまだ中学生だが、料理も作れば、洗濯もしてくれる。（我孩子虽然还是中学生，但是既会做饭，又帮我洗衣服。）","furi":"うちの<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>はまだ<ruby>中学生<rp>(</rp><rt>ちゅうがくせい</rt><rp>)</rp></ruby>だが、<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>も<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>れば、<ruby>洗濯<rp>(</rp><rt>せんたく</rt><rp>)</rp></ruby>もしてくれる。（我孩子虽然还是中学生，但是既会做饭，又帮我洗衣服。）"}],"id":"N2-132"},{"title":"133. ～やら～やら","blocks":[{"t":"label","label":"接续","text":"动词辞书形/い形容词/名词 + やら + 同","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + やら + <ruby>同<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示列举，“又是……又是……、一会儿……一会儿……”。","furi":""},{"t":"label","label":"例句","text":"彼に突然プロポーズされて、びっくりするやらうれしいやらでとても複雑な気持ちだ。（突然被男友求婚，又是吃惊，又是高兴，心情很复杂。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>に<ruby>突然<rp>(</rp><rt>とつぜん</rt><rp>)</rp></ruby>プロポーズされて、びっくりするやらうれしいやらでとても<ruby>複雑<rp>(</rp><rt>ふくざつ</rt><rp>)</rp></ruby>な<ruby>気持<rp>(</rp><rt>きも</rt><rp>)</rp></ruby>ちだ。（突然被男友求婚，又是吃惊，又是高兴，心情很复杂。）"}],"id":"N2-133"},{"title":"134. ～ようで","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+の + ようで","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + ようで"},{"t":"label","label":"说明","text":"表示外表与实际情况不符，“看上去好像……，但……”。","furi":""},{"t":"label","label":"例句","text":"敬語の使い方はわかっているようで、実は間違って使っていることが意外と多い。（敬语的用法看上去好像都懂，但实际上误用的情况出乎意料得多。）","furi":"<ruby>敬語<rp>(</rp><rt>けいご</rt><rp>)</rp></ruby>の<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>い<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>はわかっているようで、<ruby>実<rp>(</rp><rt>じつ</rt><rp>)</rp></ruby>は<ruby>間違<rp>(</rp><rt>まちが</rt><rp>)</rp></ruby>って<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>っていることが<ruby>意外<rp>(</rp><rt>いがい</rt><rp>)</rp></ruby>と<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>い。（敬语的用法看上去好像都懂，但实际上误用的情况出乎意料得多。）"}],"id":"N2-134"},{"title":"135. ～ようでは","blocks":[{"t":"label","label":"接续","text":"动词辞书形/ない形 + ようでは","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>辞<rp>(</rp><rt>じ</rt><rp>)</rp></ruby><ruby>书<rp>(</rp><rt>书</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ようでは"},{"t":"label","label":"说明","text":"表示假设，后项多与期望相反，“如果……的话，那就……”。","furi":""},{"t":"label","label":"例句","text":"この程度の練習で文句を言うようでは、次の試合に勝てないぞ。（如果这点训练都要抱怨的话，下次比赛可赢不了！）","furi":"この<ruby>程度<rp>(</rp><rt>ていど</rt><rp>)</rp></ruby>の<ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby>で<ruby>文句<rp>(</rp><rt>もんく</rt><rp>)</rp></ruby>を<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>うようでは、<ruby>次<rp>(</rp><rt>つぎ</rt><rp>)</rp></ruby>の<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>に<ruby>勝<rp>(</rp><rt>か</rt><rp>)</rp></ruby>てないぞ。（如果这点训练都要抱怨的话，下次比赛可赢不了！）"}],"id":"N2-135"},{"title":"136. ～ようなら/ようだったら","blocks":[{"t":"label","label":"接续","text":"动词/い形容词普通形 / な形容词词干+な / 名词+の + ようなら/ようだったら","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> / な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>+な / <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>+の + ようなら/ようだったら"},{"t":"label","label":"说明","text":"表示假定，“如果……”。","furi":""},{"t":"label","label":"例句","text":"明日もまた仕事を休むようなら、会社をやめてもらいます。（如果明天还不来上班的话，就不要来了。）","furi":"<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>もまた<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>を<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>むようなら、<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>をやめてもらいます。（如果明天还不来上班的话，就不要来了。）"}],"id":"N2-136"},{"title":"137. ～わりに（は）","blocks":[{"t":"label","label":"接续","text":"动词/い形容词/な形容词/名词的修饰形 + わりに（は）","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/い<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/な<ruby>形容<rp>(</rp><rt>けいよう</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>修<rp>(</rp><rt>おさむ</rt><rp>)</rp></ruby><ruby>饰<rp>(</rp><rt>饰</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + わりに（は）"},{"t":"label","label":"说明","text":"表示比较基准，前后不成比例，“虽然……但是……、比起……”。","furi":""},{"t":"label","label":"例句","text":"このレストランは高いわりにはうまいとは言えない。（这家饭店消费很高但算不上好吃。）","furi":"このレストランは<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いわりにはうまいとは<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>えない。（这家饭店消费很高但算不上好吃。）"}],"id":"N2-137"},{"title":"138. ～をかねて","blocks":[{"t":"label","label":"接续","text":"名词 + をかねて","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + をかねて"},{"t":"label","label":"说明","text":"“兼有……的目的、顺带着……”。","furi":""},{"t":"label","label":"例句","text":"飲食店の勉強をかねて、アルバイトとして働き始めた。（为了顺带学习一下餐饮业知识，开始在餐馆里打工。）","furi":"<ruby>飲食<rp>(</rp><rt>いんしょく</rt><rp>)</rp></ruby><ruby>店<rp>(</rp><rt>てん</rt><rp>)</rp></ruby>の<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>をかねて、アルバイトとして<ruby>働<rp>(</rp><rt>はたら</rt><rp>)</rp></ruby>き<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>めた。（为了顺带学习一下餐饮业知识，开始在餐馆里打工。）"}],"id":"N2-138"},{"title":"139. ～を中心に（して）/を中心として","blocks":[{"t":"label","label":"接续","text":"名词 + を中心に（して）/を中心として","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + を<ruby>中心<rp>(</rp><rt>ちゅうしん</rt><rp>)</rp></ruby>に（して）/を<ruby>中心<rp>(</rp><rt>ちゅうしん</rt><rp>)</rp></ruby>として"},{"t":"label","label":"说明","text":"“以……为中心、把……作为重点”。","furi":""},{"t":"label","label":"例句","text":"この作者の作品は、若い女性を中心に読まれている。（这位作家的作品是以年轻的女性为主要的读者群。）","furi":"この<ruby>作者<rp>(</rp><rt>さくしゃ</rt><rp>)</rp></ruby>の<ruby>作品<rp>(</rp><rt>さくひん</rt><rp>)</rp></ruby>は、<ruby>若<rp>(</rp><rt>わか</rt><rp>)</rp></ruby>い<ruby>女性<rp>(</rp><rt>じょせい</rt><rp>)</rp></ruby>を<ruby>中心<rp>(</rp><rt>ちゅうしん</rt><rp>)</rp></ruby>に<ruby>読<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>まれている。（这位作家的作品是以年轻的女性为主要的读者群。）"}],"id":"N2-139"},{"title":"140. ～を通じて/を通して","blocks":[{"t":"label","label":"接续","text":"名词 + を通じて/を通して","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + を<ruby>通<rp>(</rp><rt>つう</rt><rp>)</rp></ruby>じて/を<ruby>通<rp>(</rp><rt>とお</rt><rp>)</rp></ruby>して"},{"t":"label","label":"说明①","text":"表示整个范围。","furi":""},{"t":"label","label":"例句①","text":"この地域は一年を通して暖かくて、とても過ごしやすい。（这里一年到头都很暖和，很适合居住。）","furi":"この<ruby>地域<rp>(</rp><rt>ちいき</rt><rp>)</rp></ruby>は<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>を<ruby>通<rp>(</rp><rt>とお</rt><rp>)</rp></ruby>して<ruby>暖<rp>(</rp><rt>あたた</rt><rp>)</rp></ruby>かくて、とても<ruby>過<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ごしやすい。（这里一年到头都很暖和，很适合居住。）"},{"t":"label","label":"说明②","text":"表示中介或手段，“通过……”。","furi":""},{"t":"label","label":"例句②","text":"佐藤さんご夫妻とは、山口さんを通して知り合いました。（佐藤夫妇我是通过山口而认识的。）","furi":"<ruby>佐藤<rp>(</rp><rt>さとう</rt><rp>)</rp></ruby>さんご<ruby>夫妻<rp>(</rp><rt>ふさい</rt><rp>)</rp></ruby>とは、<ruby>山口<rp>(</rp><rt>やまぐち</rt><rp>)</rp></ruby>さんを<ruby>通<rp>(</rp><rt>とお</rt><rp>)</rp></ruby>して<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>り<ruby>合<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>いました。（佐藤夫妇我是通过山口而认识的。）"}],"id":"N2-140"},{"title":"141. ～を問わず/は問わず","blocks":[{"t":"label","label":"接续","text":"名词 + を問わず/は問わず","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + を<ruby>問<rp>(</rp><rt>と</rt><rp>)</rp></ruby>わず/は<ruby>問<rp>(</rp><rt>と</rt><rp>)</rp></ruby>わず"},{"t":"label","label":"说明","text":"“无论……、不管……”。","furi":""},{"t":"label","label":"例句","text":"この公園では、季節を問わず美しい花が見られます。（在这个公园，无论哪个季节都可以看到美丽的花。）","furi":"この<ruby>公園<rp>(</rp><rt>こうえん</rt><rp>)</rp></ruby>では、<ruby>季節<rp>(</rp><rt>きせつ</rt><rp>)</rp></ruby>を<ruby>問<rp>(</rp><rt>と</rt><rp>)</rp></ruby>わず<ruby>美<rp>(</rp><rt>うつく</rt><rp>)</rp></ruby>しい<ruby>花<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>が<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>られます。（在这个公园，无论哪个季节都可以看到美丽的花。）"}],"id":"N2-141"},{"title":"142. ～を除いて（は）/を除き","blocks":[{"t":"label","label":"接续","text":"名词 + を除いて（は）/を除き","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + を<ruby>除<rp>(</rp><rt>のぞ</rt><rp>)</rp></ruby>いて（は）/を<ruby>除<rp>(</rp><rt>のぞ</rt><rp>)</rp></ruby>き"},{"t":"label","label":"说明","text":"“除……之外”。","furi":""},{"t":"label","label":"例句","text":"この仕事は楽だし、給料もいいし、通勤時間が長いことを除いては文句ない。（这份工作很轻松，工资也高，除了上下班时间长点之外没有什么好抱怨的。）","furi":"この<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>は<ruby>楽<rp>(</rp><rt>らく</rt><rp>)</rp></ruby>だし、<ruby>給料<rp>(</rp><rt>きゅうりょう</rt><rp>)</rp></ruby>もいいし、<ruby>通勤<rp>(</rp><rt>つうきん</rt><rp>)</rp></ruby><ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>が<ruby>長<rp>(</rp><rt>なが</rt><rp>)</rp></ruby>いことを<ruby>除<rp>(</rp><rt>のぞ</rt><rp>)</rp></ruby>いては<ruby>文句<rp>(</rp><rt>もんく</rt><rp>)</rp></ruby>ない。（这份工作很轻松，工资也高，除了上下班时间长点之外没有什么好抱怨的。）"}],"id":"N2-142"},{"title":"143. ～をめぐって/をめぐり","blocks":[{"t":"label","label":"接续","text":"名词 + をめぐって/をめぐり","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + をめぐって/をめぐり"},{"t":"label","label":"说明","text":"“围绕……”。后项与“讨论、争论、对立”等动词搭配。","furi":""},{"t":"label","label":"例句","text":"外国人社員の労働条件をめぐって、会社側と労働者側が対立している。（围绕外国籍员工的劳动条件，劳资双方对立起来。）","furi":"<ruby>外国<rp>(</rp><rt>がいこく</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>じん</rt><rp>)</rp></ruby><ruby>社員<rp>(</rp><rt>しゃいん</rt><rp>)</rp></ruby>の<ruby>労働<rp>(</rp><rt>ろうどう</rt><rp>)</rp></ruby><ruby>条件<rp>(</rp><rt>じょうけん</rt><rp>)</rp></ruby>をめぐって、<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby><ruby>側<rp>(</rp><rt>がわ</rt><rp>)</rp></ruby>と<ruby>労働<rp>(</rp><rt>ろうどう</rt><rp>)</rp></ruby><ruby>者<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby><ruby>側<rp>(</rp><rt>がわ</rt><rp>)</rp></ruby>が<ruby>対立<rp>(</rp><rt>たいりつ</rt><rp>)</rp></ruby>している。（围绕外国籍员工的劳动条件，劳资双方对立起来。）"}],"id":"N2-143"},{"title":"144. ～をもとに（して）","blocks":[{"t":"label","label":"接续","text":"名词 + をもとに（して）","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby> + をもとに（して）"},{"t":"label","label":"说明","text":"“以……为基础、以……为依据”。","furi":""},{"t":"label","label":"例句","text":"昨日見たドラマは、実際にあった話をもとに作られたそうだ。（据说昨天看的电视剧是根据真实的故事而制作的。）","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby><ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>たドラマは、<ruby>実際<rp>(</rp><rt>じっさい</rt><rp>)</rp></ruby>にあった<ruby>話<rp>(</rp><rt>はなし</rt><rp>)</rp></ruby>をもとに<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>られたそうだ。（据说昨天看的电视剧是根据真实的故事而制作的。）"}],"id":"N2-144"}]},{"id":"N2-u2","title":"敬语（N2补充部分）","points":[{"title":"145. お/ご～いただけませんか","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + いただけませんか / ご + III类动词词干 + いただけませんか","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + いただけませんか / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + いただけませんか"},{"t":"label","label":"说明","text":"礼貌地请求对方为自己做某事，“能否请您……”。","furi":""},{"t":"label","label":"例句","text":"すみませんが、約束の時間をご変更いただけませんか。（对不起，能否请您改一下约定的时间？）","furi":"すみませんが、<ruby>約束<rp>(</rp><rt>やくそく</rt><rp>)</rp></ruby>の<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>をご<ruby>変更<rp>(</rp><rt>へんこう</rt><rp>)</rp></ruby>いただけませんか。（对不起，能否请您改一下约定的时间？）"}],"id":"N2-145"},{"title":"146. お/ご～願えませんか","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + 願えませんか / ご + III类动词词干 + 願えませんか","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>えませんか / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + <ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>えませんか"},{"t":"label","label":"说明","text":"礼貌地请求对方做某事。","furi":""},{"t":"label","label":"例句","text":"この資料の翻訳にご協力願えませんか。（请您帮忙翻译一下这份资料好吗？）","furi":"この<ruby>資料<rp>(</rp><rt>しりょう</rt><rp>)</rp></ruby>の<ruby>翻訳<rp>(</rp><rt>ほんやく</rt><rp>)</rp></ruby>にご<ruby>協力<rp>(</rp><rt>きょうりょく</rt><rp>)</rp></ruby><ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>えませんか。（请您帮忙翻译一下这份资料好吗？）"}],"id":"N2-146"},{"title":"147. お/ご～申し上げる","blocks":[{"t":"label","label":"接续","text":"お + I/II类动词ます形 + 申し上げる / ご + III类动词词干 + 申し上げる","furi":"お + I/II<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>申<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>し<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>げる / ご + III<ruby>类<rp>(</rp><rt>类</rt><rp>)</rp></ruby><ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>干<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby> + <ruby>申<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>し<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>げる"},{"t":"label","label":"说明","text":"比「お/ご～する/いたす」更谦恭的表达。","furi":"<ruby>比<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>「お/ご～する/いたす」<ruby>更<rp>(</rp><rt>さら</rt><rp>)</rp></ruby><ruby>谦<rp>(</rp><rt>谦</rt><rp>)</rp></ruby><ruby>恭<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>表<rp>(</rp><rt>ひょう</rt><rp>)</rp></ruby><ruby>达<rp>(</rp><rt>达</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"このたびは、私どもの商品発送ミスにより、お客様に大変ご迷惑をおかけしましたことを深くお詫び申し上げます。（这次由于我们的商品发送错误，给顾客带来了很大的麻烦，在此深表歉意。）","furi":"このたびは、<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>どもの<ruby>商品<rp>(</rp><rt>しょうひん</rt><rp>)</rp></ruby><ruby>発送<rp>(</rp><rt>はっそう</rt><rp>)</rp></ruby>ミスにより、お<ruby>客様<rp>(</rp><rt>きゃくさま</rt><rp>)</rp></ruby>に<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>ご<ruby>迷惑<rp>(</rp><rt>めいわく</rt><rp>)</rp></ruby>をおかけしましたことを<ruby>深<rp>(</rp><rt>ふか</rt><rp>)</rp></ruby>くお<ruby>詫<rp>(</rp><rt>わ</rt><rp>)</rp></ruby>び<ruby>申<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>し<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>げます。（这次由于我们的商品发送错误，给顾客带来了很大的麻烦，在此深表歉意。）"}],"id":"N2-147"},{"title":"148. ～（さ）せていただけませんか","blocks":[{"t":"label","label":"接续","text":"动词使役形て形 + いただけませんか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>使役<rp>(</rp><rt>しえき</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + いただけませんか"},{"t":"label","label":"说明","text":"请求上级允许自己做某事，“能否允许我……、请让我……”。","furi":""},{"t":"label","label":"例句","text":"課長、今度のプロジェクトに参加させていただけないでしょうか。（课长，能否让我参加这次的项目？）","furi":"<ruby>課長<rp>(</rp><rt>かちょう</rt><rp>)</rp></ruby>、<ruby>今度<rp>(</rp><rt>こんど</rt><rp>)</rp></ruby>のプロジェクトに<ruby>参加<rp>(</rp><rt>さんか</rt><rp>)</rp></ruby>させていただけないでしょうか。（课长，能否让我参加这次的项目？）"}],"id":"N2-148"},{"title":"149. ～（さ）せてやっていただけませんか","blocks":[{"t":"label","label":"接续","text":"动词使役形て形 + やっていただけませんか","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby><ruby>使役<rp>(</rp><rt>しえき</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + やっていただけませんか"},{"t":"label","label":"说明","text":"请求对方允许第三方（己方的人）做某事，“能否让……做呢？”","furi":""},{"t":"label","label":"例句","text":"この仕事はうちの弟に担当させてやっていただけませんか。（这份工作能否让我弟弟去负责呢？）","furi":"この<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>はうちの<ruby>弟<rp>(</rp><rt>おとうと</rt><rp>)</rp></ruby>に<ruby>担当<rp>(</rp><rt>たんとう</rt><rp>)</rp></ruby>させてやっていただけませんか。（这份工作能否让我弟弟去负责呢？）"}],"id":"N2-149"},{"title":"150. ～ていただけるとありがたいんですが","blocks":[{"t":"label","label":"接续","text":"动词て形 + いただけるとありがたいんですが","furi":"<ruby>动<rp>(</rp><rt>动</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + いただけるとありがたいんですが"},{"t":"label","label":"说明","text":"委婉地请求对方，表达感谢之意，“如果能……那就实在太好了”。","furi":""},{"t":"label","label":"例句","text":"ご都合がよろしければ、ご相談に乗っていただけるとありがたいんですが。（您方便的话，如果能跟我商量商量那就实在太好了。）","furi":"ご<ruby>都合<rp>(</rp><rt>つごう</rt><rp>)</rp></ruby>がよろしければ、ご<ruby>相談<rp>(</rp><rt>そうだん</rt><rp>)</rp></ruby>に<ruby>乗<rp>(</rp><rt>の</rt><rp>)</rp></ruby>っていただけるとありがたいんですが。（您方便的话，如果能跟我商量商量那就实在太好了。）"}],"id":"N2-150"}]}]},{"id":"N1","name":"N1 文法详解（整理版）","units":[{"id":"N1-u1","title":"","points":[{"title":"1. ～あっての","blocks":[{"t":"label","label":"接续","text":"名A +（が）あっての + 名B","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>A +（が）あっての + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>B"},{"t":"label","label":"说明","text":"表示条件，“正因为有A，才有B的存在”。前项助词「が」可省略，后项常以「もの」「こと」出现。","furi":"<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>条件<rp>(</rp><rt>じょうけん</rt><rp>)</rp></ruby>，“<ruby>正因<rp>(</rp><rt>まさより</rt><rp>)</rp></ruby><ruby>为<rp>(</rp><rt>为</rt><rp>)</rp></ruby><ruby>有<rp>(</rp><rt>ゆう</rt><rp>)</rp></ruby>A，<ruby>才<rp>(</rp><rt>さい</rt><rp>)</rp></ruby><ruby>有<rp>(</rp><rt>ゆう</rt><rp>)</rp></ruby>B<ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby><ruby>存在<rp>(</rp><rt>そんざい</rt><rp>)</rp></ruby>”。<ruby>前<rp>(</rp><rt>ぜん</rt><rp>)</rp></ruby><ruby>项<rp>(</rp><rt>项</rt><rp>)</rp></ruby><ruby>助<rp>(</rp><rt>じょ</rt><rp>)</rp></ruby><ruby>词<rp>(</rp><rt>词</rt><rp>)</rp></ruby>「が」<ruby>可<rp>(</rp><rt>か</rt><rp>)</rp></ruby><ruby>省略<rp>(</rp><rt>しょうりゃく</rt><rp>)</rp></ruby>，<ruby>后<rp>(</rp><rt>きさき</rt><rp>)</rp></ruby><ruby>项<rp>(</rp><rt>项</rt><rp>)</rp></ruby><ruby>常<rp>(</rp><rt>つね</rt><rp>)</rp></ruby><ruby>以<rp>(</rp><rt>以</rt><rp>)</rp></ruby>「もの」「こと」<ruby>出<rp>(</rp><rt>いずる</rt><rp>)</rp></ruby><ruby>现<rp>(</rp><rt>现</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"今の私があるのも監督あってのことです。（正是因为有教练的帮助，才有今天的我。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>の<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>があるのも<ruby>監督<rp>(</rp><rt>かんとく</rt><rp>)</rp></ruby>あってのことです。（正是因为有教练的帮助，才有今天的我。）"},{"t":"line","text":"つらい治療に耐え、病気を克服することができたのは、家族の励ましがあってのことだ。（我之所以能够战胜病魔，正是因为有家人的支持和鼓励。）","furi":"つらい<ruby>治療<rp>(</rp><rt>ちりょう</rt><rp>)</rp></ruby>に<ruby>耐<rp>(</rp><rt>た</rt><rp>)</rp></ruby>え、<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>を<ruby>克服<rp>(</rp><rt>こくふく</rt><rp>)</rp></ruby>することができたのは、<ruby>家族<rp>(</rp><rt>かぞく</rt><rp>)</rp></ruby>の<ruby>励<rp>(</rp><rt>はげ</rt><rp>)</rp></ruby>ましがあってのことだ。（我之所以能够战胜病魔，正是因为有家人的支持和鼓励。）"}],"id":"N1-1"},{"title":"2. ～以外の何ものでもない","blocks":[{"t":"label","label":"接续","text":"名 + 以外の何ものでもない","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + <ruby>以外<rp>(</rp><rt>いがい</rt><rp>)</rp></ruby>の<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>ものでもない"},{"t":"label","label":"说明","text":"表示强调，“不是别的，正是……”。","furi":""},{"t":"label","label":"例句","text":"","furi":""},{"t":"line","text":"彼女を悩ませているのは仕事のストレス以外のなにものでもない。（使她烦恼的正是工作压力。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>を<ruby>悩<rp>(</rp><rt>なや</rt><rp>)</rp></ruby>ませているのは<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>のストレス<ruby>以外<rp>(</rp><rt>いがい</rt><rp>)</rp></ruby>のなにものでもない。（使她烦恼的正是工作压力。）"},{"t":"line","text":"今回の交通事故の原因は運転手の不注意以外のなにものでもない。（正是司机的疏忽大意酿成了这起事故。）","furi":"<ruby>今回<rp>(</rp><rt>こんかい</rt><rp>)</rp></ruby>の<ruby>交通<rp>(</rp><rt>こうつう</rt><rp>)</rp></ruby><ruby>事故<rp>(</rp><rt>じこ</rt><rp>)</rp></ruby>の<ruby>原因<rp>(</rp><rt>げんいん</rt><rp>)</rp></ruby>は<ruby>運転<rp>(</rp><rt>うんてん</rt><rp>)</rp></ruby><ruby>手<rp>(</rp><rt>しゅ</rt><rp>)</rp></ruby>の<ruby>不注意<rp>(</rp><rt>ふちゅうい</rt><rp>)</rp></ruby><ruby>以外<rp>(</rp><rt>いがい</rt><rp>)</rp></ruby>のなにものでもない。（正是司机的疏忽大意酿成了这起事故。）"}],"id":"N1-2"},{"title":"3. ～いかんで／いかんでは／いかんによっては／いかんにかかっている／いかんだ","blocks":[{"t":"sub","text":"(1) ～いかんで／いかんでは／いかんによっては","furi":""},{"t":"label","label":"接续","text":"名（の）+ いかんで／いかんでは／いかんによっては","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>（の）+ いかんで／いかんでは／いかんによっては"},{"t":"label","label":"说明","text":"表示前后关联，根据前项不同后项会采取相应措施，“取决于……”。","furi":""},{"t":"label","label":"例句","text":"出席状況・学業成績のいかんでは、奨学金の支給を停止することもある。（根据出席情况和学习成绩，有可能会停止发放奖学金。）","furi":"<ruby>出席<rp>(</rp><rt>しゅっせき</rt><rp>)</rp></ruby><ruby>状況<rp>(</rp><rt>じょうきょう</rt><rp>)</rp></ruby>・<ruby>学業<rp>(</rp><rt>がくぎょう</rt><rp>)</rp></ruby><ruby>成績<rp>(</rp><rt>せいせき</rt><rp>)</rp></ruby>のいかんでは、<ruby>奨学<rp>(</rp><rt>しょうがく</rt><rp>)</rp></ruby><ruby>金<rp>(</rp><rt>きん</rt><rp>)</rp></ruby>の<ruby>支給<rp>(</rp><rt>しきゅう</rt><rp>)</rp></ruby>を<ruby>停止<rp>(</rp><rt>ていし</rt><rp>)</rp></ruby>することもある。（根据出席情况和学习成绩，有可能会停止发放奖学金。）"},{"t":"sub","text":"(2) ～いかんにかかっている／いかんだ","furi":""},{"t":"label","label":"接续","text":"名（の）+ いかんにかかっている／いかんだ","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>（の）+ いかんにかかっている／いかんだ"},{"t":"label","label":"说明","text":"表示前项取决于后项，“（会怎样），要看……”。","furi":""},{"t":"label","label":"例句","text":"試合で逆転できるかどうかは、選手たちの意志いかんだ。（比赛中能否反超对手，取决于队员们的意志。）","furi":"<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>で<ruby>逆転<rp>(</rp><rt>ぎゃくてん</rt><rp>)</rp></ruby>できるかどうかは、<ruby>選手<rp>(</rp><rt>せんしゅ</rt><rp>)</rp></ruby>たちの<ruby>意志<rp>(</rp><rt>いし</rt><rp>)</rp></ruby>いかんだ。（比赛中能否反超对手，取决于队员们的意志。）"}],"id":"N1-3"},{"title":"4. ～いかんにかかわらず／いかんによらず／いかんをとわず","blocks":[{"t":"label","label":"接续","text":"名（の）+ いかんにかかわらず／いかんによらず／いかんをとわず","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>（の）+ いかんにかかわらず／いかんによらず／いかんをとわず"},{"t":"label","label":"说明","text":"表示不论前项如何，后项都不改变，“不管……（如何）”。","furi":""},{"t":"label","label":"例句","text":"出席欠席のいかんによらず、はがきにてお返事くださるようお願いいたします。（不管出席与否，请在明信片上作出回复。）","furi":"<ruby>出席<rp>(</rp><rt>しゅっせき</rt><rp>)</rp></ruby><ruby>欠席<rp>(</rp><rt>けっせき</rt><rp>)</rp></ruby>のいかんによらず、はがきにてお<ruby>返事<rp>(</rp><rt>へんじ</rt><rp>)</rp></ruby>くださるようお<ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>いいたします。（不管出席与否，请在明信片上作出回复。）"}],"id":"N1-4"},{"title":"5. いざ～となると／いざ～となれば／いざ～となったら","blocks":[{"t":"sub","text":"(1) いざとなると／いざとなれば／いざとなったら","furi":""},{"t":"label","label":"说明","text":"作为惯用短语，“一旦发生问题……”、“万一……”、“到了关键时刻就会……”。","furi":""},{"t":"label","label":"例句","text":"いざとなったら、110番に通報してください。（万一碰到麻烦，请打110报警。）","furi":"いざとなったら、110<ruby>番<rp>(</rp><rt>ばん</rt><rp>)</rp></ruby>に<ruby>通報<rp>(</rp><rt>つうほう</rt><rp>)</rp></ruby>してください。（万一碰到麻烦，请打110报警。）"},{"t":"sub","text":"(2) いざ～となると／いざ～となれば","furi":""},{"t":"label","label":"接续","text":"いざ + 動辞書形 + となると／となれば","furi":"いざ + <ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + となると／となれば"},{"t":"label","label":"说明","text":"表示假设，“一旦真的要……的话，就会……”。","furi":""},{"t":"label","label":"例句","text":"簡単そうに見えても、いざ自分でやるとなると、なかなかうまくいかないものだ。（虽然看似简单，但一旦自己去做，就不是那么容易。）","furi":"<ruby>簡単<rp>(</rp><rt>かんたん</rt><rp>)</rp></ruby>そうに<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>えても、いざ<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>でやるとなると、なかなかうまくいかないものだ。（虽然看似简单，但一旦自己去做，就不是那么容易。）"}],"id":"N1-5"},{"title":"6. 今ひとつ～ない","blocks":[{"t":"label","label":"说明","text":"表示评价，“还差一点、还有欠缺”。","furi":""},{"t":"label","label":"例句","text":"昨日、話題のその映画を見たが、今ひとつ迫力が足りない気がした。（昨天去看了最近成为话题的那部影片，但是我感觉震撼力还不够。）","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>、<ruby>話題<rp>(</rp><rt>わだい</rt><rp>)</rp></ruby>のその<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>たが、<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>ひとつ<ruby>迫力<rp>(</rp><rt>はくりょく</rt><rp>)</rp></ruby>が<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>りない<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>がした。（昨天去看了最近成为话题的那部影片，但是我感觉震撼力还不够。）"}],"id":"N1-6"},{"title":"7. 言わずもがな","blocks":[{"t":"label","label":"接续①","text":"言わずもがな + の + 名","furi":"<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>わずもがな + の + <ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明①","text":"“不应该说的……、不说为妙的……”。","furi":""},{"t":"label","label":"例句①","text":"あまり腹が立ったので、つい言わずもがなのことを言ってしまった。（因为太生气了，不由得说了些不该说的话。）","furi":"あまり<ruby>腹<rp>(</rp><rt>はら</rt><rp>)</rp></ruby>が<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>ったので、つい<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>わずもがなのことを<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってしまった。（因为太生气了，不由得说了些不该说的话。）"},{"t":"label","label":"接续②","text":"名 + は言わずもがな","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + は<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>わずもがな"},{"t":"label","label":"说明②","text":"“自不必说，……（也）”。","furi":""},{"t":"label","label":"例句②","text":"学生は言わずもがな、教師まで集まった。（学生自不必说，连教师都到场了。）","furi":"<ruby>学生<rp>(</rp><rt>がくせい</rt><rp>)</rp></ruby>は<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>わずもがな、<ruby>教師<rp>(</rp><rt>きょうし</rt><rp>)</rp></ruby>まで<ruby>集<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>まった。（学生自不必说，连教师都到场了。）"}],"id":"N1-7"},{"title":"8. ～（よ）うが／（よ）うと","blocks":[{"t":"label","label":"接续","text":"動意向形 + が／と","furi":"<ruby>動意<rp>(</rp><rt>どうい</rt><rp>)</rp></ruby><ruby>向<rp>(</rp><rt>こう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + が／と"},{"t":"label","label":"说明","text":"表示假定条件的逆接，“无论……都……、即使……也……”。","furi":""},{"t":"label","label":"例句","text":"どんなに数学が得意だろうと、試験のときは油断してはならない。（不管数学再怎么好，考试的时候也不能掉以轻心。）","furi":"どんなに<ruby>数学<rp>(</rp><rt>すうがく</rt><rp>)</rp></ruby>が<ruby>得意<rp>(</rp><rt>とくい</rt><rp>)</rp></ruby>だろうと、<ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>のときは<ruby>油断<rp>(</rp><rt>ゆだん</rt><rp>)</rp></ruby>してはならない。（不管数学再怎么好，考试的时候也不能掉以轻心。）"}],"id":"N1-8"},{"title":"9. ～（よ）うが～（よ）うが／（よ）うと～（よ）うと","blocks":[{"t":"label","label":"接续","text":"動意向形 + が／と + 動意向形 + が／と","furi":"<ruby>動意<rp>(</rp><rt>どうい</rt><rp>)</rp></ruby><ruby>向<rp>(</rp><rt>こう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + が／と + <ruby>動意<rp>(</rp><rt>どうい</rt><rp>)</rp></ruby><ruby>向<rp>(</rp><rt>こう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + が／と"},{"t":"label","label":"说明","text":"表示假定条件的逆接，“无论……也好，……也好，都……”。","furi":""},{"t":"label","label":"例句","text":"アクセサリーの値段は高かろうと安かろうと、つける人の好みと趣味だ。（昂贵的首饰也好，便宜的首饰也好，只是看佩戴者的爱好和兴趣罢了。）","furi":"アクセサリーの<ruby>値段<rp>(</rp><rt>ねだん</rt><rp>)</rp></ruby>は<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>かろうと<ruby>安<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>かろうと、つける<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>の<ruby>好<rp>(</rp><rt>この</rt><rp>)</rp></ruby>みと<ruby>趣味<rp>(</rp><rt>しゅみ</rt><rp>)</rp></ruby>だ。（昂贵的首饰也好，便宜的首饰也好，只是看佩戴者的爱好和兴趣罢了。）"}],"id":"N1-9"},{"title":"10. ～（よ）うが～まいが／（よ）うと～まいと","blocks":[{"t":"label","label":"接续","text":"動意向形 + が／と + 動―まい形 + が／と","furi":"<ruby>動意<rp>(</rp><rt>どうい</rt><rp>)</rp></ruby><ruby>向<rp>(</rp><rt>こう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + が／と + <ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>―まい<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + が／と"},{"t":"label","label":"说明","text":"无论前项做或不做，结果都不改变，“无论是……还是……、无论是否……都……”。","furi":""},{"t":"label","label":"例句","text":"周囲の人が反対しようとしまいと、私の気持ちは変わらない。（不管周围的人反对与否，我的主意已定。）","furi":"<ruby>周囲<rp>(</rp><rt>しゅうい</rt><rp>)</rp></ruby>の<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>反対<rp>(</rp><rt>はんたい</rt><rp>)</rp></ruby>しようとしまいと、<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>の<ruby>気持<rp>(</rp><rt>きも</rt><rp>)</rp></ruby>ちは<ruby>変<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わらない。（不管周围的人反对与否，我的主意已定。）"}],"id":"N1-10"},{"title":"11. ～（よ）うとも／～くとも","blocks":[{"t":"label","label":"接续","text":"動意向形 + とも／イ形詞幹 + くとも","furi":"<ruby>動意<rp>(</rp><rt>どうい</rt><rp>)</rp></ruby><ruby>向<rp>(</rp><rt>こう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + とも／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>詞<rp>(</rp><rt>ことば</rt><rp>)</rp></ruby><ruby>幹<rp>(</rp><rt>みき</rt><rp>)</rp></ruby> + くとも"},{"t":"label","label":"说明","text":"表示假定条件的逆接，“无论……都……、即使……也……”。","furi":""},{"t":"label","label":"例句","text":"どんなに離れていようとも、家族のことを一刻も忘れたことはない。（不管离得有多远，一刻也没有忘记过家人。）","furi":"どんなに<ruby>離<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>れていようとも、<ruby>家族<rp>(</rp><rt>かぞく</rt><rp>)</rp></ruby>のことを<ruby>一刻<rp>(</rp><rt>いっこく</rt><rp>)</rp></ruby>も<ruby>忘<rp>(</rp><rt>わす</rt><rp>)</rp></ruby>れたことはない。（不管离得有多远，一刻也没有忘记过家人。）"}],"id":"N1-11"},{"title":"12. ～（よ）うにも～ない","blocks":[{"t":"label","label":"接续","text":"動意向形 + にも + 動ない形","furi":"<ruby>動意<rp>(</rp><rt>どうい</rt><rp>)</rp></ruby><ruby>向<rp>(</rp><rt>こう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + にも + <ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示无法做到某事，“即使想……也不能……”。","furi":""},{"t":"label","label":"例句","text":"風邪で喉が痛くて、声を出そうにも出せない。（感冒了嗓子痛，即使想说话声音也出不来。）","furi":"<ruby>風邪<rp>(</rp><rt>かぜ</rt><rp>)</rp></ruby>で<ruby>喉<rp>(</rp><rt>のど</rt><rp>)</rp></ruby>が<ruby>痛<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>くて、<ruby>声<rp>(</rp><rt>こえ</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>そうにも<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>せない。（感冒了嗓子痛，即使想说话声音也出不来。）"}],"id":"N1-12"},{"title":"13. ～甲斐があって／甲斐がある／甲斐もなく／甲斐がない","blocks":[{"t":"label","label":"接续","text":"動た形／名 + の + 甲斐があって／甲斐がある／甲斐もなく／甲斐がない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + の + <ruby>甲斐<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>があって／<ruby>甲斐<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>がある／<ruby>甲斐<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>もなく／<ruby>甲斐<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>がない"},{"t":"label","label":"说明","text":"表示结果，“有（没有）价值、回报、效果”。","furi":""},{"t":"label","label":"例句","text":"応援の甲斐もなく、私のクラスのチームは一勝もできなかった。（啦啦队的加油也没有起作用，我们队一场比赛也没有赢。）","furi":"<ruby>応援<rp>(</rp><rt>おうえん</rt><rp>)</rp></ruby>の<ruby>甲斐<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>もなく、<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>のクラスのチームは<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>勝<rp>(</rp><rt>しょう</rt><rp>)</rp></ruby>もできなかった。（啦啦队的加油也没有起作用，我们队一场比赛也没有赢。）"}],"id":"N1-13"},{"title":"14. ～か否か","blocks":[{"t":"label","label":"接续","text":"動辞書形/た形／イ形／ナ形語幹（である）／名（である）+ か否か","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>（である）／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>（である）+ か<ruby>否<rp>(</rp><rt>いな</rt><rp>)</rp></ruby>か"},{"t":"label","label":"说明","text":"“是否……”。书面语。","furi":""},{"t":"label","label":"例句","text":"秘密を打ち明けるべきかいなかで悩んでいます。（是否该把秘密讲出来呢，为此我感到烦恼。）","furi":"<ruby>秘密<rp>(</rp><rt>ひみつ</rt><rp>)</rp></ruby>を<ruby>打<rp>(</rp><rt>う</rt><rp>)</rp></ruby>ち<ruby>明<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>けるべきかいなかで<ruby>悩<rp>(</rp><rt>なや</rt><rp>)</rp></ruby>んでいます。（是否该把秘密讲出来呢，为此我感到烦恼。）"}],"id":"N1-14"},{"title":"15. ～限りだ","blocks":[{"t":"label","label":"接续","text":"イ形／ナ形語幹／名 + の + 限りだ","furi":"イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + の + <ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りだ"},{"t":"label","label":"说明","text":"表示强烈的感情，“无比……、非常……、……极了”。","furi":""},{"t":"label","label":"例句","text":"自分の作品がこんなに大勢の人に評価されるとは、本当にうれしい限りだ。（自己的作品能够得到这么多人的好评让我很开心。）","furi":"<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>の<ruby>作品<rp>(</rp><rt>さくひん</rt><rp>)</rp></ruby>がこんなに<ruby>大勢<rp>(</rp><rt>たいせい</rt><rp>)</rp></ruby>の<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>に<ruby>評価<rp>(</rp><rt>ひょうか</rt><rp>)</rp></ruby>されるとは、<ruby>本当<rp>(</rp><rt>ほんとう</rt><rp>)</rp></ruby>にうれしい<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りだ。（自己的作品能够得到这么多人的好评让我很开心。）"}],"id":"N1-15"},{"title":"16. ～が最後／たら最後","blocks":[{"t":"label","label":"接续","text":"動た形 + が最後／ら最後","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + が<ruby>最後<rp>(</rp><rt>さいご</rt><rp>)</rp></ruby>／ら<ruby>最後<rp>(</rp><rt>さいご</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示假定条件，“一旦……就……”。","furi":""},{"t":"label","label":"例句","text":"こんな貴重な本は、一度手放したが最後、二度とこの手には戻って来ないだろう。（如此珍贵的书，一旦脱手就再也无法找回来吧。）","furi":"こんな<ruby>貴重<rp>(</rp><rt>きちょう</rt><rp>)</rp></ruby>な<ruby>本<rp>(</rp><rt>ほん</rt><rp>)</rp></ruby>は、<ruby>一度<rp>(</rp><rt>いちど</rt><rp>)</rp></ruby><ruby>手放<rp>(</rp><rt>てばな</rt><rp>)</rp></ruby>したが<ruby>最後<rp>(</rp><rt>さいご</rt><rp>)</rp></ruby>、<ruby>二度<rp>(</rp><rt>にど</rt><rp>)</rp></ruby>とこの<ruby>手<rp>(</rp><rt>て</rt><rp>)</rp></ruby>には<ruby>戻<rp>(</rp><rt>もど</rt><rp>)</rp></ruby>って<ruby>来<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>ないだろう。（如此珍贵的书，一旦脱手就再也无法找回来吧。）"}],"id":"N1-16"},{"title":"17. ～かたがた","blocks":[{"t":"label","label":"接续","text":"名 + かたがた","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + かたがた"},{"t":"label","label":"说明","text":"表示某个行为同时具有两个目的，“顺便……”。","furi":""},{"t":"label","label":"例句","text":"先日のお礼かたがた伺いました。（为了表示对前几天的感谢，顺便过来拜访一下。）","furi":"<ruby>先日<rp>(</rp><rt>せんじつ</rt><rp>)</rp></ruby>のお<ruby>礼<rp>(</rp><rt>れい</rt><rp>)</rp></ruby>かたがた<ruby>伺<rp>(</rp><rt>うかが</rt><rp>)</rp></ruby>いました。（为了表示对前几天的感谢，顺便过来拜访一下。）"}],"id":"N1-17"},{"title":"18. ～かたわら","blocks":[{"t":"label","label":"接续","text":"名 + の／動辞書形 + かたわら","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + の／<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + かたわら"},{"t":"label","label":"说明","text":"表示集中精力做某事的同时顺便做另一件事，“一边……一边……”。","furi":""},{"t":"label","label":"例句","text":"彼は会社勤めのかたわら、福祉活動に積極的に取り組んでいる。（他在上班的同时，还积极参加和福利事业有关的工作。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby><ruby>勤<rp>(</rp><rt>つと</rt><rp>)</rp></ruby>めのかたわら、<ruby>福祉<rp>(</rp><rt>ふくし</rt><rp>)</rp></ruby><ruby>活動<rp>(</rp><rt>かつどう</rt><rp>)</rp></ruby>に<ruby>積極<rp>(</rp><rt>せっきょく</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>に<ruby>取<rp>(</rp><rt>と</rt><rp>)</rp></ruby>り<ruby>組<rp>(</rp><rt>く</rt><rp>)</rp></ruby>んでいる。（他在上班的同时，还积极参加和福利事业有关的工作。）"}],"id":"N1-18"},{"title":"19. ～がてら","blocks":[{"t":"label","label":"接续","text":"動ます形／名 + がてら","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + がてら"},{"t":"label","label":"说明","text":"表示在进行某一动作的同时兼做其他事，“顺便……”。","furi":""},{"t":"label","label":"例句","text":"週末にはドライブがてら、新しい博物館まで行ってみようと思う。（我想周末去兜风的时候，顺便到新开的博物馆去看看。）","furi":"<ruby>週末<rp>(</rp><rt>しゅうまつ</rt><rp>)</rp></ruby>にはドライブがてら、<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しい<ruby>博物館<rp>(</rp><rt>はくぶつかん</rt><rp>)</rp></ruby>まで<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってみようと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>う。（我想周末去兜风的时候，顺便到新开的博物馆去看看。）"}],"id":"N1-19"},{"title":"20. ～が早いか","blocks":[{"t":"label","label":"接续","text":"動辞書形/た形 + が早いか","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + が<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>いか"},{"t":"label","label":"说明","text":"表示前项动作结束后紧接着进行下一个动作，“刚刚……就……”。","furi":""},{"t":"label","label":"例句","text":"授業終了のベルを聞くが早いか、生徒たちは教室を飛び出して行った。（下课铃声刚响，学生们就飞奔出了教室。）","furi":"<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby><ruby>終了<rp>(</rp><rt>しゅうりょう</rt><rp>)</rp></ruby>のベルを<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>くが<ruby>早<rp>(</rp><rt>はや</rt><rp>)</rp></ruby>いか、<ruby>生徒<rp>(</rp><rt>せいと</rt><rp>)</rp></ruby>たちは<ruby>教室<rp>(</rp><rt>きょうしつ</rt><rp>)</rp></ruby>を<ruby>飛<rp>(</rp><rt>と</rt><rp>)</rp></ruby>び<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>して<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>った。（下课铃声刚响，学生们就飞奔出了教室。）"}],"id":"N1-20"},{"title":"21. ～からある／からする／からの","blocks":[{"t":"label","label":"接续","text":"名 + からある／からする／からの","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + からある／からする／からの"},{"t":"label","label":"说明","text":"表示强调，强调大、多、重、长等，“足有……、竟有……、多达……”。","furi":""},{"t":"label","label":"例句","text":"身長2メートルからある男が、突然、目の前に現れた。（一个高达2米的男人突然出现在我面前。）","furi":"<ruby>身長<rp>(</rp><rt>しんちょう</rt><rp>)</rp></ruby>2メートルからある<ruby>男<rp>(</rp><rt>おとこ</rt><rp>)</rp></ruby>が、<ruby>突然<rp>(</rp><rt>とつぜん</rt><rp>)</rp></ruby>、<ruby>目<rp>(</rp><rt>め</rt><rp>)</rp></ruby>の<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>に<ruby>現<rp>(</rp><rt>あらわ</rt><rp>)</rp></ruby>れた。（一个高达2米的男人突然出现在我面前。）"}],"id":"N1-21"},{"title":"22. ～嫌いがある","blocks":[{"t":"label","label":"接续","text":"名 + の／動辞書形 + 嫌いがある","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + の／<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>嫌<rp>(</rp><rt>きら</rt><rp>)</rp></ruby>いがある"},{"t":"label","label":"说明","text":"表示倾向、特征，“有……的倾向、有点……”，多指不好的特征。","furi":""},{"t":"label","label":"例句","text":"人は年をとると、周りの人の忠告に耳を貸さなくなる嫌いがある。（人上了年纪往往很难听进别人的忠告。）","furi":"<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>は<ruby>年<rp>(</rp><rt>とし</rt><rp>)</rp></ruby>をとると、<ruby>周<rp>(</rp><rt>まわ</rt><rp>)</rp></ruby>りの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>の<ruby>忠告<rp>(</rp><rt>ちゅうこく</rt><rp>)</rp></ruby>に<ruby>耳<rp>(</rp><rt>みみ</rt><rp>)</rp></ruby>を<ruby>貸<rp>(</rp><rt>か</rt><rp>)</rp></ruby>さなくなる<ruby>嫌<rp>(</rp><rt>きら</rt><rp>)</rp></ruby>いがある。（人上了年纪往往很难听进别人的忠告。）"}],"id":"N1-22"},{"title":"23. ～極まる／極まりない","blocks":[{"t":"label","label":"接续","text":"ナ形語幹／名 + 極まる／極まりない","furi":"ナ<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + <ruby>極<rp>(</rp><rt>きわ</rt><rp>)</rp></ruby>まる／<ruby>極<rp>(</rp><rt>きわ</rt><rp>)</rp></ruby>まりない"},{"t":"label","label":"说明","text":"表示强烈的语气，“极其……、非常……”。","furi":""},{"t":"label","label":"例句","text":"私は、彼の失礼極まりない態度に我慢できなかった。（他那种无礼的态度实在让我受不了。）","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>は、<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>失礼<rp>(</rp><rt>しつれい</rt><rp>)</rp></ruby><ruby>極<rp>(</rp><rt>きわ</rt><rp>)</rp></ruby>まりない<ruby>態度<rp>(</rp><rt>たいど</rt><rp>)</rp></ruby>に<ruby>我慢<rp>(</rp><rt>がまん</rt><rp>)</rp></ruby>できなかった。（他那种无礼的态度实在让我受不了。）"}],"id":"N1-23"},{"title":"24. ～ごとき／ごとく／ごとし","blocks":[{"t":"sub","text":"(1) 比喻、举例","furi":""},{"t":"label","label":"接续","text":"動辞書形/た形／名 + の + ごとき／ごとく／ごとし","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + の + ごとき／ごとく／ごとし"},{"t":"label","label":"说明","text":"“像……一样、如……”。","furi":""},{"t":"label","label":"例句","text":"「反省」とは、あたかも他人を眺めるがごとく自らを客観的に観察して行う精神活動である。（所谓反省是指像观察他人那样客观地省察自己的精神活动。）","furi":"「<ruby>反省<rp>(</rp><rt>はんせい</rt><rp>)</rp></ruby>」とは、あたかも<ruby>他人<rp>(</rp><rt>たにん</rt><rp>)</rp></ruby>を<ruby>眺<rp>(</rp><rt>なが</rt><rp>)</rp></ruby>めるがごとく<ruby>自<rp>(</rp><rt>みずか</rt><rp>)</rp></ruby>らを<ruby>客観<rp>(</rp><rt>きゃっかん</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>に<ruby>観察<rp>(</rp><rt>かんさつ</rt><rp>)</rp></ruby>して<ruby>行<rp>(</rp><rt>おこな</rt><rp>)</rp></ruby>う<ruby>精神<rp>(</rp><rt>せいしん</rt><rp>)</rp></ruby><ruby>活動<rp>(</rp><rt>かつどう</rt><rp>)</rp></ruby>である。（所谓反省是指像观察他人那样客观地省察自己的精神活动。）"},{"t":"sub","text":"(2) 轻视、自谦","furi":""},{"t":"label","label":"接续","text":"名 + ごとき","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + ごとき"},{"t":"label","label":"说明","text":"“……之类的（又怎能……呢）”。描述别人时表示轻视，指自己时表示自谦。","furi":""},{"t":"label","label":"例句","text":"わたしごとき新人にこんな大切な仕事ができるものかと心配です。（我很担心像我这样的新手能否胜任如此重要的工作。）","furi":"わたしごとき<ruby>新人<rp>(</rp><rt>しんじん</rt><rp>)</rp></ruby>にこんな<ruby>大切<rp>(</rp><rt>たいせつ</rt><rp>)</rp></ruby>な<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>ができるものかと<ruby>心配<rp>(</rp><rt>しんぱい</rt><rp>)</rp></ruby>です。（我很担心像我这样的新手能否胜任如此重要的工作。）"}],"id":"N1-24"},{"title":"25. ～ことだし","blocks":[{"t":"label","label":"接续","text":"動／イ形／ナ形／名の名詞修飾形 + ことだし","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>の<ruby>名詞<rp>(</rp><rt>めいし</rt><rp>)</rp></ruby><ruby>修飾<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ことだし"},{"t":"label","label":"说明","text":"陈述其中一个理由，“也因为……”。","furi":""},{"t":"label","label":"例句","text":"全員そろったことだし、そろそろ会議を始めましょう。（人也到齐了，开始开会吧。）","furi":"<ruby>全員<rp>(</rp><rt>ぜんいん</rt><rp>)</rp></ruby>そろったことだし、そろそろ<ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby>を<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>めましょう。（人也到齐了，开始开会吧。）"}],"id":"N1-25"},{"title":"26. ～こととて","blocks":[{"t":"label","label":"接续","text":"動／イ形／ナ形／名の名詞修飾形 + こととて","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>の<ruby>名詞<rp>(</rp><rt>めいし</rt><rp>)</rp></ruby><ruby>修飾<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + こととて"},{"t":"label","label":"说明","text":"表示原因，“因为……所以……”。正式表达。","furi":""},{"t":"label","label":"例句","text":"連絡もなしにお客様がいらっしゃったが、急なこととて、何のおもてなしもできなかった。（客人事先没有联络突然造访，来不及准备，未能好好招待。）","furi":"<ruby>連絡<rp>(</rp><rt>れんらく</rt><rp>)</rp></ruby>もなしにお<ruby>客様<rp>(</rp><rt>きゃくさま</rt><rp>)</rp></ruby>がいらっしゃったが、<ruby>急<rp>(</rp><rt>きゅう</rt><rp>)</rp></ruby>なこととて、<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>のおもてなしもできなかった。（客人事先没有联络突然造访，来不及准备，未能好好招待。）"}],"id":"N1-26"},{"title":"27. ～ことなしに","blocks":[{"t":"label","label":"接续①","text":"動辞書形 + ことなしに","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ことなしに"},{"t":"label","label":"说明①","text":"表示假定条件，“如果不……就（不能）……”。","furi":""},{"t":"label","label":"例句①","text":"人事部の許可を得ることなしに、勝手に休みを取ることはできない。（没有得到人事部的批准，不能随便请假。）","furi":"<ruby>人事<rp>(</rp><rt>じんじ</rt><rp>)</rp></ruby><ruby>部<rp>(</rp><rt>ぶ</rt><rp>)</rp></ruby>の<ruby>許可<rp>(</rp><rt>きょか</rt><rp>)</rp></ruby>を<ruby>得<rp>(</rp><rt>え</rt><rp>)</rp></ruby>ることなしに、<ruby>勝手<rp>(</rp><rt>かって</rt><rp>)</rp></ruby>に<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>みを<ruby>取<rp>(</rp><rt>と</rt><rp>)</rp></ruby>ることはできない。（没有得到人事部的批准，不能随便请假。）"},{"t":"label","label":"接续②","text":"動辞書形 + ことなしに","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ことなしに"},{"t":"label","label":"说明②","text":"表示附带关系，“没有……就……”。","furi":""},{"t":"label","label":"例句②","text":"彼はあいさつすることなしに、一人で帰国した。（他没有打声招呼就一个人回国了。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>はあいさつすることなしに、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>で<ruby>帰国<rp>(</rp><rt>きこく</rt><rp>)</rp></ruby>した。（他没有打声招呼就一个人回国了。）"}],"id":"N1-27"},{"title":"28. ～ことのないよう","blocks":[{"t":"label","label":"接续","text":"動辞書形 + ことのないよう","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ことのないよう"},{"t":"label","label":"说明","text":"表示目的，为了防止出现前项的情况，“为了不要……，（应该）……”。","furi":""},{"t":"label","label":"例句","text":"二度と同じミスを繰り返すことのないよう、指摘されたことをメモしておく。（为了不要再犯同样的错误，把别人指出的问题记下来。）","furi":"<ruby>二度<rp>(</rp><rt>にど</rt><rp>)</rp></ruby>と<ruby>同<rp>(</rp><rt>おな</rt><rp>)</rp></ruby>じミスを<ruby>繰<rp>(</rp><rt>く</rt><rp>)</rp></ruby>り<ruby>返<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>すことのないよう、<ruby>指摘<rp>(</rp><rt>してき</rt><rp>)</rp></ruby>されたことをメモしておく。（为了不要再犯同样的错误，把别人指出的问题记下来。）"}],"id":"N1-28"},{"title":"29. ～こともあって","blocks":[{"t":"label","label":"接续","text":"動／イ形／ナ形／名の名詞修飾形 + こともあって","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>の<ruby>名詞<rp>(</rp><rt>めいし</rt><rp>)</rp></ruby><ruby>修飾<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + こともあって"},{"t":"label","label":"说明","text":"表示其中的一个原因，“也是由于……、再加上……的原因”。","furi":""},{"t":"label","label":"例句","text":"フランス語を勉強したこともあって、一度はフランスに行ってみたかった。（也许是因为自己之前学过法语，所以很想去一次法国。）","furi":"フランス<ruby>語<rp>(</rp><rt>ご</rt><rp>)</rp></ruby>を<ruby>勉強<rp>(</rp><rt>べんきょう</rt><rp>)</rp></ruby>したこともあって、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>度<rp>(</rp><rt>ど</rt><rp>)</rp></ruby>はフランスに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ってみたかった。（也许是因为自己之前学过法语，所以很想去一次法国。）"}],"id":"N1-29"},{"title":"30. ～始末だ","blocks":[{"t":"label","label":"接续","text":"動辞書形 + 始末だ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>始末<rp>(</rp><rt>しまつ</rt><rp>)</rp></ruby>だ"},{"t":"label","label":"说明","text":"表示结果，“最终（沦落到）……、到了……的地步”，多表示不好的结果。","furi":""},{"t":"label","label":"例句","text":"彼は本当に仕事をする気があるのかどうか、疑いたくなる。遅刻はする、約束は忘れる、ついには居眠り運転で事故を起こす始末だ。（他到底是不是真的想工作，这点很让我怀疑。迟到不说，还忘记约定，最终竟然在开车的时候打盹引发了交通事故。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>本当<rp>(</rp><rt>ほんとう</rt><rp>)</rp></ruby>に<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>をする<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>があるのかどうか、<ruby>疑<rp>(</rp><rt>うたが</rt><rp>)</rp></ruby>いたくなる。<ruby>遅刻<rp>(</rp><rt>ちこく</rt><rp>)</rp></ruby>はする、<ruby>約束<rp>(</rp><rt>やくそく</rt><rp>)</rp></ruby>は<ruby>忘<rp>(</rp><rt>わす</rt><rp>)</rp></ruby>れる、ついには<ruby>居眠<rp>(</rp><rt>いねむ</rt><rp>)</rp></ruby>り<ruby>運転<rp>(</rp><rt>うんてん</rt><rp>)</rp></ruby>で<ruby>事故<rp>(</rp><rt>じこ</rt><rp>)</rp></ruby>を<ruby>起<rp>(</rp><rt>お</rt><rp>)</rp></ruby>こす<ruby>始末<rp>(</rp><rt>しまつ</rt><rp>)</rp></ruby>だ。（他到底是不是真的想工作，这点很让我怀疑。迟到不说，还忘记约定，最终竟然在开车的时候打盹引发了交通事故。）"}],"id":"N1-30"},{"title":"31. ～ずくめ","blocks":[{"t":"label","label":"接续","text":"名 + ずくめ","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + ずくめ"},{"t":"label","label":"说明","text":"表示状态，“尽是……、全是……、无一例外……”。","furi":""},{"t":"label","label":"例句","text":"うちの学校は規則ずくめで、窮屈でしかたがない。（我们学校规矩太多让人觉得太受束缚。）","furi":"うちの<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>は<ruby>規則<rp>(</rp><rt>きそく</rt><rp>)</rp></ruby>ずくめで、<ruby>窮屈<rp>(</rp><rt>きゅうくつ</rt><rp>)</rp></ruby>でしかたがない。（我们学校规矩太多让人觉得太受束缚。）"}],"id":"N1-31"},{"title":"32. ～ずじまいだ","blocks":[{"t":"label","label":"接续","text":"動ない形 + ずじまいだ（する→せずじまいだ）","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ずじまいだ（する→せずじまいだ）"},{"t":"label","label":"说明","text":"表示结果，“最终未能……、结果还是没能……”。表达遗憾、后悔。","furi":""},{"t":"label","label":"例句","text":"いなくなったペットを懸命に探したが、結局、その行方はわからずじまいだった。（到处寻找走丢的宠物，最终还是没有找到。）","furi":"いなくなったペットを<ruby>懸命<rp>(</rp><rt>けんめい</rt><rp>)</rp></ruby>に<ruby>探<rp>(</rp><rt>さが</rt><rp>)</rp></ruby>したが、<ruby>結局<rp>(</rp><rt>けっきょく</rt><rp>)</rp></ruby>、その<ruby>行方<rp>(</rp><rt>ゆくえ</rt><rp>)</rp></ruby>はわからずじまいだった。（到处寻找走丢的宠物，最终还是没有找到。）"}],"id":"N1-32"},{"title":"33. ～ずにはおかない／ないではおかない","blocks":[{"t":"label","label":"接续","text":"動ない形 + ずにはおかない／ないではおかない（する→せずにはおかない）","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ずにはおかない／ないではおかない（する→せずにはおかない）"},{"t":"label","label":"说明","text":"表示强烈的意志或评价，“肯定会使……、必然会引起……、一定会让……”。","furi":""},{"t":"label","label":"例句","text":"この映画は評判が高く、見る者を感動させずにはおかないだろう。（这部电影深受好评，一定会使观众感动。）","furi":"この<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>は<ruby>評判<rp>(</rp><rt>ひょうばん</rt><rp>)</rp></ruby>が<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>く、<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>る<ruby>者<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>を<ruby>感動<rp>(</rp><rt>かんどう</rt><rp>)</rp></ruby>させずにはおかないだろう。（这部电影深受好评，一定会使观众感动。）"}],"id":"N1-33"},{"title":"34. ～ずにはすまない／ないではすまない","blocks":[{"t":"label","label":"接续","text":"動ない形 + ずにはすまない／ないではすまない（する→せずにはすまない）","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ずにはすまない／ないではすまない（する→せずにはすまない）"},{"t":"label","label":"说明","text":"表示出于责任感或社会常识必须要做某事，“一定要……、不……的话（心里过意不去）”。","furi":""},{"t":"label","label":"例句","text":"自分が悪いことをしたんだから、謝らないではすまないだろう。（自己做了错事不道歉不行。）","furi":"<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>が<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>いことをしたんだから、<ruby>謝<rp>(</rp><rt>あやま</rt><rp>)</rp></ruby>らないではすまないだろう。（自己做了错事不道歉不行。）"}],"id":"N1-34"},{"title":"35. ～術がない","blocks":[{"t":"label","label":"接续","text":"動辞書形 + 術がない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>術<rp>(</rp><rt>じゅつ</rt><rp>)</rp></ruby>がない"},{"t":"label","label":"说明","text":"表示无可奈何，“没有办法做到……”。","furi":""},{"t":"label","label":"例句","text":"ことここに至っては、もう成す術がない。（事已至此，没有办法了。）","furi":"ことここに<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>っては、もう<ruby>成<rp>(</rp><rt>な</rt><rp>)</rp></ruby>す<ruby>術<rp>(</rp><rt>じゅつ</rt><rp>)</rp></ruby>がない。（事已至此，没有办法了。）"}],"id":"N1-35"},{"title":"36. ～（で）すら","blocks":[{"t":"label","label":"接续","text":"名 +（で）すら","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> +（で）すら"},{"t":"label","label":"说明","text":"表示强调，“甚至……、连……”。","furi":""},{"t":"label","label":"例句","text":"あの患者は重い病気のため、一人では食事すらできない。（那位患者的病情很重，甚至没法自己进食。）","furi":"あの<ruby>患者<rp>(</rp><rt>かんじゃ</rt><rp>)</rp></ruby>は<ruby>重<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>い<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>のため、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>では<ruby>食事<rp>(</rp><rt>しょくじ</rt><rp>)</rp></ruby>すらできない。（那位患者的病情很重，甚至没法自己进食。）"}],"id":"N1-36"},{"title":"37. ～そばから","blocks":[{"t":"label","label":"接续","text":"動辞書形/た形 + そばから","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + そばから"},{"t":"label","label":"说明","text":"表示一种状态的重复出现，“刚……就……”。","furi":""},{"t":"label","label":"例句","text":"私は語学の才能がないようで、新しい言葉を習うそばから忘れてしまう。（我可能是没有语言天赋，新单词总是学了就忘。）","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>は<ruby>語学<rp>(</rp><rt>ごがく</rt><rp>)</rp></ruby>の<ruby>才能<rp>(</rp><rt>さいのう</rt><rp>)</rp></ruby>がないようで、<ruby>新<rp>(</rp><rt>あたら</rt><rp>)</rp></ruby>しい<ruby>言葉<rp>(</rp><rt>ことば</rt><rp>)</rp></ruby>を<ruby>習<rp>(</rp><rt>なら</rt><rp>)</rp></ruby>うそばから<ruby>忘<rp>(</rp><rt>わす</rt><rp>)</rp></ruby>れてしまう。（我可能是没有语言天赋，新单词总是学了就忘。）"}],"id":"N1-37"},{"title":"38. ～そびれる","blocks":[{"t":"label","label":"接续","text":"動ます形 + そびれる","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + そびれる"},{"t":"label","label":"说明","text":"表示错过机会最终未能做成某事，“错过……最终没能……”。","furi":""},{"t":"label","label":"例句","text":"ぜひ見ようと思っていた映画だったのに、忙しくて行きそびれた。（本来很想看的一部电影因为太忙没有去成。）","furi":"ぜひ<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ようと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>っていた<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>だったのに、<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しくて<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>きそびれた。（本来很想看的一部电影因为太忙没有去成。）"}],"id":"N1-38"},{"title":"39. （ひとり）～だけでなく／のみならず","blocks":[{"t":"label","label":"接续","text":"ひとり + 名／動・イ形・ナ形の名詞修飾形 + だけでなく／のみならず","furi":"ひとり + <ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>／<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>・イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>・ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>の<ruby>名詞<rp>(</rp><rt>めいし</rt><rp>)</rp></ruby><ruby>修飾<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + だけでなく／のみならず"},{"t":"label","label":"说明","text":"表示不限定，“不仅……（而且）……”。「ひとり」表示强调，可省略。","furi":"<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>不<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby><ruby>限定<rp>(</rp><rt>げんてい</rt><rp>)</rp></ruby>，“<ruby>不<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby><ruby>仅<rp>(</rp><rt>仅</rt><rp>)</rp></ruby>……（<ruby>而<rp>(</rp><rt>而</rt><rp>)</rp></ruby><ruby>且<rp>(</rp><rt>且</rt><rp>)</rp></ruby>）……”。「ひとり」<ruby>表示<rp>(</rp><rt>ひょうじ</rt><rp>)</rp></ruby><ruby>强<rp>(</rp><rt>强</rt><rp>)</rp></ruby><ruby>调<rp>(</rp><rt>调</rt><rp>)</rp></ruby>，<ruby>可<rp>(</rp><rt>か</rt><rp>)</rp></ruby><ruby>省略<rp>(</rp><rt>しょうりゃく</rt><rp>)</rp></ruby>。"},{"t":"label","label":"例句","text":"公共の場所でタバコを吸うのはひとり本人にとって有害であるだけでなく、周りの人にとっても迷惑なものである。（在公共场所吸烟不仅有害本人身体健康，也会影响到周围的人。）","furi":"<ruby>公共<rp>(</rp><rt>こうきょう</rt><rp>)</rp></ruby>の<ruby>場所<rp>(</rp><rt>ばしょ</rt><rp>)</rp></ruby>でタバコを<ruby>吸<rp>(</rp><rt>す</rt><rp>)</rp></ruby>うのはひとり<ruby>本人<rp>(</rp><rt>ほんにん</rt><rp>)</rp></ruby>にとって<ruby>有害<rp>(</rp><rt>ゆうがい</rt><rp>)</rp></ruby>であるだけでなく、<ruby>周<rp>(</rp><rt>まわ</rt><rp>)</rp></ruby>りの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>にとっても<ruby>迷惑<rp>(</rp><rt>めいわく</rt><rp>)</rp></ruby>なものである。（在公共场所吸烟不仅有害本人身体健康，也会影响到周围的人。）"}],"id":"N1-39"},{"title":"40. ～だけましだ","blocks":[{"t":"label","label":"接续","text":"動辞書形/た形／イ形／名 + だけましだ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + だけましだ"},{"t":"label","label":"说明","text":"表示评价不好的事情时庆幸没有更糟，“幸好……、好在……”。","furi":""},{"t":"label","label":"例句","text":"泥棒にかなりの額の現金をとられはしたが、命を取られなかっただけましだ。（被小偷偷走了很大金额的现金，但好在没有危及性命。）","furi":"<ruby>泥棒<rp>(</rp><rt>どろぼう</rt><rp>)</rp></ruby>にかなりの<ruby>額<rp>(</rp><rt>がく</rt><rp>)</rp></ruby>の<ruby>現金<rp>(</rp><rt>げんきん</rt><rp>)</rp></ruby>をとられはしたが、<ruby>命<rp>(</rp><rt>いのち</rt><rp>)</rp></ruby>を<ruby>取<rp>(</rp><rt>と</rt><rp>)</rp></ruby>られなかっただけましだ。（被小偷偷走了很大金额的现金，但好在没有危及性命。）"}],"id":"N1-40"},{"title":"41. ただ～のみだ","blocks":[{"t":"label","label":"接续","text":"ただ + 動辞書形/名 + のみだ","furi":"ただ + <ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby> + のみだ"},{"t":"label","label":"说明","text":"表示限定，“只能……、只好是……”。","furi":""},{"t":"label","label":"例句","text":"今はただ事件の行方不明者の無事を祈るのみだ。（现在只能为事故中的失踪者祈祷。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>はただ<ruby>事件<rp>(</rp><rt>じけん</rt><rp>)</rp></ruby>の<ruby>行方<rp>(</rp><rt>ゆくえ</rt><rp>)</rp></ruby><ruby>不明<rp>(</rp><rt>ふめい</rt><rp>)</rp></ruby><ruby>者<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>の<ruby>無事<rp>(</rp><rt>ぶじ</rt><rp>)</rp></ruby>を<ruby>祈<rp>(</rp><rt>いの</rt><rp>)</rp></ruby>るのみだ。（现在只能为事故中的失踪者祈祷。）"}],"id":"N1-41"},{"title":"42. ただ～のみならず／のみか","blocks":[{"t":"label","label":"接续","text":"ただ + 動／イ形／ナ形の名詞修飾形 + のみならず／のみか","furi":"ただ + <ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>の<ruby>名詞<rp>(</rp><rt>めいし</rt><rp>)</rp></ruby><ruby>修飾<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + のみならず／のみか"},{"t":"label","label":"说明","text":"“不仅……（而且）……”。","furi":""},{"t":"label","label":"例句","text":"この映画の主人公はただ勇敢であるのみならず、優しい心の持ち主でもある。（这部电影的主人公不仅勇敢还很善良。）","furi":"この<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>の<ruby>主人公<rp>(</rp><rt>しゅじんこう</rt><rp>)</rp></ruby>はただ<ruby>勇敢<rp>(</rp><rt>ゆうかん</rt><rp>)</rp></ruby>であるのみならず、<ruby>優<rp>(</rp><rt>やさ</rt><rp>)</rp></ruby>しい<ruby>心<rp>(</rp><rt>こころ</rt><rp>)</rp></ruby>の<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>ち<ruby>主<rp>(</rp><rt>ぬし</rt><rp>)</rp></ruby>でもある。（这部电影的主人公不仅勇敢还很善良。）"}],"id":"N1-42"},{"title":"43. ～たところで","blocks":[{"t":"label","label":"接续","text":"動た形 + ところで","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところで"},{"t":"label","label":"说明","text":"表示假定条件的逆接，“即使……也（未必）……”。","furi":""},{"t":"label","label":"例句","text":"社長一人が必死になったところで、この会社が大きく変わるとは思えない。（就算社长一个人很努力，公司也难以发展壮大。）","furi":"<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby><ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>が<ruby>必死<rp>(</rp><rt>ひっし</rt><rp>)</rp></ruby>になったところで、この<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>が<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きく<ruby>変<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わるとは<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>えない。（就算社长一个人很努力，公司也难以发展壮大。）"}],"id":"N1-43"},{"title":"44. ～だに","blocks":[{"t":"label","label":"接续","text":"動辞書形 + だに","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + だに"},{"t":"label","label":"说明","text":"表示强调，“就连……、压根（没）……、连……都……”。","furi":""},{"t":"label","label":"例句","text":"地震のことなど想像するだに恐ろしい。（光是想一想发生地震就觉得很可怕。）","furi":"<ruby>地震<rp>(</rp><rt>じしん</rt><rp>)</rp></ruby>のことなど<ruby>想像<rp>(</rp><rt>そうぞう</rt><rp>)</rp></ruby>するだに<ruby>恐<rp>(</rp><rt>おそ</rt><rp>)</rp></ruby>ろしい。（光是想一想发生地震就觉得很可怕。）"}],"id":"N1-44"},{"title":"45. ～ためしがない","blocks":[{"t":"label","label":"接续","text":"動た形 + ためしがない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ためしがない"},{"t":"label","label":"说明","text":"表示从未有过某种经历，“从来没有……、不曾……”，暗含不满。","furi":""},{"t":"label","label":"例句","text":"宝くじなんて、一度も当たったためしがない。（彩票我是一次也没中过。）","furi":"<ruby>宝<rp>(</rp><rt>たから</rt><rp>)</rp></ruby>くじなんて、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>度<rp>(</rp><rt>ど</rt><rp>)</rp></ruby>も<ruby>当<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>たったためしがない。（彩票我是一次也没中过。）"}],"id":"N1-45"},{"title":"46. ～たらきりがない／ばきりがない","blocks":[{"t":"label","label":"接续","text":"動ば形 + きりがない／動た形 + らきりがない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ば<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + きりがない／<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + らきりがない"},{"t":"label","label":"说明","text":"“若是……的话，就没完没了”。","furi":""},{"t":"label","label":"例句","text":"隣のおばさんは息子さんの自慢話を言い出したらきりがない。（隔壁家的阿姨一夸起自己的儿子就没完没了。）","furi":"<ruby>隣<rp>(</rp><rt>となり</rt><rp>)</rp></ruby>のおばさんは<ruby>息子<rp>(</rp><rt>むすこ</rt><rp>)</rp></ruby>さんの<ruby>自慢<rp>(</rp><rt>じまん</rt><rp>)</rp></ruby><ruby>話<rp>(</rp><rt>ばなし</rt><rp>)</rp></ruby>を<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>い<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>したらきりがない。（隔壁家的阿姨一夸起自己的儿子就没完没了。）"}],"id":"N1-46"},{"title":"47. ～たりとも","blocks":[{"t":"label","label":"接续","text":"名 + たりとも","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + たりとも"},{"t":"label","label":"说明","text":"表示强调，“就连……也不能”。","furi":""},{"t":"label","label":"例句","text":"募金で集めたお金は一円たりとも無駄にできない。（募集的资金一块钱也不能浪费。）","furi":"<ruby>募金<rp>(</rp><rt>ぼきん</rt><rp>)</rp></ruby>で<ruby>集<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>めたお<ruby>金<rp>(</rp><rt>かね</rt><rp>)</rp></ruby>は<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>円<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>たりとも<ruby>無駄<rp>(</rp><rt>むだ</rt><rp>)</rp></ruby>にできない。（募集的资金一块钱也不能浪费。）"}],"id":"N1-47"},{"title":"48. ～たる／たるもの","blocks":[{"t":"label","label":"接续","text":"名 + たる／たるもの","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + たる／たるもの"},{"t":"label","label":"说明","text":"表示对某种特殊身份或职业者的要求和希望，“作为……，（应该）……”。","furi":""},{"t":"label","label":"例句","text":"警官たる者、そのような犯罪にかかわってはいけない。（作为警官，不能牵涉到那样的犯罪案件中。）","furi":"<ruby>警官<rp>(</rp><rt>けいかん</rt><rp>)</rp></ruby>たる<ruby>者<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>、そのような<ruby>犯罪<rp>(</rp><rt>はんざい</rt><rp>)</rp></ruby>にかかわってはいけない。（作为警官，不能牵涉到那样的犯罪案件中。）"}],"id":"N1-48"},{"title":"49. ～つ～つ","blocks":[{"t":"label","label":"接续","text":"動ます形 + つ + 動ます形 + つ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + つ + <ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + つ"},{"t":"label","label":"说明","text":"表示两个动作交替进行，“一会儿……一会儿……”。","furi":""},{"t":"label","label":"例句","text":"ラッシュアワーの時間なので、地下鉄の車内は乗客で押しつ押されつしている。（因为是上下班高峰时间，地铁车厢内乘客们挤来挤去。）","furi":"ラッシュアワーの<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>なので、<ruby>地下鉄<rp>(</rp><rt>ちかてつ</rt><rp>)</rp></ruby>の<ruby>車内<rp>(</rp><rt>しゃない</rt><rp>)</rp></ruby>は<ruby>乗客<rp>(</rp><rt>じょうきゃく</rt><rp>)</rp></ruby>で<ruby>押<rp>(</rp><rt>お</rt><rp>)</rp></ruby>しつ<ruby>押<rp>(</rp><rt>お</rt><rp>)</rp></ruby>されつしている。（因为是上下班高峰时间，地铁车厢内乘客们挤来挤去。）"}],"id":"N1-49"},{"title":"50. ～っぱなし","blocks":[{"t":"label","label":"接续","text":"動ます形 + っぱなし","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + っぱなし"},{"t":"label","label":"说明①","text":"接他动词，表示本该做的事情却不去做，“放任……不管”。","furi":""},{"t":"label","label":"例句①","text":"水を出しっぱなしにして、歯を磨くのはもったいないですよ。（刷牙的时候一直开着水龙头的话很浪费水。）","furi":"<ruby>水<rp>(</rp><rt>みず</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>しっぱなしにして、<ruby>歯<rp>(</rp><rt>は</rt><rp>)</rp></ruby>を<ruby>磨<rp>(</rp><rt>みが</rt><rp>)</rp></ruby>くのはもったいないですよ。（刷牙的时候一直开着水龙头的话很浪费水。）"},{"t":"label","label":"说明②","text":"接自动词，表示某个状态的持续，“一直……”。","furi":""},{"t":"label","label":"例句②","text":"電車の中はあいにく空席がなくて、ずっと立ちっぱなしだった。（刚好没有空位置，所以在电车中一直站着。）","furi":"<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>の<ruby>中<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>はあいにく<ruby>空席<rp>(</rp><rt>くうせき</rt><rp>)</rp></ruby>がなくて、ずっと<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>ちっぱなしだった。（刚好没有空位置，所以在电车中一直站着。）"}],"id":"N1-50"},{"title":"51. ～であれ／であろうと","blocks":[{"t":"label","label":"接续","text":"名 + であれ／であろうと","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + であれ／であろうと"},{"t":"label","label":"说明","text":"表示假定条件的逆接，“无论……如何，都（不）……”。","furi":""},{"t":"label","label":"例句","text":"うそをつくとは、どんな理由であれ、許されない。（不论出于什么理由都不允许撒谎。）","furi":"うそをつくとは、どんな<ruby>理由<rp>(</rp><rt>りゆう</rt><rp>)</rp></ruby>であれ、<ruby>許<rp>(</rp><rt>ゆる</rt><rp>)</rp></ruby>されない。（不论出于什么理由都不允许撒谎。）"}],"id":"N1-51"},{"title":"52. ～であれ～であれ／～であろうと～であろうと／～だろうが～だろうが","blocks":[{"t":"label","label":"接续","text":"名 + であれ／であろうと／だろうが + 名 + であれ／であろうと／だろうが","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + であれ／であろうと／だろうが + <ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + であれ／であろうと／だろうが"},{"t":"label","label":"说明","text":"表示假定条件的逆接，“无论是……还是……，都……”。","furi":""},{"t":"label","label":"例句","text":"正社員であれ、パートであれ、仕事に対する責任は変わらない。（正式员工也好，临时工也好，对工作的责任是一样的。）","furi":"<ruby>正社員<rp>(</rp><rt>せいしゃいん</rt><rp>)</rp></ruby>であれ、パートであれ、<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>に<ruby>対<rp>(</rp><rt>たい</rt><rp>)</rp></ruby>する<ruby>責任<rp>(</rp><rt>せきにん</rt><rp>)</rp></ruby>は<ruby>変<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わらない。（正式员工也好，临时工也好，对工作的责任是一样的。）"}],"id":"N1-52"},{"title":"53. ～てからというもの","blocks":[{"t":"label","label":"接续","text":"動て形 + からというもの","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + からというもの"},{"t":"label","label":"说明","text":"表示自从某件事发生后，后项发生了很大的变化，“自从……之后”。","furi":""},{"t":"label","label":"例句","text":"彼は結婚してからというもの、人が変わったようにまじめになった。（他自从结婚后就像变了一个人似的，认真了起来。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>結婚<rp>(</rp><rt>けっこん</rt><rp>)</rp></ruby>してからというもの、<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>が<ruby>変<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わったようにまじめになった。（他自从结婚后就像变了一个人似的，认真了起来。）"}],"id":"N1-53"},{"title":"54. ～てしかるべきだ","blocks":[{"t":"label","label":"接续","text":"動て形 + しかるべきだ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + しかるべきだ"},{"t":"label","label":"说明","text":"表示做某事本是理所应当的，“理应……、应当……”。","furi":""},{"t":"label","label":"例句","text":"先輩にはそれ相応の敬意を払ってしかるべきだ。（对前辈应当有应有的尊重。）","furi":"<ruby>先輩<rp>(</rp><rt>せんぱい</rt><rp>)</rp></ruby>にはそれ<ruby>相応<rp>(</rp><rt>そうおう</rt><rp>)</rp></ruby>の<ruby>敬意<rp>(</rp><rt>けいい</rt><rp>)</rp></ruby>を<ruby>払<rp>(</rp><rt>はら</rt><rp>)</rp></ruby>ってしかるべきだ。（对前辈应当有应有的尊重。）"}],"id":"N1-54"},{"title":"55. ～でなくてなんだろう","blocks":[{"t":"label","label":"接续","text":"名 + でなくてなんだろう","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + でなくてなんだろう"},{"t":"label","label":"说明","text":"表示强调，“不是……又是什么呢、这就是……”。","furi":""},{"t":"label","label":"例句","text":"彼女のためなら何でもする。これが愛でなくてなんだろう。（只要是为了她什么事情都愿意做，这不是爱又是什么呢？）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>のためなら<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>でもする。これが<ruby>愛<rp>(</rp><rt>め</rt><rp>)</rp></ruby>でなくてなんだろう。（只要是为了她什么事情都愿意做，这不是爱又是什么呢？）"}],"id":"N1-55"},{"title":"56. ～ではあるまいし／じゃあるまいし","blocks":[{"t":"label","label":"接续","text":"動／イ形／ナ形の名詞修飾形 + ではあるまいし／じゃあるまいし","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>の<ruby>名詞<rp>(</rp><rt>めいし</rt><rp>)</rp></ruby><ruby>修飾<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ではあるまいし／じゃあるまいし"},{"t":"label","label":"说明","text":"表示原因、理由，“又不是……（所以没必要）……”。","furi":""},{"t":"label","label":"例句","text":"子どもではあるまいし、もう少し冷静に話し合うべきだ。（又不是小孩子，所以讲话时要更冷静一些。）","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもではあるまいし、もう<ruby>少<rp>(</rp><rt>すこ</rt><rp>)</rp></ruby>し<ruby>冷静<rp>(</rp><rt>れいせい</rt><rp>)</rp></ruby>に<ruby>話<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>し<ruby>合<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>うべきだ。（又不是小孩子，所以讲话时要更冷静一些。）"}],"id":"N1-56"},{"title":"57. ～てはかなわない","blocks":[{"t":"label","label":"接续","text":"動て形 + はかなわない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + はかなわない"},{"t":"label","label":"说明","text":"强调主观感受，“……的话让人受不了、如果……的话就没有办法了”。","furi":""},{"t":"label","label":"例句","text":"仕事が好きだからといって、毎日残業続きではかなわない。（虽然喜欢这份工作，但是每天加班的话还是会受不了。）","furi":"<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>が<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きだからといって、<ruby>毎日<rp>(</rp><rt>まいにち</rt><rp>)</rp></ruby><ruby>残業<rp>(</rp><rt>ざんぎょう</rt><rp>)</rp></ruby><ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>きではかなわない。（虽然喜欢这份工作，但是每天加班的话还是会受不了。）"}],"id":"N1-57"},{"title":"58. ～ては～ては","blocks":[{"t":"label","label":"接续","text":"動て形 + は + 動て形 + は","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + は + <ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + は"},{"t":"label","label":"说明","text":"表示动作或现象的重复出现，“……又……，……又……”。","furi":""},{"t":"label","label":"例句","text":"休み中、食べては眠り、食べては眠りの連続で、すっかり太ってしまった。（休假的时候，一直过着吃了睡，睡了吃的生活，胖了很多。）","furi":"<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>み<ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby>、<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べては<ruby>眠<rp>(</rp><rt>ねむ</rt><rp>)</rp></ruby>り、<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べては<ruby>眠<rp>(</rp><rt>ねむ</rt><rp>)</rp></ruby>りの<ruby>連続<rp>(</rp><rt>れんぞく</rt><rp>)</rp></ruby>で、すっかり<ruby>太<rp>(</rp><rt>ふと</rt><rp>)</rp></ruby>ってしまった。（休假的时候，一直过着吃了睡，睡了吃的生活，胖了很多。）"}],"id":"N1-58"},{"title":"59. ～て憚らない","blocks":[{"t":"label","label":"接续","text":"動て形 + はばからない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + はばからない"},{"t":"label","label":"说明","text":"用来描述他人的言论，“公然断言……、肆无忌惮地说……”。","furi":""},{"t":"label","label":"例句","text":"その新人候補は、今回の選挙に必ず当選してみせると断言してはばからない。（初登政治舞台的人竟然大胆宣称自己一定会在选举中胜出。）","furi":"その<ruby>新人<rp>(</rp><rt>しんじん</rt><rp>)</rp></ruby><ruby>候補<rp>(</rp><rt>こうほ</rt><rp>)</rp></ruby>は、<ruby>今回<rp>(</rp><rt>こんかい</rt><rp>)</rp></ruby>の<ruby>選挙<rp>(</rp><rt>せんきょ</rt><rp>)</rp></ruby>に<ruby>必<rp>(</rp><rt>かなら</rt><rp>)</rp></ruby>ず<ruby>当選<rp>(</rp><rt>とうせん</rt><rp>)</rp></ruby>してみせると<ruby>断言<rp>(</rp><rt>だんげん</rt><rp>)</rp></ruby>してはばからない。（初登政治舞台的人竟然大胆宣称自己一定会在选举中胜出。）"}],"id":"N1-59"},{"title":"60. ～てはやりきれない","blocks":[{"t":"label","label":"接续","text":"動て形 + はやりきれない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + はやりきれない"},{"t":"label","label":"说明","text":"强调主观感受，表示某事无法忍受，“……的话让人受不了、……的话接受不了”。","furi":""},{"t":"label","label":"例句","text":"こう寒くてはやりきれない。（这么冷真让人受不了。）","furi":"こう<ruby>寒<rp>(</rp><rt>さむ</rt><rp>)</rp></ruby>くてはやりきれない。（这么冷真让人受不了。）"}],"id":"N1-60"},{"title":"61. ～てまで","blocks":[{"t":"label","label":"接续","text":"動て形 + まで","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + まで"},{"t":"label","label":"说明","text":"表示程度，“甚至不惜……”，为达到目的做出超乎寻常的事情。","furi":""},{"t":"label","label":"例句","text":"自分を信じて努力してきたのだから、周りの評価を気にして辞めてしまう必要はない。（既然相信自己努力过来了，就没有必要为了别人的评价而辞掉工作。）","furi":"<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>を<ruby>信<rp>(</rp><rt>しん</rt><rp>)</rp></ruby>じて<ruby>努力<rp>(</rp><rt>どりょく</rt><rp>)</rp></ruby>してきたのだから、<ruby>周<rp>(</rp><rt>まわ</rt><rp>)</rp></ruby>りの<ruby>評価<rp>(</rp><rt>ひょうか</rt><rp>)</rp></ruby>を<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>にして<ruby>辞<rp>(</rp><rt>や</rt><rp>)</rp></ruby>めてしまう<ruby>必要<rp>(</rp><rt>ひつよう</rt><rp>)</rp></ruby>はない。（既然相信自己努力过来了，就没有必要为了别人的评价而辞掉工作。）"}],"id":"N1-61"},{"title":"62. ～ても差し支えない","blocks":[{"t":"label","label":"接续","text":"動て形 + も差し支えない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + も<ruby>差<rp>(</rp><rt>さ</rt><rp>)</rp></ruby>し<ruby>支<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>えない"},{"t":"label","label":"说明","text":"表示没有影响、不妨碍，“即使……也没有关系”。","furi":""},{"t":"label","label":"例句","text":"この書類は部内で使うから、判子を押さなくても差し支えない。（这份文件只在部门内使用，不盖章也没有关系。）","furi":"この<ruby>書類<rp>(</rp><rt>しょるい</rt><rp>)</rp></ruby>は<ruby>部内<rp>(</rp><rt>ぶない</rt><rp>)</rp></ruby>で<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>うから、<ruby>判子<rp>(</rp><rt>はんこ</rt><rp>)</rp></ruby>を<ruby>押<rp>(</rp><rt>お</rt><rp>)</rp></ruby>さなくても<ruby>差<rp>(</rp><rt>さ</rt><rp>)</rp></ruby>し<ruby>支<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>えない。（这份文件只在部门内使用，不盖章也没有关系。）"}],"id":"N1-62"},{"title":"63. ～でもしたら","blocks":[{"t":"label","label":"接续","text":"動ます形 + でもしたら","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + でもしたら"},{"t":"label","label":"说明","text":"表示假设，举出不好的例子，“一旦……的话（就糟了）”。","furi":""},{"t":"label","label":"例句","text":"おじいさんの古時計、触らないで。壊しでもしたら大変なことになるからね。（爷爷的旧手表，你可别碰。要是弄坏了可就糟了。）","furi":"おじいさんの<ruby>古<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>時計<rp>(</rp><rt>とけい</rt><rp>)</rp></ruby>、<ruby>触<rp>(</rp><rt>さわ</rt><rp>)</rp></ruby>らないで。<ruby>壊<rp>(</rp><rt>こわ</rt><rp>)</rp></ruby>しでもしたら<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>なことになるからね。（爷爷的旧手表，你可别碰。要是弄坏了可就糟了。）"}],"id":"N1-63"},{"title":"64. ～ても知らない","blocks":[{"t":"label","label":"接续","text":"動て形 + も知らない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + も<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>らない"},{"t":"label","label":"说明","text":"表示警告，“如果（你）继续……的话，我可不管了”。","furi":""},{"t":"label","label":"例句","text":"授業をサボってばかりいては、試験に落ちても知らない。（一直逃课的话，考试不及格我可不管了。）","furi":"<ruby>授業<rp>(</rp><rt>じゅぎょう</rt><rp>)</rp></ruby>をサボってばかりいては、<ruby>試験<rp>(</rp><rt>しけん</rt><rp>)</rp></ruby>に<ruby>落<rp>(</rp><rt>お</rt><rp>)</rp></ruby>ちても<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>らない。（一直逃课的话，考试不及格我可不管了。）"}],"id":"N1-64"},{"title":"65. ～でもって","blocks":[{"t":"label","label":"接续","text":"名 + でもって","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + でもって"},{"t":"label","label":"说明","text":"表示手段和方法，“用……、以……、凭借……”。多用于口语。","furi":""},{"t":"label","label":"例句","text":"言葉だけでは足りない。行動でもって証明してください。（光说是不行的，要通过行动来证明。）","furi":"<ruby>言葉<rp>(</rp><rt>ことば</rt><rp>)</rp></ruby>だけでは<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>りない。<ruby>行動<rp>(</rp><rt>こうどう</rt><rp>)</rp></ruby>でもって<ruby>証明<rp>(</rp><rt>しょうめい</rt><rp>)</rp></ruby>してください。（光说是不行的，要通过行动来证明。）"}],"id":"N1-65"},{"title":"66. ～てもどうにもならない／てもどうなるものでもない","blocks":[{"t":"label","label":"接续","text":"動て形 + も + どうにもならない／どうなるものでもない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + も + どうにもならない／どうなるものでもない"},{"t":"label","label":"说明","text":"表示假定条件的逆接，“即使……也无济于事”。","furi":""},{"t":"label","label":"例句","text":"過ぎたことを後悔してもどうにもならない。（已经过去的事情，即使后悔也没用。）","furi":"<ruby>過<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ぎたことを<ruby>後悔<rp>(</rp><rt>こうかい</rt><rp>)</rp></ruby>してもどうにもならない。（已经过去的事情，即使后悔也没用。）"}],"id":"N1-66"},{"title":"67. ～てもともとだ","blocks":[{"t":"label","label":"接续","text":"動て形 + もともとだ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + もともとだ"},{"t":"label","label":"说明","text":"表示内心的想法，“……的话也无所谓、原本也没有抱太大希望……”。","furi":""},{"t":"label","label":"例句","text":"だめでもともとだから、思い切って彼女に告白してみた。（就算被拒绝也无所谓，就试着鼓起勇气跟她告白了。）","furi":"だめでもともとだから、<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>い<ruby>切<rp>(</rp><rt>き</rt><rp>)</rp></ruby>って<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>に<ruby>告白<rp>(</rp><rt>こくはく</rt><rp>)</rp></ruby>してみた。（就算被拒绝也无所谓，就试着鼓起勇气跟她告白了。）"}],"id":"N1-67"},{"title":"68. ～でも何でもない／～くもなんともない","blocks":[{"t":"label","label":"接续","text":"名／ナ形語幹 + でも何でもない／イ形―く + もなんともない","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby> + でも<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>でもない／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>―く + もなんともない"},{"t":"label","label":"说明","text":"表示强烈的否定，“一点也不……、根本不……”。","furi":""},{"t":"label","label":"例句","text":"彼は病気でも何でもない。ただずる休みしたいだけかもしれない。（他根本不是生病了，也许只是想偷懒休息一下罢了。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>でも<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>でもない。ただずる<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>みしたいだけかもしれない。（他根本不是生病了，也许只是想偷懒休息一下罢了。）"}],"id":"N1-68"},{"title":"69. ～ても始まらない","blocks":[{"t":"label","label":"接续","text":"動て形 + も始まらない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + も<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>まらない"},{"t":"label","label":"说明","text":"表示假定条件的逆接，“即使……也无济于事”。","furi":""},{"t":"label","label":"例句","text":"どうにもならないことを悩んでいても始まらない。（为这种没有办法的事情烦恼也没用。）","furi":"どうにもならないことを<ruby>悩<rp>(</rp><rt>なや</rt><rp>)</rp></ruby>んでいても<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>まらない。（为这种没有办法的事情烦恼也没用。）"}],"id":"N1-69"},{"title":"70. ～てやまない","blocks":[{"t":"label","label":"接续","text":"動て形 + やまない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>て<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + やまない"},{"t":"label","label":"说明","text":"表达强烈的愿望和心情，“……不已、非常……、衷心地……”。","furi":""},{"t":"label","label":"例句","text":"結婚する二人の今後の幸せを願ってやまない。（衷心祝愿二位婚后生活幸福。）","furi":"<ruby>結婚<rp>(</rp><rt>けっこん</rt><rp>)</rp></ruby>する<ruby>二<rp>(</rp><rt>に</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>の<ruby>今後<rp>(</rp><rt>こんご</rt><rp>)</rp></ruby>の<ruby>幸<rp>(</rp><rt>しあわ</rt><rp>)</rp></ruby>せを<ruby>願<rp>(</rp><rt>ねが</rt><rp>)</rp></ruby>ってやまない。（衷心祝愿二位婚后生活幸福。）"}],"id":"N1-70"},{"title":"71. ～と（が）相まって／も相まって","blocks":[{"t":"label","label":"接续","text":"名A + と + 名B + と（が）相まって／名A + が + 名B + と相まって／名B + も相まって","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>A + と + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>B + と（が）<ruby>相<rp>(</rp><rt>あい</rt><rp>)</rp></ruby>まって／<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>A + が + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>B + と<ruby>相<rp>(</rp><rt>あい</rt><rp>)</rp></ruby>まって／<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>B + も<ruby>相<rp>(</rp><rt>あい</rt><rp>)</rp></ruby>まって"},{"t":"label","label":"说明","text":"表示两个因素相互作用，“A和B相辅相成，（使得）……更加……”。","furi":""},{"t":"label","label":"例句","text":"ふるさとを歌ったこの曲は、子どものころの思い出と相まって、私の心に深く響く。（歌唱故乡的这首曲子勾起了我对童年的回忆，深深地打动了我。）","furi":"ふるさとを<ruby>歌<rp>(</rp><rt>うた</rt><rp>)</rp></ruby>ったこの<ruby>曲<rp>(</rp><rt>きょく</rt><rp>)</rp></ruby>は、<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どものころの<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>い<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>と<ruby>相<rp>(</rp><rt>あい</rt><rp>)</rp></ruby>まって、<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>の<ruby>心<rp>(</rp><rt>こころ</rt><rp>)</rp></ruby>に<ruby>深<rp>(</rp><rt>ふか</rt><rp>)</rp></ruby>く<ruby>響<rp>(</rp><rt>ひび</rt><rp>)</rp></ruby>く。（歌唱故乡的这首曲子勾起了我对童年的回忆，深深地打动了我。）"}],"id":"N1-71"},{"title":"72. ～とあって","blocks":[{"t":"label","label":"接续","text":"動普通形／イ形／ナ形語幹／名 + とあって","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + とあって"},{"t":"label","label":"说明","text":"表示因果关系，“因为……、由于……”。后项不能用命令、推测等。","furi":""},{"t":"label","label":"例句","text":"人気俳優がくるとあって、このイベントのチケットはあっという間に売り切れた。（因为有很受欢迎的演员来参加这个活动，门票瞬间就卖完了。）","furi":"<ruby>人気<rp>(</rp><rt>にんき</rt><rp>)</rp></ruby><ruby>俳優<rp>(</rp><rt>はいゆう</rt><rp>)</rp></ruby>がくるとあって、このイベントのチケットはあっという<ruby>間<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>に<ruby>売<rp>(</rp><rt>う</rt><rp>)</rp></ruby>り<ruby>切<rp>(</rp><rt>き</rt><rp>)</rp></ruby>れた。（因为有很受欢迎的演员来参加这个活动，门票瞬间就卖完了。）"}],"id":"N1-72"},{"title":"73. ～とあっては","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + とあっては","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + とあっては"},{"t":"label","label":"说明","text":"表示假设，描述特殊情况，“若是……的话，就会……”。","furi":""},{"t":"label","label":"例句","text":"大好きなアイドル歌手がコンサートを開くとあっては、何とかして見に行かなければいけない。（自己很喜欢的偶像歌手要开演唱会的话，无论如何也要想办法去看一下。）","furi":"<ruby>大好<rp>(</rp><rt>だいす</rt><rp>)</rp></ruby>きなアイドル<ruby>歌手<rp>(</rp><rt>かしゅ</rt><rp>)</rp></ruby>がコンサートを<ruby>開<rp>(</rp><rt>ひら</rt><rp>)</rp></ruby>くとあっては、<ruby>何<rp>(</rp><rt>なん</rt><rp>)</rp></ruby>とかして<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>に<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>かなければいけない。（自己很喜欢的偶像歌手要开演唱会的话，无论如何也要想办法去看一下。）"}],"id":"N1-73"},{"title":"74. ～とあれば","blocks":[{"t":"label","label":"接续","text":"動普通形／イ形／ナ形語幹／名 + とあれば","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + とあれば"},{"t":"label","label":"说明","text":"表示假设，为了前项可尽最大努力，“如果是……、既然是……就（不得不）……”。","furi":""},{"t":"label","label":"例句","text":"親は子どものためとあれば、できる限りのことをするものです。（父母为了孩子的话无论什么事都会尽力而为的。）","furi":"<ruby>親<rp>(</rp><rt>おや</rt><rp>)</rp></ruby>は<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どものためとあれば、できる<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りのことをするものです。（父母为了孩子的话无论什么事都会尽力而为的。）"}],"id":"N1-74"},{"title":"75. ～といい～といい","blocks":[{"t":"label","label":"接续","text":"名A + といい + 名B + といい","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>A + といい + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>B + といい"},{"t":"label","label":"说明","text":"表示对事物的评价，“无论（A的方面）也好，B（的方面）也好……都……”。","furi":""},{"t":"label","label":"例句","text":"あの店の服は、品質といい、デザインといい、申し分ない。（那家店的服装无论是质量方面，还是设计方面，都无可挑剔。）","furi":"あの<ruby>店<rp>(</rp><rt>みせ</rt><rp>)</rp></ruby>の<ruby>服<rp>(</rp><rt>ふく</rt><rp>)</rp></ruby>は、<ruby>品質<rp>(</rp><rt>ひんしつ</rt><rp>)</rp></ruby>といい、デザインといい、<ruby>申<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>し<ruby>分<rp>(</rp><rt>ぶん</rt><rp>)</rp></ruby>ない。（那家店的服装无论是质量方面，还是设计方面，都无可挑剔。）"}],"id":"N1-75"},{"title":"76. ～という","blocks":[{"t":"label","label":"接续","text":"名A + という + 名A","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>A + という + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>A"},{"t":"label","label":"说明","text":"表示强调，“所有的……全都……”。","furi":""},{"t":"label","label":"例句","text":"学校が始まる日の朝、道路という道路は車であふれていた。（学校开学的那天早上，所有的路上都是车。）","furi":"<ruby>学校<rp>(</rp><rt>がっこう</rt><rp>)</rp></ruby>が<ruby>始<rp>(</rp><rt>はじ</rt><rp>)</rp></ruby>まる<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>の<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>、<ruby>道路<rp>(</rp><rt>どうろ</rt><rp>)</rp></ruby>という<ruby>道路<rp>(</rp><rt>どうろ</rt><rp>)</rp></ruby>は<ruby>車<rp>(</rp><rt>くるま</rt><rp>)</rp></ruby>であふれていた。（学校开学的那天早上，所有的路上都是车。）"}],"id":"N1-76"},{"title":"77. ～というか～というか","blocks":[{"t":"label","label":"接续","text":"動普通形／イ形／名 + というか","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + というか"},{"t":"label","label":"说明","text":"列举对前项的感受或印象，后项为总结性评价。","furi":""},{"t":"label","label":"例句","text":"このドラマの最終回については、がっかりしたというか、理解できないというか、複雑な気持ちでいっぱいだ。（对这个电视剧的结局不知该说是失望好，还是说难以理解，总之心情很复杂。）","furi":"このドラマの<ruby>最終<rp>(</rp><rt>さいしゅう</rt><rp>)</rp></ruby><ruby>回<rp>(</rp><rt>かい</rt><rp>)</rp></ruby>については、がっかりしたというか、<ruby>理解<rp>(</rp><rt>りかい</rt><rp>)</rp></ruby>できないというか、<ruby>複雑<rp>(</rp><rt>ふくざつ</rt><rp>)</rp></ruby>な<ruby>気持<rp>(</rp><rt>きも</rt><rp>)</rp></ruby>ちでいっぱいだ。（对这个电视剧的结局不知该说是失望好，还是说难以理解，总之心情很复杂。）"}],"id":"N1-77"},{"title":"78. ～というところだ／といったところだ","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + というところだ／といったところだ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + というところだ／といったところだ"},{"t":"label","label":"说明","text":"表示界限、范围，“大概是……、大致上……、最多不过是……”。","furi":""},{"t":"label","label":"例句","text":"自分で料理を作るといっても、せいぜいサラダとかゆで卵といったところだ。（说是自己会做饭，但最多不过是会做些色拉和煮鸡蛋而已。）","furi":"<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>で<ruby>料理<rp>(</rp><rt>りょうり</rt><rp>)</rp></ruby>を<ruby>作<rp>(</rp><rt>つく</rt><rp>)</rp></ruby>るといっても、せいぜいサラダとかゆで<ruby>卵<rp>(</rp><rt>たまご</rt><rp>)</rp></ruby>といったところだ。（说是自己会做饭，但最多不过是会做些色拉和煮鸡蛋而已。）"}],"id":"N1-78"},{"title":"79. ～というもの","blocks":[{"t":"label","label":"接续","text":"ここ／この + 名 + というもの","furi":"ここ／この + <ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + というもの"},{"t":"label","label":"说明","text":"描述最近很长一段时间一直处于某种状态，“这段时间以来……”。","furi":""},{"t":"label","label":"例句","text":"この一か月間というもの、仕事が忙しくて朝ごはんをろくに食べていない。（这一个月以来，工作太忙了，都没怎么好好吃早饭。）","furi":"この<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby>か<ruby>月<rp>(</rp><rt>げつ</rt><rp>)</rp></ruby><ruby>間<rp>(</rp><rt>かん</rt><rp>)</rp></ruby>というもの、<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>が<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しくて<ruby>朝<rp>(</rp><rt>あさ</rt><rp>)</rp></ruby>ごはんをろくに<ruby>食<rp>(</rp><rt>た</rt><rp>)</rp></ruby>べていない。（这一个月以来，工作太忙了，都没怎么好好吃早饭。）"}],"id":"N1-79"},{"title":"80. ～といえども","blocks":[{"t":"label","label":"接续","text":"動／イ形／ナ形／名の普通形 + といえども","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>の<ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + といえども"},{"t":"label","label":"说明","text":"表示让步转折，“即使……也……、虽说……但是……”。","furi":""},{"t":"label","label":"例句","text":"国際政治の専門家といえども、日々変化する世界情勢を分析するのは難しい。（就算是国际政治方面的专家，对于瞬息万变的国际形势也很难作出准确的分析。）","furi":"<ruby>国際<rp>(</rp><rt>こくさい</rt><rp>)</rp></ruby><ruby>政治<rp>(</rp><rt>せいじ</rt><rp>)</rp></ruby>の<ruby>専門<rp>(</rp><rt>せんもん</rt><rp>)</rp></ruby><ruby>家<rp>(</rp><rt>か</rt><rp>)</rp></ruby>といえども、<ruby>日々<rp>(</rp><rt>ひび</rt><rp>)</rp></ruby><ruby>変化<rp>(</rp><rt>へんか</rt><rp>)</rp></ruby>する<ruby>世界<rp>(</rp><rt>せかい</rt><rp>)</rp></ruby><ruby>情勢<rp>(</rp><rt>じょうせい</rt><rp>)</rp></ruby>を<ruby>分析<rp>(</rp><rt>ぶんせき</rt><rp>)</rp></ruby>するのは<ruby>難<rp>(</rp><rt>むずか</rt><rp>)</rp></ruby>しい。（就算是国际政治方面的专家，对于瞬息万变的国际形势也很难作出准确的分析。）"}],"id":"N1-80"},{"title":"81. ～と言えなくもない","blocks":[{"t":"label","label":"接续","text":"動普通形／イ形／ナ形語幹／名 + と言えなくもない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + と<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>えなくもない"},{"t":"label","label":"说明","text":"表示消极的肯定，“也可以说是……、也能说是……”。","furi":""},{"t":"label","label":"例句","text":"今の生活は充実しているといえなくもないが、何か物足りない感じがする。（现在的生活也能算得上是充实的，但总感觉有点美中不足的地方。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>の<ruby>生活<rp>(</rp><rt>せいかつ</rt><rp>)</rp></ruby>は<ruby>充実<rp>(</rp><rt>じゅうじつ</rt><rp>)</rp></ruby>しているといえなくもないが、<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>か<ruby>物足<rp>(</rp><rt>ものた</rt><rp>)</rp></ruby>りない<ruby>感<rp>(</rp><rt>かん</rt><rp>)</rp></ruby>じがする。（现在的生活也能算得上是充实的，但总感觉有点美中不足的地方。）"}],"id":"N1-81"},{"title":"82. ～といったらありはしない／といったらありゃしない／といったらない／ったらない／ったらありゃしない","blocks":[{"t":"label","label":"接续","text":"動辞書形／イ形／ナ形語幹／名 + といったら（ありはし）ない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + といったら（ありはし）ない"},{"t":"label","label":"说明","text":"强调心情或状态，“……极了、没有比……更……”。","furi":""},{"t":"label","label":"例句","text":"彼の部屋の汚さといったらありゃしない。（他的房间别提有多脏了。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>部屋<rp>(</rp><rt>へや</rt><rp>)</rp></ruby>の<ruby>汚<rp>(</rp><rt>きたな</rt><rp>)</rp></ruby>さといったらありゃしない。（他的房间别提有多脏了。）"}],"id":"N1-82"},{"title":"83. ～といって～ない／といった～ない","blocks":[{"t":"label","label":"接续","text":"これ + というて～ない／これ + という／といった + 名 + ない","furi":"これ + というて～ない／これ + という／といった + <ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + ない"},{"t":"label","label":"说明","text":"“并没有特别值得一提的……”。","furi":""},{"t":"label","label":"例句","text":"今週の新聞にはこれといってたいしたニュースは載っていない。（这一周的报纸上并没有什么特别值得一提的新闻。）","furi":"<ruby>今週<rp>(</rp><rt>こんしゅう</rt><rp>)</rp></ruby>の<ruby>新聞<rp>(</rp><rt>しんぶん</rt><rp>)</rp></ruby>にはこれといってたいしたニュースは<ruby>載<rp>(</rp><rt>の</rt><rp>)</rp></ruby>っていない。（这一周的报纸上并没有什么特别值得一提的新闻。）"}],"id":"N1-83"},{"title":"84. ～といわず～といわず","blocks":[{"t":"label","label":"接续","text":"名A + といわず + 名B + といわず","furi":"<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>A + といわず + <ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>B + といわず"},{"t":"label","label":"说明","text":"表示列举两个代表性事物，暗示其他也是如此，“不论……还是……、……也好……也好”。","furi":""},{"t":"label","label":"例句","text":"今の若者は休み時間といわず食事中といわずいつも携帯電話を離さない。（现在的年轻人无论是休息的时间还是吃饭的时间，都离不开手机。）","furi":"<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>の<ruby>若者<rp>(</rp><rt>わかもの</rt><rp>)</rp></ruby>は<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>み<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>といわず<ruby>食事<rp>(</rp><rt>しょくじ</rt><rp>)</rp></ruby><ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby>といわずいつも<ruby>携帯<rp>(</rp><rt>けいたい</rt><rp>)</rp></ruby><ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>を<ruby>離<rp>(</rp><rt>はな</rt><rp>)</rp></ruby>さない。（现在的年轻人无论是休息的时间还是吃饭的时间，都离不开手机。）"}],"id":"N1-84"},{"title":"85. ～と（は）打って変わって","blocks":[{"t":"label","label":"接续","text":"名 + と（は）打って変わって","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + と（は）<ruby>打<rp>(</rp><rt>う</rt><rp>)</rp></ruby>って<ruby>変<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わって"},{"t":"label","label":"说明","text":"表示与过去相比发生了根本性的变化，“和……截然不同、和……大不一样”。","furi":""},{"t":"label","label":"例句","text":"昨日のどしゃ降りとは打って変わって、今日は晴天だった。（和昨天的倾盆大雨不同，今天是晴天。）","furi":"<ruby>昨日<rp>(</rp><rt>きのう</rt><rp>)</rp></ruby>のどしゃ<ruby>降<rp>(</rp><rt>ぶ</rt><rp>)</rp></ruby>りとは<ruby>打<rp>(</rp><rt>う</rt><rp>)</rp></ruby>って<ruby>変<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わって、<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>は<ruby>晴天<rp>(</rp><rt>せいてん</rt><rp>)</rp></ruby>だった。（和昨天的倾盆大雨不同，今天是晴天。）"}],"id":"N1-85"},{"title":"86. ～（か）と思いきや","blocks":[{"t":"label","label":"接续","text":"名 + だ／動普通形／イ形／ナ形 +（か）と思いきや","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + だ／<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> +（か）と<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>いきや"},{"t":"label","label":"说明","text":"表达惊讶、意外，“原以为……但出乎意料的是……”。","furi":""},{"t":"label","label":"例句","text":"今日は暑くなるかと思いきや、むしろ寒いぐらいだった。（我想今天应该会变热的，可谁知还有点冷了。）","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>は<ruby>暑<rp>(</rp><rt>あつ</rt><rp>)</rp></ruby>くなるかと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>いきや、むしろ<ruby>寒<rp>(</rp><rt>さむ</rt><rp>)</rp></ruby>いぐらいだった。（我想今天应该会变热的，可谁知还有点冷了。）"}],"id":"N1-86"},{"title":"87. ～ときたら","blocks":[{"t":"label","label":"接续","text":"名 + ときたら","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + ときたら"},{"t":"label","label":"说明","text":"提示主语，“提到……就……、说起……就……”，多用于负面评价。","furi":""},{"t":"label","label":"例句","text":"まったく、うちの犬ときたら！泥棒が入ってきても、寝ていたんですよ。（我们家的狗真是没用！有小偷进来也没反应，居然还在睡。）","furi":"まったく、うちの<ruby>犬<rp>(</rp><rt>いぬ</rt><rp>)</rp></ruby>ときたら！<ruby>泥棒<rp>(</rp><rt>どろぼう</rt><rp>)</rp></ruby>が<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>ってきても、<ruby>寝<rp>(</rp><rt>ね</rt><rp>)</rp></ruby>ていたんですよ。（我们家的狗真是没用！有小偷进来也没反应，居然还在睡。）"}],"id":"N1-87"},{"title":"88. ～ところを","blocks":[{"t":"label","label":"接续","text":"動辞書形/た形/ている形 + ところを","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>/ている<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ところを"},{"t":"label","label":"说明","text":"表示时间、场景、状况，“当……的时候、在……之中”。后接寒暄语或被动态。","furi":""},{"t":"label","label":"例句","text":"犯人は買い物をしていたところを警官に逮捕された。（犯人正在买东西的时候被警察抓住了。）","furi":"<ruby>犯人<rp>(</rp><rt>はんにん</rt><rp>)</rp></ruby>は<ruby>買<rp>(</rp><rt>か</rt><rp>)</rp></ruby>い<ruby>物<rp>(</rp><rt>もの</rt><rp>)</rp></ruby>をしていたところを<ruby>警官<rp>(</rp><rt>けいかん</rt><rp>)</rp></ruby>に<ruby>逮捕<rp>(</rp><rt>たいほ</rt><rp>)</rp></ruby>された。（犯人正在买东西的时候被警察抓住了。）"}],"id":"N1-88"},{"title":"89. ～としたことが","blocks":[{"t":"label","label":"接续","text":"名 + としたことが","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + としたことが"},{"t":"label","label":"说明","text":"批评某人做与自身能力不符的事或自嘲，“像……那样的人，（竟然）……”。","furi":""},{"t":"label","label":"例句","text":"私としたことが、こんなつまらないミスをするとは……。（我居然犯了这么愚蠢的错误……）","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>としたことが、こんなつまらないミスをするとは……。（我居然犯了这么愚蠢的错误……）"}],"id":"N1-89"},{"title":"90. ～としたって／としたところで／にしたところで／にしたって","blocks":[{"t":"label","label":"接续","text":"動／イ形の普通形 + としたって／としたところで／にしたところで／にしたって","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>の<ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + としたって／としたところで／にしたところで／にしたって"},{"t":"label","label":"说明","text":"表示让步转折，“即使……也……、就算……也……”。","furi":""},{"t":"label","label":"例句","text":"社長にしたところで、今回の改革案に疑問を抱いているらしい。（好像就连社长也对这次的改革方案持有疑问。）","furi":"<ruby>社長<rp>(</rp><rt>しゃちょう</rt><rp>)</rp></ruby>にしたところで、<ruby>今回<rp>(</rp><rt>こんかい</rt><rp>)</rp></ruby>の<ruby>改革<rp>(</rp><rt>かいかく</rt><rp>)</rp></ruby><ruby>案<rp>(</rp><rt>あん</rt><rp>)</rp></ruby>に<ruby>疑問<rp>(</rp><rt>ぎもん</rt><rp>)</rp></ruby>を<ruby>抱<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>いているらしい。（好像就连社长也对这次的改革方案持有疑问。）"}],"id":"N1-90"},{"title":"91. ～として～ない","blocks":[{"t":"label","label":"接续","text":"名 + として + ～ない","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + として + ～ない"},{"t":"label","label":"说明","text":"表示全面否定，“没有（一人）……、没有（一个）……”。","furi":""},{"t":"label","label":"例句","text":"あの事件が起きて以来、一日として心の休まる日はない。（自从发生了那件事，就没有过一天安宁的日子。）","furi":"あの<ruby>事件<rp>(</rp><rt>じけん</rt><rp>)</rp></ruby>が<ruby>起<rp>(</rp><rt>お</rt><rp>)</rp></ruby>きて<ruby>以来<rp>(</rp><rt>いらい</rt><rp>)</rp></ruby>、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>にち</rt><rp>)</rp></ruby>として<ruby>心<rp>(</rp><rt>こころ</rt><rp>)</rp></ruby>の<ruby>休<rp>(</rp><rt>やす</rt><rp>)</rp></ruby>まる<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>はない。（自从发生了那件事，就没有过一天安宁的日子。）"}],"id":"N1-91"},{"title":"92. ～とて","blocks":[{"t":"sub","text":"(1) 接续","furi":""},{"t":"line","text":"名 + とて","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + とて"},{"t":"label","label":"说明","text":"表示假定条件的逆接，“即使……也不例外、甚至是……、就连……”。","furi":""},{"t":"label","label":"例句","text":"常に冷静な彼とてやはり人間だから、感情的になってしまうこともあるのだろう。（尽管他平时很冷静，但是也有情绪化的时候吧。）","furi":"<ruby>常<rp>(</rp><rt>つね</rt><rp>)</rp></ruby>に<ruby>冷静<rp>(</rp><rt>れいせい</rt><rp>)</rp></ruby>な<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>とてやはり<ruby>人間<rp>(</rp><rt>にんげん</rt><rp>)</rp></ruby>だから、<ruby>感情<rp>(</rp><rt>かんじょう</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>になってしまうこともあるのだろう。（尽管他平时很冷静，但是也有情绪化的时候吧。）"},{"t":"sub","text":"(2) 接续","furi":""},{"t":"line","text":"名だ／動た形 + とて","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>だ／<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + とて"},{"t":"label","label":"说明","text":"表示假定条件的逆接，“即使……也……、就算……也……”。","furi":""},{"t":"label","label":"例句","text":"どんなに後悔したとして、過ぎたことは今さらどうしようもない。（就算再怎么后悔，对于已经过去的事情也没有办法。）","furi":"どんなに<ruby>後悔<rp>(</rp><rt>こうかい</rt><rp>)</rp></ruby>したとして、<ruby>過<rp>(</rp><rt>す</rt><rp>)</rp></ruby>ぎたことは<ruby>今<rp>(</rp><rt>いま</rt><rp>)</rp></ruby>さらどうしようもない。（就算再怎么后悔，对于已经过去的事情也没有办法。）"}],"id":"N1-92"},{"title":"93. ～とは／なんて","blocks":[{"t":"label","label":"接续","text":"動・イ形・ナ形・名の普通形 + とは／なんて","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>・イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>・ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>・<ruby>名<rp>(</rp><rt>めい</rt><rp>)</rp></ruby>の<ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + とは／なんて"},{"t":"label","label":"说明","text":"表示出现意外情况时的惊讶，“居然……”。","furi":""},{"t":"label","label":"例句","text":"20歳にもなって、そんな簡単なこともできないなんて。（都20岁了连这么简单的事情都不会做，真是的。）","furi":"20<ruby>歳<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>にもなって、そんな<ruby>簡単<rp>(</rp><rt>かんたん</rt><rp>)</rp></ruby>なこともできないなんて。（都20岁了连这么简单的事情都不会做，真是的。）"}],"id":"N1-93"},{"title":"94. ～とはいうものの／とは言い条","blocks":[{"t":"label","label":"接续","text":"動普通形／イ形／ナ形語幹／名 + とはいうものの／とは言い条","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + とはいうものの／とは<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>い<ruby>条<rp>(</rp><rt>じょう</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示让步转折，“虽说……但是……”。","furi":""},{"t":"label","label":"例句","text":"男女平等の世の中とは言い条、職場においてはまだ差別が残っている。（虽说是男女平等的社会，但是在职场中仍然存在歧视。）","furi":"<ruby>男女<rp>(</rp><rt>だんじょ</rt><rp>)</rp></ruby><ruby>平等<rp>(</rp><rt>びょうどう</rt><rp>)</rp></ruby>の<ruby>世<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>の<ruby>中<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>とは<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>い<ruby>条<rp>(</rp><rt>じょう</rt><rp>)</rp></ruby>、<ruby>職場<rp>(</rp><rt>しょくば</rt><rp>)</rp></ruby>においてはまだ<ruby>差別<rp>(</rp><rt>さべつ</rt><rp>)</rp></ruby>が<ruby>残<rp>(</rp><rt>のこ</rt><rp>)</rp></ruby>っている。（虽说是男女平等的社会，但是在职场中仍然存在歧视。）"}],"id":"N1-94"},{"title":"95. ～とはいえ","blocks":[{"t":"label","label":"接续","text":"動普通形／イ形／ナ形語幹／名 + とはいえ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + とはいえ"},{"t":"label","label":"说明","text":"表示让步转折，“虽说……但是……、尽管……可是……”。","furi":""},{"t":"label","label":"例句","text":"春になったとはいえ、まだまだ寒い日が続いている。（虽然已经到了春天，但还是很冷。）","furi":"<ruby>春<rp>(</rp><rt>はる</rt><rp>)</rp></ruby>になったとはいえ、まだまだ<ruby>寒<rp>(</rp><rt>さむ</rt><rp>)</rp></ruby>い<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>が<ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>いている。（虽然已经到了春天，但还是很冷。）"}],"id":"N1-95"},{"title":"96. ～とばかりに","blocks":[{"t":"label","label":"接续","text":"動辞書形／イ形／ナ形語幹／名 + とばかりに","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + とばかりに"},{"t":"label","label":"说明","text":"描述对方的动作、神态、表情，“像……的样子、几乎就要……似的”。","furi":""},{"t":"label","label":"例句","text":"彼は出て行けとばかりに、ドアを開けた。（他好像跟我说“出去！”似的，把门打开了。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>て<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>けとばかりに、ドアを<ruby>開<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>けた。（他好像跟我说“出去！”似的，把门打开了。）"}],"id":"N1-96"},{"title":"97. ～とまではいかないが／とまではいかないとしても","blocks":[{"t":"label","label":"接续","text":"動普通形／イ形／ナ形語幹／名 + とまではいかないが／とまではいかないとしても","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + とまではいかないが／とまではいかないとしても"},{"t":"label","label":"说明","text":"表示前后对比，达不到前项程度但至少做后项，“虽然达不到……的程度，但是（至少）……”。","furi":""},{"t":"label","label":"例句","text":"絶対とまではいかないとしても、成功する確率は高いと思う。（即使没有绝对成功的把握，但是机会还是很大的。）","furi":"<ruby>絶対<rp>(</rp><rt>ぜったい</rt><rp>)</rp></ruby>とまではいかないとしても、<ruby>成功<rp>(</rp><rt>せいこう</rt><rp>)</rp></ruby>する<ruby>確率<rp>(</rp><rt>かくりつ</rt><rp>)</rp></ruby>は<ruby>高<rp>(</rp><rt>たか</rt><rp>)</rp></ruby>いと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>う。（即使没有绝对成功的把握，但是机会还是很大的。）"}],"id":"N1-97"},{"title":"98. ～とまでは言わないが／～とまでは言わないとしても","blocks":[{"t":"label","label":"接续","text":"動普通形／イ形／ナ形語幹／名 + とまでは言わないが／とまでは言わないとしても","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + とまでは<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>わないが／とまでは<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>わないとしても"},{"t":"label","label":"说明","text":"表示前后对比，不要求做前项但至少做后项，“即使不说……但至少……”。","furi":""},{"t":"label","label":"例句","text":"全部一人で解決しろとまでは言わないが、できる限りの努力をしてもらいたい。（虽然不要求你一个人解决所有问题，但是希望你能做出自己尽可能的努力。）","furi":"<ruby>全部<rp>(</rp><rt>ぜんぶ</rt><rp>)</rp></ruby><ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>にん</rt><rp>)</rp></ruby>で<ruby>解決<rp>(</rp><rt>かいけつ</rt><rp>)</rp></ruby>しろとまでは<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>わないが、できる<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りの<ruby>努力<rp>(</rp><rt>どりょく</rt><rp>)</rp></ruby>をしてもらいたい。（虽然不要求你一个人解决所有问题，但是希望你能做出自己尽可能的努力。）"}],"id":"N1-98"},{"title":"99. ～ともあろうものが","blocks":[{"t":"label","label":"接续","text":"名 + ともあろうものが","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + ともあろうものが"},{"t":"label","label":"说明","text":"表示有一定身份的人做出了不符合身份的事情，“身为……竟然……”。","furi":""},{"t":"label","label":"例句","text":"大学の学長ともあろうものが、賄賂を受け取るなんて、驚いた。（作为一所大学的校长，却收受贿赂，让人惊讶。）","furi":"<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>の<ruby>学長<rp>(</rp><rt>がくちょう</rt><rp>)</rp></ruby>ともあろうものが、<ruby>賄賂<rp>(</rp><rt>わいろ</rt><rp>)</rp></ruby>を<ruby>受<rp>(</rp><rt>う</rt><rp>)</rp></ruby>け<ruby>取<rp>(</rp><rt>と</rt><rp>)</rp></ruby>るなんて、<ruby>驚<rp>(</rp><rt>おどろ</rt><rp>)</rp></ruby>いた。（作为一所大学的校长，却收受贿赂，让人惊讶。）"}],"id":"N1-99"},{"title":"100. ～ともなく／ともなしに","blocks":[{"t":"label","label":"接续","text":"動辞書形 + ともなく／ともなしに","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ともなく／ともなしに"},{"t":"label","label":"说明","text":"表示无意间做某事时发现了意外的情况，“漫不经心地……、无意识地……”。","furi":""},{"t":"label","label":"例句","text":"電車の窓から外を見るともなく見ていたら、高校時代の同級生の姿が目に入った。（无意间看窗外的时候突然发现了高中时代同班同学的身影。）","furi":"<ruby>電車<rp>(</rp><rt>でんしゃ</rt><rp>)</rp></ruby>の<ruby>窓<rp>(</rp><rt>まど</rt><rp>)</rp></ruby>から<ruby>外<rp>(</rp><rt>そと</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>るともなく<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>ていたら、<ruby>高校<rp>(</rp><rt>こうこう</rt><rp>)</rp></ruby><ruby>時代<rp>(</rp><rt>じだい</rt><rp>)</rp></ruby>の<ruby>同級生<rp>(</rp><rt>どうきゅうせい</rt><rp>)</rp></ruby>の<ruby>姿<rp>(</rp><rt>すがた</rt><rp>)</rp></ruby>が<ruby>目<rp>(</rp><rt>め</rt><rp>)</rp></ruby>に<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>った。（无意间看窗外的时候突然发现了高中时代同班同学的身影。）"}],"id":"N1-100"},{"title":"101. ～ともなると／ともなれば","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + ともなると／ともなれば","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + ともなると／ともなれば"},{"t":"label","label":"说明","text":"表示评价的角度，“一到……的时候、一旦……的话”。","furi":""},{"t":"label","label":"例句","text":"社会人ともなると、服装や言葉遣いにも気をつけなければならない。（走上社会后要注意自己的服装和用语。）","furi":"<ruby>社会<rp>(</rp><rt>しゃかい</rt><rp>)</rp></ruby><ruby>人<rp>(</rp><rt>じん</rt><rp>)</rp></ruby>ともなると、<ruby>服装<rp>(</rp><rt>ふくそう</rt><rp>)</rp></ruby>や<ruby>言葉<rp>(</rp><rt>ことば</rt><rp>)</rp></ruby><ruby>遣<rp>(</rp><rt>づか</rt><rp>)</rp></ruby>いにも<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>をつけなければならない。（走上社会后要注意自己的服装和用语。）"}],"id":"N1-101"},{"title":"102. ～と／に～を重ねて","blocks":[{"t":"label","label":"接续","text":"名 + と／に + 名 + を重ねて","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + と／に + <ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>重<rp>(</rp><rt>かさ</rt><rp>)</rp></ruby>ねて"},{"t":"label","label":"说明","text":"“反复……、屡次……、历经……”。","furi":""},{"t":"label","label":"例句","text":"努力と工夫を重ねて、やっと満足のいく作品に仕上げた。（经过不断的努力和反复钻研，终于完成了令人满意的作品。）","furi":"<ruby>努力<rp>(</rp><rt>どりょく</rt><rp>)</rp></ruby>と<ruby>工夫<rp>(</rp><rt>くふう</rt><rp>)</rp></ruby>を<ruby>重<rp>(</rp><rt>かさ</rt><rp>)</rp></ruby>ねて、やっと<ruby>満足<rp>(</rp><rt>まんぞく</rt><rp>)</rp></ruby>のいく<ruby>作品<rp>(</rp><rt>さくひん</rt><rp>)</rp></ruby>に<ruby>仕上<rp>(</rp><rt>しあ</rt><rp>)</rp></ruby>げた。（经过不断的努力和反复钻研，终于完成了令人满意的作品。）"}],"id":"N1-102"},{"title":"103. ～ないではない／ないでもない","blocks":[{"t":"label","label":"接续","text":"動ない形 + ないではない／ないでもない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ないではない／ないでもない"},{"t":"label","label":"说明","text":"表示前项也有可能，但往往难以实现，“并不是不……、并非是……”。","furi":""},{"t":"label","label":"例句","text":"もう一度考えてみたら、彼の意見も正しいという気がしないでもない。（再想一想，觉得他的意见也不是不对。）","furi":"もう<ruby>一度<rp>(</rp><rt>いちど</rt><rp>)</rp></ruby><ruby>考<rp>(</rp><rt>かんが</rt><rp>)</rp></ruby>えてみたら、<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>意見<rp>(</rp><rt>いけん</rt><rp>)</rp></ruby>も<ruby>正<rp>(</rp><rt>ただ</rt><rp>)</rp></ruby>しいという<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>がしないでもない。（再想一想，觉得他的意见也不是不对。）"}],"id":"N1-103"},{"title":"104. ～ないまでも","blocks":[{"t":"label","label":"接续","text":"動ない形 + までも","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + までも"},{"t":"label","label":"说明","text":"表示前后对比，即使达不到前项程度但至少做后项，“即使做不到……但（至少）……”。","furi":""},{"t":"label","label":"例句","text":"週末まで残業しないとは言わないまでも、せめて平日くらいはきちんと出勤したほうがいいんじゃないですか。（即使不要求周末加班，但是至少要保证平时的出勤吧。）","furi":"<ruby>週末<rp>(</rp><rt>しゅうまつ</rt><rp>)</rp></ruby>まで<ruby>残業<rp>(</rp><rt>ざんぎょう</rt><rp>)</rp></ruby>しないとは<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>わないまでも、せめて<ruby>平日<rp>(</rp><rt>へいじつ</rt><rp>)</rp></ruby>くらいはきちんと<ruby>出勤<rp>(</rp><rt>しゅっきん</rt><rp>)</rp></ruby>したほうがいいんじゃないですか。（即使不要求周末加班，但是至少要保证平时的出勤吧。）"}],"id":"N1-104"},{"title":"105. ～ないものでもない","blocks":[{"t":"label","label":"接续","text":"動ない形 + ものでもない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + ものでもない"},{"t":"label","label":"说明","text":"表示在某个前提条件下后项也有可能，“不是不……、有可能……”。","furi":""},{"t":"label","label":"例句","text":"「私が悪かった」と素直に謝れば、許してやらないものでもない。（只要你能坦率地承认是自己不对，我也不是不原谅你。）","furi":"「<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>が<ruby>悪<rp>(</rp><rt>わる</rt><rp>)</rp></ruby>かった」と<ruby>素直<rp>(</rp><rt>すなお</rt><rp>)</rp></ruby>に<ruby>謝<rp>(</rp><rt>あやま</rt><rp>)</rp></ruby>れば、<ruby>許<rp>(</rp><rt>ゆる</rt><rp>)</rp></ruby>してやらないものでもない。（只要你能坦率地承认是自己不对，我也不是不原谅你。）"}],"id":"N1-105"},{"title":"106. ～ながらに／ながらの","blocks":[{"t":"label","label":"接续","text":"動ます形／名 + ながらに／ながらの","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + ながらに／ながらの"},{"t":"label","label":"说明","text":"表示状态，“保持……的状态、一边……一边……”。","furi":""},{"t":"label","label":"例句","text":"彼は自らのつらい体験を涙ながらに語った。（他含泪诉说了自己悲惨的遭遇。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>自<rp>(</rp><rt>みずか</rt><rp>)</rp></ruby>らのつらい<ruby>体験<rp>(</rp><rt>たいけん</rt><rp>)</rp></ruby>を<ruby>涙<rp>(</rp><rt>なみだ</rt><rp>)</rp></ruby>ながらに<ruby>語<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>った。（他含泪诉说了自己悲惨的遭遇。）"}],"id":"N1-106"},{"title":"107. ～ながらも","blocks":[{"t":"label","label":"接续","text":"動ます形／イ形／ナ形語幹／名 + ながらも","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + ながらも"},{"t":"label","label":"说明","text":"表示逆接，“虽然……但是……、尽管……但是……”。","furi":""},{"t":"label","label":"例句","text":"様々な苦難にあいながらも、あきらめないで最後までやり抜いた。（虽然碰到了各种各样的困难，但是没有放弃坚持到了最后。）","furi":"<ruby>様々<rp>(</rp><rt>さまざま</rt><rp>)</rp></ruby>な<ruby>苦難<rp>(</rp><rt>くなん</rt><rp>)</rp></ruby>にあいながらも、あきらめないで<ruby>最後<rp>(</rp><rt>さいご</rt><rp>)</rp></ruby>までやり<ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>いた。（虽然碰到了各种各样的困难，但是没有放弃坚持到了最后。）"}],"id":"N1-107"},{"title":"108. ～なくして（は）","blocks":[{"t":"label","label":"接续","text":"名 + なくして（は）","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + なくして（は）"},{"t":"label","label":"说明","text":"表示假设，“如果没有……，就（不能）……”。","furi":""},{"t":"label","label":"例句","text":"「努力なくして成功はない」という言葉は、祖父の口癖だ。（“不努力就不会成功”，这句话是爷爷的口头禅。）","furi":"「<ruby>努力<rp>(</rp><rt>どりょく</rt><rp>)</rp></ruby>なくして<ruby>成功<rp>(</rp><rt>せいこう</rt><rp>)</rp></ruby>はない」という<ruby>言葉<rp>(</rp><rt>ことば</rt><rp>)</rp></ruby>は、<ruby>祖父<rp>(</rp><rt>そふ</rt><rp>)</rp></ruby>の<ruby>口癖<rp>(</rp><rt>くちぐせ</rt><rp>)</rp></ruby>だ。（“不努力就不会成功”，这句话是爷爷的口头禅。）"}],"id":"N1-108"},{"title":"109. ～なくはない／なくもない","blocks":[{"t":"label","label":"接续","text":"動ない形／イ形―く／ナ形語幹／名 + なくはない／なくもない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>―く／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + なくはない／なくもない"},{"t":"label","label":"说明","text":"表示前项也有可能，“也有可能……、也不是不……”。","furi":""},{"t":"label","label":"例句","text":"彼の気持ちは分からなくもないが、ただその行為には賛成できない。（他的心情我不是不理解，但是那种行为我不赞成。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>気持<rp>(</rp><rt>きも</rt><rp>)</rp></ruby>ちは<ruby>分<rp>(</rp><rt>わ</rt><rp>)</rp></ruby>からなくもないが、ただその<ruby>行為<rp>(</rp><rt>こうい</rt><rp>)</rp></ruby>には<ruby>賛成<rp>(</rp><rt>さんせい</rt><rp>)</rp></ruby>できない。（他的心情我不是不理解，但是那种行为我不赞成。）"}],"id":"N1-109"},{"title":"110. ～なしに／なしには／なしでは","blocks":[{"t":"sub","text":"(1) 接续","furi":""},{"t":"line","text":"名 + なしに／なしには／なしでは","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + なしに／なしには／なしでは"},{"t":"label","label":"说明","text":"表示假定，“如果没有……就不能……”。","furi":""},{"t":"label","label":"例句","text":"教授の助言なしには、この研究の成功はなかった。（如果没有教授的建议，这个研究将无法获得成功。）","furi":"<ruby>教授<rp>(</rp><rt>きょうじゅ</rt><rp>)</rp></ruby>の<ruby>助言<rp>(</rp><rt>じょげん</rt><rp>)</rp></ruby>なしには、この<ruby>研究<rp>(</rp><rt>けんきゅう</rt><rp>)</rp></ruby>の<ruby>成功<rp>(</rp><rt>せいこう</rt><rp>)</rp></ruby>はなかった。（如果没有教授的建议，这个研究将无法获得成功。）"},{"t":"sub","text":"(2) 接续","furi":""},{"t":"line","text":"名 + なしに","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + なしに"},{"t":"label","label":"说明","text":"表示附带关系，“没有……的状态下，就……”。","furi":""},{"t":"label","label":"例句","text":"彼はひと言のあいさつなしに帰国した。（他没有打声招呼就回国了。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>はひと<ruby>言<rp>(</rp><rt>こと</rt><rp>)</rp></ruby>のあいさつなしに<ruby>帰国<rp>(</rp><rt>きこく</rt><rp>)</rp></ruby>した。（他没有打声招呼就回国了。）"}],"id":"N1-110"},{"title":"111. ～ならいざしらず","blocks":[{"t":"label","label":"接续","text":"名 + ならいざしらず","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + ならいざしらず"},{"t":"label","label":"说明","text":"表示前后比较，“如果……的话，另当别论，但是……的话（就很严重了）”。","furi":""},{"t":"label","label":"例句","text":"新入社員ならいざしらず、入社8年にもなる君がこんなミスをするとは信じられない。（若是新员工的话还情有可原，你进公司都8年了还犯这种错误，简直让人难以置信。）","furi":"<ruby>新入<rp>(</rp><rt>しんにゅう</rt><rp>)</rp></ruby><ruby>社員<rp>(</rp><rt>しゃいん</rt><rp>)</rp></ruby>ならいざしらず、<ruby>入社<rp>(</rp><rt>にゅうしゃ</rt><rp>)</rp></ruby>8<ruby>年<rp>(</rp><rt>ねん</rt><rp>)</rp></ruby>にもなる<ruby>君<rp>(</rp><rt>きみ</rt><rp>)</rp></ruby>がこんなミスをするとは<ruby>信<rp>(</rp><rt>しん</rt><rp>)</rp></ruby>じられない。（若是新员工的话还情有可原，你进公司都8年了还犯这种错误，简直让人难以置信。）"}],"id":"N1-111"},{"title":"112. ～ならでは／ならではの","blocks":[{"t":"label","label":"接续","text":"名 + ならでは／ならではの","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + ならでは／ならではの"},{"t":"label","label":"说明","text":"强调地方特色、某人独有的才能等，“只有……才具备的……、……独特的……”。","furi":""},{"t":"label","label":"例句","text":"日本全国、その地方ならではの名産がある。（在日本全国都有当地的特产。）","furi":"<ruby>日本<rp>(</rp><rt>にっぽん</rt><rp>)</rp></ruby><ruby>全国<rp>(</rp><rt>ぜんこく</rt><rp>)</rp></ruby>、その<ruby>地方<rp>(</rp><rt>ちほう</rt><rp>)</rp></ruby>ならではの<ruby>名産<rp>(</rp><rt>めいさん</rt><rp>)</rp></ruby>がある。（在日本全国都有当地的特产。）"}],"id":"N1-112"},{"title":"113. ～なり","blocks":[{"t":"label","label":"接续","text":"動辞書形 + なり","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + なり"},{"t":"label","label":"说明","text":"表示前项动作结束后紧接着进行后项，“一……就……”。","furi":""},{"t":"label","label":"例句","text":"娘は家に帰ってくるなり、泣き出した。（女儿一回家就哭了起来。）","furi":"<ruby>娘<rp>(</rp><rt>むすめ</rt><rp>)</rp></ruby>は<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>に<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>ってくるなり、<ruby>泣<rp>(</rp><rt>な</rt><rp>)</rp></ruby>き<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>した。（女儿一回家就哭了起来。）"}],"id":"N1-113"},{"title":"114. ～なりとも","blocks":[{"t":"sub","text":"(1) 接续","furi":""},{"t":"line","text":"名 + なりとも","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + なりとも"},{"t":"label","label":"说明","text":"表示列举，“……之类的、……什么的”。","furi":""},{"t":"label","label":"例句","text":"時間があったら、電話なりとも、かけてくれればいい。（有时间的时候，打个电话过来什么的就可以了。）","furi":"<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>があったら、<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>なりとも、かけてくれればいい。（有时间的时候，打个电话过来什么的就可以了。）"},{"t":"sub","text":"(2) 接续","furi":""},{"t":"line","text":"名 + なり何なると","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + なり<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>なると"},{"t":"label","label":"说明","text":"列举其中一项，暗示其他，“不管……、无论……”。","furi":""},{"t":"label","label":"例句","text":"何なりとお好きなものを持って帰るといい。（可以带自己喜欢的东西回去。）","furi":"<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>なりとお<ruby>好<rp>(</rp><rt>す</rt><rp>)</rp></ruby>きなものを<ruby>持<rp>(</rp><rt>も</rt><rp>)</rp></ruby>って<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>るといい。（可以带自己喜欢的东西回去。）"}],"id":"N1-114"},{"title":"115. ～なり～なり","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + なり","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + なり"},{"t":"label","label":"说明","text":"表示列举，“……也好，……也好、可以……或者……”。","furi":""},{"t":"label","label":"例句","text":"わからない単語があったら、辞書を引くなりだれかに聞くなりして調べておきなさい。（有不懂的单词可以查查词典或者是问问别人。）","furi":"わからない<ruby>単語<rp>(</rp><rt>たんご</rt><rp>)</rp></ruby>があったら、<ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby>を<ruby>引<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>くなりだれかに<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>くなりして<ruby>調<rp>(</rp><rt>しら</rt><rp>)</rp></ruby>べておきなさい。（有不懂的单词可以查查词典或者是问问别人。）"}],"id":"N1-115"},{"title":"116. ～なりに／なりの","blocks":[{"t":"label","label":"接续","text":"動普通形／イ形／ナ形／名 + なりに／なりの","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + なりに／なりの"},{"t":"label","label":"说明","text":"表示判断的立场，“以……（某人）自己的方式、与……相应的”。","furi":""},{"t":"label","label":"例句","text":"私が事業で成功できたのは、自分なりに工夫を重ねたからだと思います。（我觉得自己之所以能够在事业上获得成功，是因为以自己的方式做了很多努力。）","furi":"<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>が<ruby>事業<rp>(</rp><rt>じぎょう</rt><rp>)</rp></ruby>で<ruby>成功<rp>(</rp><rt>せいこう</rt><rp>)</rp></ruby>できたのは、<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>なりに<ruby>工夫<rp>(</rp><rt>くふう</rt><rp>)</rp></ruby>を<ruby>重<rp>(</rp><rt>かさ</rt><rp>)</rp></ruby>ねたからだと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>います。（我觉得自己之所以能够在事业上获得成功，是因为以自己的方式做了很多努力。）"}],"id":"N1-116"},{"title":"117. ～に値する／に値しない","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + に値する／に値しない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>値<rp>(</rp><rt>あたい</rt><rp>)</rp></ruby>する／に<ruby>値<rp>(</rp><rt>あたい</rt><rp>)</rp></ruby>しない"},{"t":"label","label":"说明","text":"表示值不值得做某事，“值得……、不值得……”。","furi":""},{"t":"label","label":"例句","text":"彼の行為は賞賛に値する。（他的行为值得称赞。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>の<ruby>行為<rp>(</rp><rt>こうい</rt><rp>)</rp></ruby>は<ruby>賞賛<rp>(</rp><rt>しょうさん</rt><rp>)</rp></ruby>に<ruby>値<rp>(</rp><rt>あたい</rt><rp>)</rp></ruby>する。（他的行为值得称赞。）"}],"id":"N1-117"},{"title":"118. ～に（は）あたらない","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + に（は）あたらない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に（は）あたらない"},{"t":"label","label":"说明","text":"表示没有必要做某事，“不必……、用不着……”。","furi":""},{"t":"label","label":"例句","text":"彼なりにできるだけの努力をしたのだから、いい結果を出せなかったとしても、非難するにはあたらない。（他已经尽可能的做出了努力，即使没有好的结果也没必要指责。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>なりにできるだけの<ruby>努力<rp>(</rp><rt>どりょく</rt><rp>)</rp></ruby>をしたのだから、いい<ruby>結果<rp>(</rp><rt>けっか</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>せなかったとしても、<ruby>非難<rp>(</rp><rt>ひなん</rt><rp>)</rp></ruby>するにはあたらない。（他已经尽可能的做出了努力，即使没有好的结果也没必要指责。）"}],"id":"N1-118"},{"title":"119. ～にあって（は）／にあっても","blocks":[{"t":"label","label":"接续","text":"名 + にあって（は）／にあっても","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にあって（は）／にあっても"},{"t":"label","label":"说明","text":"描述某种场合、时间、情况，“处于……、在……之下”。","furi":""},{"t":"label","label":"例句","text":"動物の世界にあっても、親子の情愛は変わらないものだ。（即使在动物的世界里，亲子之爱也是不变的。）","furi":"<ruby>動物<rp>(</rp><rt>どうぶつ</rt><rp>)</rp></ruby>の<ruby>世界<rp>(</rp><rt>せかい</rt><rp>)</rp></ruby>にあっても、<ruby>親子<rp>(</rp><rt>おやこ</rt><rp>)</rp></ruby>の<ruby>情愛<rp>(</rp><rt>じょうあい</rt><rp>)</rp></ruby>は<ruby>変<rp>(</rp><rt>か</rt><rp>)</rp></ruby>わらないものだ。（即使在动物的世界里，亲子之爱也是不变的。）"}],"id":"N1-119"},{"title":"120. ～に至って／に至る／に至っては／に至っても","blocks":[{"t":"sub","text":"(1) ～に至って／に至る","furi":"(1) ～に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>って／に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>る"},{"t":"label","label":"接续","text":"動辞書形／名 + に至って／に至る","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>って／に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>る"},{"t":"label","label":"说明","text":"表示程度、结果、范围，“到……为止”。","furi":""},{"t":"label","label":"例句","text":"彼らが興した会社は発展を続け、海外に支店を出すに至った。（他们一起兴办的公司规模越来越大，甚至在国外开了分店。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>らが<ruby>興<rp>(</rp><rt>おこ</rt><rp>)</rp></ruby>した<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>は<ruby>発展<rp>(</rp><rt>はってん</rt><rp>)</rp></ruby>を<ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>け、<ruby>海外<rp>(</rp><rt>かいがい</rt><rp>)</rp></ruby>に<ruby>支店<rp>(</rp><rt>してん</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>すに<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>った。（他们一起兴办的公司规模越来越大，甚至在国外开了分店。）"},{"t":"sub","text":"(2) ～に至っては","furi":"(2) ～に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>っては"},{"t":"label","label":"接续①","text":"動辞書形／名 + に至っては","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>っては"},{"t":"label","label":"说明①","text":"表示顺接，“既然事情已经到了……的地步”。","furi":""},{"t":"label","label":"例句①","text":"ここに至っては、仕事をやめてもう一度やり直すしかないでしょう。（事已至此，只好辞职，从头开始。）","furi":"ここに<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>っては、<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>をやめてもう<ruby>一度<rp>(</rp><rt>いちど</rt><rp>)</rp></ruby>やり<ruby>直<rp>(</rp><rt>なお</rt><rp>)</rp></ruby>すしかないでしょう。（事已至此，只好辞职，从头开始。）"},{"t":"label","label":"接续②","text":"名 + に至っては","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>っては"},{"t":"label","label":"说明②","text":"“提到……、谈到……”，用于引出话题。","furi":""},{"t":"label","label":"例句②","text":"数学の問題に至っては、私もお手上げだ。（关于数学方面的问题，我也没辙。）","furi":"<ruby>数学<rp>(</rp><rt>すうがく</rt><rp>)</rp></ruby>の<ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>っては、<ruby>私<rp>(</rp><rt>わたし</rt><rp>)</rp></ruby>もお<ruby>手上<rp>(</rp><rt>てあ</rt><rp>)</rp></ruby>げだ。（关于数学方面的问题，我也没辙。）"},{"t":"sub","text":"(3) ～に至っても","furi":"(3) ～に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>っても"},{"t":"label","label":"接续","text":"動辞書形／名 + に至っても","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>っても"},{"t":"label","label":"说明","text":"表示逆接，“即使……也……”。","furi":""},{"t":"label","label":"例句","text":"株価がここまで下落するに至っても、彼はまだあきらめていないらしい。（股价下跌到如此程度，他好像仍然没有放弃。）","furi":"<ruby>株価<rp>(</rp><rt>かぶか</rt><rp>)</rp></ruby>がここまで<ruby>下落<rp>(</rp><rt>げらく</rt><rp>)</rp></ruby>するに<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>っても、<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>はまだあきらめていないらしい。（股价下跌到如此程度，他好像仍然没有放弃。）"}],"id":"N1-120"},{"title":"121. ～に至るまで","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + に至るまで","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>るまで"},{"t":"label","label":"说明","text":"表示程度、范围，“从……到……、甚至连……也……”。","furi":""},{"t":"label","label":"例句","text":"帰宅途中、夕立にあい、頭から足先に至るまで全身びしょ濡れになった。（回家途中遇到雷雨，从头到脚全身都淋湿了。）","furi":"<ruby>帰宅<rp>(</rp><rt>きたく</rt><rp>)</rp></ruby><ruby>途中<rp>(</rp><rt>とちゅう</rt><rp>)</rp></ruby>、<ruby>夕立<rp>(</rp><rt>ゆうだち</rt><rp>)</rp></ruby>にあい、<ruby>頭<rp>(</rp><rt>あたま</rt><rp>)</rp></ruby>から<ruby>足<rp>(</rp><rt>あし</rt><rp>)</rp></ruby><ruby>先<rp>(</rp><rt>さき</rt><rp>)</rp></ruby>に<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>るまで<ruby>全身<rp>(</rp><rt>ぜんしん</rt><rp>)</rp></ruby>びしょ<ruby>濡<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>れになった。（回家途中遇到雷雨，从头到脚全身都淋湿了。）"}],"id":"N1-121"},{"title":"122. ～に負うところが多い／に負うところが大きい","blocks":[{"t":"label","label":"接续","text":"名 + に負うところが多い／に負うところが大きい","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>負<rp>(</rp><rt>お</rt><rp>)</rp></ruby>うところが<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>い／に<ruby>負<rp>(</rp><rt>お</rt><rp>)</rp></ruby>うところが<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きい"},{"t":"label","label":"说明","text":"表示承蒙恩惠，“得益于……、多亏了……”。","furi":""},{"t":"label","label":"例句","text":"この会社に入ったのは大学時代の先生の推薦に負うところが多い。（能够进这家公司得益于大学时代的老师的推荐。）","furi":"この<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>に<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>ったのは<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby><ruby>時代<rp>(</rp><rt>じだい</rt><rp>)</rp></ruby>の<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>の<ruby>推薦<rp>(</rp><rt>すいせん</rt><rp>)</rp></ruby>に<ruby>負<rp>(</rp><rt>お</rt><rp>)</rp></ruby>うところが<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>い。（能够进这家公司得益于大学时代的老师的推荐。）"}],"id":"N1-122"},{"title":"123. ～におかれましては","blocks":[{"t":"label","label":"接续","text":"名 + におかれましては","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + におかれましては"},{"t":"label","label":"说明","text":"提示前项的人或事，“关于……、至于……”。用于问候对方健康状况等正式场合。","furi":""},{"t":"label","label":"例句","text":"皆様におかれましてはますますご健勝のことと心よりお慶び申し上げます。（祝愿大家身体健康。）","furi":"<ruby>皆様<rp>(</rp><rt>みなさま</rt><rp>)</rp></ruby>におかれましてはますますご<ruby>健勝<rp>(</rp><rt>けんしょう</rt><rp>)</rp></ruby>のことと<ruby>心<rp>(</rp><rt>こころ</rt><rp>)</rp></ruby>よりお<ruby>慶<rp>(</rp><rt>よろこ</rt><rp>)</rp></ruby>び<ruby>申<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>し<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>げます。（祝愿大家身体健康。）"}],"id":"N1-123"},{"title":"124. ～に（は）及ばない","blocks":[{"t":"sub","text":"(1) 接续","furi":""},{"t":"line","text":"動辞書形／名 + には及ばない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + には<ruby>及<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>ばない"},{"t":"label","label":"说明","text":"表示没有必要，“不必……、没必要……”。","furi":""},{"t":"label","label":"例句","text":"検査では何の異常も見つからなかったので、心配するには及ばない。（在检查中没有发现任何异常情况，不必担心。）","furi":"<ruby>検査<rp>(</rp><rt>けんさ</rt><rp>)</rp></ruby>では<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>の<ruby>異常<rp>(</rp><rt>いじょう</rt><rp>)</rp></ruby>も<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>つからなかったので、<ruby>心配<rp>(</rp><rt>しんぱい</rt><rp>)</rp></ruby>するには<ruby>及<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>ばない。（在检查中没有发现任何异常情况，不必担心。）"},{"t":"sub","text":"(2) 接续","furi":""},{"t":"line","text":"名 + に（は）及ばない","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に（は）<ruby>及<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>ばない"},{"t":"label","label":"说明","text":"表示无法企及，“比不上……、不及……”。","furi":""},{"t":"label","label":"例句","text":"数学にかけては、彼に及ばない。（在数学方面比不上他。）","furi":"<ruby>数学<rp>(</rp><rt>すうがく</rt><rp>)</rp></ruby>にかけては、<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>に<ruby>及<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>ばない。（在数学方面比不上他。）"}],"id":"N1-124"},{"title":"125. ～に欠かせない／が欠かせない","blocks":[{"t":"label","label":"接续","text":"名 + に欠かせない／が欠かせない","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>欠<rp>(</rp><rt>か</rt><rp>)</rp></ruby>かせない／が<ruby>欠<rp>(</rp><rt>か</rt><rp>)</rp></ruby>かせない"},{"t":"label","label":"说明","text":"“在……方面不可或缺的、必不可少的”。","furi":""},{"t":"label","label":"例句","text":"彼はわが社にとって欠かせない優秀な人材である。（他是我们公司必不可少的优秀人才。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>はわが<ruby>社<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>にとって<ruby>欠<rp>(</rp><rt>か</rt><rp>)</rp></ruby>かせない<ruby>優秀<rp>(</rp><rt>ゆうしゅう</rt><rp>)</rp></ruby>な<ruby>人材<rp>(</rp><rt>じんざい</rt><rp>)</rp></ruby>である。（他是我们公司必不可少的优秀人才。）"}],"id":"N1-125"},{"title":"126. ～にかかったら／にかかっては／にかかると","blocks":[{"t":"label","label":"接续","text":"名 + にかかったら／にかかっては／にかかると","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にかかったら／にかかっては／にかかると"},{"t":"label","label":"说明","text":"提示主语，“说到……、提到……”，指某人达到某种程度无人能及。","furi":""},{"t":"label","label":"例句","text":"彼女の早口にかかっては、誰も比べものにならない。（她讲话语速之快，无人能比。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>の<ruby>早口<rp>(</rp><rt>はやくち</rt><rp>)</rp></ruby>にかかっては、<ruby>誰<rp>(</rp><rt>だれ</rt><rp>)</rp></ruby>も<ruby>比<rp>(</rp><rt>くら</rt><rp>)</rp></ruby>べものにならない。（她讲话语速之快，无人能比。）"}],"id":"N1-126"},{"title":"127. ～にかかっている","blocks":[{"t":"label","label":"接续","text":"名 + にかかっている","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にかかっている"},{"t":"label","label":"说明","text":"表示前项取决于后项，“取决于……、全凭……”。","furi":""},{"t":"label","label":"例句","text":"物事の成否は人の考え方にかかっている。（事情成功与否，取决于人们的想法。）","furi":"<ruby>物事<rp>(</rp><rt>ものごと</rt><rp>)</rp></ruby>の<ruby>成否<rp>(</rp><rt>せいひ</rt><rp>)</rp></ruby>は<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>の<ruby>考<rp>(</rp><rt>かんが</rt><rp>)</rp></ruby>え<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>にかかっている。（事情成功与否，取决于人们的想法。）"}],"id":"N1-127"},{"title":"128. ～にかかわる","blocks":[{"t":"label","label":"接续","text":"名 + にかかわる","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にかかわる"},{"t":"label","label":"说明","text":"表示前后两项的关联，“关系到……、影响到……”。多为重要内容。","furi":""},{"t":"label","label":"例句","text":"会社の評判にかかわるから、製品の品質管理は厳しくしなければならない。（产品的质量管理关系到公司的信誉问题，必须要严格。）","furi":"<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>の<ruby>評判<rp>(</rp><rt>ひょうばん</rt><rp>)</rp></ruby>にかかわるから、<ruby>製品<rp>(</rp><rt>せいひん</rt><rp>)</rp></ruby>の<ruby>品質<rp>(</rp><rt>ひんしつ</rt><rp>)</rp></ruby><ruby>管理<rp>(</rp><rt>かんり</rt><rp>)</rp></ruby>は<ruby>厳<rp>(</rp><rt>きび</rt><rp>)</rp></ruby>しくしなければならない。（产品的质量管理关系到公司的信誉问题，必须要严格。）"}],"id":"N1-128"},{"title":"129. ～に限ったことではない","blocks":[{"t":"label","label":"接续","text":"名 + に限ったことではない","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>ったことではない"},{"t":"label","label":"说明","text":"“不是……所独有的问题”。","furi":""},{"t":"label","label":"例句","text":"試合などの時の誤審は何もプロサッカーに限ったことではない。（比赛中的误判并非职业足球所独有的问题。）","furi":"<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>などの<ruby>時<rp>(</rp><rt>とき</rt><rp>)</rp></ruby>の<ruby>誤審<rp>(</rp><rt>ごしん</rt><rp>)</rp></ruby>は<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>もプロサッカーに<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>ったことではない。（比赛中的误判并非职业足球所独有的问题。）"}],"id":"N1-129"},{"title":"130. ～にかこつけて","blocks":[{"t":"label","label":"接续","text":"名 + にかこつけて","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にかこつけて"},{"t":"label","label":"说明","text":"“以……为托词、以……为借口”。","furi":""},{"t":"label","label":"例句","text":"病気にかこつけて、一日会社をサボった。（以生病为由，请了一天假。）","furi":"<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>にかこつけて、<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>にち</rt><rp>)</rp></ruby><ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>をサボった。（以生病为由，请了一天假。）"}],"id":"N1-130"},{"title":"131. ～にかたくない","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + にかたくない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にかたくない"},{"t":"label","label":"说明","text":"“不难想象……、不难察觉……”。","furi":""},{"t":"label","label":"例句","text":"子どもを亡くした親の悲しみは察するにかたくない。（失去孩子的父母的悲痛之情不难察觉。）","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもを<ruby>亡<rp>(</rp><rt>な</rt><rp>)</rp></ruby>くした<ruby>親<rp>(</rp><rt>おや</rt><rp>)</rp></ruby>の<ruby>悲<rp>(</rp><rt>かな</rt><rp>)</rp></ruby>しみは<ruby>察<rp>(</rp><rt>さっ</rt><rp>)</rp></ruby>するにかたくない。（失去孩子的父母的悲痛之情不难察觉。）"}],"id":"N1-131"},{"title":"132. ～にかまけて","blocks":[{"t":"label","label":"接续","text":"名 + にかまけて","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にかまけて"},{"t":"label","label":"说明","text":"“忙于……、只顾……”。","furi":""},{"t":"label","label":"例句","text":"仕事にかまけて、子どもの面倒を見る時間もない。（忙于工作无暇照顾孩子。）","furi":"<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>にかまけて、<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもの<ruby>面倒<rp>(</rp><rt>めんどう</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>る<ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>もない。（忙于工作无暇照顾孩子。）"}],"id":"N1-132"},{"title":"133. ～に越したことはない","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + に越したことはない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>越<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>したことはない"},{"t":"label","label":"说明","text":"“最好是……、莫过于……”。","furi":""},{"t":"label","label":"例句","text":"体は丈夫に越したことはない。（身体结实是再好不过了。）","furi":"<ruby>体<rp>(</rp><rt>からだ</rt><rp>)</rp></ruby>は<ruby>丈夫<rp>(</rp><rt>じょうぶ</rt><rp>)</rp></ruby>に<ruby>越<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>したことはない。（身体结实是再好不过了。）"}],"id":"N1-133"},{"title":"134. ～に如くはない","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + に如くはない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>如<rp>(</rp><rt>ごと</rt><rp>)</rp></ruby>くはない"},{"t":"label","label":"说明","text":"“不如……、最好……”。","furi":""},{"t":"label","label":"例句","text":"逃げるにしくはなし。（三十六计，走为上策。）","furi":"<ruby>逃<rp>(</rp><rt>に</rt><rp>)</rp></ruby>げるにしくはなし。（三十六计，走为上策。）"}],"id":"N1-134"},{"title":"135. ～にして","blocks":[{"t":"sub","text":"(1) 接续","furi":""},{"t":"line","text":"名 + にして","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にして"},{"t":"label","label":"说明","text":"表示时间、次数等，“在……的时候、在某个时间段”。","furi":""},{"t":"label","label":"例句","text":"彼は40歳にして父親になった。（他在40岁当了父亲。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は40<ruby>歳<rp>(</rp><rt>さい</rt><rp>)</rp></ruby>にして<ruby>父親<rp>(</rp><rt>ちちおや</rt><rp>)</rp></ruby>になった。（他在40岁当了父亲。）"},{"t":"sub","text":"(2) 接续","furi":""},{"t":"line","text":"名 + にして","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にして"},{"t":"label","label":"说明","text":"表示并列，“既是……又是……”。","furi":""},{"t":"label","label":"例句","text":"彼は医者にして作家でもある。（他既是医生也是一名作家。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>医者<rp>(</rp><rt>いしゃ</rt><rp>)</rp></ruby>にして<ruby>作家<rp>(</rp><rt>さっか</rt><rp>)</rp></ruby>でもある。（他既是医生也是一名作家。）"},{"t":"sub","text":"(3) 接续","furi":""},{"t":"line","text":"名 + にしてはじめて","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にしてはじめて"},{"t":"label","label":"说明","text":"表示条件、限定，“只有……才……”。","furi":""},{"t":"label","label":"例句","text":"そんな驚異的な発明は彼のような天才にしてはじめてできることだ。（那么了不起的发明只有像他那样的天才才能做得到。）","furi":"そんな<ruby>驚異<rp>(</rp><rt>きょうい</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>な<ruby>発明<rp>(</rp><rt>はつめい</rt><rp>)</rp></ruby>は<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>のような<ruby>天才<rp>(</rp><rt>てんさい</rt><rp>)</rp></ruby>にしてはじめてできることだ。（那么了不起的发明只有像他那样的天才才能做得到。）"},{"t":"sub","text":"(4) 接续","furi":""},{"t":"line","text":"名 + にして + ～ない","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にして + ～ない"},{"t":"label","label":"说明","text":"表示逆接，“就连……也……（没有做到）”。","furi":""},{"t":"label","label":"例句","text":"先生にして解けない問題なので、生徒たちができないのも無理はない。（就连老师都没有解答出来的问题，学生不会也情有可原。）","furi":"<ruby>先生<rp>(</rp><rt>せんせい</rt><rp>)</rp></ruby>にして<ruby>解<rp>(</rp><rt>と</rt><rp>)</rp></ruby>けない<ruby>問題<rp>(</rp><rt>もんだい</rt><rp>)</rp></ruby>なので、<ruby>生徒<rp>(</rp><rt>せいと</rt><rp>)</rp></ruby>たちができないのも<ruby>無理<rp>(</rp><rt>むり</rt><rp>)</rp></ruby>はない。（就连老师都没有解答出来的问题，学生不会也情有可原。）"}],"id":"N1-135"},{"title":"136. ～に忍びない","blocks":[{"t":"label","label":"接续","text":"動辞書形 + に忍びない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + に<ruby>忍<rp>(</rp><rt>しの</rt><rp>)</rp></ruby>びない"},{"t":"label","label":"说明","text":"表示难以忍受或觉得痛心，“不忍心……、不堪……”。","furi":""},{"t":"label","label":"例句","text":"事故の被害者たちの姿はあまりにも気の毒で見るに忍びない。（事故受害者的样子简直惨不忍睹。）","furi":"<ruby>事故<rp>(</rp><rt>じこ</rt><rp>)</rp></ruby>の<ruby>被害<rp>(</rp><rt>ひがい</rt><rp>)</rp></ruby><ruby>者<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>たちの<ruby>姿<rp>(</rp><rt>すがた</rt><rp>)</rp></ruby>はあまりにも<ruby>気<rp>(</rp><rt>き</rt><rp>)</rp></ruby>の<ruby>毒<rp>(</rp><rt>どく</rt><rp>)</rp></ruby>で<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>るに<ruby>忍<rp>(</rp><rt>しの</rt><rp>)</rp></ruby>びない。（事故受害者的样子简直惨不忍睹。）"}],"id":"N1-136"},{"title":"137. ～に準じて／に準じ／に準じる","blocks":[{"t":"label","label":"接续","text":"名 + に準じ／に準じて／に準じる","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>準<rp>(</rp><rt>じゅん</rt><rp>)</rp></ruby>じ／に<ruby>準<rp>(</rp><rt>じゅん</rt><rp>)</rp></ruby>じて／に<ruby>準<rp>(</rp><rt>じゅん</rt><rp>)</rp></ruby>じる"},{"t":"label","label":"说明","text":"“以……为标准、按照……对待”。","furi":""},{"t":"label","label":"例句","text":"毎年の業務の実績及び勤務時間に準じて、ボーナスを決める。（根据每年的实际业绩和上班时间来决定年终奖。）","furi":"<ruby>毎年<rp>(</rp><rt>まいとし</rt><rp>)</rp></ruby>の<ruby>業務<rp>(</rp><rt>ぎょうむ</rt><rp>)</rp></ruby>の<ruby>実績<rp>(</rp><rt>じっせき</rt><rp>)</rp></ruby><ruby>及<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>び<ruby>勤務<rp>(</rp><rt>きんむ</rt><rp>)</rp></ruby><ruby>時間<rp>(</rp><rt>じかん</rt><rp>)</rp></ruby>に<ruby>準<rp>(</rp><rt>じゅん</rt><rp>)</rp></ruby>じて、ボーナスを<ruby>決<rp>(</rp><rt>き</rt><rp>)</rp></ruby>める。（根据每年的实际业绩和上班时间来决定年终奖。）"}],"id":"N1-137"},{"title":"138. ～に即して／に即した／に則して／に則した","blocks":[{"t":"label","label":"接续","text":"名 + に即して／に即した／に則して／に則した","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>即<rp>(</rp><rt>そく</rt><rp>)</rp></ruby>して／に<ruby>即<rp>(</rp><rt>そく</rt><rp>)</rp></ruby>した／に<ruby>則<rp>(</rp><rt>そく</rt><rp>)</rp></ruby>して／に<ruby>則<rp>(</rp><rt>そく</rt><rp>)</rp></ruby>した"},{"t":"label","label":"说明","text":"“按照……、依据……”。","furi":""},{"t":"label","label":"例句","text":"新聞には、事実に即して、正確な情報を提供してほしい。（报纸应该依据事实，提供准确情报。）","furi":"<ruby>新聞<rp>(</rp><rt>しんぶん</rt><rp>)</rp></ruby>には、<ruby>事実<rp>(</rp><rt>じじつ</rt><rp>)</rp></ruby>に<ruby>即<rp>(</rp><rt>そく</rt><rp>)</rp></ruby>して、<ruby>正確<rp>(</rp><rt>せいかく</rt><rp>)</rp></ruby>な<ruby>情報<rp>(</rp><rt>じょうほう</rt><rp>)</rp></ruby>を<ruby>提供<rp>(</rp><rt>ていきょう</rt><rp>)</rp></ruby>してほしい。（报纸应该依据事实，提供准确情报。）"}],"id":"N1-138"},{"title":"139. ～にたえる／にたえない","blocks":[{"t":"sub","text":"(1) ～にたえる","furi":""},{"t":"label","label":"接续","text":"動辞書形／名 + にたえる","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にたえる"},{"t":"label","label":"说明","text":"表示有价值，“值得……”。","furi":""},{"t":"label","label":"例句","text":"わが社が開発したこの機種は、多くのユーザーの評価にたえるものだ。（我们公司开发的这种型号的商品，深受用户好评。）","furi":"わが<ruby>社<rp>(</rp><rt>しゃ</rt><rp>)</rp></ruby>が<ruby>開発<rp>(</rp><rt>かいはつ</rt><rp>)</rp></ruby>したこの<ruby>機種<rp>(</rp><rt>きしゅ</rt><rp>)</rp></ruby>は、<ruby>多<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>くのユーザーの<ruby>評価<rp>(</rp><rt>ひょうか</rt><rp>)</rp></ruby>にたえるものだ。（我们公司开发的这种型号的商品，深受用户好评。）"},{"t":"sub","text":"(2) ～にたえない","furi":""},{"t":"label","label":"接续①","text":"動辞書形 + にたえない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + にたえない"},{"t":"label","label":"说明①","text":"表示评价，“无法……、不值得……”。","furi":""},{"t":"label","label":"例句①","text":"この番組はひどくて見るにたえない。（这个节目太糟糕了简直看不下去。）","furi":"この<ruby>番組<rp>(</rp><rt>ばんぐみ</rt><rp>)</rp></ruby>はひどくて<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>るにたえない。（这个节目太糟糕了简直看不下去。）"},{"t":"label","label":"接续②","text":"名 + にたえない","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にたえない"},{"t":"label","label":"说明②","text":"表示一种情感，“非常……、极其……”。","furi":""},{"t":"label","label":"例句②","text":"いろいろお世話になりました。感謝にたえません。（承蒙您多方关照，不胜感谢。）","furi":"いろいろお<ruby>世話<rp>(</rp><rt>せわ</rt><rp>)</rp></ruby>になりました。<ruby>感謝<rp>(</rp><rt>かんしゃ</rt><rp>)</rp></ruby>にたえません。（承蒙您多方关照，不胜感谢。）"}],"id":"N1-139"},{"title":"140. ～に足りる／に足る","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + に足りる／に足る","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>りる／に<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>る"},{"t":"label","label":"说明","text":"表示达到某种程度或要求，“值得……、足以……”。","furi":""},{"t":"label","label":"例句","text":"先日提出された調査報告は信頼に足るものではなかった。（上次提交的调查报告不足为信。）","furi":"<ruby>先日<rp>(</rp><rt>せんじつ</rt><rp>)</rp></ruby><ruby>提出<rp>(</rp><rt>ていしゅつ</rt><rp>)</rp></ruby>された<ruby>調査<rp>(</rp><rt>ちょうさ</rt><rp>)</rp></ruby><ruby>報告<rp>(</rp><rt>ほうこく</rt><rp>)</rp></ruby>は<ruby>信頼<rp>(</rp><rt>しんらい</rt><rp>)</rp></ruby>に<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>るものではなかった。（上次提交的调查报告不足为信。）"}],"id":"N1-140"},{"title":"141. ～に足りない／に足らない","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + に足りない／に足らない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>りない／に<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>らない"},{"t":"label","label":"说明","text":"表示不足以那样去做，“不值得……、不足以……”。","furi":""},{"t":"label","label":"例句","text":"相手チームは実力が足りないので、恐れるに足らない。（对手实力欠缺，不足为惧。）","furi":"<ruby>相手<rp>(</rp><rt>あいて</rt><rp>)</rp></ruby>チームは<ruby>実力<rp>(</rp><rt>じつりょく</rt><rp>)</rp></ruby>が<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>りないので、<ruby>恐<rp>(</rp><rt>おそ</rt><rp>)</rp></ruby>れるに<ruby>足<rp>(</rp><rt>た</rt><rp>)</rp></ruby>らない。（对手实力欠缺，不足为惧。）"}],"id":"N1-141"},{"title":"142. ～に照らして","blocks":[{"t":"label","label":"接续","text":"名 + に照らして","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>照<rp>(</rp><rt>て</rt><rp>)</rp></ruby>らして"},{"t":"label","label":"说明","text":"表示动作、行为的依据，“依照……、对照……”。","furi":""},{"t":"label","label":"例句","text":"法律に照らして処分する。（依法判处。）","furi":"<ruby>法律<rp>(</rp><rt>ほうりつ</rt><rp>)</rp></ruby>に<ruby>照<rp>(</rp><rt>て</rt><rp>)</rp></ruby>らして<ruby>処分<rp>(</rp><rt>しょぶん</rt><rp>)</rp></ruby>する。（依法判处。）"}],"id":"N1-142"},{"title":"143. ～にとどまらず","blocks":[{"t":"label","label":"接续","text":"名 +（だけ/のみ）+ にとどまらず","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> +（だけ/のみ）+ にとどまらず"},{"t":"label","label":"说明","text":"“不仅停留在……而且（还波及到）……”。","furi":""},{"t":"label","label":"例句","text":"火山の噴火の影響は、ふもとにとどまらず、周辺地域全体に及んだ。（火山爆发不仅影响到山脚地带，还波及到周边地区。）","furi":"<ruby>火山<rp>(</rp><rt>かざん</rt><rp>)</rp></ruby>の<ruby>噴火<rp>(</rp><rt>ふんか</rt><rp>)</rp></ruby>の<ruby>影響<rp>(</rp><rt>えいきょう</rt><rp>)</rp></ruby>は、ふもとにとどまらず、<ruby>周辺<rp>(</rp><rt>しゅうへん</rt><rp>)</rp></ruby><ruby>地域<rp>(</rp><rt>ちいき</rt><rp>)</rp></ruby><ruby>全体<rp>(</rp><rt>ぜんたい</rt><rp>)</rp></ruby>に<ruby>及<rp>(</rp><rt>およ</rt><rp>)</rp></ruby>んだ。（火山爆发不仅影响到山脚地带，还波及到周边地区。）"}],"id":"N1-143"},{"title":"144. ～に則って","blocks":[{"t":"label","label":"接续","text":"名 + に則って","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + に<ruby>則<rp>(</rp><rt>のっと</rt><rp>)</rp></ruby>って"},{"t":"label","label":"说明","text":"“依据……、按照……、效法……”。","furi":""},{"t":"label","label":"例句","text":"古式に則って、結婚式を行いました。（效法古礼，举办了婚礼。）","furi":"<ruby>古式<rp>(</rp><rt>こしき</rt><rp>)</rp></ruby>に<ruby>則<rp>(</rp><rt>のっと</rt><rp>)</rp></ruby>って、<ruby>結婚式<rp>(</rp><rt>けっこんしき</rt><rp>)</rp></ruby>を<ruby>行<rp>(</rp><rt>おこな</rt><rp>)</rp></ruby>いました。（效法古礼，举办了婚礼。）"}],"id":"N1-144"},{"title":"145. ～には無理がある","blocks":[{"t":"label","label":"接续","text":"動辞書形／名 + には無理がある","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + には<ruby>無理<rp>(</rp><rt>むり</rt><rp>)</rp></ruby>がある"},{"t":"label","label":"说明","text":"“……方面有不合理的地方、……有行不通的地方”。","furi":""},{"t":"label","label":"例句","text":"ただ3か月でこのプロジェクトを完成するには無理がある。（想在三个月之内完成这个项目有点困难。）","furi":"ただ3か<ruby>月<rp>(</rp><rt>げつ</rt><rp>)</rp></ruby>でこのプロジェクトを<ruby>完成<rp>(</rp><rt>かんせい</rt><rp>)</rp></ruby>するには<ruby>無理<rp>(</rp><rt>むり</rt><rp>)</rp></ruby>がある。（想在三个月之内完成这个项目有点困难。）"}],"id":"N1-145"},{"title":"146. ～にひきかえ／にひきかえて","blocks":[{"t":"label","label":"接续","text":"名 + にひきかえ／にひきかえて","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にひきかえ／にひきかえて"},{"t":"label","label":"说明","text":"表示对比，“与……相反、与……不同”。","furi":""},{"t":"label","label":"例句","text":"弟が社交的なタイプなのにひきかえて、兄は人前に出るのを嫌うタイプだ。（弟弟是个擅长交际的人，哥哥却不太喜欢与人交往。）","furi":"<ruby>弟<rp>(</rp><rt>おとうと</rt><rp>)</rp></ruby>が<ruby>社交<rp>(</rp><rt>しゃこう</rt><rp>)</rp></ruby><ruby>的<rp>(</rp><rt>てき</rt><rp>)</rp></ruby>なタイプなのにひきかえて、<ruby>兄<rp>(</rp><rt>あに</rt><rp>)</rp></ruby>は<ruby>人前<rp>(</rp><rt>ひとまえ</rt><rp>)</rp></ruby>に<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>るのを<ruby>嫌<rp>(</rp><rt>きら</rt><rp>)</rp></ruby>うタイプだ。（弟弟是个擅长交际的人，哥哥却不太喜欢与人交往。）"}],"id":"N1-146"},{"title":"147. ～にもほどがある","blocks":[{"t":"label","label":"说明","text":"告诫做事要适可而止，“……也应该有个度、……也应该有分寸”。","furi":""},{"t":"label","label":"例句","text":"先輩に対して、あんな失礼なことを言うなんて、無神経にもほどがある。（居然对前辈讲那么失礼的话，真是太迟钝了。）","furi":"<ruby>先輩<rp>(</rp><rt>せんぱい</rt><rp>)</rp></ruby>に<ruby>対<rp>(</rp><rt>たい</rt><rp>)</rp></ruby>して、あんな<ruby>失礼<rp>(</rp><rt>しつれい</rt><rp>)</rp></ruby>なことを<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>うなんて、<ruby>無神経<rp>(</rp><rt>むしんけい</rt><rp>)</rp></ruby>にもほどがある。（居然对前辈讲那么失礼的话，真是太迟钝了。）"}],"id":"N1-147"},{"title":"148. ～にもまして","blocks":[{"t":"label","label":"接续","text":"動・イ形・ナ形の名詞修飾形 + の／名 + にもまして","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>・イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>・ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>の<ruby>名詞<rp>(</rp><rt>めいし</rt><rp>)</rp></ruby><ruby>修飾<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + の／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + にもまして"},{"t":"label","label":"说明","text":"“比……更加……、超过……”。","furi":""},{"t":"label","label":"例句","text":"大学生の就職は、今年は去年にもまして、さらに厳しい状況になることが予想される。（大学生的就业情况，今年会比去年更加严峻。）","furi":"<ruby>大学生<rp>(</rp><rt>だいがくせい</rt><rp>)</rp></ruby>の<ruby>就職<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby>は、<ruby>今年<rp>(</rp><rt>ことし</rt><rp>)</rp></ruby>は<ruby>去年<rp>(</rp><rt>きょねん</rt><rp>)</rp></ruby>にもまして、さらに<ruby>厳<rp>(</rp><rt>きび</rt><rp>)</rp></ruby>しい<ruby>状況<rp>(</rp><rt>じょうきょう</rt><rp>)</rp></ruby>になることが<ruby>予想<rp>(</rp><rt>よそう</rt><rp>)</rp></ruby>される。（大学生的就业情况，今年会比去年更加严峻。）"}],"id":"N1-148"},{"title":"149. ～によるところが大きい","blocks":[{"t":"label","label":"接续","text":"名 + によるところが大きい","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + によるところが<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きい"},{"t":"label","label":"说明","text":"表示前项在很大程度上依赖后项，“得益于……、多亏了……、主要依赖于……”。","furi":""},{"t":"label","label":"例句","text":"かつて映画スターであった山田氏が初挑戦で知事選に勝利したのは、能力というより、人気と知名度によるところが大きい。（山田曾经是电影明星，他第一次参选知事就获得了成功，与其说是凭借实力，不如说很大程度上得益于他（她）的人气和知名度。）","furi":"かつて<ruby>映画<rp>(</rp><rt>えいが</rt><rp>)</rp></ruby>スターであった<ruby>山田<rp>(</rp><rt>やまだ</rt><rp>)</rp></ruby><ruby>氏<rp>(</rp><rt>し</rt><rp>)</rp></ruby>が<ruby>初<rp>(</rp><rt>はつ</rt><rp>)</rp></ruby><ruby>挑戦<rp>(</rp><rt>ちょうせん</rt><rp>)</rp></ruby>で<ruby>知事<rp>(</rp><rt>ちじ</rt><rp>)</rp></ruby><ruby>選<rp>(</rp><rt>せん</rt><rp>)</rp></ruby>に<ruby>勝利<rp>(</rp><rt>しょうり</rt><rp>)</rp></ruby>したのは、<ruby>能力<rp>(</rp><rt>のうりょく</rt><rp>)</rp></ruby>というより、<ruby>人気<rp>(</rp><rt>にんき</rt><rp>)</rp></ruby>と<ruby>知名度<rp>(</rp><rt>ちめいど</rt><rp>)</rp></ruby>によるところが<ruby>大<rp>(</rp><rt>おお</rt><rp>)</rp></ruby>きい。（山田曾经是电影明星，他第一次参选知事就获得了成功，与其说是凭借实力，不如说很大程度上得益于他（她）的人气和知名度。）"}],"id":"N1-149"},{"title":"150. ～の至り","blocks":[{"t":"label","label":"接续","text":"名 + の至り","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + の<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>り"},{"t":"label","label":"说明","text":"表示达到极致，“非常……、……之极”。多用固定搭配。","furi":""},{"t":"label","label":"例句","text":"こんな立派な賞をいただけて、光栄の至りです。（能够得到如此大奖无比的光荣。）","furi":"こんな<ruby>立派<rp>(</rp><rt>りっぱ</rt><rp>)</rp></ruby>な<ruby>賞<rp>(</rp><rt>しょう</rt><rp>)</rp></ruby>をいただけて、<ruby>光栄<rp>(</rp><rt>こうえい</rt><rp>)</rp></ruby>の<ruby>至<rp>(</rp><rt>いた</rt><rp>)</rp></ruby>りです。（能够得到如此大奖无比的光荣。）"}],"id":"N1-150"},{"title":"151. ～の極み","blocks":[{"t":"label","label":"接续","text":"名 + の極み","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + の<ruby>極<rp>(</rp><rt>きわ</rt><rp>)</rp></ruby>み"},{"t":"label","label":"说明","text":"表示程度达到极限，“极其……、……之极”。","furi":""},{"t":"label","label":"例句","text":"残業続きで、疲労の極みに達している。（持续加班，让我筋疲力尽。）","furi":"<ruby>残業<rp>(</rp><rt>ざんぎょう</rt><rp>)</rp></ruby><ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>きで、<ruby>疲労<rp>(</rp><rt>ひろう</rt><rp>)</rp></ruby>の<ruby>極<rp>(</rp><rt>きわ</rt><rp>)</rp></ruby>みに<ruby>達<rp>(</rp><rt>たっ</rt><rp>)</rp></ruby>している。（持续加班，让我筋疲力尽。）"}],"id":"N1-151"},{"title":"152. ～のなんの","blocks":[{"t":"label","label":"接续","text":"動辞書形／ナ形語幹／イ形／名 + のなんの","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + のなんの"},{"t":"label","label":"说明","text":"列举有代表性的负面言论，“又是说……又是说什么的、说这说那的”。","furi":""},{"t":"label","label":"例句","text":"給料が低いのなんのと文句ばかり言っている。（又是说工资低又是说什么的，尽是抱怨。）","furi":"<ruby>給料<rp>(</rp><rt>きゅうりょう</rt><rp>)</rp></ruby>が<ruby>低<rp>(</rp><rt>ひく</rt><rp>)</rp></ruby>いのなんのと<ruby>文句<rp>(</rp><rt>もんく</rt><rp>)</rp></ruby>ばかり<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>っている。（又是说工资低又是说什么的，尽是抱怨。）"}],"id":"N1-152"},{"title":"153. ～はおろか","blocks":[{"t":"label","label":"接续","text":"名 + はおろか","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + はおろか"},{"t":"label","label":"说明","text":"表示附加关系，“别说……，就连……（都不会）”。","furi":""},{"t":"label","label":"例句","text":"父も母も海外旅行はおろか国内さえもほとんど見て回ったことがない。（父母亲别说是国外旅行了，就连国内的地方也没怎么去过。）","furi":"<ruby>父<rp>(</rp><rt>ちち</rt><rp>)</rp></ruby>も<ruby>母<rp>(</rp><rt>はは</rt><rp>)</rp></ruby>も<ruby>海外<rp>(</rp><rt>かいがい</rt><rp>)</rp></ruby><ruby>旅行<rp>(</rp><rt>りょこう</rt><rp>)</rp></ruby>はおろか<ruby>国内<rp>(</rp><rt>こくない</rt><rp>)</rp></ruby>さえもほとんど<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>て<ruby>回<rp>(</rp><rt>まわ</rt><rp>)</rp></ruby>ったことがない。（父母亲别说是国外旅行了，就连国内的地方也没怎么去过。）"}],"id":"N1-153"},{"title":"154. ～ばこそ","blocks":[{"t":"label","label":"接续","text":"動ば形 + こそ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ば<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + こそ"},{"t":"label","label":"说明","text":"强调原因，“正因为……才……”。","furi":""},{"t":"label","label":"例句","text":"彼女の働きがあればこそ、計画が順調に進んでいるのだ。（正是因为有了她的努力，计划才会如此顺利。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>の<ruby>働<rp>(</rp><rt>はたら</rt><rp>)</rp></ruby>きがあればこそ、<ruby>計画<rp>(</rp><rt>けいかく</rt><rp>)</rp></ruby>が<ruby>順調<rp>(</rp><rt>じゅんちょう</rt><rp>)</rp></ruby>に<ruby>進<rp>(</rp><rt>すす</rt><rp>)</rp></ruby>んでいるのだ。（正是因为有了她的努力，计划才会如此顺利。）"}],"id":"N1-154"},{"title":"155. ～はさておき／はさておいて","blocks":[{"t":"label","label":"接续","text":"名 + はさておき／はさておいて","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + はさておき／はさておいて"},{"t":"label","label":"说明","text":"表示其他事情暂时放一放，“其他的暂且不论，首先……”。","furi":""},{"t":"label","label":"例句","text":"実現できるかどうかはさておき、まずは新商品のアイディアをみんなで出してみよう。（至于能否实现另当别论，大家先想想新产品的创意。）","furi":"<ruby>実現<rp>(</rp><rt>じつげん</rt><rp>)</rp></ruby>できるかどうかはさておき、まずは<ruby>新<rp>(</rp><rt>しん</rt><rp>)</rp></ruby><ruby>商品<rp>(</rp><rt>しょうひん</rt><rp>)</rp></ruby>のアイディアをみんなで<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>してみよう。（至于能否实现另当别论，大家先想想新产品的创意。）"}],"id":"N1-155"},{"title":"156. ～弾み","blocks":[{"t":"label","label":"接续","text":"動辞書形/た形 + 弾みに／名 + の弾みで","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>弾<rp>(</rp><rt>はず</rt><rp>)</rp></ruby>みに／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + の<ruby>弾<rp>(</rp><rt>はず</rt><rp>)</rp></ruby>みで"},{"t":"label","label":"说明","text":"“在……的时候、刚一……就……”。","furi":""},{"t":"label","label":"例句","text":"バスの急ブレーキの弾みで、立っていた乗客が転倒するなどして軽いけがを負った。（公交车急刹车使得站着的乘客摔倒受了轻伤。）","furi":"バスの<ruby>急<rp>(</rp><rt>きゅう</rt><rp>)</rp></ruby>ブレーキの<ruby>弾<rp>(</rp><rt>はず</rt><rp>)</rp></ruby>みで、<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>っていた<ruby>乗客<rp>(</rp><rt>じょうきゃく</rt><rp>)</rp></ruby>が<ruby>転倒<rp>(</rp><rt>てんとう</rt><rp>)</rp></ruby>するなどして<ruby>軽<rp>(</rp><rt>かる</rt><rp>)</rp></ruby>いけがを<ruby>負<rp>(</rp><rt>お</rt><rp>)</rp></ruby>った。（公交车急刹车使得站着的乘客摔倒受了轻伤。）"}],"id":"N1-156"},{"title":"157. ～はそっちのけで／をそっちのけで","blocks":[{"t":"label","label":"接续","text":"名 + はそっちのけで／をそっちのけで","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + はそっちのけで／をそっちのけで"},{"t":"label","label":"说明","text":"“抛开不管、不顾……”。把本应做的事放在一边做其他事。","furi":""},{"t":"label","label":"例句","text":"彼女は本業をそっちのけで、副業に精を出している。（她把本职工作抛在一边，一心扑在副业上。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>は<ruby>本業<rp>(</rp><rt>ほんぎょう</rt><rp>)</rp></ruby>をそっちのけで、<ruby>副業<rp>(</rp><rt>ふくぎょう</rt><rp>)</rp></ruby>に<ruby>精<rp>(</rp><rt>せい</rt><rp>)</rp></ruby>を<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>している。（她把本职工作抛在一边，一心扑在副业上。）"}],"id":"N1-157"},{"title":"158. ～ばそれまでだ","blocks":[{"t":"label","label":"接续","text":"動ば形 + それまでだ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ば<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + それまでだ"},{"t":"label","label":"说明","text":"表示假定条件，“……的话，也就完了、……的话，也就没有意义了”。","furi":""},{"t":"label","label":"例句","text":"この精密機械は水に弱い。水がかかればそれまでだ。（这种精密仪器很怕水，一旦沾水了就报废了。）","furi":"この<ruby>精密<rp>(</rp><rt>せいみつ</rt><rp>)</rp></ruby><ruby>機械<rp>(</rp><rt>きかい</rt><rp>)</rp></ruby>は<ruby>水<rp>(</rp><rt>みず</rt><rp>)</rp></ruby>に<ruby>弱<rp>(</rp><rt>よわ</rt><rp>)</rp></ruby>い。<ruby>水<rp>(</rp><rt>みず</rt><rp>)</rp></ruby>がかかればそれまでだ。（这种精密仪器很怕水，一旦沾水了就报废了。）"}],"id":"N1-158"},{"title":"159. ～羽目になる／羽目に陥る","blocks":[{"t":"label","label":"接续","text":"動辞書形 + 羽目になる／羽目に陥る","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + <ruby>羽目<rp>(</rp><rt>はめ</rt><rp>)</rp></ruby>になる／<ruby>羽目<rp>(</rp><rt>はめ</rt><rp>)</rp></ruby>に<ruby>陥<rp>(</rp><rt>おちい</rt><rp>)</rp></ruby>る"},{"t":"label","label":"说明","text":"表示因某种原因陷入困境，“落到……地步、陷入……境地”。","furi":""},{"t":"label","label":"例句","text":"就職活動に失敗して苦しい羽目に陥った。（找不到工作情况十分糟糕。）","furi":"<ruby>就職<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>活動<rp>(</rp><rt>かつどう</rt><rp>)</rp></ruby>に<ruby>失敗<rp>(</rp><rt>しっぱい</rt><rp>)</rp></ruby>して<ruby>苦<rp>(</rp><rt>くる</rt><rp>)</rp></ruby>しい<ruby>羽目<rp>(</rp><rt>はめ</rt><rp>)</rp></ruby>に<ruby>陥<rp>(</rp><rt>おちい</rt><rp>)</rp></ruby>った。（找不到工作情况十分糟糕。）"}],"id":"N1-159"},{"title":"160. ～べからず／べからざる","blocks":[{"t":"sub","text":"(1) ～べからず","furi":""},{"t":"label","label":"接续","text":"動辞書形 + べからず（する→すべからず／するべからず）","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + べからず（する→すべからず／するべからず）"},{"t":"label","label":"说明","text":"表示禁止，“禁止……、不要……”。用于布告、告示牌。","furi":""},{"t":"label","label":"例句","text":"『危険！工事中につき、立ち入るべからず。』（危险！施工中请勿进入。）","furi":"『<ruby>危険<rp>(</rp><rt>きけん</rt><rp>)</rp></ruby>！<ruby>工事<rp>(</rp><rt>こうじ</rt><rp>)</rp></ruby><ruby>中<rp>(</rp><rt>ちゅう</rt><rp>)</rp></ruby>につき、<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>ち<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>るべからず。』（危险！施工中请勿进入。）"},{"t":"sub","text":"(2) ～べからざる","furi":""},{"t":"label","label":"接续","text":"動辞書形 + べからざる（する→すべからざる）","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + べからざる（する→すべからざる）"},{"t":"label","label":"说明","text":"表示禁止，作为定语修饰名词，“不应该做的……”。","furi":""},{"t":"label","label":"例句","text":"彼はうちの会社にとって欠くべからざる人材だ。（他是我们公司不可缺少的人才。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>はうちの<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>にとって<ruby>欠<rp>(</rp><rt>か</rt><rp>)</rp></ruby>くべからざる<ruby>人材<rp>(</rp><rt>じんざい</rt><rp>)</rp></ruby>だ。（他是我们公司不可缺少的人才。）"}],"id":"N1-160"},{"title":"161. ～べく","blocks":[{"t":"label","label":"接续","text":"動辞書形 + べく（する→すべく／するべく）","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + べく（する→すべく／するべく）"},{"t":"label","label":"说明","text":"表示目的，“为了……、想要……”。后接具体动作动词。","furi":""},{"t":"label","label":"例句","text":"彼を見舞うべく病院を訪ねた。（为了探望他到医院去了。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>を<ruby>見舞<rp>(</rp><rt>みま</rt><rp>)</rp></ruby>うべく<ruby>病院<rp>(</rp><rt>びょういん</rt><rp>)</rp></ruby>を<ruby>訪<rp>(</rp><rt>たず</rt><rp>)</rp></ruby>ねた。（为了探望他到医院去了。）"}],"id":"N1-161"},{"title":"162. ～べくして","blocks":[{"t":"label","label":"接续","text":"動辞書形 + べくして","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + べくして"},{"t":"label","label":"说明","text":"表示一种必然性，“该（发生）的就（发生）了、……的出现是必然的”。","furi":""},{"t":"label","label":"例句","text":"彼は練習に練習を重ねてきて、勝つべくして勝ったのだ。（他的获胜不是偶然的，是通过不断的练习才取得的。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby>に<ruby>練習<rp>(</rp><rt>れんしゅう</rt><rp>)</rp></ruby>を<ruby>重<rp>(</rp><rt>かさ</rt><rp>)</rp></ruby>ねてきて、<ruby>勝<rp>(</rp><rt>か</rt><rp>)</rp></ruby>つべくして<ruby>勝<rp>(</rp><rt>か</rt><rp>)</rp></ruby>ったのだ。（他的获胜不是偶然的，是通过不断的练习才取得的。）"}],"id":"N1-162"},{"title":"163. ～べくもない","blocks":[{"t":"label","label":"接续","text":"動辞書形 + べくもない（する→すべくもない／するべくもない）","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + べくもない（する→すべくもない／するべくもない）"},{"t":"label","label":"说明","text":"表示否定，“做不到……、不可能……”。文言体。","furi":""},{"t":"label","label":"例句","text":"主力が抜けているので、優勝は望むべくもない。（主力队员没有上场，夺冠没有指望。）","furi":"<ruby>主力<rp>(</rp><rt>しゅりょく</rt><rp>)</rp></ruby>が<ruby>抜<rp>(</rp><rt>ぬ</rt><rp>)</rp></ruby>けているので、<ruby>優勝<rp>(</rp><rt>ゆうしょう</rt><rp>)</rp></ruby>は<ruby>望<rp>(</rp><rt>のぞ</rt><rp>)</rp></ruby>むべくもない。（主力队员没有上场，夺冠没有指望。）"}],"id":"N1-163"},{"title":"164. ～まじき","blocks":[{"t":"label","label":"接续","text":"動辞書形 + まじき","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + まじき"},{"t":"label","label":"说明","text":"表示出于某种身份不应该做某事，“作为……不应该有的行为”。","furi":""},{"t":"label","label":"例句","text":"患者のプライバシーをほかの人に漏らすなんて、医者としてあるまじきことだ。（作为一名医生，泄露患者的隐私是不能允许的行为。）","furi":"<ruby>患者<rp>(</rp><rt>かんじゃ</rt><rp>)</rp></ruby>のプライバシーをほかの<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>に<ruby>漏<rp>(</rp><rt>も</rt><rp>)</rp></ruby>らすなんて、<ruby>医者<rp>(</rp><rt>いしゃ</rt><rp>)</rp></ruby>としてあるまじきことだ。（作为一名医生，泄露患者的隐私是不能允许的行为。）"}],"id":"N1-164"},{"title":"165. ～までして","blocks":[{"t":"label","label":"接续","text":"名 + までして","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + までして"},{"t":"label","label":"说明","text":"表示极端的行为，“甚至于到了……的地步、不惜……”。","furi":""},{"t":"label","label":"例句","text":"この絵は、昔父が借金までして手に入れたものです。（这幅画是父亲曾经不惜借钱购得的。）","furi":"この<ruby>絵<rp>(</rp><rt>え</rt><rp>)</rp></ruby>は、<ruby>昔<rp>(</rp><rt>むかし</rt><rp>)</rp></ruby><ruby>父<rp>(</rp><rt>ちち</rt><rp>)</rp></ruby>が<ruby>借金<rp>(</rp><rt>しゃっきん</rt><rp>)</rp></ruby>までして<ruby>手<rp>(</rp><rt>て</rt><rp>)</rp></ruby>に<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>れたものです。（这幅画是父亲曾经不惜借钱购得的。）"}],"id":"N1-165"},{"title":"166. ～までだ／までのことだ","blocks":[{"t":"sub","text":"(1) 接续","furi":""},{"t":"line","text":"動辞書形/た形 + までだ／までのことだ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + までだ／までのことだ"},{"t":"label","label":"说明","text":"表示程度轻，“只不过……罢了、只是……而已”。","furi":""},{"t":"label","label":"例句","text":"就職が決まらなくても困らない。アルバイトをして生活するまでだ。（找不到工作也没关系，那样的话只不过要靠打工来维持生计而已。）","furi":"<ruby>就職<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby>が<ruby>決<rp>(</rp><rt>き</rt><rp>)</rp></ruby>まらなくても<ruby>困<rp>(</rp><rt>こま</rt><rp>)</rp></ruby>らない。アルバイトをして<ruby>生活<rp>(</rp><rt>せいかつ</rt><rp>)</rp></ruby>するまでだ。（找不到工作也没关系，那样的话只不过要靠打工来维持生计而已。）"},{"t":"sub","text":"(2) 接续","furi":""},{"t":"line","text":"動辞書形 + までだ／までのことだ","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + までだ／までのことだ"},{"t":"label","label":"说明","text":"表示别无选择，“只好……、只有……”。","furi":""},{"t":"label","label":"例句","text":"終電に乗り遅れたので、歩いて帰るまでのことだ。（错过了末班车，只能走着回去。）","furi":"<ruby>終電<rp>(</rp><rt>しゅうでん</rt><rp>)</rp></ruby>に<ruby>乗<rp>(</rp><rt>の</rt><rp>)</rp></ruby>り<ruby>遅<rp>(</rp><rt>おく</rt><rp>)</rp></ruby>れたので、<ruby>歩<rp>(</rp><rt>ある</rt><rp>)</rp></ruby>いて<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>るまでのことだ。（错过了末班车，只能走着回去。）"}],"id":"N1-166"},{"title":"167. ～までもなく／までもない","blocks":[{"t":"label","label":"接续","text":"動辞書形 + までもなく／までもない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + までもなく／までもない"},{"t":"label","label":"说明","text":"“没有必要……、用不着……”。","furi":""},{"t":"label","label":"例句","text":"孫が無事生まれたとの知らせに、彼が喜んだのは言うまでもない。（知道了孙子平安无事地出生，他的喜悦之情无以言表。）","furi":"<ruby>孫<rp>(</rp><rt>まご</rt><rp>)</rp></ruby>が<ruby>無事<rp>(</rp><rt>ぶじ</rt><rp>)</rp></ruby><ruby>生<rp>(</rp><rt>う</rt><rp>)</rp></ruby>まれたとの<ruby>知<rp>(</rp><rt>し</rt><rp>)</rp></ruby>らせに、<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>が<ruby>喜<rp>(</rp><rt>よろこ</rt><rp>)</rp></ruby>んだのは<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>うまでもない。（知道了孙子平安无事地出生，他的喜悦之情无以言表。）"}],"id":"N1-167"},{"title":"168. ～まみれ","blocks":[{"t":"label","label":"接续","text":"名 + まみれ","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + まみれ"},{"t":"label","label":"说明","text":"表示状态，“全是……、满是……、浑身都是……”，多指脏的或不好的东西。","furi":""},{"t":"label","label":"例句","text":"押し入れの中から埃まみれの昔のアルバムが見つかった。（从壁橱里找出了满是灰尘的过去的相册。）","furi":"<ruby>押<rp>(</rp><rt>お</rt><rp>)</rp></ruby>し<ruby>入<rp>(</rp><rt>い</rt><rp>)</rp></ruby>れの<ruby>中<rp>(</rp><rt>なか</rt><rp>)</rp></ruby>から<ruby>埃<rp>(</rp><rt>ほこり</rt><rp>)</rp></ruby>まみれの<ruby>昔<rp>(</rp><rt>むかし</rt><rp>)</rp></ruby>のアルバムが<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>つかった。（从壁橱里找出了满是灰尘的过去的相册。）"}],"id":"N1-168"},{"title":"169. ～めく","blocks":[{"t":"label","label":"接续","text":"名 + めく","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + めく"},{"t":"label","label":"说明","text":"表示某种状态和特征，“带有……的气息、变成……的样子”。","furi":""},{"t":"label","label":"例句","text":"そんな皮肉めいた言い方をしないでください。（请不要用这种话里带刺的讲话方式。）","furi":"そんな<ruby>皮肉<rp>(</rp><rt>ひにく</rt><rp>)</rp></ruby>めいた<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>い<ruby>方<rp>(</rp><rt>かた</rt><rp>)</rp></ruby>をしないでください。（请不要用这种话里带刺的讲话方式。）"}],"id":"N1-169"},{"title":"170. ～も顧みず／を顧みず","blocks":[{"t":"label","label":"接续","text":"名 + も顧みず／を顧みず","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + も<ruby>顧<rp>(</rp><rt>かえり</rt><rp>)</rp></ruby>みず／を<ruby>顧<rp>(</rp><rt>かえり</rt><rp>)</rp></ruby>みず"},{"t":"label","label":"说明","text":"表示不顾某种危险性坚持做某事，“不顾……、不管……”。","furi":""},{"t":"label","label":"例句","text":"家族のことも自分の健康も顧みず懸命に会社のために働いた。（为了工作牺牲了自己的家庭甚至身体健康。）","furi":"<ruby>家族<rp>(</rp><rt>かぞく</rt><rp>)</rp></ruby>のことも<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>の<ruby>健康<rp>(</rp><rt>けんこう</rt><rp>)</rp></ruby>も<ruby>顧<rp>(</rp><rt>かえり</rt><rp>)</rp></ruby>みず<ruby>懸命<rp>(</rp><rt>けんめい</rt><rp>)</rp></ruby>に<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby>のために<ruby>働<rp>(</rp><rt>はたら</rt><rp>)</rp></ruby>いた。（为了工作牺牲了自己的家庭甚至身体健康。）"}],"id":"N1-170"},{"title":"171. ～もさることながら","blocks":[{"t":"label","label":"接续","text":"名 + もさることながら","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + もさることながら"},{"t":"label","label":"说明","text":"表示前后关联，相比前项后项更……，“……自不必说，……更是如此”。","furi":""},{"t":"label","label":"例句","text":"両親は、息子に病院の跡を継いで医者になってほしいと思っているようだ。だが、親の希望もさることながら、やはり本人の気持ちが第一だろう。（父母都希望儿子能够继承医院当医生。但是相比之下，个人的想法其实才是最重要的。）","furi":"<ruby>両親<rp>(</rp><rt>りょうしん</rt><rp>)</rp></ruby>は、<ruby>息子<rp>(</rp><rt>むすこ</rt><rp>)</rp></ruby>に<ruby>病院<rp>(</rp><rt>びょういん</rt><rp>)</rp></ruby>の<ruby>跡<rp>(</rp><rt>あと</rt><rp>)</rp></ruby>を<ruby>継<rp>(</rp><rt>つ</rt><rp>)</rp></ruby>いで<ruby>医者<rp>(</rp><rt>いしゃ</rt><rp>)</rp></ruby>になってほしいと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>っているようだ。だが、<ruby>親<rp>(</rp><rt>おや</rt><rp>)</rp></ruby>の<ruby>希望<rp>(</rp><rt>きぼう</rt><rp>)</rp></ruby>もさることながら、やはり<ruby>本人<rp>(</rp><rt>ほんにん</rt><rp>)</rp></ruby>の<ruby>気持<rp>(</rp><rt>きも</rt><rp>)</rp></ruby>ちが<ruby>第<rp>(</rp><rt>だい</rt><rp>)</rp></ruby><ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby>だろう。（父母都希望儿子能够继承医院当医生。但是相比之下，个人的想法其实才是最重要的。）"}],"id":"N1-171"},{"title":"172. ～も同然だ／も同然の","blocks":[{"t":"label","label":"接续","text":"動た形／名 + も同然だ／も同然の","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + も<ruby>同然<rp>(</rp><rt>どうぜん</rt><rp>)</rp></ruby>だ／も<ruby>同然<rp>(</rp><rt>どうぜん</rt><rp>)</rp></ruby>の"},{"t":"label","label":"说明","text":"“几乎等同于……、几乎跟……一样”。","furi":""},{"t":"label","label":"例句","text":"彼とは家族も同然の付き合いをしている。（跟他的交情就像家人一样。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>とは<ruby>家族<rp>(</rp><rt>かぞく</rt><rp>)</rp></ruby>も<ruby>同然<rp>(</rp><rt>どうぜん</rt><rp>)</rp></ruby>の<ruby>付<rp>(</rp><rt>つ</rt><rp>)</rp></ruby>き<ruby>合<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>いをしている。（跟他的交情就像家人一样。）"}],"id":"N1-172"},{"title":"173. ～ものと思われる","blocks":[{"t":"label","label":"接续","text":"動／イ形／ナ形の名詞修飾形 + ものと思われる","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>の<ruby>名詞<rp>(</rp><rt>めいし</rt><rp>)</rp></ruby><ruby>修飾<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ものと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>われる"},{"t":"label","label":"说明","text":"表示大多数人的看法，“在大家看来……、人们一般认为……”。","furi":""},{"t":"label","label":"例句","text":"犯人は海外へ逃亡したものと思われる。（人们认为犯人是逃往了国外。）","furi":"<ruby>犯人<rp>(</rp><rt>はんにん</rt><rp>)</rp></ruby>は<ruby>海外<rp>(</rp><rt>かいがい</rt><rp>)</rp></ruby>へ<ruby>逃亡<rp>(</rp><rt>とうぼう</rt><rp>)</rp></ruby>したものと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>われる。（人们认为犯人是逃往了国外。）"}],"id":"N1-173"},{"title":"174. ～ものを","blocks":[{"t":"label","label":"接续","text":"動／イ形／ナ形の名詞修飾形 + ものを","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>の<ruby>名詞<rp>(</rp><rt>めいし</rt><rp>)</rp></ruby><ruby>修飾<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ものを"},{"t":"label","label":"说明","text":"表示对已经发生的事情的假设，“要是……就好了、早知道……就好了”，表达不满、后悔。","furi":""},{"t":"label","label":"例句","text":"電話をしてくれれば、迎えに行ったものを。（要是打个电话给我的话，就去接你了。）","furi":"<ruby>電話<rp>(</rp><rt>でんわ</rt><rp>)</rp></ruby>をしてくれれば、<ruby>迎<rp>(</rp><rt>むか</rt><rp>)</rp></ruby>えに<ruby>行<rp>(</rp><rt>い</rt><rp>)</rp></ruby>ったものを。（要是打个电话给我的话，就去接你了。）"}],"id":"N1-174"},{"title":"175. ～や／や否や","blocks":[{"t":"label","label":"接续","text":"動辞書形 + や／や否や","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + や／や<ruby>否<rp>(</rp><rt>いな</rt><rp>)</rp></ruby>や"},{"t":"label","label":"说明","text":"表示前项动作结束后后项紧接着发生，“刚刚……立刻……”。","furi":""},{"t":"label","label":"例句","text":"娘は家へ帰るや否やおなかが減ったと言って、冷蔵庫をのぞき込んだ。（女儿一回家就说肚子饿了，打开冰箱看了一下。）","furi":"<ruby>娘<rp>(</rp><rt>むすめ</rt><rp>)</rp></ruby>は<ruby>家<rp>(</rp><rt>いえ</rt><rp>)</rp></ruby>へ<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>るや<ruby>否<rp>(</rp><rt>いな</rt><rp>)</rp></ruby>やおなかが<ruby>減<rp>(</rp><rt>へ</rt><rp>)</rp></ruby>ったと<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>って、<ruby>冷蔵庫<rp>(</rp><rt>れいぞうこ</rt><rp>)</rp></ruby>をのぞき<ruby>込<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>んだ。（女儿一回家就说肚子饿了，打开冰箱看了一下。）"}],"id":"N1-175"},{"title":"176. ～やしない／～はしない","blocks":[{"t":"label","label":"接续","text":"動ます形／名 + やしない／はしない","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + やしない／はしない"},{"t":"label","label":"说明","text":"“不是……、不会……”，用于强调否定，多用于口语。","furi":""},{"t":"label","label":"例句","text":"彼女は芯の強い人で、試合に負けても皆の前で涙を見せやしなかった。（她是一个很坚强的人，即使比赛输了也没有在大家面前流过泪。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>は<ruby>芯<rp>(</rp><rt>しん</rt><rp>)</rp></ruby>の<ruby>強<rp>(</rp><rt>つよ</rt><rp>)</rp></ruby>い<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>で、<ruby>試合<rp>(</rp><rt>しあい</rt><rp>)</rp></ruby>に<ruby>負<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>けても<ruby>皆<rp>(</rp><rt>みな</rt><rp>)</rp></ruby>の<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>で<ruby>涙<rp>(</rp><rt>なみだ</rt><rp>)</rp></ruby>を<ruby>見<rp>(</rp><rt>み</rt><rp>)</rp></ruby>せやしなかった。（她是一个很坚强的人，即使比赛输了也没有在大家面前流过泪。）"}],"id":"N1-176"},{"title":"177. ～矢先に","blocks":[{"t":"label","label":"接续","text":"動辞書形/た形 + 矢先に","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby><ruby>辞書<rp>(</rp><rt>じしょ</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>/た<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + <ruby>矢先<rp>(</rp><rt>やさき</rt><rp>)</rp></ruby>に"},{"t":"label","label":"说明","text":"“正要……的时候、正当……的时候”，后项多为意外情况。","furi":""},{"t":"label","label":"例句","text":"机を片付けて帰ろうとした矢先に、課長に会議室へ呼ばれた。（正收拾好桌子准备回去的时候，被课长叫到会议室去了。）","furi":"<ruby>机<rp>(</rp><rt>つくえ</rt><rp>)</rp></ruby>を<ruby>片付<rp>(</rp><rt>かたづ</rt><rp>)</rp></ruby>けて<ruby>帰<rp>(</rp><rt>かえ</rt><rp>)</rp></ruby>ろうとした<ruby>矢先<rp>(</rp><rt>やさき</rt><rp>)</rp></ruby>に、<ruby>課長<rp>(</rp><rt>かちょう</rt><rp>)</rp></ruby>に<ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby><ruby>室<rp>(</rp><rt>しつ</rt><rp>)</rp></ruby>へ<ruby>呼<rp>(</rp><rt>よ</rt><rp>)</rp></ruby>ばれた。（正收拾好桌子准备回去的时候，被课长叫到会议室去了。）"}],"id":"N1-177"},{"title":"178. やれ～やれ～","blocks":[{"t":"label","label":"接续","text":"やれ + 名 + やれ + 名","furi":"やれ + <ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + やれ + <ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby>"},{"t":"label","label":"说明","text":"表示列举，“什么……啦，什么……啦”，多表示消极。","furi":""},{"t":"label","label":"例句","text":"今月はやれ子どもの日だやれ娘の誕生日だと、お祝いが重なる。（这个月又是儿童节又是女儿的生日，都是要庆祝的日子。）","furi":"<ruby>今月<rp>(</rp><rt>こんげつ</rt><rp>)</rp></ruby>はやれ<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どもの<ruby>日<rp>(</rp><rt>ひ</rt><rp>)</rp></ruby>だやれ<ruby>娘<rp>(</rp><rt>むすめ</rt><rp>)</rp></ruby>の<ruby>誕生<rp>(</rp><rt>たんじょう</rt><rp>)</rp></ruby><ruby>日<rp>(</rp><rt>び</rt><rp>)</rp></ruby>だと、お<ruby>祝<rp>(</rp><rt>いわ</rt><rp>)</rp></ruby>いが<ruby>重<rp>(</rp><rt>かさ</rt><rp>)</rp></ruby>なる。（这个月又是儿童节又是女儿的生日，都是要庆祝的日子。）"}],"id":"N1-178"},{"title":"179. ～（が）ゆえ（に）／ゆえの","blocks":[{"t":"label","label":"接续","text":"動／イ形の名詞修飾形 + がゆえ（に）／ナ形語幹／名 +（である）ゆえ（に）／ゆえの","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>／イ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby>の<ruby>名詞<rp>(</rp><rt>めいし</rt><rp>)</rp></ruby><ruby>修飾<rp>(</rp><rt>しゅうしょく</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + がゆえ（に）／ナ<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby><ruby>語幹<rp>(</rp><rt>ごかん</rt><rp>)</rp></ruby>／<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> +（である）ゆえ（に）／ゆえの"},{"t":"label","label":"说明","text":"表示原因、理由，“由于……、因为……”。文言体。","furi":""},{"t":"label","label":"例句","text":"部下を評価する立場になると、優しすぎるがゆえに、思い悩む人も少なくない。（要对下属进行评估的时候，有很多人因为自己的标准太宽松了而感到烦恼。）","furi":"<ruby>部下<rp>(</rp><rt>ぶか</rt><rp>)</rp></ruby>を<ruby>評価<rp>(</rp><rt>ひょうか</rt><rp>)</rp></ruby>する<ruby>立場<rp>(</rp><rt>たちば</rt><rp>)</rp></ruby>になると、<ruby>優<rp>(</rp><rt>やさ</rt><rp>)</rp></ruby>しすぎるがゆえに、<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>い<ruby>悩<rp>(</rp><rt>なや</rt><rp>)</rp></ruby>む<ruby>人<rp>(</rp><rt>ひと</rt><rp>)</rp></ruby>も<ruby>少<rp>(</rp><rt>すく</rt><rp>)</rp></ruby>なくない。（要对下属进行评估的时候，有很多人因为自己的标准太宽松了而感到烦恼。）"}],"id":"N1-179"},{"title":"180. ～ようによっては","blocks":[{"t":"label","label":"接续","text":"動ます形 + ようによっては","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ます<ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + ようによっては"},{"t":"label","label":"说明","text":"表示前后关联，前项的方式方法不同后项结果不同，“要看怎么……、取决于……（的方法）”。","furi":""},{"t":"label","label":"例句","text":"この古新聞も、使いようによっては、何かの役に立つではないかと思いますが。（我觉得旧报纸也能发挥作用，这取决于使用的方法。）","furi":"この<ruby>古<rp>(</rp><rt>こ</rt><rp>)</rp></ruby><ruby>新聞<rp>(</rp><rt>しんぶん</rt><rp>)</rp></ruby>も、<ruby>使<rp>(</rp><rt>つか</rt><rp>)</rp></ruby>いようによっては、<ruby>何<rp>(</rp><rt>なに</rt><rp>)</rp></ruby>かの<ruby>役<rp>(</rp><rt>やく</rt><rp>)</rp></ruby>に<ruby>立<rp>(</rp><rt>た</rt><rp>)</rp></ruby>つではないかと<ruby>思<rp>(</rp><rt>おも</rt><rp>)</rp></ruby>いますが。（我觉得旧报纸也能发挥作用，这取决于使用的方法。）"}],"id":"N1-180"},{"title":"181. ～をおいて","blocks":[{"t":"label","label":"接续","text":"名 + をおいて","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + をおいて"},{"t":"label","label":"说明","text":"表示限定，“除了……之外，（没有）……”。","furi":""},{"t":"label","label":"例句","text":"彼をおいて、この仕事を任せられる人間はいないだろう。（除了他之外没有人能够做这份工作。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>をおいて、この<ruby>仕事<rp>(</rp><rt>しごと</rt><rp>)</rp></ruby>を<ruby>任<rp>(</rp><rt>まか</rt><rp>)</rp></ruby>せられる<ruby>人間<rp>(</rp><rt>にんげん</rt><rp>)</rp></ruby>はいないだろう。（除了他之外没有人能够做这份工作。）"}],"id":"N1-181"},{"title":"182. ～を押して／を押し切って","blocks":[{"t":"label","label":"接续","text":"名 + を押して／を押し切って","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>押<rp>(</rp><rt>お</rt><rp>)</rp></ruby>して／を<ruby>押<rp>(</rp><rt>お</rt><rp>)</rp></ruby>し<ruby>切<rp>(</rp><rt>き</rt><rp>)</rp></ruby>って"},{"t":"label","label":"说明","text":"表示克服困难或不顾反对坚持做某事，“不顾……的反对、冒着……”。","furi":""},{"t":"label","label":"例句","text":"病気を押し切って、会議に出席した。（抱病出席了会议。）","furi":"<ruby>病気<rp>(</rp><rt>びょうき</rt><rp>)</rp></ruby>を<ruby>押<rp>(</rp><rt>お</rt><rp>)</rp></ruby>し<ruby>切<rp>(</rp><rt>き</rt><rp>)</rp></ruby>って、<ruby>会議<rp>(</rp><rt>かいぎ</rt><rp>)</rp></ruby>に<ruby>出席<rp>(</rp><rt>しゅっせき</rt><rp>)</rp></ruby>した。（抱病出席了会议。）"}],"id":"N1-182"},{"title":"183. ～を限りに","blocks":[{"t":"sub","text":"(1) 接续","furi":""},{"t":"line","text":"名 + を限りに","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りに"},{"t":"label","label":"说明","text":"表示时间的结束，“以……为截止日期、到……为止”。","furi":""},{"t":"label","label":"例句","text":"今日を限りにタバコをやめることにした。（从今天开始戒烟。）","furi":"<ruby>今日<rp>(</rp><rt>きょう</rt><rp>)</rp></ruby>を<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りにタバコをやめることにした。（从今天开始戒烟。）"},{"t":"sub","text":"(2) 接续","furi":""},{"t":"line","text":"名 + を限りに","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りに"},{"t":"label","label":"说明","text":"表示尽最大的可能，“以……为最大限度、尽最大的……”。","furi":""},{"t":"label","label":"例句","text":"力を限りに、ゴールに向かって走っていました。（尽全力跑向终点。）","furi":"<ruby>力<rp>(</rp><rt>ちから</rt><rp>)</rp></ruby>を<ruby>限<rp>(</rp><rt>かぎ</rt><rp>)</rp></ruby>りに、ゴールに<ruby>向<rp>(</rp><rt>む</rt><rp>)</rp></ruby>かって<ruby>走<rp>(</rp><rt>はし</rt><rp>)</rp></ruby>っていました。（尽全力跑向终点。）"}],"id":"N1-183"},{"title":"184. ～を皮切りに（して）","blocks":[{"t":"label","label":"接续","text":"名 + を皮切りに（して）","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>皮切<rp>(</rp><rt>かわき</rt><rp>)</rp></ruby>りに（して）"},{"t":"label","label":"说明","text":"“以……为开端”，表示以某项活动为开端相继发生类似事情。","furi":""},{"t":"label","label":"例句","text":"当劇団は評判がよく、明日の公演を皮切りに、今年は10都市を回る予定である。（这个剧团的评价不错，以明天的公演为开端，今年之内准备在十个城市公演。）","furi":"<ruby>当<rp>(</rp><rt>とう</rt><rp>)</rp></ruby><ruby>劇団<rp>(</rp><rt>げきだん</rt><rp>)</rp></ruby>は<ruby>評判<rp>(</rp><rt>ひょうばん</rt><rp>)</rp></ruby>がよく、<ruby>明日<rp>(</rp><rt>あした</rt><rp>)</rp></ruby>の<ruby>公演<rp>(</rp><rt>こうえん</rt><rp>)</rp></ruby>を<ruby>皮切<rp>(</rp><rt>かわき</rt><rp>)</rp></ruby>りに、<ruby>今年<rp>(</rp><rt>ことし</rt><rp>)</rp></ruby>は10<ruby>都市<rp>(</rp><rt>とし</rt><rp>)</rp></ruby>を<ruby>回<rp>(</rp><rt>まわ</rt><rp>)</rp></ruby>る<ruby>予定<rp>(</rp><rt>よてい</rt><rp>)</rp></ruby>である。（这个剧团的评价不错，以明天的公演为开端，今年之内准备在十个城市公演。）"}],"id":"N1-184"},{"title":"185. ～を機に","blocks":[{"t":"label","label":"接续","text":"名 + を機に","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>機<rp>(</rp><rt>き</rt><rp>)</rp></ruby>に"},{"t":"label","label":"说明","text":"“以……为契机、借……的机会”。","furi":""},{"t":"label","label":"例句","text":"入院したのを機に、お酒をやめた。（以住院为契机戒了酒。）","furi":"<ruby>入院<rp>(</rp><rt>にゅういん</rt><rp>)</rp></ruby>したのを<ruby>機<rp>(</rp><rt>き</rt><rp>)</rp></ruby>に、お<ruby>酒<rp>(</rp><rt>さけ</rt><rp>)</rp></ruby>をやめた。（以住院为契机戒了酒。）"}],"id":"N1-185"},{"title":"186. ～を禁じ得ない","blocks":[{"t":"label","label":"接续","text":"名 + を禁じ得ない","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>禁<rp>(</rp><rt>きん</rt><rp>)</rp></ruby>じ<ruby>得<rp>(</rp><rt>え</rt><rp>)</rp></ruby>ない"},{"t":"label","label":"说明","text":"强调一种感情，“不禁……、忍不住……”。","furi":""},{"t":"label","label":"例句","text":"あんまりにも悲しい場面に涙を禁じえなかった。（这个画面太悲伤，让人忍不住流泪。）","furi":"あんまりにも<ruby>悲<rp>(</rp><rt>かな</rt><rp>)</rp></ruby>しい<ruby>場面<rp>(</rp><rt>ばめん</rt><rp>)</rp></ruby>に<ruby>涙<rp>(</rp><rt>なみだ</rt><rp>)</rp></ruby>を<ruby>禁<rp>(</rp><rt>きん</rt><rp>)</rp></ruby>じえなかった。（这个画面太悲伤，让人忍不住流泪。）"}],"id":"N1-186"},{"title":"187. ～を蔑ろにする","blocks":[{"t":"label","label":"接续","text":"名 + を蔑ろにする","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>蔑<rp>(</rp><rt>ないがし</rt><rp>)</rp></ruby>ろにする"},{"t":"label","label":"说明","text":"“轻视……、把……不当一回事”。","furi":""},{"t":"label","label":"例句","text":"社員の福祉をないがしろにして、目の前の利益だけを求めてはいけない。（忽视员工的福利而只追求眼前的利益，这是不行的。）","furi":"<ruby>社員<rp>(</rp><rt>しゃいん</rt><rp>)</rp></ruby>の<ruby>福祉<rp>(</rp><rt>ふくし</rt><rp>)</rp></ruby>をないがしろにして、<ruby>目<rp>(</rp><rt>め</rt><rp>)</rp></ruby>の<ruby>前<rp>(</rp><rt>まえ</rt><rp>)</rp></ruby>の<ruby>利益<rp>(</rp><rt>りえき</rt><rp>)</rp></ruby>だけを<ruby>求<rp>(</rp><rt>もと</rt><rp>)</rp></ruby>めてはいけない。（忽视员工的福利而只追求眼前的利益，这是不行的。）"}],"id":"N1-187"},{"title":"188. ～をなおざりにして","blocks":[{"t":"label","label":"接续","text":"名 + をなおざりにして","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + をなおざりにして"},{"t":"label","label":"说明","text":"“轻视……、忽视……”，表示随便应付。","furi":""},{"t":"label","label":"例句","text":"子どものしつけをなおざりにしていては、将来は大変なことになるよ。（如果忽视了孩子的教育，今后会有很严重的问题。）","furi":"<ruby>子<rp>(</rp><rt>こ</rt><rp>)</rp></ruby>どものしつけをなおざりにしていては、<ruby>将来<rp>(</rp><rt>しょうらい</rt><rp>)</rp></ruby>は<ruby>大変<rp>(</rp><rt>たいへん</rt><rp>)</rp></ruby>なことになるよ。（如果忽视了孩子的教育，今后会有很严重的问题。）"}],"id":"N1-188"},{"title":"189. ～を控え／を控えて／を控えた","blocks":[{"t":"label","label":"接续","text":"名 + を控え／を控えて／を控えた","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>控<rp>(</rp><rt>ひか</rt><rp>)</rp></ruby>え／を<ruby>控<rp>(</rp><rt>ひか</rt><rp>)</rp></ruby>えて／を<ruby>控<rp>(</rp><rt>ひか</rt><rp>)</rp></ruby>えた"},{"t":"label","label":"说明","text":"“面临……、……即将来临之际”。","furi":""},{"t":"label","label":"例句","text":"結婚式を一か月後に控え、いろいろな準備で忙しい。（一个月后就要结婚了，现在有很多事情要准备，很忙。）","furi":"<ruby>結婚式<rp>(</rp><rt>けっこんしき</rt><rp>)</rp></ruby>を<ruby>一<rp>(</rp><rt>いち</rt><rp>)</rp></ruby>か<ruby>月<rp>(</rp><rt>げつ</rt><rp>)</rp></ruby><ruby>後<rp>(</rp><rt>ご</rt><rp>)</rp></ruby>に<ruby>控<rp>(</rp><rt>ひか</rt><rp>)</rp></ruby>え、いろいろな<ruby>準備<rp>(</rp><rt>じゅんび</rt><rp>)</rp></ruby>で<ruby>忙<rp>(</rp><rt>いそが</rt><rp>)</rp></ruby>しい。（一个月后就要结婚了，现在有很多事情要准备，很忙。）"}],"id":"N1-189"},{"title":"190. ～を踏まえ／を踏まえて","blocks":[{"t":"label","label":"接续","text":"名 + を踏まえ／を踏まえて","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>踏<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>まえ／を<ruby>踏<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>まえて"},{"t":"label","label":"说明","text":"“依据……、根据……、立足于……、考虑到……”。","furi":""},{"t":"label","label":"例句","text":"各家庭の実情を踏まえて、補助金を配るべきだ。（应该根据每个家庭的实际情况发放补助金。）","furi":"<ruby>各<rp>(</rp><rt>かく</rt><rp>)</rp></ruby><ruby>家庭<rp>(</rp><rt>かてい</rt><rp>)</rp></ruby>の<ruby>実情<rp>(</rp><rt>じつじょう</rt><rp>)</rp></ruby>を<ruby>踏<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>まえて、<ruby>補助<rp>(</rp><rt>ほじょ</rt><rp>)</rp></ruby><ruby>金<rp>(</rp><rt>きん</rt><rp>)</rp></ruby>を<ruby>配<rp>(</rp><rt>くば</rt><rp>)</rp></ruby>るべきだ。（应该根据每个家庭的实际情况发放补助金。）"}],"id":"N1-190"},{"title":"191. ～を振り出しに","blocks":[{"t":"label","label":"接续","text":"名 + を振り出しに","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>振<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>り<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>しに"},{"t":"label","label":"说明","text":"“以……为开端、以……为起点”。","furi":""},{"t":"label","label":"例句","text":"彼は小学校の教師を振り出しに社会に出た。（他以小学老师为起点走上了社会。）","furi":"<ruby>彼<rp>(</rp><rt>かれ</rt><rp>)</rp></ruby>は<ruby>小学校<rp>(</rp><rt>しょうがっこう</rt><rp>)</rp></ruby>の<ruby>教師<rp>(</rp><rt>きょうし</rt><rp>)</rp></ruby>を<ruby>振<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>り<ruby>出<rp>(</rp><rt>だ</rt><rp>)</rp></ruby>しに<ruby>社会<rp>(</rp><rt>しゃかい</rt><rp>)</rp></ruby>に<ruby>出<rp>(</rp><rt>で</rt><rp>)</rp></ruby>た。（他以小学老师为起点走上了社会。）"}],"id":"N1-191"},{"title":"192. ～を経て","blocks":[{"t":"label","label":"接续","text":"名 + を経て","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>経<rp>(</rp><rt>へ</rt><rp>)</rp></ruby>て"},{"t":"label","label":"说明","text":"“经过……、通过……”。","furi":""},{"t":"label","label":"例句","text":"正式の手続きを経て、この大学に入った。（办理了正式的手续之后进入了这所大学。）","furi":"<ruby>正式<rp>(</rp><rt>せいしき</rt><rp>)</rp></ruby>の<ruby>手続<rp>(</rp><rt>てつづ</rt><rp>)</rp></ruby>きを<ruby>経<rp>(</rp><rt>へ</rt><rp>)</rp></ruby>て、この<ruby>大学<rp>(</rp><rt>だいがく</rt><rp>)</rp></ruby>に<ruby>入<rp>(</rp><rt>はい</rt><rp>)</rp></ruby>った。（办理了正式的手续之后进入了这所大学。）"}],"id":"N1-192"},{"title":"193. ～をもって／をもちまして","blocks":[{"t":"sub","text":"(1) 接续","furi":""},{"t":"line","text":"名 + をもって／をもちまして","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + をもって／をもちまして"},{"t":"label","label":"说明","text":"表示时间的开始或结束，“以……（为起始点）、于……开始、于……结束”。","furi":""},{"t":"label","label":"例句","text":"7時をもちまして、本日の営業を終了いたします。（我们店的营业将在7点结束。）","furi":"7<ruby>時<rp>(</rp><rt>じ</rt><rp>)</rp></ruby>をもちまして、<ruby>本日<rp>(</rp><rt>ほんじつ</rt><rp>)</rp></ruby>の<ruby>営業<rp>(</rp><rt>えいぎょう</rt><rp>)</rp></ruby>を<ruby>終了<rp>(</rp><rt>しゅうりょう</rt><rp>)</rp></ruby>いたします。（我们店的营业将在7点结束。）"},{"t":"sub","text":"(2) 接续","furi":""},{"t":"line","text":"名 + をもって","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + をもって"},{"t":"label","label":"说明","text":"表示手段、方式、状态等，“以……、凭借……、带着……”。","furi":""},{"t":"label","label":"例句","text":"自信をもって、頑張っていきましょう。（满怀信心地去努力吧。）","furi":"<ruby>自信<rp>(</rp><rt>じしん</rt><rp>)</rp></ruby>をもって、<ruby>頑張<rp>(</rp><rt>がんば</rt><rp>)</rp></ruby>っていきましょう。（满怀信心地去努力吧。）"}],"id":"N1-193"},{"title":"194. ～をものともせずに","blocks":[{"t":"label","label":"接续","text":"名 + をものともせずに","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + をものともせずに"},{"t":"label","label":"说明","text":"表示克服困难坚持做某事，“克服困难……、不顾……”。","furi":""},{"t":"label","label":"例句","text":"彼女は周りの反対をものともせずに、自分の信じる道を歩み続けてきた。（尽管周围的人都反对，但她还是坚持走自己认为正确的路。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>は<ruby>周<rp>(</rp><rt>まわ</rt><rp>)</rp></ruby>りの<ruby>反対<rp>(</rp><rt>はんたい</rt><rp>)</rp></ruby>をものともせずに、<ruby>自分<rp>(</rp><rt>じぶん</rt><rp>)</rp></ruby>の<ruby>信<rp>(</rp><rt>しん</rt><rp>)</rp></ruby>じる<ruby>道<rp>(</rp><rt>みち</rt><rp>)</rp></ruby>を<ruby>歩<rp>(</rp><rt>あゆ</rt><rp>)</rp></ruby>み<ruby>続<rp>(</rp><rt>つづ</rt><rp>)</rp></ruby>けてきた。（尽管周围的人都反对，但她还是坚持走自己认为正确的路。）"}],"id":"N1-194"},{"title":"195. ～を余儀なくさせる","blocks":[{"t":"label","label":"接续","text":"名 + を余儀なくさせる","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>余儀<rp>(</rp><rt>よぎ</rt><rp>)</rp></ruby>なくさせる"},{"t":"label","label":"说明","text":"表示使役，前项事态迫使后项不得不改变，“迫使……、迫使……不得不……”。","furi":""},{"t":"label","label":"例句","text":"台風の上陸が、出発予定のフライトの延期を余儀なくさせた。（台风的登陆，使得本来要出发的航班被迫延期。）","furi":"<ruby>台風<rp>(</rp><rt>たいふう</rt><rp>)</rp></ruby>の<ruby>上陸<rp>(</rp><rt>じょうりく</rt><rp>)</rp></ruby>が、<ruby>出発<rp>(</rp><rt>しゅっぱつ</rt><rp>)</rp></ruby><ruby>予定<rp>(</rp><rt>よてい</rt><rp>)</rp></ruby>のフライトの<ruby>延期<rp>(</rp><rt>えんき</rt><rp>)</rp></ruby>を<ruby>余儀<rp>(</rp><rt>よぎ</rt><rp>)</rp></ruby>なくさせた。（台风的登陆，使得本来要出发的航班被迫延期。）"}],"id":"N1-195"},{"title":"196. ～を余儀なくされる","blocks":[{"t":"label","label":"接续","text":"名 + を余儀なくされる","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + を<ruby>余儀<rp>(</rp><rt>よぎ</rt><rp>)</rp></ruby>なくされる"},{"t":"label","label":"说明","text":"表示被动，某人因突发状况被迫改变，“被迫……”。","furi":""},{"t":"label","label":"例句","text":"不正な取引が明らかになり、その取引に関わった会社役員は辞職を余儀なくされた。（非法交易的情况被证实属实，牵涉其中的董事被迫辞职。）","furi":"<ruby>不正<rp>(</rp><rt>ふせい</rt><rp>)</rp></ruby>な<ruby>取引<rp>(</rp><rt>とりひき</rt><rp>)</rp></ruby>が<ruby>明<rp>(</rp><rt>あき</rt><rp>)</rp></ruby>らかになり、その<ruby>取引<rp>(</rp><rt>とりひき</rt><rp>)</rp></ruby>に<ruby>関<rp>(</rp><rt>かか</rt><rp>)</rp></ruby>わった<ruby>会社<rp>(</rp><rt>かいしゃ</rt><rp>)</rp></ruby><ruby>役員<rp>(</rp><rt>やくいん</rt><rp>)</rp></ruby>は<ruby>辞職<rp>(</rp><rt>じしょく</rt><rp>)</rp></ruby>を<ruby>余儀<rp>(</rp><rt>よぎ</rt><rp>)</rp></ruby>なくされた。（非法交易的情况被证实属实，牵涉其中的董事被迫辞职。）"}],"id":"N1-196"},{"title":"197. ～をよそに","blocks":[{"t":"label","label":"接续","text":"名 + をよそに","furi":"<ruby>名<rp>(</rp><rt>な</rt><rp>)</rp></ruby> + をよそに"},{"t":"label","label":"说明","text":"“不顾……、不管……”。","furi":""},{"t":"label","label":"例句","text":"住民の反対運動が盛り上がるのをよそに、高層ホテルの建設工事はどんどん進められている。（声势浩大的居民反对运动被完全忽视，高层宾馆的施工仍在继续。）","furi":"<ruby>住民<rp>(</rp><rt>じゅうみん</rt><rp>)</rp></ruby>の<ruby>反対<rp>(</rp><rt>はんたい</rt><rp>)</rp></ruby><ruby>運動<rp>(</rp><rt>うんどう</rt><rp>)</rp></ruby>が<ruby>盛<rp>(</rp><rt>も</rt><rp>)</rp></ruby>り<ruby>上<rp>(</rp><rt>あ</rt><rp>)</rp></ruby>がるのをよそに、<ruby>高層<rp>(</rp><rt>こうそう</rt><rp>)</rp></ruby>ホテルの<ruby>建設<rp>(</rp><rt>けんせつ</rt><rp>)</rp></ruby><ruby>工事<rp>(</rp><rt>こうじ</rt><rp>)</rp></ruby>はどんどん<ruby>進<rp>(</rp><rt>すす</rt><rp>)</rp></ruby>められている。（声势浩大的居民反对运动被完全忽视，高层宾馆的施工仍在继续。）"}],"id":"N1-197"},{"title":"198. ～んがため（に）／んがための","blocks":[{"t":"label","label":"接续","text":"動ない形 + んがため（に）／んがための（する→せんがため）","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + んがため（に）／んがための（する→せんがため）"},{"t":"label","label":"说明","text":"表示积极的目的，“为了……”。书面语。","furi":""},{"t":"label","label":"例句","text":"夢をかなえんがため、日々努力している。（为了实现梦想，每天都在努力。）","furi":"<ruby>夢<rp>(</rp><rt>ゆめ</rt><rp>)</rp></ruby>をかなえんがため、<ruby>日々<rp>(</rp><rt>ひび</rt><rp>)</rp></ruby><ruby>努力<rp>(</rp><rt>どりょく</rt><rp>)</rp></ruby>している。（为了实现梦想，每天都在努力。）"}],"id":"N1-198"},{"title":"199. ～んじゃなかった","blocks":[{"t":"label","label":"接续","text":"文の普通形 + んじゃなかった","furi":"<ruby>文<rp>(</rp><rt>ぶん</rt><rp>)</rp></ruby>の<ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + んじゃなかった"},{"t":"label","label":"说明","text":"表示对已经发生的事情后悔，“不该……的、早知道就不……了”。口语。","furi":""},{"t":"label","label":"例句","text":"ああ、100万円も負けた。彼女の儲け話なんて聞くんじゃなかった。（唉，输了100万日币。真不该听她说的什么赚钱之类的话的。）","furi":"ああ、100<ruby>万<rp>(</rp><rt>まん</rt><rp>)</rp></ruby><ruby>円<rp>(</rp><rt>えん</rt><rp>)</rp></ruby>も<ruby>負<rp>(</rp><rt>ま</rt><rp>)</rp></ruby>けた。<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>の<ruby>儲<rp>(</rp><rt>もう</rt><rp>)</rp></ruby>け<ruby>話<rp>(</rp><rt>ばなし</rt><rp>)</rp></ruby>なんて<ruby>聞<rp>(</rp><rt>き</rt><rp>)</rp></ruby>くんじゃなかった。（唉，输了100万日币。真不该听她说的什么赚钱之类的话的。）"}],"id":"N1-199"},{"title":"200. ～んだって／んですって","blocks":[{"t":"label","label":"接续","text":"文の普通形 + んだって／んですって","furi":"<ruby>文<rp>(</rp><rt>ぶん</rt><rp>)</rp></ruby>の<ruby>普通<rp>(</rp><rt>ふつう</rt><rp>)</rp></ruby><ruby>形<rp>(</rp><rt>がた</rt><rp>)</rp></ruby> + んだって／んですって"},{"t":"label","label":"说明","text":"表示传闻，“据说……”。","furi":""},{"t":"label","label":"例句","text":"太田さんは来月から北海道に転勤するんだって。（听说太田下个月要调到北海道去了。）","furi":"<ruby>太田<rp>(</rp><rt>おおた</rt><rp>)</rp></ruby>さんは<ruby>来月<rp>(</rp><rt>らいげつ</rt><rp>)</rp></ruby>から<ruby>北海道<rp>(</rp><rt>ほっかいどう</rt><rp>)</rp></ruby>に<ruby>転勤<rp>(</rp><rt>てんきん</rt><rp>)</rp></ruby>するんだって。（听说太田下个月要调到北海道去了。）"}],"id":"N1-200"},{"title":"201. ～んばかりに／んばかりの／んばかりだ","blocks":[{"t":"label","label":"接续","text":"動ない形 + んばかりに／んばかりの／んばかりだ（する→せんばかり）","furi":"<ruby>動<rp>(</rp><rt>どう</rt><rp>)</rp></ruby>ない<ruby>形<rp>(</rp><rt>かたち</rt><rp>)</rp></ruby> + んばかりに／んばかりの／んばかりだ（する→せんばかり）"},{"t":"label","label":"说明","text":"表示样态，“几乎显出……的样子、几乎就要……”。","furi":""},{"t":"label","label":"例句","text":"彼女は泣かんばかりに、「元気でね」と言いながら手を振った。（她眼泪快要流下来的样子，挥了挥手说了声保重。）","furi":"<ruby>彼女<rp>(</rp><rt>かのじょ</rt><rp>)</rp></ruby>は<ruby>泣<rp>(</rp><rt>な</rt><rp>)</rp></ruby>かんばかりに、「<ruby>元気<rp>(</rp><rt>げんき</rt><rp>)</rp></ruby>でね」と<ruby>言<rp>(</rp><rt>い</rt><rp>)</rp></ruby>いながら<ruby>手<rp>(</rp><rt>て</rt><rp>)</rp></ruby>を<ruby>振<rp>(</rp><rt>ふ</rt><rp>)</rp></ruby>った。（她眼泪快要流下来的样子，挥了挥手说了声保重。）"}],"id":"N1-201"}]}]}]
